INSERT INTO `DialogueLine` (`dialogueID`, `npcID`, `narrativeID`, `sceneID`, `dialogueLine`, `sequenceOrder`) VALUES
(1, 1, 1, NULL, 'Tugasku sebagai Perdana Menteri ialah meyakinkan lima wilayah bersatu tanpa paksaan: mendengar Borneo, menandatangani perjanjian dan mengisytiharkan Malaysia. Jika aku gagal mendengar, tiada Malaysia, dan rakyat Borneo terus menunggu kemerdekaan, {nama}.', 1),
(2, 1, 1, NULL, 'Daripada perjalanan itu aku belajar bahawa perpaduan tidak dipaksa. Ia dibina dengan mendengar suara setiap pihak.', 2),
(3, 1, 1, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, Perdana Menteri Persekutuan Tanah Melayu. Setiap keputusan yang kau ambil akan menentukan nasib lima wilayah. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(4, 10, 1, 'e1_n1_s1', 'Tunku, dewan sudah penuh. Sekali kau sebut perkataan \'Malaysia\', semua mata akan memandang kau.', 1),
(5, 4, 1, 'e1_n1_s1', 'Aku sokong gagasan ini, Tunku. Tetapi wartawan akan bertanya mengapa. Mereka mahu alasan, bukan slogan.', 2),
(6, 10, 1, 'e1_n1_s1', 'Kita sudah bincangkan semalam: ada empat sebab. Kalau wartawan bertanya sekarang, Tunku, apa jawapan kau?', 3),
(7, 4, 1, 'e1_n1_s1', 'Dengan jawapan itu kau menjawab soalan wartawan dan soalan rakyat. Tarikhnya 27 Mei 1961. Ingat tarikh ini.', 4),
(8, NULL, 1, 'e1_n1_s1', 'Aku tahu. Selepas ini setiap negeri akan bertanya, \'Apa untung kami?\' Kita mesti bersedia.', 5),
(9, 10, 1, 'e1_n1_s1', 'Dan itu bermula di Borneo, Tunku. Kau perlu mendengar mereka, bukan hanya bercakap kepada mereka.', 6),
(10, 10, 1, 'e1_n1_s1', 'Idea ini bukan baharu, Tunku: Lord Brassey 1887, Ibrahim Yaakob 1938, Malcolm MacDonald 1951. Kau sendiri pernah menyebutnya pada 1955.', 7),
(11, 3, 1, 'e1_n1_s2', 'Tunku, JSKM ditubuhkan 23 Julai 1961. Setiap kampung bertanya sama ada Sabah dilayan sebagai rakan atau sekadar tambahan.', 1),
(12, 10, 1, 'e1_n1_s2', 'Suruhanjaya Cobbold bermula 17 Januari 1962. Kami turun ke kampung-kampung sendiri. Kalau rakyat rasa dipaksa, laporan ini tidak bernilai.', 2),
(13, 3, 1, 'e1_n1_s2', 'Seorang penduduk bertanya melalui aku, Tunku: \'Adakah kami dipaksa menyertai Malaysia?\' Apa jawapan kau?', 3),
(14, 10, 1, 'e1_n1_s2', 'Laporan siap 21 Jun 1962. Dua pertiga menyokong, tetapi sokongan itu ada syaratnya.', 4),
(15, NULL, 1, 'e1_n1_s2', 'Syarat itu akan datang ke meja kita. Kita mesti bersedia menjawabnya satu demi satu.', 5),
(16, 5, 1, 'e1_n1_s3', 'Tunku, JAK bersidang hari ini. Lord Lansdowne di sebelah sana, aku di sebelah sini. Setiap perenggan akan dibaca berkali-kali.', 1),
(17, 2, 1, 'e1_n1_s3', 'Tunku, adat kami bukan hiasan. Tulis ia dalam perlembagaan, bukan dalam janji lisan sahaja.', 2),
(18, 3, 1, 'e1_n1_s3', 'Tunku, ini tuntutan kami: Hak 20 Perkara untuk Sabah dan hak adat Sarawak. Bagaimana kau memastikan ia tidak dilupakan?', 3),
(19, 5, 1, 'e1_n1_s3', 'Kita tulis satu demi satu. Tetapi cepat, Tunku, masa tidak menunggu kita.', 4),
(20, NULL, 1, 'e1_n1_s3', 'Kita tidak akan tergesa-gesa dalam perkara yang menentukan hak orang lain. Mari mulakan perenggan pertama.', 5),
(21, 2, 1, 'e1_n1_s3', 'Sabah membawa 20 Perkara dan Sarawak 18 Perkara, Tunku. Lord Lansdowne dan Tun Razak mengerusikan JAK. Semuanya mesti ditulis.', 6),
(22, 7, 1, 'e1_n1_s4', 'Tunku, kami tidak mahu Sarawak diserap tanpa suara sendiri. Merdeka dahulu, baru kita bincang gabungan. Itu pendirian SUPP.', 1),
(23, 5, 1, 'e1_n1_s4', 'Indonesia sudah mengisytiharkan Konfrontasi pada 20 Januari 1963: \'Ganyang Malaysia\'. Ini bukan lagi perbincangan dalam bilik, Tunku.', 2),
(24, 10, 1, 'e1_n1_s4', 'Filipina pula menuntut Sabah. Tunku, kita boleh minta PBB bertanya kepada rakyat Borneo sendiri, supaya bukan kita yang menjawab bagi pihak mereka. Apa pendapat kau?', 3),
(25, 5, 1, 'e1_n1_s4', 'Kita tidak boleh menjawab ketiga-tiganya sekali gus. Pilih dahulu yang paling mendesak, kemudian rujuk PBB.', 4),
(26, NULL, 1, 'e1_n1_s4', 'Kumpulkan semua dokumen di atas meja. Aku mahu melihat buktinya sebelum membuat keputusan.', 5),
(27, 5, 1, 'e1_n1_s5', 'Tunku, Marlborough House, 9 Julai 1963. Pen sudah di tangan kau. Tetapi Indonesia dan Filipina belum puas hati, jadi tandatangan ini belum menutup cerita.', 1),
(28, 10, 1, 'e1_n1_s5', 'PBB menghantar misi UNMM pada 12 Ogos 1963. Laurence Michelmore akan bertanya kepada rakyat Borneo, bukan kepada kita.', 2),
(29, 3, 1, 'e1_n1_s5', 'Tunku, kalau Michelmore bertanya kepada kau, siapa yang patut menentukan sama ada Sabah dan Sarawak mahu menyertai Malaysia?', 3),
(30, 3, 1, 'e1_n1_s5', 'Rakyat kami akan menjawab dengan jujur, Tunku. Itu sebab aku tidak risau, cuma berdebar.', 4),
(31, NULL, 1, 'e1_n1_s5', 'Laporan itu akan tiba tidak lama lagi. Kita tunggu, dan kita terima apa sahaja jawapannya.', 5),
(32, 10, 1, 'e1_n1_s5', 'Tarikh asal 31 Ogos 1963 ditangguhkan ke 16 September, Tunku, supaya PBB sempat bertanya kepada rakyat Borneo dahulu.', 6),
(33, 5, 1, 'e1_n1_s6', 'Tunku, esok 16 September 1963. Kau sudah membaca teks ini puluhan kali.', 1),
(34, NULL, 1, 'e1_n1_s6', 'Tetapi bila berdiri nanti, aku mahu ia terasa seperti kali pertama.', 2),
(35, 10, 1, 'e1_n1_s6', 'Laporan UNMM tiba 14 September, dan ia menyokong kita. Selepas ini tiada lagi \'kalau\'. Hanya \'bila\'.', 3),
(36, 6, 1, 'e1_n1_s6', 'Tunku, Sarawak mahu dilihat sebagai rakan, bukan pengikut. Pemasyhuran dibaca serentak di Kuala Lumpur, Kuching, Kota Kinabalu dan Singapura. Mengapa ia mesti serentak?', 4),
(37, NULL, 1, 'e1_n1_s6', 'Kita bina ini bersama. Pastikan setiap suara didengar, kerana negara ini bermula daripada suara-suara itu.', 5),
(38, 5, 1, 'e1_n1_s6', 'Di Singapura, Pemasyhuran dibaca di City Hall, Tunku. Jalur Gemilang dikibarkan sebagai lambang negara baharu, di Stadium Merdeka tempat kau melaungkan Merdeka pada 31 Ogos 1957.', 6),
(39, 3, 2, NULL, 'Tugasku ialah membawa suara rakyat Borneo ke meja perundingan dan memastikan hak kami ditulis dalam Perlembagaan. Jika suara itu tidak sampai, Sabah dan Sarawak hanya menjadi tambahan, bukan rakan, {nama}.', 1),
(40, 3, 2, NULL, 'Aku belajar bahawa penyertaan yang adil hanya wujud apabila suara kecil diberi tempat di meja perundingan.', 2),
(41, 3, 2, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, Pengerusi JSKM dari Sabah. Rakyat Borneo menunggu jawapan kau: adakah mereka rakan, atau sekadar tambahan? Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(42, 9, 2, 'e1_n2_s1', 'Donald, dia sudah umumkan di Adelphi pada 27 Mei 1961. Sekarang bola ada pada kita. Terima atau tolak, kita mesti tahu apa yang kita mahu.', 1),
(43, 2, 2, 'e1_n2_s1', 'Aku sudah tua, Donald, dan aku dengar cerita ini sejak zaman Brassey lagi. Orang putih bercakap, tanah kami tidak ditanya.', 2),
(44, 2, 2, 'e1_n2_s1', 'Aku bimbang kami hanya diberitahu, bukan ditanya. Kalau kau di tempat kami, apa yang patut dibuat dahulu sebelum menjawab Tunku?', 3),
(45, NULL, 2, 'e1_n2_s1', 'Kali ini lain, Tun. Kemerdekaan lebih awal, perlindungan daripada komunis, ekonomi yang bergerak. Tetapi hanya jika kita bangun dan bersuara.', 4),
(46, 9, 2, 'e1_n2_s1', 'Maka bersuaralah dengan jelas, Donald. Seluruh Sabah memerhati.', 5),
(47, 9, 2, 'e1_n2_s1', 'Idea ini pun bukan baharu, Donald: Lord Brassey 1887, Ibrahim Yaakob 1938, Malcolm MacDonald 1951, dan Tunku sendiri pada 1955. Cuma kali ini ia diumumkan terang-terangan di Adelphi.', 6),
(48, 2, 2, 'e1_n2_s2', 'Donald, JSKM bermula 23 Julai 1961. Setiap kampung mahu tahu apa itu Malaysia, dan kau tidak boleh menjawab dengan \'tidak pasti\'.', 1),
(49, 9, 2, 'e1_n2_s2', 'Rakyat bertanya tentang agama dan tanah. Jangan jawab dengan janji kosong, Donald. Mereka ingat setiap perkataan.', 2),
(50, 2, 2, 'e1_n2_s2', 'Cobbold akan tiba pada 17 Januari 1962 untuk mendengar rakyat. Seorang penduduk bertanya kepada kau, \'Adakah suara kami benar-benar dicatat?\' Apa jawapan kau?', 3),
(51, 2, 2, 'e1_n2_s2', 'Laporan 21 Jun 1962 menunjukkan majoriti menyokong. Tetapi sokongan ini datang dengan harapan, dan harapan mesti ditunaikan.', 4),
(52, NULL, 2, 'e1_n2_s2', 'Aku faham, Tun. Aku akan bawa harapan itu ke meja JAK.', 5),
(53, 5, 2, 'e1_n2_s3', 'Donald, Hak 20 Perkara. Bawa senarai ini ke meja. Kalau mahu Borneo menjadi sebahagian Malaysia, inilah asasnya.', 1),
(54, 2, 2, 'e1_n2_s3', 'Sarawak juga ada tuntutan. Imigresen, adat, pentadbiran tempatan. Jangan biarkan kami hanya disebut dalam lampiran.', 2),
(55, 5, 2, 'e1_n2_s3', 'JAK bersidang hari ini dengan Lord Lansdowne. Apa yang dipersetujui di sini akan menjadi Perlembagaan. Kau wakil Borneo di meja ini, Donald: apa yang kau minta?', 3),
(56, NULL, 2, 'e1_n2_s3', '30 Ogos 1962. Ingat tarikh ini. Hari kita menulis hak kita sendiri.', 4),
(57, 5, 2, 'e1_n2_s3', 'Sarawak pula membawa 18 Perkara, Donald. Dua senarai, satu Perlembagaan.', 5),
(58, 6, 2, 'e1_n2_s4', 'Donald, SUPP bising di dewan. Mereka mahu Sarawak merdeka berasingan. Kita mesti jawab dengan hak yang sudah ditulis dalam Perlembagaan melalui JAK, bukan mengabaikannya.', 1),
(59, 9, 2, 'e1_n2_s4', 'Di luar, tentera Indonesia melintas sempadan. Konfrontasi bermula 20 Januari 1963. Ini bukan sekadar pertikaian politik.', 2),
(60, 9, 2, 'e1_n2_s4', 'Filipina pula menuntut Sabah. Mereka yang ragu bimbang suara kita hilang. Donald, bagaimana kau meyakinkan mereka?', 3),
(61, NULL, 2, 'e1_n2_s4', 'Kita tidak boleh biarkan sesiapa menentukan masa depan kita tanpa bertanya kita dahulu. Mari kumpulkan buktinya.', 4),
(62, 9, 2, 'e1_n2_s4', 'Slogan mereka ialah \'Ganyang Malaysia\', Donald. Kita mesti tahu mana ancaman sebenar dan mana yang boleh dijawab dengan hak yang tertulis.', 5),
(63, 6, 2, 'e1_n2_s5', 'Donald, Marlborough House, 9 Julai 1963. Kau menandatangani Perjanjian. Tanganku sedikit bergetar. Ini bukan dokumen biasa.', 1),
(64, 6, 2, 'e1_n2_s5', 'Indonesia dan Filipina masih membantah. Jadi PBB menghantar UNMM pada 12 Ogos 1963. Michelmore mahu mendengar sendiri daripada rakyat kita.', 2),
(65, 2, 2, 'e1_n2_s5', 'Biar mereka datang ke rumah panjang. Tetapi katakan, Donald: kalau pegawai PBB bertanya kepada kau, \'Adakah anda menyokong Malaysia?\', bagaimana kau menjawab?', 3),
(66, 6, 2, 'e1_n2_s5', 'Laporan UNMM 14 September 1963 menyokong kita. Tetapi semua orang di sini tahu, selepas ini barulah kerja sebenar bermula.', 4),
(67, 6, 2, 'e1_n2_s5', 'Tarikh asal 31 Ogos 1963 ditangguhkan ke 16 September, Donald, supaya PBB sempat bertanya kepada rakyat dahulu.', 5),
(68, 9, 2, 'e1_n2_s6', 'Donald, 16 September 1963. Kau akan membacanya di Kota Kinabalu. Aku tahu kau sudah membaca seratus kali, tetapi hari ini lain.', 1),
(69, NULL, 2, 'e1_n2_s6', 'Hari ini lain, Tun. Seluruh Sabah di hadapan aku.', 2),
(70, 9, 2, 'e1_n2_s6', 'Tenang. Seluruh Sabah di belakang kau. Baca perlahan, supaya setiap orang dengar.', 3),
(71, 6, 2, 'e1_n2_s6', 'Di Kuching, aku membacanya bersama Tun Jugah. Donald, kalau seseorang bertanya siapa yang membacakan Pemasyhuran di Sabah dan di Sarawak, apa kau jawab?', 4),
(72, 2, 2, 'e1_n2_s6', 'Hari ini bukan akhir perjuangan. Ia permulaan tanggungjawab kita bersama.', 5),
(73, 9, 2, 'e1_n2_s6', 'Di Kuala Lumpur, Tunku membaca Pemasyhuran di Stadium Merdeka, tempat Merdeka dilaungkan pada 31 Ogos 1957. Di Singapura, di City Hall. Jalur Gemilang dikibarkan sebagai lambang negara baharu.', 6),
(74, 10, 3, NULL, 'Tugasku ialah menjaga keselamatan dan diplomasi di belakang tabir: menghadapi Konfrontasi, tuntutan Filipina dan memastikan PBB mengesahkan pilihan rakyat. Jika satu kesilapan berlaku, seluruh rancangan runtuh, {nama}.', 1),
(75, 10, 3, NULL, 'Aku belajar bahawa keselamatan sebenar dibina dengan diplomasi, kejujuran dan pengesahan yang bebas.', 2),
(76, 10, 3, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, diplomat dan perunding keselamatan negara. Kau bekerja di belakang tabir, dan satu kesilapan boleh meruntuhkan segalanya. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(77, 1, 3, 'e1_n3_s1', 'Ghazali, aku sudah bercakap di Adelphi. Sekarang aku perlukan kau membaca keadaan rantau dengan jelas.', 1),
(78, 1, 3, 'e1_n3_s1', 'Singapura bergolak, Sarawak pun ada tanda-tandanya. Tetapi bukan komunis sahaja: ada keseimbangan kaum, kemerdekaan lebih awal untuk Borneo, dan ekonomi yang maju. Empat sebab, saling berkait.', 2),
(79, 4, 3, 'e1_n3_s1', 'Aku sokong penggabungan, Ghazali, tetapi keselamatan sahaja tidak cukup. Seorang pelajar bertanya kepada kau, \'Mengapa Malaysia dicadangkan?\' Apa jawapan kau?', 3),
(80, NULL, 3, 'e1_n3_s1', 'Setiap sebab menjawab satu kebimbangan rakyat. Catat tarikhnya: 27 Mei 1961.', 4),
(81, 4, 3, 'e1_n3_s1', 'Idea ini bukan baharu, Ghazali: Lord Brassey 1887, Ibrahim Yaakob 1938, Malcolm MacDonald 1951, Tunku 1955. Hotel Adelphi hanya menyatukannya.', 5),
(82, 1, 3, 'e1_n3_s2', 'Ghazali, JSKM bermula 23 Julai 1961 di bawah Donald Stephens untuk menerangkan Malaysia. Cobbold bermula 17 Januari 1962, dan kau bersama Wong Pow Nee dalam suruhanjaya itu.', 1),
(83, 5, 3, 'e1_n3_s2', 'Apa yang rakyat Borneo katakan kepada kau, Ghazali? Aku mahu dengar sebenar-benarnya, bukan versi yang menyenangkan.', 2),
(84, NULL, 3, 'e1_n3_s2', 'Laporan siap 21 Jun 1962: dua pertiga menyokong. Tetapi ada juga yang ragu, dan keraguan itu mesti dijawab, bukan disenyapkan.', 3),
(85, 5, 3, 'e1_n3_s2', 'Betul. Jadi, Ghazali, apa yang patut kita lakukan dengan keraguan mereka yang belum menyokong?', 4),
(86, 1, 3, 'e1_n3_s2', 'Selepas ini JAK akan menulis jawapannya, bukan sekadar janji.', 5),
(87, 5, 3, 'e1_n3_s3', 'Ghazali, JAK bersidang 30 Ogos 1962. Lord Lansdowne dan aku mengerusikannya. Setiap perenggan akan disemak berkali-kali.', 1),
(88, 3, 3, 'e1_n3_s3', 'Sabah menuntut Hak 20 Perkara, Ghazali, dan Sarawak membawa 18 Perkara. Kami mahu semuanya ditulis, bukan dijanjikan.', 2),
(89, 2, 3, 'e1_n3_s3', 'Adat kami bukan hiasan, Ghazali. Jika ia tidak tertulis, ia hilang bersama orang yang berjanji. Bagaimana kau memastikan ia dijaga?', 3),
(90, 5, 3, 'e1_n3_s3', 'Cepat, Ghazali, masa tidak menunggu kita. Tetapi perenggan demi perenggan, tanpa tergesa-gesa.', 4),
(91, NULL, 3, 'e1_n3_s3', 'Hak yang ditulis menjadi undang-undang. Kita tidak akan tergesa-gesa dalam perkara yang menentukan hak orang lain.', 5),
(92, 5, 3, 'e1_n3_s4', 'Ghazali, SUPP mahu merdeka berasingan. Indonesia mengisytiharkan Konfrontasi 20 Januari 1963. Filipina menuntut Sabah. Tiga ancaman, satu meja.', 1),
(93, 1, 3, 'e1_n3_s4', 'Mana satu yang paling mendesak, Ghazali? Aku perlu tahu sebelum membuat keputusan.', 2),
(94, 5, 3, 'e1_n3_s4', 'Konfrontasi ialah ancaman keselamatan: tentera melintas sempadan. SUPP dan Filipina boleh dijawab dengan perundingan dan diplomasi. Menurut kau, yang mana kita tangani dahulu?', 3),
(95, 1, 3, 'e1_n3_s4', 'Susun mengikut keutamaan. Aku tidak mahu satu masalah kecil menjadi sebab seluruh rancangan terhenti.', 4),
(96, 5, 3, 'e1_n3_s4', 'Slogan mereka \'Ganyang Malaysia\', Ghazali. Jangan silap menilai: ia ancaman sebenar.', 5),
(97, 1, 3, 'e1_n3_s5', 'Ghazali, Marlborough House, 9 Julai 1963. Perjanjian sudah ditandatangani. Tetapi aku masih gelisah, kerana bantahan tidak berhenti begitu sahaja.', 1),
(98, 5, 3, 'e1_n3_s5', 'UNMM bermula 12 Ogos 1963, diketuai Laurence Michelmore. Prinsip PBB jelas: laporan hanya dipercayai jika pegawainya bebas bertemu sesiapa tanpa kita campur tangan.', 2),
(99, 1, 3, 'e1_n3_s5', 'Kau penasihatku, Ghazali. Patutkah kita menemani pegawai UNMM ke mana-mana mereka pergi, atau biarkan mereka bertemu sesiapa sahaja sendiri?', 3),
(100, NULL, 3, 'e1_n3_s5', 'Biar mereka sendiri mendengar rakyat. Laporan 14 September akan lebih berharga jika kita tidak mencampurinya.', 4),
(101, 5, 3, 'e1_n3_s5', 'Tarikh asal 31 Ogos 1963 ditangguhkan ke 16 September, Ghazali, supaya PBB sempat bertanya dahulu.', 5),
(102, 1, 3, 'e1_n3_s6', 'Ghazali, 16 September 1963. Empat bandar serentak: Kuala Lumpur, Kuching, Kota Kinabalu, Singapura. Satu kesilapan masa, dan semua orang akan nampak.', 1),
(103, 5, 3, 'e1_n3_s6', 'Kawalan keselamatan sudah disusun. Tetapi hari ini bukan hari untuk menyangka semuanya selamat.', 2),
(104, 1, 3, 'e1_n3_s6', 'Aku bakal membaca Pemasyhuran. Kau menjaga keselamatan majlis. Apa tugas utama kau hari ini, Ghazali: menjadi pusat perhatian, atau memastikan majlis berjalan tanpa gangguan?', 3),
(105, NULL, 3, 'e1_n3_s6', 'Diplomasi, peninjauan dan keselamatan. Itulah tiga tiang, dan hari ini ketiga-tiganya berdiri.', 4),
(106, 5, 3, 'e1_n3_s6', 'Di Stadium Merdeka, tempat Merdeka dilaungkan pada 31 Ogos 1957, Tunku membaca Pemasyhuran. Di Singapura, di City Hall. Jalur Gemilang dikibarkan sebagai lambang negara baharu.', 5),
(107, 21, 201, NULL, 'Tahukah kau, {nama}? Setiap kali penglipur lara berhenti bercerita, satu nama negeri hilang daripada ingatan. Terima kasih kerana meminjamkan jiwa, kini nama dan warisan kita terus hidup!', 1),
(108, 21, 201, NULL, 'Nama sesebuah negeri ialah wasiat nenek moyang. Selagi kita bercerita tentangnya, jati diri kita tidak akan pudar.', 2),
(109, 21, 201, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penglipur lara tua yang menyimpan cerita asal usul nama negeri. Tikar mengkuang dibentang, cerita pun bermula! Dengarlah dengan telinganya dan bercakaplah dengan suaranya.', 3),
(110, NULL, 201, 'e2_n1_s1', 'Angin sawah menghembus padi yang menguning. Bendera Perlis berkibar di tiang kampung, jata negeri terpampang pada balai di tengah sawah, dan radio di atas meja mengalunkan lagu negeri.', 1),
(111, 28, 201, 'e2_n1_s1', 'Eh, Tok Penglipur Lara! Berhenti sekejap sebelum lumpur sawah melekat di kaki Tok! Kami sedang berbalah ni: apakah asal usul nama Perlis?', 2),
(112, NULL, 201, 'e2_n1_s1', 'Hah, rapatkan duduk dan dengar baik-baik: Daripada perkataan Siam \'phrau loi\' (kelapa hanyut), perkataan tempatan \'peroleh\' atau tokoh Tok Perlis.', 3),
(113, 28, 201, 'e2_n1_s1', 'Kelapa hanyut? Ha ha, patutlah! Selama ini saya angkat kelapa tepi parit tanpa tahu sejarahnya. Tok, siapa pula yang memayungi Perlis?', 4),
(114, NULL, 201, 'e2_n1_s1', 'Nah, ini yang ramai terlupa! Ketua negeri Perlis bergelar Raja.', 5),
(115, 28, 201, 'e2_n1_s1', 'Dan di manakah ibu negerinya, Tok? Saya mahu catat dalam buku!', 6),
(116, NULL, 201, 'e2_n1_s1', 'Catat laju-laju! Ibu negerinya Kangar, dan bandar dirajanya Arau.', 7),
(117, 28, 201, 'e2_n1_s1', 'Eh, dengar! Radio itu berbunyi, TING-TUNG! Lagu apakah itu, Tok?', 8),
(118, NULL, 201, 'e2_n1_s1', 'Dengar, itulah dia! Radio itu mengalunkan lagu negeri; tajuk lagunya belum dapat kita pastikan. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(119, 28, 201, 'e2_n1_s1', 'Wah, padi pun macam mengangguk dengar cerita Tok! Mari ke pondok, saya belanja teh panas.', 10),
(120, NULL, 201, 'e2_n1_s2', 'Hamparan sawah padi berkilau di bawah langit senja. Bendera Kedah berkibar di hujung tiang, jata negeri terpampang pada rumah besar, dan alat muzik di beranda mengalunkan lagu negeri.', 1),
(121, 28, 201, 'e2_n1_s2', 'Tok! Tok! Sini, sini! Cucu saya baru belajar nama negeri tapi saya sendiri tak pandai jawab. Apakah asal usul nama Kedah?', 2),
(122, NULL, 201, 'e2_n1_s2', 'Syyy! Ini bukan cerita calang-calang: Daripada \'Kheddah\' (perangkap gajah), \'Qadah\' dalam bahasa Arab (gelas berkaki) atau \'Kadaram\' dalam rujukan India.', 3),
(123, 28, 201, 'e2_n1_s2', 'Perangkap gajah! Patutlah ada yang kata nama ini bunyi garang. Hebat betul! Tok, siapa pula yang memayungi Kedah?', 4),
(124, NULL, 201, 'e2_n1_s2', 'Soalan yang bagus! Ketua negeri Kedah bergelar Sultan.', 5),
(125, 28, 201, 'e2_n1_s2', 'Ibu negerinya pula, Tok? Cepat, cepat, saya tak sabar!', 6),
(126, NULL, 201, 'e2_n1_s2', 'Pena sudah sedia? Ibu negerinya Alor Setar, dan bandar dirajanya Anak Bukit.', 7),
(127, 28, 201, 'e2_n1_s2', 'Shhh! Radio itu mengalunkan lagu, Tok. Lagu negeri apakah itu?', 8),
(128, NULL, 201, 'e2_n1_s2', 'Jangan berhenti menyanyi! Lagu negerinya ialah \'Allah Selamatkan Sultan Mahkota\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(129, 28, 201, 'e2_n1_s2', 'Cucu saya ternganga, Tok! Esok dia mesti cerita pada kawan-kawan. Terima kasih, Tok!', 10),
(130, NULL, 201, 'e2_n1_s3', 'Bau garam dan angin laut singgah di jeti yang sibuk. Bendera Pulau Pinang berkibar di jeti, jata negeri terpampang pada gerbang batu, dan gramofon di tepi laut mengalunkan lagu negeri.', 1),
(131, 30, 201, 'e2_n1_s3', 'Hoi, Tok Penglipur Lara! Duduk dulu atas tong ni sebelum bot berlepas! Pelanggan saya tanya, saya tak tahu: apakah asal usul nama Pulau Pinang?', 2),
(132, NULL, 201, 'e2_n1_s3', 'Tarik nafas dalam-dalam, kerana kisahnya begini: Sempena pokok pinang yang banyak tumbuh di pulau itu, yang dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga.', 3),
(133, 30, 201, 'e2_n1_s3', 'Pokok pinang! Patutlah nama itu sesuai dengan pulau ini! Siapa pula yang memayungi Pulau Pinang?', 4),
(134, NULL, 201, 'e2_n1_s3', 'Dengar elok-elok, ini penting! Ketua negeri Pulau Pinang bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 5),
(135, 30, 201, 'e2_n1_s3', 'Satu lagi, Tok: di manakah ibu negerinya dan bandar dirajanya?', 6),
(136, NULL, 201, 'e2_n1_s3', 'Ini mudah, tetapi ramai tersilap! Ibu negerinya Georgetown.', 7),
(137, 30, 201, 'e2_n1_s3', 'Tok, tok! Radio itu berbunyi sendiri. Itu lagu apa?', 8),
(138, NULL, 201, 'e2_n1_s3', 'Hebat telinga kamu! Lagu negerinya ialah \'Untuk Negeri Kita\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(139, 30, 201, 'e2_n1_s3', 'Ha, sekarang saya boleh jawab pelancong yang bertanya tiap hari! Terima kasih, Tok. Jeti ini bergema dengan cerita Tok!', 10),
(140, NULL, 201, 'e2_n1_s4', 'Cahaya petang menyuluh halaman yang bersih disapu. Bendera Perak berkibar di tiang, jata negeri terpampang pada ukiran rumah, dan gramofon di atas meja mengalunkan lagu negeri.', 1),
(141, 32, 201, 'e2_n1_s4', 'Ya Allah, Tok Penglipur Lara datang! Nenek tunggu dari pagi tadi, Tok. Cucu-cucu bertanya dan nenek buntu: apakah asal usul nama Perak?', 2),
(142, NULL, 201, 'e2_n1_s4', 'Hehe, ini rahsia orang tua-tua: Dikaitkan dengan kilatan ikan di dalam air atau warna bijih timah putih yang berkilat seperti perak.', 3),
(143, 32, 201, 'e2_n1_s4', 'Kilauan perak! Ha, nenek patut sebut dari dulu. Cucu-cucu, dengar elok-elok! Tok, siapa pula yang memayungi Perak?', 4),
(144, NULL, 201, 'e2_n1_s4', 'Hah, jangan lupa yang ini! Ketua negeri Perak bergelar Sultan. Takhtanya berpindah secara bergilir mengikut sistem penggiliran yang unik.', 5),
(145, 32, 201, 'e2_n1_s4', 'Dan di manakah ibu negerinya, Tok? Saya mahu catat dalam buku!', 6),
(146, NULL, 201, 'e2_n1_s4', 'Catat laju-laju! Ibu negerinya Ipoh, dan bandar dirajanya Kuala Kangsar.', 7),
(147, 32, 201, 'e2_n1_s4', 'Eh, dengar! Radio itu berbunyi, TING-TUNG! Lagu apakah itu, Tok?', 8),
(148, NULL, 201, 'e2_n1_s4', 'Dengar, itulah dia! Lagu negerinya ialah \'Allah Lanjutkan Usia Sultan\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(149, 32, 201, 'e2_n1_s4', 'Hebat, Tok! Cucu-cucu nenek sudah tak berani nakal. Mari makan kuih dahulu!', 10),
(150, NULL, 201, 'e2_n1_s5', 'Air sungai mengalir tenang dan burung berkicau di tebing. Bendera Selangor berkibar di tiang, jata negeri terpampang pada pintu gerbang rumah, dan gramofon di atas meja mengalunkan lagu negeri.', 1),
(151, 30, 201, 'e2_n1_s5', 'Tok! Tok Penglipur Lara! Pelanggan saya berbalah di kedai, semuanya bertanya benda sama: apakah asal usul nama Selangor?', 2),
(152, NULL, 201, 'e2_n1_s5', 'Hah, rapatkan duduk dan dengar baik-baik: Sempena Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga yang disebut selangur.', 3),
(153, 30, 201, 'e2_n1_s5', 'Sungai, pokok, serangga? Banyaknya teori! Saya ingat satu cerita saja. Tok memang gudang cerita! Siapa pula yang memayungi Selangor?', 4),
(154, NULL, 201, 'e2_n1_s5', 'Nah, ini yang ramai terlupa! Ketua negeri Selangor bergelar Sultan.', 5),
(155, 30, 201, 'e2_n1_s5', 'Ibu negerinya pula, Tok? Cepat, cepat, saya tak sabar!', 6),
(156, NULL, 201, 'e2_n1_s5', 'Pena sudah sedia? Ibu negerinya Shah Alam, dan bandar dirajanya Klang.', 7),
(157, 30, 201, 'e2_n1_s5', 'Shhh! Radio itu mengalunkan lagu, Tok. Lagu negeri apakah itu?', 8),
(158, NULL, 201, 'e2_n1_s5', 'Jangan berhenti menyanyi! Lagu negerinya ialah \'Duli Yang Maha Mulia\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(159, 30, 201, 'e2_n1_s5', 'Pelanggan saya senyap semua, Tok! Ini baru namanya penglipur lara. Esok datang lagi, ya!', 10),
(160, NULL, 201, 'e2_n1_s6', 'Bumbung bergonjong rumah adat tegak di hujung halaman. Bendera Negeri Sembilan berkibar di tiang, jata negeri terpampang pada pintu pagar, dan gramofon di halaman mengalunkan lagu negeri.', 1),
(161, 32, 201, 'e2_n1_s6', 'Tok Penglipur Lara, naiklah ke halaman! Nenek sedang membetulkan sirih tapi cucu bertanya soalan sukar: apakah asal usul nama Negeri Sembilan?', 2),
(162, NULL, 201, 'e2_n1_s6', 'Syyy! Ini bukan cerita calang-calang: Penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada \'nagari\'.', 3),
(163, 32, 201, 'e2_n1_s6', 'Sembilan luak! Ha, ya betul, nenek pun ingat sekarang. Dan \'nagari\' bermaksud wilayah. Pandainya Tok! Siapa pula yang memayungi Negeri Sembilan?', 4),
(164, NULL, 201, 'e2_n1_s6', 'Soalan yang bagus! Ketua negeri Negeri Sembilan bergelar Yang di-Pertuan Besar. Beliau dipilih oleh Undang Yang Empat.', 5),
(165, 32, 201, 'e2_n1_s6', 'Satu lagi, Tok: di manakah ibu negerinya dan bandar dirajanya?', 6),
(166, NULL, 201, 'e2_n1_s6', 'Ini mudah, tetapi ramai tersilap! Ibu negerinya Seremban, dan bandar dirajanya Seri Menanti.', 7),
(167, 32, 201, 'e2_n1_s6', 'Tok, tok! Radio itu berbunyi sendiri. Itu lagu apa?', 8),
(168, NULL, 201, 'e2_n1_s6', 'Hebat telinga kamu! Lagu negerinya ialah \'Berkatlah Yang di-Pertuan Besar\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(169, 32, 201, 'e2_n1_s6', 'Cucu-cucu nenek ternganga macam ikan keli. Terima kasih, Tok! Marilah naik, nenek hidangkan masakan lemak.', 10),
(170, NULL, 201, 'e2_n1_s7', 'Bunyi sungai dan bayangan kubu lama menyambut pagi. Bendera Melaka berkibar di atas kubu, jata negeri terpampang pada papan kayu, dan gambus di atas tugu mengalunkan lagu negeri.', 1),
(171, 30, 201, 'e2_n1_s7', 'Tok Penglipur Lara! Demi sejarah, singgahlah dahulu! Pelancong bertanya dan saya tak tahu jawab: apakah asal usul nama Melaka?', 2),
(172, NULL, 201, 'e2_n1_s7', 'Tarik nafas dalam-dalam, kerana kisahnya begini: Sempena pokok Melaka tempat Parameswara berehat, atau \'Malakat\' dalam rujukan Arab yang bermaksud pusat pedagang.', 3),
(173, 30, 201, 'e2_n1_s7', 'Pokok Melaka! Tempat Parameswara berehat! Saya selalu lalu situ tapi tak pernah fikir. Hebat Tok! Siapa pula yang memayungi Melaka?', 4),
(174, NULL, 201, 'e2_n1_s7', 'Dengar elok-elok, ini penting! Ketua negeri Melaka bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 5),
(175, 30, 201, 'e2_n1_s7', 'Dan di manakah ibu negerinya, Tok? Saya mahu catat dalam buku!', 6),
(176, NULL, 201, 'e2_n1_s7', 'Catat laju-laju! Ibu negerinya Bandar Melaka.', 7),
(177, 30, 201, 'e2_n1_s7', 'Eh, dengar! Radio itu berbunyi, TING-TUNG! Lagu apakah itu, Tok?', 8),
(178, NULL, 201, 'e2_n1_s7', 'Dengar, itulah dia! Lagu negerinya ialah \'Melaka Maju Jaya\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(179, 30, 201, 'e2_n1_s7', 'Pelancong bertepuk tangan, Tok! Sungai Melaka pun macam mengalir lebih laju dengan semangat cerita itu.', 10),
(180, NULL, 201, 'e2_n1_s8', 'Angin petang menyapu permukaan sungai yang berkilat. Bendera Johor berkibar di tepi sungai, jata negeri terpampang pada pintu gerbang, dan gramofon di kedai kopi mengalunkan lagu negeri.', 1),
(181, 30, 201, 'e2_n1_s8', 'Aduh, Tok Penglipur Lara! Tepat pada masanya! Kedai kopi saya hampir bergaduh sebab satu soalan: apakah asal usul nama Johor?', 2),
(182, NULL, 201, 'e2_n1_s8', 'Hehe, ini rahsia orang tua-tua: Daripada perkataan Arab \'Jauhar\' (batu permata bernilai), dan dikenali sebagai Ujung Tanah dalam Sulalatus Salatin.', 3),
(183, 30, 201, 'e2_n1_s8', 'Batu permata! Patutlah Johor berkilau! Orang kedai kopi pun pasti terkejut. Tok, siapa pula yang memayungi Johor?', 4),
(184, NULL, 201, 'e2_n1_s8', 'Hah, jangan lupa yang ini! Ketua negeri Johor bergelar Sultan.', 5),
(185, 30, 201, 'e2_n1_s8', 'Ibu negerinya pula, Tok? Cepat, cepat, saya tak sabar!', 6),
(186, NULL, 201, 'e2_n1_s8', 'Pena sudah sedia? Ibu negerinya Johor Bahru, dan bandar dirajanya Bandar Maharani.', 7),
(187, 30, 201, 'e2_n1_s8', 'Shhh! Radio itu mengalunkan lagu, Tok. Lagu negeri apakah itu?', 8),
(188, NULL, 201, 'e2_n1_s8', 'Jangan berhenti menyanyi! Lagu negerinya ialah \'Lagu Bangsa Johor\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(189, 30, 201, 'e2_n1_s8', 'Seisi kedai kopi senyap, Tok! Kopi pun sejuk sebab semua dengar cerita Tok. Hebat!', 10),
(190, NULL, 201, 'e2_n1_s9', 'Kabus nipis naik dari sungai dan hutan di seberang. Bendera Pahang berkibar di tepi sungai, jata negeri terpampang pada rumah besar, dan radio di atas meja kayu mengalunkan lagu negeri.', 1),
(191, 29, 201, 'e2_n1_s9', 'Hoi, Tok Penglipur Lara! Datuk saya tinggalkan catatan lama tapi saya tak boleh baca soalan pertamanya: apakah asal usul nama Pahang?', 2),
(192, NULL, 201, 'e2_n1_s9', 'Hah, rapatkan duduk dan dengar baik-baik: Diambil daripada nama pokok mahang, dan dikenali juga sebagai Inderapura dalam catatan lama.', 3),
(193, 29, 201, 'e2_n1_s9', 'Pokok mahang! Dan Inderapura pun rupanya nama lamanya! Kabus pun macam tersenyum. Tok, siapa pula yang memayungi Pahang?', 4),
(194, NULL, 201, 'e2_n1_s9', 'Nah, ini yang ramai terlupa! Ketua negeri Pahang bergelar Sultan.', 5),
(195, 29, 201, 'e2_n1_s9', 'Satu lagi, Tok: di manakah ibu negerinya dan bandar dirajanya?', 6),
(196, NULL, 201, 'e2_n1_s9', 'Ini mudah, tetapi ramai tersilap! Ibu negerinya Kuantan, dan bandar dirajanya Pekan.', 7),
(197, 29, 201, 'e2_n1_s9', 'Tok, tok! Radio itu berbunyi sendiri. Itu lagu apa?', 8),
(198, NULL, 201, 'e2_n1_s9', 'Hebat telinga kamu! Lagu negerinya ialah \'Allah Selamatkan Sultan Kami\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(199, 29, 201, 'e2_n1_s9', 'Datuk saya pasti bangga di alam sana, Tok! Hutan seberang sungai pun senyap dengar cerita Tok.', 10),
(200, NULL, 201, 'e2_n1_s10', 'Ombak berbuih memukul pantai dan layang-layang camar berputar. Bendera Terengganu berkibar di tepi pantai, jata negeri terpampang pada dinding rumah, dan alat muzik di beranda mengalunkan lagu negeri.', 1),
(201, 27, 201, 'e2_n1_s10', 'Tok Penglipur Lara! Sini, duduk atas perahu ini! Saya nelayan tapi tak pandai jawab soalan anak saya: apakah asal usul nama Terengganu?', 2),
(202, NULL, 201, 'e2_n1_s10', 'Syyy! Ini bukan cerita calang-calang: Daripada sebutan \'taring anu\' (taring harimau atau binatang liar) atau \'terang ganu\' yang bermaksud pelangi.', 3),
(203, 27, 201, 'e2_n1_s10', 'Taring binatang atau pelangi! Dua-duanya cantik, Tok! Hampir terlepas jala saya kerana terkejut. Siapa pula yang memayungi Terengganu?', 4),
(204, NULL, 201, 'e2_n1_s10', 'Soalan yang bagus! Ketua negeri Terengganu bergelar Sultan.', 5),
(205, 27, 201, 'e2_n1_s10', 'Dan di manakah ibu negerinya, Tok? Saya mahu catat dalam buku!', 6),
(206, NULL, 201, 'e2_n1_s10', 'Catat laju-laju! Ibu negerinya Kuala Terengganu.', 7),
(207, 27, 201, 'e2_n1_s10', 'Eh, dengar! Radio itu berbunyi, TING-TUNG! Lagu apakah itu, Tok?', 8),
(208, NULL, 201, 'e2_n1_s10', 'Dengar, itulah dia! Lagu negerinya ialah \'Selamat Sultan\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(209, 27, 201, 'e2_n1_s10', 'Anak saya melompat gembira, Tok! Perahu ini bergoyang tak henti. Terima kasih banyak!', 10),
(210, NULL, 201, 'e2_n1_s11', 'Ukiran kayu berkilat di rumah tua yang harum dengan bunga. Bendera Kelantan berkibar di tiang, jata negeri terpampang pada gerbang rumah, dan rebana dan serunai di atas meja mengalunkan lagu negeri.', 1),
(211, 32, 201, 'e2_n1_s11', 'Tok Penglipur Lara! Nenek sedang menyudahkan tikar ni, tapi cucu bertanya soalan yang nenek tak dapat jawab: apakah asal usul nama Kelantan?', 2),
(212, NULL, 201, 'e2_n1_s11', 'Tarik nafas dalam-dalam, kerana kisahnya begini: Sebutan \'kilatan\' (cahaya terang) atau nama pokok gelam hutan, dan disebut Ho-lan-tan dalam rujukan China.', 3),
(213, 32, 201, 'e2_n1_s11', 'Kilatan cahaya atau pokok gelam hutan! Cantik betul ceritanya. Dan orang China menyebutnya Ho-lan-tan! Tok, siapa pula yang memayungi Kelantan?', 4),
(214, NULL, 201, 'e2_n1_s11', 'Dengar elok-elok, ini penting! Ketua negeri Kelantan bergelar Sultan.', 5),
(215, 32, 201, 'e2_n1_s11', 'Ibu negerinya pula, Tok? Cepat, cepat, saya tak sabar!', 6),
(216, NULL, 201, 'e2_n1_s11', 'Pena sudah sedia? Ibu negerinya Kota Bharu.', 7),
(217, 32, 201, 'e2_n1_s11', 'Shhh! Radio itu mengalunkan lagu, Tok. Lagu negeri apakah itu?', 8),
(218, NULL, 201, 'e2_n1_s11', 'Jangan berhenti menyanyi! Lagu negerinya ialah \'Selamat Sultan\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(219, 32, 201, 'e2_n1_s11', 'Cucu nenek terdiam, Tok! Jarang betul dia diam begini. Marilah makan dahulu.', 10),
(220, NULL, 201, 'e2_n1_s12', 'Air sungai berwarna teh mengalir lambat di bawah tebing. Bendera Sarawak berkibar tinggi, jata negeri terpampang pada pintu gerbang, dan alat muzik di atas tugu mengalunkan lagu negeri.', 1),
(221, 34, 201, 'e2_n1_s12', 'Uy, Tok Penglipur Lara! Datang jauh sampai sini? Saya bangga dengan nama negeri saya tapi satu soalan membuntukan saya: apakah asal usul nama Sarawak?', 2),
(222, NULL, 201, 'e2_n1_s12', 'Hehe, ini rahsia orang tua-tua: Berasal daripada Sungai Sarawak, logam antimoni yang disebut cerava, atau dialog \'serah kepada awak\'.', 3),
(223, 34, 201, 'e2_n1_s12', 'Sungai, antimoni, atau \'serah kepada awak\'! Banyak betul cerita! Saya mesti ceritakan pada kawan di bandar. Tok, siapa pula yang memayungi Sarawak?', 4),
(224, NULL, 201, 'e2_n1_s12', 'Hah, jangan lupa yang ini! Ketua negeri Sarawak bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 5),
(225, 34, 201, 'e2_n1_s12', 'Satu lagi, Tok: di manakah ibu negerinya dan bandar dirajanya?', 6),
(226, NULL, 201, 'e2_n1_s12', 'Ini mudah, tetapi ramai tersilap! Ibu negerinya Kuching.', 7),
(227, 34, 201, 'e2_n1_s12', 'Tok, tok! Radio itu berbunyi sendiri. Itu lagu apa?', 8),
(228, NULL, 201, 'e2_n1_s12', 'Hebat telinga kamu! Lagu negerinya ialah \'Ibu Pertiwiku\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(229, 34, 201, 'e2_n1_s12', 'Gempak, Tok! Sungai ini sendiri macam mengalir lebih laju mendengar cerita Tok.', 10),
(230, NULL, 201, 'e2_n1_s13', 'Angin teluk berhembus sambil gong kecil berdenting jauh. Bendera Sabah berkibar di tiang, jata negeri terpampang pada bangunan batu, dan alat muzik di pondok mengalunkan lagu negeri.', 1),
(231, 33, 201, 'e2_n1_s13', 'Selamat datang, Tok Penglipur Lara! Duduk dahulu di pondok ini. Kami bawa nota dari kampung tapi tak pandai tafsir: apakah asal usul nama Sabah?', 2),
(232, NULL, 201, 'e2_n1_s13', 'Hah, rapatkan duduk dan dengar baik-baik: Diambil daripada sejenis pisang, iaitu pisang saba (pisang jaba).', 3),
(233, 33, 201, 'e2_n1_s13', 'Pisang saba! Pisang jaba! Perut saya pun berbunyi mendengarnya. Hebat sungguh, Tok! Siapa pula yang memayungi Sabah?', 4),
(234, NULL, 201, 'e2_n1_s13', 'Nah, ini yang ramai terlupa! Ketua negeri Sabah bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 5),
(235, 33, 201, 'e2_n1_s13', 'Dan di manakah ibu negerinya, Tok? Saya mahu catat dalam buku!', 6),
(236, NULL, 201, 'e2_n1_s13', 'Catat laju-laju! Ibu negerinya Kota Kinabalu.', 7),
(237, 33, 201, 'e2_n1_s13', 'Eh, dengar! Radio itu berbunyi, TING-TUNG! Lagu apakah itu, Tok?', 8),
(238, NULL, 201, 'e2_n1_s13', 'Dengar, itulah dia! Lagu negerinya ialah \'Sabah Tanah Airku\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(239, 33, 201, 'e2_n1_s13', 'Seisi kampung bertepuk tangan, Tok! Gong pun berbunyi sendiri. Terima kasih banyak!', 10),
(240, NULL, 201, 'e2_n1_s14', 'Lampu bandar menyala dan bunyi trafik bersahut-sahutan. Bendera Wilayah Persekutuan berkibar di tiang, jata negeri terpampang pada gerbang batu, dan gramofon di atas tugu mengalunkan lagu negeri.', 1),
(241, 38, 201, 'e2_n1_s14', 'Wah, Tok Penglipur Lara betul-betul wujud! Cikgu suruh buat kerja rumah tentang nama Wilayah Persekutuan tapi Google pun buntu: apakah asal usul namanya?', 2),
(242, NULL, 201, 'e2_n1_s14', 'Syyy! Ini bukan cerita calang-calang: Kuala Lumpur daripada muara sungai berlumpur akibat perlombongan bijih timah, Labuan daripada \'labuhan\', Putrajaya sempena Tunku Abdul Rahman Putra.', 3),
(243, 38, 201, 'e2_n1_s14', 'Muara berlumpur, labuhan, dan nama Tunku! Tiga nama, tiga cerita! Boleh saya rakam? Tok, siapa pula yang memayungi Wilayah Persekutuan?', 4),
(244, NULL, 201, 'e2_n1_s14', 'Soalan yang bagus! Ketua negeri bagi tiga Wilayah Persekutuan ialah Yang di-Pertuan Agong.', 5),
(245, 38, 201, 'e2_n1_s14', 'Adakah Wilayah Persekutuan ada ibu negeri sendiri, Tok? Saya hairan betul!', 6),
(246, NULL, 201, 'e2_n1_s14', 'Pena sudah sedia? Wilayah Persekutuan tidak mempunyai ibu negeri tersendiri; ketiga-tiganya ialah Kuala Lumpur, Labuan dan Putrajaya.', 7),
(247, 38, 201, 'e2_n1_s14', 'Shhh! Radio itu mengalunkan lagu, Tok. Lagu negeri apakah itu?', 8),
(248, NULL, 201, 'e2_n1_s14', 'Jangan berhenti menyanyi! Lagu negerinya ialah \'Maju dan Sejahtera\'. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(249, 38, 201, 'e2_n1_s14', 'Kerja rumah saya selesai! Kawan-kawan mesti cemburu. Terima kasih, Tok! Boleh saya siarkan?', 10),
(250, 22, 202, NULL, 'Payung hanya berguna jika dipegang dengan betul, {nama}. Kerana kau memegang payung negeri ini, gelaran dan adat kita tidak pudar. Daulat Tuanku, dan terima kasih!', 1),
(251, 22, 202, NULL, 'Setiap gelaran ketua negeri membawa sejarah dan tanggungjawabnya sendiri. Menghormatinya bermakna menghormati warisan negara kita.', 2),
(252, 22, 202, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, ketua sebuah negeri beraja. Gamelan berbunyi, panji berkibar, dan ketua-ketua negeri lain menanti. Lihat dengan matanya dan bertitahlah dengan suaranya!', 3),
(253, NULL, 202, 'e2_n2_s1', 'Angin petang menyapu permukaan sungai yang berkilat. Bendera Johor berkibar di tepi sungai, jata negeri terpampang pada pintu gerbang, dan gramofon di kedai kopi mengalunkan lagu negeri.', 1),
(254, 22, 202, 'e2_n2_s1', 'Selamat datang ke Johor, Tuanku! Angin petang menyambut Tuanku di tepi sungai. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(255, NULL, 202, 'e2_n2_s1', 'Hmm, beta mahu melihat jata itu dahulu. Gelaran bukan sekadar nama; ia membawa sejarah.', 3),
(256, 22, 202, 'e2_n2_s1', 'Demikianlah, Tuanku. Ketua negeri Johor bergelar Sultan.', 4),
(257, NULL, 202, 'e2_n2_s1', 'Dan nama Johor sendiri, dari manakah asalnya? Beta terlalu ingin tahu!', 5),
(258, 22, 202, 'e2_n2_s1', 'Menurut cerita lama, daripada perkataan Arab \'Jauhar\' (batu permata bernilai), dan dikenali sebagai Ujung Tanah dalam Sulalatus Salatin.', 6),
(259, NULL, 202, 'e2_n2_s1', 'Wah, menarik sekali! Beta tidak menyangka cerita nama itu begitu. Dan ibu negeri serta bandar dirajanya pula?', 7),
(260, 22, 202, 'e2_n2_s1', 'Ibu negerinya Johor Bahru, dan bandar dirajanya Bandar Maharani.', 8),
(261, NULL, 202, 'e2_n2_s1', 'Dengar! Radio itu berbunyi, dan beta kenal bunyinya. Lagu apakah itu?', 9),
(262, 22, 202, 'e2_n2_s1', 'Lagu negerinya ialah \'Lagu Bangsa Johor\'.', 10),
(263, NULL, 202, 'e2_n2_s1', 'Terima kasih, Tuanku. Beta sudah mencatat semuanya dalam hati.', 11),
(264, 22, 202, 'e2_n2_s1', 'Semoga Tuanku mengingati Johor seperti batu permata, berkilau dalam ingatan.', 12),
(265, NULL, 202, 'e2_n2_s2', 'Hamparan sawah padi berkilau di bawah langit senja. Bendera Kedah berkibar di hujung tiang, jata negeri terpampang pada rumah besar, dan alat muzik di beranda mengalunkan lagu negeri.', 1),
(266, 22, 202, 'e2_n2_s2', 'Selamat datang, Tuanku! Sawah Kedah sedang berkilau menyambut kunjungan Tuanku. Cuba teka: apakah gelaran ketua negeri kami?', 2),
(267, NULL, 202, 'e2_n2_s2', 'Beta perhatikan bendera itu berkibar megah. Biar beta cuba teka dahulu...', 3),
(268, 22, 202, 'e2_n2_s2', 'Tepat pada pertanyaan Tuanku. Ketua negeri Kedah bergelar Sultan.', 4),
(269, NULL, 202, 'e2_n2_s2', 'Apakah pula sejarah nama Kedah? Ceritakanlah, beta sedia mendengar!', 5),
(270, 22, 202, 'e2_n2_s2', 'Menurut cerita lama, daripada \'Kheddah\' (perangkap gajah), \'Qadah\' dalam bahasa Arab (gelas berkaki) atau \'Kadaram\' dalam rujukan India.', 6),
(271, NULL, 202, 'e2_n2_s2', 'Subhanallah, ada rupanya! Beta suka cerita begini. Di manakah ibu negerinya?', 7),
(272, 22, 202, 'e2_n2_s2', 'Ibu negerinya Alor Setar, dan bandar dirajanya Anak Bukit.', 8),
(273, NULL, 202, 'e2_n2_s2', 'Alunan itu merdu sekali! Lagu apakah yang dimainkan di radio itu?', 9),
(274, 22, 202, 'e2_n2_s2', 'Lagu negerinya ialah \'Allah Selamatkan Sultan Mahkota\'.', 10),
(275, NULL, 202, 'e2_n2_s2', 'Alhamdulillah, hari ini beta bertambah ilmu tentang warisan negeri.', 11),
(276, 22, 202, 'e2_n2_s2', 'Semoga Tuanku bawa pulang cerita Kedah, dan sebutkan nama Kedah dengan bangga!', 12),
(277, NULL, 202, 'e2_n2_s3', 'Ukiran kayu berkilat di rumah tua yang harum dengan bunga. Bendera Kelantan berkibar di tiang, jata negeri terpampang pada gerbang rumah, dan rebana dan serunai di atas meja mengalunkan lagu negeri.', 1),
(278, 22, 202, 'e2_n2_s3', 'Selamat datang ke Kelantan, Tuanku! Ukiran kayu rumah ini berkilat menyambut Tuanku. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(279, NULL, 202, 'e2_n2_s3', 'Menarik! Beta sudah lama ingin tahu tentang perkara ini.', 3),
(280, 22, 202, 'e2_n2_s3', 'Itulah jawapannya, Tuanku. Ketua negeri Kelantan bergelar Sultan.', 4),
(281, NULL, 202, 'e2_n2_s3', 'Nama Kelantan bunyinya indah. Bagaimana ia bermula?', 5),
(282, 22, 202, 'e2_n2_s3', 'Menurut cerita lama, sebutan \'kilatan\' (cahaya terang) atau nama pokok gelam hutan, dan disebut Ho-lan-tan dalam rujukan China.', 6),
(283, NULL, 202, 'e2_n2_s3', 'Hmm, menarik! Beta akan ingat itu. Ibu negeri dan bandar dirajanya pula di mana?', 7),
(284, 22, 202, 'e2_n2_s3', 'Ibu negerinya Kota Bharu.', 8),
(285, NULL, 202, 'e2_n2_s3', 'Ada lagu di radio itu! Beta pasti ia lagu negeri. Apakah tajuknya?', 9),
(286, 22, 202, 'e2_n2_s3', 'Lagu negerinya ialah \'Selamat Sultan\'.', 10),
(287, NULL, 202, 'e2_n2_s3', 'Beta pulang dengan hati yang puas. Daulat!', 11),
(288, 22, 202, 'e2_n2_s3', 'Semoga Tuanku mengenang Kelantan melalui ukiran dan cerita yang sampai ke telinga.', 12),
(289, NULL, 202, 'e2_n2_s4', 'Kabus nipis naik dari sungai dan hutan di seberang. Bendera Pahang berkibar di tepi sungai, jata negeri terpampang pada rumah besar, dan radio di atas meja kayu mengalunkan lagu negeri.', 1),
(290, 22, 202, 'e2_n2_s4', 'Selamat datang ke Pahang, Tuanku! Kabus sungai ini menyambut Tuanku dengan tenang. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(291, NULL, 202, 'e2_n2_s4', 'Hmm, beta mahu melihat jata itu dahulu. Gelaran bukan sekadar nama; ia membawa sejarah.', 3),
(292, 22, 202, 'e2_n2_s4', 'Demikianlah, Tuanku. Ketua negeri Pahang bergelar Sultan.', 4),
(293, NULL, 202, 'e2_n2_s4', 'Dan nama Pahang sendiri, dari manakah asalnya? Beta terlalu ingin tahu!', 5),
(294, 22, 202, 'e2_n2_s4', 'Menurut cerita lama, diambil daripada nama pokok mahang, dan dikenali juga sebagai Inderapura dalam catatan lama.', 6),
(295, NULL, 202, 'e2_n2_s4', 'Wah, menarik sekali! Beta tidak menyangka cerita nama itu begitu. Dan ibu negeri serta bandar dirajanya pula?', 7),
(296, 22, 202, 'e2_n2_s4', 'Ibu negerinya Kuantan, dan bandar dirajanya Pekan.', 8),
(297, NULL, 202, 'e2_n2_s4', 'Dengar! Radio itu berbunyi, dan beta kenal bunyinya. Lagu apakah itu?', 9),
(298, 22, 202, 'e2_n2_s4', 'Lagu negerinya ialah \'Allah Selamatkan Sultan Kami\'.', 10),
(299, NULL, 202, 'e2_n2_s4', 'Terima kasih, Tuanku. Beta sudah mencatat semuanya dalam hati.', 11),
(300, 22, 202, 'e2_n2_s4', 'Semoga Tuanku mengenang Pahang bila kabus pagi naik dari sungai.', 12),
(301, NULL, 202, 'e2_n2_s5', 'Cahaya petang menyuluh halaman yang bersih disapu. Bendera Perak berkibar di tiang, jata negeri terpampang pada ukiran rumah, dan gramofon di atas meja mengalunkan lagu negeri.', 1),
(302, 22, 202, 'e2_n2_s5', 'Selamat datang ke Perak, Tuanku! Halaman ini disapu bersih sejak subuh. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(303, NULL, 202, 'e2_n2_s5', 'Beta perhatikan bendera itu berkibar megah. Biar beta cuba teka dahulu...', 3),
(304, 22, 202, 'e2_n2_s5', 'Tepat pada pertanyaan Tuanku. Ketua negeri Perak bergelar Sultan. Takhtanya berpindah secara bergilir mengikut sistem penggiliran yang unik.', 4),
(305, NULL, 202, 'e2_n2_s5', 'Apakah pula sejarah nama Perak? Ceritakanlah, beta sedia mendengar!', 5),
(306, 22, 202, 'e2_n2_s5', 'Menurut cerita lama, dikaitkan dengan kilatan ikan di dalam air atau warna bijih timah putih yang berkilat seperti perak.', 6),
(307, NULL, 202, 'e2_n2_s5', 'Subhanallah, ada rupanya! Beta suka cerita begini. Di manakah ibu negerinya?', 7),
(308, 22, 202, 'e2_n2_s5', 'Ibu negerinya Ipoh, dan bandar dirajanya Kuala Kangsar.', 8),
(309, NULL, 202, 'e2_n2_s5', 'Alunan itu merdu sekali! Lagu apakah yang dimainkan di radio itu?', 9),
(310, 22, 202, 'e2_n2_s5', 'Lagu negerinya ialah \'Allah Lanjutkan Usia Sultan\'.', 10),
(311, NULL, 202, 'e2_n2_s5', 'Alhamdulillah, hari ini beta bertambah ilmu tentang warisan negeri.', 11),
(312, 22, 202, 'e2_n2_s5', 'Semoga Tuanku puas bertandang. Kuih sudah dihidang, jangan balik begitu sahaja!', 12),
(313, NULL, 202, 'e2_n2_s6', 'Air sungai mengalir tenang dan burung berkicau di tebing. Bendera Selangor berkibar di tiang, jata negeri terpampang pada pintu gerbang rumah, dan gramofon di atas meja mengalunkan lagu negeri.', 1),
(314, 22, 202, 'e2_n2_s6', 'Selamat datang ke Selangor, Tuanku! Kicauan burung sungai menyambut kedatangan Tuanku. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(315, NULL, 202, 'e2_n2_s6', 'Menarik! Beta sudah lama ingin tahu tentang perkara ini.', 3),
(316, 22, 202, 'e2_n2_s6', 'Itulah jawapannya, Tuanku. Ketua negeri Selangor bergelar Sultan.', 4),
(317, NULL, 202, 'e2_n2_s6', 'Nama Selangor bunyinya indah. Bagaimana ia bermula?', 5),
(318, 22, 202, 'e2_n2_s6', 'Menurut cerita lama, sempena Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga yang disebut selangur.', 6),
(319, NULL, 202, 'e2_n2_s6', 'Hmm, menarik! Beta akan ingat itu. Ibu negeri dan bandar dirajanya pula di mana?', 7),
(320, 22, 202, 'e2_n2_s6', 'Ibu negerinya Shah Alam, dan bandar dirajanya Klang.', 8),
(321, NULL, 202, 'e2_n2_s6', 'Ada lagu di radio itu! Beta pasti ia lagu negeri. Apakah tajuknya?', 9),
(322, 22, 202, 'e2_n2_s6', 'Lagu negerinya ialah \'Duli Yang Maha Mulia\'.', 10),
(323, NULL, 202, 'e2_n2_s6', 'Beta pulang dengan hati yang puas. Daulat!', 11),
(324, 22, 202, 'e2_n2_s6', 'Semoga Tuanku suka Selangor. Sungai ini sentiasa terbuka untuk Tuanku berehat.', 12),
(325, NULL, 202, 'e2_n2_s7', 'Ombak berbuih memukul pantai dan layang-layang camar berputar. Bendera Terengganu berkibar di tepi pantai, jata negeri terpampang pada dinding rumah, dan alat muzik di beranda mengalunkan lagu negeri.', 1),
(326, 22, 202, 'e2_n2_s7', 'Selamat datang ke Terengganu, Tuanku! Ombak berbuih menyambut Tuanku di pantai. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(327, NULL, 202, 'e2_n2_s7', 'Hmm, beta mahu melihat jata itu dahulu. Gelaran bukan sekadar nama; ia membawa sejarah.', 3),
(328, 22, 202, 'e2_n2_s7', 'Demikianlah, Tuanku. Ketua negeri Terengganu bergelar Sultan.', 4),
(329, NULL, 202, 'e2_n2_s7', 'Dan nama Terengganu sendiri, dari manakah asalnya? Beta terlalu ingin tahu!', 5),
(330, 22, 202, 'e2_n2_s7', 'Menurut cerita lama, daripada sebutan \'taring anu\' (taring harimau atau binatang liar) atau \'terang ganu\' yang bermaksud pelangi.', 6),
(331, NULL, 202, 'e2_n2_s7', 'Wah, menarik sekali! Beta tidak menyangka cerita nama itu begitu. Dan ibu negeri serta bandar dirajanya pula?', 7),
(332, 22, 202, 'e2_n2_s7', 'Ibu negerinya Kuala Terengganu.', 8),
(333, NULL, 202, 'e2_n2_s7', 'Dengar! Radio itu berbunyi, dan beta kenal bunyinya. Lagu apakah itu?', 9),
(334, 22, 202, 'e2_n2_s7', 'Lagu negerinya ialah \'Selamat Sultan\'.', 10),
(335, NULL, 202, 'e2_n2_s7', 'Terima kasih, Tuanku. Beta sudah mencatat semuanya dalam hati.', 11),
(336, 22, 202, 'e2_n2_s7', 'Semoga Tuanku membawa pulang bunyi ombak Terengganu dalam ingatan.', 12),
(337, NULL, 202, 'e2_n2_s8', 'Angin sawah menghembus padi yang menguning. Bendera Perlis berkibar di tiang kampung, jata negeri terpampang pada balai di tengah sawah, dan radio di atas meja mengalunkan lagu negeri.', 1),
(338, 23, 202, 'e2_n2_s8', 'Selamat datang ke Perlis, Tuanku! Angin sawah pun berhenti menyambut. Soalan pertama: tahukah Tuanku gelaran ketua negeri di sini?', 2),
(339, NULL, 202, 'e2_n2_s8', 'Beta perhatikan bendera itu berkibar megah. Biar beta cuba teka dahulu...', 3),
(340, 23, 202, 'e2_n2_s8', 'Tepat pada pertanyaan Tuanku. Ketua negeri Perlis bergelar Raja.', 4),
(341, NULL, 202, 'e2_n2_s8', 'Apakah pula sejarah nama Perlis? Ceritakanlah, beta sedia mendengar!', 5),
(342, 23, 202, 'e2_n2_s8', 'Menurut cerita lama, daripada perkataan Siam \'phrau loi\' (kelapa hanyut), perkataan tempatan \'peroleh\' atau tokoh Tok Perlis.', 6),
(343, NULL, 202, 'e2_n2_s8', 'Subhanallah, ada rupanya! Beta suka cerita begini. Di manakah ibu negerinya?', 7),
(344, 23, 202, 'e2_n2_s8', 'Ibu negerinya Kangar, dan bandar dirajanya Arau.', 8),
(345, NULL, 202, 'e2_n2_s8', 'Alunan itu merdu sekali! Lagu apakah yang dimainkan di radio itu?', 9),
(346, 23, 202, 'e2_n2_s8', 'Radio itu mengalunkan lagu negeri; tajuk lagunya belum dapat kita pastikan.', 10),
(347, NULL, 202, 'e2_n2_s8', 'Alhamdulillah, hari ini beta bertambah ilmu tentang warisan negeri.', 11),
(348, 23, 202, 'e2_n2_s8', 'Perlis kecil, Tuanku, tetapi ceritanya besar. Singgahlah lagi bila padi menguning!', 12),
(349, NULL, 202, 'e2_n2_s9', 'Bumbung bergonjong rumah adat tegak di hujung halaman. Bendera Negeri Sembilan berkibar di tiang, jata negeri terpampang pada pintu pagar, dan gramofon di halaman mengalunkan lagu negeri.', 1),
(350, 24, 202, 'e2_n2_s9', 'Selamat datang ke Negeri Sembilan, Tuanku! Bumbung gonjong ini menjadi saksi kunjungan Tuanku. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(351, NULL, 202, 'e2_n2_s9', 'Menarik! Beta sudah lama ingin tahu tentang perkara ini.', 3);
INSERT INTO `DialogueLine` (`dialogueID`, `npcID`, `narrativeID`, `sceneID`, `dialogueLine`, `sequenceOrder`) VALUES
(352, 24, 202, 'e2_n2_s9', 'Itulah jawapannya, Tuanku. Ketua negeri Negeri Sembilan bergelar Yang di-Pertuan Besar. Beliau dipilih oleh Undang Yang Empat.', 4),
(353, NULL, 202, 'e2_n2_s9', 'Nama Negeri Sembilan bunyinya indah. Bagaimana ia bermula?', 5),
(354, 24, 202, 'e2_n2_s9', 'Menurut cerita lama, penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada \'nagari\'.', 6),
(355, NULL, 202, 'e2_n2_s9', 'Hmm, menarik! Beta akan ingat itu. Ibu negeri dan bandar dirajanya pula di mana?', 7),
(356, 24, 202, 'e2_n2_s9', 'Ibu negerinya Seremban, dan bandar dirajanya Seri Menanti.', 8),
(357, NULL, 202, 'e2_n2_s9', 'Ada lagu di radio itu! Beta pasti ia lagu negeri. Apakah tajuknya?', 9),
(358, 24, 202, 'e2_n2_s9', 'Lagu negerinya ialah \'Berkatlah Yang di-Pertuan Besar\'.', 10),
(359, NULL, 202, 'e2_n2_s9', 'Beta pulang dengan hati yang puas. Daulat!', 11),
(360, 24, 202, 'e2_n2_s9', 'Moga Tuanku mengingati Negeri Sembilan dengan bumbung gonjong dan sembilan luaknya!', 12),
(361, NULL, 202, 'e2_n2_s10', 'Bunyi sungai dan bayangan kubu lama menyambut pagi. Bendera Melaka berkibar di atas kubu, jata negeri terpampang pada papan kayu, dan gambus di atas tugu mengalunkan lagu negeri.', 1),
(362, 25, 202, 'e2_n2_s10', 'Selamat datang ke Melaka, Tuanku! Bayangan kubu lama berdiri menyambut Tuanku. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(363, NULL, 202, 'e2_n2_s10', 'Hmm, beta mahu melihat jata itu dahulu. Gelaran bukan sekadar nama; ia membawa sejarah.', 3),
(364, 25, 202, 'e2_n2_s10', 'Demikianlah, Tuanku. Ketua negeri Melaka bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 4),
(365, NULL, 202, 'e2_n2_s10', 'Dan nama Melaka sendiri, dari manakah asalnya? Beta terlalu ingin tahu!', 5),
(366, 25, 202, 'e2_n2_s10', 'Menurut cerita lama, sempena pokok Melaka tempat Parameswara berehat, atau \'Malakat\' dalam rujukan Arab yang bermaksud pusat pedagang.', 6),
(367, NULL, 202, 'e2_n2_s10', 'Wah, menarik sekali! Beta tidak menyangka cerita nama itu begitu. Dan ibu negeri serta bandar dirajanya pula?', 7),
(368, 25, 202, 'e2_n2_s10', 'Ibu negerinya Bandar Melaka.', 8),
(369, NULL, 202, 'e2_n2_s10', 'Dengar! Radio itu berbunyi, dan beta kenal bunyinya. Lagu apakah itu?', 9),
(370, 25, 202, 'e2_n2_s10', 'Lagu negerinya ialah \'Melaka Maju Jaya\'.', 10),
(371, NULL, 202, 'e2_n2_s10', 'Terima kasih, Tuanku. Beta sudah mencatat semuanya dalam hati.', 11),
(372, 25, 202, 'e2_n2_s10', 'Semoga Tuanku membawa semangat Melaka bersama. Kubu lama ini sentiasa menunggu kedatangan Tuanku.', 12),
(373, NULL, 202, 'e2_n2_s11', 'Bau garam dan angin laut singgah di jeti yang sibuk. Bendera Pulau Pinang berkibar di jeti, jata negeri terpampang pada gerbang batu, dan gramofon di tepi laut mengalunkan lagu negeri.', 1),
(374, 25, 202, 'e2_n2_s11', 'Selamat datang ke Pulau Pinang, Tuanku! Bunyi pekikan burung camar pun bagai menyambut. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(375, NULL, 202, 'e2_n2_s11', 'Beta perhatikan bendera itu berkibar megah. Biar beta cuba teka dahulu...', 3),
(376, 25, 202, 'e2_n2_s11', 'Tepat pada pertanyaan Tuanku. Ketua negeri Pulau Pinang bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 4),
(377, NULL, 202, 'e2_n2_s11', 'Apakah pula sejarah nama Pulau Pinang? Ceritakanlah, beta sedia mendengar!', 5),
(378, 25, 202, 'e2_n2_s11', 'Menurut cerita lama, sempena pokok pinang yang banyak tumbuh di pulau itu, yang dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga.', 6),
(379, NULL, 202, 'e2_n2_s11', 'Subhanallah, ada rupanya! Beta suka cerita begini. Di manakah ibu negerinya?', 7),
(380, 25, 202, 'e2_n2_s11', 'Ibu negerinya Georgetown.', 8),
(381, NULL, 202, 'e2_n2_s11', 'Alunan itu merdu sekali! Lagu apakah yang dimainkan di radio itu?', 9),
(382, 25, 202, 'e2_n2_s11', 'Lagu negerinya ialah \'Untuk Negeri Kita\'.', 10),
(383, NULL, 202, 'e2_n2_s11', 'Alhamdulillah, hari ini beta bertambah ilmu tentang warisan negeri.', 11),
(384, 25, 202, 'e2_n2_s11', 'Pulau ini kecil, Tuanku, tetapi hati kami besar. Semoga Tuanku singgah lagi sebelum bot terakhir berlepas.', 12),
(385, NULL, 202, 'e2_n2_s12', 'Angin teluk berhembus sambil gong kecil berdenting jauh. Bendera Sabah berkibar di tiang, jata negeri terpampang pada bangunan batu, dan alat muzik di pondok mengalunkan lagu negeri.', 1),
(386, 25, 202, 'e2_n2_s12', 'Selamat datang ke Sabah, Tuanku! Angin teluk menyambut Tuanku dengan alunan gong. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(387, NULL, 202, 'e2_n2_s12', 'Menarik! Beta sudah lama ingin tahu tentang perkara ini.', 3),
(388, 25, 202, 'e2_n2_s12', 'Itulah jawapannya, Tuanku. Ketua negeri Sabah bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 4),
(389, NULL, 202, 'e2_n2_s12', 'Nama Sabah bunyinya indah. Bagaimana ia bermula?', 5),
(390, 25, 202, 'e2_n2_s12', 'Menurut cerita lama, diambil daripada sejenis pisang, iaitu pisang saba (pisang jaba).', 6),
(391, NULL, 202, 'e2_n2_s12', 'Hmm, menarik! Beta akan ingat itu. Ibu negeri dan bandar dirajanya pula di mana?', 7),
(392, 25, 202, 'e2_n2_s12', 'Ibu negerinya Kota Kinabalu.', 8),
(393, NULL, 202, 'e2_n2_s12', 'Ada lagu di radio itu! Beta pasti ia lagu negeri. Apakah tajuknya?', 9),
(394, 25, 202, 'e2_n2_s12', 'Lagu negerinya ialah \'Sabah Tanah Airku\'.', 10),
(395, NULL, 202, 'e2_n2_s12', 'Beta pulang dengan hati yang puas. Daulat!', 11),
(396, 25, 202, 'e2_n2_s12', 'Semoga Tuanku membawa pulang hembusan angin teluk Sabah dalam ingatan.', 12),
(397, NULL, 202, 'e2_n2_s13', 'Air sungai berwarna teh mengalir lambat di bawah tebing. Bendera Sarawak berkibar tinggi, jata negeri terpampang pada pintu gerbang, dan alat muzik di atas tugu mengalunkan lagu negeri.', 1),
(398, 25, 202, 'e2_n2_s13', 'Selamat datang ke Sarawak, Tuanku! Sungai ini menyambut Tuanku dengan tenang. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(399, NULL, 202, 'e2_n2_s13', 'Hmm, beta mahu melihat jata itu dahulu. Gelaran bukan sekadar nama; ia membawa sejarah.', 3),
(400, 25, 202, 'e2_n2_s13', 'Demikianlah, Tuanku. Ketua negeri Sarawak bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 4),
(401, NULL, 202, 'e2_n2_s13', 'Dan nama Sarawak sendiri, dari manakah asalnya? Beta terlalu ingin tahu!', 5),
(402, 25, 202, 'e2_n2_s13', 'Menurut cerita lama, berasal daripada Sungai Sarawak, logam antimoni yang disebut cerava, atau dialog \'serah kepada awak\'.', 6),
(403, NULL, 202, 'e2_n2_s13', 'Wah, menarik sekali! Beta tidak menyangka cerita nama itu begitu. Dan ibu negeri serta bandar dirajanya pula?', 7),
(404, 25, 202, 'e2_n2_s13', 'Ibu negerinya Kuching.', 8),
(405, NULL, 202, 'e2_n2_s13', 'Dengar! Radio itu berbunyi, dan beta kenal bunyinya. Lagu apakah itu?', 9),
(406, 25, 202, 'e2_n2_s13', 'Lagu negerinya ialah \'Ibu Pertiwiku\'.', 10),
(407, NULL, 202, 'e2_n2_s13', 'Terima kasih, Tuanku. Beta sudah mencatat semuanya dalam hati.', 11),
(408, 25, 202, 'e2_n2_s13', 'Semoga Tuanku membawa nama Sarawak jauh ke seberang laut dan kembali lagi.', 12),
(409, NULL, 202, 'e2_n2_s14', 'Lampu bandar menyala dan bunyi trafik bersahut-sahutan. Bendera Wilayah Persekutuan berkibar di tiang, jata negeri terpampang pada gerbang batu, dan gramofon di atas tugu mengalunkan lagu negeri.', 1),
(410, 38, 202, 'e2_n2_s14', 'Selamat datang ke ibu kota, Tuanku! Lampu bandar menyala menyambut Tuanku. Soalan pembuka: tahukah Tuanku gelaran ketua negeri bagi tiga Wilayah Persekutuan?', 2),
(411, NULL, 202, 'e2_n2_s14', 'Beta perhatikan bendera itu berkibar megah. Biar beta cuba teka dahulu...', 3),
(412, 38, 202, 'e2_n2_s14', 'Tepat pada pertanyaan Tuanku. Ketua negeri bagi tiga Wilayah Persekutuan ialah Yang di-Pertuan Agong.', 4),
(413, NULL, 202, 'e2_n2_s14', 'Apakah pula sejarah nama Wilayah Persekutuan? Ceritakanlah, beta sedia mendengar!', 5),
(414, 38, 202, 'e2_n2_s14', 'Menurut cerita lama, kuala Lumpur daripada muara sungai berlumpur akibat perlombongan bijih timah, Labuan daripada \'labuhan\', Putrajaya sempena Tunku Abdul Rahman Putra.', 6),
(415, NULL, 202, 'e2_n2_s14', 'Menarik sekali! Tetapi adakah Wilayah Persekutuan mempunyai ibu negeri sendiri?', 7),
(416, 38, 202, 'e2_n2_s14', 'Wilayah Persekutuan tidak mempunyai ibu negeri tersendiri; ketiga-tiganya ialah Kuala Lumpur, Labuan dan Putrajaya.', 8),
(417, NULL, 202, 'e2_n2_s14', 'Alunan itu merdu sekali! Lagu apakah yang dimainkan di radio itu?', 9),
(418, 38, 202, 'e2_n2_s14', 'Lagu negerinya ialah \'Maju dan Sejahtera\'.', 10),
(419, NULL, 202, 'e2_n2_s14', 'Alhamdulillah, hari ini beta bertambah ilmu tentang warisan negeri.', 11),
(420, 38, 202, 'e2_n2_s14', 'Semoga Tuanku suka kota ini. Lampu bandar tidak pernah tidur untuk menyambut Tuanku!', 12),
(421, 26, 203, NULL, 'Setiap negeri yang kau catat ialah satu lagu yang tidak akan senyap, {nama}. Terima kasih kerana mengembara bersamaku, kini ingatan tentang tanah air lebih terang!', 1),
(422, 26, 203, NULL, 'Ibu negeri, bandar diraja dan lagu negeri ialah lambang kebanggaan setiap negeri. Mengenalinya ialah langkah pertama untuk mencintai tanah air.', 2),
(423, 26, 203, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengembara yang menjelajah seluruh tanah air dengan buku catatan di tangan. Beg digalas, kasut diikat, jejak bermula! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(424, NULL, 203, 'e2_n3_s1', 'Angin sawah menghembus padi yang menguning. Bendera Perlis berkibar di tiang kampung, jata negeri terpampang pada balai di tengah sawah, dan radio di atas meja mengalunkan lagu negeri.', 1),
(425, 28, 203, 'e2_n3_s1', 'Pengembara! Jangan pijak batas sawah saya! Anda mencari ibu negeri Perlis, ya? Sudah tahu jawapannya?', 2),
(426, NULL, 203, 'e2_n3_s1', 'Belum! Tetapi pena sudah tajam dan buku catatan terbuka lebar. Ceritakanlah!', 3),
(427, 28, 203, 'e2_n3_s1', 'Catatlah! Ibu negerinya Kangar, dan bandar dirajanya Arau.', 4),
(428, NULL, 203, 'e2_n3_s1', 'Dan radio itu berbunyi sendiri! Lagu negeri apakah yang berkumandang itu?', 5),
(429, 28, 203, 'e2_n3_s1', 'Radio itu mengalunkan lagu negeri; tajuk lagunya belum dapat kita pastikan.', 6),
(430, NULL, 203, 'e2_n3_s1', 'Satu lagi untuk buku catatan: siapakah ketua negerinya, dan dari mana nama negeri ini bermula?', 7),
(431, 28, 203, 'e2_n3_s1', 'Ketua negeri Perlis bergelar Raja.', 8),
(432, 28, 203, 'e2_n3_s1', 'Dan nama negeri ini pula? Perkataan Siam \'phrau loi\', iaitu kelapa hanyut.', 9),
(433, NULL, 203, 'e2_n3_s1', 'Sudah lengkap! Dakwat pun hampir kering, tetapi hati saya penuh.', 10),
(434, 28, 203, 'e2_n3_s1', 'Itu sahaja untuk Perlis, pengembara! Isi buku catatan sampai penuh, sawah ini jadi saksi.', 11),
(435, NULL, 203, 'e2_n3_s2', 'Hamparan sawah padi berkilau di bawah langit senja. Bendera Kedah berkibar di hujung tiang, jata negeri terpampang pada rumah besar, dan alat muzik di beranda mengalunkan lagu negeri.', 1),
(436, 28, 203, 'e2_n3_s2', 'Pengembara! Sudah jauh berjalan ke Kedah? Duduk, duduk! Anda mencari ibu negeri Kedah, kan? Tahu jawapannya?', 2),
(437, NULL, 203, 'e2_n3_s2', 'Belum lagi, saya baru tiba! Tolong beritahu, saya sudah sedia mencatat.', 3),
(438, 28, 203, 'e2_n3_s2', 'Ini jawapannya! Ibu negerinya Alor Setar, dan bandar dirajanya Anak Bukit.', 4),
(439, NULL, 203, 'e2_n3_s2', 'Eh, lagu apa pula itu? Radio itu seolah-olah mahu menyampuk!', 5),
(440, 28, 203, 'e2_n3_s2', 'Lagu negerinya ialah \'Allah Selamatkan Sultan Mahkota\'.', 6),
(441, NULL, 203, 'e2_n3_s2', 'Dua soalan lagi sebelum dakwat habis: siapakah ketua negeri ini, dan dari mana nama negerinya?', 7),
(442, 28, 203, 'e2_n3_s2', 'Ketua negeri Kedah bergelar Sultan.', 8),
(443, 28, 203, 'e2_n3_s2', 'Dan nama negeri ini pula? Perkataan \'Kheddah\', iaitu perangkap gajah.', 9),
(444, NULL, 203, 'e2_n3_s2', 'Habis catatan! Perjalanan ini bernilai setiap langkah.', 10),
(445, 28, 203, 'e2_n3_s2', 'Sudah lengkap catatan Kedah, pengembara! Bawa bersama semangat sawah ini.', 11),
(446, NULL, 203, 'e2_n3_s3', 'Bau garam dan angin laut singgah di jeti yang sibuk. Bendera Pulau Pinang berkibar di jeti, jata negeri terpampang pada gerbang batu, dan gramofon di tepi laut mengalunkan lagu negeri.', 1),
(447, 30, 203, 'e2_n3_s3', 'Pengembara! Cepat, bot sudah berbunyi! Anda mencari ibu negeri Pulau Pinang, kan? Sudah tahu jawapannya?', 2),
(448, NULL, 203, 'e2_n3_s3', 'Tidak tahu langsung! Sebab itulah saya datang. Mulakan, saya mencatat!', 3),
(449, 30, 203, 'e2_n3_s3', 'Pena sudah sedia, bukan? Ibu negerinya Georgetown.', 4),
(450, NULL, 203, 'e2_n3_s3', 'Telinga saya tertarik pada radio itu. Lagu negeri apakah itu?', 5),
(451, 30, 203, 'e2_n3_s3', 'Lagu negerinya ialah \'Untuk Negeri Kita\'.', 6),
(452, NULL, 203, 'e2_n3_s3', 'Soalan terakhir, tetapi besar: gelaran ketua negerinya dan asal usul namanya?', 7),
(453, 30, 203, 'e2_n3_s3', 'Ketua negeri Pulau Pinang bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 8),
(454, 30, 203, 'e2_n3_s3', 'Dan nama negeri ini pula? Pokok pinang yang banyak tumbuh di pulau itu.', 9),
(455, NULL, 203, 'e2_n3_s3', 'Selesai! Saya akan baca catatan ini kepada setiap orang yang saya jumpa.', 10),
(456, 30, 203, 'e2_n3_s3', 'Selesai catatan Pulau Pinang! Cepat naik bot, pengembara, kalau tidak anda tertinggal!', 11),
(457, NULL, 203, 'e2_n3_s4', 'Cahaya petang menyuluh halaman yang bersih disapu. Bendera Perak berkibar di tiang, jata negeri terpampang pada ukiran rumah, dan gramofon di atas meja mengalunkan lagu negeri.', 1),
(458, 32, 203, 'e2_n3_s4', 'Pengembara! Cahaya petang pun seakan mahu mencatat sama. Anda mencari ibu negeri Perak, ya? Sudah tahu jawapannya?', 2),
(459, NULL, 203, 'e2_n3_s4', 'Belum! Tetapi pena sudah tajam dan buku catatan terbuka lebar. Ceritakanlah!', 3),
(460, 32, 203, 'e2_n3_s4', 'Catatlah! Ibu negerinya Ipoh, dan bandar dirajanya Kuala Kangsar.', 4),
(461, NULL, 203, 'e2_n3_s4', 'Dan radio itu berbunyi sendiri! Lagu negeri apakah yang berkumandang itu?', 5),
(462, 32, 203, 'e2_n3_s4', 'Lagu negerinya ialah \'Allah Lanjutkan Usia Sultan\'.', 6),
(463, NULL, 203, 'e2_n3_s4', 'Satu lagi untuk buku catatan: siapakah ketua negerinya, dan dari mana nama negeri ini bermula?', 7),
(464, 32, 203, 'e2_n3_s4', 'Ketua negeri Perak bergelar Sultan. Takhtanya berpindah secara bergilir mengikut sistem penggiliran yang unik.', 8),
(465, 32, 203, 'e2_n3_s4', 'Dan nama negeri ini pula? Kilatan ikan atau bijih timah putih yang berkilat seperti perak.', 9),
(466, NULL, 203, 'e2_n3_s4', 'Sudah lengkap! Dakwat pun hampir kering, tetapi hati saya penuh.', 10),
(467, 32, 203, 'e2_n3_s4', 'Catatan Perak sudah lengkap, pengembara! Nenek-nenek di sini ikut berbangga.', 11),
(468, NULL, 203, 'e2_n3_s5', 'Air sungai mengalir tenang dan burung berkicau di tebing. Bendera Selangor berkibar di tiang, jata negeri terpampang pada pintu gerbang rumah, dan gramofon di atas meja mengalunkan lagu negeri.', 1),
(469, 30, 203, 'e2_n3_s5', 'Pengembara! Burung pun berhenti berkicau mahu dengar. Anda mencari ibu negeri Selangor, kan? Sudah tahu jawapannya?', 2),
(470, NULL, 203, 'e2_n3_s5', 'Belum lagi, saya baru tiba! Tolong beritahu, saya sudah sedia mencatat.', 3),
(471, 30, 203, 'e2_n3_s5', 'Ini jawapannya! Ibu negerinya Shah Alam, dan bandar dirajanya Klang.', 4),
(472, NULL, 203, 'e2_n3_s5', 'Eh, lagu apa pula itu? Radio itu seolah-olah mahu menyampuk!', 5),
(473, 30, 203, 'e2_n3_s5', 'Lagu negerinya ialah \'Duli Yang Maha Mulia\'.', 6),
(474, NULL, 203, 'e2_n3_s5', 'Dua soalan lagi sebelum dakwat habis: siapakah ketua negeri ini, dan dari mana nama negerinya?', 7),
(475, 30, 203, 'e2_n3_s5', 'Ketua negeri Selangor bergelar Sultan.', 8),
(476, 30, 203, 'e2_n3_s5', 'Dan nama negeri ini pula? Sungai Selangor, pokok mentagau atau serangga selangur.', 9),
(477, NULL, 203, 'e2_n3_s5', 'Habis catatan! Perjalanan ini bernilai setiap langkah.', 10),
(478, 30, 203, 'e2_n3_s5', 'Selesai Selangor! Pena anda pasti sudah penat, pengembara. Rehat di tebing sungai sebentar.', 11),
(479, NULL, 203, 'e2_n3_s6', 'Bumbung bergonjong rumah adat tegak di hujung halaman. Bendera Negeri Sembilan berkibar di tiang, jata negeri terpampang pada pintu pagar, dan gramofon di halaman mengalunkan lagu negeri.', 1),
(480, 32, 203, 'e2_n3_s6', 'Pengembara! Naiklah ke halaman rumah adat ini. Anda mencari ibu negeri Negeri Sembilan, ya? Sudah tahu jawapannya?', 2),
(481, NULL, 203, 'e2_n3_s6', 'Tidak tahu langsung! Sebab itulah saya datang. Mulakan, saya mencatat!', 3),
(482, 32, 203, 'e2_n3_s6', 'Pena sudah sedia, bukan? Ibu negerinya Seremban, dan bandar dirajanya Seri Menanti.', 4),
(483, NULL, 203, 'e2_n3_s6', 'Telinga saya tertarik pada radio itu. Lagu negeri apakah itu?', 5),
(484, 32, 203, 'e2_n3_s6', 'Lagu negerinya ialah \'Berkatlah Yang di-Pertuan Besar\'.', 6),
(485, NULL, 203, 'e2_n3_s6', 'Soalan terakhir, tetapi besar: gelaran ketua negerinya dan asal usul namanya?', 7),
(486, 32, 203, 'e2_n3_s6', 'Ketua negeri Negeri Sembilan bergelar Yang di-Pertuan Besar. Beliau dipilih oleh Undang Yang Empat.', 8),
(487, 32, 203, 'e2_n3_s6', 'Dan nama negeri ini pula? Penyatuan sembilan luak asal, dan \'nagari\' bermaksud wilayah.', 9),
(488, NULL, 203, 'e2_n3_s6', 'Selesai! Saya akan baca catatan ini kepada setiap orang yang saya jumpa.', 10),
(489, 32, 203, 'e2_n3_s6', 'Beres untuk Negeri Sembilan, pengembara! Bumbung gonjong ini sudah menyaksikan semuanya.', 11),
(490, NULL, 203, 'e2_n3_s7', 'Bunyi sungai dan bayangan kubu lama menyambut pagi. Bendera Melaka berkibar di atas kubu, jata negeri terpampang pada papan kayu, dan gambus di atas tugu mengalunkan lagu negeri.', 1),
(491, 30, 203, 'e2_n3_s7', 'Pengembara! Selamat datang ke bumi bersejarah. Anda mencari ibu negeri Melaka, kan? Sudah tahu jawapannya?', 2),
(492, NULL, 203, 'e2_n3_s7', 'Belum! Tetapi pena sudah tajam dan buku catatan terbuka lebar. Ceritakanlah!', 3),
(493, 30, 203, 'e2_n3_s7', 'Catatlah! Ibu negerinya Bandar Melaka.', 4),
(494, NULL, 203, 'e2_n3_s7', 'Dan radio itu berbunyi sendiri! Lagu negeri apakah yang berkumandang itu?', 5),
(495, 30, 203, 'e2_n3_s7', 'Lagu negerinya ialah \'Melaka Maju Jaya\'.', 6),
(496, NULL, 203, 'e2_n3_s7', 'Satu lagi untuk buku catatan: siapakah ketua negerinya, dan dari mana nama negeri ini bermula?', 7),
(497, 30, 203, 'e2_n3_s7', 'Ketua negeri Melaka bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 8),
(498, 30, 203, 'e2_n3_s7', 'Dan nama negeri ini pula? Pokok Melaka tempat Parameswara berehat.', 9),
(499, NULL, 203, 'e2_n3_s7', 'Sudah lengkap! Dakwat pun hampir kering, tetapi hati saya penuh.', 10),
(500, 30, 203, 'e2_n3_s7', 'Selesai Melaka! Sungai ini sudah menyimpan banyak catatan, kini giliran buku anda.', 11),
(501, NULL, 203, 'e2_n3_s8', 'Angin petang menyapu permukaan sungai yang berkilat. Bendera Johor berkibar di tepi sungai, jata negeri terpampang pada pintu gerbang, dan gramofon di kedai kopi mengalunkan lagu negeri.', 1),
(502, 30, 203, 'e2_n3_s8', 'Pengembara! Duduk dahulu di tepi sungai. Anda mencari ibu negeri Johor, bukan? Sudah tahu jawapannya?', 2),
(503, NULL, 203, 'e2_n3_s8', 'Belum lagi, saya baru tiba! Tolong beritahu, saya sudah sedia mencatat.', 3),
(504, 30, 203, 'e2_n3_s8', 'Ini jawapannya! Ibu negerinya Johor Bahru, dan bandar dirajanya Bandar Maharani.', 4),
(505, NULL, 203, 'e2_n3_s8', 'Eh, lagu apa pula itu? Radio itu seolah-olah mahu menyampuk!', 5),
(506, 30, 203, 'e2_n3_s8', 'Lagu negerinya ialah \'Lagu Bangsa Johor\'.', 6),
(507, NULL, 203, 'e2_n3_s8', 'Dua soalan lagi sebelum dakwat habis: siapakah ketua negeri ini, dan dari mana nama negerinya?', 7),
(508, 30, 203, 'e2_n3_s8', 'Ketua negeri Johor bergelar Sultan.', 8),
(509, 30, 203, 'e2_n3_s8', 'Dan nama negeri ini pula? Perkataan Arab \'Jauhar\', iaitu batu permata bernilai.', 9),
(510, NULL, 203, 'e2_n3_s8', 'Habis catatan! Perjalanan ini bernilai setiap langkah.', 10),
(511, 30, 203, 'e2_n3_s8', 'Lengkap catatan Johor, pengembara! Berkilau seperti batu permata yang dikatakan itu.', 11),
(512, NULL, 203, 'e2_n3_s9', 'Kabus nipis naik dari sungai dan hutan di seberang. Bendera Pahang berkibar di tepi sungai, jata negeri terpampang pada rumah besar, dan radio di atas meja kayu mengalunkan lagu negeri.', 1),
(513, 29, 203, 'e2_n3_s9', 'Pengembara! Kabus ini pandai menyembunyikan jalan. Anda mencari ibu negeri Pahang, kan? Sudah tahu jawapannya?', 2),
(514, NULL, 203, 'e2_n3_s9', 'Tidak tahu langsung! Sebab itulah saya datang. Mulakan, saya mencatat!', 3),
(515, 29, 203, 'e2_n3_s9', 'Pena sudah sedia, bukan? Ibu negerinya Kuantan, dan bandar dirajanya Pekan.', 4),
(516, NULL, 203, 'e2_n3_s9', 'Telinga saya tertarik pada radio itu. Lagu negeri apakah itu?', 5),
(517, 29, 203, 'e2_n3_s9', 'Lagu negerinya ialah \'Allah Selamatkan Sultan Kami\'.', 6),
(518, NULL, 203, 'e2_n3_s9', 'Soalan terakhir, tetapi besar: gelaran ketua negerinya dan asal usul namanya?', 7),
(519, 29, 203, 'e2_n3_s9', 'Ketua negeri Pahang bergelar Sultan.', 8),
(520, 29, 203, 'e2_n3_s9', 'Dan nama negeri ini pula? Pokok mahang, juga dikenali sebagai Inderapura.', 9),
(521, NULL, 203, 'e2_n3_s9', 'Selesai! Saya akan baca catatan ini kepada setiap orang yang saya jumpa.', 10),
(522, 29, 203, 'e2_n3_s9', 'Selesai Pahang! Buku catatan anda kini lebih berat daripada beg galas, bukan?', 11),
(523, NULL, 203, 'e2_n3_s10', 'Ombak berbuih memukul pantai dan layang-layang camar berputar. Bendera Terengganu berkibar di tepi pantai, jata negeri terpampang pada dinding rumah, dan alat muzik di beranda mengalunkan lagu negeri.', 1),
(524, 27, 203, 'e2_n3_s10', 'Pengembara! Ombak pun macam mahu mengintai buku catatan anda. Anda mencari ibu negeri Terengganu, ya? Sudah tahu jawapannya?', 2),
(525, NULL, 203, 'e2_n3_s10', 'Belum! Tetapi pena sudah tajam dan buku catatan terbuka lebar. Ceritakanlah!', 3),
(526, 27, 203, 'e2_n3_s10', 'Catatlah! Ibu negerinya Kuala Terengganu.', 4),
(527, NULL, 203, 'e2_n3_s10', 'Dan radio itu berbunyi sendiri! Lagu negeri apakah yang berkumandang itu?', 5),
(528, 27, 203, 'e2_n3_s10', 'Lagu negerinya ialah \'Selamat Sultan\'.', 6),
(529, NULL, 203, 'e2_n3_s10', 'Satu lagi untuk buku catatan: siapakah ketua negerinya, dan dari mana nama negeri ini bermula?', 7),
(530, 27, 203, 'e2_n3_s10', 'Ketua negeri Terengganu bergelar Sultan.', 8),
(531, 27, 203, 'e2_n3_s10', 'Dan nama negeri ini pula? \'Taring anu\' (taring binatang liar) atau \'terang ganu\' (pelangi).', 9),
(532, NULL, 203, 'e2_n3_s10', 'Sudah lengkap! Dakwat pun hampir kering, tetapi hati saya penuh.', 10),
(533, 27, 203, 'e2_n3_s10', 'Lengkap Terengganu! Biar ombak yang memadam jejak kaki, tapi catatan anda kekal.', 11),
(534, NULL, 203, 'e2_n3_s11', 'Ukiran kayu berkilat di rumah tua yang harum dengan bunga. Bendera Kelantan berkibar di tiang, jata negeri terpampang pada gerbang rumah, dan rebana dan serunai di atas meja mengalunkan lagu negeri.', 1),
(535, 32, 203, 'e2_n3_s11', 'Pengembara! Rumah ukiran ini sudah lama menanti tetamu. Anda mencari ibu negeri Kelantan, kan? Sudah tahu jawapannya?', 2),
(536, NULL, 203, 'e2_n3_s11', 'Belum lagi, saya baru tiba! Tolong beritahu, saya sudah sedia mencatat.', 3),
(537, 32, 203, 'e2_n3_s11', 'Ini jawapannya! Ibu negerinya Kota Bharu.', 4),
(538, NULL, 203, 'e2_n3_s11', 'Eh, lagu apa pula itu? Radio itu seolah-olah mahu menyampuk!', 5),
(539, 32, 203, 'e2_n3_s11', 'Lagu negerinya ialah \'Selamat Sultan\'.', 6),
(540, NULL, 203, 'e2_n3_s11', 'Dua soalan lagi sebelum dakwat habis: siapakah ketua negeri ini, dan dari mana nama negerinya?', 7),
(541, 32, 203, 'e2_n3_s11', 'Ketua negeri Kelantan bergelar Sultan.', 8),
(542, 32, 203, 'e2_n3_s11', 'Dan nama negeri ini pula? Kilatan cahaya terang atau pokok gelam hutan.', 9),
(543, NULL, 203, 'e2_n3_s11', 'Habis catatan! Perjalanan ini bernilai setiap langkah.', 10),
(544, 32, 203, 'e2_n3_s11', 'Selesai Kelantan, pengembara! Ukiran kayu ini pun macam tersenyum melihat catatan anda.', 11),
(545, NULL, 203, 'e2_n3_s12', 'Angin teluk berhembus sambil gong kecil berdenting jauh. Bendera Sabah berkibar di tiang, jata negeri terpampang pada bangunan batu, dan alat muzik di pondok mengalunkan lagu negeri.', 1),
(546, 33, 203, 'e2_n3_s12', 'Pengembara! Angin teluk bawa khabar Anda tiba. Anda mencari ibu negeri Sabah, kan? Sudah tahu jawapannya?', 2),
(547, NULL, 203, 'e2_n3_s12', 'Tidak tahu langsung! Sebab itulah saya datang. Mulakan, saya mencatat!', 3),
(548, 33, 203, 'e2_n3_s12', 'Pena sudah sedia, bukan? Ibu negerinya Kota Kinabalu.', 4),
(549, NULL, 203, 'e2_n3_s12', 'Telinga saya tertarik pada radio itu. Lagu negeri apakah itu?', 5),
(550, 33, 203, 'e2_n3_s12', 'Lagu negerinya ialah \'Sabah Tanah Airku\'.', 6),
(551, NULL, 203, 'e2_n3_s12', 'Soalan terakhir, tetapi besar: gelaran ketua negerinya dan asal usul namanya?', 7),
(552, 33, 203, 'e2_n3_s12', 'Ketua negeri Sabah bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 8),
(553, 33, 203, 'e2_n3_s12', 'Dan nama negeri ini pula? Sejenis pisang, iaitu pisang saba atau pisang jaba.', 9),
(554, NULL, 203, 'e2_n3_s12', 'Selesai! Saya akan baca catatan ini kepada setiap orang yang saya jumpa.', 10),
(555, 33, 203, 'e2_n3_s12', 'Selesai Sabah! Gong kecil itu berdenting kerana gembira, pengembara.', 11),
(556, NULL, 203, 'e2_n3_s13', 'Air sungai berwarna teh mengalir lambat di bawah tebing. Bendera Sarawak berkibar tinggi, jata negeri terpampang pada pintu gerbang, dan alat muzik di atas tugu mengalunkan lagu negeri.', 1),
(557, 34, 203, 'e2_n3_s13', 'Pengembara! Naik sampan, sampai sini jauh juga. Anda mencari ibu negeri Sarawak, kan? Sudah tahu jawapannya?', 2),
(558, NULL, 203, 'e2_n3_s13', 'Belum! Tetapi pena sudah tajam dan buku catatan terbuka lebar. Ceritakanlah!', 3),
(559, 34, 203, 'e2_n3_s13', 'Catatlah! Ibu negerinya Kuching.', 4),
(560, NULL, 203, 'e2_n3_s13', 'Dan radio itu berbunyi sendiri! Lagu negeri apakah yang berkumandang itu?', 5),
(561, 34, 203, 'e2_n3_s13', 'Lagu negerinya ialah \'Ibu Pertiwiku\'.', 6),
(562, NULL, 203, 'e2_n3_s13', 'Satu lagi untuk buku catatan: siapakah ketua negerinya, dan dari mana nama negeri ini bermula?', 7),
(563, 34, 203, 'e2_n3_s13', 'Ketua negeri Sarawak bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 8),
(564, 34, 203, 'e2_n3_s13', 'Dan nama negeri ini pula? Sungai Sarawak, logam antimoni (cerava) atau \'serah kepada awak\'.', 9),
(565, NULL, 203, 'e2_n3_s13', 'Sudah lengkap! Dakwat pun hampir kering, tetapi hati saya penuh.', 10),
(566, 34, 203, 'e2_n3_s13', 'Selesai Sarawak, pengembara! Sungai ini sudah menyimpan banyak cerita, kini buku anda pula.', 11),
(567, NULL, 203, 'e2_n3_s14', 'Lampu bandar menyala dan bunyi trafik bersahut-sahutan. Bendera Wilayah Persekutuan berkibar di tiang, jata negeri terpampang pada gerbang batu, dan gramofon di atas tugu mengalunkan lagu negeri.', 1),
(568, 38, 203, 'e2_n3_s14', 'Pengembara! Bunyi trafik pun macam sorak sambutan. Anda mencari lagu negeri Wilayah Persekutuan, kan? Sudah tahu jawapannya?', 2),
(569, NULL, 203, 'e2_n3_s14', 'Belum lagi, saya baru tiba! Tolong beritahu, saya sudah sedia mencatat.', 3),
(570, 38, 203, 'e2_n3_s14', 'Mari mulakan dengan lagu. Lagu negerinya ialah \'Maju dan Sejahtera\'.', 4),
(571, NULL, 203, 'e2_n3_s14', 'Dan ibu negerinya pula, adakah ada?', 5),
(572, 38, 203, 'e2_n3_s14', 'Wilayah Persekutuan tidak mempunyai ibu negeri tersendiri; ketiga-tiganya ialah Kuala Lumpur, Labuan dan Putrajaya.', 6),
(573, NULL, 203, 'e2_n3_s14', 'Dua soalan lagi sebelum dakwat habis: siapakah ketua negeri ini, dan dari mana nama negerinya?', 7),
(574, 38, 203, 'e2_n3_s14', 'Ketua negeri bagi tiga Wilayah Persekutuan ialah Yang di-Pertuan Agong.', 8),
(575, 38, 203, 'e2_n3_s14', 'Dan nama negeri ini pula? Muara berlumpur (KL), labuhan (Labuan), sempena Tunku (Putrajaya).', 9),
(576, NULL, 203, 'e2_n3_s14', 'Habis catatan! Perjalanan ini bernilai setiap langkah.', 10),
(577, 38, 203, 'e2_n3_s14', 'Selesai Wilayah Persekutuan! Buku catatan anda kini lengkap, tahniah pengembara!', 11),
(578, 5, 301, NULL, 'Tugasku sebagai Pengarah MAGERAN ialah memulihkan ketenteraman dan menyediakan asas supaya rakyat berbilang kaum bersatu semula. Rukun Negara ialah panduan bersama itu. Jika aku gagal, luka lama terbuka semula, {nama}.', 1),
(579, 5, 301, NULL, 'Perpaduan tidak lahir daripada paksaan. Ia tumbuh apabila setiap rakyat berpegang pada prinsip yang sama.', 2),
(580, 5, 301, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, Pengarah MAGERAN. Negara sedang bangkit selepas Mei 1969, dan setiap arahan kau akan didengar seluruh rakyat. Tarik nafas dalam-dalam, misi bermula sekarang!', 3),
(581, 42, 301, 'e3_n1_s1', 'Tun Pengarah! Radio berbunyi KRRR-KRRR sejak subuh, tetapi tiada yang lebih mustahak daripada misi ini: kita mesti ingat bagaimana semuanya bermula!', 1),
(582, NULL, 301, 'e3_n1_s1', 'Tenang, Leftenan. Satu demi satu, macam menyusun kepingan teka-teki.', 2),
(583, 43, 301, 'e3_n1_s1', 'Fail ringkas siap, Tun! Rusuhan kaum 13 Mei 1969, kemudian MAGERAN mentadbir negara. Jadi, Tun, apakah urutan penuh sehingga Rukun Negara lahir?', 3),
(584, 42, 301, 'e3_n1_s1', 'Jawatankuasa Rukun Negara bekerja di bawah MAPEN, dan 4 Mac 1970 Rukun Negara dirangka dan diperkenalkan. Ia diisytiharkan pada 31 Ogos 1970. Mantap!', 4),
(585, NULL, 301, 'e3_n1_s1', 'Bagus. Setiap tarikh ialah satu langkah ke arah negara yang lebih bersatu.', 5),
(586, 45, 301, 'e3_n1_s2', 'Selamat pagi, Tun! Saya Pak Tani. Kami tanam padi untuk makan sendiri, jadi sawah ialah \'bank\' kami. Rumah pun di kampung, jauh dari bandar!', 1),
(587, 44, 301, 'e3_n1_s2', 'Ha, saya Tauke Lim, Tun! Kami buka kedai di bandar dari subuh sampai malam, ada juga yang melombong. Jual beli, itulah \'combo\' kami!', 2),
(588, 46, 301, 'e3_n1_s2', 'Saya Muthu, Tun. Menoreh getah sebelum matahari naik! Rumah kami pun di dalam ladang, bukan di bandar.', 3),
(589, 45, 301, 'e3_n1_s2', 'Bila jarang bertemu, mudah salah sangka, Tun. Tambah lagi bila fahaman politik berbeza, suhu pun naik sehingga 13 Mei 1969. Tun, apakah sebab semua ini berlaku?', 4),
(590, NULL, 301, 'e3_n1_s2', 'Aku dengar, Pak Tani. Kerja, tempat tinggal dan fahaman yang berbeza menjauhkan kita. Itulah sebab Rukun Negara diperkenalkan, untuk mengukuhkan perpaduan dan semangat kekitaan.', 5),
(591, 51, 301, 'e3_n1_s3', 'Tun! Anak saya bertanya apa itu matlamat Rukun Negara. Saya jawab separuh sahaja. Tolong, kami perlukan senarai lengkap lima matlamat!', 1),
(592, 52, 301, 'e3_n1_s3', 'Betul, Tun! Cikgu kata ada lima, tetapi saya baru ingat dua. Mari kita buru satu per satu macam dalam permainan!', 2),
(593, NULL, 301, 'e3_n1_s3', 'Mudah. Satu: perpaduan yang lebih erat. Dua: cara hidup demokrasi. Tiga: masyarakat adil, kemakmuran dinikmati bersama. Empat: tradisi kebudayaan yang pelbagai. Lima: masyarakat progresif dengan sains dan teknologi moden.', 3),
(594, 51, 301, 'e3_n1_s3', 'Wah, bateri saya penuh! Tun, matlamat yang manakah menyebut sains dan teknologi moden?', 4),
(595, 50, 301, 'e3_n1_s4', 'Tun! Saya Hafiz, baru selesai solat. Di sebelah ada kuil, tokong dan gereja. Dulu saya hanya lalu sahaja, hari ini saya mahu faham!', 1),
(596, 48, 301, 'e3_n1_s4', 'Hehe, saya Mei Ling. Kami hafal ikrar yang bermula, \'Maka kami, rakyat Malaysia, berikrar...\' dan ada lima prinsip. Tun, ikrar itu \'power\' betul!', 2),
(597, NULL, 301, 'e3_n1_s4', 'Dengar baik-baik, ya. Prinsip pertama: Kepercayaan kepada Tuhan. Agama jadi pegangan utama, dan kita hormati amalan agama lain.', 3),
(598, 49, 301, 'e3_n1_s4', 'Saya Arun, Tun! Itu satu. Prinsip kedua pula?', 4),
(599, NULL, 301, 'e3_n1_s4', 'Kesetiaan kepada Raja dan Negara: taat setia kepada Yang di-Pertuan Agong, Ketua Utama Negara. Rakyat bersatu dan penuh semangat patriotik.', 5),
(600, 48, 301, 'e3_n1_s4', 'Cantik! Tun, kalau jiran kami berbeza agama, apakah yang patut kami buat berdasarkan prinsip pertama?', 6),
(601, 52, 301, 'e3_n1_s5', 'Tun! Cikgu kata Perlembagaan ialah \'bos terbesar\' semua undang-undang. Betulkah, Tun?', 1),
(602, NULL, 301, 'e3_n1_s5', 'Hampir tepat! Prinsip ketiga: Keluhuran Perlembagaan. Perlembagaan Persekutuan ialah undang-undang tertinggi negara, tiada institusi dapat mengatasinya, dan rakyat menerima, mematuhi serta mempertahankannya.', 2),
(603, 43, 301, 'e3_n1_s5', 'Prinsip keempat, Tun: Kedaulatan Undang-undang. Setiap rakyat menghormati dan mematuhi undang-undang untuk menjamin keharmonian dan keselamatan negara.', 3),
(604, 42, 301, 'e3_n1_s5', 'Dan prinsip kelima: Kesopanan dan Kesusilaan. Nilai murni, disiplin, akhlak mulia, saling memahami dan bekerjasama. Tiga prinsip siap, Tun!', 4),
(605, 52, 301, 'e3_n1_s5', 'Tun, kalau ada orang kata ada institusi yang boleh mengatasi Perlembagaan, prinsip yang manakah dilanggar?', 5),
(606, 51, 301, 'e3_n1_s6', 'Tun! Hari ini hari bersejarah, tetapi nota Tun basah terkena air! Tulisan pudar di sana-sini, macam peta harta karun!', 1),
(607, 50, 301, 'e3_n1_s6', 'Saya cuba baca, Tun, tetapi \'peranan\' yang terakhir hilang. Tolong nyahkodkan!', 2),
(608, NULL, 301, 'e3_n1_s6', 'Tak mengapa. Enam peranan Rukun Negara: meraikan kepelbagaian agama dan kepercayaan, membentuk masyarakat patriotik, memupuk hormat undang-undang, mengukuhkan perpaduan, menerapkan nilai murni, dan satu lagi yang pudar.', 3),
(609, 52, 301, 'e3_n1_s6', 'Satu lagi tu apa, Tun? Saya ada bisikan, katanya tentang identiti kita sebagai rakyat Malaysia!', 4),
(610, 41, 302, NULL, 'Tugasku ialah mendengar dan menenangkan rakyat pelbagai kaum, kemudian membawa suara mereka ke meja pemimpin supaya Rukun Negara dipegang bersama. Jika suara kecil tidak didengar, jurang bertambah dalam, {nama}.', 1),
(611, 41, 302, NULL, 'Perpaduan bermula apabila kita sanggup duduk dan mendengar orang yang berbeza daripada kita.', 2),
(612, 41, 302, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemimpin yang gemar mengetuk pintu rumah rakyat. Hari ini ada banyak kampung, ladang dan kedai untuk dilawati. Pakai kasut yang selesa, kita berjalan!', 3),
(613, 47, 302, 'e3_n2_s1', 'Tun! Wei Jie lapor diri! Kami sukarelawan satu pasukan: ada saya, Hafiz dan Arun. Plaster ada, air ada, semangat pun penuh!', 1),
(614, 50, 302, 'e3_n2_s1', 'Betul, Tun. Hafiz di sini. Tadi pegawai MAGERAN tinggalkan surat ini. Tulisannya agak berbelit.', 2),
(615, 49, 302, 'e3_n2_s1', 'Arun pula kata, Tun, surat itu sebut tentang majlis khas dan tarikh 4 Mac 1970. Siapa agaknya? Kami main teka-teki sejak pagi!', 3),
(616, NULL, 302, 'e3_n2_s1', 'Pegang dahulu. Selepas rusuhan 13 Mei 1969, negara ditadbir oleh satu majlis khas, kemudian Rukun Negara diisytiharkan pada 31 Ogos 1970.', 4),
(617, 47, 302, 'e3_n2_s1', 'Baik, Tun! Tolong nyahkodkan surat ini: siapakah yang mentadbir negara dan di bawah majlis apakah Rukun Negara dirangka?', 5),
(618, 46, 302, 'e3_n2_s2', 'Selamat pagi, Tun! Muthu di sini. Pukul lima pagi kami sudah menoreh, rumah kami pun di dalam ladang. Bandar? Hanya sebulan sekali!', 1),
(619, 45, 302, 'e3_n2_s2', 'Pak Tani pula, Tun. Kami Melayu tanam padi untuk makan sendiri. Rumah di kampung dan pedalaman. Sawah ialah restoran kami!', 2),
(620, 44, 302, 'e3_n2_s2', 'Dan kami di bandar, Tun! Lim buka kedai, ramai juga yang melombong. Jiran kami lain-lain kaum, tapi kami jarang makan semeja. Sayang, kan?', 3),
(621, NULL, 302, 'e3_n2_s2', 'Sayang sekali, Tauke. Kerja berbeza, tempat tinggal berbeza, lalu fahaman politik pun berbeza. Itu menegangkan hubungan sehingga tercetus rusuhan 13 Mei 1969.', 4),
(622, 46, 302, 'e3_n2_s2', 'Jadi apa gunanya Rukun Negara, Tun? Beritahu kami supaya kami boleh cerita pada anak-anak!', 5),
(623, 50, 302, 'e3_n2_s3', 'Tun, ramai orang di sini! Ada tarian singa, ada kompang, ada radio bergema. Ibu saya kata lima matlamat itu penting.', 1),
(624, 48, 302, 'e3_n2_s3', 'Betul, Tun! Kalau Tun ingat lima matlamat itu, \'bonus\' kami akan bertambah! Tarian singa pun menari lebih galak!', 2),
(625, NULL, 302, 'e3_n2_s3', 'Mari kita senaraikan: perpaduan yang lebih erat, cara hidup demokrasi, masyarakat adil dengan kemakmuran dinikmati bersama, cara liberal terhadap tradisi kebudayaan, dan masyarakat progresif dengan sains dan teknologi moden.', 3),
(626, 49, 302, 'e3_n2_s3', 'Wah! Tun, kemakmuran negara hendaklah dinikmati bagaimana, menurut matlamat itu?', 4),
(627, 51, 302, 'e3_n2_s4', 'Tun! Ini tempat paling riuh pagi ini. Tuan-tuan hendak ikrar? Ia bermula: \'Maka kami, rakyat Malaysia, berikrar...\'', 1),
(628, 52, 302, 'e3_n2_s4', 'Ada lima prinsip, Tun! Saya jumpa dua yang pertama! Tinggal kita cari lambangnya dalam gambar. Siapa cepat dia dapat!', 2),
(629, NULL, 302, 'e3_n2_s4', 'Prinsip pertama: Kepercayaan kepada Tuhan, agama jadi pegangan utama dan kita hormati amalan agama lain. Prinsip kedua: Kesetiaan kepada Raja dan Negara, taat setia kepada Yang di-Pertuan Agong.', 3),
(630, 51, 302, 'e3_n2_s4', 'Cantik, Tun! Tapi kenapa dua prinsip ini disebut dahulu? Apakah kesannya kepada masyarakat?', 4),
(631, 43, 302, 'e3_n2_s5', 'Tun! Petikan ini tertinggal di mesin taip, dan dakwatnya habis separuh jalan. Kita ada tiga prinsip yang perlu disambung.', 1),
(632, NULL, 302, 'e3_n2_s5', 'Prinsip ketiga: Keluhuran Perlembagaan. Perlembagaan Persekutuan ialah undang-undang tertinggi, tiada institusi dapat mengatasinya, dan rakyat menerima, mematuhi serta mempertahankannya.', 2),
(633, 42, 302, 'e3_n2_s5', 'Keempat, Tun: Kedaulatan Undang-undang. Rakyat menghormati dan mematuhi undang-undang untuk menjamin keharmonian dan keselamatan negara.', 3),
(634, 43, 302, 'e3_n2_s5', 'Kelima, Tun: Kesopanan dan Kesusilaan. Nilai murni, disiplin, akhlak mulia, saling memahami dan bekerjasama. Tapi bahagian akhir petikan hilang. Tolong sambung, Tun!', 4),
(635, 48, 302, 'e3_n2_s6', 'Tun! Saya Mei Ling. Cikgu minta saya senaraikan enam peranan Rukun Negara. Saya hanya ingat \'lima setengah\'!', 1),
(636, 50, 302, 'e3_n2_s6', 'Saya pula ingat \'enam, tetapi tertukar tempat\'. Tolong, Tun, kami mahu jawab betul-betul sebelum loceng berbunyi!', 2),
(637, NULL, 302, 'e3_n2_s6', 'Mudah. Satu: meraikan kepelbagaian agama dan kepercayaan. Dua: membentuk masyarakat patriotik. Tiga: memupuk hormat undang-undang. Empat: mengukuhkan perpaduan. Lima: menerapkan nilai murni. Enam: membentuk jati diri.', 3),
(638, 49, 302, 'e3_n2_s6', 'Wah, jelas! Tun, jika murid bertanya, \'Rukun Negara meraikan apa?\', apa jawapan Tun?', 4),
(639, 1, 303, NULL, 'Tugasku ialah memimpin rakyat berbilang kaum bangkit semula dengan lima prinsip yang sama-sama kami ikrarkan. Jika ikrar itu kosong, negara kembali bergolak, {nama}.', 1),
(640, 1, 303, NULL, 'Ikrar yang dipegang bersama menjadikan rakyat berbilang kaum satu keluarga.', 2),
(641, 1, 303, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, Perdana Menteri yang memikul luka negara selepas Mei 1969. Kau tidak berseorangan: rakyat dari kampung, bandar dan ladang menanti kata-katamu. Bersedia, ikrar akan bermula!', 3),
(642, 43, 303, 'e3_n3_s1', 'Tunku, selamat pagi! Kopi sudah sejuk, fail sudah setinggi menara, tetapi semangat kami masih menyala. Hari ini misi: ingat bagaimana Rukun Negara bermula!', 1),
(643, 42, 303, 'e3_n3_s1', 'Betul, Tunku. Selepas rusuhan 13 Mei 1969, MAGERAN mentadbir negara. Kemudian Jawatankuasa Rukun Negara di bawah MAPEN bekerja keras.', 2),
(644, NULL, 303, 'e3_n3_s1', 'Ah, anak-anakku, jangan tergesa-gesa. Rukun Negara dirangka dan diperkenalkan pada 4 Mac 1970, dan diisytiharkan pada 31 Ogos 1970.', 3),
(645, 43, 303, 'e3_n3_s1', 'Cantik, Tunku! Kalau wartawan bertanya macam mana Rukun Negara bermula, apa jawapan Tunku? Kami catat sampai tangan kebas!', 4),
(646, 44, 303, 'e3_n3_s2', 'Selamat pagi, Tunku! Tauke Lim di sini. Kedai saya buka awal, anak buah pun sudah kerja. Lombong pun bising sejak subuh. Bandar tak pernah tidur!', 1),
(647, 45, 303, 'e3_n3_s2', 'Pak Tani datang dari kampung, Tunku. Kami tanam padi untuk makan sendiri. Bandar ini jauh, kami jarang masuk.', 2),
(648, 46, 303, 'e3_n3_s2', 'Saya Muthu dari ladang getah, Tunku. Rumah kami pun dalam ladang. Bila nak ke bandar, kena tunggu lori!', 3),
(649, NULL, 303, 'e3_n3_s2', 'Anak-anakku, itulah yang menjadi masalah. Kerja berbeza, tempat tinggal berbeza, malah fahaman politik pun berbeza. Hubungan tegang sehingga 13 Mei 1969.', 4),
(650, 44, 303, 'e3_n3_s2', 'Tunku, ada catatan lama ini. Satu bahagian pudar. Tolong nyahkodkan: apakah tujuan utama Rukun Negara?', 5),
(651, 52, 303, 'e3_n3_s3', 'Tunku! Tarian singa itu \'power\'! Tapi cikgu kata ada lima matlamat Rukun Negara. Saya baru ingat tiga. Tolong, Tunku!', 1),
(652, 51, 303, 'e3_n3_s3', 'Hafiz dan Arun pun tak ingat, Tunku. Mari kita buat \'checklist\' macam dalam permainan!', 2),
(653, NULL, 303, 'e3_n3_s3', 'Mari, anak-anakku. Satu: perpaduan yang lebih erat. Dua: cara hidup demokrasi. Tiga: masyarakat adil dengan kemakmuran dinikmati bersama. Empat: cara liberal terhadap tradisi kebudayaan. Lima: masyarakat progresif dengan sains dan teknologi moden.', 3),
(654, 52, 303, 'e3_n3_s3', 'Wah! Tunku, kalau tarian singa dan alat muzik tradisional ini dihargai, matlamat yang manakah itu?', 4),
(655, 49, 303, 'e3_n3_s4', 'Tunku! Arun di sini. Dalam masa lima minit saya sudah melalui masjid, kuil, tokong dan gereja. Jiran-jiran kita memang meriah!', 1),
(656, 48, 303, 'e3_n3_s4', 'Betul, Tunku! Ikrar kita bermula: \'Maka kami, rakyat Malaysia, berikrar...\' kemudian lima prinsip. Dua yang pertama, apa dia, Tunku?', 2),
(657, NULL, 303, 'e3_n3_s4', 'Prinsip pertama: Kepercayaan kepada Tuhan, agama pegangan utama, kita hormati amalan agama lain dan rakyat bersatu. Prinsip kedua: Kesetiaan kepada Raja dan Negara, taat setia kepada Yang di-Pertuan Agong.', 3),
(658, 50, 303, 'e3_n3_s4', 'Dan petikan ini, Tunku, yang menyebut \'Ketua Utama Negara\', tulisannya pudar. Boleh nyahkodkan?', 4),
(659, 51, 303, 'e3_n3_s5', 'Tunku! Dataran ini macam permainan \'cari objek\'! Ada gulungan di batu, papan nama dan orang menanam pokok. Tiga prinsip, tiga bukti!', 1),
(660, 52, 303, 'e3_n3_s5', 'Cepat, Tunku! Ketiga: Keluhuran Perlembagaan. Keempat: Kedaulatan Undang-undang. Kelima: Kesopanan dan Kesusilaan. Saya jaga masa!', 2),
(661, NULL, 303, 'e3_n3_s5', 'Tenang, anak-anakku. Perlembagaan ialah undang-undang tertinggi dan tiada institusi mengatasinya. Undang-undang dipatuhi untuk keharmonian dan keselamatan. Nilai murni pula membentuk masyarakat berdisiplin dan bekerjasama.', 3),
(662, 51, 303, 'e3_n3_s5', 'Hebat, Tunku! Kalau nilai murni membuat masyarakat berdisiplin dan harmoni, apa yang rakyat patut lakukan sesama jiran?', 4),
(663, 52, 303, 'e3_n3_s6', 'Tunku! Cikgu minta contoh kehidupan untuk setiap peranan Rukun Negara. Enam semuanya! Kalau saya betul, saya dapat bintang emas!', 1),
(664, 51, 303, 'e3_n3_s6', 'Saya bantu, Tunku! Tapi saya cuma kenal tiga. Tolong beritahu semua peranan itu dahulu?', 2),
(665, NULL, 303, 'e3_n3_s6', 'Sabar, anak-anakku. Meraikan kepelbagaian agama dan kepercayaan, membentuk masyarakat patriotik, memupuk hormat undang-undang, mengukuhkan perpaduan, menerapkan nilai murni dan membentuk jati diri masyarakat Malaysia.', 3),
(666, 52, 303, 'e3_n3_s6', 'Wah, panjang tapi jelas! Tunku, bila jiran pelbagai kaum bergotong-royong membersihkan taman, peranan yang manakah itu?', 4),
(667, 61, 401, NULL, 'Tugasku ialah membawa rentak setiap kaum ke satu pentas supaya setiap bunyi dihargai. Jika pemuzik berhenti, lagu warisan itu hilang bersama orang tua, {nama}.', 1),
(668, 61, 401, NULL, 'Setiap kaum membawa rentak sendiri, dan lagu Malaysia hanya merdu apabila semua rentak dimainkan bersama.', 2),
(669, 61, 401, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemuzik tua yang membawa gambus, sape dan gendang dari kampung ke kampung. Rentak sudah bermula, jangan terlepas ketukan!', 3),
(670, 69, 401, 'e4_n1_s1', 'Pak Cik! Ah Meng lapor diri! Pentas penuh sesak dan setiap kaum bawa rentak sendiri. Tapi kami keliru: berapa banyak kaum sebenarnya? Misi hari ini: kenal semua!', 1),
(671, NULL, 401, 'e4_n1_s1', 'TUNG-TUNG-TUNG! Mulakan dengan Semenanjung: Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh dan Serani. Banyaknya, macam senarai lagu!', 2),
(672, 66, 401, 'e4_n1_s1', 'Linda dari Sabah pula, pak cik! Kami ada Kadazandusun, dan kaum lain seperti Murut, Rungus, Iranun dan Bajau.', 3),
(673, 67, 401, 'e4_n1_s1', 'Jenny dari Sarawak! Kami ada Iban, dan kaum lain seperti Melayu, Kenyah, Melanau dan Bidayuh. Pak cik, kaum yang manakah termasuk kaum lain di Sabah?', 4),
(674, 64, 401, 'e4_n1_s2', 'Pak Cik Pemuzik! Aishah di sini. Kampung kami di tepi pantai dan sungai. Ayah saya petani dan nelayan, emak berniaga kecil-kecilan. Ada juga yang makan gaji kerajaan!', 1),
(675, 69, 401, 'e4_n1_s2', 'Kalau saya, pak cik, keluarga Ah Meng di pekan dan bandar. Datuk melombong, ayah berniaga. Pekan pun bising dengan \'KLANG-KLANG\' dari kedai!', 2),
(676, 65, 401, 'e4_n1_s2', 'Kavitha pula tinggal di ladang dan pinggir bandar, pak cik. Ayah bekerja di ladang, ada juga yang jadi peniaga kecil dan pekerja pelabuhan.', 3),
(677, 70, 401, 'e4_n1_s2', 'Dan kami Orang Asli, anak. Kami di pedalaman, membuat kraf tangan, berburu dan memungut hasil hutan. Pak Cik, kaum yang manakah tinggal di pekan dan bandar, dan kerja mereka apa?', 4),
(678, 68, 401, 'e4_n1_s3', 'Selamat datang, pemuzik! Apai ini orang Iban, kami di lembah sungai dan bertani. Dayung perlahan, nanti perahu kita ikut rentak sape!', 1),
(679, 67, 401, 'e4_n1_s3', 'Jenny tolong cerita, pak cik. Kaum Bidayuh, Kenyah dan Kelabit di pedalaman. Mereka tanam padi sawah dan padi bukit, juga mengutip hasil hutan.', 2),
(680, NULL, 401, 'e4_n1_s3', 'Wah! Dan di pekan dan bandar pula Melayu, Melanau dan Kedayan. Mereka pedagang, pembuat perahu dan pengusaha sagu. Iban dan Bisaya di lembah sungai, bertani.', 3),
(681, 68, 401, 'e4_n1_s3', 'Kini, selepas merdeka dan pembentukan Malaysia, hasil kerja keras pemimpin dan sikap toleransi, semua kaum bekerja bersama dan tinggal dalam satu kawasan perumahan. Pak Cik, nyahkod nota lama ini!', 4),
(682, 65, 401, 'e4_n1_s4', 'Pak Cik! Kavitha lapor diri! Pentas India saya baru siap. Veenai, mattalam dan talam sudah sedia, dan tarian bharatanatyam akan bermula, TING-TING!', 1),
(683, 69, 401, 'e4_n1_s4', 'Hampir, pak cik! Pentas Cina ada gendang, bo, liu qin dan seruling. Tarian singa mesti menari dahulu, nanti singa merajuk!', 2),
(684, NULL, 401, 'e4_n1_s4', 'Melayu pula: angklung, gambus, nafiri dan geduk, dengan tarian makyung dan zapin. Sarawak: sape, engkerurai, engkerumong dengan tarian ngajat. Sabah: kulintangan, sompotan, tongkungan, tontog dengan tarian sumazau.', 3),
(685, 66, 401, 'e4_n1_s4', 'Wah! Pak cik, tarian sumazau itu dari pentas kaum yang manakah?', 4),
(686, 74, 401, 'e4_n1_s5', 'Pak Cik! Cikgu kata ada tiga jenis tempat permainan tradisional: anjung, laman dan kawasan lapang. Apa dalam setiap satu? Saya hendak menang pertandingan!', 1),
(687, NULL, 401, 'e4_n1_s5', 'Anjung dahulu, ya: congkak, batu seremban, go atau weiqi, yoyo cina atau diabolo, chaturangam dan paramapadham. Rentak perlahan, macam duduk bersila.', 2),
(688, 69, 401, 'e4_n1_s5', 'Laman pula, pak cik? Sepak raga, chap teh dan kabaddi! Ah Meng sudah pecah peluh, hehe.', 3),
(689, NULL, 401, 'e4_n1_s5', 'Dan kawasan lapang: wau, tibau, sepak manggis dan gasing. Wau terbang tinggi, gasing berpusing laju.', 4),
(690, 74, 401, 'e4_n1_s5', 'Hebat! Pak Cik, jika saya mahu bermain wau, di manakah tempat yang paling sesuai?', 5),
(691, 72, 401, 'e4_n1_s6', 'Hehe, pemuzik! Aku Si Luncai! Raja menghukum aku kerana mempermain-mainkan baginda dan pembesar. Mereka masukkan aku ke dalam guni, letak atas perahu ke tengah laut! GLUP-GLUP!', 1),
(692, NULL, 401, 'e4_n1_s6', 'Wah, Luncai! Kau menipu pesuruh raja dengan lagu: \'Si Luncai terjun dengan labu-labunya. Biarkan! Biarkan!\' Mereka pun leka menyanyi, hehe!', 2),
(693, 73, 401, 'e4_n1_s6', 'Aku Puteri Santubong, pemuzik. Aku menenun, Puteri Sejinjang menumbuk padi. Kami diturunkan dari kayangan untuk mendamaikan kampung Pasir Kuning dan Pasir Putih.', 3),
(694, 73, 401, 'e4_n1_s6', 'Tapi kami berebut Putera Serapi dari Matang lalu bertelingkah. Antan terkena pipiku, Gunung Santubong sumbing. Batang belidah terkena kepala Sejinjang, lalu jadi Pulau Kera, Satang dan Talang-talang.', 4),
(695, 66, 401, 'e4_n1_s6', 'Nunuk Ragang pula cerita Sabah, pak cik! Penduduk Sungai Liwagu berehat di bawah pohon nunuk. Ayam gergasi merah bertaji emas membawa mereka terbang. Di mana sayap dikibar, di situ mereka jatuh.', 5),
(696, 66, 401, 'e4_n1_s6', 'Di situ mereka membina petempatan di Tambunan dan Ranau. Mereka terpisah lalu membina dialek masing-masing. Itulah asal pelbagai kaum di sana!', 6),
(697, 72, 401, 'e4_n1_s6', 'Eh, pemuzik! Tolong susun tipu helahku. Apa yang aku buat apabila pesuruh raja leka menyanyi?', 7),
(698, 62, 402, NULL, 'Tugasku ialah menurunkan cerita kaum supaya cucu mengenali jiran sendiri. Jika nenek berdiam diri, cerita itu hilang bersama usia, {nama}.', 1),
(699, 62, 402, NULL, 'Cerita setiap kaum ialah satu laci dalam peti yang sama, dan Malaysia lengkap apabila semua laci dibuka dan dikongsi.', 2),
(700, 62, 402, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, nenek yang menyimpan cerita semua kaum dalam peti lamanya. Cucu-cucu sudah duduk bersila, bukalah laci pertama!', 3),
(701, 74, 402, 'e4_n2_s1', 'Nenek! Nenek! Peti itu berkunci, tapi cikgu kata Malaysia ada banyak kaum! Berapa banyak, nenek? Kami mahu kad bergambar!', 1),
(702, NULL, 402, 'e4_n2_s1', 'Sabarlah, cucu! Laci pertama: Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh dan Serani. Sembilan kad untuk Semenanjung!', 2),
(703, 66, 402, 'e4_n2_s1', 'Nek, di Sabah ada Kadazandusun! Jiran saya Pak Bajau, jadi Bajau pun ada. Murut, Rungus dan Iranun juga kaum di Sabah!', 3),
(704, 67, 402, 'e4_n2_s1', 'Di Sarawak ada Iban, nek! Kawan saya orang Melayu, Kenyah, Melanau dan Bidayuh. Semua kaum Sarawak!', 4),
(705, 74, 402, 'e4_n2_s1', 'Hebat! Nenek, sekarang kami mahu padankan kad. Apakah kaum lain di Sabah dalam senarai nenek tadi?', 5),
(706, 64, 402, 'e4_n2_s2', 'Nenek! Aishah mahu tahu. Datuk kata kami orang Melayu dahulu tinggal di kampung, persisiran pantai dan sungai. Nenek, apa kerja kami?', 1),
(707, NULL, 402, 'e4_n2_s2', 'Petani, nelayan dan peniaga kecil-kecilan, cu. Ada juga yang berkhidmat dalam perkhidmatan awam. Bau laut dan bau padi bercampur, sedap!', 2);
INSERT INTO `DialogueLine` (`dialogueID`, `npcID`, `narrativeID`, `sceneID`, `dialogueLine`, `sequenceOrder`) VALUES
(708, 69, 402, 'e4_n2_s2', 'Nenek! Ah Meng pula? Datuk saya tinggal di pekan dan bandar. Dia pelombong, kemudian berniaga. Kedai kami bising dengan KLANG-KLANG timbangan!', 3),
(709, 65, 402, 'e4_n2_s2', 'Kavitha di ladang dan pinggir bandar, nek! Bapa bekerja di ladang, ada yang berniaga kecil dan bekerja di pelabuhan.', 4),
(710, 70, 402, 'e4_n2_s2', 'Kami Orang Asli di pedalaman. Kraf tangan, berburu dan memungut hasil hutan. Nenek, baca nota lama ini dahulu sebelum kami pulang ke hutan!', 5),
(711, 67, 402, 'e4_n2_s3', 'Nenek, Jenny pula! Kaum Bidayuh, Kenyah dan Kelabit tinggal di pedalaman. Mereka tanam padi sawah dan padi bukit, juga kutip hasil hutan!', 1),
(712, 68, 402, 'e4_n2_s3', 'Apai Iban beritahu. Iban dan Bisaya di lembah sungai, kami petani. Air sungai jadi jalan kami!', 2),
(713, NULL, 402, 'e4_n2_s3', 'Dan di pekan dan bandar: Melayu, Melanau dan Kedayan. Mereka pedagang, pembuat perahu dan pengusaha sagu. Pandai sungguh, macam kilang kecil!', 3),
(714, 67, 402, 'e4_n2_s3', 'Kini, nek? Kata cikgu, selepas merdeka dan pembentukan Malaysia, hasil kerja keras pemimpin dan sikap toleransi, rakyat bekerja bersama dan tinggal dalam satu kawasan perumahan!', 4),
(715, 68, 402, 'e4_n2_s3', 'Betul, nenek. Sekarang rumah jiran saya Cina, India, Melayu. Nenek, kaum manakah di lembah sungai dan apa kerjanya?', 5),
(716, 65, 402, 'e4_n2_s4', 'Nenek, Kavitha mahu menari bharatanatyam! Iringannya pullangkulal, talam, mattalam dan veenai. TING-TING-TING!', 1),
(717, 69, 402, 'e4_n2_s4', 'Ah Meng pun mahu, nek! Cina ada gendang, bo, liu qin dan seruling, dengan tarian singa. Singa saya pandai kenyit mata!', 2),
(718, NULL, 402, 'e4_n2_s4', 'Melayu: angklung, gambus, nafiri dan geduk, dengan makyung dan zapin. Sarawak: sape, engkerurai, engkerumong dengan ngajat. Sabah: kulintangan, sompotan, tongkungan, tontog dengan sumazau.', 3),
(719, 66, 402, 'e4_n2_s4', 'Nek, alat muzik sumazau di pentas Sabah ada sompotan dan kulintangan, kan? Nenek, padankan lima kaum dengan tarian mereka!', 4),
(720, 74, 402, 'e4_n2_s5', 'Nenek! Nenek! Dulu nenek main apa? Kami mahu main yang nenek main, tapi mesti betul tempatnya!', 1),
(721, NULL, 402, 'e4_n2_s5', 'Di anjung: congkak, batu seremban, go atau weiqi, yoyo cina atau diabolo, chaturangam dan paramapadham. Main sambil minum teh, hehe!', 2),
(722, 69, 402, 'e4_n2_s5', 'Di laman: sepak raga, chap teh dan kabaddi! Ah Meng jaguh kabaddi, tak ada siapa boleh tangkap!', 3),
(723, 63, 402, 'e4_n2_s5', 'Di kawasan lapang: wau, tibau, sepak manggis dan gasing. Tok Permainan datang, nek! Cuba cari permainan pada gambar padang ini!', 4),
(724, 72, 402, 'e4_n2_s6', 'Hehe, nenek! Aku Si Luncai, dihukum raja kerana mempermain-mainkan baginda. Aku dimasukkan dalam guni di atas perahu. Aku tipu pesuruh raja dengan lagu: \'Si Luncai terjun dengan labu-labunya, biarkan! biarkan!\'', 1),
(725, 72, 402, 'e4_n2_s6', 'Mereka leka menyanyi. Aku isi labu dalam guni, terjun dan berenang dengan labu air. Guni berisi labu itu mereka campak ke laut. Gempak, kan?', 2),
(726, 73, 402, 'e4_n2_s6', 'Aku Puteri Santubong, menenun. Sejinjang menumbuk padi. Kami turun dari kayangan untuk mendamaikan Pasir Kuning dan Pasir Putih. Tetapi kami menyukai Putera Serapi dari Matang lalu bertelingkah.', 3),
(727, 73, 402, 'e4_n2_s6', 'Antan terkena pipiku, Gunung Santubong sumbing. Batang belidah terkena kepala Sejinjang, lalu menjadi Pulau Kera, Pulau Satang dan Pulau Talang-talang.', 4),
(728, 66, 402, 'e4_n2_s6', 'Nunuk Ragang, nek! Penduduk Sungai Liwagu berehat di bawah pohon nunuk. Ayam gergasi merah bertaji emas membawa mereka terbang. Di mana sayap dikibar, di situ mereka jatuh dan bina petempatan di Tambunan dan Ranau.', 5),
(729, 66, 402, 'e4_n2_s6', 'Mereka terpisah dan membina dialek masing-masing. Nenek, baca teka-teki pada gulung Santubong ini!', 6),
(730, 63, 403, NULL, 'Tugasku ialah memastikan semua kaum bermain di gelanggang yang sama supaya warisan tidak padam. Jika gelanggang sunyi, permainan lama pun hilang, {nama}.', 1),
(731, 63, 403, NULL, 'Setiap kaum membawa permainan, muzik dan cerita sendiri ke gelanggang, dan Malaysia menang apabila semua bermain bersama.', 2),
(732, 63, 403, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penjaga gelanggang tempat semua kaum bermain bersama. Wisel sudah ditiup, pusingan pertama bermula!', 3),
(733, 69, 403, 'e4_n3_s1', 'Tok! Ah Meng daftar pasukan! Borang tanya kaum apa sahaja boleh masuk. Cepat, wisel tok sudah berbunyi, PEEEP!', 1),
(734, NULL, 403, 'e4_n3_s1', 'Semenanjung masuk dahulu: Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh dan Serani. Sembilan pasukan, gelanggang pun penuh!', 2),
(735, 71, 403, 'e4_n3_s1', 'Pak Bajau dari Sabah daftar, tok! Kadazandusun pun ada. Kami dari Murut, Rungus, Iranun dan Bajau juga main sama.', 3),
(736, 68, 403, 'e4_n3_s1', 'Apai dari Sarawak, tok! Iban dan kaum lain seperti Melayu, Kenyah, Melanau dan Bidayuh ikut sama. Tok, ada surat lama pasal pendaftaran ini!', 4),
(737, 70, 403, 'e4_n3_s2', 'Tok Batin dari pedalaman! Kami buat kraf tangan, berburu dan memungut hasil hutan. Gelanggang kuiz tok, mari mulakan!', 1),
(738, 64, 403, 'e4_n3_s2', 'Aishah dari kampung, persisiran pantai dan sungai! Ayah kami petani dan nelayan, ada peniaga kecil-kecilan dan ada makan gaji perkhidmatan awam!', 2),
(739, 69, 403, 'e4_n3_s2', 'Ah Meng dari pekan dan bandar! Datuk saya pelombong, ayah peniaga. Kedai kami KLING-KLING siang malam!', 3),
(740, 65, 403, 'e4_n3_s2', 'Kavitha dari ladang dan pinggir bandar! Kami bekerja di ladang, ada peniaga kecil dan pekerja pelabuhan. Tok, soalan mata penentu: siapa tinggal di pedalaman?', 4),
(741, 67, 403, 'e4_n3_s3', 'Tok, Jenny bawa kad garis masa! Kaum Bidayuh, Kenyah dan Kelabit di pedalaman, tanam padi sawah dan padi bukit, juga mengutip hasil hutan.', 1),
(742, 68, 403, 'e4_n3_s3', 'Apai di lembah sungai, tok. Iban dan Bisaya bertani, air sungai jadi gelanggang kami!', 2),
(743, NULL, 403, 'e4_n3_s3', 'Di pekan dan bandar pula Melayu, Melanau dan Kedayan: pedagang, pembuat perahu dan pengusaha sagu. Hebat semuanya!', 3),
(744, 67, 403, 'e4_n3_s3', 'Selepas merdeka dan pembentukan Malaysia, hasil kerja keras pemimpin dan sikap toleransi, rakyat bekerja bersama dan tinggal dalam satu kawasan perumahan. Tok, tolong susun garis masa kami!', 4),
(745, 69, 403, 'e4_n3_s4', 'Tok, pasukan Cina bertanding! Gendang, bo, liu qin dan seruling, dengan tarian singa. DUM-DUM-DUM!', 1),
(746, 65, 403, 'e4_n3_s4', 'India pula tok! Pullangkulal, talam, mattalam dan veenai, dengan bharatanatyam. Kavitha menari dahulu!', 2),
(747, NULL, 403, 'e4_n3_s4', 'Melayu: angklung, gambus, nafiri dan geduk, dengan makyung dan zapin. Sarawak: sape, engkerurai, engkerumong, ngajat. Sabah: kulintangan, sompotan, tongkungan, tontog, sumazau.', 3),
(748, 66, 403, 'e4_n3_s4', 'Linda bersedia, tok! Satu soalan: tarian sumazau milik kaum yang mana?', 4),
(749, 74, 403, 'e4_n3_s5', 'Tok, saya mahu main semua! Tapi papan skor luntur. Tok bacalah, sebelum kita mula!', 1),
(750, NULL, 403, 'e4_n3_s5', 'Anjung: congkak, batu seremban, go atau weiqi, yoyo cina atau diabolo, chaturangam dan paramapadham. Laman: sepak raga, chap teh dan kabaddi.', 2),
(751, NULL, 403, 'e4_n3_s5', 'Kawasan lapang: wau, tibau, sepak manggis dan gasing. Semua kaum main bersama di sini!', 3),
(752, 69, 403, 'e4_n3_s5', 'Tok, baca papan skor ini dahulu: permainan manakah di kawasan lapang?', 4),
(753, 72, 403, 'e4_n3_s6', 'Hehe, tok! Si Luncai dihukum raja kerana mempermain-mainkan baginda dan pembesar. Aku dimasukkan dalam guni atas perahu. Aku tipu pesuruh raja dengan lagu: \'Si Luncai terjun dengan labu-labunya, biarkan! biarkan!\'', 1),
(754, 72, 403, 'e4_n3_s6', 'Mereka leka. Aku isi labu dalam guni, terjun dan berenang dengan labu air. Mereka campak guni berisi labu itu. Aku selamat!', 2),
(755, 73, 403, 'e4_n3_s6', 'Aku Puteri Santubong, menenun. Sejinjang menumbuk padi. Kami diturunkan dari kayangan untuk mendamaikan Pasir Kuning dan Pasir Putih, tapi bertelingkah kerana Putera Serapi dari Matang.', 3),
(756, 73, 403, 'e4_n3_s6', 'Antan terkena pipiku, Gunung Santubong sumbing. Batang belidah terkena kepala Sejinjang lalu menjadi Pulau Kera, Satang dan Talang-talang.', 4),
(757, 66, 403, 'e4_n3_s6', 'Nunuk Ragang pula, tok! Penduduk Sungai Liwagu berehat di bawah pohon nunuk. Ayam gergasi merah bertaji emas membawa mereka terbang. Di mana sayap dikibar, di situ mereka membina petempatan di Tambunan dan Ranau.', 5),
(758, 66, 403, 'e4_n3_s6', 'Mereka terpisah dan membina dialek masing-masing. Tok, cari bukti legenda ini pada gambar!', 6),
(855, 81, 501, NULL, 'Tugasku ialah mencatat agama dan kepercayaan dengan jujur supaya semua kaum saling memahami. Jika pengkaji berhenti mencatat, kita mudah salah faham, {nama}. Terima kasih kerana meminjamkan jiwa!', 1),
(856, 81, 501, NULL, 'Setiap agama dan kepercayaan perlu dikenali dengan hormat. Apabila kita memahami jiran kita, kehidupan bersama menjadi lebih aman dan damai.', 2),
(857, 81, 501, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengkaji yang mengembara dengan buku nota lapangan. Pena dibuka, misi bermula! Catat setiap agama dan kepercayaan dengan adil dan hormat.', 3),
(858, 84, 501, 'e5_n1_s1', 'Pengkaji! Selamat datang ke Taman Tujuh Pintu! Aishah di sini, wakil Islam. Misi pertama kau: kenal semua wakil sebelum matahari terbenam. Siap sedia, ya?', 1),
(859, NULL, 501, 'e5_n1_s1', 'Siap! Pena sudah dibuka, buku nota sudah dibentang. Siapa seterusnya?', 2),
(860, 85, 501, 'e5_n1_s1', 'Daniel wakil Kristian! Salam sejahtera, pengkaji. Mei Ling dari Buddha di sebelah saya, dan dia malu-malu sikit.', 3),
(861, 86, 501, 'e5_n1_s1', 'Mana ada malu! Mei Ling sedia, pengkaji. Itu Kavitha untuk Hindu, dan Harjit untuk Sikh, yang paling tenang antara kami.', 4),
(862, 87, 501, 'e5_n1_s1', 'Pengkaji, jangan lupa catat nama dengan betul. Saya Hindu, dia Sikh. Dua pintu, dua agama, tapi kami berkawan sejak kecil!', 5),
(863, 89, 501, 'e5_n1_s1', 'Dan saya Kenny, wakil Ajaran Tao dan Ajaran Konfusius. Dua ajaran, satu orang, jimat tempat duduk! Pengkaji, teka: dua ajaran apakah yang saya wakili?', 6),
(864, 98, 501, 'e5_n1_s2', 'Pengkaji! Pengkaji! Saya bawa kamera sekolah! Misi kita: cari semua rumah ibadat di jalan ini. Mana satu masjid, mana satu gereja?', 1),
(865, 84, 501, 'e5_n1_s2', 'Aishah bantu! Rumah ibadat Islam ialah masjid, dan ia ada kubah hijau dengan menara yang tinggi.', 2),
(866, 85, 501, 'e5_n1_s2', 'Gereja untuk Kristian, pengkaji! Menara bersilang itu milik kami. Cantik, kan? Kami bangga!', 3),
(867, 87, 501, 'e5_n1_s2', 'Kuil untuk Hindu, dengan menara berwarna-warni. Dan itu gurdwara, untuk Sikh, dengan kubah emas.', 4),
(868, 86, 501, 'e5_n1_s2', 'Buddha ada tokong atau wat. Tokong juga digunakan untuk Ajaran Konfusius dan Ajaran Tao. Satu nama, tiga penghuni!', 5),
(869, 98, 501, 'e5_n1_s2', 'Wah! Pengkaji, cepat tunjuk pada gambar: mana satu rumah ibadat Sikh?', 6),
(870, 98, 501, 'e5_n1_s3', 'Pengkaji, cikgu kata Perkara 3 itu penting untuk peperiksaan! Cepat, ceritakan apa maksudnya!', 1),
(871, NULL, 501, 'e5_n1_s3', 'Perkara 3(1): Islam adalah agama bagi Persekutuan, tetapi agama lain boleh diamalkan dengan aman dan damai di mana-mana bahagian Persekutuan.', 2),
(872, 96, 501, 'e5_n1_s3', 'Beta menyambung, pengkaji. Perkara 3(2): di negeri yang mempunyai Raja, kedudukan Raja ialah Ketua Agama Islam di negeri itu.', 3),
(873, 97, 501, 'e5_n1_s3', 'Dan saya wakil negeri tanpa Raja. Perkara 3(3): bagi Melaka, Pulau Pinang, Sabah dan Sarawak, Yang di-Pertuan Agong ialah Ketua Agama Islam.', 4),
(874, 96, 501, 'e5_n1_s3', 'Perkara 3(5) pula, pengkaji: Yang di-Pertuan Agong ialah Ketua Agama Islam Wilayah Persekutuan Kuala Lumpur, Labuan dan Putrajaya.', 5),
(875, 98, 501, 'e5_n1_s3', 'Wah, banyak nombor! Pengkaji, di Sabah, siapakah Ketua Agama Islamnya?', 6),
(876, 91, 501, 'e5_n1_s4', 'Selamat datang, pengkaji! Saya Pak Mah Meri. Hari ini kami mengadakan Puja Pantai, upacara memohon perlindungan dan pengampunan daripada semangat laut. Dengar ombak itu, pengkaji!', 1),
(877, NULL, 501, 'e5_n1_s4', 'Wah, jadi Puja Pantai itu untuk perlindungan dan pengampunan. Boleh saya catat, Pak?', 2),
(878, 90, 501, 'e5_n1_s4', 'Catatlah, pengkaji. Kami suku Temiar dan Semai percaya penyakit datang daripada kuasa jahat. Kami adakan upacara ritual untuk menghalau kuasa jahat itu.', 3),
(879, 91, 501, 'e5_n1_s4', 'Itulah kepercayaan kami, pengkaji. Orang Asli di Semenanjung menjaga laut, hutan dan tubuh dengan upacara. Cuba kau ulang, apa tujuan Puja Pantai?', 4),
(880, 92, 501, 'e5_n1_s5', 'Pengkaji, Apai Jelani ini orang Iban. Kami percaya Petara, dewa kami, menyampaikan petanda dan alamat melalui mimpi dan bayangan. Mimpi pun boleh jadi surat!', 1),
(881, NULL, 501, 'e5_n1_s5', 'Wah, surat melalui mimpi! Bagaimana Petara dipuja, Apai?', 2),
(882, 92, 501, 'e5_n1_s5', 'Melalui upacara Miring, pengkaji. Miring dimulai dengan jampi mentera, dan dilakukan oleh seorang penyair dikenali sebagai Lemambang.', 3),
(883, 93, 501, 'e5_n1_s5', 'Linda dari Kadazandusun pula! Kami percaya Kinorohingan, Tuhan untuk meminta sesuatu. Kami juga percaya semangat padi, jadi kami adakan upacara Magavau.', 4),
(884, 93, 501, 'e5_n1_s5', 'Magavau diketuai oleh ketua bomoh yang dikenali sebagai Bobohizan. Pengkaji, kau teka: siapa yang melakukan upacara Miring?', 5),
(885, 94, 501, 'e5_n1_s6', 'Salam, pengkaji! Saya petani Bisaya. Kami percaya kuasa ghaib. Sebelum membuka kawasan pertanian baharu, kami baca jampi mentera supaya tidak ada gangguan.', 1),
(886, 94, 501, 'e5_n1_s6', 'Jika ada orang sakit, kami adakan upacara Tamarok untuk menghalau kuasa ghaib daripada badan pesakit. Bau asapnya wangi, pengkaji!', 2),
(887, 95, 501, 'e5_n1_s6', 'Pak Bajau datang menyampuk! Kami orang Bajau menjalankan upacara Ngeduang di pantai barat Sabah, Kota Belud. Keluarga si mati menjamu makanan kepada tetamu sebagai sedekah.', 3),
(888, 95, 501, 'e5_n1_s6', 'Orang Bajau di pantai timur, Semporna, pula mengadakan Mag\'ombo. Mag\'ombo bermaksud menghargai dan menghormati warisan turun-temurun agar kehidupan dirahmati. Pengkaji, di manakah Ngeduang diamalkan?', 4),
(889, 82, 502, NULL, 'Tugasku ialah menjaga cerita kepercayaan setiap kaum supaya tidak lenyap seperti kabus pagi. Jika penjaga adat berdiam diri, anak cucu lupa asal mereka, {nama}. Terima kasih kerana meminjamkan jiwa!', 1),
(890, 82, 502, NULL, 'Setiap kaum menjaga kepercayaannya dengan cara sendiri. Apabila kita belajar menghormati cara itu, kita hidup aman seperti padi yang tumbuh sama tinggi.', 2),
(891, 82, 502, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penjaga padi yang dijemput ke persidangan para penjaga adat. Loceng kecil berdenting, semangat padi pun menanti. Dengarlah dengan telinganya dan bercakaplah dengan suaranya.', 3),
(892, 98, 502, 'e5_n2_s1', 'Bobohizan! Bobohizan! Murid sekolah dijemput ke persidangan ini. Cikgu kata kita mesti kenal tujuh agama dan ajaran. Tujuh? Banyaknya!', 1),
(893, NULL, 502, 'e5_n2_s1', 'Ssshh, jangan cemas, anak. Semangat padi pun belajar satu persatu. Marilah, kita bertemu wakil mereka dengan hormat.', 2),
(894, 84, 502, 'e5_n2_s1', 'Aishah wakil Islam. Terima kasih sudah sudi datang, Bobohizan. Di sebelah saya, Daniel untuk Kristian.', 3),
(895, 85, 502, 'e5_n2_s1', 'Betul tu! Daniel yang pandai berjenaka tapi kali ini serius. Mei Ling di sana wakil Buddha, dan Kavitha untuk Hindu.', 4),
(896, 88, 502, 'e5_n2_s1', 'Saya Harjit, wakil Sikh. Orang pertama yang tersenyum bila ditanya, kata orang!', 5),
(897, 89, 502, 'e5_n2_s1', 'Kenny di hujung! Wakil Ajaran Tao dan Ajaran Konfusius, dua ajaran, satu kerusi. Bobohizan, bantu padankan nama kami dengan agama, ya?', 6),
(898, 98, 502, 'e5_n2_s2', 'Bobohizan, dari atas bukit ini nampak banyak bangunan! Itu rumah ibadat, kan? Nama masing-masing apa?', 1),
(899, NULL, 502, 'e5_n2_s2', 'Ya, anak. Setiap bangunan itu rumah doa. Ada masjid, gereja, kuil, gurdwara, tokong dan wat. Lihat betul-betul!', 2),
(900, 84, 502, 'e5_n2_s2', 'Masjid untuk Islam, Bobohizan! Kubahnya berwarna merah jambu di sebelah sana.', 3),
(901, 87, 502, 'e5_n2_s2', 'Kuil untuk Hindu. Menara warna-warni itu milik kami, Bobohizan. Cantik, kan?', 4),
(902, 86, 502, 'e5_n2_s2', 'Tokong atau wat untuk Buddha. Tokong yang sama juga untuk Ajaran Konfusius dan Ajaran Tao. Gereja untuk Kristian, gurdwara untuk Sikh.', 5),
(903, 98, 502, 'e5_n2_s2', 'Bobohizan, cepat tunjuk pada gambar! Cari masjid, gereja, kuil, gurdwara dan tokong!', 6),
(904, 96, 502, 'e5_n2_s3', 'Selamat datang, Bobohizan. Beta mahu menerangkan Perkara 3. Perkara 3(1): Islam adalah agama bagi Persekutuan, tetapi agama lain boleh diamalkan dengan aman dan damai di mana-mana bahagian Persekutuan.', 1),
(905, NULL, 502, 'e5_n2_s3', 'Wah, jadi setiap agama dijaga dengan aman. Sama macam kampung kami, setiap upacara ada tempatnya.', 2),
(906, 96, 502, 'e5_n2_s3', 'Perkara 3(2): di negeri yang mempunyai Raja, kedudukan Raja ialah Ketua Agama Islam di negeri beraja itu.', 3),
(907, 97, 502, 'e5_n2_s3', 'Saya dari negeri tanpa Raja. Perkara 3(3): bagi Melaka, Pulau Pinang, Sabah dan Sarawak, Yang di-Pertuan Agong ialah Ketua Agama Islam.', 4),
(908, 97, 502, 'e5_n2_s3', 'Perkara 3(5): Yang di-Pertuan Agong juga Ketua Agama Islam Wilayah Persekutuan Kuala Lumpur, Labuan dan Putrajaya. Bobohizan, soalan untuk kau: siapa Ketua Agama Islam Wilayah Persekutuan?', 5),
(909, 91, 502, 'e5_n2_s4', 'Bobohizan dari Sabah! Jauh kau datang. Saya Pak Mah Meri. Di sini kami mengadakan upacara Puja Pantai untuk memohon perlindungan dan pengampunan daripada semangat laut.', 1),
(910, NULL, 502, 'e5_n2_s4', 'Semangat laut, ya? Di kampung saya, kami pun ada semangat padi. Setiap kaum menjaga dengan cara masing-masing.', 2),
(911, 90, 502, 'e5_n2_s4', 'Tok Batin Temiar berkata: orang Asli percaya penyakit disebabkan kuasa jahat. Kami suku Temiar dan Semai mengadakan upacara ritual untuk menghalau kuasa jahat itu.', 3),
(912, 98, 502, 'e5_n2_s4', 'Bobohizan, saya hendak kuiz! Apakah yang Orang Asli percayai tentang punca penyakit?', 4),
(913, 93, 502, 'e5_n2_s5', 'Bobohizan, Linda di sini! Matahari terbit di atas sawah macam lukisan. Kami percaya Kinorohingan, Tuhan untuk meminta sesuatu. Apa pun kita pinta, kita sebut nama itu.', 1),
(914, NULL, 502, 'e5_n2_s5', 'Betul, anak. Kami juga percaya semangat padi. Kerana itu kami menjalankan upacara Magavau, dan Bobohizan yang memimpinnya, itulah tugas aku!', 2),
(915, 92, 502, 'e5_n2_s5', 'Apai Jelani, orang Iban, menumpang berbual. Kami percaya Petara menyampaikan petanda dan alamat melalui mimpi dan bayangan. Kami memujanya melalui upacara Miring.', 3),
(916, 92, 502, 'e5_n2_s5', 'Miring dimulai dengan jampi mentera, dan dilakukan oleh penyair yang dikenali sebagai Lemambang. Bobohizan, siapa yang memimpin upacara Magavau?', 4),
(917, 95, 502, 'e5_n2_s6', 'Selamat datang, Bobohizan! Pak Bajau jemput makan dahulu. Di Kota Belud, pantai barat Sabah, keluarga si mati menjamu makanan kepada tetamu sebagai sedekah. Itulah upacara Ngeduang.', 1),
(918, NULL, 502, 'e5_n2_s6', 'Terima kasih, Pak. Jamuan sebagai sedekah, bunyi macam adat kampung saya juga.', 2),
(919, 94, 502, 'e5_n2_s6', 'Petani Bisaya pun menumpang. Kami di Sarawak percaya kuasa ghaib. Jampi mentera dibaca sebelum membuka kawasan pertanian baharu supaya tiada gangguan.', 3),
(920, 94, 502, 'e5_n2_s6', 'Kalau ada pesakit, kami adakan upacara Tamarok untuk menghalau kuasa ghaib daripada badan pesakit.', 4),
(921, 95, 502, 'e5_n2_s6', 'Orang Bajau di pantai timur, Semporna, mengadakan Mag\'ombo, menghargai dan menghormati warisan turun-temurun agar kehidupan dirahmati. Bobohizan, padankan upacara dengan tempatnya!', 5),
(922, 83, 503, NULL, 'Tugasku ialah melagukan syair supaya kepercayaan setiap kaum difahami dan dihormati. Jika penyair senyap, bait-bait lama pun lenyap, {nama}. Terima kasih kerana meminjamkan suara!', 1),
(923, 83, 503, NULL, 'Setiap agama dan kepercayaan ialah satu bait dalam syair besar negara kita. Apabila semua bait dilagukan bersama, Malaysia berbunyi merdu.', 2),
(924, 83, 503, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penyair yang melagukan jampi mentera dan syair pujian. Suaramu bergema, sekolah pun senyap menanti! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(925, 98, 503, 'e5_n3_s1', 'Lemambang! Lemambang! Papan tanda pesta ini luntur terkena hujan semalam! Boleh Lemambang nyanyikan semula senarai agama?', 1),
(926, NULL, 503, 'e5_n3_s1', 'Hai, anak cucu! Syair bermula begini: Islam, Kristian, Buddha, Hindu. Empat nama itu masih jelas pada papan tanda, bukan?', 2),
(927, 84, 503, 'e5_n3_s1', 'Jelas, Lemambang! Tapi tiga nama terakhir pudar. Aishah sendiri pun tak nampak, hehe.', 3),
(928, 89, 503, 'e5_n3_s1', 'Kenny pun tak nampak! Hmm, nama saya pun hilang? Aduh, Lemambang, tolong baca tiga nama terakhir itu!', 4),
(929, 98, 503, 'e5_n3_s2', 'Lemambang! Murid-murid dapat kad nama rumah ibadat, tapi kad itu bertaburan ditiup angin! Boleh Lemambang tolong susun semula?', 1),
(930, NULL, 503, 'e5_n3_s2', 'Hai, tenanglah, anak cucu! Syair ini pun ada rentaknya. Islam dengan masjid, Kristian dengan gereja.', 2),
(931, 87, 503, 'e5_n3_s2', 'Hindu dengan kuil, Lemambang! Cepat, jangan sampai angin bawa kad itu ke pantai!', 3),
(932, 88, 503, 'e5_n3_s2', 'Sikh dengan gurdwara. Harjit pegang kadnya erat-erat, Lemambang. Tak mahu hilang!', 4),
(933, 86, 503, 'e5_n3_s2', 'Buddha dengan tokong atau wat. Tokong juga untuk Ajaran Konfusius dan Ajaran Tao. Lemambang, padankan semua kad ya!', 5),
(934, 98, 503, 'e5_n3_s3', 'Lemambang, cikgu kata Perkara 3 ada empat bahagian. Tapi kad saya bercampur, dan saya tak ingat susunannya!', 1),
(935, NULL, 503, 'e5_n3_s3', 'Tenang, anak. Syair ini ada urutannya. Mulakan dengan Perkara 3(1): Islam adalah agama bagi Persekutuan, tetapi agama lain boleh diamalkan dengan aman dan damai di mana-mana bahagian Persekutuan.', 2),
(936, 96, 503, 'e5_n3_s3', 'Beta menyambung. Perkara 3(2): di negeri yang mempunyai Raja, kedudukan Raja ialah Ketua Agama Islam di negeri itu.', 3),
(937, 97, 503, 'e5_n3_s3', 'Perkara 3(3): bagi Melaka, Pulau Pinang, Sabah dan Sarawak, Yang di-Pertuan Agong ialah Ketua Agama Islam. Perkara 3(5): Yang di-Pertuan Agong juga Ketua Agama Islam Wilayah Persekutuan Kuala Lumpur, Labuan dan Putrajaya.', 4),
(938, 98, 503, 'e5_n3_s3', 'Wah, banyaknya! Lemambang, tolong susun kad saya mengikut nombor Perkara!', 5),
(939, 91, 503, 'e5_n3_s4', 'Lemambang, selamat datang ke pantai! Orang Mah Meri mengadakan Puja Pantai untuk memohon perlindungan dan pengampunan daripada semangat laut. Dengar ombak, itu suara semangat laut.', 1),
(940, NULL, 503, 'e5_n3_s4', 'Merdu sekali, Pak! Syair kami di Sarawak pun begitu. Setiap kaum menyanyi mengikut alamnya.', 2),
(941, 90, 503, 'e5_n3_s4', 'Tok Batin Temiar bercerita. Orang Asli percaya penyakit disebabkan kuasa jahat. Suku Temiar dan Suku Semai mengadakan upacara ritual untuk menghalau kuasa jahat itu.', 3),
(942, 98, 503, 'e5_n3_s4', 'Lemambang, saya nak tanya! Mana satu padanan yang betul tentang kepercayaan Orang Asli?', 4),
(943, 92, 503, 'e5_n3_s5', 'Lemambang! Betul-betul orang kita! Apai Jelani mahu bercerita. Kami orang Iban percaya Petara menyampaikan petanda dan alamat melalui mimpi dan bayangan.', 1),
(944, NULL, 503, 'e5_n3_s5', 'Betul, Apai. Kita memuja Petara melalui upacara Miring. Miring dimulai dengan jampi mentera, dan dilakukan oleh penyair, Lemambang, iaitu saya sendiri, hai!', 2),
(945, 93, 503, 'e5_n3_s5', 'Linda dari Kadazandusun menumpang. Kami percaya Kinorohingan, Tuhan untuk meminta sesuatu. Kami juga percaya semangat padi dan menjalankan upacara Magavau.', 3),
(946, 93, 503, 'e5_n3_s5', 'Upacara Magavau diketuai oleh ketua bomoh yang dikenali sebagai ... eh, nama itu terlupa pula! Lemambang, tolong baca catatan ini dahulu!', 4),
(947, 94, 503, 'e5_n3_s6', 'Lemambang! Petani Bisaya datang jauh dari Sarawak. Kami percaya kuasa ghaib. Jampi mentera dibaca sebelum membuka kawasan pertanian baharu supaya tiada gangguan.', 1),
(948, 94, 503, 'e5_n3_s6', 'Bila ada pesakit, kami adakan upacara Tamarok untuk menghalau kuasa ghaib daripada badan pesakit.', 2),
(949, 95, 503, 'e5_n3_s6', 'Pak Bajau pula, Lemambang! Di pantai barat Sabah, Kota Belud, keluarga si mati menjamu makanan kepada tetamu sebagai sedekah. Itulah upacara Ngeduang.', 3),
(950, 95, 503, 'e5_n3_s6', 'Di pantai timur, Semporna, kami mengadakan Mag\'ombo, bermaksud menghargai dan menghormati warisan turun-temurun agar kehidupan dirahmati. Lemambang, cari bukti upacara pantai ini pada gambar!', 4),
(951, 101, 601, NULL, 'Tugasku ialah membuat hiasan supaya setiap perayaan kelihatan meriah dan dikenali kaum lain. Jika tangan kraf berhenti, tradisi pun luput, {nama}. Terima kasih kerana meminjamkan tanganmu!', 1),
(952, 101, 601, NULL, 'Setiap perayaan mempunyai cara dan tujuan sendiri. Apabila kita mengenalinya, kita boleh meraikan bersama-sama sebagai jiran dan rakan.', 2),
(953, 101, 601, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penggiat kraf yang membuat hiasan untuk setiap perayaan. Gunting, kertas dan lampu kelip sudah sedia, bengkel dibuka! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(954, 104, 601, 'e6_n1_s1', 'Penggiat! Aishah nak tempah ketupat kertas untuk Hari Raya Aidilfitri dan Aidiladha. Kira kerja, cepat, ya? Hehe!', 1),
(955, 106, 601, 'e6_n1_s1', 'Ah Meng pula tempah lampion merah untuk Tahun Baharu Cina! Bengkel ini macam tempat latihan tentera perayaan, hebat!', 2),
(956, 105, 601, 'e6_n1_s1', 'Kavitha nak lampu pelita untuk Deepavali dan Thaipusam! Saya sudah lukis rekaannya, kau cuma perlu potong, penggiat!', 3),
(957, 110, 601, 'e6_n1_s1', 'Harjit tempah kain berwarna untuk Vaisakhi. Dan itu Mei Ling mahu tempah hiasan bunga teratai untuk Hari Wesak!', 4),
(958, 108, 601, 'e6_n1_s1', 'Daniel nak hiasan Krismas! Dan hiasan Hari Gawai juga. Satu kedai untuk semua, jimat langkah!', 5),
(959, 109, 601, 'e6_n1_s1', 'Linda tempah hiasan padi untuk Pesta Kaamatan. Pak Nelayan di belakang pula nak hiasan perahu untuk San Pedro.', 6),
(960, NULL, 601, 'e6_n1_s1', 'Wah, penuh meja! Jangan lupa Sambutan Tahun Baharu, Genggulang dan Hari Moyang, pun ada dalam senarai. Aku catat semua!', 7),
(961, 110, 601, 'e6_n1_s1', 'Penggiat, soalan mata penentu: perayaan manakah yang saya, Harjit, raikan?', 8),
(962, 113, 601, 'e6_n1_s2', 'Penggiat! Cikgu kata setiap perayaan ada tujuan sendiri. Tapi saya keliru, bolehkah penggiat jelaskan sambil menggunting?', 1),
(963, NULL, 601, 'e6_n1_s2', 'Boleh, murid! Keagamaan: Hari Raya Aidilfitri, Aidiladha, Krismas dan Thaipusam. Gunting dahulu, kemudian cerita lagi!', 2),
(964, 106, 601, 'e6_n1_s2', 'Meraikan tahun baharu pula: Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk dan Tawun Empai. Ramai tahun baharu, kan?', 3),
(965, 109, 601, 'e6_n1_s2', 'Mensyukuri hasil tanaman atau hasil laut: Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro. Terima kasih kepada padi dan laut!', 4),
(966, 105, 601, 'e6_n1_s2', 'Deepavali pula supaya unsur baik mengatasi kejahatan, dan Hari Wesak untuk mengingati tokoh agama.', 5),
(967, 113, 601, 'e6_n1_s2', 'Banyaknya! Penggiat, saya mahu padankan kad tujuan dengan perayaan. Siap-siap!', 6),
(968, 112, 601, 'e6_n1_s3', 'Cucu, dahulu nenek hantar kad ucapan melalui pos atau serahan tangan. Setiap kad tulis tangan, ada bau dakwat. Seronok!', 1),
(969, 113, 601, 'e6_n1_s3', 'Kini kami hantar ucapan guna media elektronik dan media sosial, nek! Satu klik, terus sampai. Bunyi pop!', 2),
(970, 112, 601, 'e6_n1_s3', 'Foto keluarga pula dahulu diambil di kedai gambar. Satu kali sahaja, jangan berkelip!', 3),
(971, 113, 601, 'e6_n1_s3', 'Kini kami swafoto bersama keluarga dan memuat naiknya di media sosial! Penggiat, cari bukti cara dahulu pada gambar studio ini!', 4),
(972, 105, 601, 'e6_n1_s4', 'Penggiat, lihat kolam ini! Dahulu kami membuat kolam daripada tepung ketika Deepavali. Putih bersih, cantik macam salji!', 1),
(973, 105, 601, 'e6_n1_s4', 'Kini kolam dihasilkan daripada beras atau hampas kelapa yang berwarna-warni. Meriah macam pelangi!', 2),
(974, 106, 601, 'e6_n1_s4', 'Ah Meng pula, penggiat! Tradisi makan besar Tahun Baharu Cina dahulu di rumah, berkumpul bersama keluarga. Meja bulat penuh!', 3),
(975, 107, 601, 'e6_n1_s4', 'Kini masih diraikan di rumah, tetapi ada keluarga yang memilih restoran atau hotel. Tak payah masak, kata mereka!', 4),
(976, 105, 601, 'e6_n1_s4', 'Penggiat, baca catatan lama ini! Kolam dahulu daripada apa?', 5),
(977, 112, 601, 'e6_n1_s5', 'Cucu-cucu, dahulu kami menyediakan kuih-muih menggunakan bahan dan kaedah tradisional secara gotong-royong. Asap kayu api pedih mata, tapi seronok!', 1),
(978, 104, 601, 'e6_n1_s5', 'Kini peralatan moden memudahkan penyediaan, penggiat. Kuih raya juga mudah dibeli, tinggal bayar sahaja!', 2),
(979, 112, 601, 'e6_n1_s5', 'Tapi ada amalan yang kekal, tau. Balik ke kampung, pemberian duit raya dan kunjung-mengunjung. Itu tidak akan berubah!', 3),
(980, 113, 601, 'e6_n1_s5', 'Penggiat, soalan mata penentu: apakah amalan yang masih kekal sehingga kini?', 4),
(981, 111, 601, 'e6_n1_s6', 'Penggiat, Apai Jelani cerita sikit tentang Hari Gawai. Dahulu hanya golongan petani daripada kaum Dayak yang meraikannya dengan pelbagai upacara ritual.', 1),
(982, 108, 601, 'e6_n1_s6', 'Kini pelbagai kaum merayakannya tanpa mengira bidang pekerjaan, penggiat! Daniel pun ikut sama dengan hiasan Gawai!', 2),
(983, 109, 601, 'e6_n1_s6', 'Linda pula untuk Pesta Kaamatan dan Unduk Ngadau! Dahulu pemenang dipilih berdasarkan semangat Huminodun, iaitu kesanggupan berkorban demi menyelamatkan generasi.', 3),
(984, 109, 601, 'e6_n1_s6', 'Kini pemenang juga dipilih berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau. Pandai, mahir dan berani!', 4),
(985, 111, 601, 'e6_n1_s6', 'Penggiat, cari bukti Unduk Ngadau dahulu pada gambar pentas pondok ini!', 5),
(986, 102, 602, NULL, 'Tugasku ialah menjadi jambatan antara cara dahulu dan cara kini supaya anak-anak tidak lupa asal usul perayaan. Terima kasih kerana meminjamkan jiwa, {nama}. Perjalanan pulang ini bermakna kerana kau!', 1),
(987, 102, 602, NULL, 'Cara kita beraya boleh berubah mengikut zaman, tetapi kasih sayang, kunjung-mengunjung dan pulang ke kampung kekal sebagai tanda hormat kepada keluarga.', 2),
(988, 102, 602, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, ibu moden yang memandu pulang ke kampung dengan kereta penuh bagasi. Radio berbunyi, anak-anak bising, nenek menunggu di beranda! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(989, 113, 602, 'e6_n2_s1', 'Ibu! Ibu! Cikgu bagi kerja rumah: senaraikan perayaan utama masyarakat Malaysia. Cepat Ibu, sebelum internet nenek putus!', 1),
(990, 112, 602, 'e6_n2_s1', 'Nenek tolong dulu! Ada Hari Raya Aidilfitri dan Hari Raya Aidiladha. Yang kedua ni orang kampung panggil Raya Haji!', 2),
(991, 105, 602, 'e6_n2_s1', 'Kavitha dari sebelah rumah! Deepavali dan Thaipusam. Harjit pula Vaisakhi. Tiga perayaan, tiga cerita!', 3),
(992, 108, 602, 'e6_n2_s1', 'Daniel, Krismas! Mei Ling untuk Hari Wesak. Dan Ah Meng untuk Tahun Baharu Cina, dengan ang pau yang banyak!', 4),
(993, 109, 602, 'e6_n2_s1', 'Linda bawa Pesta Kaamatan! Daniel tambah Hari Gawai. Pak Nelayan pula sambut San Pedro. Dan ada juga Sambutan Tahun Baharu, Genggulang dan Hari Moyang!', 5),
(994, NULL, 602, 'e6_n2_s1', 'Banyaknya! Ibu pun terkejut, nak. Tapi senang, kita padankan satu persatu. Mari!', 6),
(995, 109, 602, 'e6_n2_s1', 'Ibu, soalan mata penentu: Pesta Kaamatan disambut di negeri manakah?', 7),
(996, 112, 602, 'e6_n2_s2', 'Cucu, nenek ajar satu perkara. Setiap perayaan ada tujuan. Keagamaan: Hari Raya Aidilfitri, Aidiladha, Krismas dan Thaipusam.', 1),
(997, 113, 602, 'e6_n2_s2', 'Nenek, tahun baharu pula? Ada banyak nama pelik, kan?', 2),
(998, 112, 602, 'e6_n2_s2', 'Ya! Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk dan Tawun Empai. Semua untuk meraikan tahun baharu.', 3),
(999, NULL, 602, 'e6_n2_s2', 'Dan hasil tanaman atau hasil laut, nenek? Ibu dengar ada Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro.', 4),
(1000, 112, 602, 'e6_n2_s2', 'Betul! Untuk mensyukuri hasil. Deepavali pula supaya unsur baik mengatasi kejahatan, dan Hari Wesak untuk mengingati tokoh agama.', 5),
(1001, 113, 602, 'e6_n2_s2', 'Bagus! Ibu, nenek tulis surat lama tapi dakwatnya luntur. Cuba nyahkod: tujuan Deepavali apa?', 6),
(1002, 113, 602, 'e6_n2_s3', 'Ibu! Saya dah hantar ucapan raya kepada nenek melalui media sosial. Satu klik, terus sampai! Bunyi PING!', 1),
(1003, 112, 602, 'e6_n2_s3', 'Dahulu kad ucapan dihantar melalui pos atau serahan tangan, cucu. Kad itu nenek simpan sampai sekarang, bau kertas lama pun wangi.', 2),
(1004, NULL, 602, 'e6_n2_s3', 'Foto keluarga dahulu nenek ambil di kedai gambar. Kini kami swafoto bersama keluarga dan muat naik di media sosial.', 3),
(1005, 113, 602, 'e6_n2_s3', 'Betul nenek! Hari ini Ibu swafoto sepuluh kali sebab ayah berkelip. Ibu, soalan: apakah cara menghantar ucapan kini?', 4),
(1006, 105, 602, 'e6_n2_s4', 'Kolam kami tahun ini guna beras berwarna dan hampas kelapa berwarna-warni, Puan! Dahulu nenek-nenek guna tepung sahaja.', 1),
(1007, NULL, 602, 'e6_n2_s4', 'Cantiknya! Macam lukisan pelangi di atas tanah. Dan makan besar Tahun Baharu Cina pula bagaimana, Ah Meng?', 2),
(1008, 106, 602, 'e6_n2_s4', 'Dahulu keluarga kami berkumpul di rumah untuk makan besar, Puan. Kini masih diraikan di rumah, tetapi ada keluarga yang memilih restoran atau hotel.', 3),
(1009, 107, 602, 'e6_n2_s4', 'Betul tu! Mei Ling pun ikut sama. Puan, tolong cari bukti kolam kini pada gambar halaman ini!', 4),
(1010, 112, 602, 'e6_n2_s5', 'Cucu, dahulu nenek menyediakan kuih-muih menggunakan bahan dan kaedah tradisional secara gotong-royong. Ramai jiran datang membantu. Tangan penuh tepung!', 1),
(1011, 113, 602, 'e6_n2_s5', 'Kini peralatan moden memudahkan penyediaan, nek. Kuih raya pun mudah dibeli di kedai macam ini. Bunyi KRING juruwang!', 2),
(1012, NULL, 602, 'e6_n2_s5', 'Tapi ada amalan yang kekal, kan nek? Balik ke kampung, pemberian duit raya, dan amalan kunjung-mengunjung.', 3),
(1013, 112, 602, 'e6_n2_s5', 'Betul, nak. Itu yang kekal. Cuba susun mengikut urutan: dahulu, kini, kemudian yang sentiasa kekal!', 4),
(1014, 111, 602, 'e6_n2_s6', 'Puan, Apai Jelani datang dari Sarawak. Dahulu Hari Gawai diraikan oleh golongan petani daripada kaum Dayak dengan pelbagai upacara ritual.', 1),
(1015, 108, 602, 'e6_n2_s6', 'Kini Hari Gawai diraikan oleh pelbagai kaum tanpa mengira bidang pekerjaan, Puan! Daniel pun datang bergembira sama!', 2),
(1016, 109, 602, 'e6_n2_s6', 'Linda di sini! Di pentas itu ialah Unduk Ngadau, Pesta Kaamatan. Dahulu pemenang dipilih berdasarkan semangat Huminodun, iaitu kesanggupan berkorban demi menyelamatkan generasi.', 3),
(1017, 109, 602, 'e6_n2_s6', 'Kini pemenang juga dipilih berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau. Puan, baca pengumuman ini, tapi tulisannya luntur!', 4),
(1018, 103, 603, NULL, 'Tugasku ialah memastikan setiap pelanggan, apa pun kaumnya, mendapat apa yang diperlukan untuk beraya. Kedai ini hidup kerana kau, {nama}. Terima kasih kerana meminjamkan tangan menjaga kaunter!', 1),
(1019, 103, 603, NULL, 'Setiap perayaan menyatukan keluarga dan jiran. Apabila kita mengenali perayaan kaum lain, kita boleh meraikannya bersama-sama dengan hormat dan gembira.', 2),
(1020, 103, 603, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, tuan punya kedai yang menjual kad, kuih dan hiasan untuk semua perayaan. Loceng pintu berbunyi, pelanggan pertama sudah masuk! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(1021, 104, 603, 'e6_n3_s1', 'Selamat pagi, tauke! Aishah nak beli kad Hari Raya Aidilfitri dan Aidiladha. Dua perayaan, dua kad, tolong bungkus cantik-cantik!', 1),
(1022, 106, 603, 'e6_n3_s1', 'Ah Meng, Tahun Baharu Cina! Dan Mei Ling di belakang nak bunga teratai untuk Hari Wesak. Antri panjang tapi sabar!', 2),
(1023, 105, 603, 'e6_n3_s1', 'Kavitha, Deepavali dan Thaipusam! Harjit di sebelah nak kain untuk Vaisakhi. Tauke ada stok tak?', 3),
(1024, 108, 603, 'e6_n3_s1', 'Daniel, Krismas dan Hari Gawai! Linda untuk Pesta Kaamatan. Pak Nelayan pula nak benda untuk San Pedro. Penuh kedai, tauke!', 4),
(1025, NULL, 603, 'e6_n3_s1', 'Wah, penuh kaunter! Belum lagi Sambutan Tahun Baharu, Genggulang dan Hari Moyang. Esok mungkin ada yang tanya. Mari lihat senarai jualan!', 5),
(1026, 113, 603, 'e6_n3_s1', 'Tauke, senarai jualan ini luntur! Boleh tolong nyahkod perayaan yang tak kelihatan?', 6),
(1027, 113, 603, 'e6_n3_s2', 'Tauke, kad ini disusun ikut apa? Tak ikut kaum ya?', 1),
(1028, NULL, 603, 'e6_n3_s2', 'Ikut tujuan perayaan, murid! Keagamaan: Aidilfitri, Aidiladha, Krismas dan Thaipusam. Tahun baharu: Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk, Tawun Empai.', 2),
(1029, 109, 603, 'e6_n3_s2', 'Rak syukur hasil, ya, tauke! Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro. Syukur padi dan laut!', 3),
(1030, 105, 603, 'e6_n3_s2', 'Rak kebaikan mengatasi kejahatan untuk Deepavali, dan rak mengingati tokoh agama untuk Hari Wesak. Cantik susunannya, tauke!', 4),
(1031, 113, 603, 'e6_n3_s2', 'Betul! Tauke, soalan pop: kad Gawai, Kaamatan, Vaisakhi dan San Pedro, tujuannya apa?', 5),
(1032, 112, 603, 'e6_n3_s3', 'Tauke, dahulu nenek beli kad di kedai ini dan hantar melalui pos atau serahan tangan. Kad itu nenek tulis sendiri, dengan tulisan cantik.', 1),
(1033, 113, 603, 'e6_n3_s3', 'Kini kami hantar ucapan melalui media elektronik dan media sosial, tauke! Tak payah beli kad pun, hehe.', 2),
(1034, 112, 603, 'e6_n3_s3', 'Foto keluarga pula dahulu diambil di kedai gambar. Tegak badan, jangan bergerak!', 3),
(1035, 113, 603, 'e6_n3_s3', 'Kini kami swafoto bersama keluarga dan muat naik di media sosial. Tauke, tolong susun cara dahulu dan kini mengikut zaman!', 4),
(1036, 105, 603, 'e6_n3_s4', 'Tauke, pelanggan nak beli beras berwarna untuk kolam Deepavali! Dahulu orang buat kolam daripada tepung, kini guna beras atau hampas kelapa yang berwarna-warni.', 1),
(1037, 106, 603, 'e6_n3_s4', 'Ah Meng pula, tauke! Makan besar Tahun Baharu Cina dahulu diraikan di rumah, berkumpul bersama keluarga. Meja bulat penuh!', 2),
(1038, 107, 603, 'e6_n3_s4', 'Kini diraikan di rumah juga, tapi ada keluarga yang memilih restoran atau hotel, tauke. Tak perlu cuci pinggan!', 3),
(1039, 113, 603, 'e6_n3_s4', 'Tauke, cepat padankan! Kolam dahulu dan kini, makan besar dahulu dan kini!', 4),
(1040, 112, 603, 'e6_n3_s5', 'Tauke, dahulu kuih-muih disediakan menggunakan bahan dan kaedah tradisional secara gotong-royong. Tak ada kedai macam ini, kami buat sendiri!', 1),
(1041, 104, 603, 'e6_n3_s5', 'Kini penggunaan peralatan moden memudahkan penyediaan, tauke. Kuih raya juga mudah dibeli di kedai macam ini. Bunyi KLING loceng pintu!', 2),
(1042, 112, 603, 'e6_n3_s5', 'Tapi ada amalan yang kekal, tauke. Balik ke kampung, pemberian duit raya, dan amalan kunjung-mengunjung.', 3),
(1043, 113, 603, 'e6_n3_s5', 'Tauke, cari bukti kuih kini pada gambar kedai ini! Saya nak cari kuih dan duit raya!', 4),
(1044, 111, 603, 'e6_n3_s6', 'Tauke, lihat perarakan Gawai! Dahulu Hari Gawai diraikan oleh golongan petani daripada kaum Dayak dengan mengadakan pelbagai upacara ritual.', 1),
(1045, 108, 603, 'e6_n3_s6', 'Kini diraikan oleh pelbagai kaum tanpa mengira bidang pekerjaan, tauke! Daniel pun ikut berarak, tapi dengan hiasan yang tauke jual!', 2),
(1046, 109, 603, 'e6_n3_s6', 'Linda untuk Pesta Kaamatan! Unduk Ngadau dahulu memilih pemenang berdasarkan semangat Huminodun, iaitu kesanggupan berkorban demi menyelamatkan generasi.', 3),
(1047, 109, 603, 'e6_n3_s6', 'Kini pemenang juga dipilih berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau. Tauke, padankan Gawai dan Unduk Ngadau dahulu dan kini!', 4),
(1192, 121, 701, NULL, 'Tugasku ialah memastikan rakyat mengenali pemimpin negara mereka. Jika wartawan berhenti bertanya, sejarah pun senyap, {nama}. Terima kasih kerana meminjamkan suaramu!', 1),
(1193, 121, 701, NULL, 'Setiap Perdana Menteri membawa tugas dan pencapaian sendiri. Apabila kita mengenali mereka, kita menghargai perjalanan negara dari kemerdekaan hingga kini.', 2),
(1194, 121, 701, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, wartawan muda dengan kad akhbar di leher dan mikrofon di tangan. Kamera sudah menyala, siaran khas bermula! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(1195, 132, 701, 'e7_n1_s1', 'Wartawan muda, selamat datang! Beta Yang di-Pertuan Agong, Ketua Utama Negara. Hari ini kau bertanya tentang jawatan Perdana Menteri, bukan?', 1),
(1196, NULL, 701, 'e7_n1_s1', 'Betul, Tuanku! Kamera sudah merakam. Siapakah yang mengetuai pentadbiran negara kita, Tuanku?', 2),
(1197, 124, 701, 'e7_n1_s1', 'Itu kerja Perdana Menteri, wartawan! Beliau ialah Ketua Kerajaan yang mengetuai pentadbiran negara. Akulah orang pertama memegang jawatan itu, tahu?', 3),
(1198, 132, 701, 'e7_n1_s1', 'Dan Perdana Menteri dilantik secara rasmi oleh Beta. Itulah pembahagian tugasnya: Beta Ketua Utama Negara, Perdana Menteri Ketua Kerajaan.', 4),
(1199, 124, 701, 'e7_n1_s1', 'Jawatan ini diwujudkan selepas kemerdekaan, dan ia kekal hingga hari ini. Dari aku sampai ke Perdana Menteri seterusnya, wartawan!', 5),
(1200, NULL, 701, 'e7_n1_s1', 'Catatan penuh! Ketua Kerajaan, dilantik oleh Yang di-Pertuan Agong, diwujudkan selepas kemerdekaan dan kekal hingga kini. Betul, Tunku?', 6),
(1201, 124, 701, 'e7_n1_s1', 'Betul, wartawan! Tapi Tunku nak uji sedikit sebelum siaran bersambung. Siapakah yang melantik Perdana Menteri secara rasmi?', 7),
(1202, NULL, 701, 'e7_n1_s2', 'Hadirin sekalian, ini sesi gambar barisan Perdana Menteri Malaysia! Satu persatu, sila kenalkan diri mengikut giliran. Mikrofon dihidupkan!', 1),
(1203, 124, 701, 'e7_n1_s2', 'Aku Tunku Abdul Rahman Putra Al-Haj, Perdana Menteri pertama. Giliran pertama, jadi aku bercakap dahulu, wartawan!', 2),
(1204, 125, 701, 'e7_n1_s2', 'Tun Abdul Razak bin Hussein, Perdana Menteri kedua. Aku berdiri tepat selepas Tunku.', 3),
(1205, 126, 701, 'e7_n1_s2', 'Tun Hussein bin Onn, Perdana Menteri ketiga. Tiga ialah nombor yang cantik, bukan?', 4),
(1206, 127, 701, 'e7_n1_s2', 'Tun Dr. Mahathir bin Mohamad. Aku Perdana Menteri keempat, dan sekali lagi Perdana Menteri ketujuh! Dua giliran, seorang aku!', 5),
(1207, 128, 701, 'e7_n1_s2', 'Tun Abdullah bin Ahmad Badawi, Perdana Menteri kelima. Hadir, wartawan!', 6),
(1208, 129, 701, 'e7_n1_s2', 'Dato\' Sri Mohd Najib bin Tun Abdul Razak, Perdana Menteri keenam. Senyum untuk kamera!', 7),
(1209, 130, 701, 'e7_n1_s2', 'Tan Sri Muhyiddin bin Md Yassin, Perdana Menteri kelapan, selepas Tun Dr. Mahathir kali kedua.', 8),
(1210, 131, 701, 'e7_n1_s2', 'Dato\' Seri Ismail Sabri bin Yaakob, Perdana Menteri kesembilan! Akulah penutup barisan.', 9),
(1211, 124, 701, 'e7_n1_s2', 'Wartawan, kad temu bualmu bercampur-aduk! Sebelum menyusunnya, jawab soalan Tunku: siapakah Perdana Menteri keempat?', 10),
(1212, 132, 701, 'e7_n1_s3', 'Wartawan, bilik ini ialah tempat Mesyuarat Majlis Raja-Raja. Perdana Menteri mengiringi Beta ke sini, kerana beliau Penasihat kepada Yang di-Pertuan Agong.', 1),
(1213, 125, 701, 'e7_n1_s3', 'Itu tugas pertama, wartawan. Aku mengiringi Yang di-Pertuan Agong ke Mesyuarat Majlis Raja-Raja sebagai penasihat. Berdiri tegak, senyum sedikit!', 2),
(1214, 126, 701, 'e7_n1_s3', 'Tugas kedua: mencadangkan senarai Jemaah Menteri. Aku juga mempengerusikan Mesyuarat Jemaah Menteri bagi menteri yang dilantik oleh Yang di-Pertuan Agong.', 3),
(1215, 128, 701, 'e7_n1_s3', 'Tugas ketiga: Ketua Pentadbir Utama! Aku merancang dan menyelaraskan semua dasar negara, dan memastikan pembangunan ditingkatkan demi kesejahteraan rakyat.', 4),
(1216, 132, 701, 'e7_n1_s3', 'Tugas keempat: menjalin hubungan diplomatik. Perdana Menteri mencadangkan pelantikan duta, diplomat dan konsulat untuk menjalin kerjasama dengan negara luar.', 5),
(1217, NULL, 701, 'e7_n1_s3', 'Empat tugas, empat tajuk berita! Penasihat, Jemaah Menteri, Ketua Pentadbir Utama dan Hubungan Diplomatik. Nanti saya padankan!', 6),
(1218, 125, 701, 'e7_n1_s3', 'Sebelum itu, soalan pantas. Tugas mencadangkan pelantikan duta, diplomat dan konsulat termasuk dalam tugas yang mana?', 7),
(1219, 124, 701, 'e7_n1_s4', 'Wartawan! Ini Stadium Merdeka. Aku memperjuangkan kemerdekaan secara rundingan, bukan secara perang. Bijak, bukan?', 1),
(1220, NULL, 701, 'e7_n1_s4', 'Bijak sekali, Tunku! Dan apakah lagi yang Tunku capai?', 2),
(1221, 124, 701, 'e7_n1_s4', 'Pada 16 September 1963, aku merealisasikan Pembentukan Malaysia. Itulah dua pencapaian besarku!', 3),
(1222, 125, 701, 'e7_n1_s4', 'Aku Tun Abdul Razak. Selepas peristiwa 13 Mei 1969, aku mengembalikan keamanan menerusi Majlis Gerakan Negara, atau MAGERAN.', 4),
(1223, 125, 701, 'e7_n1_s4', 'Aku juga memperkenalkan Dasar Ekonomi Baru (DEB) untuk membasmi kemiskinan dan menyusun semula masyarakat.', 5),
(1224, 126, 701, 'e7_n1_s4', 'Giliran aku, Tun Hussein Onn! Aku memperkenalkan Amanah Saham Nasional Berhad (ASNB) untuk pemilikan saham bumiputera.', 6),
(1225, 126, 701, 'e7_n1_s4', 'Aku juga memperkenalkan Program Rukun Tetangga untuk perpaduan. Jiran bertegur sapa, negara pun aman!', 7),
(1226, 124, 701, 'e7_n1_s4', 'Wartawan, cari bukti pada gambar stadium ini. Tapi dahulu soalan Tunku: pada tarikh manakah Pembentukan Malaysia direalisasikan?', 8),
(1227, 127, 701, 'e7_n1_s5', 'Wartawan, tengok pemandangan ini! Aku Tun Dr. Mahathir. Aku memperkenalkan Wawasan 2020, wawasan untuk membawa negara ke hadapan!', 1),
(1228, 127, 701, 'e7_n1_s5', 'Pembinaan Putrajaya, KLIA dan Menara Berkembar Petronas (KLCC) berlaku pada zamanku. Menara kembar itu kebanggaan kita!', 2),
(1229, 127, 701, 'e7_n1_s5', 'Aku juga menubuhkan HICOM untuk industri berteknologi tinggi. Kilang dan mesin moden, itulah matlamatnya!', 3),
(1230, 128, 701, 'e7_n1_s5', 'Aku Tun Abdullah Ahmad Badawi, wartawan. Aku memperkenalkan Koridor Wilayah Ekonomi dan Pelan Integriti Nasional, atau PIN.', 4),
(1231, 128, 701, 'e7_n1_s5', 'PIN ialah Pelan Integriti Nasional. Ingat singkatan itu, ya! Sebut sekali lagi: P-I-N.', 5),
(1232, NULL, 701, 'e7_n1_s5', 'Dua Perdana Menteri, banyak pencapaian! Wawasan 2020, Putrajaya, KLIA, KLCC, HICOM, Koridor Wilayah Ekonomi dan PIN. Saya catat semua!', 6),
(1233, 127, 701, 'e7_n1_s5', 'Wartawan, nota di tanganmu itu luntur. Tapi dahulu, jawab soalanku: Wawasan 2020 diperkenalkan oleh siapa?', 7),
(1234, 129, 701, 'e7_n1_s6', 'Wartawan, aku Dato\' Sri Mohd Najib bin Tun Abdul Razak. Aku memperkenalkan Gagasan 1Malaysia dan Program Transformasi Kerajaan, atau GTP.', 1),
(1235, 129, 701, 'e7_n1_s6', 'Satu ialah gagasan, satu lagi ialah program. Jangan tertukar, ya! Nanti siaran songsang.', 2),
(1236, 130, 701, 'e7_n1_s6', 'Aku Tan Sri Muhyiddin bin Md Yassin. Aku menubuhkan Majlis Tindakan Ekonomi (MTE) dan mengumumkan bantuan kewangan serta peruntukan besar semasa Perintah Kawalan Pergerakan (PKP).', 3),
(1237, 130, 701, 'e7_n1_s6', 'Itu semasa pandemik COVID-19, wartawan. Rakyat duduk di rumah dan bantuan pun diumumkan.', 4),
(1238, 131, 701, 'e7_n1_s6', 'Aku Dato\' Seri Ismail Sabri bin Yaakob. Aku memperkenalkan konsep Keluarga Malaysia.', 5),
(1239, 131, 701, 'e7_n1_s6', 'Keluarga Malaysia meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia. Semua ada tempat di meja makan!', 6),
(1240, NULL, 701, 'e7_n1_s6', 'Najib: 1Malaysia dan GTP. Muhyiddin: MTE dan bantuan semasa PKP. Ismail Sabri: Keluarga Malaysia. Siaran khas ditutup dengan kemas!', 7),
(1241, 131, 701, 'e7_n1_s6', 'Soalan penutup untukmu, wartawan: Keluarga Malaysia meraikan keterangkuman apa?', 8),
(1242, 122, 702, NULL, 'Tugasku ialah memastikan murid-murid mengenali pemimpin yang membina negara mereka. Jika guru berhenti bercerita, buku teks hanya jadi kertas, {nama}. Terima kasih kerana meminjamkan suaramu!', 1),
(1243, 122, 702, NULL, 'Para Perdana Menteri bukan sekadar nama dalam buku. Mereka mempunyai tugas, giliran dan pencapaian yang boleh kita pelajari untuk menghargai perjalanan negara.', 2),
(1244, 122, 702, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, guru yang paling disayangi murid-muridnya. Kapur sudah di tangan dan buku teks Unit 7 mula berpendar. Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(1245, NULL, 702, 'e7_n2_s1', 'Murid-murid, buka buku teks Unit 7! Eh, kenapa halaman ini berpendar? Ada orang keluar dari buku!', 1),
(1246, 124, 702, 'e7_n2_s1', 'Cikgu! Aku Tunku Abdul Rahman, tersangkut dalam bab Peranan Jawatan Perdana Menteri. Tolong tarik aku keluar!', 2),
(1247, 132, 702, 'e7_n2_s1', 'Beta Yang di-Pertuan Agong, Ketua Utama Negara. Cikgu, Beta yang melantik Perdana Menteri secara rasmi.', 3),
(1248, 124, 702, 'e7_n2_s1', 'Dan aku, sebagai Perdana Menteri, ialah Ketua Kerajaan yang mengetuai pentadbiran negara. Dua ketua, dua tugas berbeza, cikgu!', 4),
(1249, 132, 702, 'e7_n2_s1', 'Jawatan Perdana Menteri diwujudkan selepas kemerdekaan, dan kekal hingga kini. Murid-murid tak perlu cari tarikh pemansuhan, kerana tiada!', 5),
(1250, NULL, 702, 'e7_n2_s1', 'Faham! Ketua Kerajaan, dilantik oleh Yang di-Pertuan Agong. Tapi nota di papan putih ini sudah luntur!', 6),
(1251, 124, 702, 'e7_n2_s1', 'Cikgu, sebelum cikgu baca nota itu, jawab soalan Tunku: Perdana Menteri ialah ketua apa?', 7),
(1252, NULL, 702, 'e7_n2_s2', 'Baik, panggilan nama! Satu persatu, sebut giliran masing-masing. Cikgu ada kad kehadiran sembilan keping!', 1),
(1253, 124, 702, 'e7_n2_s2', 'Hadir! Tunku Abdul Rahman Putra Al-Haj, Perdana Menteri pertama.', 2),
(1254, 125, 702, 'e7_n2_s2', 'Hadir, cikgu! Tun Abdul Razak bin Hussein, Perdana Menteri kedua.', 3),
(1255, 126, 702, 'e7_n2_s2', 'Hadir! Tun Hussein bin Onn, Perdana Menteri ketiga.', 4),
(1256, 127, 702, 'e7_n2_s2', 'Hadir dua kali, cikgu! Tun Dr. Mahathir bin Mohamad, Perdana Menteri keempat dan juga ketujuh. Kad kehadiran aku dua keping!', 5),
(1257, 128, 702, 'e7_n2_s2', 'Tun Abdullah bin Ahmad Badawi, Perdana Menteri kelima. Hadir!', 6),
(1258, 129, 702, 'e7_n2_s2', 'Dato\' Sri Mohd Najib bin Tun Abdul Razak, keenam. Hadir, cikgu!', 7),
(1259, 130, 702, 'e7_n2_s2', 'Tan Sri Muhyiddin bin Md Yassin, kelapan. Hadir!', 8),
(1260, 131, 702, 'e7_n2_s2', 'Dato\' Seri Ismail Sabri bin Yaakob, kesembilan. Hadir, penutup senarai!', 9),
(1261, 127, 702, 'e7_n2_s2', 'Cikgu, kad kehadiran aku dua keping tadi. Sebelum cikgu padankan, jawab: aku Perdana Menteri yang keberapa?', 10);
INSERT INTO `DialogueLine` (`dialogueID`, `npcID`, `narrativeID`, `sceneID`, `dialogueLine`, `sequenceOrder`) VALUES
(1262, NULL, 702, 'e7_n2_s3', 'Murid-murid, hari ini papan tugas Perdana Menteri ada empat petak. Setiap petak dijaga oleh seorang tetamu dari buku teks!', 1),
(1263, 132, 702, 'e7_n2_s3', 'Petak pertama dijaga Beta. Perdana Menteri ialah Penasihat kepada Yang di-Pertuan Agong dan mengiringi Beta ke Mesyuarat Majlis Raja-Raja.', 2),
(1264, 126, 702, 'e7_n2_s3', 'Petak kedua aku jaga! Perdana Menteri mencadangkan senarai Jemaah Menteri dan mempengerusikan Mesyuarat Jemaah Menteri bagi menteri yang dilantik oleh Yang di-Pertuan Agong.', 3),
(1265, 127, 702, 'e7_n2_s3', 'Petak ketiga: Ketua Pentadbir Utama! Perdana Menteri merancang dan menyelaraskan semua dasar negara, serta memastikan pembangunan ditingkatkan demi kesejahteraan rakyat.', 4),
(1266, 125, 702, 'e7_n2_s3', 'Petak keempat milik aku: hubungan diplomatik. Perdana Menteri mencadangkan pelantikan duta, diplomat dan konsulat untuk menjalin kerjasama dengan negara luar.', 5),
(1267, NULL, 702, 'e7_n2_s3', 'Empat petak, empat tugas! Murid-murid, bantu cikgu jawab soalan daripada tetamu kita ini.', 6),
(1268, 126, 702, 'e7_n2_s3', 'Cikgu! Mesyuarat Jemaah Menteri, siapakah yang mempengerusikannya?', 7),
(1269, NULL, 702, 'e7_n2_s4', 'Eh, halaman buku teks bertukar jadi jalan lengang. Murid-murid, jangan takut, ini ingatan sejarah!', 1),
(1270, 124, 702, 'e7_n2_s4', 'Cikgu, aku Tunku. Aku memperjuangkan kemerdekaan secara rundingan, dan pada 16 September 1963 aku merealisasikan Pembentukan Malaysia.', 2),
(1271, 125, 702, 'e7_n2_s4', 'Tun Abdul Razak di sini. Jalan ini sunyi selepas peristiwa 13 Mei 1969. Aku mengembalikan keamanan menerusi Majlis Gerakan Negara (MAGERAN).', 3),
(1272, 125, 702, 'e7_n2_s4', 'Aku juga memperkenalkan Dasar Ekonomi Baru (DEB) untuk membasmi kemiskinan dan menyusun semula masyarakat.', 4),
(1273, 126, 702, 'e7_n2_s4', 'Aku Tun Hussein Onn. Aku memperkenalkan Amanah Saham Nasional Berhad (ASNB) untuk pemilikan saham bumiputera.', 5),
(1274, 126, 702, 'e7_n2_s4', 'Dan Program Rukun Tetangga untuk perpaduan. Jiran bertegur sapa, negara aman, cikgu!', 6),
(1275, NULL, 702, 'e7_n2_s4', 'Empat peristiwa ini bercampur-baur. Cikgu mahu susun mengikut urutan, tapi murid-murid keliru!', 7),
(1276, 125, 702, 'e7_n2_s4', 'Sebelum cikgu susun, jawab dahulu. MAGERAN itu kepanjangan apa?', 8),
(1277, 127, 702, 'e7_n2_s5', 'Cikgu! Buku teks ini jadi bandar. Aku Tun Dr. Mahathir, dan inilah Wawasan 2020 aku!', 1),
(1278, 127, 702, 'e7_n2_s5', 'Pembinaan Putrajaya, KLIA dan Menara Berkembar Petronas (KLCC) berlaku pada zamanku, cikgu!', 2),
(1279, 127, 702, 'e7_n2_s5', 'Kilang itu pula berkait dengan HICOM, yang aku tubuhkan untuk industri berteknologi tinggi.', 3),
(1280, 128, 702, 'e7_n2_s5', 'Aku Tun Abdullah Ahmad Badawi, cikgu. Pencapaianku ialah Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).', 4),
(1281, 128, 702, 'e7_n2_s5', 'Koridor itu ekonomi, PIN itu integriti. Dua perkara berbeza, jangan tertukar, ya!', 5),
(1282, NULL, 702, 'e7_n2_s5', 'Murid-murid, mari cari bukti pencapaian Tun Dr. Mahathir pada gambar bandar ini. Tunjukkan dengan jari!', 6),
(1283, 127, 702, 'e7_n2_s5', 'Sebelum itu, soalan aku: HICOM ditubuhkan untuk industri jenis apa?', 7),
(1284, NULL, 702, 'e7_n2_s6', 'Murid-murid, bab terakhir! Tiga Perdana Menteri terakhir dalam senarai. Siapa mahu mula?', 1),
(1285, 129, 702, 'e7_n2_s6', 'Aku Dato\' Sri Najib, cikgu. Aku memperkenalkan Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP).', 2),
(1286, 130, 702, 'e7_n2_s6', 'Tan Sri Muhyiddin di sini. Aku menubuhkan Majlis Tindakan Ekonomi (MTE) dan mengumumkan bantuan kewangan serta peruntukan besar semasa PKP pandemik COVID-19.', 3),
(1287, 131, 702, 'e7_n2_s6', 'Aku Dato\' Seri Ismail Sabri. Aku memperkenalkan Keluarga Malaysia, konsep yang meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.', 4),
(1288, NULL, 702, 'e7_n2_s6', 'Terima kasih, tuan-tuan! Murid-murid, catat: 1Malaysia dan GTP, MTE dan bantuan PKP, Keluarga Malaysia. Eh, kertas tugasan cikgu luntur sedikit!', 5),
(1289, 129, 702, 'e7_n2_s6', 'Cikgu, aku tanya dahulu sebelum cikgu baca: GTP itu apa?', 6),
(1290, 123, 703, NULL, 'Tugasku ialah mengumpul semua kad supaya kawan-kawan mengenali pemimpin negara. Jika murid berhenti menyelidik, album pun tinggal kosong, {nama}. Terima kasih kerana meminjamkan tanganmu!', 1),
(1291, 123, 703, NULL, 'Setiap kad dalam album itu ialah satu cerita tentang pemimpin negara. Apabila kita menyusunnya dengan betul, sejarah menjadi mudah diingat.', 2),
(1292, 123, 703, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, murid yang bersemangat dengan album kad kosong dan pensel di telinga. Projek besar bermula sekarang! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(1293, NULL, 703, 'e7_n3_s1', 'Projekku: album kad koleksi Perdana Menteri! Tapi kad pertama masih kosong. Ayuh cari maklumat di Wilayah Persekutuan!', 1),
(1294, 132, 703, 'e7_n3_s1', 'Wahai murid penyelidik, Beta Yang di-Pertuan Agong. Beta ialah Ketua Utama Negara, dan Beta melantik Perdana Menteri secara rasmi.', 2),
(1295, 124, 703, 'e7_n3_s1', 'Aku Tunku. Perdana Menteri ialah Ketua Kerajaan yang mengetuai pentadbiran negara. Tulis di kad pertama, murid!', 3),
(1296, 124, 703, 'e7_n3_s1', 'Jawatan ini diwujudkan selepas kemerdekaan. Dan lihat, ia kekal hingga kini. Kad ini takkan lapuk!', 4),
(1297, 132, 703, 'e7_n3_s1', 'Ingat pesan Beta: Ketua Utama Negara melantik, Ketua Kerajaan mentadbir. Dua jawatan, dua peranan.', 5),
(1298, NULL, 703, 'e7_n3_s1', 'Tulis! Ketua Kerajaan, dilantik oleh Yang di-Pertuan Agong, diwujudkan selepas kemerdekaan, kekal hingga kini. Wah, kad pertama penuh!', 6),
(1299, 124, 703, 'e7_n3_s1', 'Murid, soalan pantas Tunku: jawatan Perdana Menteri diwujudkan bila?', 7),
(1300, NULL, 703, 'e7_n3_s2', 'Kad kedua hingga kesembilan dalam album masih bercampur. Aku mesti letak ikut giliran Perdana Menteri. Tolong, tuan-tuan!', 1),
(1301, 124, 703, 'e7_n3_s2', 'Kad pertama sudah milik aku, Tunku Abdul Rahman Putra Al-Haj, Perdana Menteri pertama.', 2),
(1302, 125, 703, 'e7_n3_s2', 'Kad kedua: Tun Abdul Razak bin Hussein. Kemudian kad ketiga milik Tun Hussein bin Onn.', 3),
(1303, 126, 703, 'e7_n3_s2', 'Betul! Aku ketiga. Kemudian Tun Dr. Mahathir bin Mohamad pula, yang keempat.', 4),
(1304, 127, 703, 'e7_n3_s2', 'Aku muncul dua kali dalam album: keempat dan ketujuh. Jangan lupa tampal dua kad untukku!', 5),
(1305, 128, 703, 'e7_n3_s2', 'Kad kelima: Tun Abdullah bin Ahmad Badawi, murid. Selepas Tun Dr. Mahathir yang keempat.', 6),
(1306, 129, 703, 'e7_n3_s2', 'Kad keenam: Dato\' Sri Mohd Najib bin Tun Abdul Razak. Letak elok-elok, ya!', 7),
(1307, 130, 703, 'e7_n3_s2', 'Selepas kad ketujuh Tun Dr. Mahathir, kad kelapan ialah aku, Tan Sri Muhyiddin bin Md Yassin.', 8),
(1308, 131, 703, 'e7_n3_s2', 'Dan kad kesembilan, penutup album: Dato\' Seri Ismail Sabri bin Yaakob. Selesai!', 9),
(1309, 127, 703, 'e7_n3_s2', 'Murid, sebelum album ditutup, soalan aku: dalam album ini, aku diletakkan pada giliran yang mana?', 10),
(1310, NULL, 703, 'e7_n3_s3', 'Kad tugas Perdana Menteri ada empat. Ayuh, tuan-tuan, isi kad ini bersama-sama! Pensel sedia!', 1),
(1311, 132, 703, 'e7_n3_s3', 'Kad pertama daripada Beta: Perdana Menteri ialah Penasihat kepada Yang di-Pertuan Agong, dan mengiringi Beta ke Mesyuarat Majlis Raja-Raja.', 2),
(1312, 125, 703, 'e7_n3_s3', 'Kad kedua: mencadangkan senarai Jemaah Menteri. Perdana Menteri juga mempengerusikan Mesyuarat Jemaah Menteri bagi menteri yang dilantik oleh Yang di-Pertuan Agong.', 3),
(1313, 128, 703, 'e7_n3_s3', 'Kad ketiga: Ketua Pentadbir Utama. Merancang dan menyelaraskan semua dasar negara serta memastikan pembangunan ditingkatkan demi kesejahteraan rakyat.', 4),
(1314, 131, 703, 'e7_n3_s3', 'Kad keempat: hubungan diplomatik. Mencadangkan pelantikan duta, diplomat dan konsulat untuk menjalin kerjasama dengan negara luar.', 5),
(1315, NULL, 703, 'e7_n3_s3', 'Penuh! Tapi kad keempat luntur terkena air minuman. Tolong nyahkodkan!', 6),
(1316, 131, 703, 'e7_n3_s3', 'Sebelum itu, soalan aku: duta dan konsulat menjalin kerjasama dengan siapa?', 7),
(1317, NULL, 703, 'e7_n3_s4', 'Peta besar Pembentukan Malaysia terbentang di meja. Albumku kini ke halaman Tunku, Tun Abdul Razak dan Tun Hussein Onn!', 1),
(1318, 124, 703, 'e7_n3_s4', 'Murid, aku memperjuangkan kemerdekaan secara rundingan. Pada 16 September 1963, aku merealisasikan Pembentukan Malaysia.', 2),
(1319, 125, 703, 'e7_n3_s4', 'Selepas peristiwa 13 Mei 1969, aku mengembalikan keamanan menerusi MAGERAN. Aku juga memperkenalkan Dasar Ekonomi Baru (DEB).', 3),
(1320, 125, 703, 'e7_n3_s4', 'DEB bertujuan membasmi kemiskinan dan menyusun semula masyarakat. Ingat, murid: kemiskinan dibasmi, masyarakat disusun!', 4),
(1321, 126, 703, 'e7_n3_s4', 'Aku Tun Hussein Onn. Aku memperkenalkan ASNB supaya bumiputera memiliki saham, dan Program Rukun Tetangga untuk perpaduan.', 5),
(1322, NULL, 703, 'e7_n3_s4', 'Hebat! Kad-kadku makin bernilai. Tapi aku mahu padankan semuanya dahulu.', 6),
(1323, 124, 703, 'e7_n3_s4', 'Murid, soalan Tunku: kemerdekaan diperjuangkan secara apa?', 7),
(1324, NULL, 703, 'e7_n3_s5', 'Kad Tun Dr. Mahathir dan Tun Abdullah paling tebal. Aku di hadapan bangunan pentadbiran negara. Siapa tolong ceritakan?', 1),
(1325, 127, 703, 'e7_n3_s5', 'Murid penyelidik, aku Tun Dr. Mahathir. Kad aku penuh: Wawasan 2020, pembinaan Putrajaya, KLIA dan Menara Berkembar Petronas (KLCC).', 2),
(1326, 127, 703, 'e7_n3_s5', 'Dan kad HICOM juga, penubuhan untuk industri berteknologi tinggi. Susun betul-betul, nanti kad jatuh!', 3),
(1327, 128, 703, 'e7_n3_s5', 'Kad aku, Tun Abdullah Ahmad Badawi: Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).', 4),
(1328, NULL, 703, 'e7_n3_s5', 'Dua kad penuh! Nota lengkap: Wawasan 2020, Putrajaya, KLIA, KLCC, HICOM, Koridor Wilayah Ekonomi, PIN. Siap!', 5),
(1329, 128, 703, 'e7_n3_s5', 'Soalan aku, murid: PIN itu kepanjangan apa?', 6),
(1330, NULL, 703, 'e7_n3_s6', 'Kad terakhir album! Tiga kad: Perdana Menteri keenam, kelapan dan kesembilan. Siapa mula?', 1),
(1331, 129, 703, 'e7_n3_s6', 'Murid, aku Dato\' Sri Najib. Kad aku: Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP). Aku Perdana Menteri keenam.', 2),
(1332, 130, 703, 'e7_n3_s6', 'Aku Tan Sri Muhyiddin, Perdana Menteri kelapan. Kadku: Majlis Tindakan Ekonomi (MTE), serta bantuan kewangan dan peruntukan besar semasa PKP pandemik COVID-19.', 3),
(1333, 131, 703, 'e7_n3_s6', 'Aku Dato\' Seri Ismail Sabri, kesembilan. Kad aku: Keluarga Malaysia, yang meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.', 4),
(1334, NULL, 703, 'e7_n3_s6', 'Album siap! Tapi tiga kad ini mesti disusun ikut giliran Perdana Menteri.', 5),
(1335, 131, 703, 'e7_n3_s6', 'Murid, soalan penutup aku: konsep Keluarga Malaysia diperkenalkan oleh siapa?', 6),
(1448, 141, 801, NULL, 'Tugasku ialah memastikan mesin ladang terus berjalan supaya ekonomi tidak berhenti. Jika juruteknik berhenti, jentera pun senyap, {nama}. Terima kasih kerana meminjamkan tanganmu!', 1),
(1449, 141, 801, NULL, 'Ekonomi negara berkembang daripada cangkul kepada jentera, dan daripada ladang kepada industri. Apabila kita mengenali setiap kegiatan, kita menghargai kemajuan yang dicapai.', 2),
(1450, 141, 801, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, juruteknik yang tangannya sentiasa berminyak dan kotak peralatannya sentiasa berbunyi. Enjin sudah dihidupkan, kembara bermula! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(1451, 144, 801, 'e8_n1_s1', 'Anak muda juruteknik, lihat sawah ini! Ekonomi tradisional dijalankan secara kecil-kecilan, tahu? Satu keluarga, satu petak kecil.', 1),
(1452, NULL, 801, 'e8_n1_s1', 'Nampak bersih dan sederhana, Pak Tani. Apakah peralatan Pak Tani?', 2),
(1453, 144, 801, 'e8_n1_s1', 'Peralatan mudah sahaja: cangkul dan sabit. Modal kecil, tenaga kerja pun sedikit. Hasilnya untuk keperluan sendiri dan keluarga.', 3),
(1454, 145, 801, 'e8_n1_s1', 'Ha, tengok pula ladangku! Ekonomi komersial dijalankan secara perladangan. Peralatannya moden, seperti mesin dan jentera penuai!', 4),
(1455, 145, 801, 'e8_n1_s1', 'Modalnya besar, tenaga kerjanya banyak. Hasilnya untuk kegunaan tempatan dan juga dieksport ke luar negara!', 5),
(1456, NULL, 801, 'e8_n1_s1', 'Wah, bezanya jelas! Tradisional: kecil-kecilan, cangkul dan sabit, modal kecil, tenaga sedikit, untuk keluarga. Komersial: ladang, jentera, modal besar, tenaga banyak, tempatan dan eksport!', 6),
(1457, 144, 801, 'e8_n1_s1', 'Pandai! Sebelum cari bukti pada gambar sawah ini, soalan Pak Tani: ekonomi tradisional untuk keperluan siapa?', 7),
(1458, 146, 801, 'e8_n1_s2', 'Juruteknik! Ini kebun getah. Industri getah dan kelapa sawit meningkatkan pendapatan negara. Titisan susu getah ini bernilai!', 1),
(1459, 146, 801, 'e8_n1_s2', 'Industri ini juga menyediakan peluang pekerjaan. Aku menoreh getah, kau membaiki mesin. Ramai orang ada kerja!', 2),
(1460, 145, 801, 'e8_n1_s2', 'Di ladang sawit pula, industri ini mewujudkan industri hiliran. Hasilnya diproses menjadi pelbagai barangan, bukan dijual mentah sahaja!', 3),
(1461, 145, 801, 'e8_n1_s2', 'Ia juga memajukan industri asas tani, dan membangunkan industri biodiesel. Bahan api daripada sawit pun ada!', 4),
(1462, NULL, 801, 'e8_n1_s2', 'Lima kesan: pendapatan negara, peluang pekerjaan, industri hiliran, industri asas tani dan industri biodiesel. Mudah diingat!', 5),
(1463, 146, 801, 'e8_n1_s2', 'Cuba satu soalan: industri biodiesel dibangunkan hasil industri apa?', 6),
(1464, 147, 801, 'e8_n1_s3', 'Juruteknik, selamat datang ke pelantar minyak! Industri petroleum dan gas mewujudkan peluang pekerjaan. Aku jurutera, kau juruteknik, kita sama-sama bekerja!', 1),
(1465, 147, 801, 'e8_n1_s3', 'Industri ini juga melahirkan usahawan stesen minyak. Dari pelantar ke stesen, ramai orang berniaga!', 2),
(1466, 147, 801, 'e8_n1_s3', 'Pendapatan juga meningkat menerusi penajaan sukan permotoran. Syarikat menaja perlumbaan, rakyat pula bersorak!', 3),
(1467, 147, 801, 'e8_n1_s3', 'Dan industri ini menyediakan biasiswa. Ramai pelajar belajar dengan tenang berkat biasiswa ini!', 4),
(1468, NULL, 801, 'e8_n1_s3', 'Empat kesan: peluang pekerjaan, usahawan stesen minyak, pendapatan menerusi penajaan sukan permotoran dan biasiswa. Siap catat!', 5),
(1469, 147, 801, 'e8_n1_s3', 'Soalan pantas: industri petroleum dan gas melahirkan usahawan jenis apa?', 6),
(1470, 142, 801, 'e8_n1_s4', 'Juruteknik! Selamat datang ke kilang kereta. Industri automotif bermula dengan PROTON pada tahun 1983. Satu lagi nama besar ialah PERODUA, pada tahun 1993.', 1),
(1471, 142, 801, 'e8_n1_s4', 'PROTON juga mengadakan usaha sama dengan Geely Holding Group pada tahun 2018. Kereta rakyat, kilang kita!', 2),
(1472, NULL, 801, 'e8_n1_s4', 'PROTON 1983, PERODUA 1993, Geely 2018. Tapi apa pula kaitan industri pelancongan di sini?', 3),
(1473, 148, 801, 'e8_n1_s4', 'Aku pemandu pelancong! Kempen Tahun Melawat Malaysia dipacu oleh keistimewaan tapak dan bangunan bersejarah serta alam semula jadi.', 4),
(1474, 148, 801, 'e8_n1_s4', 'Keharmonian budaya dan agropelancongan juga memacunya. Pelancong suka melihat ladang dan kebun!', 5),
(1475, 148, 801, 'e8_n1_s4', 'Penganjuran sukan, muzik dan pameran antarabangsa pun menarik pelancong. Banyak sebab untuk melawat Malaysia!', 6),
(1476, 142, 801, 'e8_n1_s4', 'Sebelum susun garis masa, soalan inspektor: PERODUA ditubuhkan pada tahun berapa?', 7),
(1477, 143, 801, 'e8_n1_s5', 'Juruteknik! Selamat datang ke kedai barangan jenama Malaysia. Produk pertanian: minyak masak, buah durian, buah nanas dan sabun!', 1),
(1478, 143, 801, 'e8_n1_s5', 'Produk petroleum pula: minyak petrol, gas untuk memasak dan minyak pelincir kenderaan. Tong gas dan botol minyak semua ada!', 2),
(1479, 145, 801, 'e8_n1_s5', 'Produk automotif: motosikal dan kereta. Dua roda dan empat roda, semuanya jenama Malaysia!', 3),
(1480, NULL, 801, 'e8_n1_s5', 'Tiga kumpulan: pertanian, petroleum dan automotif. Eh, catatan tentang produk petroleum ini luntur sedikit!', 4),
(1481, 143, 801, 'e8_n1_s5', 'Tolong baca nanti, tetapi dahulu satu soalan: sabun termasuk dalam kumpulan produk apa?', 5),
(1482, 149, 801, 'e8_n1_s6', 'Juruteknik! Lihat bandar ini. Pembangunan bermakna kewujudan bangunan pencakar langit yang menjulang!', 1),
(1483, 149, 801, 'e8_n1_s6', 'Perhubungan pula: jaringan perhubungan moden yang terancang. Kereta api, jambatan layang dan lebuh raya semuanya bersambung kemas!', 2),
(1484, 149, 801, 'e8_n1_s6', 'Dan perdagangan: kegiatan e-dagang yang semakin berkembang. Aku jual barang melalui telefon dan sampai ke pintu rumah!', 3),
(1485, NULL, 801, 'e8_n1_s6', 'Wah, maju betul! Pembangunan, perhubungan dan perdagangan. Jom padankan!', 4),
(1486, 149, 801, 'e8_n1_s6', 'Soalan e-dagang untuk juruteknik: apakah kegiatan perdagangan yang semakin berkembang itu?', 5),
(1487, 142, 802, NULL, 'Tugasku ialah memastikan setiap produk lulus pemeriksaan sebelum sampai ke tangan rakyat. Jika inspektor berhenti memeriksa, mutu pun terabai, {nama}. Terima kasih kerana meminjamkan matamu!', 1),
(1488, 142, 802, NULL, 'Ekonomi yang kukuh dibina daripada banyak kegiatan yang saling menyokong. Apabila kita memeriksa setiap satu dengan teliti, kita menghargai kemajuan negara.', 2),
(1489, 142, 802, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, inspektor yang membawa papan klip dan cop LULUS di poket. Satu pemeriksaan besar bermula hari ini! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(1490, NULL, 802, 'e8_n2_s1', 'Inspektor kilang turun ke ladang! Borang pemeriksaan pertama: ekonomi tradisional atau komersial? Lihat dahulu, baru cop LULUS!', 1),
(1491, 145, 802, 'e8_n2_s1', 'Inspektor, ladang ini komersial! Dijalankan secara perladangan, dengan peralatan moden seperti mesin dan jentera penuai.', 2),
(1492, 145, 802, 'e8_n2_s1', 'Modal besar, tenaga kerja banyak. Hasilnya untuk kegunaan tempatan dan juga dieksport!', 3),
(1493, 144, 802, 'e8_n2_s1', 'Hmmph, aku masih setia dengan cara tradisional. Dijalankan kecil-kecilan, dengan cangkul dan sabit.', 4),
(1494, 144, 802, 'e8_n2_s1', 'Modal kecil, tenaga kerja sedikit. Hasilnya untuk keperluan sendiri dan keluarga. Cukup untuk dapur sendiri!', 5),
(1495, NULL, 802, 'e8_n2_s1', 'Dua jenis ekonomi, dua borang. Aku mahu padankan ciri dengan jenisnya. Cop sedia!', 6),
(1496, 145, 802, 'e8_n2_s1', 'Soalan inspektor, dengar baik-baik: mesin dan jentera penuai digunakan dalam ekonomi jenis apa?', 7),
(1497, 146, 802, 'e8_n2_s2', 'Inspektor, selamat datang ke ladang getah! Industri getah dan kelapa sawit meningkatkan pendapatan negara.', 1),
(1498, 146, 802, 'e8_n2_s2', 'Ia menyediakan peluang pekerjaan dan mewujudkan industri hiliran. Dari pokok ke kilang, sambung-menyambung!', 2),
(1499, 145, 802, 'e8_n2_s2', 'Ia juga memajukan industri asas tani, dan membangunkan industri biodiesel. Lima kesan semuanya, inspektor!', 3),
(1500, NULL, 802, 'e8_n2_s2', 'Lima kesan: pendapatan negara, peluang pekerjaan, industri hiliran, industri asas tani dan biodiesel. Cop LULUS untuk kelimanya!', 4),
(1501, 146, 802, 'e8_n2_s2', 'Eh, nanti dulu! Soalan semakan: kesan manakah yang berkait dengan peluang kerja untuk penoreh macam aku?', 5),
(1502, 147, 802, 'e8_n2_s3', 'Inspektor, kau tahu syarikat petroleum menaja perlumbaan ini? Industri petroleum dan gas meningkatkan pendapatan menerusi penajaan sukan permotoran!', 1),
(1503, 147, 802, 'e8_n2_s3', 'Industri ini juga mewujudkan peluang pekerjaan, melahirkan usahawan stesen minyak dan menyediakan biasiswa.', 2),
(1504, NULL, 802, 'e8_n2_s3', 'Ada sorakan, ada enjin! Empat kesan dalam satu litar: pekerjaan, usahawan stesen minyak, penajaan sukan permotoran dan biasiswa.', 3),
(1505, 147, 802, 'e8_n2_s3', 'Papan iklan itu luntur, inspektor. Tapi dahulu, jawab soalanku: apakah yang disediakan kepada pelajar oleh industri ini?', 4),
(1506, 148, 802, 'e8_n2_s4', 'Inspektor, kau tengok pantai ini? Kempen Tahun Melawat Malaysia dipacu oleh keistimewaan tapak dan bangunan bersejarah serta alam semula jadi!', 1),
(1507, 148, 802, 'e8_n2_s4', 'Keharmonian budaya dan agropelancongan juga menarik pelancong. Penganjuran sukan, muzik dan pameran antarabangsa pun sama!', 2),
(1508, NULL, 802, 'e8_n2_s4', 'Aku inspektor kilang kereta. Hairan juga kerjaku datang ke hutan! Tetapi PROTON ditubuhkan pada tahun 1983 dan PERODUA pada tahun 1993.', 3),
(1509, 148, 802, 'e8_n2_s4', 'Dan pada tahun 2018, PROTON mengadakan usaha sama dengan Geely Holding Group. Kereta kita sudah maju, inspektor!', 4),
(1510, 148, 802, 'e8_n2_s4', 'Jom cari bukti tarikan pelancong pada gambar ini! Tetapi dahulu, soalan: PROTON ditubuhkan pada tahun berapa?', 5),
(1511, NULL, 802, 'e8_n2_s5', 'Barisan pemeriksaan terakhir! Inspektor mahu semak barangan jenama Malaysia sebelum lulus. Satu persatu, ya!', 1),
(1512, 143, 802, 'e8_n2_s5', 'Produk pertanian: minyak masak, buah durian, buah nanas dan sabun, inspektor!', 2),
(1513, 143, 802, 'e8_n2_s5', 'Produk petroleum: minyak petrol, gas untuk memasak dan minyak pelincir kenderaan.', 3),
(1514, 143, 802, 'e8_n2_s5', 'Produk automotif: motosikal dan kereta. Yang ini memang bidang inspektor, bukan?', 4),
(1515, NULL, 802, 'e8_n2_s5', 'Baik! Tiga kumpulan, sembilan produk. Aku padankan semuanya sekarang!', 5),
(1516, 143, 802, 'e8_n2_s5', 'Soalan semakan: gas untuk memasak ialah produk apa?', 6),
(1517, 149, 802, 'e8_n2_s6', 'Inspektor! Lihat bandar ini. Pembangunan bermakna kewujudan bangunan pencakar langit.', 1),
(1518, 149, 802, 'e8_n2_s6', 'Perhubungan pula jaringan perhubungan moden yang terancang. Kereta api dan jambatan layang bersambung kemas!', 2),
(1519, 149, 802, 'e8_n2_s6', 'Dan perdagangan: e-dagang yang semakin berkembang. Barang terus sampai ke pintu rumah!', 3),
(1520, NULL, 802, 'e8_n2_s6', 'Pemeriksaan terakhir: cari bukti pembangunan, perhubungan dan perdagangan pada gambar ini.', 4),
(1521, 149, 802, 'e8_n2_s6', 'Sebelum itu, soalan inspektor: yang manakah kegiatan perdagangan yang semakin berkembang?', 5),
(1522, 143, 803, NULL, 'Tugasku ialah memperkenalkan barangan buatan negara sendiri kepada setiap pelanggan. Jika pemilik kedai berhenti bercerita, rak pun sunyi, {nama}. Terima kasih kerana meminjamkan suaramu!', 1),
(1523, 143, 803, NULL, 'Setiap barangan di rak membawa cerita tentang kegiatan ekonomi di sebaliknya. Apabila kita mengenalinya, kita lebih menghargai barangan buatan negara sendiri.', 2),
(1524, 143, 803, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemilik kedai yang bangga dengan setiap rak di kedainya. Papan tanda sudah dipasang dan pintu dibuka! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(1525, 144, 803, 'e8_n3_s1', 'Tauke kedai! Pak Tani jual beras sendiri di kampung ini. Ekonomi tradisional dijalankan kecil-kecilan, dengan peralatan mudah seperti cangkul dan sabit.', 1),
(1526, 144, 803, 'e8_n3_s1', 'Modal kecil, tenaga kerja sedikit, dan hasilnya untuk keperluan sendiri dan keluarga. Kedai Pak Tani cuma di pangkin rumah!', 2),
(1527, 145, 803, 'e8_n3_s1', 'Aku pula petani moden, tauke! Ekonomi komersial secara perladangan, dengan peralatan moden seperti mesin dan jentera penuai.', 3),
(1528, 145, 803, 'e8_n3_s1', 'Modal besar dan tenaga kerja banyak. Hasilnya untuk kegunaan tempatan dan eksport. Kedai tauke pun boleh jual ke luar negara!', 4),
(1529, NULL, 803, 'e8_n3_s1', 'Dua jenis ekonomi, kontras yang jelas. Tetapi lembaran nota ini luntur, tolong nyahkod!', 5),
(1530, 144, 803, 'e8_n3_s1', 'Sebelum itu soalan Pak Tani: peralatan ekonomi tradisional apa yang aku guna?', 6),
(1531, 145, 803, 'e8_n3_s2', 'Tauke, lihat ladang sawit ini! Industri getah dan kelapa sawit meningkatkan pendapatan negara.', 1),
(1532, 146, 803, 'e8_n3_s2', 'Dan menyediakan peluang pekerjaan. Aku menoreh getah, jiranku mengendalikan jentera, semua ada kerja!', 2),
(1533, 145, 803, 'e8_n3_s2', 'Industri hiliran pun diwujudkan, dan industri asas tani dimajukan.', 3),
(1534, 146, 803, 'e8_n3_s2', 'Industri biodiesel pun dibangunkan! Hasil sawit boleh menjadi bahan api, tauke.', 4),
(1535, NULL, 803, 'e8_n3_s2', 'Lima kesan, lima rak di kedai! Aku padankan kesan dengan kata kerjanya sekarang.', 5),
(1536, 145, 803, 'e8_n3_s2', 'Soalan pantas, tauke: lima kesan semuanya datang daripada industri apa?', 6),
(1537, 147, 803, 'e8_n3_s3', 'Tauke! Pelantar ini mengeluarkan minyak dan gas yang tauke jual dalam tong dan botol. Industri petroleum dan gas mewujudkan peluang pekerjaan.', 1),
(1538, 147, 803, 'e8_n3_s3', 'Ia melahirkan usahawan stesen minyak, dan meningkatkan pendapatan menerusi penajaan sukan permotoran.', 2),
(1539, 147, 803, 'e8_n3_s3', 'Industri ini juga menyediakan biasiswa. Pelajar pintar belajar dengan tenang!', 3),
(1540, NULL, 803, 'e8_n3_s3', 'Empat kesan, empat tin minyak di rak. Aku jawab soalan pelanggan dahulu!', 4),
(1541, 147, 803, 'e8_n3_s3', 'Tauke, soalan: yang manakah cara industri petroleum dan gas meningkatkan pendapatan?', 5),
(1542, 148, 803, 'e8_n3_s4', 'Tauke, litar ini tarikan pelancong! Penganjuran sukan, muzik dan pameran antarabangsa menarik pelancong ke Malaysia.', 1),
(1543, 148, 803, 'e8_n3_s4', 'Kempen Tahun Melawat Malaysia dipacu oleh tapak dan bangunan bersejarah, serta alam semula jadi.', 2),
(1544, 148, 803, 'e8_n3_s4', 'Keharmonian budaya dan agropelancongan juga memacunya. Banyak pilihan untuk pelancong!', 3),
(1545, 142, 803, 'e8_n3_s4', 'Aku inspektor kilang, tauke. Industri automotif bermula dengan PROTON pada tahun 1983, kemudian PERODUA pada tahun 1993.', 4),
(1546, 142, 803, 'e8_n3_s4', 'Pada tahun 2018, PROTON mengadakan usaha sama dengan Geely Holding Group. Kereta kita makin maju!', 5),
(1547, NULL, 803, 'e8_n3_s4', 'Susun kad dahulu, tauke! 1983, 1993, 2018. Tapi aku tanya dahulu satu soalan.', 6),
(1548, 142, 803, 'e8_n3_s4', 'Soalan inspektor: PROTON mengadakan usaha sama dengan syarikat apa pada tahun 2018?', 7),
(1549, NULL, 803, 'e8_n3_s5', 'Inilah rak kebanggaan kedaiku! Barangan jenama Malaysia di mana-mana.', 1),
(1550, 145, 803, 'e8_n3_s5', 'Tauke, produk pertanian: minyak masak, buah durian, buah nanas dan sabun. Semuanya bermula daripada ladang kita!', 2),
(1551, 147, 803, 'e8_n3_s5', 'Produk petroleum: minyak petrol, gas untuk memasak dan minyak pelincir kenderaan. Tong gas itu datang dari pelantar aku!', 3),
(1552, 142, 803, 'e8_n3_s5', 'Produk automotif: motosikal dan kereta. Semua keluaran Malaysia, tauke!', 4),
(1553, NULL, 803, 'e8_n3_s5', 'Tiga rak penuh! Sekarang pelanggan bertanya soalan di kaunter.', 5),
(1554, 145, 803, 'e8_n3_s5', 'Tauke, tolong jawab soalan pelanggan ini. Yang manakah produk pertanian?', 6),
(1555, 149, 803, 'e8_n3_s6', 'Tauke, kedai tauke patut ada laman web! Perdagangan e-dagang semakin berkembang. Pelanggan boleh membeli dari rumah!', 1),
(1556, 149, 803, 'e8_n3_s6', 'Pembangunan juga ketara: kewujudan bangunan pencakar langit yang menghiasi langit bandar.', 2),
(1557, 149, 803, 'e8_n3_s6', 'Dan perhubungan: jaringan perhubungan moden yang terancang, supaya barang cepat sampai.', 3),
(1558, NULL, 803, 'e8_n3_s6', 'Pembangunan, perhubungan dan perdagangan! Tiga kejayaan ekonomi negara. Tetapi nota ini luntur sedikit, tolong bantu!', 4),
(1559, 149, 803, 'e8_n3_s6', 'Soalan peniaga: yang manakah termasuk dalam perhubungan?', 5),
(1560, 161, 901, NULL, 'Tugasku ialah menyampaikan kejayaan atlet kita supaya seluruh negara bersorak bersama. Jika pengulas berhenti bersuara, stadium pun sunyi, {nama}. Terima kasih kerana meminjamkan suaramu!', 1),
(1561, 161, 901, NULL, 'Sukan membawa kebanggaan dan menyatukan rakyat pelbagai kaum. Apabila kita mengenali atlet, program dan tokohnya, kita bersorak dengan lebih bermakna.', 2),
(1562, 161, 901, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengulas sukan yang suaranya sudah serak sebelum perlawanan bermula. Mikrofon sudah dihidupkan, siaran langsung bermula! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(1563, 164, 901, 'e9_n1_s1', 'Pengulas muda! Selamat datang ke gelanggang. Aku Lee Chong Wei. Badminton diuruskan oleh Persatuan Badminton Malaysia, atau BAM!', 1),
(1564, 164, 901, 'e9_n1_s1', 'Atlet contoh kami: Punch Gunalan, Misbun Sidek dan aku sendiri. Rancak, bukan, barisan itu?', 2),
(1565, 164, 901, 'e9_n1_s1', 'Pencapaian kami: juara Piala Thomas lima kali! Pingat perak dan gangsa di Sukan Olimpik, serta juara Terbuka All England!', 3),
(1566, NULL, 901, 'e9_n1_s1', 'Dan kini beralih ke padang bola sepak, pendengar sekalian! Persatuan Bola Sepak Malaysia, atau FAM, menguruskannya. Atlet contohnya Soh Chin Ann, James Wong dan Safawi Rasid!', 4),
(1567, NULL, 901, 'e9_n1_s1', 'Bola sepak layak ke Sukan Olimpik Munich 1972 dan Moscow 1980, serta menjuarai Piala Suzuki AFF pada tahun 2010. Gol!', 5),
(1568, 164, 901, 'e9_n1_s1', 'Wah, pengulas hafal semuanya! Soalan aku: berapa kali Malaysia menjuarai Piala Thomas?', 6),
(1569, 179, 901, 'e9_n1_s2', 'Pengulas! Aku Dr. M. Jegathesan. Olahraga diuruskan oleh Kesatuan Olahraga Malaysia, atau KOM, yang dahulu dikenali sebagai KOAM.', 1),
(1570, 179, 901, 'e9_n1_s2', 'Atlet contohnya: aku, Rabuan Pit dan Watson Nyambek. Larian kami pantas, tahu?', 2),
(1571, 179, 901, 'e9_n1_s2', 'Kami meraih pingat emas 100m Sukan Asia pada tahun 1966 dan 1982, dan olahraga menjuarai Kejohanan Sukan SEA pada tahun 2017!', 3),
(1572, NULL, 901, 'e9_n1_s2', 'Dari trek ke padang hoki, pendengar sekalian! Konfederasi Hoki Malaysia, atau MHC, menguruskannya. Atlet contohnya Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi!', 4),
(1573, NULL, 901, 'e9_n1_s2', 'Hoki layak lapan kali ke Piala Dunia, dengan tempat ke-4 pada tahun 1975, serta menjadi naib juara Sukan Komanwel 1998. Hebat!', 5),
(1574, 179, 901, 'e9_n1_s2', 'Sebelum kau cari bukti pada gambar trek ini, soalan aku: pada tahun berapakah emas 100m Sukan Asia diraih?', 6),
(1575, NULL, 901, 'e9_n1_s3', 'Pendengar sekalian, di atas pentas inilah atlet kebanggaan negara! Aku memperkenalkan mereka satu persatu. Mikrofon sedia!', 1),
(1576, 164, 901, 'e9_n1_s3', 'Lee Chong Wei di sini! Bersama aku ada Nicol Ann David dan S. Kuhan. Kami bangga mewakili negara!', 2),
(1577, 167, 901, 'e9_n1_s3', 'Pandelela Rinong anak Pamg melambai! Di sebelahku Mohd Azizulhasni Awang dan Team Secret MY.', 3),
(1578, 170, 901, 'e9_n1_s3', 'Nurul Huda Abdullah di sini! Bersama Abdul Malek Mohamed Noor dan Bonnie Bunyau Gustin.', 4),
(1579, 173, 901, 'e9_n1_s3', 'Muhammad Ziyad bin Zolkefli hadir! Dengan Mohamad Ridzuan bin Mohamad Puzi dan Abdul Latif bin Romly.', 5),
(1580, NULL, 901, 'e9_n1_s3', 'Dua belas nama, satu pentas! Tetapi papan kemenangan ini luntur sedikit, tolong nyahkod senarai!', 6),
(1581, 164, 901, 'e9_n1_s3', 'Sebelum itu soalan Chong Wei: berapa orang atlet dalam senarai kebanggaan negara ini?', 7),
(1582, NULL, 901, 'e9_n1_s4', 'Pendengar sekalian, lihat stadium ini! Murid pelbagai kaum bermain bersama. Sukan ialah alat perpaduan dan keharmonian kaum!', 1),
(1583, 162, 901, 'e9_n1_s4', 'Pengulas! Program pertama ialah RIMUP, iaitu Rancangan Integrasi Murid untuk Perpaduan. Murid daripada sekolah berbeza bergabung!', 2),
(1584, 162, 901, 'e9_n1_s4', 'Program kedua ialah 1M1S, iaitu 1Murid 1Sukan. Setiap murid menyertai satu sukan. Tiada alasan duduk di bangku!', 3),
(1585, 162, 901, 'e9_n1_s4', 'Kejohanan MSSM ialah Majlis Sukan Sekolah Malaysia. Kemudian SUKMA, Temasya Sukan Malaysia, dan SUKIPT, Sukan Institusi Pendidikan Tinggi.', 4),
(1586, 162, 901, 'e9_n1_s4', 'Dan Sukan Paralimpik juga termasuk! Enam program semuanya. Pengulas, soalan jurulatih: apakah kepanjangan 1M1S?', 5),
(1587, NULL, 901, 'e9_n1_s5', 'Pendengar sekalian, selamat datang ke stadium Sukan SEA! Malaysia menjadi tuan rumah pada tahun 1965, 1971, 1977, 2001 dan 2017. Penganjuran ini merapatkan hubungan serantau!', 1),
(1588, 162, 901, 'e9_n1_s5', 'Pengulas, Piala Thomas berlangsung enam kali di Malaysia. Hoki Piala Dunia pula dua edisi.', 2),
(1589, 162, 901, 'e9_n1_s5', 'Sukan permotoran, iaitu Formula One dan Formula E, bermula pada 1991 dan 2000. Le Tour de Langkawi pula acara tahunan sejak 1996.', 3),
(1590, 162, 901, 'e9_n1_s5', 'Sukan Komanwel dianjurkan pada 1998, negara Asia pertama menjadi tuan rumah! Dan Piala Monsun kejohanan perahu layar sejak 2005.', 4),
(1591, NULL, 901, 'e9_n1_s5', 'Banyak penganjuran! Tapi kad tarikh Sukan SEA ini bercampur-aduk. Tolong susun!', 5),
(1592, 162, 901, 'e9_n1_s5', 'Sebelum susun, soalan jurulatih: berapa kali Piala Thomas berlangsung di Malaysia?', 6),
(1593, NULL, 901, 'e9_n1_s6', 'Pendengar sekalian, siaran terakhir kita! Di pentas ini berdiri tokoh inspirasi sukan negara. Mikrofon sedia!', 1),
(1594, 176, 901, 'e9_n1_s6', 'Beta Sultan Azlan Muhibbuddin Shah, tokoh inspirasi sukan negara. Selamat berjumpa, pengulas.', 2),
(1595, 177, 901, 'e9_n1_s6', 'Aku Dato\' Peter Velappan. Di sebelahku Dato\' Sieh Kok Chi!', 3),
(1596, 179, 901, 'e9_n1_s6', 'Dr. M. Jegathesan hadir lagi! Tadi aku di trek, sekarang di pentas tokoh.', 4),
(1597, 180, 901, 'e9_n1_s6', 'M. Rajamani di sini, bersama Tan Aik Huang dan Mokhtar Dahari.', 5),
(1598, NULL, 901, 'e9_n1_s6', 'Tujuh tokoh: Sultan Azlan Muhibbuddin Shah, Dato\' Peter Velappan, Dato\' Sieh Kok Chi, Dr. M. Jegathesan, M. Rajamani, Tan Aik Huang dan Mokhtar Dahari. Siaran ditutup dengan baik!', 6),
(1599, 177, 901, 'e9_n1_s6', 'Soalan penutup daripada Dato\' Peter Velappan: yang manakah ialah tokoh inspirasi sukan negara?', 7),
(1600, 162, 902, NULL, 'Melatih murid bukan sekadar mengajar teknik, {nama}. Kami mengajar mereka bermimpi besar seperti atlet negara. Terima kasih kerana menjadi pembantu jurulatih hari ini!', 1),
(1601, 162, 902, NULL, 'Sukan melahirkan atlet yang membawa kebanggaan dan menyatukan murid pelbagai kaum. Kita menghargai atlet dan tokohnya dengan menyertai sukan sendiri.', 2),
(1602, 162, 902, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, jurulatih yang wisel di lehernya tidak pernah berhenti berbunyi. Murid sudah beratur di padang, latihan pagi bermula! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(1603, 163, 902, 'e9_n2_s1', 'Cikgu! Hari ini latihan bola sepak. Tapi saya nak tahu dulu: siapa yang uruskan bola sepak negara?', 1),
(1604, NULL, 902, 'e9_n2_s1', 'Persatuan Bola Sepak Malaysia, atau FAM! Atlet contohnya Soh Chin Ann, James Wong dan Safawi Rasid. Catat dalam buku!', 2),
(1605, 163, 902, 'e9_n2_s1', 'Bola sepak pernah ke Olimpik tak, cikgu?', 3),
(1606, NULL, 902, 'e9_n2_s1', 'Pernah! Layak ke Sukan Olimpik Munich 1972 dan Moscow 1980, dan menjuarai Piala Suzuki AFF pada tahun 2010. Semangat!', 4),
(1607, 164, 902, 'e9_n2_s1', 'Jangan lupakan badminton, cikgu! Aku Lee Chong Wei. Persatuan Badminton Malaysia, atau BAM, uruskan kami bersama Punch Gunalan dan Misbun Sidek.', 5),
(1608, 164, 902, 'e9_n2_s1', 'Kami juara Piala Thomas lima kali, pingat perak dan gangsa Olimpik, serta juara Terbuka All England! Papan skor Olimpik ini luntur, tolong nyahkod!', 6),
(1609, 164, 902, 'e9_n2_s1', 'Sebelum nyahkod, soalan aku: siapa yang menguruskan badminton negara?', 7),
(1610, NULL, 902, 'e9_n2_s2', 'Murid-murid, padang hoki dahulu! Konfederasi Hoki Malaysia, atau MHC, menguruskan hoki. Atlet contohnya Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi.', 1),
(1611, 163, 902, 'e9_n2_s2', 'Hoki pernah ke Piala Dunia, cikgu?', 2),
(1612, NULL, 902, 'e9_n2_s2', 'Layak lapan kali! Tempat ke-4 pada tahun 1975, dan naib juara Sukan Komanwel 1998. Hebat, bukan?', 3),
(1613, 179, 902, 'e9_n2_s2', 'Cikgu, olahraga pun hebat! Aku Dr. M. Jegathesan. Kesatuan Olahraga Malaysia, atau KOM, dahulunya KOAM, uruskan olahraga.', 4),
(1614, 179, 902, 'e9_n2_s2', 'Atlet contoh: aku, Rabuan Pit dan Watson Nyambek. Emas 100m Sukan Asia pada 1966 dan 1982, serta juara Sukan SEA 2017!', 5),
(1615, 179, 902, 'e9_n2_s2', 'Soalan cabaran sebelum padanan: pada tahun berapa hoki mencapai tempat ke-4 di Piala Dunia?', 6),
(1616, NULL, 902, 'e9_n2_s3', 'Murid-murid, inilah atlet kebanggaan negara! Perhatikan nama mereka dan jangan tidur!', 1),
(1617, 164, 902, 'e9_n2_s3', 'Lee Chong Wei hadir! Bersama Nicol Ann David dan S. Kuhan, kami datang menyapa murid cikgu!', 2),
(1618, 167, 902, 'e9_n2_s3', 'Pandelela Rinong anak Pamg melambai! Di sebelahku Mohd Azizulhasni Awang dan Team Secret MY.', 3),
(1619, 172, 902, 'e9_n2_s3', 'Bonnie Bunyau Gustin di sini! Bersama Nurul Huda Abdullah dan Abdul Malek Mohamed Noor.', 4),
(1620, 175, 902, 'e9_n2_s3', 'Abdul Latif bin Romly pun sampai! Dengan Muhammad Ziyad bin Zolkefli dan Mohamad Ridzuan bin Mohamad Puzi.', 5),
(1621, NULL, 902, 'e9_n2_s3', 'Dua belas atlet kebanggaan negara! Murid-murid, tepuk tangan!', 6),
(1622, 164, 902, 'e9_n2_s3', 'Cikgu, soalan Chong Wei: kejohanan manakah yang badminton menjuarai lima kali?', 7),
(1623, NULL, 902, 'e9_n2_s4', 'Murid-murid, sukan bukan sekadar menang! Sukan ialah alat perpaduan dan keharmonian kaum!', 1),
(1624, 161, 902, 'e9_n2_s4', 'Betul, cikgu! Aku pengulas sukan. Program pertama RIMUP, iaitu Rancangan Integrasi Murid untuk Perpaduan.', 2),
(1625, 161, 902, 'e9_n2_s4', 'Kemudian 1M1S, iaitu 1Murid 1Sukan. Dan MSSM ialah Kejohanan Majlis Sukan Sekolah Malaysia!', 3),
(1626, 161, 902, 'e9_n2_s4', 'Untuk peringkat lebih tinggi ada SUKMA, Temasya Sukan Malaysia, dan SUKIPT, Sukan Institusi Pendidikan Tinggi.', 4),
(1627, 161, 902, 'e9_n2_s4', 'Jangan lupa Sukan Paralimpik, enam program semuanya! Cikgu, soalan: apakah maksud 1M1S?', 5),
(1628, NULL, 902, 'e9_n2_s5', 'Murid-murid, Malaysia menjadi tuan rumah banyak sukan antarabangsa! Pengulas, tolong terangkan!', 1),
(1629, 161, 902, 'e9_n2_s5', 'Dengan senang hati! Sukan SEA dianjurkan pada 1965, 1971, 1977, 2001 dan 2017. Ia merapatkan hubungan serantau!', 2),
(1630, 161, 902, 'e9_n2_s5', 'Piala Thomas berlangsung enam kali di sini, dan Hoki Piala Dunia dua edisi. Sukan permotoran, Formula One dan Formula E, bermula pada 1991 dan 2000.', 3),
(1631, 161, 902, 'e9_n2_s5', 'Le Tour de Langkawi pula acara tahunan sejak 1996. Sukan Komanwel 1998, negara Asia pertama menjadi tuan rumah, dan Piala Monsun kejohanan perahu layar sejak 2005!', 4),
(1632, 161, 902, 'e9_n2_s5', 'Cikgu, soalan pengulas: Le Tour de Langkawi dianjurkan sejak tahun berapa?', 5),
(1633, NULL, 902, 'e9_n2_s6', 'Murid-murid, sesi terakhir! Hormat kepada tokoh inspirasi sukan negara!', 1),
(1634, 176, 902, 'e9_n2_s6', 'Beta Sultan Azlan Muhibbuddin Shah. Selamat petang, jurulatih dan murid-murid!', 2),
(1635, 177, 902, 'e9_n2_s6', 'Aku Dato\' Peter Velappan. Di sebelahku Dato\' Sieh Kok Chi!', 3),
(1636, 179, 902, 'e9_n2_s6', 'Dr. M. Jegathesan datang lagi! Kali ini dengan M. Rajamani.', 4),
(1637, 181, 902, 'e9_n2_s6', 'Tan Aik Huang melambai! Bersama Mokhtar Dahari, kami tujuh tokoh inspirasi.', 5),
(1638, NULL, 902, 'e9_n2_s6', 'Tujuh tokoh: Sultan Azlan, Dato\' Peter Velappan, Dato\' Sieh Kok Chi, Dr. M. Jegathesan, M. Rajamani, Tan Aik Huang dan Mokhtar Dahari. Dinding ini luntur, tolong nyahkod!', 6),
(1639, 177, 902, 'e9_n2_s6', 'Sebelum nyahkod, soalan aku: ada berapa tokoh inspirasi sukan negara?', 7),
(1640, 163, 903, NULL, 'Setiap kad dalam buku skrapku ialah kisah kebanggaan, {nama}. Kini ada seorang lagi sahabat yang tahu ceritanya. Terima kasih kerana membantu!', 1),
(1641, 163, 903, NULL, 'Sukan menyatukan rakyat pelbagai kaum dan melahirkan atlet serta tokoh yang membanggakan negara. Kisah mereka layak dikenang oleh setiap murid.', 2),
(1642, 163, 903, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, murid yang beg sekolahnya penuh kad atlet dan keratan akhbar. Buku skrap terbuka, kisah kebanggaan negara menanti! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(1643, NULL, 903, 'e9_n3_s1', 'Wah, stadium Piala Thomas! Aku hendak minta tandatangan dalam buku skrapku!', 1),
(1644, 164, 903, 'e9_n3_s1', 'Hai, adik! Aku Lee Chong Wei. Badminton diuruskan oleh Persatuan Badminton Malaysia, BAM. Atlet contoh: Punch Gunalan, Misbun Sidek dan aku.', 2),
(1645, 164, 903, 'e9_n3_s1', 'Kami juara Piala Thomas lima kali, pingat perak dan gangsa Olimpik, serta juara Terbuka All England. Tulis dalam buku skrap kamu!', 3),
(1646, 161, 903, 'e9_n3_s1', 'Hai, adik! Aku pengulas sukan. Bola sepak diuruskan oleh FAM. Atlet contoh: Soh Chin Ann, James Wong dan Safawi Rasid.', 4),
(1647, 161, 903, 'e9_n3_s1', 'Bola sepak layak ke Olimpik Munich 1972 dan Moscow 1980, dan juara Piala Suzuki AFF 2010. Soalan pengulas: berapa kali Piala Thomas dijuarai?', 5),
(1648, NULL, 903, 'e9_n3_s2', 'Aku hendak masukkan hoki dan olahraga dalam buku skrap! Tolong ceritakan!', 1),
(1649, 162, 903, 'e9_n3_s2', 'Dengan senang hati! Hoki diuruskan Konfederasi Hoki Malaysia, MHC. Atlet contoh: Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi.', 2),
(1650, 162, 903, 'e9_n3_s2', 'Hoki layak lapan kali ke Piala Dunia, tempat ke-4 pada tahun 1975, dan naib juara Sukan Komanwel 1998!', 3),
(1651, 179, 903, 'e9_n3_s2', 'Olahraga pula diuruskan KOM, dahulu KOAM. Aku Dr. M. Jegathesan, bersama Rabuan Pit dan Watson Nyambek.', 4),
(1652, 179, 903, 'e9_n3_s2', 'Emas 100m Sukan Asia pada 1966 dan 1982, serta juara Sukan SEA 2017! Soalan aku: berapa kali hoki layak ke Piala Dunia?', 5),
(1653, NULL, 903, 'e9_n3_s3', 'Dua belas atlet kebanggaan di depan mata! Buku skrapku sudah sedia!', 1),
(1654, 164, 903, 'e9_n3_s3', 'Aku Lee Chong Wei! Di sebelahku Nicol Ann David dan S. Kuhan. Tandatangan dahulu, ya!', 2),
(1655, 167, 903, 'e9_n3_s3', 'Aku Pandelela Rinong anak Pamg. Bersama Mohd Azizulhasni Awang dan Team Secret MY, kami menanti!', 3),
(1656, 172, 903, 'e9_n3_s3', 'Aku Bonnie Bunyau Gustin! Dengan Nurul Huda Abdullah dan Abdul Malek Mohamed Noor!', 4),
(1657, 175, 903, 'e9_n3_s3', 'Aku Abdul Latif bin Romly. Muhammad Ziyad bin Zolkefli dan Mohamad Ridzuan bin Mohamad Puzi pun di sini!', 5),
(1658, NULL, 903, 'e9_n3_s3', 'Wah, dua belas tandatangan! Tetapi podium ini penuh bukti kebanggaan. Aku mesti cari semuanya!', 6),
(1659, 164, 903, 'e9_n3_s3', 'Cari bukti kebanggaan di podium ini, adik! Kami tunggu!', 7),
(1660, NULL, 903, 'e9_n3_s4', 'Cikgu, aku nampak poster program sukan! Apakah maknanya?', 1),
(1661, 162, 903, 'e9_n3_s4', 'Sukan ialah alat perpaduan dan keharmonian kaum! RIMUP ialah Rancangan Integrasi Murid untuk Perpaduan, dan 1M1S ialah 1Murid 1Sukan.', 2),
(1662, 162, 903, 'e9_n3_s4', 'MSSM ialah Kejohanan Majlis Sukan Sekolah Malaysia. SUKMA ialah Temasya Sukan Malaysia, dan SUKIPT ialah Sukan Institusi Pendidikan Tinggi.', 3),
(1663, 162, 903, 'e9_n3_s4', 'Ada juga Sukan Paralimpik! Enam program semuanya. Poster ini luntur sedikit, tolong nyahkod!', 4),
(1664, 162, 903, 'e9_n3_s4', 'Sebelum nyahkod, soalan cikgu: apakah kepanjangan SUKMA?', 5),
(1665, NULL, 903, 'e9_n3_s5', 'Aku hendak tahu semua sukan antarabangsa yang pernah diadakan di Malaysia!', 1),
(1666, 161, 903, 'e9_n3_s5', 'Sukan SEA pada 1965, 1971, 1977, 2001 dan 2017, merapatkan hubungan serantau! Piala Thomas berlangsung enam kali!', 2),
(1667, 161, 903, 'e9_n3_s5', 'Hoki Piala Dunia dua edisi. Sukan permotoran, Formula One dan Formula E, bermula pada 1991 dan 2000!', 3),
(1668, 162, 903, 'e9_n3_s5', 'Le Tour de Langkawi acara tahunan sejak 1996. Dan di stadium ini, Sukan Komanwel 1998, negara Asia pertama menjadi tuan rumah!', 4),
(1669, 162, 903, 'e9_n3_s5', 'Ada juga Piala Monsun, kejohanan perahu layar sejak 2005. Soalan cikgu: Piala Monsun ialah kejohanan apa?', 5),
(1670, NULL, 903, 'e9_n3_s6', 'Halaman terakhir buku skrapku: tokoh inspirasi sukan negara!', 1),
(1671, 176, 903, 'e9_n3_s6', 'Beta Sultan Azlan Muhibbuddin Shah. Selamat berjumpa, adik!', 2),
(1672, 177, 903, 'e9_n3_s6', 'Aku Dato\' Peter Velappan, bersama Dato\' Sieh Kok Chi!', 3),
(1673, 179, 903, 'e9_n3_s6', 'Dr. M. Jegathesan datang lagi, dengan M. Rajamani!', 4),
(1674, 182, 903, 'e9_n3_s6', 'Mokhtar Dahari di sini! Tan Aik Huang pun hadir. Tujuh tokoh semuanya!', 5),
(1675, NULL, 903, 'e9_n3_s6', 'Tujuh tokoh inspirasi! Tetapi satu nama pada dinding ini sudah pudar. Tolong nyahkod!', 6),
(1676, 181, 903, 'e9_n3_s6', 'Sebelum nyahkod, soalan Tan Aik Huang: ada berapa tokoh inspirasi sukan negara dalam senarai?', 7),
(1677, 221, 1001, NULL, 'Menjadi wakil muda bukan sekadar duduk di kerusi, {nama}. Kita membawa suara negara ke meja rundingan. Terima kasih kerana menemani aku sepanjang sidang ini!', 1),
(1678, 221, 1001, NULL, 'Malaysia berperanan aktif dalam hubungan antarabangsa melalui ASEAN, Komanwel, OIC dan PBB. Kerjasama dan perdamaian membawa kebaikan kepada semua.', 2),
(1679, 221, 1001, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, wakil muda yang membawa fail penuh nota ke sidang serantau. Pintu bilik mesyuarat dibuka, bendera-bendera berkibar! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(1680, 224, 1001, 'e10_n1_s1', 'Wakil muda, selamat tiba di bilik sidang serantau! Hari ini kita menjejak bagaimana negara-negara rantau ini berhimpun.', 1),
(1681, 224, 1001, 'e10_n1_s1', 'Pertubuhan pertama: SEAFET, Southeast Asia Friendship and Economic Treaty. Anggotanya Tanah Melayu, Thailand dan Filipina.', 2),
(1682, 224, 1001, 'e10_n1_s1', 'Pertubuhan kedua: ASA, Association of Southeast Asia. Anggotanya sama: Tanah Melayu, Thailand dan Filipina!', 3),
(1683, NULL, 1001, 'e10_n1_s1', 'Dua pertubuhan, tiga negara yang sama! Jadi yang ketiga lebih besar?', 4),
(1684, 231, 1001, 'e10_n1_s1', 'Betul! ASEAN, Association of Southeast Asian Nations. Anggotanya Malaysia, Indonesia, Thailand, Filipina dan Singapura. Aku wakil Indonesia!', 5),
(1685, 231, 1001, 'e10_n1_s1', 'Soalan aku sebelum kau memadankan nama: pertubuhan manakah yang anggotanya Malaysia, Indonesia, Thailand, Filipina dan Singapura?', 6),
(1686, 226, 1001, 'e10_n1_s2', 'Selamat datang, wakil muda! Aku utusan Komanwel. Keahlian kami terdiri daripada negara bekas tanah jajahan British.', 1),
(1687, 225, 1001, 'e10_n1_s2', 'Aku wakil PBB, Pertubuhan Bangsa-Bangsa Bersatu. Keahlian kami terbuka kepada semua negara!', 2),
(1688, 227, 1001, 'e10_n1_s2', 'Aku wakil OIC, Pertubuhan Kerjasama Islam. Kami terdiri daripada 57 buah negara Islam.', 3),
(1689, 228, 1001, 'e10_n1_s2', 'Aku duta NAM, Pergerakan Negara-negara Berkecuali. Kami 120 buah negara membangun di Asia, Afrika dan Amerika Selatan!', 4),
(1690, NULL, 1001, 'e10_n1_s2', 'Empat pertubuhan antarabangsa dan satu pertubuhan serantau, ASEAN. Aku mahu susun tarikh penubuhannya!', 5),
(1691, 227, 1001, 'e10_n1_s2', 'Sebelum menyusun, soalan aku: berapakah bilangan negara Islam dalam OIC?', 6),
(1692, 224, 1001, 'e10_n1_s3', 'Wakil muda, inilah ASEAN. Ditubuhkan pada 8 Ogos 1967 dan dianggotai 10 negara Asia Tenggara. Ibu pejabatnya di Jakarta, Indonesia.', 1),
(1693, 224, 1001, 'e10_n1_s3', 'Matlamatnya: keamanan dan kestabilan politik, pertumbuhan ekonomi, sosial dan budaya, latihan dan penyelidikan, serta meningkatkan taraf hidup.', 2),
(1694, 224, 1001, 'e10_n1_s3', 'Malaysia menjadi tuan rumah Mesyuarat Menteri Luar ASEAN dan membantu isu pencerobohan Vietnam di Kemboja.', 3),
(1695, 224, 1001, 'e10_n1_s3', 'Malaysia meredakan konflik di Selatan Filipina, mengutarakan penubuhan ZOPFAN dan menyertai SEAMEO!', 4),
(1696, NULL, 1001, 'e10_n1_s3', 'Banyak sumbangan! Tetapi dokumen ASEAN ini luntur sedikit, tolong nyahkod!', 5),
(1697, 224, 1001, 'e10_n1_s3', 'Sebelum nyahkod, soalan aku: apakah kepanjangan ZOPFAN?', 6),
(1698, 226, 1001, 'e10_n1_s4', 'Wakil muda, Komanwel dibentuk pada 11 Disember 1931 dan dianggotai 54 negara bekas jajahan British. Ibu pejabatnya di London, England!', 1),
(1699, 226, 1001, 'e10_n1_s4', 'Malaysia mengecam dan membantu menamatkan dasar Aparteid, menjadi tuan rumah CHOGM pada 1989 dan mengisytiharkan Deklarasi Langkawi 1989 untuk alam sekitar.', 2),
(1700, 227, 1001, 'e10_n1_s4', 'OIC pula ditubuhkan pada 25 September 1969, dianggotai 57 negara dengan ibu pejabat di Jeddah, Arab Saudi.', 3),
(1701, 230, 1001, 'e10_n1_s4', 'Beta, Tunku Abdul Rahman, dilantik sebagai Setiausaha Agung OIC yang pertama!', 4),
(1702, 227, 1001, 'e10_n1_s4', 'Malaysia membantu menubuhkan Bank Pembangunan Islam, menangani isu Bosnia dan Herzegovina pada 1991, menyokong perjuangan Palestin, dan menubuhkan UIAM pada 1983.', 5),
(1703, 227, 1001, 'e10_n1_s4', 'Malaysia juga menjadi tuan rumah Persidangan OIC pada 1974 dan 2003. Soalan aku: universiti manakah yang ditubuhkan pada 1983?', 6),
(1704, 225, 1001, 'e10_n1_s5', 'Wakil muda, inilah PBB! Ditubuhkan pada 24 Oktober 1945 dengan ibu pejabat di New York, Amerika Syarikat.', 1),
(1705, 225, 1001, 'e10_n1_s5', 'Malaysia membawa isu rakyat Palestin, mendesak usaha memerangi dadah dan menyarankan peningkatan mutu pendidikan.', 2),
(1706, 222, 1001, 'e10_n1_s5', 'Aku penjaga keamanan PBB! Malaysia menyertai pasukan pengaman, dan kami diiktiraf melalui sijil dan pingat perkhidmatan PBB!', 3),
(1707, 225, 1001, 'e10_n1_s5', 'Tokoh Malaysia pun terkenal: Tan Sri Razali Ismail ialah Pengerusi Majlis Keselamatan PBB (1989-1990) dan Pengerusi Perhimpunan Agung PBB sesi ke-51 (1996-1997).', 4),
(1708, 225, 1001, 'e10_n1_s5', 'Datuk Dr. Mazlan Othman pula Pengarah Hal Ehwal Angkasa Lepas PBB (1999-2002 dan 2007). Cari bukti di dewan ini!', 5),
(1709, 222, 1001, 'e10_n1_s5', 'Sebelum itu, soalan aku: apakah pengiktirafan PBB kepada pasukan pengaman Malaysia?', 6),
(1710, 223, 1001, 'e10_n1_s6', 'Selamat datang ke ruang UNESCO, wakil muda! Warisan Malaysia diiktiraf dunia di sini.', 1),
(1711, 223, 1001, 'e10_n1_s6', 'Tapak Warisan Dunia alam semula jadi pada tahun 2000: Taman Negara Gunung Mulu di Sarawak dan Taman Kinabalu di Sabah!', 2),
(1712, 223, 1001, 'e10_n1_s6', 'Tapak Warisan Dunia kebudayaan: Melaka dan George Town pada 2008, serta Warisan Arkeologi Lembah Lenggong pada 2012.', 3),
(1713, 223, 1001, 'e10_n1_s6', 'Daftar Memori Dunia: Hikayat Hang Tuah (2001), Surat-menyurat Almarhum Sultan Kedah 1882-1943 (2001), Sulalatus Salatin (2002) dan Batu Bersurat Terengganu (2009).', 4),
(1714, 223, 1001, 'e10_n1_s6', 'Warisan Budaya Tidak Ketara Kemanusiaan: Makyung (2005), Dondang Sayang (2018), Silat (2019) dan Wangkang (2020).', 5),
(1715, 223, 1001, 'e10_n1_s6', 'Soalan penutup aku: pernyataan manakah yang betul tentang warisan dunia Malaysia?', 6),
(1716, 222, 1002, NULL, 'Keamanan dunia dijaga bersama, {nama}. Sehelai topi biru tidak bermakna jika tiada rakan yang setia. Terima kasih kerana meronda bersamaku!', 1),
(1717, 222, 1002, NULL, 'Malaysia menyumbang kepada keamanan dan kerjasama dunia melalui ASEAN, Komanwel, OIC dan PBB. Pengiktirafan dunia lahir daripada usaha yang berterusan.', 2),
(1718, 222, 1002, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penjaga keamanan yang topi birunya sentiasa tegak. Rondaan bermula, pintu bilik mesyuarat dibuka satu persatu! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3);
INSERT INTO `DialogueLine` (`dialogueID`, `npcID`, `narrativeID`, `sceneID`, `dialogueLine`, `sequenceOrder`) VALUES
(1719, 224, 1002, 'e10_n2_s1', 'Penjaga keamanan, sidang serantau akan bermula! Tolong jaga pintu, ya. Sementara itu, kau tahu pertubuhan serantau kita?', 1),
(1720, NULL, 1002, 'e10_n2_s1', 'Sedikit-sedikit sahaja. Tolong ceritakan!', 2),
(1721, 224, 1002, 'e10_n2_s1', 'SEAFET, Southeast Asia Friendship and Economic Treaty, dan ASA, Association of Southeast Asia. Anggota keduanya ialah Tanah Melayu, Thailand dan Filipina.', 3),
(1722, 231, 1002, 'e10_n2_s1', 'Kemudian ASEAN, Association of Southeast Asian Nations! Anggotanya Malaysia, Indonesia, Thailand, Filipina dan Singapura. Aku wakil Indonesia!', 4),
(1723, 224, 1002, 'e10_n2_s1', 'Sebelum kau menjawab soalan kuiz sidang, jawab dahulu soalan aku: apakah kepanjangan ASA?', 5),
(1724, NULL, 1002, 'e10_n2_s2', 'Empat pintu, empat pertubuhan antarabangsa! Giliran siapa dahulu?', 1),
(1725, 226, 1002, 'e10_n2_s2', 'Aku utusan Komanwel! Keahlian kami terdiri daripada negara bekas tanah jajahan British.', 2),
(1726, 225, 1002, 'e10_n2_s2', 'Aku wakil PBB. Keahlian PBB terbuka kepada semua negara, termasuk Malaysia!', 3),
(1727, 227, 1002, 'e10_n2_s2', 'Aku wakil OIC, Pertubuhan Kerjasama Islam. Kami terdiri daripada 57 buah negara Islam.', 4),
(1728, 228, 1002, 'e10_n2_s2', 'Aku duta NAM. Pergerakan Negara-negara Berkecuali ini terdiri daripada 120 buah negara membangun di Asia, Afrika dan Amerika Selatan!', 5),
(1729, 225, 1002, 'e10_n2_s2', 'Sebelum kau memadankan, soalan PBB: pertubuhan manakah yang ditubuhkan pada 24 Oktober 1945?', 6),
(1730, 224, 1002, 'e10_n2_s3', 'Penjaga, kau meronda di bilik ASEAN! Ia ditubuhkan pada 8 Ogos 1967 dan dianggotai 10 negara Asia Tenggara. Ibu pejabatnya di Jakarta.', 1),
(1731, 224, 1002, 'e10_n2_s3', 'Matlamatnya: keamanan dan kestabilan politik, pertumbuhan ekonomi, sosial dan budaya, latihan dan penyelidikan, serta meningkatkan taraf hidup.', 2),
(1732, NULL, 1002, 'e10_n2_s3', 'Dan apakah sumbangan Malaysia?', 3),
(1733, 224, 1002, 'e10_n2_s3', 'Malaysia menjadi tuan rumah Mesyuarat Menteri Luar ASEAN, membantu isu pencerobohan Vietnam di Kemboja dan meredakan konflik di Selatan Filipina.', 4),
(1734, 224, 1002, 'e10_n2_s3', 'Malaysia juga mengutarakan penubuhan ZOPFAN dan menyertai SEAMEO! Sebelum kau memeriksa bilik, soalan aku: berapakah negara anggota ASEAN?', 5),
(1735, 226, 1002, 'e10_n2_s4', 'Penjaga! Komanwel dibentuk pada 11 Disember 1931 dengan 54 negara bekas jajahan British. Ibu pejabatnya di London, England.', 1),
(1736, 226, 1002, 'e10_n2_s4', 'Malaysia mengecam dan membantu menamatkan dasar Aparteid, menjadi tuan rumah CHOGM 1989 dan mengisytiharkan Deklarasi Langkawi 1989 untuk alam sekitar.', 2),
(1737, 227, 1002, 'e10_n2_s4', 'OIC ditubuhkan pada 25 September 1969, dengan 57 negara dan ibu pejabat di Jeddah, Arab Saudi.', 3),
(1738, 230, 1002, 'e10_n2_s4', 'Beta, Tunku Abdul Rahman, Setiausaha Agung OIC yang pertama!', 4),
(1739, 229, 1002, 'e10_n2_s4', 'Aku sukarelawan kemanusiaan OIC. Malaysia membantu menubuhkan Bank Pembangunan Islam, menangani isu Bosnia dan Herzegovina 1991 dan menyokong perjuangan Palestin.', 5),
(1740, 229, 1002, 'e10_n2_s4', 'UIAM ditubuhkan pada 1983, dan Malaysia menjadi tuan rumah Persidangan OIC pada 1974 dan 2003! Soalan aku: siapa Setiausaha Agung OIC yang pertama?', 6),
(1741, 225, 1002, 'e10_n2_s5', 'Penjaga, kau bertugas di pusat operasi PBB! Ditubuhkan pada 24 Oktober 1945 dengan ibu pejabat di New York, Amerika Syarikat.', 1),
(1742, 225, 1002, 'e10_n2_s5', 'Malaysia membawa isu rakyat Palestin, mendesak usaha memerangi dadah, menyertai pasukan pengaman dan menyarankan peningkatan mutu pendidikan.', 2),
(1743, NULL, 1002, 'e10_n2_s5', 'Pasukan pengaman diiktiraf, bukan?', 3),
(1744, 225, 1002, 'e10_n2_s5', 'Betul! Melalui pemberian sijil dan pingat perkhidmatan PBB. Tokoh Malaysia pun diiktiraf: Tan Sri Razali Ismail, Pengerusi Majlis Keselamatan PBB (1989-1990).', 4),
(1745, 225, 1002, 'e10_n2_s5', 'Beliau juga Pengerusi Perhimpunan Agung PBB sesi ke-51 (1996-1997), dan Datuk Dr. Mazlan Othman Pengarah Hal Ehwal Angkasa Lepas PBB (1999-2002 dan 2007).', 5),
(1746, 225, 1002, 'e10_n2_s5', 'Soalan aku sebelum kuiz: siapakah Pengarah Hal Ehwal Angkasa Lepas PBB itu?', 6),
(1747, 223, 1002, 'e10_n2_s6', 'Penjaga, rondaan terakhir! Ruang UNESCO menyimpan warisan Malaysia yang diiktiraf dunia.', 1),
(1748, 223, 1002, 'e10_n2_s6', 'Tapak Warisan Dunia alam semula jadi pada 2000: Taman Negara Gunung Mulu di Sarawak dan Taman Kinabalu di Sabah.', 2),
(1749, 223, 1002, 'e10_n2_s6', 'Kebudayaan: Melaka dan George Town pada 2008, dan Warisan Arkeologi Lembah Lenggong pada 2012.', 3),
(1750, 223, 1002, 'e10_n2_s6', 'Daftar Memori Dunia: Hikayat Hang Tuah dan Surat-menyurat Almarhum Sultan Kedah 1882-1943 (2001), Sulalatus Salatin (2002) dan Batu Bersurat Terengganu (2009).', 4),
(1751, 223, 1002, 'e10_n2_s6', 'Warisan Budaya Tidak Ketara Kemanusiaan: Makyung (2005), Dondang Sayang (2018), Silat (2019) dan Wangkang (2020).', 5),
(1752, NULL, 1002, 'e10_n2_s6', 'Senarai yang panjang! Tolong susun lima tahun pengiktirafan ini supaya mudah dihafal.', 6),
(1753, 223, 1002, 'e10_n2_s6', 'Sebelum menyusun, soalan aku: Batu Bersurat Terengganu masuk Daftar Memori Dunia pada tahun berapa?', 7),
(1754, 223, 1003, NULL, 'Pameran hanya hidup jika ada yang menceritakannya, {nama}. Hari ini kau menjadi suara yang membawa kisah Malaysia kepada dunia. Terima kasih kerana membantuku memandu!', 1),
(1755, 223, 1003, NULL, 'Malaysia berperanan aktif dalam ASEAN, Komanwel, OIC dan PBB, dan warisannya diiktiraf dunia. Kisah ini patut diceritakan dengan bangga kepada semua.', 2),
(1756, 223, 1003, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemandu pameran yang kad namanya berkilat di dada. Pelawat sudah beratur di pintu masuk, lawatan bermula! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(1757, NULL, 1003, 'e10_n3_s1', 'Selamat datang, para pelawat! Bilik pertama ialah pertubuhan serantau. Pakar, tolong bantu!', 1),
(1758, 224, 1003, 'e10_n3_s1', 'Dengan senang hati! SEAFET ialah Southeast Asia Friendship and Economic Treaty, dan ASA ialah Association of Southeast Asia.', 2),
(1759, 224, 1003, 'e10_n3_s1', 'Anggota keduanya sama: Tanah Melayu, Thailand dan Filipina.', 3),
(1760, 231, 1003, 'e10_n3_s1', 'Aku wakil Indonesia! ASEAN pula Association of Southeast Asian Nations, dianggotai Malaysia, Indonesia, Thailand, Filipina dan Singapura.', 4),
(1761, NULL, 1003, 'e10_n3_s1', 'Papan nama anggota SEAFET ini luntur sedikit. Tolong nyahkod bersama kami!', 5),
(1762, 231, 1003, 'e10_n3_s1', 'Soalan aku dahulu: apakah kepanjangan ASEAN?', 6),
(1763, NULL, 1003, 'e10_n3_s2', 'Bilik kedua: pertubuhan antarabangsa! Utusan sekalian, silakan memperkenalkan diri.', 1),
(1764, 226, 1003, 'e10_n3_s2', 'Aku utusan Komanwel. Ahlinya terdiri daripada negara bekas tanah jajahan British.', 2),
(1765, 225, 1003, 'e10_n3_s2', 'Aku wakil PBB. Keahlian PBB terbuka kepada semua negara!', 3),
(1766, 227, 1003, 'e10_n3_s2', 'Aku wakil OIC. Pertubuhan Kerjasama Islam terdiri daripada 57 buah negara Islam.', 4),
(1767, 228, 1003, 'e10_n3_s2', 'Aku duta NAM. Kami 120 buah negara membangun di Asia, Afrika dan Amerika Selatan!', 5),
(1768, 228, 1003, 'e10_n3_s2', 'Soalan aku: berapakah bilangan negara membangun dalam NAM?', 6),
(1769, 224, 1003, 'e10_n3_s3', 'Pemandu, bilik ini bilik ASEAN! Ia ditubuhkan pada 8 Ogos 1967, dianggotai 10 negara Asia Tenggara dan beribu pejabat di Jakarta.', 1),
(1770, 224, 1003, 'e10_n3_s3', 'Matlamatnya: keamanan dan kestabilan politik, pertumbuhan ekonomi, sosial dan budaya, latihan dan penyelidikan, serta meningkatkan taraf hidup.', 2),
(1771, NULL, 1003, 'e10_n3_s3', 'Pelawat sekalian, dan apakah sumbangan Malaysia?', 3),
(1772, 224, 1003, 'e10_n3_s3', 'Malaysia menjadi tuan rumah Mesyuarat Menteri Luar ASEAN, membantu isu pencerobohan Vietnam di Kemboja dan meredakan konflik di Selatan Filipina.', 4),
(1773, 224, 1003, 'e10_n3_s3', 'Malaysia juga mengutarakan penubuhan ZOPFAN dan menyertai SEAMEO! Sekarang padankan butiran ASEAN pada kad pameran ini.', 5),
(1774, 226, 1003, 'e10_n3_s4', 'Pemandu, Komanwel dibentuk pada 11 Disember 1931 dan dianggotai 54 negara bekas jajahan British. Ibu pejabatnya di London, England.', 1),
(1775, 226, 1003, 'e10_n3_s4', 'Malaysia mengecam dan membantu menamatkan dasar Aparteid. Malaysia juga tuan rumah CHOGM 1989 dan mengisytiharkan Deklarasi Langkawi 1989 untuk alam sekitar.', 2),
(1776, 227, 1003, 'e10_n3_s4', 'OIC ditubuhkan pada 25 September 1969, dianggotai 57 negara dengan ibu pejabat di Jeddah, Arab Saudi.', 3),
(1777, 230, 1003, 'e10_n3_s4', 'Beta, Tunku Abdul Rahman, dilantik sebagai Setiausaha Agung OIC yang pertama.', 4),
(1778, 227, 1003, 'e10_n3_s4', 'Malaysia membantu menubuhkan Bank Pembangunan Islam, menangani isu Bosnia dan Herzegovina 1991, menyokong perjuangan Palestin dan menubuhkan UIAM pada 1983.', 5),
(1779, 227, 1003, 'e10_n3_s4', 'Malaysia menjadi tuan rumah Persidangan OIC pada 1974 dan 2003. Soalan aku: siapa Setiausaha Agung OIC yang pertama?', 6),
(1780, 225, 1003, 'e10_n3_s5', 'Pemandu, dewan ini milik PBB! Ditubuhkan pada 24 Oktober 1945 dengan ibu pejabat di New York, Amerika Syarikat.', 1),
(1781, 225, 1003, 'e10_n3_s5', 'Malaysia membawa isu rakyat Palestin, mendesak usaha memerangi dadah dan menyarankan peningkatan mutu pendidikan.', 2),
(1782, 222, 1003, 'e10_n3_s5', 'Aku penjaga keamanan PBB! Malaysia menyertai pasukan pengaman dan diiktiraf melalui sijil dan pingat perkhidmatan PBB!', 3),
(1783, 225, 1003, 'e10_n3_s5', 'Tan Sri Razali Ismail ialah Pengerusi Majlis Keselamatan PBB (1989-1990) dan Pengerusi Perhimpunan Agung PBB sesi ke-51 (1996-1997).', 4),
(1784, 225, 1003, 'e10_n3_s5', 'Datuk Dr. Mazlan Othman ialah Pengarah Hal Ehwal Angkasa Lepas PBB (1999-2002 dan 2007).', 5),
(1785, NULL, 1003, 'e10_n3_s5', 'Wah, bangga! Tetapi sijil ini luntur sedikit. Tolong nyahkod!', 6),
(1786, 222, 1003, 'e10_n3_s5', 'Sebelum nyahkod, soalan aku: apakah sumbangan Malaysia dalam bidang keamanan PBB?', 7),
(1787, 223, 1003, 'e10_n3_s6', 'Pemandu, bilik terakhir! Di sini warisan Malaysia diiktiraf UNESCO.', 1),
(1788, 223, 1003, 'e10_n3_s6', 'Tapak Warisan Dunia alam semula jadi pada 2000: Taman Negara Gunung Mulu di Sarawak dan Taman Kinabalu di Sabah.', 2),
(1789, 223, 1003, 'e10_n3_s6', 'Tapak kebudayaan: Melaka dan George Town pada 2008, dan Warisan Arkeologi Lembah Lenggong pada 2012.', 3),
(1790, 223, 1003, 'e10_n3_s6', 'Daftar Memori Dunia: Hikayat Hang Tuah dan Surat-menyurat Almarhum Sultan Kedah 1882-1943 (2001), Sulalatus Salatin (2002) dan Batu Bersurat Terengganu (2009).', 4),
(1791, 223, 1003, 'e10_n3_s6', 'Warisan Budaya Tidak Ketara Kemanusiaan: Makyung (2005), Dondang Sayang (2018), Silat (2019) dan Wangkang (2020).', 5),
(1792, NULL, 1003, 'e10_n3_s6', 'Banyak bukti kebanggaan! Mari kita cari buktinya di dalam kotak kaca ini.', 6),
(1793, 223, 1003, 'e10_n3_s6', 'Sebelum itu, soalan aku: Taman Kinabalu terletak di negeri mana?', 7);
