(1, 'S1001', 0.00, 0, 0, 0, 0);
INSERT INTO `LearningSupport` (`supportID`, `questID`, `sceneID`, `supportType`, `hint`, `explanation`, `feedback`) VALUES
(1, NULL, 'e1_n1_s1', 'hint', 'Tunku Abdul Rahman berdiri di hadapan wartawan tempatan dan antarabangsa pada 27 Mei 1961. Di sebalik cadangan ini, terdapat sejarah idea daripada Lord Brassey (1887), Ibrahim Yaakob (1938), Malcolm MacDonald (1951), dan ucapan awal Tunku pada 1955.', NULL, NULL),
(2, 1, NULL, 'hint', 'Fikirkan ancaman komunis di Singapura dan Sarawak serta faedah kemerdekaan dan pembangunan ekonomi bersama.', '27 Mei 1961, Hotel Adelphi. Aku mengumumkan gagasan Malaysia kepada dunia. Empat sebab menyokongnya: membendung komunis, mengimbangi kaum, mempercepat kemerdekaan Borneo dan memajukan ekonomi.', 'Syabas! Penerangan yang berasas ini berhasil meyakinkan perwakilan media dan memulakan langkah rasmi pembentukan.'),
(3, NULL, 'e1_n1_s2', 'hint', 'Selepas penubuhan Jawatankuasa Setia Kawan Malaysia (JSKM) pada 23 Julai 1961 di bawah Donald Stephens, Suruhanjaya Cobbold ditubuhkan pada 17 Januari 1962 bersama ahli tempatan seperti Tun Muhammad Ghazali Shafie dan Tan Sri Wong Pow Nee.', NULL, NULL),
(4, 2, NULL, 'hint', 'Gabungkan kumpulan yang menyokong penuh dan menyokong bersyarat untuk mendapatkan nisbah majoriti dua pertiga.', 'JSKM (23 Julai 1961, Donald Stephens) menerangkan Malaysia. Cobbold (17 Januari 1962; Ghazali dan Wong Pow Nee) mendengar rakyat. Laporan 21 Jun 1962: dua pertiga menyokong, ada bersyarat.', 'Syabas! Analisis anda membuktikan sokongan majoriti rakyat Borneo terhadap gagasan penyatuan ini.'),
(5, NULL, 'e1_n1_s3', 'hint', 'Jawatankuasa Antara Kerajaan (JAK) ditubuhkan pada 30 Ogos 1962 dipengerusikan oleh Lord Lansdowne dan Tun Abdul Razak untuk merangka perlembagaan dan memasukkan peruntukan Hak 20 Perkara Sabah serta tuntutan Sarawak.', NULL, NULL),
(6, 3, NULL, 'hint', 'JAK dipengerusikan oleh Lansdowne dan Tun Razak untuk memasukkan Hak 20 Perkara ke dalam Perlembagaan.', '30 Ogos 1962: JAK (Lord Lansdowne dan Tun Razak) menulis Hak 20 Perkara Sabah dan 18 Perkara Sarawak dalam Perlembagaan. Janji lisan boleh dilupa, undang-undang tertulis tidak.', 'Tepat sekali! Penggubalan syarat ini menjamin keadilan dan persetujuan bersama antara wilayah.'),
(7, NULL, 'e1_n1_s4', 'hint', 'Tunku Abdul Rahman dan Tun Abdul Razak meneliti laporan bantahan parti Sarawak United People\'s Party (SUPP), pengisytiharan Konfrontasi Indonesia (Ganyang Malaysia) pada 20 Januari 1963, serta tuntutan Filipina ke atas Sabah.', NULL, NULL),
(9, NULL, 'e1_n1_s5', 'hint', 'Perjanjian Malaysia ditandatangani pada 9 Julai 1963 di London. Ekoran bantahan Indonesia dan Filipina, PBB menubuhkan United Nations Malaysia Mission (UNMM) pada 12 Ogos 1963 di bawah Laurence Michelmore.', NULL, NULL),
(10, 5, NULL, 'hint', 'Laporan UNMM mengesahkan semula dapatan Suruhanjaya Cobbold bahawa majoriti rakyat Borneo menyokong Malaysia.', '9 Julai 1963: Perjanjian Malaysia ditandatangani di London. UNMM (12 Ogos 1963, Michelmore) bertanya kepada rakyat Borneo. Laporan 14 September mengesahkan sokongan; 31 Ogos ditangguh ke 16 September.', 'Syabas! Pengesahan antarabangsa ini mematahkan hujah penentang luaran secara muktamad.'),
(11, NULL, 'e1_n1_s6', 'hint', 'Tunku Abdul Rahman berdiri megah membacakan Teks Pemasyhuran Malaysia pada 16 September 1963, dilangsungkan serentak di Kuala Lumpur, Kuching, Kota Kinabalu, dan Singapura.', NULL, NULL),
(12, 6, NULL, 'hint', 'Bermula dari Cadangan 1961, JSKM, Laporan Cobbold 1962, Perjanjian London Julai 1963, dan Pemasyhuran 16 September 1963.', '16 September 1963: Malaysia diisytiharkan serentak di Kuala Lumpur (Stadium Merdeka), Kuching, Kota Kinabalu dan City Hall Singapura. Jalur Gemilang dikibarkan. Semuanya bermula dengan mendengar.', 'Cemerlang! Urutan garis masa sejarah pembentukan negara telah berjaya anda susun dengan sempurna.'),
(13, NULL, 'e1_n2_s1', 'hint', 'Donald Stephens dan Tun Temenggung Jugah mengadakan perbincangan susulan pengumuman Tunku Abdul Rahman di Hotel Adelphi Singapura pada 27 Mei 1961. Di samping itu, sejarah cadangan awal Lord Brassey (1887) dan Malcolm MacDonald (1951) turut dikaji.', NULL, NULL),
(14, 7, NULL, 'hint', 'Fikirkan faedah kemerdekaan pantas, pertahanan daripada komunis, dan pembangunan sosioekonomi.', 'Pengumuman Tunku (27 Mei 1961) membuka peluang kepada Borneo: kemerdekaan lebih awal, perlindungan daripada komunis dan ekonomi yang maju. Tetapi aku mendengar rakyat dahulu sebelum menjawab.', 'Syabas! Keputusan anda mencerminkan wawasan kepimpinan Borneo demi masa depan rakyat.'),
(15, NULL, 'e1_n2_s2', 'hint', 'Donald Stephens mempengerusikan Jawatankuasa Setia Kawan Malaysia (JSKM) pada 23 Julai 1961, manakala Suruhanjaya Cobbold tiba pada 17 Januari 1962 mengumpul pandangan rakyat bersama wakil Tanah Melayu seperti Ghazali Shafie dan Wong Pow Nee.', NULL, NULL),
(16, 8, NULL, 'hint', 'Donald Stephens mempengerusikan JSKM manakala Laporan Cobbold mengesahkan sokongan 2/3 rakyat.', 'JSKM (23 Julai 1961) kami gunakan untuk menerangkan Malaysia. Cobbold (17 Januari 1962; Ghazali dan Wong Pow Nee antara ahlinya) mendengar rakyat. Laporan 21 Jun 1962: dua pertiga menyokong.', 'Padanan tepat! Usaha gigih ini berjaya menyatukan pandangan pelbagai etnik di Borneo.'),
(17, NULL, 'e1_n2_s3', 'hint', 'Dalam mesyuarat JAK yang dipengerusikan Lord Lansdowne dan Tun Abdul Razak pada 30 Ogos 1962, Donald Stephens dan pemimpin Borneo memperjuangkan Hak 20 Perkara Sabah serta tuntutan Sarawak.', NULL, NULL),
(18, 9, NULL, 'hint', 'Hak keistimewaan merangkumi kawalan imigresen, agama, dan pentadbiran tempatan Borneo.', 'Di JAK (30 Ogos 1962, Lord Lansdowne dan Tun Razak) aku membawa Hak 20 Perkara Sabah; Sarawak membawa 18 Perkara. Imigresen, agama, bahasa dan perkhidmatan awam dilindungi dalam Perlembagaan.', 'Syabas! Perjuangan gigih anda berjaya mendaulat dan melindungi hak keistimewaan rakyat Borneo.'),
(19, NULL, 'e1_n2_s4', 'hint', 'Pemimpin Borneo menghadapi bantahan dalaman parti SUPP di Sarawak yang mahukan kemerdekaan berasingan, serta pencerobohan tentera Indonesia semasa Konfrontasi (20 Jan 1963) dan tuntutan Filipina ke atas Sabah.', NULL, NULL),
(21, NULL, 'e1_n2_s5', 'hint', 'Perjanjian Malaysia ditandatangani di Marlborough House London pada 9 Julai 1963. Seterusnya, Misi PBB (UNMM) pimpinan Laurence Michelmore tiba pada 12 Ogos 1963 untuk membuat penilaian rasmi.', NULL, NULL),
(22, 11, NULL, 'hint', 'Siasatan UNMM PBB mengesahkan semula bahawa rakyat Borneo menyokong gabungan Malaysia.', 'Selepas perjanjian (9 Julai 1963), UNMM (12 Ogos 1963, Michelmore) bertanya kepada rakyat Borneo. Laporan 14 September 1963 mengesahkan sokongan bebas; 31 Ogos ditangguh ke 16 September.', 'Syabas! Pengesahan PBB ini membuktikan keabsahan perjuangan rakyat Borneo di arena antarabangsa.'),
(23, NULL, 'e1_n2_s6', 'hint', 'Donald Stephens membacakan Pemasyhuran Malaysia di Kota Kinabalu bersama Tun Datu Mustapha, manakala Stephen Kalong Ningkan membacakannya di Kuching bersama Tun Temenggung Jugah pada 16 September 1963.', NULL, NULL),
(24, 12, NULL, 'hint', 'Urutan bermula dari Cadangan 1961, Penerangan JSKM, Tinjauan Cobbold 1962, Perjanjian London Julai 1963, dan Pemasyhuran 16 September 1963.', '16 September 1963: aku membaca Pemasyhuran di Kota Kinabalu, Stephen Kalong Ningkan di Kuching, Tunku di Stadium Merdeka dan City Hall Singapura. Empat tempat, satu hari, satu negara.', 'Cemerlang! Urutan sejarah pembentukan negara telah berjaya anda susun dengan tepat.'),
(25, NULL, 'e1_n3_s1', 'hint', 'Tun Ghazali Shafie menganalisis geopolitik Asia Tenggara susulan pengumuman Tunku Abdul Rahman di Hotel Adelphi Singapura pada 27 Mei 1961. Idea Lord Brassey (1887), Ibrahim Yaakob (1938), dan Malcolm MacDonald (1951) turut dijadikan rujukan.', NULL, NULL),
(26, 13, NULL, 'hint', 'Penggabungan wilayah memperkukuh benteng pertahanan daripada resapan anasir komunis.', 'Empat sebab menyokong Malaysia: membendung komunis di Singapura dan Sarawak, mengimbangi kaum, mempercepat kemerdekaan dan memajukan ekonomi. Keselamatan hanya satu daripadanya.', 'Tepat sekali! Analisis strategik anda menjadi asas pertahanan dan diplomasi negara.'),
(27, NULL, 'e1_n3_s2', 'hint', 'Tun Ghazali Shafie dan Tan Sri Wong Pow Nee menganggotai Suruhanjaya Cobbold (17 Jan 1962). Laporan diserahkan pada 21 Jun 1962 selepas JSKM (23 Julai 1961) menerangkan Malaysia kepada rakyat.', NULL, NULL),
(28, 14, NULL, 'hint', 'JSKM menerangkan, Cobbold mendengar, dan laporan 21 Jun 1962 mengesahkan sokongan dua pertiga.', 'JSKM (23 Julai 1961) menerangkan Malaysia. Cobbold (17 Januari 1962; aku dan Wong Pow Nee) mendengar rakyat. Laporan 21 Jun 1962: dua pertiga menyokong. Keraguan dijawab oleh JAK.', 'Cemerlang! Proses diplomasi dan perundangan berjaya disusun dengan teratur dan sah.'),
(29, NULL, 'e1_n3_s3', 'hint', 'Jawatankuasa Antara Kerajaan (JAK) bersidang pada 30 Ogos 1962 di bawah Lord Lansdowne dan Tun Abdul Razak. Hak 20 Perkara Sabah dan 18 Perkara Sarawak ditulis dalam Perlembagaan.', NULL, NULL),
(30, 15, NULL, 'hint', 'JAK dipengerusikan oleh Lord Lansdowne dan Tun Razak. Hak yang ditulis dalam Perlembagaan menjadi undang-undang.', 'JAK (30 Ogos 1962, Lord Lansdowne dan Tun Razak) menulis Hak 20 Perkara Sabah dan 18 Perkara Sarawak ke dalam Perlembagaan. Aku memastikan ia bertulis, bukan janji lisan.', 'Tepat sekali! Hak Borneo kini tertulis dalam Perlembagaan, bukan sekadar janji.'),
(31, NULL, 'e1_n3_s4', 'hint', 'Tun Ghazali Shafie meneliti maklumat bantahan parti SUPP di Sarawak, pengisytiharan Konfrontasi Indonesia (Ganyang Malaysia) pada 20 Januari 1963, serta tuntutan Filipina ke atas Sabah.', NULL, NULL),
(33, NULL, 'e1_n3_s5', 'hint', 'Selepas Perjanjian Malaysia ditandatangani pada 9 Julai 1963 di Marlborough House London, Misi PBB (UNMM) ditubuhkan pada 12 Ogos 1963 di bawah Laurence Michelmore untuk membuat tinjauan semula.', NULL, NULL),
(34, 17, NULL, 'hint', 'Laporan UNMM mengesahkan semula sokongan majoriti rakyat Borneo terhadap pembentukan Malaysia.', 'UNMM (12 Ogos 1963) mesti bebas bertemu sesiapa tanpa kita campur tangan. Laporan 14 September 1963 dipercayai kerana kita tidak menyentuhnya. Tarikh 31 Ogos ditangguh ke 16 September.', 'Syabas! Pengesahan PBB mematahkan tuduhan luar dan membuktikan ketelusan Malaysia kepada dunia.'),
(35, NULL, 'e1_n3_s6', 'hint', 'Tun Ghazali Shafie memantau kawalan keselamatan semasa Tunku Abdul Rahman membaca Teks Pemasyhuran Malaysia pada 16 September 1963 secara serentak di Kuala Lumpur, Kuching, Kota Kinabalu, dan Singapura.', NULL, NULL),
(36, 18, NULL, 'hint', 'Urutan bermula dari Cadangan 1961, Penerangan JSKM, Tinjauan Cobbold 1962, Perjanjian London Julai 1963, dan Pemasyhuran 16 September 1963.', '16 September 1963: Pemasyhuran serentak di Stadium Merdeka (Kuala Lumpur), Kuching, Kota Kinabalu dan City Hall Singapura. Kerja keselamatan jarang dipuji, tetapi tanpanya majlis itu tidak berlangsung.', 'Cemerlang! Urutan peristiwa sejarah pembentukan negara telah berjaya anda susun dengan tepat.'),
(37, NULL, 'e2_n1_s1', 'hint', 'Cerita nama Perlis berkait dengan kelapa hanyut. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(38, 201, NULL, 'hint', 'Ingat kata kunci kelapa hanyut. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Perlis: asal nama, Perkataan Siam \'phrau loi\', iaitu kelapa hanyut. Ketua negeri Raja. Ibu negeri Kangar, bandar diraja Arau.', 'Hebat! Perlis kini terukir kemas dalam ingatan kau.'),
(39, NULL, 'e2_n1_s2', 'hint', 'Telinga tajam, mata tajam! Nama Kedah ada kaitan dengan perangkap gajah.', NULL, NULL),
(40, 202, NULL, 'hint', 'Sst! Kata kunci hari ini ialah perangkap gajah. Tengok jata, bendera dan radio dengan teliti.', 'Kedah: asal nama, Perkataan \'Kheddah\', iaitu perangkap gajah. Ketua negeri Sultan. Ibu negeri Alor Setar, bandar diraja Anak Bukit. Lagu \'Allah Selamatkan Sultan Mahkota\'.', 'Betul sekali! Jawapan kau membuat penduduk Kedah tersenyum bangga.'),
(41, NULL, 'e2_n1_s3', 'hint', 'Cerita nama Pulau Pinang berkait dengan pokok pinang. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(43, NULL, 'e2_n1_s4', 'hint', 'Telinga tajam, mata tajam! Nama Perak ada kaitan dengan bijih timah putih.', NULL, NULL),
(44, 204, NULL, 'hint', 'Ingat kata kunci bijih timah putih. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Perak: asal nama, Kilatan ikan atau bijih timah putih yang berkilat seperti perak. Ketua negeri Sultan (Takhtanya berpindah secara bergilir mengikut sistem penggiliran yang unik). Ibu negeri Ipoh, bandar diraja Kuala Kangsar. Lagu \'Allah Lanjutkan Usia Sultan\'.', 'Tepat! Maklumat Perak kini lengkap dalam catatan kau, dan semua orang bersorak!'),
(45, NULL, 'e2_n1_s5', 'hint', 'Cerita nama Selangor berkait dengan sungai dan serangga. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(46, 205, NULL, 'hint', 'Sst! Kata kunci hari ini ialah sungai dan serangga. Tengok jata, bendera dan radio dengan teliti.', 'Selangor: asal nama, Sungai Selangor, pokok mentagau atau serangga selangur. Ketua negeri Sultan. Ibu negeri Shah Alam, bandar diraja Klang. Lagu \'Duli Yang Maha Mulia\'.', 'Hebat! Selangor kini terukir kemas dalam ingatan kau.'),
(47, NULL, 'e2_n1_s6', 'hint', 'Telinga tajam, mata tajam! Nama Negeri Sembilan ada kaitan dengan sembilan luak.', NULL, NULL),
(48, 206, NULL, 'hint', 'Petunjuk rahsia: sembilan luak. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Negeri Sembilan: asal nama, Penyatuan sembilan luak asal, dan \'nagari\' bermaksud wilayah. Ketua negeri Yang di-Pertuan Besar (Beliau dipilih oleh Undang Yang Empat). Ibu negeri Seremban, bandar diraja Seri Menanti. Lagu \'Berkatlah Yang di-Pertuan Besar\'.', 'Betul sekali! Jawapan kau membuat penduduk Negeri Sembilan tersenyum bangga.'),
(49, NULL, 'e2_n1_s7', 'hint', 'Cerita nama Melaka berkait dengan pokok Melaka. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(51, NULL, 'e2_n1_s8', 'hint', 'Telinga tajam, mata tajam! Nama Johor ada kaitan dengan batu permata.', NULL, NULL),
(52, 208, NULL, 'hint', 'Sst! Kata kunci hari ini ialah batu permata. Tengok jata, bendera dan radio dengan teliti.', 'Johor: asal nama, Perkataan Arab \'Jauhar\', iaitu batu permata bernilai. Ketua negeri Sultan. Ibu negeri Johor Bahru, bandar diraja Bandar Maharani. Lagu \'Lagu Bangsa Johor\'.', 'Tepat! Maklumat Johor kini lengkap dalam catatan kau, dan semua orang bersorak!'),
(53, NULL, 'e2_n1_s9', 'hint', 'Cerita nama Pahang berkait dengan pokok mahang. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(54, 209, NULL, 'hint', 'Petunjuk rahsia: pokok mahang. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Pahang: asal nama, Pokok mahang, juga dikenali sebagai Inderapura. Ketua negeri Sultan. Ibu negeri Kuantan, bandar diraja Pekan. Lagu \'Allah Selamatkan Sultan Kami\'.', 'Hebat! Pahang kini terukir kemas dalam ingatan kau.'),
(55, NULL, 'e2_n1_s10', 'hint', 'Telinga tajam, mata tajam! Nama Terengganu ada kaitan dengan pelangi.', NULL, NULL),
(56, 210, NULL, 'hint', 'Ingat kata kunci pelangi. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Terengganu: asal nama, \'Taring anu\' (taring binatang liar) atau \'terang ganu\' (pelangi). Ketua negeri Sultan. Ibu negeri Kuala Terengganu. Lagu \'Selamat Sultan\'.', 'Betul sekali! Jawapan kau membuat penduduk Terengganu tersenyum bangga.'),
(57, NULL, 'e2_n1_s11', 'hint', 'Cerita nama Kelantan berkait dengan Ho-lan-tan. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(59, NULL, 'e2_n1_s12', 'hint', 'Telinga tajam, mata tajam! Nama Sarawak ada kaitan dengan antimoni.', NULL, NULL),
(60, 212, NULL, 'hint', 'Petunjuk rahsia: antimoni. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Sarawak: asal nama, Sungai Sarawak, logam antimoni (cerava) atau \'serah kepada awak\'. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Kuching. Lagu \'Ibu Pertiwiku\'.', 'Tepat! Maklumat Sarawak kini lengkap dalam catatan kau, dan semua orang bersorak!'),
(61, NULL, 'e2_n1_s13', 'hint', 'Cerita nama Sabah berkait dengan pisang saba. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(62, 213, NULL, 'hint', 'Ingat kata kunci pisang saba. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Sabah: asal nama, Sejenis pisang, iaitu pisang saba atau pisang jaba. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Kota Kinabalu. Lagu \'Sabah Tanah Airku\'.', 'Hebat! Sabah kini terukir kemas dalam ingatan kau.'),
(63, NULL, 'e2_n1_s14', 'hint', 'Telinga tajam, mata tajam! Nama Wilayah Persekutuan ada kaitan dengan muara berlumpur.', NULL, NULL),
(64, 214, NULL, 'hint', 'Sst! Kata kunci hari ini ialah muara berlumpur. Tengok jata, bendera dan radio dengan teliti.', 'Wilayah Persekutuan: asal nama, Muara berlumpur (KL), labuhan (Labuan), sempena Tunku (Putrajaya). Ketua negeri Yang di-Pertuan Agong. Lagu \'Maju dan Sejahtera\'.', 'Betul sekali! Jawapan kau membuat penduduk Wilayah Persekutuan tersenyum bangga.'),
(65, NULL, 'e2_n2_s1', 'hint', 'Setiap negeri ada gelaran ketua negerinya. Perhatikan jata, bendera dan radio Johor, dan ingat batu permata.', NULL, NULL),
(66, 215, NULL, 'hint', 'Ingat kata kunci batu permata. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Johor: asal nama, Perkataan Arab \'Jauhar\', iaitu batu permata bernilai. Ketua negeri Sultan. Ibu negeri Johor Bahru, bandar diraja Bandar Maharani. Lagu \'Lagu Bangsa Johor\'.', 'Betul sekali! Jawapan kau membuat penduduk Johor tersenyum bangga.'),
(67, NULL, 'e2_n2_s2', 'hint', 'Gelaran ketua negeri Kedah tersimpan pada jata dan bendera. Kata kunci: perangkap gajah.', NULL, NULL),
(69, NULL, 'e2_n2_s3', 'hint', 'Setiap negeri ada gelaran ketua negerinya. Perhatikan jata, bendera dan radio Kelantan, dan ingat Ho-lan-tan.', NULL, NULL),
(70, 217, NULL, 'hint', 'Petunjuk rahsia: Ho-lan-tan. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Kelantan: asal nama, Kilatan cahaya terang atau pokok gelam hutan. Ketua negeri Sultan. Ibu negeri Kota Bharu. Lagu \'Selamat Sultan\'.', 'Tepat! Maklumat Kelantan kini lengkap dalam catatan kau, dan semua orang bersorak!'),
(71, NULL, 'e2_n2_s4', 'hint', 'Gelaran ketua negeri Pahang tersimpan pada jata dan bendera. Kata kunci: pokok mahang.', NULL, NULL),
(72, 218, NULL, 'hint', 'Ingat kata kunci pokok mahang. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Pahang: asal nama, Pokok mahang, juga dikenali sebagai Inderapura. Ketua negeri Sultan. Ibu negeri Kuantan, bandar diraja Pekan. Lagu \'Allah Selamatkan Sultan Kami\'.', 'Hebat! Pahang kini terukir kemas dalam ingatan kau.'),
(73, NULL, 'e2_n2_s5', 'hint', 'Setiap negeri ada gelaran ketua negerinya. Perhatikan jata, bendera dan radio Perak, dan ingat bijih timah putih.', NULL, NULL),
(74, 219, NULL, 'hint', 'Sst! Kata kunci hari ini ialah bijih timah putih. Tengok jata, bendera dan radio dengan teliti.', 'Perak: asal nama, Kilatan ikan atau bijih timah putih yang berkilat seperti perak. Ketua negeri Sultan (Takhtanya berpindah secara bergilir mengikut sistem penggiliran yang unik). Ibu negeri Ipoh, bandar diraja Kuala Kangsar. Lagu \'Allah Lanjutkan Usia Sultan\'.', 'Betul sekali! Jawapan kau membuat penduduk Perak tersenyum bangga.'),
(75, NULL, 'e2_n2_s6', 'hint', 'Gelaran ketua negeri Selangor tersimpan pada jata dan bendera. Kata kunci: sungai dan serangga.', NULL, NULL),
(77, NULL, 'e2_n2_s7', 'hint', 'Setiap negeri ada gelaran ketua negerinya. Perhatikan jata, bendera dan radio Terengganu, dan ingat pelangi.', NULL, NULL),
(78, 221, NULL, 'hint', 'Ingat kata kunci pelangi. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Terengganu: asal nama, \'Taring anu\' (taring binatang liar) atau \'terang ganu\' (pelangi). Ketua negeri Sultan. Ibu negeri Kuala Terengganu. Lagu \'Selamat Sultan\'.', 'Tepat! Maklumat Terengganu kini lengkap dalam catatan kau, dan semua orang bersorak!'),
(79, NULL, 'e2_n2_s8', 'hint', 'Gelaran ketua negeri Perlis tersimpan pada jata dan bendera. Kata kunci: kelapa hanyut.', NULL, NULL),
(80, 222, NULL, 'hint', 'Sst! Kata kunci hari ini ialah kelapa hanyut. Tengok jata, bendera dan radio dengan teliti.', 'Perlis: asal nama, Perkataan Siam \'phrau loi\', iaitu kelapa hanyut. Ketua negeri Raja. Ibu negeri Kangar, bandar diraja Arau.', 'Hebat! Perlis kini terukir kemas dalam ingatan kau.'),
(81, NULL, 'e2_n2_s9', 'hint', 'Setiap negeri ada gelaran ketua negerinya. Perhatikan jata, bendera dan radio Negeri Sembilan, dan ingat sembilan luak.', NULL, NULL),
(82, 223, NULL, 'hint', 'Petunjuk rahsia: sembilan luak. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Negeri Sembilan: asal nama, Penyatuan sembilan luak asal, dan \'nagari\' bermaksud wilayah. Ketua negeri Yang di-Pertuan Besar (Beliau dipilih oleh Undang Yang Empat). Ibu negeri Seremban, bandar diraja Seri Menanti. Lagu \'Berkatlah Yang di-Pertuan Besar\'.', 'Betul sekali! Jawapan kau membuat penduduk Negeri Sembilan tersenyum bangga.'),
(83, NULL, 'e2_n2_s10', 'hint', 'Gelaran ketua negeri Melaka tersimpan pada jata dan bendera. Kata kunci: pokok Melaka.', NULL, NULL),
