(113, NULL, 'e2_n3_s11', 'hint', 'Catat ibu negeri, bandar diraja dan lagu Kelantan. Jata, bendera dan radio di gambar ini membantu kau ingat.', NULL, NULL),
(114, 239, NULL, 'hint', 'Sst! Kata kunci hari ini ialah Ho-lan-tan. Tengok jata, bendera dan radio dengan teliti.', 'Kelantan: asal nama, Kilatan cahaya terang atau pokok gelam hutan. Ketua negeri Sultan. Ibu negeri Kota Bharu. Lagu \'Selamat Sultan\'.', 'Hebat! Kelantan kini terukir kemas dalam ingatan kau.'),
(115, NULL, 'e2_n3_s12', 'hint', 'Buku catatan sedia? Ibu negeri, bandar diraja dan lagu Sabah ada di sekeliling kau.', NULL, NULL),
