INSERT INTO `Narrative` (`narrativeID`, `narrativeTitle`, `eraID`, `summary`) VALUES
(1, 'Perjalanan Sang Arsitek', 1, 'Masuki peranan Tunku Abdul Rahman dalam merancang dan memimpin pembentukan Malaysia. Hadapi siri perundingan diplomatik, tinjauan rakyat Borneo, tuntutan perlembagaan, bantahan SUPP, ancaman Konfrontasi Indonesia, tuntutan Filipina, serta siasatan PBB sebelum mengisytiharkan kelahiran negara pada 16 September 1963. Naratif ini merangkumi keenam-enam topik utama: cadangan Malaysia, JSKM dan Cobbold, JAK, ancaman keselamatan, Perjanjian London dan PBB, serta Pemasyhuran.'),
(2, 'Suara Kebangkitan Borneo', 1, 'Ikuti perjuangan pembentukan Malaysia dari sudut pandang pemimpin Borneo. Libatkan diri dalam siri penerangan JSKM, perundingan Suruhanjaya Cobbold, penggubalan Hak 20 Perkara Sabah dalam JAK, penentangan tentera Konfrontasi di sempadan, siasatan PBB, hingga hari Pemasyhuran di Kota Kinabalu dan Kuching. Naratif ini merangkumi keenam-enam topik utama: cadangan Malaysia, JSKM dan Cobbold, JAK, ancaman keselamatan, Perjanjian London dan PBB, serta Pemasyhuran.'),
(3, 'Perisai Diplomasi dan Keamanan', 1, 'Sertai peranan Tun Ghazali Shafie dan pasukan diplomatik negara. Menganalisis ancaman komunis, memimpin tinjauan Suruhanjaya Cobbold, merangka Perlembagaan JAK, menangkis bantahan SUPP, menghadapi Konfrontasi Indonesia dan tuntutan Filipina, serta mengendalikan siasatan PBB (UNMM) demi keselamatan Malaysia. Naratif ini merangkumi keenam-enam topik utama: cadangan Malaysia, JSKM dan Cobbold, JAK, ancaman keselamatan, Perjanjian London dan PBB, serta Pemasyhuran.'),
(201, 'Rahsia di Sebalik Nama', 2, 'Masuki peranan Tok Penglipur Lara yang mengembara dari utara hingga Borneo. Di setiap negeri, penduduk berebut mendengar ceritamu tentang asal nama, ketua negeri, ibu negeri, bandar diraja, lagu, jata dan bendera.'),
(202, 'Payung Negeri: Takhta dan Tanggungjawab', 2, 'Masuki peranan seorang Sultan yang menerima kunjungan ketua-ketua negeri. Di setiap negeri, ketua negeri menguji kau tentang gelaran, asal nama, ibu negeri, bandar diraja, lagu, jata dan bendera.'),
(203, 'Jejak Ibu Negeri dan Lagu Kebanggaan', 2, 'Masuki peranan Pengembara Warisan yang menjelajah seluruh tanah air dengan buku catatan. Di setiap negeri, kau mencatat ibu negeri, bandar diraja, lagu, ketua negeri, asal nama, jata dan bendera.'),
(301, 'Arahan dari Bilik Gerakan', 3, 'Masuki peranan Tun Abdul Razak, Pengarah MAGERAN, yang bergegas dari bilik gerakan ke kampung, bandar dan ladang. Kau menyusun latar belakang Rukun Negara, memahami sebab ia diperkenalkan, menemui lima matlamat, lima prinsip dan enam peranannya.'),
(302, 'Pintu Rumah Rakyat', 3, 'Masuki peranan Tun V.T. Sambanthan yang berjalan dari pos bantuan, kampung, ladang dan bandar untuk mendengar rakyat berbilang kaum. Dalam perjalanan itu kau mengenal latar belakang, sebab, lima matlamat, lima prinsip dan enam peranan Rukun Negara.'),
(303, 'Ikrar Satu Malaysia', 3, 'Masuki peranan Tunku Abdul Rahman, Perdana Menteri yang memikul luka negara selepas Mei 1969 dan mengajak rakyat berikrar bersama. Kau memahami latar belakang, sebab, lima matlamat, lima prinsip dan enam peranan Rukun Negara bersama rakyat dari bandar, kampung dan ladang.'),
(401, 'Rentak Seribu Kaum', 4, 'Masuki peranan seorang pemuzik tua yang mengembara dari kampung ke kampung membawa gambus, sape dan gendang. Dalam setiap rentak kau mengenali kepelbagaian kaum, petempatan dan ekonomi mereka dahulu dan kini, alat muzik dan tarian, permainan tradisional serta cerita rakyat.'),
(402, 'Peti Cerita Nenek', 4, 'Masuki peranan Nenek Segala Kaum yang membuka peti cerita lamanya. Dari satu laci ke satu laci, kau mengajar cucu-cucu tentang kepelbagaian kaum, petempatan dan ekonomi dahulu serta kini, alat muzik dan tarian, permainan tradisional dan tiga cerita rakyat.'),
(403, 'Gelanggang Seribu Kaum', 4, 'Masuki peranan Tok Permainan yang menjaga gelanggang tempat semua kaum bermain bersama. Setiap pusingan membawa kau mengenali kepelbagaian kaum, petempatan dan ekonomi dahulu serta kini, alat muzik dan tarian, permainan tradisional dan tiga cerita rakyat.'),
(501, 'Nota Lapangan Tujuh Pintu', 5, 'Masuki peranan seorang pengkaji budaya dengan buku nota lapangan. Dalam setiap misi kau mengenali tujuh agama dan ajaran, rumah ibadat mereka, kedudukan Islam dalam Perlembagaan, serta kepercayaan Orang Asli, Iban, Kadazandusun, Bisaya dan Bajau.'),
(502, 'Persidangan Para Penjaga Adat', 5, 'Masuki peranan Bobohizan yang dijemput ke persidangan para penjaga adat. Sambil mendengar wakil setiap agama, kau belajar tentang tujuh agama dan ajaran, rumah ibadat, Perkara 3 Perlembagaan, serta kepercayaan Orang Asli, Iban, Kadazandusun, Bisaya dan Bajau.'),
(503, 'Syair Seribu Kepercayaan', 5, 'Masuki peranan Lemambang yang melagukan syair di Pesta Kepercayaan Sekolah. Dalam setiap bait kau mengenali tujuh agama dan ajaran, rumah ibadat, Perkara 3 Perlembagaan, serta kepercayaan Orang Asli, Iban, Kadazandusun, Bisaya dan Bajau.'),
(601, 'Bengkel Kraf Seribu Perayaan', 6, 'Masuki peranan penggiat kraf perayaan yang membuat hiasan untuk semua kaum. Dalam bengkelmu kau mengenali perayaan utama dan tujuannya, cara sambutan dahulu dan kini, serta amalan yang kekal sehingga hari ini.'),
(602, 'Pulang Beraya Bersama Nenek', 6, 'Masuki peranan seorang ibu moden yang membawa anak pulang beraya ke kampung. Bersama Nenek Dahulu, kau mengenali perayaan utama dan tujuannya, cara sambutan dahulu dan kini, serta amalan yang kekal.'),
(603, 'Kedai Seribu Perayaan', 6, 'Masuki peranan peniaga rumah kedai yang menjual kad, kuih dan hiasan untuk semua perayaan. Setiap pelanggan membawa cerita: perayaan utama, tujuan, cara sambutan dahulu dan kini, serta amalan yang kekal.'),
(701, 'Siaran Khas dari Pejabat Perdana Menteri', 7, 'Masuki peranan wartawan muda yang menemu bual Yang di-Pertuan Agong dan para Perdana Menteri Malaysia. Dalam siaranmu kau mengenali peranan jawatan, senarai sembilan giliran Perdana Menteri, tugas-tugasnya dan pencapaian setiap pemimpin.'),
(702, 'Perdana Menteri Keluar dari Buku Teks', 7, 'Masuki peranan guru Sejarah yang buku teks Unit 7-nya tiba-tiba berpendar dan melepaskan para Perdana Menteri ke dalam bilik darjah. Dalam kelasmu kau mengenali peranan jawatan, senarai sembilan giliran, tugas-tugas dan pencapaian setiap pemimpin.'),
(703, 'Album Kad Koleksi Perdana Menteri', 7, 'Masuki peranan murid penyelidik yang membuat album kad koleksi Perdana Menteri untuk projek sekolah. Dalam setiap halaman kau mengumpul maklumat tentang peranan jawatan, senarai sembilan giliran, tugas-tugas dan pencapaian setiap pemimpin.'),
(801, 'Dari Cangkul ke Jentera: Kembara Juruteknik', 8, 'Masuki peranan juruteknik mesin ladang yang mengembara dari sawah bercangkul ke pelantar minyak dan bandar moden. Dalam perjalananmu kau mengenali ekonomi tradisional dan komersial, industri pemacu, barangan jenama Malaysia serta pencapaian pembangunan, perhubungan dan perdagangan.'),
(802, 'Pemeriksaan Mutu Ekonomi Negara', 8, 'Masuki peranan inspektor kilang yang memeriksa mutu ekonomi negara dengan borang dan cop LULUS. Dalam setiap pemeriksaan kau mengenali ekonomi tradisional dan komersial, industri pemacu, barangan jenama Malaysia serta pencapaian pembangunan, perhubungan dan perdagangan.'),
(803, 'Kedai Jenama Malaysia: Cerita Setiap Rak', 8, 'Masuki peranan pemilik kedai jenama Malaysia yang menceritakan kisah di sebalik setiap rak. Dalam kedaimu kau mengenali ekonomi tradisional dan komersial, industri pemacu, barangan jenama Malaysia serta pencapaian pembangunan, perhubungan dan perdagangan.'),
(901, 'Siaran Langsung Stadium Kebanggaan Negara', 9, 'Masuki peranan pengulas sukan yang membuat siaran langsung dari stadium ke stadium. Dalam siaranmu kau mengenali pencapaian badminton, bola sepak, olahraga dan hoki, atlet kebanggaan, program sukan perpaduan, penganjuran sukan antarabangsa dan tokoh inspirasi sukan negara.'),
(902, 'Latihan Pagi Jurulatih Sekolah', 9, 'Masuki peranan jurulatih sekolah yang melatih murid di padang, trek dan dewan. Dalam sesi latihanmu kau mengajar pencapaian sukan kebanggaan, atlet negara, program sukan perpaduan, penganjuran sukan antarabangsa dan tokoh inspirasi sukan negara.'),
(903, 'Buku Skrap Peminat Sukan Negara', 9, 'Masuki peranan murid peminat sukan yang mengumpul kad dan keratan akhbar. Dalam buku skrapmu kau menyimpan pencapaian sukan kebanggaan, atlet negara, program sukan perpaduan, penganjuran sukan antarabangsa dan tokoh inspirasi sukan negara.'),
(1001, 'Sidang Serantau Wakil Muda ASEAN', 10, 'Masuki peranan wakil muda ASEAN yang menghadiri sidang di bilik mesyuarat dunia. Dalam sidang itu kau mengenali pertubuhan serantau dan antarabangsa, sumbangan Malaysia dalam ASEAN, Komanwel, OIC dan PBB, serta pengiktirafan UNESCO.'),
(1002, 'Rondaan Keamanan Penjaga Topi Biru', 10, 'Masuki peranan penjaga keamanan PBB yang meronda dari bilik mesyuarat ke bilik mesyuarat. Dalam rondaanmu kau mengenali pertubuhan serantau dan antarabangsa, sumbangan Malaysia dalam ASEAN, Komanwel, OIC dan PBB, serta pengiktirafan UNESCO.'),
(1003, 'Lawatan Pameran Malaysia dan Dunia', 10, 'Masuki peranan pemandu pameran UNESCO yang membawa pelawat melawat bilik demi bilik. Dalam lawatan itu kau mengenali pertubuhan serantau dan antarabangsa, sumbangan Malaysia dalam ASEAN, Komanwel, OIC dan PBB, serta pengiktirafan UNESCO.');
INSERT INTO `NPC` (`npcID`, `name`, `biography`, `contribution`, `asset`) VALUES
(1, 'Tunku Abdul Rahman Putra Al-Haj', 'Perdana Menteri pertama Persekutuan Tanah Melayu dan Bapa Kemerdekaan.', 'Meyakinkan lima wilayah bersatu tanpa paksaan: mendengar Borneo, menandatangani perjanjian dan mengisytiharkan Malaysia.', 'tunku_abdul_rahman.png'),
(2, 'Tun Temenggong Jugah anak Barieng', 'Pemimpin utama masyarakat Iban dari Sarawak dan pengerusi parti PESAKA.', 'Menegaskan perlindungan hak adat Sarawak dalam rundingan pembentukan Malaysia.', 'tun_temenggung_jugah.png'),
(3, 'Donald Stephens (Tun Fuad Stephens)', 'Tokoh utama Sabah dan Pengerusi Jawatankuasa Setia Kawan Malaysia (JSKM).', 'Membawa suara rakyat Borneo ke meja perundingan supaya hak mereka ditulis dalam Perlembagaan.', 'tun_muhammad_fuad_stephens.png'),
(4, 'Lee Kuan Yew', 'Perdana Menteri Singapura yang menyokong penggabungan dengan Malaysia.', 'Memimpin referendum Singapura dan menangani ancaman pengaruh komunis.', 'lee_kuan_yew.png'),
(5, 'Tun Abdul Razak bin Dato\' Hussein', 'Timbalan Perdana Menteri Persekutuan Tanah Melayu dan Pengerusi JAK.', 'Merangka hak perlembagaan dan perlindungan khas bagi Sabah dan Sarawak.', 'tun_abdul_razak.png'),
(6, 'Tan Sri Stephen Kalong Ningkan', 'Ketua Menteri Sarawak yang pertama dan pengasas Perikatan Sarawak.', 'Memimpin Sarawak menyertai Malaysia dan membaca Pemasyhuran di Kuching.', 'tan_sri_dato_amar_stephen_kalong.png'),
(7, 'Wakil SUPP / Pembangkang', 'Wakil gerakan politik tempatan di Sarawak yang menentang idea gabungan awal.', 'Menuntut kemerdekaan Sarawak secara berasingan sebelum cadangan persekutuan.', 'orang_sarawak.png'),
(9, 'Tun Datu Mustapha bin Datu Harun', 'Pengasas USNO dan Pemimpin Utama Sabah.', 'Memimpin penyatuan rakyat Sabah dan menyokong pembentukan Malaysia.', 'tun_dato_mustapha.png'),
(10, 'Tun Muhammad Ghazali Shafie', 'Diplomat dan perunding keselamatan negara dalam rundingan pembentukan Malaysia.', 'Menjaga keselamatan dan diplomasi di belakang tabir: menghadapi Konfrontasi dan memastikan PBB mengesahkan pilihan rakyat.', 'tun_muhammad_ghazali_shafie.png'),
(21, 'Tok Penglipur Lara', 'Penglipur lara tua yang mengembara dari kampung ke kampung menyampaikan cerita asal usul nama negeri.', 'Menyimpan dan menurunkan cerita asal usul nama negeri supaya warisan lisan tidak hilang.', 'orang_tradisi_lama.png'),
(22, 'Sultan (ketua negeri bersultan)', 'Ketua negeri bergelar Sultan, payung kepada negeri dan rakyatnya.', 'Memelihara adat dan menjadi payung kepada negeri yang diketuainya.', 'sultan.png'),
(23, 'Raja Perlis', 'Ketua negeri Perlis yang bergelar Raja.', 'Mewakili institusi diraja Perlis, satu-satunya negeri yang diketuai oleh Raja.', 'raja.png'),
(24, 'Yang di-Pertuan Besar Negeri Sembilan', 'Ketua negeri Negeri Sembilan yang dipilih oleh Undang Yang Empat.', 'Mewakili institusi diraja Negeri Sembilan yang dipilih mengikut adat.', 'yang_dipertuan_besar.png'),
(25, 'Yang di-Pertua Negeri', 'Ketua negeri bagi Melaka, Pulau Pinang, Sabah dan Sarawak yang dilantik oleh Yang di-Pertuan Agong.', 'Memegang jawatan ketua negeri untuk satu penggal empat tahun.', 'yang_dipertuan_negeri.png'),
(26, 'Pengembara Warisan', 'Pengembara yang mencatat ibu negeri, bandar diraja dan lagu negeri di seluruh Malaysia.', 'Memperkenalkan lambang kebanggaan setiap negeri kepada generasi muda.', 'jejaka_melayu.png'),
(27, 'Nelayan Tua', 'Nelayan tua yang tinggal di pesisir pantai dan gemar bercerita tentang nama tempat.', 'Menyimpan cerita lisan tentang nama pulau dan pantai.', 'nelayan.png'),
(28, 'Pesawah Padi', 'Pesawah di utara Semenanjung yang ingin tahu asal nama negerinya.', 'Mewakili rakyat biasa yang menjaga cerita kampung.', 'pesawah_padi.png'),
(29, 'Pemburu', 'Penduduk pantai timur yang menemui catatan lama di rumah datuknya.', 'Mewakili rakyat yang menyimpan catatan lama keluarga.', 'pemburu.png'),
(30, 'Peniaga Rumah Kedai', 'Peniaga bandar yang sering ditanya pelanggan tentang nama tempat.', 'Mewakili rakyat bandar yang ingin tahu asal usul tempat tinggalnya.', 'peniaga_rumah_kedai.png'),
(32, 'Nenek Dahulu', 'Warga emas yang masih mengingati warkah dan cerita istana lama.', 'Menyimpan ingatan tentang adat dan cerita istana.', 'nenek_dahulu.png'),
