(112, 'Nenek Dahulu', 'Warga emas yang mengingati cara beraya pada zaman dahulu (watak rekaan).', 'Menceritakan cara sambutan perayaan dahulu kepada cucu-cucu.', 'nenek_dahulu.png'),
(113, 'Murid Sekolah', 'Murid yang gemar bertanya dan memegang telefon pintar (watak rekaan).', 'Mewakili generasi muda yang meraikan perayaan dengan cara kini.', 'budak_gajet.png'),
(114, 'Pak Nelayan', 'Nelayan peramah yang bersyukur dengan hasil laut (watak rekaan).', 'Mewakili sambutan San Pedro yang mensyukuri hasil laut.', 'nelayan.png'),
(121, 'Wartawan Muda', 'Wartawan muda yang merakam siaran khas tentang Perdana Menteri Malaysia (watak rekaan).', 'Menemu bual tokoh dan melaporkan sejarah kepimpinan negara kepada rakyat.', 'jejaka_melayu.png'),
(122, 'Guru Sejarah', 'Guru Sejarah yang buku teksnya tiba-tiba menghidupkan para Perdana Menteri (watak rekaan).', 'Menjadikan pelajaran tentang pemimpin negara mudah difahami oleh murid.', 'perempuan_melayu.png'),
(123, 'Murid Penyelidik', 'Murid yang membuat album kad koleksi Perdana Menteri untuk projek sekolah (watak rekaan).', 'Mengumpul maklumat tentang pemimpin negara untuk dikongsi bersama rakan.', 'budak_gajet.png'),
(124, 'Tunku Abdul Rahman Putra Al-Haj', 'Perdana Menteri pertama Malaysia.', 'Memperjuangkan kemerdekaan secara rundingan dan merealisasikan Pembentukan Malaysia pada 16 September 1963.', 'tunku_abdul_rahman.png'),
