INSERT INTO `Quest` (`questID`, `sceneID`, `questName`, `instruction`, `questType`, `description`, `questContent`) VALUES
(1, 'e1_n1_s1', 'Hujah Gagasan Tunku', 'Bantu Tunku Abdul Rahman menyampaikan empat faktor utama pembentukan Malaysia kepada media antarabangsa.', '3', 'Memahami faktor pembentukan Malaysia iaitu membendung komunis, keseimbangan kaum, mempercepat kemerdekaan, dan memajukan sosioekonomi.', '{\"prompt\": \"Wartawan bertanya kepada kau: apakah empat faktor utama yang menjadi asas cadangan pembentukan Malaysia?\", \"options\": [{\"text\": \"Membendung komunis, mengimbangi kaum, mempercepat kemerdekaan Borneo dan memajukan ekonomi.\", \"isCorrect\": true}, {\"text\": \"Membendung komunis, mengimbangi kaum, mengekalkan British di Borneo dan memajukan ekonomi.\", \"isCorrect\": false, \"consequence\": \"Akhbar menulis bahawa Tunku mahu British kekal di Borneo. Pemimpin Sabah dan Sarawak berhenti mempercayai cadangan itu sebelum perundingan bermula.\"}, {\"text\": \"Membendung komunis, menyeragamkan kaum, mempercepat kemerdekaan Borneo dan menambah wilayah.\", \"isCorrect\": false, \"consequence\": \"Wartawan menulis bahawa Tanah Melayu mahu menakluk Borneo. Pemimpin tempatan menolak untuk duduk berunding.\"}], \"aftermath\": \"Cadangan kau diterima dengan syak wasangka. Sebelum perundingan bermula, kepercayaan sudah mula hilang.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Membendung komunis, mengimbangi kaum, mempercepat kemerdekaan dan memajukan ekonomi.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tunku. Ringkas dan jelas. Tiada siapa boleh kata kita menyorok sesuatu.\"}, {\"text\": \"Membendung komunis, mengimbangi kaum, menambah cukai dan menguatkan tentera.\", \"isCorrect\": false, \"reaction\": \"Tunku, cukai dan tentera bukan sebab kita. Akhbar akan menulis bahawa gagasan ini membebankan rakyat.\"}, {\"text\": \"Menyeragamkan bahasa, menyeragamkan agama, mempercepat kemerdekaan dan memajukan ekonomi.\", \"isCorrect\": false, \"reaction\": \"Kita tidak mahu menyeragamkan sesiapa, Tunku. Itu yang paling ditakuti wilayah Borneo.\"}], \"clue\": \"Ghazali menyebut empat sebab, dan salah satunya tentang kemerdekaan wilayah Borneo.\"}]}'),
(2, 'e1_n1_s2', 'Analisis Laporan Suruhanjaya Cobbold', 'Nyahkod laporan rasmi Suruhanjaya Cobbold yang diserahkan pada 21 Jun 1962 untuk menentukan pendirian rakyat Sabah dan Sarawak.', '5', 'Mengenal pasti dapatan Laporan Suruhanjaya Cobbold 1962.', '{\"clueText\": \"Laporan mencatatkan satu pertiga penduduk menyokong penuh tanpa syarat, satu pertiga menyokong dengan syarat hak mereka dipelihara, dan satu pertiga lagi mahukan kemerdekaan berasingan terlebih dahulu.\", \"options\": [{\"text\": \"Dua pertiga penduduk menyokong Malaysia, sebahagiannya dengan syarat hak mereka dipelihara.\", \"isCorrect\": true}, {\"text\": \"Dua pertiga penduduk menyokong Malaysia tanpa sebarang syarat dan tuntutan.\", \"isCorrect\": false, \"consequence\": \"Jika kau mengabaikan syarat rakyat, perundingan JAK bermula tanpa tahu apa yang mereka mahu. Wakil Borneo merasa tidak didengar.\"}, {\"text\": \"Separuh penduduk menyokong Malaysia dan separuh lagi mahu pungutan suara baharu.\", \"isCorrect\": false, \"consequence\": \"Jika kau menganggap rakyat berpecah dua, perundingan ditangguh tanpa sebab. Konfrontasi dan Filipina mengambil kesempatan.\"}], \"aftermath\": \"Kau membaca laporan yang anggaran sahaja, tanpa memahami syarat rakyat. Perundingan seterusnya bermula dengan salah faham.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Tidak. Suruhanjaya Cobbold datang untuk mendengar pandangan anda sendiri.\", \"isCorrect\": true, \"reaction\": \"Itu yang mereka perlukan, Tunku. Mereka mahu didengar, bukan diarah.\"}, {\"text\": \"Ya. Keputusan sudah dibuat, suruhanjaya ini hanya untuk mengesahkannya.\", \"isCorrect\": false, \"reaction\": \"Kalau itu yang kau katakan, mereka berhenti bercakap. Laporan itu tidak bernilai lagi.\"}, {\"text\": \"Tidak. Pemimpin akan bercakap bagi pihak anda semasa suruhanjaya datang.\", \"isCorrect\": false, \"reaction\": \"Orang yang disenyapkan tidak akan mempercayai suruhanjaya mana pun, Tunku.\"}], \"clue\": \"Ghazali menyebut laporan tidak bernilai jika rakyat rasa dipaksa. Mereka mesti didengar.\"}]}'),
(3, 'e1_n1_s3', 'Padanan Syarat Perlembagaan JAK', 'Padankan tokoh dan perkara keistimewaan yang diperjuangkan dalam mesyuarat JAK.', '4', 'Memahami fungsi JAK dan peruntukan perlindungan hak Sabah serta Sarawak.', '{\"pairs\": [{\"text\": \"Lord Lansdowne & Tun Abdul Razak\", \"pair\": 1}, {\"text\": \"Pengerusi bersama Jawatankuasa Antara Kerajaan (JAK)\", \"pair\": 1}, {\"text\": \"Hak 20 Perkara Sabah\", \"pair\": 2}, {\"text\": \"Tuntutan perlindungan khas perlembagaan yang dikemukakan oleh pemimpin Sabah\", \"pair\": 2}, {\"text\": \"Kuasa Imigresen & Agama\", \"pair\": 3}, {\"text\": \"Perkara keistimewaan yang diberikan kepada Sabah dan Sarawak dalam perlembagaan\", \"pair\": 3}, {\"text\": \"Perlakuan Pentadbiran Tempatan\", \"pair\": 4}, {\"text\": \"Perlindungan perkhidmatan awam khas untuk penduduk tempatan Borneo\", \"pair\": 4}], \"aftermath\": \"Hak yang tidak ditulis hilang bersama pemimpin yang berjanji. Wakil Borneo bangun dan meninggalkan dewan.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Menulisnya dalam Perlembagaan Malaysia supaya menjadi undang-undang.\", \"isCorrect\": true, \"reaction\": \"Itu maksud kami, Tunku. Janji boleh dilupa, undang-undang tertulis tidak.\"}, {\"text\": \"Memasukkannya dalam surat perjanjian sahaja, supaya mudah dipinda kemudian.\", \"isCorrect\": false, \"reaction\": \"Surat perjanjian boleh dipinda diam-diam, Tunku. Kami mahu undang-undang yang tidak mudah diubah.\"}, {\"text\": \"Menulisnya selepas Malaysia terbentuk, apabila semua pihak sudah tenang.\", \"isCorrect\": false, \"reaction\": \"Selepas itu rakyat kami tiada kuasa berunding, Tunku. Itu bukan jalan yang adil.\"}], \"clue\": \"Tun Jugah berkata adat mesti ditulis dalam perlembagaan, bukan janji lisan.\"}]}'),
(4, 'e1_n1_s4', 'Cari Bukti Ancaman Negara', 'Cari bukti fizikal tentangan dalaman dan luaran yang cuba menghalang penubuhan Malaysia.', '2', 'Mengenal pasti bantahan SUPP di Sarawak, Konfrontasi Indonesia, dan tuntutan Filipina ke atas Sabah.', '{\"hotspots\":[{\"name\":\"Minit Bantahan Parti SUPP Sarawak yang menolak gabungan demi merdeka berasingan\",\"top\":\"68.9%\",\"left\":\"31.3%\"},{\"name\":\"Perisytiharan Konfrontasi Indonesia: slogan Ganyang Malaysia (20 Januari 1963)\",\"top\":\"80.5%\",\"left\":\"20.6%\"},{\"name\":\"Dokumen Tuntutan Rasmi Filipina ke atas Wilayah Sabah\",\"top\":\"72%\",\"left\":\"56.1%\"}],\"bgImage\":\"../assets/gameAsset/background/bilik_strategi_keselamatan.png\",\"aftermath\":\"Tanpa bukti yang jelas, setiap pihak menuduh pihak lain. Rundingan terhenti dan tekanan di sempadan bertambah.\",\"turns\":[{\"after\":3,\"options\":[{\"text\":\"Biar PBB bertanya kepada rakyat Borneo sendiri, bukan kita yang menjawab bagi pihak mereka.\",\"isCorrect\":true,\"reaction\":\"Itu yang paling sukar dipertikaikan, Tunku: suara rakyat sendiri.\"},{\"text\":\"Biar Parlimen Tanah Melayu mengundi bagi pihak rakyat Borneo.\",\"isCorrect\":false,\"reaction\":\"Itu sama seperti kita menjawab bagi pihak mereka, Tunku. Indonesia akan terus membantah.\"},{\"text\":\"Biar tentera kita menjaga sempadan dahulu, kemudian baru berunding dengan PBB.\",\"isCorrect\":false,\"reaction\":\"Tentera boleh menjaga sempadan, Tunku, tetapi tuntutan Filipina dan SUPP tidak akan hilang dengan senjata.\"}],\"clue\":\"Ghazali mencadangkan PBB bertanya kepada rakyat Borneo sendiri.\"}]}'),
(5, 'e1_n1_s5', 'Laporan Pengesahan PBB', 'Nyahkod kandungan laporan rasmi UNMM yang diterbitkan pada 14 September 1963.', '5', 'Memahami fungsi Perjanjian London 1963 dan pengesahan rasmi UNMM/PBB.', '{\"clueText\": \"Siasatan bebas PBB di Sabah dan Sarawak mengesahkan bahawa majoriti rakyat menyokong pembentukan Malaysia secara bebas dan demokratik.\", \"options\": [{\"text\": \"Majoriti rakyat Sabah dan Sarawak menyokong Malaysia secara bebas, tanpa paksaan.\", \"isCorrect\": true}, {\"text\": \"Majoriti rakyat Sabah dan Sarawak menyokong Malaysia, tetapi hanya selepas ditekan pemimpin.\", \"isCorrect\": false, \"consequence\": \"Jika laporan ini dianggap disahkan oleh tekanan, Indonesia menggunakannya untuk menolak keputusan PBB. Pengesahan antarabangsa goyah.\"}, {\"text\": \"Majoriti rakyat Sabah menyokong, tetapi Sarawak meminta pungutan suara baharu.\", \"isCorrect\": false, \"consequence\": \"Jika kau membaca laporan dengan salah, perundingan dibuka semula untuk Sarawak. Pemasyhuran tertangguh dan Konfrontasi bertambah kuat.\"}], \"aftermath\": \"Laporan yang salah dibaca menimbulkan kekeliruan. Indonesia dan Filipina menggunakannya untuk mempersoalkan Malaysia di PBB.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Rakyat Sabah dan Sarawak sendiri.\", \"isCorrect\": true, \"reaction\": \"Itulah sebab misi ini wujud, Tunku, dan sebab laporannya akan dipercayai.\"}, {\"text\": \"Wakil PBB bersama Kerajaan Tanah Melayu.\", \"isCorrect\": false, \"reaction\": \"Kalau kita turut menentukan, misi PBB tiada gunanya, Tunku. Indonesia dan Filipina menang hujah.\"}, {\"text\": \"Kerajaan British, kerana perjanjian sudah ditandatangani.\", \"isCorrect\": false, \"reaction\": \"Perjanjian sudah ditandatangani, Tunku, tetapi PBB mahu mendengar rakyat, bukan London.\"}], \"clue\": \"Ghazali menyebut Michelmore bertanya kepada rakyat Borneo, bukan kepada kita.\"}]}'),
(6, 'e1_n1_s6', 'Susun Kronologi Pembentukan Malaysia', 'Susun peristiwa penting pembentukan Malaysia dari awal hingga hari pemasyhuran mengikut urutan yang betul.', '1', 'Menyusun ikhtisar kronologi peristiwa Pembentukan Malaysia (1961–1963).', '{\"timelineItems\": [{\"id\": 1, \"year\": \"27 Mei 1961\", \"text\": \"Tunku Abdul Rahman mengumumkan cadangan Pembentukan Malaysia di Hotel Adelphi Singapura\", \"why\": \"Semuanya bermula apabila Tunku mengumumkan cadangan itu di hadapan wartawan.\"}, {\"id\": 2, \"year\": \"23 Julai 1961\", \"text\": \"Penubuhan Jawatankuasa Setia Kawan Malaysia JSKM\", \"why\": \"Selepas cadangan diumumkan, rakyat Borneo perlu faham maksud Malaysia, jadi JSKM ditubuhkan untuk menerangkannya.\"}, {\"id\": 3, \"year\": \"21 Jun 1962\", \"text\": \"Laporan Suruhanjaya Cobbold diserahkan mengesahkan sokongan 2/3 rakyat Borneo\", \"why\": \"Penerangan sahaja tidak cukup. Suruhanjaya Cobbold turun mendengar rakyat, dan laporannya mengesahkan sokongan.\"}, {\"id\": 4, \"year\": \"9 Julai 1963\", \"text\": \"Perjanjian Malaysia ditandatangani di Marlborough House London\", \"why\": \"Setelah sokongan rakyat disahkan dan Perlembagaan dirangka melalui JAK, perjanjian boleh ditandatangani di London.\"}, {\"id\": 5, \"year\": \"16 September 1963\", \"text\": \"Pemasyhuran Rasmi Malaysia diisytiharkan secara serentak\", \"why\": \"Selepas perjanjian dan siasatan PBB, tiada lagi halangan, maka Malaysia diisytiharkan.\"}], \"aftermath\": \"Peristiwa disusun dengan salah, dan sejarah yang kau baca di Stadium Merdeka tidak lagi bersambung. Kau perlu menyusunnya semula.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Supaya setiap wilayah dilihat sama taraf sebagai rakan.\", \"isCorrect\": true, \"reaction\": \"Betul, Tunku. Empat tempat, satu hari, satu negara.\"}, {\"text\": \"Supaya Kuala Lumpur dilihat sebagai pusat utama dan yang lain mengikut.\", \"isCorrect\": false, \"reaction\": \"Kalau begitu, Sarawak dilihat sebagai pengikut, Tunku. Itu yang kami tidak mahu.\"}, {\"text\": \"Supaya wartawan asing tidak sempat membuat liputan di setiap bandar.\", \"isCorrect\": false, \"reaction\": \"Kita mahu dunia melihat, Tunku. Serentak bermakna semua orang boleh menyaksikannya.\"}], \"clue\": \"Kalong berkata Sarawak mahu dilihat sebagai rakan, bukan pengikut. Fikirkan mengapa semua tempat membaca serentak.\"}]}'),
(7, 'e1_n2_s1', 'Menilai Kebajikan Rakyat Borneo', 'Bantu Donald Stephens menjelaskan faktor utama mengapa Sabah dan Sarawak perlu mempertimbangkan pembentukan Malaysia.', '3', 'Memahami faktor pembentukan Malaysia dari perspektif keselamatan dan pembangunan sosioekonomi Borneo.', '{\"prompt\": \"Rakyat Borneo bertanya kepada kau: apakah faedah utama yang diperoleh Sabah dan Sarawak melalui pembentukan Malaysia?\", \"options\": [{\"text\": \"Kemerdekaan lebih awal, perlindungan daripada komunis, keseimbangan kaum dan kemajuan ekonomi.\", \"isCorrect\": true}, {\"text\": \"Kemerdekaan lebih awal, perlindungan daripada komunis, penguasaan wilayah dan kemajuan ekonomi.\", \"isCorrect\": false, \"consequence\": \"Rakyat menganggap kau mahu Borneo dikuasai pihak lain. Perhimpunan menjadi gempar dan sokongan merosot.\"}, {\"text\": \"Kemerdekaan lebih lewat, perlindungan daripada British, keseimbangan kaum dan kemajuan ekonomi.\", \"isCorrect\": false, \"consequence\": \"Rakyat bertanya mengapa mahu menyertai Malaysia jika kemerdekaan bertambah lewat. Mereka menolak hujah kau serta-merta.\"}], \"aftermath\": \"Rakyat menilai kau sebagai pemimpin yang tidak menjaga kebajikan mereka. Perhimpunan bersurai dengan rasa curiga.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Dengar pandangan rakyat dan timbang untung ruginya dahulu.\", \"isCorrect\": true, \"reaction\": \"Itu cara orang yang menghormati tanahnya, Donald. Kita dengar, kita timbang, baru kita bercakap.\"}, {\"text\": \"Terima segera supaya Sabah cepat merdeka dan tidak ketinggalan.\", \"isCorrect\": false, \"reaction\": \"Tergesa-gesa begini, Donald, rakyat akan rasa tidak diajak berbincang.\"}, {\"text\": \"Tolak segera sehingga Tunku menjelaskan semua syaratnya secara bertulis.\", \"isCorrect\": false, \"reaction\": \"Menolak tanpa mendengar rakyat sama sahaja dengan diam ketika orang lain menentukan nasib kita, Donald.\"}], \"clue\": \"Tun Jugah bimbang hanya diberitahu, bukan ditanya. Jadi mulakan dengan mendengar rakyat.\"}]}'),
(8, 'e1_n2_s2', 'Padanan Tokoh dan Jawatankuasa Borneo', 'Padankan tokoh pejuang Borneo dan jawatankuasa tinjauan dengan peranannya yang betul.', '4', 'Mengenal pasti peranan Donald Stephens, Tun Temenggung Jugah, JSKM, dan Suruhanjaya Cobbold.', '{\"pairs\": [{\"text\": \"Donald Stephens\", \"pair\": 1}, {\"text\": \"Pengerusi JSKM yang memimpin penerangan pembentukan Malaysia di Borneo\", \"pair\": 1}, {\"text\": \"Tun Temenggung Jugah\", \"pair\": 2}, {\"text\": \"Pemimpin masyarakat Iban Sarawak yang menegaskan perlindungan hak adat tempatan\", \"pair\": 2}, {\"text\": \"JSKM (23 Julai 1961)\", \"pair\": 3}, {\"text\": \"Jawatankuasa penerangan awal bagi meyakinkan pemimpin dan rakyat Borneo\", \"pair\": 3}, {\"text\": \"Laporan Cobbold (21 Jun 1962)\", \"pair\": 4}, {\"text\": \"Mengesahkan dua pertiga (2/3) penduduk Sabah dan Sarawak menyokong Malaysia\", \"pair\": 4}], \"aftermath\": \"Rakyat tidak lagi mempercayai suruhanjaya. Kampung demi kampung berhenti bercakap kepada Cobbold.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Ya, Suruhanjaya Cobbold datang untuk mencatat pandangan anda.\", \"isCorrect\": true, \"reaction\": \"Betul, Donald, dan sebab itu laporan mereka nanti dipercayai.\"}, {\"text\": \"Ya, tetapi hanya pandangan pemimpin kampung yang akan dicatat.\", \"isCorrect\": false, \"reaction\": \"Rakyat biasa pun mahu didengar, Donald. Kalau tidak, mereka berhenti percaya.\"}, {\"text\": \"Tidak pasti, kerana keputusan Malaysia mungkin sudah dibuat di London.\", \"isCorrect\": false, \"reaction\": \"Jawapan begitu menguatkan syak mereka, Donald. Jangan biarkan mereka berhenti bercakap.\"}], \"clue\": \"Tun Jugah berkata Cobbold datang untuk mendengar rakyat. Itulah tujuannya.\"}]}'),
(9, 'e1_n2_s3', 'Keputusan Hak Keistimewaan Borneo', 'Bantu Donald Stephens dan Tun Temenggung Jugah memastikan tuntutan hak keistimewaan Borneo diterima dalam JAK.', '3', 'Memahami perkara utama dalam Hak 20 Perkara Sabah dan draf Perlembagaan Malaysia oleh JAK.', '{\"prompt\": \"Apakah tuntutan utama yang diperjuangkan oleh pemimpin Borneo untuk dimasukkan ke dalam Perlembagaan Malaysia?\", \"options\": [{\"text\": \"Hak imigresen, agama, bahasa dan perkhidmatan awam tempatan dilindungi dalam Perlembagaan.\", \"isCorrect\": true}, {\"text\": \"Hak imigresen, agama, bahasa dan perkhidmatan awam tempatan dijanjikan secara lisan oleh pemimpin.\", \"isCorrect\": false, \"consequence\": \"Janji lisan hilang apabila pemimpin bertukar. Beberapa tahun kemudian rakyat Borneo tidak dapat menuntut hak mereka.\"}, {\"text\": \"Hak imigresen, agama, bahasa dan perkhidmatan awam tempatan dipindahkan ke Kerajaan Pusat sahaja.\", \"isCorrect\": false, \"consequence\": \"Kuasa ke atas tanah dan imigresen beralih ke Kuala Lumpur. Rakyat Borneo merasa kehilangan kawalan atas tanah mereka.\"}], \"aftermath\": \"Tuntutan Borneo tidak termasuk dalam teks akhir. Apabila rakyat membacanya, mereka merasa dikhianati.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Perlindungan hak imigresen, agama, bahasa dan perkhidmatan awam, ditulis dalam Perlembagaan.\", \"isCorrect\": true, \"reaction\": \"Itulah cara ia menjadi undang-undang, Donald. Kita tulis satu demi satu.\"}, {\"text\": \"Perlindungan hak imigresen, agama, bahasa dan perkhidmatan awam, dicatat dalam surat sokongan.\", \"isCorrect\": false, \"reaction\": \"Surat sokongan mudah dilupakan, Donald. Itu yang Tun Jugah takutkan.\"}, {\"text\": \"Perlindungan hak imigresen, agama, bahasa dan perkhidmatan awam, dijanjikan oleh pemimpin lisan.\", \"isCorrect\": false, \"reaction\": \"Aku percaya, Donald, tetapi rakyat memerlukan jaminan bertulis, bukan hanya kepercayaan.\"}], \"clue\": \"Tun Jugah tidak mahu tuntutan hanya disebut dalam lampiran. Ia mesti ada dalam Perlembagaan.\"}]}'),
(10, 'e1_n2_s4', 'Cari Bukti Ancaman di Borneo', 'Cari dokumen bantahan politik tempatan dan bukti pencerobohan luar di sempadan Borneo.', '2', 'Mengenal pasti cabaran pembentukan Malaysia di Borneo (SUPP, Konfrontasi Indonesia, tuntutan Filipina).', '{\"hotspots\":[{\"name\":\"Dokumen Bantahan Parti SUPP Sarawak yang menolak cadangan Pembentukan Malaysia\",\"top\":\"86.3%\",\"left\":\"54.4%\"},{\"name\":\"Laporan Pencerobohan Tentera Konfrontasi Indonesia di Sempadan Sabah dan Sarawak\",\"top\":\"81.2%\",\"left\":\"21.1%\"},{\"name\":\"Nota Tuntutan Filipina ke atas Wilayah Sabah\",\"top\":\"69.5%\",\"left\":\"31.5%\"}],\"bgImage\":\"../assets/gameAsset/background/bilik_strategi_keselamatan.png\",\"aftermath\":\"Tanpa bukti, dakwaan SUPP, Indonesia dan Filipina tidak dapat dijawab. Rakyat mula ragu-ragu.\",\"turns\":[{\"after\":3,\"options\":[{\"text\":\"Tunjukkan bahawa hak Borneo sudah ditulis dalam Perlembagaan melalui JAK.\",\"isCorrect\":true,\"reaction\":\"Itu jawapan yang boleh dipegang, Donald. Hak yang tertulis tidak mudah dipadam.\"},{\"text\":\"Tunjukkan bahawa tentera kita cukup kuat menghadapi Konfrontasi dan tuntutan Filipina.\",\"isCorrect\":false,\"reaction\":\"Kekuatan tidak menjawab kebimbangan SUPP, Donald. Mereka mahu jaminan hak, bukan senjata.\"},{\"text\":\"Tunjukkan bahawa SUPP tidak berhak bersuara kerana mereka pembangkang.\",\"isCorrect\":false,\"reaction\":\"Menyenyapkan SUPP hanya menguatkan kebimbangan mereka, Donald.\"}],\"clue\":\"Kalong berkata SUPP mesti dijawab dengan hak yang sudah ditulis dalam Perlembagaan melalui JAK.\"}]}'),
(11, 'e1_n2_s5', 'Nyahkod Hasil Tinjauan PBB', 'Nyahkod kenyataan Laporan UNMM yang diterbitkan pada 14 September 1963 di Borneo.', '5', 'Memahami peranan Perjanjian London 1963 dan pengesahan rasmi PBB di Sabah dan Sarawak.', '{\"clueText\": \"Penilaian bebas Suruhanjaya PBB mengesahkan bahawa majoriti rakyat Sabah dan Sarawak tetap teguh memilih untuk menyertai Malaysia.\", \"options\": [{\"text\": \"Majoriti rakyat Sabah dan Sarawak menyokong Malaysia, dan pilihan itu dibuat secara bebas.\", \"isCorrect\": true}, {\"text\": \"Majoriti rakyat Sabah dan Sarawak menolak Malaysia, dan pilihan itu dibuat secara bebas.\", \"isCorrect\": false, \"consequence\": \"Jika laporan menolak Malaysia, Perjanjian London terbatal dan rundingan dua tahun hilang. Tetapi itu bukan laporan UNMM.\"}, {\"text\": \"Majoriti rakyat Sabah dan Sarawak menyokong Malaysia, tetapi mahu kekal di bawah British dahulu.\", \"isCorrect\": false, \"consequence\": \"Jika Borneo kekal di bawah British, kemerdekaan tertangguh sekali lagi. Pemasyhuran 16 September tidak dapat diteruskan.\"}], \"aftermath\": \"Laporan yang tidak jujur tidak dipercayai sesiapa. Indonesia dan Filipina menggunakannya sebagai hujah menentang Malaysia.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Menjawab dengan jujur, mengikut kehendak hati sendiri.\", \"isCorrect\": true, \"reaction\": \"Itu yang kami mahu, Donald. Kejujuran kita ialah bukti terbaik.\"}, {\"text\": \"Menjawab seperti yang diminta pemimpin supaya perjanjian cepat disahkan.\", \"isCorrect\": false, \"reaction\": \"Kalau begitu, misi ini membuang masa dan Indonesia berkata kita memaksa rakyat, Donald.\"}, {\"text\": \"Menjawab secara umum tanpa menyebut pendirian sendiri.\", \"isCorrect\": false, \"reaction\": \"Jawapan kabur menjadikan suara kita tidak dikira, Donald. Jangan biarkan orang lain bercakap bagi pihak kita.\"}], \"clue\": \"Kalong berkata Michelmore mahu mendengar sendiri daripada rakyat, jadi jawapan mesti datang daripada hati sendiri.\"}]}'),
(12, 'e1_n2_s6', 'Susun Garis Masa Pemasyhuran Borneo', 'Susun peristiwa penting perjalanan pembentukan Malaysia mengikut urutan kronologi dari perspektif Borneo.', '1', 'Menyusun ikhtisar urutan kronologi Pembentukan Malaysia (1961–1963).', '{\"timelineItems\": [{\"id\": 1, \"year\": \"27 Mei 1961\", \"text\": \"Pengumuman Cadangan Malaysia oleh Tunku Abdul Rahman di Singapura\", \"why\": \"Pengumuman Tunku membuka peluang kepada Borneo untuk bersuara.\"}, {\"id\": 2, \"year\": \"23 Julai 1961\", \"text\": \"Penubuhan Jawatankuasa Setia Kawan Malaysia JSKM di bawah Donald Stephens\", \"why\": \"Donald Stephens mengetuai JSKM supaya rakyat Sabah dan Sarawak memahami cadangan itu sebelum menjawab.\"}, {\"id\": 3, \"year\": \"21 Jun 1962\", \"text\": \"Penyerahan Laporan Suruhanjaya Cobbold mengesahkan sokongan 2/3 rakyat Borneo\", \"why\": \"Kemudian Cobbold mendengar rakyat sendiri, dan laporannya menunjukkan dua pertiga menyokong.\"}, {\"id\": 4, \"year\": \"9 Julai 1963\", \"text\": \"Penandatanganan Perjanjian Malaysia di Marlborough House London\", \"why\": \"Dengan sokongan itu dan hak Borneo dijamin dalam Perlembagaan, perjanjian ditandatangani di London.\"}, {\"id\": 5, \"year\": \"16 September 1963\", \"text\": \"Pembacaan Pemasyhuran Malaysia di Kota Kinabalu dan Kuching\", \"why\": \"Selepas UNMM mengesahkan pilihan rakyat, pemimpin Borneo membacakan Pemasyhuran di Kota Kinabalu dan Kuching.\"}], \"aftermath\": \"Urutan peristiwa terganggu, dan kisah Pemasyhuran tidak lagi mengalir. Kau perlu menyusunnya semula.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Donald Stephens di Sabah, Stephen Kalong Ningkan di Sarawak.\", \"isCorrect\": true, \"reaction\": \"Betul, Donald. Dua tempat, satu hari, satu negara.\"}, {\"text\": \"Tun Mustapha di Sabah, Stephen Kalong Ningkan di Sarawak.\", \"isCorrect\": false, \"reaction\": \"Tun Mustapha berdiri bersama kita, Donald, tetapi bukan dia yang membacanya di Sabah.\"}, {\"text\": \"Donald Stephens di Sabah, Tun Jugah di Sarawak.\", \"isCorrect\": false, \"reaction\": \"Tun Jugah menyokong kita, Donald, tetapi bukan dia yang membacanya di Kuching.\"}], \"clue\": \"Kalong berkata dia membacanya di Kuching, dan kau di Kota Kinabalu.\"}]}'),
(13, 'e1_n3_s1', 'Strategi Benteng Keselamatan', 'Bantu Tun Ghazali Shafie menggariskan faktor keselamatan dan kestabilan utama pembentukan Malaysia.', '3', 'Memahami faktor pembentukan Malaysia iaitu membendung komunis, keseimbangan kaum, kemerdekaan, dan sosioekonomi.', '{\"prompt\": \"Apakah pertimbangan keselamatan utama yang menjadikan pembentukan Malaysia sangat mendesak?\", \"options\": [{\"text\": \"Membendung komunis di Singapura dan Sarawak serta menjamin kestabilan politik rantau.\", \"isCorrect\": true}, {\"text\": \"Membendung komunis di Singapura dan Sarawak dengan bantuan tentera asing yang kekal.\", \"isCorrect\": false, \"consequence\": \"Jika tentera asing menetap, kedaulatan hilang sebelum Malaysia terbentuk. Tunku menolak nasihat itu serta-merta.\"}, {\"text\": \"Membendung komunis di Singapura dan Sarawak dengan mengurangkan kerjasama antara wilayah.\", \"isCorrect\": false, \"consequence\": \"Jika kerjasama antara wilayah dikurangkan, komunis menembusi jurang itu dan ancaman bertambah besar.\"}], \"aftermath\": \"Nasihat kau tidak lengkap. Pelan keselamatan tidak merangkumi semua ancaman, dan jurang itu dimanfaatkan pihak lawan.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Membendung komunis, menjaga kaum, mempercepat kemerdekaan dan memajukan ekonomi.\", \"isCorrect\": true, \"reaction\": \"Tepat, Ghazali. Empat sebab, bukan satu.\"}, {\"text\": \"Membendung komunis, menjaga kaum, melambatkan kemerdekaan dan memajukan ekonomi.\", \"isCorrect\": false, \"reaction\": \"Melambatkan kemerdekaan bukan sebab kita, Ghazali. Borneo akan menolak sebelum sempat berunding.\"}, {\"text\": \"Membendung komunis, menjaga British, mempercepat kemerdekaan dan memajukan ekonomi.\", \"isCorrect\": false, \"reaction\": \"Kita bukan menjaga British, Ghazali. Hujah itu mudah dipatahkan Indonesia.\"}], \"clue\": \"Tunku menyebut empat sebab: komunis, kaum, kemerdekaan Borneo dan ekonomi. Sebutkan kesemuanya.\"}]}'),
(14, 'e1_n3_s2', 'Padanan Misi Tinjauan Cobbold', 'Padankan JSKM, Suruhanjaya Cobbold, laporannya dan ahli tempatan dengan maklumat yang betul.', '4', 'Mengenal pasti peranan JSKM dan Suruhanjaya Cobbold.', '{\"pairs\": [{\"text\": \"JSKM (23 Julai 1961)\", \"pair\": 1}, {\"text\": \"Jawatankuasa penerangan awal di bawah pimpinan Donald Stephens\", \"pair\": 1}, {\"text\": \"Suruhanjaya Cobbold (17 Jan 1962)\", \"pair\": 2}, {\"text\": \"Meninjau pandangan rakyat Sabah dan Sarawak di kampung-kampung\", \"pair\": 2}, {\"text\": \"Laporan Cobbold (21 Jun 1962)\", \"pair\": 3}, {\"text\": \"Dua pertiga menyokong; selebihnya mahu merdeka dahulu\", \"pair\": 3}, {\"text\": \"Ghazali Shafie dan Wong Pow Nee\", \"pair\": 4}, {\"text\": \"Ahli tempatan dalam Suruhanjaya Cobbold\", \"pair\": 4}], \"aftermath\": \"Misi dan jawatankuasa disalah padankan, dan laporan menjadi kelam-kabut. Tiada siapa pasti siapa bertanggungjawab ke atas apa.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Menjawab keraguan itu dengan menulis jaminan hak mereka dalam Perlembagaan.\", \"isCorrect\": true, \"reaction\": \"Betul, Ghazali. Keraguan hilang apabila ada jaminan bertulis, bukan janji kosong.\"}, {\"text\": \"Menjawab keraguan itu dengan janji lisan daripada Perdana Menteri sahaja.\", \"isCorrect\": false, \"reaction\": \"Janji lisan tidak menenangkan keraguan, Ghazali. Mereka mahukan bukti tertulis.\"}, {\"text\": \"Menangguhkan Malaysia sehingga seluruh rakyat Borneo menyokong sepenuhnya.\", \"isCorrect\": false, \"reaction\": \"Jika semua mesti setuju, Malaysia tidak akan terbentuk, Ghazali. Tetapi suara yang ragu mesti dihormati.\"}], \"clue\": \"Kau sendiri berkata keraguan mesti dijawab, bukan disenyapkan. JAK menulis Perlembagaan, jadi jawapannya ditulis di sana.\"}]}'),
(15, 'e1_n3_s3', 'Jaminan Hak Borneo dalam Perlembagaan', 'Bantu Tun Ghazali Shafie memastikan hak Sabah dan Sarawak dijamin dalam Perlembagaan melalui JAK.', '3', 'Memahami peranan JAK serta Hak 20 Perkara Sabah dan 18 Perkara Sarawak.', '{\"prompt\": \"Seorang wakil Borneo bertanya kepada kau: bagaimana Hak 20 Perkara Sabah dan 18 Perkara Sarawak dapat dilindungi dengan kukuh?\", \"options\": [{\"text\": \"Hak itu ditulis dalam Perlembagaan Malaysia sebagai undang-undang yang mengikat.\", \"isCorrect\": true}, {\"text\": \"Hak itu dicatat sebagai janji lisan pemimpin pada hari penandatanganan perjanjian.\", \"isCorrect\": false, \"consequence\": \"Janji lisan hilang apabila pemimpin bertukar. Beberapa tahun kemudian rakyat Borneo tidak dapat menuntut hak mereka.\"}, {\"text\": \"Hak itu ditangguhkan sehingga selepas Malaysia terbentuk dan kerajaan baharu bersidang.\", \"isCorrect\": false, \"consequence\": \"Selepas Malaysia terbentuk, Borneo tiada kuasa berunding lagi. Pemimpin Sabah dan Sarawak menarik sokongan.\"}], \"aftermath\": \"Hak yang tidak ditulis hilang bersama pemimpin yang berjanji. Wakil Borneo bangun dan meninggalkan dewan.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Menulis jaminan itu dalam Perlembagaan sebagai undang-undang.\", \"isCorrect\": true, \"reaction\": \"Itu maksud kami, Ghazali. Janji boleh dilupa, undang-undang tertulis tidak.\"}, {\"text\": \"Menerima janji lisan para pemimpin pada hari penandatanganan itu.\", \"isCorrect\": false, \"reaction\": \"Janji lisan hilang bersama orang yang berjanji, Ghazali. Kami sudah banyak melihatnya.\"}, {\"text\": \"Menangguhkan perbincangan sehingga selepas Malaysia terbentuk nanti.\", \"isCorrect\": false, \"reaction\": \"Selepas itu rakyat kami tiada kuasa berunding lagi, Ghazali. Itu bukan jalan yang adil.\"}], \"clue\": \"Tun Jugah berkata adat mesti ditulis, bukan janji lisan. Hak yang tertulis dalam Perlembagaan menjadi undang-undang.\"}]}'),
(16, 'e1_n3_s4', 'Cari Bukti Ancaman Keselamatan', 'Cari dokumen bukti tentangan dalaman dan pencerobohan luaran terhadap Malaysia.', '2', 'Mengenal pasti bantahan SUPP, Konfrontasi Indonesia, dan tuntutan Filipina ke atas Sabah.', '{\"hotspots\":[{\"name\":\"Risalah Bantahan Parti SUPP Sarawak yang menolak cadangan Persekutuan\",\"top\":\"48.6%\",\"left\":\"58.6%\"},{\"name\":\"Perisytiharan Konfrontasi Indonesia (Ganyang Malaysia) pada 20 Januari 1963\",\"top\":\"55%\",\"left\":\"62%\"},{\"name\":\"Teks Tuntutan Filipina ke atas Wilayah Sabah\",\"top\":\"31.8%\",\"left\":\"67.6%\"}],\"bgImage\":\"../assets/gameAsset/background/perancangan_pembentukan_malaysia.png\",\"aftermath\":\"Ancaman yang tidak dikenal pasti tidak dapat dijawab. Sempadan terdedah dan rundingan diplomasi terganggu.\",\"turns\":[{\"after\":3,\"options\":[{\"text\":\"Konfrontasi, kerana ia ancaman keselamatan sebenar di sempadan.\",\"isCorrect\":true,\"reaction\":\"Betul, Ghazali. Keselamatan dahulu, baru diplomasi boleh berjalan.\"},{\"text\":\"SUPP, kerana ia pertikaian dalam negeri yang boleh merebak.\",\"isCorrect\":false,\"reaction\":\"SUPP penting dan boleh dirunding, Ghazali. Tetapi tentera di sempadan tidak menunggu.\"},{\"text\":\"Filipina, kerana tuntutannya boleh menjejaskan kedaulatan Sabah.\",\"isCorrect\":false,\"reaction\":\"Tuntutan itu serius, Ghazali, tetapi ia diplomasi. Ancaman di sempadan lebih mendesak.\"}],\"clue\":\"Kau sendiri berkata Konfrontasi ialah ancaman keselamatan, sementara dua lagi boleh dijawab dengan perundingan.\"}]}'),
(17, 'e1_n3_s5', 'Nyahkod Keputusan Misi PBB', 'Nyahkod penemuan rasmi Laporan UNMM yang dikeluarkan pada 14 September 1963.', '5', 'Memahami peranan Perjanjian London 1963 dan pengesahan rasmi UNMM/PBB.', '{\"clueText\": \"Siasatan PBB mengesahkan bahawa majoriti rakyat Sabah dan Sarawak menyokong pembentukan Malaysia secara demokratik, sekali gus menolak dakwaan Indonesia dan Filipina.\", \"options\": [{\"text\": \"Majoriti rakyat Sabah dan Sarawak menyokong Malaysia, dan PBB mengesahkannya.\", \"isCorrect\": true}, {\"text\": \"Majoriti rakyat Sabah dan Sarawak menyokong Malaysia, tetapi PBB menolak mengesahkannya.\", \"isCorrect\": false, \"consequence\": \"Jika PBB tidak mengesahkan, Indonesia dan Filipina menggunakannya untuk menyerang Malaysia. Pemasyhuran tertangguh.\"}, {\"text\": \"Majoriti rakyat Sabah dan Sarawak mahu bergabung dengan Indonesia, dan PBB mengesahkannya.\", \"isCorrect\": false, \"consequence\": \"Jika Borneo bergabung dengan Indonesia, negara baharu itu hilang sebelum lahir. Tetapi itu bukan penemuan laporan.\"}], \"aftermath\": \"Laporan dicurigai kerana disaring oleh pihak berkuasa. Indonesia menolaknya, dan pengesahan antarabangsa goyah.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Biarkan mereka bertemu sesiapa sahaja sendiri tanpa kita.\", \"isCorrect\": true, \"reaction\": \"Itu nasihat yang baik, Ghazali. Laporan yang dipercayai ialah laporan yang tidak kita sentuh.\"}, {\"text\": \"Temani pegawai UNMM ke setiap pertemuan untuk menjawab soalan.\", \"isCorrect\": false, \"reaction\": \"Kalau kita ada, rakyat berhati-hati, Ghazali, dan Indonesia berkata kita memengaruhi mereka.\"}, {\"text\": \"Sediakan senarai orang yang akan ditemui oleh pegawai UNMM.\", \"isCorrect\": false, \"reaction\": \"Senarai itu menjadikan laporan kita yang tulis, Ghazali, bukan PBB.\"}], \"clue\": \"Tun Razak berkata PBB mahu pegawainya bebas bertemu sesiapa tanpa kita campur tangan.\"}]}'),
(18, 'e1_n3_s6', 'Kronologi Keselamatan dan Kedaulatan', 'Susun peristiwa penting perjalanan pembentukan Malaysia mengikut urutan kronologi yang betul dari awal hingga kemuncak pemasyhuran.', '1', 'Menyusun ikhtisar urutan kronologi Pembentukan Malaysia (1961–1963).', '{\"timelineItems\": [{\"id\": 1, \"year\": \"27 Mei 1961\", \"text\": \"Pengumuman Cadangan Malaysia oleh Tunku Abdul Rahman di Hotel Adelphi Singapura\", \"why\": \"Ancaman komunis menjadi sebab utama cadangan ini diumumkan.\"}, {\"id\": 2, \"year\": \"23 Julai 1961\", \"text\": \"Penubuhan Jawatankuasa Setia Kawan Malaysia JSKM\", \"why\": \"Rakyat perlu diyakinkan untuk menolak pengaruh yang mengancam keselamatan, jadi JSKM ditubuhkan.\"}, {\"id\": 3, \"year\": \"21 Jun 1962\", \"text\": \"Laporan Suruhanjaya Cobbold diserahkan mengesahkan sokongan 2/3 rakyat Borneo\", \"why\": \"Cobbold menilai suara sebenar rakyat, dan laporannya mengesahkan sokongan walaupun ada bantahan.\"}, {\"id\": 4, \"year\": \"9 Julai 1963\", \"text\": \"Perjanjian Malaysia ditandatangani di Marlborough House London\", \"why\": \"Selepas bantahan SUPP dijawab dan Konfrontasi dihadapi, perjanjian ditandatangani di London.\"}, {\"id\": 5, \"year\": \"16 September 1963\", \"text\": \"Pengisytiharan Rasmi Pemasyhuran Malaysia secara serentak\", \"why\": \"Dengan keselamatan terjamin dan PBB mengesahkan sokongan, Malaysia diisytiharkan secara serentak.\"}], \"aftermath\": \"Susunan hari Pemasyhuran terganggu. Empat bandar tidak serentak dan keselamatan majlis goyah.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Memastikan majlis berjalan lancar tanpa gangguan keselamatan.\", \"isCorrect\": true, \"reaction\": \"Betul, Ghazali. Tugas yang jarang dipuji, tetapi tanpanya tiada majlis.\"}, {\"text\": \"Berdiri di sebelah Tunku supaya diambil gambar bersama.\", \"isCorrect\": false, \"reaction\": \"Kamera tidak menjaga sempadan, Ghazali. Kerja kita di belakang tabir.\"}, {\"text\": \"Mengubah jadual majlis supaya mula lebih awal di semua bandar.\", \"isCorrect\": false, \"reaction\": \"Empat bandar sudah diselaraskan, Ghazali. Jika satu berubah, yang lain terkacau.\"}], \"clue\": \"Satu kesilapan masa akan dilihat semua orang, jadi keselamatan dan susunan ialah tugas utama kau.\"}]}'),
(201, 'e2_n1_s1', 'Nyahkod Catatan Lama Perlis', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Perlis melalui asal nama.', '{\"clueText\": \"Catatan lama, tulisan sudah pudar: namanya dikaitkan dengan Perkataan Siam \'phrau loi\', iaitu kelapa hanyut.\", \"options\": [{\"text\": \"Negeri itu ialah Perlis.\", \"isCorrect\": true}, {\"text\": \"Negeri itu ialah Perak.\", \"isCorrect\": false, \"consequence\": \"Maklumat itu sebenarnya milik Perak! Penduduk Perlis mengerut dahi dan berasa nama negeri mereka disalah ertikan.\"}, {\"text\": \"Negeri itu ialah Melaka.\", \"isCorrect\": false, \"consequence\": \"Kau menyebut maklumat Melaka untuk Perlis. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut.\"}], \"aftermath\": \"Catatan itu dihantar ke negeri yang salah. Maklumat Perlis hilang daripada simpanan.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Daripada perkataan Siam \'phrau loi\' (kelapa hanyut), perkataan tempatan \'peroleh\' atau tokoh Tok Perlis\", \"isCorrect\": true, \"reaction\": \"Betul, Tok! Jawapan itu kena tepat pada Perlis. Penduduk bertepuk tangan.\"}, {\"text\": \"Dikaitkan dengan kilatan ikan di dalam air atau warna bijih timah putih yang berkilat seperti perak\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Perak, Tok! Perlis lain ceritanya. Orang ramai mengerut dahi.\"}, {\"text\": \"Sempena pokok Melaka tempat Parameswara berehat, atau \'Malakat\' dalam rujukan Arab yang bermaksud pusat pedagang\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Melaka, bukan Perlis. Cuba ingat semula.\"}], \"clue\": \"Ingat kata kunci tentang Perlis: kelapa hanyut.\"}]}'),
(202, 'e2_n1_s2', 'Soalan Sergahan di Kedah', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang asal nama bagi Kedah.', '3', 'Mengenal pasti asal nama bagi Kedah.', '{\"prompt\": \"Tiba-tiba seorang cikgu yang menjinjit bakul buku menahan kau dan bertanya: apakah asal usul nama Kedah?\", \"options\": [{\"text\": \"Daripada \'Kheddah\' (perangkap gajah), \'Qadah\' dalam bahasa Arab (gelas berkaki) atau \'Kadaram\' dalam rujukan India\", \"isCorrect\": true}, {\"text\": \"Sempena Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga yang disebut selangur\", \"isCorrect\": false, \"consequence\": \"Kau menyebut maklumat Selangor untuk Kedah. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut.\"}, {\"text\": \"Daripada perkataan Arab \'Jauhar\' (batu permata bernilai), dan dikenali sebagai Ujung Tanah dalam Sulalatus Salatin\", \"isCorrect\": false, \"consequence\": \"Itu fakta Johor, bukan Kedah! Pelajar yang mendengarnya menulis jawapan salah dalam buku, dan cikgu terpaksa membetulkannya kemudian.\"}], \"aftermath\": \"Orang ramai pulang dengan jawapan Kedah yang salah, dan cerita itu tersebar semula dengan silap.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Daripada \'Kheddah\' (perangkap gajah), \'Qadah\' dalam bahasa Arab (gelas berkaki) atau \'Kadaram\' dalam rujukan India\", \"isCorrect\": true, \"reaction\": \"Hebat, Tok! Itulah dia tentang Kedah. Semua mengangguk setuju.\"}, {\"text\": \"Sempena Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga yang disebut selangur\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Selangor, bukan Kedah. Cuba ingat semula.\"}, {\"text\": \"Daripada perkataan Arab \'Jauhar\' (batu permata bernilai), dan dikenali sebagai Ujung Tanah dalam Sulalatus Salatin\", \"isCorrect\": false, \"reaction\": \"Hmm, itu milik Johor, bukan Kedah. Ada yang tergelak kecil di belakang.\"}], \"clue\": \"Ingat kata kunci tentang Kedah: perangkap gajah.\"}]}'),
(203, 'e2_n1_s3', 'Misi Lambang: Jata, Bendera dan Radio Pulau Pinang', 'Cari jata, bendera dan radio pada gambar untuk mengenal pasti fakta tentang Pulau Pinang. Mata tajam, ya!', '2', 'Mengenal pasti maklumat asal nama bagi Pulau Pinang daripada jata, bendera dan radio.', '{\"hotspots\":[{\"name\":\"Pada jata: asal nama, berkait dengan pokok pinang\",\"top\":\"27.4%\",\"left\":\"70.7%\"},{\"name\":\"Di tiang bendera: ketua negeri bergelar Yang di-Pertua Negeri\",\"top\":\"23.8%\",\"left\":\"45.7%\"},{\"name\":\"Di radio: lagu \'Untuk Negeri Kita\'\",\"top\":\"74%\",\"left\":\"10%\"}],\"bgImage\":\"../assets/gameAsset/background/negeri_pulau_pinang.png\",\"aftermath\":\"Bukti tentang Pulau Pinang terlepas pandang. Catatan tentang jata, bendera dan lagunya menjadi samar, dan penduduk kecewa.\",\"turns\":[{\"after\":2,\"options\":[{\"text\":\"Sempena pokok pinang yang banyak tumbuh di pulau itu, yang dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga\",\"isCorrect\":true,\"reaction\":\"Ya, ya, itulah jawapannya, Tok! Pulau Pinang memang begitu. Ada yang bersorak kecil.\"},{\"text\":\"Penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada \'nagari\'\",\"isCorrect\":false,\"reaction\":\"Hmm, itu milik Negeri Sembilan, bukan Pulau Pinang. Ada yang tergelak kecil di belakang.\"},{\"text\":\"Diambil daripada nama pokok mahang, dan dikenali juga sebagai Inderapura dalam catatan lama\",\"isCorrect\":false,\"reaction\":\"Silap negeri, Tok! Itu tentang Pahang, bukan Pulau Pinang. Cuba sekali lagi!\"}],\"clue\":\"Ingat kata kunci tentang Pulau Pinang: pokok pinang.\"}]}'),
(204, 'e2_n1_s4', 'Padanan Pantas: Asal nama', 'Cepat, padankan setiap negeri dengan asal namanya yang betul sebelum kad bercampur aduk!', '4', 'Mengenal pasti asal nama bagi Perak dan negeri lain.', '{\"pairs\": [{\"text\": \"Perak\", \"pair\": 1}, {\"text\": \"Kilatan ikan atau bijih timah putih yang berkilat seperti perak\", \"pair\": 1}, {\"text\": \"Melaka\", \"pair\": 2}, {\"text\": \"Pokok Melaka tempat Parameswara berehat\", \"pair\": 2}, {\"text\": \"Terengganu\", \"pair\": 3}, {\"text\": \"\'Taring anu\' (taring binatang liar) atau \'terang ganu\' (pelangi)\", \"pair\": 3}, {\"text\": \"Sabah\", \"pair\": 4}, {\"text\": \"Sejenis pisang, iaitu pisang saba atau pisang jaba\", \"pair\": 4}], \"aftermath\": \"Kad Perak tersalah letak, dan negeri-negeri lain pun ikut berselerak.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Dikaitkan dengan kilatan ikan di dalam air atau warna bijih timah putih yang berkilat seperti perak\", \"isCorrect\": true, \"reaction\": \"Tepat sekali, Tok! Itulah maklumat Perak yang patut diingat. Sorakan bergema di sekeliling!\"}, {\"text\": \"Sempena pokok Melaka tempat Parameswara berehat, atau \'Malakat\' dalam rujukan Arab yang bermaksud pusat pedagang\", \"isCorrect\": false, \"reaction\": \"Silap negeri, Tok! Itu tentang Melaka, bukan Perak. Cuba sekali lagi!\"}, {\"text\": \"Daripada sebutan \'taring anu\' (taring harimau atau binatang liar) atau \'terang ganu\' yang bermaksud pelangi\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Terengganu, Tok! Perak lain ceritanya. Orang ramai mengerut dahi.\"}], \"clue\": \"Ingat kata kunci tentang Perak: bijih timah putih.\"}]}'),
(205, 'e2_n1_s5', 'Nyahkod Catatan Lama Selangor', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Selangor melalui asal nama.', '{\"clueText\": \"Catatan lama, tulisan sudah pudar: namanya dikaitkan dengan Sungai negeri ini, pokok mentagau atau serangga selangur.\", \"options\": [{\"text\": \"Negeri itu ialah Selangor.\", \"isCorrect\": true}, {\"text\": \"Negeri itu ialah Johor.\", \"isCorrect\": false, \"consequence\": \"Maklumat Johor tersasar masuk ke Selangor! Sekarang semua orang keliru dan perlu bertanya semula.\"}, {\"text\": \"Negeri itu ialah Kelantan.\", \"isCorrect\": false, \"consequence\": \"Aduh, itu bukan Selangor, itu Kelantan! Catatan kau pun terpaksa dipadam dan ditulis semula.\"}], \"aftermath\": \"Catatan itu dihantar ke negeri yang salah. Maklumat Selangor hilang daripada simpanan.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Sempena Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga yang disebut selangur\", \"isCorrect\": true, \"reaction\": \"Betul, Tok! Jawapan itu kena tepat pada Selangor. Penduduk bertepuk tangan.\"}, {\"text\": \"Daripada perkataan Arab \'Jauhar\' (batu permata bernilai), dan dikenali sebagai Ujung Tanah dalam Sulalatus Salatin\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Johor, Tok! Selangor lain ceritanya. Orang ramai mengerut dahi.\"}, {\"text\": \"Sebutan \'kilatan\' (cahaya terang) atau nama pokok gelam hutan, dan disebut Ho-lan-tan dalam rujukan China\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Kelantan, bukan Selangor. Cuba ingat semula.\"}], \"clue\": \"Ingat kata kunci tentang Selangor: sungai dan serangga.\"}]}'),
(206, 'e2_n1_s6', 'Soalan Sergahan di Negeri Sembilan', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang asal nama bagi Negeri Sembilan.', '3', 'Mengenal pasti asal nama bagi Negeri Sembilan.', '{\"prompt\": \"Tiba-tiba seorang peniaga yang sibuk menimbang barang menahan kau dan bertanya: apakah asal usul nama Negeri Sembilan?\", \"options\": [{\"text\": \"Penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada \'nagari\'\", \"isCorrect\": true}, {\"text\": \"Diambil daripada nama pokok mahang, dan dikenali juga sebagai Inderapura dalam catatan lama\", \"isCorrect\": false, \"consequence\": \"Aduh, itu bukan Negeri Sembilan, itu Pahang! Catatan kau pun terpaksa dipadam dan ditulis semula.\"}, {\"text\": \"Berasal daripada Sungai Sarawak, logam antimoni yang disebut cerava, atau dialog \'serah kepada awak\'\", \"isCorrect\": false, \"consequence\": \"Maklumat itu sebenarnya milik Sarawak! Penduduk Negeri Sembilan mengerut dahi dan berasa nama negeri mereka disalah ertikan.\"}], \"aftermath\": \"Orang ramai pulang dengan jawapan Negeri Sembilan yang salah, dan cerita itu tersebar semula dengan silap.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada \'nagari\'\", \"isCorrect\": true, \"reaction\": \"Hebat, Tok! Itulah dia tentang Negeri Sembilan. Semua mengangguk setuju.\"}, {\"text\": \"Diambil daripada nama pokok mahang, dan dikenali juga sebagai Inderapura dalam catatan lama\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Pahang, bukan Negeri Sembilan. Cuba ingat semula.\"}, {\"text\": \"Berasal daripada Sungai Sarawak, logam antimoni yang disebut cerava, atau dialog \'serah kepada awak\'\", \"isCorrect\": false, \"reaction\": \"Hmm, itu milik Sarawak, bukan Negeri Sembilan. Ada yang tergelak kecil di belakang.\"}], \"clue\": \"Ingat kata kunci tentang Negeri Sembilan: sembilan luak.\"}]}'),
(207, 'e2_n1_s7', 'Misi Lambang: Jata, Bendera dan Radio Melaka', 'Cari jata, bendera dan radio pada gambar untuk mengenal pasti fakta tentang Melaka. Mata tajam, ya!', '2', 'Mengenal pasti maklumat asal nama bagi Melaka daripada jata, bendera dan radio.', '{\"hotspots\":[{\"name\":\"Pada jata: asal nama, berkait dengan pokok Melaka\",\"top\":\"68.8%\",\"left\":\"43%\"},{\"name\":\"Di tiang bendera: ketua negeri bergelar Yang di-Pertua Negeri\",\"top\":\"7%\",\"left\":\"27.2%\"},{\"name\":\"Di radio: lagu \'Melaka Maju Jaya\'\",\"top\":\"67.5%\",\"left\":\"85.6%\"}],\"bgImage\":\"../assets/gameAsset/background/negeri_melaka.png\",\"aftermath\":\"Bukti tentang Melaka terlepas pandang. Catatan tentang jata, bendera dan lagunya menjadi samar, dan penduduk kecewa.\",\"turns\":[{\"after\":2,\"options\":[{\"text\":\"Sempena pokok Melaka tempat Parameswara berehat, atau \'Malakat\' dalam rujukan Arab yang bermaksud pusat pedagang\",\"isCorrect\":true,\"reaction\":\"Ya, ya, itulah jawapannya, Tok! Melaka memang begitu. Ada yang bersorak kecil.\"},{\"text\":\"Daripada sebutan \'taring anu\' (taring harimau atau binatang liar) atau \'terang ganu\' yang bermaksud pelangi\",\"isCorrect\":false,\"reaction\":\"Hmm, itu milik Terengganu, bukan Melaka. Ada yang tergelak kecil di belakang.\"},{\"text\":\"Diambil daripada sejenis pisang, iaitu pisang saba (pisang jaba)\",\"isCorrect\":false,\"reaction\":\"Silap negeri, Tok! Itu tentang Sabah, bukan Melaka. Cuba sekali lagi!\"}],\"clue\":\"Ingat kata kunci tentang Melaka: pokok Melaka.\"}]}'),
(208, 'e2_n1_s8', 'Padanan Pantas: Asal nama', 'Cepat, padankan setiap negeri dengan asal namanya yang betul sebelum kad bercampur aduk!', '4', 'Mengenal pasti asal nama bagi Johor dan negeri lain.', '{\"pairs\": [{\"text\": \"Johor\", \"pair\": 1}, {\"text\": \"Perkataan Arab \'Jauhar\', iaitu batu permata bernilai\", \"pair\": 1}, {\"text\": \"Kelantan\", \"pair\": 2}, {\"text\": \"Kilatan cahaya terang atau pokok gelam hutan\", \"pair\": 2}, {\"text\": \"Wilayah Persekutuan\", \"pair\": 3}, {\"text\": \"Muara berlumpur (KL), labuhan (Labuan), sempena Tunku (Putrajaya)\", \"pair\": 3}, {\"text\": \"Pulau Pinang\", \"pair\": 4}, {\"text\": \"Pokok pinang yang banyak tumbuh di pulau itu\", \"pair\": 4}], \"aftermath\": \"Kad Johor tersalah letak, dan negeri-negeri lain pun ikut berselerak.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Daripada perkataan Arab \'Jauhar\' (batu permata bernilai), dan dikenali sebagai Ujung Tanah dalam Sulalatus Salatin\", \"isCorrect\": true, \"reaction\": \"Tepat sekali, Tok! Itulah maklumat Johor yang patut diingat. Sorakan bergema di sekeliling!\"}, {\"text\": \"Sebutan \'kilatan\' (cahaya terang) atau nama pokok gelam hutan, dan disebut Ho-lan-tan dalam rujukan China\", \"isCorrect\": false, \"reaction\": \"Silap negeri, Tok! Itu tentang Kelantan, bukan Johor. Cuba sekali lagi!\"}, {\"text\": \"Kuala Lumpur daripada muara sungai berlumpur akibat perlombongan bijih timah, Labuan daripada \'labuhan\', Putrajaya sempena Tunku Abdul Rahman Putra\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Wilayah Persekutuan, Tok! Johor lain ceritanya. Orang ramai mengerut dahi.\"}], \"clue\": \"Ingat kata kunci tentang Johor: batu permata.\"}]}');
INSERT INTO `Quest` (`questID`, `sceneID`, `questName`, `instruction`, `questType`, `description`, `questContent`) VALUES
(209, 'e2_n1_s9', 'Nyahkod Catatan Lama Pahang', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Pahang melalui asal nama.', '{\"clueText\": \"Catatan lama, tulisan sudah pudar: namanya dikaitkan dengan Pokok mahang, juga dikenali sebagai Inderapura.\", \"options\": [{\"text\": \"Negeri itu ialah Pahang.\", \"isCorrect\": true}, {\"text\": \"Negeri itu ialah Sarawak.\", \"isCorrect\": false, \"consequence\": \"Itu fakta Sarawak, bukan Pahang! Pelajar yang mendengarnya menulis jawapan salah dalam buku, dan cikgu terpaksa membetulkannya kemudian.\"}, {\"text\": \"Negeri itu ialah Perlis.\", \"isCorrect\": false, \"consequence\": \"Hmm, itu cerita Perlis. Penduduk Pahang saling berpandangan dan ada yang tergelak kecil kerana tersilap negeri.\"}], \"aftermath\": \"Catatan itu dihantar ke negeri yang salah. Maklumat Pahang hilang daripada simpanan.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Diambil daripada nama pokok mahang, dan dikenali juga sebagai Inderapura dalam catatan lama\", \"isCorrect\": true, \"reaction\": \"Betul, Tok! Jawapan itu kena tepat pada Pahang. Penduduk bertepuk tangan.\"}, {\"text\": \"Berasal daripada Sungai Sarawak, logam antimoni yang disebut cerava, atau dialog \'serah kepada awak\'\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Sarawak, Tok! Pahang lain ceritanya. Orang ramai mengerut dahi.\"}, {\"text\": \"Daripada perkataan Siam \'phrau loi\' (kelapa hanyut), perkataan tempatan \'peroleh\' atau tokoh Tok Perlis\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Perlis, bukan Pahang. Cuba ingat semula.\"}], \"clue\": \"Ingat kata kunci tentang Pahang: pokok mahang.\"}]}'),
(210, 'e2_n1_s10', 'Soalan Sergahan di Terengganu', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang asal nama bagi Terengganu.', '3', 'Mengenal pasti asal nama bagi Terengganu.', '{\"prompt\": \"Tiba-tiba seorang cikgu yang menjinjit bakul buku menahan kau dan bertanya: apakah asal usul nama Terengganu?\", \"options\": [{\"text\": \"Daripada sebutan \'taring anu\' (taring harimau atau binatang liar) atau \'terang ganu\' yang bermaksud pelangi\", \"isCorrect\": true}, {\"text\": \"Diambil daripada sejenis pisang, iaitu pisang saba (pisang jaba)\", \"isCorrect\": false, \"consequence\": \"Hmm, itu cerita Sabah. Penduduk Terengganu saling berpandangan dan ada yang tergelak kecil kerana tersilap negeri.\"}, {\"text\": \"Daripada \'Kheddah\' (perangkap gajah), \'Qadah\' dalam bahasa Arab (gelas berkaki) atau \'Kadaram\' dalam rujukan India\", \"isCorrect\": false, \"consequence\": \"Maklumat Kedah tersasar masuk ke Terengganu! Sekarang semua orang keliru dan perlu bertanya semula.\"}], \"aftermath\": \"Orang ramai pulang dengan jawapan Terengganu yang salah, dan cerita itu tersebar semula dengan silap.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Daripada sebutan \'taring anu\' (taring harimau atau binatang liar) atau \'terang ganu\' yang bermaksud pelangi\", \"isCorrect\": true, \"reaction\": \"Hebat, Tok! Itulah dia tentang Terengganu. Semua mengangguk setuju.\"}, {\"text\": \"Diambil daripada sejenis pisang, iaitu pisang saba (pisang jaba)\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Sabah, bukan Terengganu. Cuba ingat semula.\"}, {\"text\": \"Daripada \'Kheddah\' (perangkap gajah), \'Qadah\' dalam bahasa Arab (gelas berkaki) atau \'Kadaram\' dalam rujukan India\", \"isCorrect\": false, \"reaction\": \"Hmm, itu milik Kedah, bukan Terengganu. Ada yang tergelak kecil di belakang.\"}], \"clue\": \"Ingat kata kunci tentang Terengganu: pelangi.\"}]}'),
(211, 'e2_n1_s11', 'Misi Lambang: Jata, Bendera dan Radio Kelantan', 'Cari jata, bendera dan radio pada gambar untuk mengenal pasti fakta tentang Kelantan. Mata tajam, ya!', '2', 'Mengenal pasti maklumat asal nama bagi Kelantan daripada jata, bendera dan radio.', '{\"hotspots\":[{\"name\":\"Pada jata: asal nama, berkait dengan Ho-lan-tan\",\"top\":\"57.5%\",\"left\":\"41.8%\"},{\"name\":\"Di tiang bendera: ketua negeri bergelar Sultan\",\"top\":\"17%\",\"left\":\"73.4%\"},{\"name\":\"Di radio: lagu \'Selamat Sultan\'\",\"top\":\"72%\",\"left\":\"17%\"}],\"bgImage\":\"../assets/gameAsset/background/negeri_kelantan.png\",\"aftermath\":\"Bukti tentang Kelantan terlepas pandang. Catatan tentang jata, bendera dan lagunya menjadi samar, dan penduduk kecewa.\",\"turns\":[{\"after\":2,\"options\":[{\"text\":\"Sebutan \'kilatan\' (cahaya terang) atau nama pokok gelam hutan, dan disebut Ho-lan-tan dalam rujukan China\",\"isCorrect\":true,\"reaction\":\"Ya, ya, itulah jawapannya, Tok! Kelantan memang begitu. Ada yang bersorak kecil.\"},{\"text\":\"Kuala Lumpur daripada muara sungai berlumpur akibat perlombongan bijih timah, Labuan daripada \'labuhan\', Putrajaya sempena Tunku Abdul Rahman Putra\",\"isCorrect\":false,\"reaction\":\"Hmm, itu milik Wilayah Persekutuan, bukan Kelantan. Ada yang tergelak kecil di belakang.\"},{\"text\":\"Sempena pokok pinang yang banyak tumbuh di pulau itu, yang dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga\",\"isCorrect\":false,\"reaction\":\"Silap negeri, Tok! Itu tentang Pulau Pinang, bukan Kelantan. Cuba sekali lagi!\"}],\"clue\":\"Ingat kata kunci tentang Kelantan: Ho-lan-tan.\"}]}'),
(212, 'e2_n1_s12', 'Padanan Pantas: Asal nama', 'Cepat, padankan setiap negeri dengan asal namanya yang betul sebelum kad bercampur aduk!', '4', 'Mengenal pasti asal nama bagi Sarawak dan negeri lain.', '{\"pairs\": [{\"text\": \"Sarawak\", \"pair\": 1}, {\"text\": \"Sungai Sarawak, logam antimoni (cerava) atau \'serah kepada awak\'\", \"pair\": 1}, {\"text\": \"Perlis\", \"pair\": 2}, {\"text\": \"Perkataan Siam \'phrau loi\', iaitu kelapa hanyut\", \"pair\": 2}, {\"text\": \"Perak\", \"pair\": 3}, {\"text\": \"Kilatan ikan atau bijih timah putih yang berkilat seperti perak\", \"pair\": 3}, {\"text\": \"Melaka\", \"pair\": 4}, {\"text\": \"Pokok Melaka tempat Parameswara berehat\", \"pair\": 4}], \"aftermath\": \"Kad Sarawak tersalah letak, dan negeri-negeri lain pun ikut berselerak.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Berasal daripada Sungai Sarawak, logam antimoni yang disebut cerava, atau dialog \'serah kepada awak\'\", \"isCorrect\": true, \"reaction\": \"Tepat sekali, Tok! Itulah maklumat Sarawak yang patut diingat. Sorakan bergema di sekeliling!\"}, {\"text\": \"Daripada perkataan Siam \'phrau loi\' (kelapa hanyut), perkataan tempatan \'peroleh\' atau tokoh Tok Perlis\", \"isCorrect\": false, \"reaction\": \"Silap negeri, Tok! Itu tentang Perlis, bukan Sarawak. Cuba sekali lagi!\"}, {\"text\": \"Dikaitkan dengan kilatan ikan di dalam air atau warna bijih timah putih yang berkilat seperti perak\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Perak, Tok! Sarawak lain ceritanya. Orang ramai mengerut dahi.\"}], \"clue\": \"Ingat kata kunci tentang Sarawak: antimoni.\"}]}'),
(213, 'e2_n1_s13', 'Nyahkod Catatan Lama Sabah', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Sabah melalui asal nama.', '{\"clueText\": \"Catatan lama, tulisan sudah pudar: namanya dikaitkan dengan Sejenis pisang, iaitu pisang saba atau pisang jaba.\", \"options\": [{\"text\": \"Negeri itu ialah Sabah.\", \"isCorrect\": true}, {\"text\": \"Negeri itu ialah Kedah.\", \"isCorrect\": false, \"consequence\": \"Maklumat itu sebenarnya milik Kedah! Penduduk Sabah mengerut dahi dan berasa nama negeri mereka disalah ertikan.\"}, {\"text\": \"Negeri itu ialah Selangor.\", \"isCorrect\": false, \"consequence\": \"Kau menyebut maklumat Selangor untuk Sabah. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut.\"}], \"aftermath\": \"Catatan itu dihantar ke negeri yang salah. Maklumat Sabah hilang daripada simpanan.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Diambil daripada sejenis pisang, iaitu pisang saba (pisang jaba)\", \"isCorrect\": true, \"reaction\": \"Betul, Tok! Jawapan itu kena tepat pada Sabah. Penduduk bertepuk tangan.\"}, {\"text\": \"Daripada \'Kheddah\' (perangkap gajah), \'Qadah\' dalam bahasa Arab (gelas berkaki) atau \'Kadaram\' dalam rujukan India\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Kedah, Tok! Sabah lain ceritanya. Orang ramai mengerut dahi.\"}, {\"text\": \"Sempena Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga yang disebut selangur\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Selangor, bukan Sabah. Cuba ingat semula.\"}], \"clue\": \"Ingat kata kunci tentang Sabah: pisang saba.\"}]}'),
(214, 'e2_n1_s14', 'Soalan Sergahan di Wilayah Persekutuan', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang asal nama bagi Wilayah Persekutuan.', '3', 'Mengenal pasti asal nama bagi Wilayah Persekutuan.', '{\"prompt\": \"Tiba-tiba seorang peniaga yang sibuk menimbang barang menahan kau dan bertanya: apakah asal usul nama Wilayah Persekutuan?\", \"options\": [{\"text\": \"Kuala Lumpur daripada muara sungai berlumpur akibat perlombongan bijih timah, Labuan daripada \'labuhan\', Putrajaya sempena Tunku Abdul Rahman Putra\", \"isCorrect\": true}, {\"text\": \"Sempena pokok pinang yang banyak tumbuh di pulau itu, yang dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga\", \"isCorrect\": false, \"consequence\": \"Kau menyebut maklumat Pulau Pinang untuk Wilayah Persekutuan. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut.\"}, {\"text\": \"Penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada \'nagari\'\", \"isCorrect\": false, \"consequence\": \"Itu fakta Negeri Sembilan, bukan Wilayah Persekutuan! Pelajar yang mendengarnya menulis jawapan salah dalam buku, dan cikgu terpaksa membetulkannya kemudian.\"}], \"aftermath\": \"Orang ramai pulang dengan jawapan Wilayah Persekutuan yang salah, dan cerita itu tersebar semula dengan silap.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Kuala Lumpur daripada muara sungai berlumpur akibat perlombongan bijih timah, Labuan daripada \'labuhan\', Putrajaya sempena Tunku Abdul Rahman Putra\", \"isCorrect\": true, \"reaction\": \"Hebat, Tok! Itulah dia tentang Wilayah Persekutuan. Semua mengangguk setuju.\"}, {\"text\": \"Sempena pokok pinang yang banyak tumbuh di pulau itu, yang dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Pulau Pinang, bukan Wilayah Persekutuan. Cuba ingat semula.\"}, {\"text\": \"Penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada \'nagari\'\", \"isCorrect\": false, \"reaction\": \"Hmm, itu milik Negeri Sembilan, bukan Wilayah Persekutuan. Ada yang tergelak kecil di belakang.\"}], \"clue\": \"Ingat kata kunci tentang Wilayah Persekutuan: muara berlumpur.\"}]}'),
(215, 'e2_n2_s1', 'Soalan Sergahan di Johor', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang gelaran ketua negeri bagi Johor.', '3', 'Mengenal pasti gelaran ketua negeri bagi Johor.', '{\"prompt\": \"Tiba-tiba seorang pelancong yang tercungap-cungap membawa peta menahan kau dan bertanya: apakah gelaran ketua negeri bagi Johor?\", \"options\": [{\"text\": \"Sultan\", \"isCorrect\": true}, {\"text\": \"Yang di-Pertuan Agong\", \"isCorrect\": false, \"consequence\": \"Maklumat itu sebenarnya milik Wilayah Persekutuan! Penduduk Johor mengerut dahi dan berasa nama negeri mereka disalah ertikan.\"}, {\"text\": \"Yang di-Pertua Negeri\", \"isCorrect\": false, \"consequence\": \"Kau menyebut maklumat Pulau Pinang untuk Johor. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut.\"}], \"aftermath\": \"Jawapan tentang Johor tersasar. Soalan yang sama ditanya semula dan semua orang keliru.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Sultan.\", \"isCorrect\": true, \"reaction\": \"Hebat, Tuanku! Itulah dia tentang Johor. Semua mengangguk setuju.\"}, {\"text\": \"Yang di-Pertuan Agong.\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Wilayah Persekutuan, Tuanku! Johor lain ceritanya. Orang ramai mengerut dahi.\"}, {\"text\": \"Yang di-Pertua Negeri.\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Pulau Pinang, bukan Johor. Cuba ingat semula.\"}], \"clue\": \"Cuba ingat gambar Johor: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(216, 'e2_n2_s2', 'Misi Lambang: Jata, Bendera dan Radio Kedah', 'Cari jata, bendera dan radio pada gambar untuk mengenal pasti fakta tentang Kedah. Mata tajam, ya!', '2', 'Mengenal pasti maklumat gelaran ketua negeri bagi Kedah daripada jata, bendera dan radio.', '{\"hotspots\":[{\"name\":\"Pada jata: ketua negeri bergelar Sultan\",\"top\":\"52.3%\",\"left\":\"81.7%\"},{\"name\":\"Di tiang bendera: asal nama, berkait dengan perangkap gajah\",\"top\":\"25.5%\",\"left\":\"26.4%\"},{\"name\":\"lagu \'Allah Selamatkan Sultan Mahkota\'\",\"top\":\"71.8%\",\"left\":\"17.2%\"}],\"bgImage\":\"../assets/gameAsset/background/negeri_kedah.png\",\"aftermath\":\"Jata, bendera dan radio Kedah tidak dibaca dengan teliti. Maklumat negeri itu hilang daripada ingatan.\",\"turns\":[{\"after\":2,\"options\":[{\"text\":\"Sultan.\",\"isCorrect\":true,\"reaction\":\"Ya, ya, itulah jawapannya, Tuanku! Kedah memang begitu. Ada yang bersorak kecil.\"},{\"text\":\"Yang di-Pertuan Agong.\",\"isCorrect\":false,\"reaction\":\"Aduh, tersilap sedikit! Itu maklumat Wilayah Persekutuan, bukan Kedah. Cuba ingat semula.\"},{\"text\":\"Yang di-Pertua Negeri.\",\"isCorrect\":false,\"reaction\":\"Hmm, itu milik Pulau Pinang, bukan Kedah. Ada yang tergelak kecil di belakang.\"}],\"clue\":\"Cuba ingat gambar Kedah: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(217, 'e2_n2_s3', 'Padanan Pantas: Gelaran ketua negeri', 'Cepat, padankan setiap negeri dengan gelaran ketua negerinya yang betul sebelum kad bercampur aduk!', '4', 'Mengenal pasti gelaran ketua negeri bagi Kelantan dan negeri lain.', '{\"pairs\": [{\"text\": \"Kelantan\", \"pair\": 1}, {\"text\": \"Sultan\", \"pair\": 1}, {\"text\": \"Wilayah Persekutuan\", \"pair\": 2}, {\"text\": \"Yang di-Pertuan Agong\", \"pair\": 2}, {\"text\": \"Pulau Pinang\", \"pair\": 3}, {\"text\": \"Yang di-Pertua Negeri\", \"pair\": 3}, {\"text\": \"Negeri Sembilan\", \"pair\": 4}, {\"text\": \"Yang di-Pertuan Besar\", \"pair\": 4}], \"aftermath\": \"Maklumat Kelantan bercampur dengan negeri lain. Kekeliruan itu terus diulang dari mulut ke mulut.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Sultan.\", \"isCorrect\": true, \"reaction\": \"Tepat sekali, Tuanku! Itulah maklumat Kelantan yang patut diingat. Sorakan bergema di sekeliling!\"}, {\"text\": \"Yang di-Pertuan Agong.\", \"isCorrect\": false, \"reaction\": \"Hmm, itu milik Wilayah Persekutuan, bukan Kelantan. Ada yang tergelak kecil di belakang.\"}, {\"text\": \"Yang di-Pertua Negeri.\", \"isCorrect\": false, \"reaction\": \"Silap negeri, Tuanku! Itu tentang Pulau Pinang, bukan Kelantan. Cuba sekali lagi!\"}], \"clue\": \"Cuba ingat gambar Kelantan: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(218, 'e2_n2_s4', 'Nyahkod Catatan Lama Pahang', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Pahang melalui gelaran ketua negeri.', '{\"clueText\": \"Catatan lama, tulisan sudah pudar: ketua negeri ini bergelar Sultan, dan ibu negerinya Kuantan.\", \"options\": [{\"text\": \"Negeri itu ialah Pahang.\", \"isCorrect\": true}, {\"text\": \"Negeri itu ialah Sarawak.\", \"isCorrect\": false, \"consequence\": \"Hmm, itu cerita Sarawak. Penduduk Pahang saling berpandangan dan ada yang tergelak kecil kerana tersilap negeri.\"}, {\"text\": \"Negeri itu ialah Perlis.\", \"isCorrect\": false, \"consequence\": \"Maklumat Perlis tersasar masuk ke Pahang! Sekarang semua orang keliru dan perlu bertanya semula.\"}], \"aftermath\": \"Catatan lama tentang Pahang disalah baca, dan sejarah negeri itu ditulis dengan silap.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Sultan.\", \"isCorrect\": true, \"reaction\": \"Betul, Tuanku! Jawapan itu kena tepat pada Pahang. Penduduk bertepuk tangan.\"}, {\"text\": \"Yang di-Pertua Negeri.\", \"isCorrect\": false, \"reaction\": \"Silap negeri, Tuanku! Itu tentang Sarawak, bukan Pahang. Cuba sekali lagi!\"}, {\"text\": \"Raja.\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Perlis, Tuanku! Pahang lain ceritanya. Orang ramai mengerut dahi.\"}], \"clue\": \"Cuba ingat gambar Pahang: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(219, 'e2_n2_s5', 'Soalan Sergahan di Perak', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang gelaran ketua negeri bagi Perak.', '3', 'Mengenal pasti gelaran ketua negeri bagi Perak.', '{\"prompt\": \"Tiba-tiba seorang nenek yang sedang menyapu halaman menahan kau dan bertanya: apakah gelaran ketua negeri bagi Perak?\", \"options\": [{\"text\": \"Sultan\", \"isCorrect\": true}, {\"text\": \"Yang di-Pertua Negeri\", \"isCorrect\": false, \"consequence\": \"Maklumat Melaka tersasar masuk ke Perak! Sekarang semua orang keliru dan perlu bertanya semula.\"}, {\"text\": \"Yang di-Pertuan Agong\", \"isCorrect\": false, \"consequence\": \"Aduh, itu bukan Perak, itu Wilayah Persekutuan! Catatan kau pun terpaksa dipadam dan ditulis semula.\"}], \"aftermath\": \"Jawapan tentang Perak tersasar. Soalan yang sama ditanya semula dan semua orang keliru.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Sultan.\", \"isCorrect\": true, \"reaction\": \"Hebat, Tuanku! Itulah dia tentang Perak. Semua mengangguk setuju.\"}, {\"text\": \"Yang di-Pertua Negeri.\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Melaka, Tuanku! Perak lain ceritanya. Orang ramai mengerut dahi.\"}, {\"text\": \"Yang di-Pertuan Agong.\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Wilayah Persekutuan, bukan Perak. Cuba ingat semula.\"}], \"clue\": \"Cuba ingat gambar Perak: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(220, 'e2_n2_s6', 'Misi Lambang: Jata, Bendera dan Radio Selangor', 'Cari jata, bendera dan radio pada gambar untuk mengenal pasti fakta tentang Selangor. Mata tajam, ya!', '2', 'Mengenal pasti maklumat gelaran ketua negeri bagi Selangor daripada jata, bendera dan radio.', '{\"hotspots\":[{\"name\":\"Pada jata: ketua negeri bergelar Sultan\",\"top\":\"52%\",\"left\":\"84.4%\"},{\"name\":\"Di tiang bendera: asal nama, berkait dengan sungai dan serangga\",\"top\":\"21.2%\",\"left\":\"55.2%\"},{\"name\":\"Di radio: lagu \'Duli Yang Maha Mulia\'\",\"top\":\"67.6%\",\"left\":\"60.5%\"}],\"bgImage\":\"../assets/gameAsset/background/negeri_selangor.png\",\"aftermath\":\"Jata, bendera dan radio Selangor tidak dibaca dengan teliti. Maklumat negeri itu hilang daripada ingatan.\",\"turns\":[{\"after\":2,\"options\":[{\"text\":\"Sultan.\",\"isCorrect\":true,\"reaction\":\"Ya, ya, itulah jawapannya, Tuanku! Selangor memang begitu. Ada yang bersorak kecil.\"},{\"text\":\"Yang di-Pertuan Agong.\",\"isCorrect\":false,\"reaction\":\"Aduh, tersilap sedikit! Itu maklumat Wilayah Persekutuan, bukan Selangor. Cuba ingat semula.\"},{\"text\":\"Yang di-Pertua Negeri.\",\"isCorrect\":false,\"reaction\":\"Hmm, itu milik Pulau Pinang, bukan Selangor. Ada yang tergelak kecil di belakang.\"}],\"clue\":\"Cuba ingat gambar Selangor: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(221, 'e2_n2_s7', 'Padanan Pantas: Gelaran ketua negeri', 'Cepat, padankan setiap negeri dengan gelaran ketua negerinya yang betul sebelum kad bercampur aduk!', '4', 'Mengenal pasti gelaran ketua negeri bagi Terengganu dan negeri lain.', '{\"pairs\": [{\"text\": \"Terengganu\", \"pair\": 1}, {\"text\": \"Sultan\", \"pair\": 1}, {\"text\": \"Sabah\", \"pair\": 2}, {\"text\": \"Yang di-Pertua Negeri\", \"pair\": 2}, {\"text\": \"Wilayah Persekutuan\", \"pair\": 3}, {\"text\": \"Yang di-Pertuan Agong\", \"pair\": 3}, {\"text\": \"Negeri Sembilan\", \"pair\": 4}, {\"text\": \"Yang di-Pertuan Besar\", \"pair\": 4}], \"aftermath\": \"Maklumat Terengganu bercampur dengan negeri lain. Kekeliruan itu terus diulang dari mulut ke mulut.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Sultan.\", \"isCorrect\": true, \"reaction\": \"Tepat sekali, Tuanku! Itulah maklumat Terengganu yang patut diingat. Sorakan bergema di sekeliling!\"}, {\"text\": \"Yang di-Pertua Negeri.\", \"isCorrect\": false, \"reaction\": \"Hmm, itu milik Sabah, bukan Terengganu. Ada yang tergelak kecil di belakang.\"}, {\"text\": \"Yang di-Pertuan Agong.\", \"isCorrect\": false, \"reaction\": \"Silap negeri, Tuanku! Itu tentang Wilayah Persekutuan, bukan Terengganu. Cuba sekali lagi!\"}], \"clue\": \"Cuba ingat gambar Terengganu: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(222, 'e2_n2_s8', 'Nyahkod Catatan Lama Perlis', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Perlis melalui gelaran ketua negeri.', '{\"clueText\": \"Catatan lama, tulisan sudah pudar: ketua negeri ini bergelar Raja, dan ibu negerinya Kangar.\", \"options\": [{\"text\": \"Negeri itu ialah Perlis.\", \"isCorrect\": true}, {\"text\": \"Negeri itu ialah Perak.\", \"isCorrect\": false, \"consequence\": \"Kau menyebut maklumat Perak untuk Perlis. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut.\"}, {\"text\": \"Negeri itu ialah Melaka.\", \"isCorrect\": false, \"consequence\": \"Itu fakta Melaka, bukan Perlis! Pelajar yang mendengarnya menulis jawapan salah dalam buku, dan cikgu terpaksa membetulkannya kemudian.\"}], \"aftermath\": \"Catatan lama tentang Perlis disalah baca, dan sejarah negeri itu ditulis dengan silap.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Raja.\", \"isCorrect\": true, \"reaction\": \"Betul, Tuanku! Jawapan itu kena tepat pada Perlis. Penduduk bertepuk tangan.\"}, {\"text\": \"Sultan.\", \"isCorrect\": false, \"reaction\": \"Silap negeri, Tuanku! Itu tentang Perak, bukan Perlis. Cuba sekali lagi!\"}, {\"text\": \"Yang di-Pertua Negeri.\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Melaka, Tuanku! Perlis lain ceritanya. Orang ramai mengerut dahi.\"}], \"clue\": \"Cuba ingat gambar Perlis: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(223, 'e2_n2_s9', 'Soalan Sergahan di Negeri Sembilan', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang gelaran ketua negeri bagi Negeri Sembilan.', '3', 'Mengenal pasti gelaran ketua negeri bagi Negeri Sembilan.', '{\"prompt\": \"Tiba-tiba seorang pelancong yang tercungap-cungap membawa peta menahan kau dan bertanya: apakah gelaran ketua negeri bagi Negeri Sembilan?\", \"options\": [{\"text\": \"Yang di-Pertuan Besar\", \"isCorrect\": true}, {\"text\": \"Sultan\", \"isCorrect\": false, \"consequence\": \"Itu fakta Pahang, bukan Negeri Sembilan! Pelajar yang mendengarnya menulis jawapan salah dalam buku, dan cikgu terpaksa membetulkannya kemudian.\"}, {\"text\": \"Yang di-Pertua Negeri\", \"isCorrect\": false, \"consequence\": \"Hmm, itu cerita Sarawak. Penduduk Negeri Sembilan saling berpandangan dan ada yang tergelak kecil kerana tersilap negeri.\"}], \"aftermath\": \"Jawapan tentang Negeri Sembilan tersasar. Soalan yang sama ditanya semula dan semua orang keliru.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Yang di-Pertuan Besar.\", \"isCorrect\": true, \"reaction\": \"Hebat, Tuanku! Itulah dia tentang Negeri Sembilan. Semua mengangguk setuju.\"}, {\"text\": \"Sultan.\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Pahang, Tuanku! Negeri Sembilan lain ceritanya. Orang ramai mengerut dahi.\"}, {\"text\": \"Yang di-Pertua Negeri.\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Sarawak, bukan Negeri Sembilan. Cuba ingat semula.\"}], \"clue\": \"Cuba ingat gambar Negeri Sembilan: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
