(232, 'e2_n3_s4', 'Misi Lambang: Jata, Bendera dan Radio Perak', 'Cari jata, bendera dan radio pada gambar untuk mengenal pasti fakta tentang Perak. Mata tajam, ya!', '2', 'Mengenal pasti maklumat ibu negeri dan bandar diraja bagi Perak daripada jata, bendera dan radio.', '{\"hotspots\":[{\"name\":\"Pada jata: ketua negeri bergelar Sultan\",\"top\":\"38.1%\",\"left\":\"40.8%\"},{\"name\":\"Di tiang bendera: ibu negeri Ipoh, bandar diraja Kuala Kangsar\",\"top\":\"14.7%\",\"left\":\"12.1%\"},{\"name\":\"lagu \'Allah Lanjutkan Usia Sultan\'\",\"top\":\"67.3%\",\"left\":\"9.4%\"}],\"bgImage\":\"../assets/gameAsset/background/negeri_perak.png\",\"aftermath\":\"Jata, bendera dan radio Perak tidak dibaca dengan teliti. Maklumat negeri itu hilang daripada ingatan.\",\"turns\":[{\"after\":2,\"options\":[{\"text\":\"Ipoh.\",\"isCorrect\":true,\"reaction\":\"Hebat, pengembara! Itulah dia tentang Perak. Semua mengangguk setuju.\"},{\"text\":\"Bandar Melaka.\",\"isCorrect\":false,\"reaction\":\"Silap negeri, pengembara! Itu tentang Melaka, bukan Perak. Cuba sekali lagi!\"},{\"text\":\"Kuala Terengganu.\",\"isCorrect\":false,\"reaction\":\"Eh, itu cerita Terengganu, pengembara! Perak lain ceritanya. Orang ramai mengerut dahi.\"}],\"clue\":\"Cuba ingat gambar Perak: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(233, 'e2_n3_s5', 'Padanan Pantas: Ibu negeri dan bandar diraja', 'Cepat, padankan setiap negeri dengan ibu negeri dan bandar dirajanya yang betul sebelum kad bercampur aduk!', '4', 'Mengenal pasti ibu negeri dan bandar diraja bagi Selangor dan negeri lain.', '{\"pairs\": [{\"text\": \"Selangor\", \"pair\": 1}, {\"text\": \"Shah Alam, bandar diraja Klang\", \"pair\": 1}, {\"text\": \"Johor\", \"pair\": 2}, {\"text\": \"Johor Bahru, bandar diraja Bandar Maharani\", \"pair\": 2}, {\"text\": \"Kelantan\", \"pair\": 3}, {\"text\": \"Kota Bharu\", \"pair\": 3}, {\"text\": \"Pulau Pinang\", \"pair\": 4}, {\"text\": \"Georgetown\", \"pair\": 4}], \"aftermath\": \"Maklumat Selangor bercampur dengan negeri lain. Kekeliruan itu terus diulang dari mulut ke mulut.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Shah Alam.\", \"isCorrect\": true, \"reaction\": \"Ya, ya, itulah jawapannya, pengembara! Selangor memang begitu. Ada yang bersorak kecil.\"}, {\"text\": \"Johor Bahru.\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Johor, pengembara! Selangor lain ceritanya. Orang ramai mengerut dahi.\"}, {\"text\": \"Kota Bharu.\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Kelantan, bukan Selangor. Cuba ingat semula.\"}], \"clue\": \"Cuba ingat gambar Selangor: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(234, 'e2_n3_s6', 'Nyahkod Catatan Lama Negeri Sembilan', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Negeri Sembilan melalui ibu negeri dan bandar diraja.', '{\"clueText\": \"Catatan lama, tulisan sudah pudar: ibu negerinya Seremban dan bandar dirajanya Seri Menanti.\", \"options\": [{\"text\": \"Negeri itu ialah Negeri Sembilan.\", \"isCorrect\": true}, {\"text\": \"Negeri itu ialah Pahang.\", \"isCorrect\": false, \"consequence\": \"Aduh, itu bukan Negeri Sembilan, itu Pahang! Catatan kau pun terpaksa dipadam dan ditulis semula.\"}, {\"text\": \"Negeri itu ialah Sarawak.\", \"isCorrect\": false, \"consequence\": \"Maklumat itu sebenarnya milik Sarawak! Penduduk Negeri Sembilan mengerut dahi dan berasa nama negeri mereka disalah ertikan.\"}], \"aftermath\": \"Catatan lama tentang Negeri Sembilan disalah baca, dan sejarah negeri itu ditulis dengan silap.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Seremban.\", \"isCorrect\": true, \"reaction\": \"Tepat sekali, pengembara! Itulah maklumat Negeri Sembilan yang patut diingat. Sorakan bergema di sekeliling!\"}, {\"text\": \"Kuantan.\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Pahang, bukan Negeri Sembilan. Cuba ingat semula.\"}, {\"text\": \"Kuching.\", \"isCorrect\": false, \"reaction\": \"Hmm, itu milik Sarawak, bukan Negeri Sembilan. Ada yang tergelak kecil di belakang.\"}], \"clue\": \"Cuba ingat gambar Negeri Sembilan: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(235, 'e2_n3_s7', 'Soalan Sergahan di Melaka', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang ibu negeri dan bandar diraja bagi Melaka.', '3', 'Mengenal pasti ibu negeri dan bandar diraja bagi Melaka.', '{\"prompt\": \"Tiba-tiba seorang pemandu bas yang berhenti seketika menahan kau dan bertanya: apakah ibu negeri Melaka?\", \"options\": [{\"text\": \"Bandar Melaka\", \"isCorrect\": true}, {\"text\": \"Kuala Terengganu\", \"isCorrect\": false, \"consequence\": \"Maklumat itu sebenarnya milik Terengganu! Penduduk Melaka mengerut dahi dan berasa nama negeri mereka disalah ertikan.\"}, {\"text\": \"Kota Kinabalu\", \"isCorrect\": false, \"consequence\": \"Kau menyebut maklumat Sabah untuk Melaka. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut.\"}], \"aftermath\": \"Jawapan tentang Melaka tersasar. Soalan yang sama ditanya semula dan semua orang keliru.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Bandar Melaka.\", \"isCorrect\": true, \"reaction\": \"Betul, pengembara! Jawapan itu kena tepat pada Melaka. Penduduk bertepuk tangan.\"}, {\"text\": \"Kuala Terengganu.\", \"isCorrect\": false, \"reaction\": \"Hmm, itu milik Terengganu, bukan Melaka. Ada yang tergelak kecil di belakang.\"}, {\"text\": \"Kota Kinabalu.\", \"isCorrect\": false, \"reaction\": \"Silap negeri, pengembara! Itu tentang Sabah, bukan Melaka. Cuba sekali lagi!\"}], \"clue\": \"Cuba ingat gambar Melaka: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(236, 'e2_n3_s8', 'Misi Lambang: Jata, Bendera dan Radio Johor', 'Cari jata, bendera dan radio pada gambar untuk mengenal pasti fakta tentang Johor. Mata tajam, ya!', '2', 'Mengenal pasti maklumat ibu negeri dan bandar diraja bagi Johor daripada jata, bendera dan radio.', '{\"hotspots\":[{\"name\":\"Pada jata: ketua negeri bergelar Sultan\",\"top\":\"41.5%\",\"left\":\"35.7%\"},{\"name\":\"Di tiang bendera: ibu negeri Johor Bahru, bandar diraja Bandar Maharani\",\"top\":\"15.8%\",\"left\":\"66.4%\"},{\"name\":\"lagu \'Lagu Bangsa Johor\'\",\"top\":\"66.4%\",\"left\":\"81%\"}],\"bgImage\":\"../assets/gameAsset/background/negeri_johor.png\",\"aftermath\":\"Jata, bendera dan radio Johor tidak dibaca dengan teliti. Maklumat negeri itu hilang daripada ingatan.\",\"turns\":[{\"after\":2,\"options\":[{\"text\":\"Johor Bahru.\",\"isCorrect\":true,\"reaction\":\"Hebat, pengembara! Itulah dia tentang Johor. Semua mengangguk setuju.\"},{\"text\":\"Kota Bharu.\",\"isCorrect\":false,\"reaction\":\"Silap negeri, pengembara! Itu tentang Kelantan, bukan Johor. Cuba sekali lagi!\"},{\"text\":\"Georgetown.\",\"isCorrect\":false,\"reaction\":\"Eh, itu cerita Pulau Pinang, pengembara! Johor lain ceritanya. Orang ramai mengerut dahi.\"}],\"clue\":\"Cuba ingat gambar Johor: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(237, 'e2_n3_s9', 'Padanan Pantas: Ibu negeri dan bandar diraja', 'Cepat, padankan setiap negeri dengan ibu negeri dan bandar dirajanya yang betul sebelum kad bercampur aduk!', '4', 'Mengenal pasti ibu negeri dan bandar diraja bagi Pahang dan negeri lain.', '{\"pairs\": [{\"text\": \"Pahang\", \"pair\": 1}, {\"text\": \"Kuantan, bandar diraja Pekan\", \"pair\": 1}, {\"text\": \"Sarawak\", \"pair\": 2}, {\"text\": \"Kuching\", \"pair\": 2}, {\"text\": \"Perlis\", \"pair\": 3}, {\"text\": \"Kangar, bandar diraja Arau\", \"pair\": 3}, {\"text\": \"Perak\", \"pair\": 4}, {\"text\": \"Ipoh, bandar diraja Kuala Kangsar\", \"pair\": 4}], \"aftermath\": \"Maklumat Pahang bercampur dengan negeri lain. Kekeliruan itu terus diulang dari mulut ke mulut.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Kuantan.\", \"isCorrect\": true, \"reaction\": \"Ya, ya, itulah jawapannya, pengembara! Pahang memang begitu. Ada yang bersorak kecil.\"}, {\"text\": \"Kuching.\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Sarawak, pengembara! Pahang lain ceritanya. Orang ramai mengerut dahi.\"}, {\"text\": \"Kangar.\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Perlis, bukan Pahang. Cuba ingat semula.\"}], \"clue\": \"Cuba ingat gambar Pahang: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(238, 'e2_n3_s10', 'Nyahkod Catatan Lama Terengganu', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Terengganu melalui ibu negeri dan bandar diraja.', '{\"clueText\": \"Catatan lama, tulisan sudah pudar: ibu negerinya Kuala Terengganu.\", \"options\": [{\"text\": \"Negeri itu ialah Terengganu.\", \"isCorrect\": true}, {\"text\": \"Negeri itu ialah Sabah.\", \"isCorrect\": false, \"consequence\": \"Hmm, itu cerita Sabah. Penduduk Terengganu saling berpandangan dan ada yang tergelak kecil kerana tersilap negeri.\"}, {\"text\": \"Negeri itu ialah Kedah.\", \"isCorrect\": false, \"consequence\": \"Maklumat Kedah tersasar masuk ke Terengganu! Sekarang semua orang keliru dan perlu bertanya semula.\"}], \"aftermath\": \"Catatan lama tentang Terengganu disalah baca, dan sejarah negeri itu ditulis dengan silap.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Kuala Terengganu.\", \"isCorrect\": true, \"reaction\": \"Tepat sekali, pengembara! Itulah maklumat Terengganu yang patut diingat. Sorakan bergema di sekeliling!\"}, {\"text\": \"Kota Kinabalu.\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Sabah, bukan Terengganu. Cuba ingat semula.\"}, {\"text\": \"Alor Setar.\", \"isCorrect\": false, \"reaction\": \"Hmm, itu milik Kedah, bukan Terengganu. Ada yang tergelak kecil di belakang.\"}], \"clue\": \"Cuba ingat gambar Terengganu: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(239, 'e2_n3_s11', 'Soalan Sergahan di Kelantan', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang ibu negeri dan bandar diraja bagi Kelantan.', '3', 'Mengenal pasti ibu negeri dan bandar diraja bagi Kelantan.', '{\"prompt\": \"Tiba-tiba seorang pelajar dengan buku nota penuh contengan menahan kau dan bertanya: apakah ibu negeri Kelantan?\", \"options\": [{\"text\": \"Kota Bharu\", \"isCorrect\": true}, {\"text\": \"Georgetown\", \"isCorrect\": false, \"consequence\": \"Maklumat Pulau Pinang tersasar masuk ke Kelantan! Sekarang semua orang keliru dan perlu bertanya semula.\"}, {\"text\": \"Seremban, bandar diraja Seri Menanti\", \"isCorrect\": false, \"consequence\": \"Aduh, itu bukan Kelantan, itu Negeri Sembilan! Catatan kau pun terpaksa dipadam dan ditulis semula.\"}], \"aftermath\": \"Jawapan tentang Kelantan tersasar. Soalan yang sama ditanya semula dan semua orang keliru.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Kota Bharu.\", \"isCorrect\": true, \"reaction\": \"Betul, pengembara! Jawapan itu kena tepat pada Kelantan. Penduduk bertepuk tangan.\"}, {\"text\": \"Georgetown.\", \"isCorrect\": false, \"reaction\": \"Hmm, itu milik Pulau Pinang, bukan Kelantan. Ada yang tergelak kecil di belakang.\"}, {\"text\": \"Seremban.\", \"isCorrect\": false, \"reaction\": \"Silap negeri, pengembara! Itu tentang Negeri Sembilan, bukan Kelantan. Cuba sekali lagi!\"}], \"clue\": \"Cuba ingat gambar Kelantan: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(240, 'e2_n3_s12', 'Misi Lambang: Jata, Bendera dan Radio Sabah', 'Cari jata, bendera dan radio pada gambar untuk mengenal pasti fakta tentang Sabah. Mata tajam, ya!', '2', 'Mengenal pasti maklumat ibu negeri dan bandar diraja bagi Sabah daripada jata, bendera dan radio.', '{\"hotspots\":[{\"name\":\"Pada jata: ketua negeri bergelar Yang di-Pertua Negeri\",\"top\":\"48%\",\"left\":\"76.1%\"},{\"name\":\"Di tiang bendera: ibu negeri Kota Kinabalu\",\"top\":\"38.4%\",\"left\":\"45.4%\"},{\"name\":\"lagu \'Sabah Tanah Airku\'\",\"top\":\"74.1%\",\"left\":\"28.4%\"}],\"bgImage\":\"../assets/gameAsset/background/negeri_sabah.png\",\"aftermath\":\"Jata, bendera dan radio Sabah tidak dibaca dengan teliti. Maklumat negeri itu hilang daripada ingatan.\",\"turns\":[{\"after\":2,\"options\":[{\"text\":\"Kota Kinabalu.\",\"isCorrect\":true,\"reaction\":\"Hebat, pengembara! Itulah dia tentang Sabah. Semua mengangguk setuju.\"},{\"text\":\"Alor Setar.\",\"isCorrect\":false,\"reaction\":\"Silap negeri, pengembara! Itu tentang Kedah, bukan Sabah. Cuba sekali lagi!\"},{\"text\":\"Shah Alam.\",\"isCorrect\":false,\"reaction\":\"Eh, itu cerita Selangor, pengembara! Sabah lain ceritanya. Orang ramai mengerut dahi.\"}],\"clue\":\"Cuba ingat gambar Sabah: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}');
INSERT INTO `Quest` (`questID`, `sceneID`, `questName`, `instruction`, `questType`, `description`, `questContent`) VALUES
(241, 'e2_n3_s13', 'Padanan Pantas: Ibu negeri dan bandar diraja', 'Cepat, padankan setiap negeri dengan ibu negeri dan bandar dirajanya yang betul sebelum kad bercampur aduk!', '4', 'Mengenal pasti ibu negeri dan bandar diraja bagi Sarawak dan negeri lain.', '{\"pairs\": [{\"text\": \"Sarawak\", \"pair\": 1}, {\"text\": \"Kuching\", \"pair\": 1}, {\"text\": \"Perlis\", \"pair\": 2}, {\"text\": \"Kangar, bandar diraja Arau\", \"pair\": 2}, {\"text\": \"Perak\", \"pair\": 3}, {\"text\": \"Ipoh, bandar diraja Kuala Kangsar\", \"pair\": 3}, {\"text\": \"Melaka\", \"pair\": 4}, {\"text\": \"Bandar Melaka\", \"pair\": 4}], \"aftermath\": \"Maklumat Sarawak bercampur dengan negeri lain. Kekeliruan itu terus diulang dari mulut ke mulut.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Kuching.\", \"isCorrect\": true, \"reaction\": \"Ya, ya, itulah jawapannya, pengembara! Sarawak memang begitu. Ada yang bersorak kecil.\"}, {\"text\": \"Kangar.\", \"isCorrect\": false, \"reaction\": \"Eh, itu cerita Perlis, pengembara! Sarawak lain ceritanya. Orang ramai mengerut dahi.\"}, {\"text\": \"Ipoh.\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Perak, bukan Sarawak. Cuba ingat semula.\"}], \"clue\": \"Cuba ingat gambar Sarawak: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(242, 'e2_n3_s14', 'Nyahkod Catatan Lama Wilayah Persekutuan', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Wilayah Persekutuan melalui lagu negeri.', '{\"clueText\": \"Catatan lama, tulisan sudah pudar: lagu negeri ini ialah \'Maju dan Sejahtera\'.\", \"options\": [{\"text\": \"Negeri itu ialah Wilayah Persekutuan.\", \"isCorrect\": true}, {\"text\": \"Negeri itu ialah Pulau Pinang.\", \"isCorrect\": false, \"consequence\": \"Kau menyebut maklumat Pulau Pinang untuk Wilayah Persekutuan. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut.\"}, {\"text\": \"Negeri itu ialah Negeri Sembilan.\", \"isCorrect\": false, \"consequence\": \"Itu fakta Negeri Sembilan, bukan Wilayah Persekutuan! Pelajar yang mendengarnya menulis jawapan salah dalam buku, dan cikgu terpaksa membetulkannya kemudian.\"}], \"aftermath\": \"Catatan lama tentang Wilayah Persekutuan disalah baca, dan sejarah negeri itu ditulis dengan silap.\", \"turns\": [{\"after\": 2, \"options\": [{\"text\": \"Maju dan Sejahtera.\", \"isCorrect\": true, \"reaction\": \"Tepat sekali, pengembara! Itulah maklumat Wilayah Persekutuan yang patut diingat. Sorakan bergema di sekeliling!\"}, {\"text\": \"Untuk Negeri Kita.\", \"isCorrect\": false, \"reaction\": \"Aduh, tersilap sedikit! Itu maklumat Pulau Pinang, bukan Wilayah Persekutuan. Cuba ingat semula.\"}, {\"text\": \"Berkatlah Yang di-Pertuan Besar.\", \"isCorrect\": false, \"reaction\": \"Hmm, itu milik Negeri Sembilan, bukan Wilayah Persekutuan. Ada yang tergelak kecil di belakang.\"}], \"clue\": \"Cuba ingat gambar Wilayah Persekutuan: jata, bendera dan radio di situ menyimpan petunjuknya.\"}]}'),
(301, 'e3_n1_s1', 'Susun Jalan ke Rukun Negara', 'Susun peristiwa yang membawa kepada kelahiran Rukun Negara mengikut urutan yang betul.', '1', 'Mengenal pasti latar belakang Rukun Negara: 13 Mei 1969, MAGERAN, MAPEN dan 4 Mac 1970.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"13 Mei 1969\", \"text\": \"Rusuhan kaum 13 Mei 1969 menegangkan hubungan antara kaum\", \"why\": \"Ketegangan yang memuncak menjadi punca negara perlukan pemulihan.\"}, {\"id\": 2, \"year\": \"Selepas 1969\", \"text\": \"MAGERAN mentadbir negara selepas peristiwa itu\", \"why\": \"Pentadbiran khas memulihkan ketenteraman dan menyediakan asas perpaduan.\"}, {\"id\": 3, \"year\": \"4 Mac 1970\", \"text\": \"Jawatankuasa Rukun Negara di bawah MAPEN merangka dan memperkenalkan Rukun Negara\", \"why\": \"Rukun Negara menjadi panduan bersama untuk mengukuhkan perpaduan.\"}, {\"id\": 4, \"year\": \"31 Ogos 1970\", \"text\": \"Rukun Negara diisytiharkan pada Hari Kebangsaan\", \"why\": \"Seluruh rakyat berikrar berpegang pada prinsip yang sama.\"}], \"aftermath\": \"Urutan yang tersasar membuat laporan bercanggah. Arahan tertunda sehari dan Bilik Gerakan bertambah kelam-kabut.\", \"turns\": [{\"after\": 3, \"options\": [{\"text\": \"Rusuhan 13 Mei 1969, MAGERAN mentadbir negara, kemudian Rukun Negara diperkenalkan.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tun! Gambaran penuh. Papan misi bercahaya hijau, markas bersorak!\"}, {\"text\": \"MAGERAN dahulu, kemudian rusuhan 13 Mei 1969, dan akhirnya Rukun Negara diperkenalkan.\", \"isCorrect\": false, \"reaction\": \"Eh, Tun, MAGERAN muncul kerana rusuhan itu. Kalau terbalik, laporan kita bercanggah dan kerani mula menggaru kepala.\"}, {\"text\": \"Rukun Negara dahulu, kemudian rusuhan 13 Mei 1969, dan akhirnya MAGERAN mentadbir negara.\", \"isCorrect\": false, \"reaction\": \"Tun, Rukun Negara lahir selepas rusuhan, bukan sebelumnya. Kalau terbalik, sejarah pun kelam-kabut!\"}], \"clue\": \"MAGERAN ditubuhkan selepas peristiwa 13 Mei 1969, dan Rukun Negara hanya lahir selepas itu.\"}]}'),
(302, 'e3_n1_s2', 'Padanan Kaum, Kerja dan Tempat Tinggal', 'Padankan setiap kaum dengan kegiatan ekonomi dan tempat tinggalnya, serta kaitkan fahaman politik dengan 13 Mei 1969.', '4', 'Mengenal pasti sebab Rukun Negara diperkenalkan: perbezaan ekonomi, tempat tinggal dan fahaman politik.', '{\"pairs\": [{\"text\": \"Melayu\", \"pair\": 1}, {\"text\": \"Pertanian sara diri; tinggal di kampung dan pedalaman\", \"pair\": 1}, {\"text\": \"Cina\", \"pair\": 2}, {\"text\": \"Perlombongan dan perniagaan; tinggal di bandar\", \"pair\": 2}, {\"text\": \"India\", \"pair\": 3}, {\"text\": \"Perladangan; tinggal di ladang\", \"pair\": 3}, {\"text\": \"Fahaman politik\", \"pair\": 4}, {\"text\": \"Menegangkan hubungan kaum sehingga rusuhan 13 Mei 1969\", \"pair\": 4}], \"aftermath\": \"Maklumat kau bercampur aduk. Laporan tinjauan menyalahkan satu kaum dan salah faham semakin tebal.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Kegiatan ekonomi dan tempat tinggal yang berasingan, serta fahaman politik berbeza.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tun! Kami jarang bertemu dan mudah salah faham. Itu puncanya, bukan niat jahat mana-mana kaum.\"}, {\"text\": \"Semua kaum berebut tanah sawah yang sama sehingga bergaduh setiap hari.\", \"isCorrect\": false, \"reaction\": \"Kami tak berebut sawah pun, Tun. Cerita begitu hanya menambah syak wasangka.\"}, {\"text\": \"Semua kaum tinggal bercampur di taman perumahan yang sama sejak dahulu lagi.\", \"isCorrect\": false, \"reaction\": \"Kalau kami sudah bercampur, Tun tak perlu datang bertanya! Kenyataannya kami tinggal berasingan.\"}], \"clue\": \"Ingat tiga perbezaan yang disebut: kerja, tempat tinggal dan fahaman politik.\"}]}'),
(303, 'e3_n1_s3', 'Cari Bukti Lima Matlamat', 'Cari objek pada gambar yang mewakili setiap matlamat Rukun Negara.', '2', 'Mengenal pasti lima matlamat Rukun Negara.', '{\"hotspots\":[{\"name\":\"Bendera dan jata: perpaduan yang lebih erat dalam kalangan masyarakat\",\"top\":\"12.4%\",\"left\":\"55.4%\"},{\"name\":\"Buku Perlembagaan: memelihara satu cara hidup demokrasi\",\"top\":\"45.8%\",\"left\":\"75.4%\"},{\"name\":\"Timbangan keadilan: masyarakat adil, kemakmuran dinikmati bersama\",\"top\":\"29.8%\",\"left\":\"83.2%\"},{\"name\":\"Masjid dan gereja: cara liberal terhadap tradisi kebudayaan yang pelbagai\",\"top\":\"27.2%\",\"left\":\"28.1%\"},{\"name\":\"Panel digital: masyarakat progresif dengan sains dan teknologi moden\",\"top\":\"79%\",\"left\":\"51.3%\"}],\"bgImage\":\"../assets/gameAsset/background/matlamat_rukun_negara.png\",\"aftermath\":\"Dua matlamat terlepas pandang. Anak-anak pulang dengan senarai yang tidak lengkap.\",\"turns\":[{\"after\":4,\"options\":[{\"text\":\"Membina masyarakat progresif yang menggunakan sains dan teknologi moden.\",\"isCorrect\":true,\"reaction\":\"Tepat, Tun! Skrin digital itu pun bersinar. Anak saya bersorak!\"},{\"text\":\"Memelihara satu cara hidup demokrasi dalam kalangan seluruh rakyat.\",\"isCorrect\":false,\"reaction\":\"Demokrasi tentang cara kita memilih dan memerintah, Tun, bukan peralatan canggih. Anak saya berkerut dahi.\"},{\"text\":\"Mencipta masyarakat yang adil dan saksama bagi seluruh rakyat.\",\"isCorrect\":false,\"reaction\":\"Itu tentang kemakmuran yang dikongsi, Tun. Skrin digital itu tak bersinar pun!\"}],\"clue\":\"Cari matlamat yang menyebut perkataan moden.\"}]}'),
(304, 'e3_n1_s4', 'Bantu Menjawab Soalan Anak Muda', 'Bantu Tun Abdul Razak menjawab pertanyaan anak muda tentang prinsip Kesetiaan kepada Raja dan Negara.', '3', 'Memahami prinsip Kepercayaan kepada Tuhan dan Kesetiaan kepada Raja dan Negara.', '{\"prompt\": \"Arun bertanya kepada kau: kepada siapakah rakyat Malaysia memberi taat setia sebagai Ketua Utama Negara, dan apakah kesannya kepada masyarakat?\", \"options\": [{\"text\": \"Yang di-Pertuan Agong; masyarakat bersatu padu dan penuh semangat patriotik.\", \"isCorrect\": true}, {\"text\": \"Perdana Menteri; masyarakat bergantung kepada satu parti sahaja.\", \"isCorrect\": false, \"consequence\": \"Arun menulis jawapan yang salah. Kawan-kawannya ikut menyalin, dan taat setia kepada Yang di-Pertuan Agong terlepas daripada nota mereka.\"}, {\"text\": \"Ketua kaum masing-masing; masyarakat kekal terpisah mengikut kaum.\", \"isCorrect\": false, \"consequence\": \"Arun menyebarkan jawapan itu. Jurang antara kaum seolah-olah dibenarkan, bertentangan dengan tujuan Rukun Negara.\"}], \"aftermath\": \"Taat setia disalah tafsir. Anak-anak muda pulang dengan faham yang tersasar tentang Ketua Utama Negara.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Menghormati amalan agama mereka kerana kepercayaan menyatukan rakyat berbilang kaum.\", \"isCorrect\": true, \"reaction\": \"Betul, Tun! Pagi ini kami hantar kuih untuk jiran kami. Mereka gembira, kami pun gembira!\"}, {\"text\": \"Menegur cara ibadat jiran supaya sama dengan cara ibadat kami sendiri.\", \"isCorrect\": false, \"reaction\": \"Aduh, Tun. Jiran kami terasa hati dan menjauh. Kita nak bersatu, bukan menyeragamkan.\"}, {\"text\": \"Tidak mengendahkan jiran kerana urusan agama ialah urusan masing-masing sahaja.\", \"isCorrect\": false, \"reaction\": \"Kalau kami tak peduli langsung, Tun, jurang makin besar. Prinsip ini menuntut rasa hormat.\"}], \"clue\": \"Prinsip pertama meminta kita menghormati amalan agama masyarakat lain.\"}]}'),
(305, 'e3_n1_s5', 'Padanan Lima Prinsip', 'Padankan setiap prinsip Rukun Negara dengan maksudnya yang betul.', '4', 'Mengenal pasti maksud lima prinsip Rukun Negara.', '{\"pairs\": [{\"text\": \"Kepercayaan kepada Tuhan\", \"pair\": 1}, {\"text\": \"Agama pegangan utama dan hormat amalan agama lain\", \"pair\": 1}, {\"text\": \"Kesetiaan kepada Raja dan Negara\", \"pair\": 2}, {\"text\": \"Taat setia kepada Yang di-Pertuan Agong\", \"pair\": 2}, {\"text\": \"Keluhuran Perlembagaan\", \"pair\": 3}, {\"text\": \"Perlembagaan Persekutuan ialah undang-undang tertinggi\", \"pair\": 3}, {\"text\": \"Kedaulatan Undang-undang\", \"pair\": 4}, {\"text\": \"Hormati dan patuhi undang-undang demi keharmonian\", \"pair\": 4}, {\"text\": \"Kesopanan dan Kesusilaan\", \"pair\": 5}, {\"text\": \"Nilai murni, disiplin dan akhlak mulia\", \"pair\": 5}], \"aftermath\": \"Prinsip-prinsip tertukar tempat. Murid-murid menghafal maksud yang salah dan guru terpaksa mengajar semula.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Keluhuran Perlembagaan: tiada institusi dapat mengatasi Perlembagaan Persekutuan.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tun! Murid-murid bersorak sampai burung merpati terbang!\"}, {\"text\": \"Kesopanan dan Kesusilaan: setiap rakyat perlu bersopan dengan semua orang.\", \"isCorrect\": false, \"reaction\": \"Tun, itu tentang nilai murni. Perlembagaan ialah soal undang-undang tertinggi, jadi jawapan itu tidak sepadan.\"}, {\"text\": \"Kepercayaan kepada Tuhan: agama menjadi pegangan utama rakyat Malaysia.\", \"isCorrect\": false, \"reaction\": \"Itu prinsip pertama, Tun. Soalan ini tentang kedudukan Perlembagaan di atas semua institusi.\"}], \"clue\": \"Soalan ini tentang undang-undang tertinggi negara.\"}]}'),
(306, 'e3_n1_s6', 'Nyahkod Nota Peranan Rukun Negara', 'Baca petunjuk nota yang pudar dan tentukan peranan Rukun Negara yang hilang.', '5', 'Mengenal pasti enam peranan Rukun Negara.', '{\"clueText\": \"Nota pudar menyenaraikan peranan Rukun Negara: meraikan kepelbagaian agama dan kepercayaan, membentuk masyarakat patriotik, memupuk sikap hormat undang-undang, mengukuhkan perpaduan masyarakat dan menerapkan nilai murni. Peranan terakhir berkait dengan identiti dan perasaan memiliki sebagai rakyat Malaysia.\", \"options\": [{\"text\": \"Membentuk jati diri masyarakat Malaysia.\", \"isCorrect\": true}, {\"text\": \"Menggantikan Perlembagaan Persekutuan sebagai undang-undang tertinggi.\", \"isCorrect\": false, \"consequence\": \"Murid menulis jawapan itu dalam buku. Mereka salah faham kedudukan Perlembagaan dan Rukun Negara.\"}, {\"text\": \"Menyeragamkan semua agama dan budaya menjadi satu.\", \"isCorrect\": false, \"consequence\": \"Nota itu bercanggah dengan peranan meraikan kepelbagaian. Rakyat keliru tentang maksud sebenar perpaduan.\"}], \"aftermath\": \"Peranan terakhir tersilap dibaca. Nota hari bersejarah itu diedarkan dengan maklumat yang salah.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Membentuk jati diri masyarakat Malaysia.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tun! Nota itu bersinar semula dan semua orang bersorak!\"}, {\"text\": \"Menggantikan Perlembagaan Persekutuan.\", \"isCorrect\": false, \"reaction\": \"Tun, Rukun Negara tidak menggantikan Perlembagaan. Murid-murid yang salah tulis hampir gagal ujian!\"}, {\"text\": \"Menyeragamkan semua agama dan budaya.\", \"isCorrect\": false, \"reaction\": \"Eh, Tun, bukankah peranan pertama meraikan kepelbagaian? Jawapan itu bercanggah dan nota jadi bercelaru.\"}], \"clue\": \"Satu peranan yang pudar berkait dengan identiti rakyat Malaysia.\"}]}'),
(307, 'e3_n2_s1', 'Nyahkod Surat Pos Bantuan', 'Baca petunjuk surat dan tentukan siapa yang mentadbir negara serta di bawah majlis apa Rukun Negara dirangka.', '5', 'Mengenal pasti latar belakang Rukun Negara: MAGERAN, MAPEN dan 4 Mac 1970.', '{\"clueText\": \"Surat di meja pos bantuan menulis: Selepas rusuhan kaum 13 Mei 1969, negara ditadbir oleh sebuah majlis khas yang memulihkan ketenteraman. Kemudian sebuah jawatankuasa di bawah majlis perundingan negara merangka dasar perpaduan itu pada 4 Mac 1970.\", \"options\": [{\"text\": \"MAGERAN mentadbir negara; Rukun Negara dirangka di bawah MAPEN pada 4 Mac 1970.\", \"isCorrect\": true}, {\"text\": \"MAPEN mentadbir negara; Rukun Negara dirangka di bawah MAGERAN pada 4 Mac 1970.\", \"isCorrect\": false, \"consequence\": \"Pasukan sukarelawan menyalin maklumat yang tertukar. Buku kerja mereka memisahkan dua majlis itu dengan cara yang salah.\"}, {\"text\": \"MAGERAN mentadbir negara; Rukun Negara dirangka di bawah MAPEN pada 13 Mei 1969.\", \"isCorrect\": false, \"consequence\": \"Tarikh itu ialah hari rusuhan, bukan hari Rukun Negara dirangka. Surat itu dicatat dengan tarikh yang salah.\"}], \"aftermath\": \"Surat itu disalah baca. Pasukan sukarelawan menyampaikan maklumat yang tersasar kepada penduduk.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"MAGERAN mentadbir negara, dan Rukun Negara dirangka di bawah MAPEN.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tun! Wei Jie menandakan \'betul\' pada surat itu. Pasukan kami bersorak!\"}, {\"text\": \"MAPEN mentadbir negara, dan Rukun Negara dirangka di bawah MAGERAN.\", \"isCorrect\": false, \"reaction\": \"Alamak, Tun, nama dua majlis itu tertukar. Surat itu pun dibaca terbalik oleh seluruh pasukan.\"}, {\"text\": \"MAGERAN mentadbir negara, tetapi Rukun Negara dirangka sebelum rusuhan.\", \"isCorrect\": false, \"reaction\": \"Tun, rusuhan 13 Mei 1969 berlaku dahulu. Kalau Rukun Negara sebelum itu, ceritanya tak masuk akal!\"}], \"clue\": \"MAGERAN mentadbir negara, manakala jawatankuasa yang merangka Rukun Negara bekerja di bawah MAPEN.\"}]}'),
(308, 'e3_n2_s2', 'Cari Bukti Kaum, Kerja dan Tempat Tinggal', 'Cari tiga tempat pada gambar untuk mengenal pasti kegiatan ekonomi dan tempat tinggal setiap kaum.', '2', 'Mengenal pasti sebab Rukun Negara diperkenalkan: perbezaan ekonomi dan tempat tinggal kaum.', '{\"bgImage\": \"../assets/gameAsset/background/petempatan_semua_dahulu.png\", \"hotspots\": [{\"name\": \"Ladang getah: orang India menoreh dan tinggal di ladang (perladangan)\", \"top\": \"80%\", \"left\": \"7%\"}, {\"name\": \"Kampung dan sawah: orang Melayu bertani sara diri di kampung dan pedalaman\", \"top\": \"48%\", \"left\": \"62%\"}, {\"name\": \"Rumah kedai dan pekan sungai: orang Cina berniaga dan melombong di bandar\", \"top\": \"72%\", \"left\": \"85%\"}], \"aftermath\": \"Bukti tersilap dicatat. Laporan kau menyebut kaum yang salah di tempat yang salah, dan salah faham bertambah.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Untuk mengukuhkan perpaduan dan semangat kekitaan masyarakat berbilang kaum.\", \"isCorrect\": true, \"reaction\": \"Betul, Tun! Kami akan cerita begitu pada anak-anak. \'Semangat kekitaan\' memang sedap didengar!\"}, {\"text\": \"Untuk mengasingkan setiap kaum di kawasan masing-masing supaya tidak bergaduh.\", \"isCorrect\": false, \"reaction\": \"Mengasingkan lagi, Tun? Itu yang buat kami jauh. Kalau begitu cerita kita pun terbalik.\"}, {\"text\": \"Untuk memajukan ekonomi satu kaum sahaja dan melupakan kaum yang lain.\", \"isCorrect\": false, \"reaction\": \"Tun, anak-anak kami berbeza kaum. Kalau hanya satu kaum, yang lain berasa tersisih dan marah.\"}], \"clue\": \"Rukun Negara diperkenalkan untuk menyatukan, bukan mengasingkan.\"}]}'),
(309, 'e3_n2_s3', 'Padanan Lima Matlamat', 'Padankan setiap matlamat Rukun Negara dengan penerangannya.', '4', 'Mengenal pasti lima matlamat Rukun Negara.', '{\"pairs\": [{\"text\": \"Perpaduan\", \"pair\": 1}, {\"text\": \"Perpaduan yang lebih erat dalam kalangan seluruh masyarakat\", \"pair\": 1}, {\"text\": \"Demokrasi\", \"pair\": 2}, {\"text\": \"Memelihara satu cara hidup demokrasi\", \"pair\": 2}, {\"text\": \"Keadilan\", \"pair\": 3}, {\"text\": \"Kemakmuran negara dinikmati bersama secara adil dan saksama\", \"pair\": 3}, {\"text\": \"Kebudayaan\", \"pair\": 4}, {\"text\": \"Cara liberal terhadap tradisi kebudayaan yang kaya dan pelbagai\", \"pair\": 4}, {\"text\": \"Sains dan teknologi\", \"pair\": 5}, {\"text\": \"Masyarakat progresif yang menggunakan sains dan teknologi moden\", \"pair\": 5}], \"aftermath\": \"Matlamat-matlamat tertukar. Tarian singa berhenti dan penonton pulang dengan senarai yang bercelaru.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Dinikmati bersama secara adil dan saksama.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tun! Tarian singa terus menari. Semua orang merasa dihargai!\"}, {\"text\": \"Dinikmati oleh kaum yang paling ramai sahaja.\", \"isCorrect\": false, \"reaction\": \"Tun, itu tidak adil. Penonton yang tidak disebut terus senyap dan pulang.\"}, {\"text\": \"Dinikmati oleh mereka yang tinggal di bandar sahaja.\", \"isCorrect\": false, \"reaction\": \"Tun, orang kampung dan ladang pun rakyat. Kalau mereka tertinggal, jurang makin besar.\"}], \"clue\": \"Matlamat ketiga menyebut masyarakat yang adil, dan kemakmuran dinikmati bersama.\"}]}'),
(310, 'e3_n2_s4', 'Cari Bukti Dua Prinsip Pertama', 'Cari lambang pada gambar yang mewakili prinsip Kepercayaan kepada Tuhan dan Kesetiaan kepada Raja dan Negara.', '2', 'Memahami prinsip Kepercayaan kepada Tuhan dan Kesetiaan kepada Raja dan Negara.', '{\"hotspots\":[{\"name\":\"Orang pelbagai agama berdoa: agama pegangan utama, hormat amalan agama lain\",\"top\":\"24%\",\"left\":\"12%\"},{\"name\":\"Jata negara: taat setia kepada Yang di-Pertuan Agong, Ketua Utama Negara\",\"top\":\"25.8%\",\"left\":\"41.5%\"},{\"name\":\"Tugu Negara: semangat patriotik dan taat setia kepada negara\",\"top\":\"36.8%\",\"left\":\"91.9%\"}],\"bgImage\":\"../assets/gameAsset/background/prinsip_rukun_negara_.png\",\"aftermath\":\"Lambang prinsip terlepas pandang. Orang ramai berpecah dan ikrar dibaca tanpa difahami.\",\"turns\":[{\"after\":4,\"options\":[{\"text\":\"Menyatupadukan rakyat berbilang kaum dan menumbuhkan semangat patriotik.\",\"isCorrect\":true,\"reaction\":\"Tepat, Tun! Seluruh dataran bersorak. Kami berasa seperti satu keluarga!\"},{\"text\":\"Membuat setiap kaum berasa lebih baik daripada kaum lain dalam semua perkara.\",\"isCorrect\":false,\"reaction\":\"Tun, itu bukan maksudnya. Kata-kata begitu hanya menjauhkan, dan anak-anak mula berbalah.\"},{\"text\":\"Menggantikan Perlembagaan Persekutuan sebagai undang-undang tertinggi negara.\",\"isCorrect\":false,\"reaction\":\"Tun, prinsip ini tidak menggantikan Perlembagaan. Orang ramai keliru dan perayaan pun jadi sunyi.\"}],\"clue\":\"Dua prinsip itu menyatukan rakyat dan menumbuhkan semangat cinta akan negara.\"}]}'),
(311, 'e3_n2_s5', 'Nyahkod Petikan Tiga Prinsip', 'Baca petikan yang separuh hilang dan tentukan maksud yang betul bagi prinsip Kesopanan dan Kesusilaan.', '5', 'Mengenal pasti maksud prinsip Keluhuran Perlembagaan, Kedaulatan Undang-undang serta Kesopanan dan Kesusilaan.', '{\"clueText\": \"Petikan menulis: Perlembagaan Persekutuan ialah undang-undang tertinggi negara, dan setiap rakyat menghormati serta mematuhi undang-undang. Bagi Kesopanan dan Kesusilaan, petikan menyebut amalan nilai murni membentuk masyarakat berdisiplin dan berakhlak mulia, dan ayat akhirnya hilang.\", \"options\": [{\"text\": \"Masyarakat saling memahami dan bekerjasama dalam suasana yang harmoni.\", \"isCorrect\": true}, {\"text\": \"Setiap kaum menyendiri supaya tiada pertelingkahan berlaku.\", \"isCorrect\": false, \"consequence\": \"Petikan dicetak dengan maksud yang terbalik. Pembaca menyangka perpaduan bermaksud setiap kaum berasingan.\"}, {\"text\": \"Undang-undang boleh dilanggar apabila tiada sesiapa yang melihat.\", \"isCorrect\": false, \"consequence\": \"Petikan dicetak dengan nasihat yang salah. Ia bertentangan dengan Kedaulatan Undang-undang dan mencemar nama prinsip itu.\"}], \"aftermath\": \"Petikan dicetak dengan ayat yang salah. Surat khabar menyebarkan maksud prinsip yang tersasar.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Masyarakat saling memahami dan bekerjasama dalam suasana harmoni.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tun! Mesin taip berbunyi TING dan petikan lengkap!\"}, {\"text\": \"Setiap kaum menyendiri supaya tiada pertelingkahan.\", \"isCorrect\": false, \"reaction\": \"Tun, saling memahami dan bekerjasama tidak sama dengan menyendiri. Petikan itu terbalik maksudnya.\"}, {\"text\": \"Undang-undang boleh dilanggar jika tiada orang melihat.\", \"isCorrect\": false, \"reaction\": \"Tun, itu bercanggah dengan prinsip keempat. Petikan itu hampir dicetak dengan nasihat yang salah!\"}], \"clue\": \"Prinsip kelima menggalakkan saling memahami dan bekerjasama dalam kalangan masyarakat.\"}]}'),
(312, 'e3_n2_s6', 'Bantu Mei Ling Menjawab', 'Bantu murid menjawab soalan guru tentang peranan Rukun Negara.', '3', 'Mengenal pasti enam peranan Rukun Negara.', '{\"prompt\": \"Guru bertanya kepada kau: apakah peranan Rukun Negara dalam hal perpaduan, nilai murni dan jati diri masyarakat Malaysia?\", \"options\": [{\"text\": \"Mengukuhkan perpaduan, menerapkan nilai murni dan membentuk jati diri masyarakat Malaysia.\", \"isCorrect\": true}, {\"text\": \"Mengasingkan setiap kaum, menekankan kuasa dan menggantikan jati diri tempatan.\", \"isCorrect\": false, \"consequence\": \"Murid menulis jawapan yang bertentangan dengan Rukun Negara. Guru terpaksa mengajar semula pelajaran itu di hadapan kelas.\"}, {\"text\": \"Menyeragamkan budaya, melemahkan undang-undang dan menolak nilai murni.\", \"isCorrect\": false, \"consequence\": \"Murid-murid menyalin jawapan itu dan pulang membawa salah faham. Mereka tidak lagi menghargai perbezaan.\"}], \"aftermath\": \"Peranan Rukun Negara dijawab dengan salah. Murid-murid pulang membawa salah faham tentang perpaduan dan jati diri.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Kepelbagaian agama dan kepercayaan.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tun! Mei Ling terus menulis sambil tersenyum. Loceng pun berbunyi tepat pada masanya!\"}, {\"text\": \"Kejayaan satu kaum sahaja.\", \"isCorrect\": false, \"reaction\": \"Tun, itu bukan peranannya. Kalau begitu murid lain tersisih dan mula berasa kecil hati.\"}, {\"text\": \"Kemenangan satu parti politik.\", \"isCorrect\": false, \"reaction\": \"Tun, Rukun Negara bukan milik satu parti. Salah faham begitu hanya memecahbelahkan kita.\"}], \"clue\": \"Peranan pertama menyebut meraikan kepelbagaian agama dan kepercayaan.\"}]}'),
(313, 'e3_n3_s1', 'Bantu Tunku Menjawab Wartawan', 'Bantu Tunku Abdul Rahman menjawab soalan wartawan tentang bagaimana Rukun Negara bermula.', '3', 'Mengenal pasti latar belakang Rukun Negara: 13 Mei 1969, MAGERAN, MAPEN dan 4 Mac 1970.', '{\"prompt\": \"Wartawan bertanya kepada kau: bagaimanakah Rukun Negara bermula dan siapakah yang merangka serta memperkenalkannya?\", \"options\": [{\"text\": \"Selepas 13 Mei 1969 dan MAGERAN, Jawatankuasa Rukun Negara di bawah MAPEN memperkenalkannya pada 4 Mac 1970.\", \"isCorrect\": true}, {\"text\": \"Sebelum 13 Mei 1969, MAGERAN dan MAPEN memperkenalkannya melalui satu undian rakyat pada 4 Mac 1970.\", \"isCorrect\": false, \"consequence\": \"Akhbar menulis urutan yang salah. Pembaca menyangka Rukun Negara wujud sebelum rusuhan dan sejarahnya menjadi kabur.\"}, {\"text\": \"Selepas 13 Mei 1969, MAGERAN sendiri menulis dan mengisytiharkannya pada 4 Mac 1970 tanpa jawatankuasa.\", \"isCorrect\": false, \"consequence\": \"Akhbar menyebut peranan jawatankuasa tidak wujud. Pembaca tidak tahu siapa yang sebenarnya merangka Rukun Negara.\"}], \"aftermath\": \"Wartawan menyiarkan sejarah yang salah. Rakyat membaca urutan yang terbalik dan terus mengulang kesilapan itu.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Selepas 13 Mei 1969 dan MAGERAN, jawatankuasa di bawah MAPEN merangkanya pada 4 Mac 1970.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tunku! Wartawan mengangguk dan pen berlari di atas kertas. Tajuk akhbar esok pasti betul!\"}, {\"text\": \"Sebelum rusuhan 13 Mei 1969, sebuah jawatankuasa khas merangkanya pada 4 Mac 1970.\", \"isCorrect\": false, \"reaction\": \"Tunku, rusuhan berlaku dahulu. Kalau terbalik, wartawan menulis cerita yang tidak masuk akal.\"}, {\"text\": \"Selepas rusuhan 13 Mei 1969, MAGERAN sendiri merangkanya tanpa sebarang jawatankuasa khas.\", \"isCorrect\": false, \"reaction\": \"Tunku, ia dirangka oleh jawatankuasa di bawah MAPEN. Tajuk akhbar silap dan kami kena betulkan.\"}], \"clue\": \"Rusuhan berlaku dahulu, kemudian MAGERAN, dan jawatankuasa di bawah MAPEN merangka Rukun Negara.\"}]}'),
(314, 'e3_n3_s2', 'Nyahkod Catatan Lama Pekan', 'Baca catatan lama dan tentukan tujuan utama Rukun Negara diperkenalkan.', '5', 'Mengenal pasti sebab Rukun Negara diperkenalkan: perpaduan dan semangat kekitaan.', '{\"clueText\": \"Catatan lama menyebut: Orang Melayu bertani sara diri di kampung, orang Cina melombong dan berniaga di bandar, orang India berladang di ladang. Fahaman politik yang berbeza menegangkan hubungan sehingga rusuhan 13 Mei 1969. Satu dasar perlu diperkenalkan untuk mengatasinya. Bahagian tujuannya pudar.\", \"options\": [{\"text\": \"Mengukuhkan perpaduan dan semangat kekitaan masyarakat berbilang kaum.\", \"isCorrect\": true}, {\"text\": \"Memisahkan setiap kaum di kawasan tempat tinggal masing-masing.\", \"isCorrect\": false, \"consequence\": \"Catatan itu ditulis semula dengan maksud yang terbalik. Rakyat menyangka jarak antara kaum memang dikehendaki.\"}, {\"text\": \"Menyeragamkan harga barang di semua kampung, bandar dan ladang.\", \"isCorrect\": false, \"consequence\": \"Pembaca menyangka Rukun Negara soal harga barang. Tujuan perpaduan terlepas daripada catatan.\"}], \"aftermath\": \"Tujuan Rukun Negara dicatat dengan salah. Rakyat bertanya semula dan kekeliruan berlarutan.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Mengukuhkan perpaduan dan semangat kekitaan masyarakat berbilang kaum.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tunku! Kami semua berasa lega, bandar, kampung dan ladang sekali gus!\"}, {\"text\": \"Memisahkan setiap kaum di kawasan masing-masing supaya tidak bertembung.\", \"isCorrect\": false, \"reaction\": \"Tunku, memisahkan lagi? Itu yang menambah jurang. Tauke Lim mengerutkan dahi dan menggeleng.\"}, {\"text\": \"Menaikkan harga barang di bandar supaya semua kaum mendapat harga seragam.\", \"isCorrect\": false, \"reaction\": \"Haha, Tunku, harga barang bukan soal perpaduan. Pak Tani pun tergelak dan berhenti mendengar.\"}], \"clue\": \"Tujuan utama berkait dengan perpaduan dan semangat kekitaan dalam kalangan rakyat berbilang kaum.\"}]}'),
(315, 'e3_n3_s3', 'Bantu Murid Mengingat Matlamat', 'Bantu Tunku menjawab soalan murid tentang matlamat Rukun Negara yang menghargai tradisi kebudayaan.', '3', 'Mengenal pasti lima matlamat Rukun Negara.', '{\"prompt\": \"Murid bertanya kepada kau: apakah dua matlamat Rukun Negara yang berkaitan dengan kehidupan yang adil bersama dan kemajuan masa depan?\", \"options\": [{\"text\": \"Masyarakat adil dengan kemakmuran dinikmati bersama, dan masyarakat progresif dengan sains dan teknologi moden.\", \"isCorrect\": true}, {\"text\": \"Kemakmuran dinikmati satu kaum sahaja, dan masyarakat tradisional yang menolak penggunaan teknologi.\", \"isCorrect\": false, \"consequence\": \"Murid itu menulis jawapan yang tersasar. Lima matlamat tidak lagi lengkap dalam buku mereka.\"}, {\"text\": \"Memelihara demokrasi sahaja, dan masyarakat yang menolak sains serta teknologi moden sepenuhnya.\", \"isCorrect\": false, \"consequence\": \"Murid itu menyebarkan jawapan yang bercanggah. Matlamat kemajuan dan keadilan hilang daripada catatan mereka.\"}], \"aftermath\": \"Dua matlamat dijawab dengan salah. Murid-murid pulang dengan senarai yang tidak lengkap.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Cara yang liberal terhadap tradisi kebudayaan yang kaya dan pelbagai.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tunku! Singa itu menari lebih galak. Kami semua bertepuk tangan!\"}, {\"text\": \"Memelihara satu cara hidup demokrasi.\", \"isCorrect\": false, \"reaction\": \"Tunku, demokrasi tentang cara kita memerintah dan memilih, bukan tentang tarian singa. Murid-murid tertawa kecil.\"}, {\"text\": \"Membina masyarakat progresif yang menggunakan sains dan teknologi moden.\", \"isCorrect\": false, \"reaction\": \"Tunku, itu tentang kemajuan. Tarian dan muzik tradisional ialah soal warisan kebudayaan.\"}], \"clue\": \"Tarian singa dan muzik ialah sebahagian daripada tradisi kebudayaan yang kaya dan pelbagai.\"}]}'),
(316, 'e3_n3_s4', 'Nyahkod Petikan Ikrar', 'Baca petikan ikrar yang separuh pudar dan tentukan siapa Ketua Utama Negara dalam prinsip kedua.', '5', 'Memahami prinsip Kepercayaan kepada Tuhan dan Kesetiaan kepada Raja dan Negara.', '{\"clueText\": \"Petikan menulis: Prinsip pertama meminta agama sebagai pegangan utama dan menghormati amalan agama lain. Prinsip kedua meminta setiap warganegara memberi sepenuh taat setia kepada Duli Yang Maha Mulia Seri Paduka Baginda sebagai Ketua Utama Negara. Nama jawatan itu pudar.\", \"options\": [{\"text\": \"Yang di-Pertuan Agong.\", \"isCorrect\": true}, {\"text\": \"Perdana Menteri.\", \"isCorrect\": false, \"consequence\": \"Petikan dicetak dengan jawatan yang salah. Rakyat menyangka taat setia diberikan kepada Perdana Menteri.\"}, {\"text\": \"Ketua kaum masing-masing.\", \"isCorrect\": false, \"consequence\": \"Petikan itu dicetak dengan maksud yang salah. Rakyat menyangka setiap kaum berikrar kepada ketuanya sahaja.\"}], \"aftermath\": \"Ketua Utama Negara disalah baca. Ikrar dicetak dengan maksud yang tersasar.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Yang di-Pertuan Agong ialah Ketua Utama Negara.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tunku! Petikan itu bersinar kembali. Semua orang berdiri tegak!\"}, {\"text\": \"Perdana Menteri ialah Ketua Utama Negara.\", \"isCorrect\": false, \"reaction\": \"Eh, Tunku, itu tidak betul. Ketua Utama Negara dalam prinsip ini ialah Yang di-Pertuan Agong.\"}, {\"text\": \"Ketua setiap kaum ialah Ketua Utama Negara.\", \"isCorrect\": false, \"reaction\": \"Tunku, ketua kaum bukan Ketua Utama Negara. Salah itu hampir dicatat dalam buku sekolah.\"}], \"clue\": \"Prinsip kedua menyebut taat setia kepada Yang di-Pertuan Agong sebagai Ketua Utama Negara.\"}]}'),
(317, 'e3_n3_s5', 'Cari Bukti Tiga Prinsip Terakhir', 'Cari objek pada gambar yang mewakili Keluhuran Perlembagaan, Kedaulatan Undang-undang serta Kesopanan dan Kesusilaan.', '2', 'Mengenal pasti maksud prinsip Keluhuran Perlembagaan, Kedaulatan Undang-undang serta Kesopanan dan Kesusilaan.', '{\"hotspots\":[{\"name\":\"Gulungan pada batu: Perlembagaan ialah undang-undang tertinggi negara\",\"top\":\"21.4%\",\"left\":\"65.6%\"},{\"name\":\"Papan Kedaulatan Undang-undang: hormati dan patuhi undang-undang\",\"top\":\"45.5%\",\"left\":\"25.9%\"},{\"name\":\"Menanam pokok bersama: bekerjasama dan saling memahami (kesopanan)\",\"top\":\"38%\",\"left\":\"42%\"},{\"name\":\"Membantu warga emas: nilai murni dan akhlak mulia\",\"top\":\"87.7%\",\"left\":\"17.4%\"}],\"bgImage\":\"../assets/gameAsset/background/prinsip_rukun_negara_.png\",\"aftermath\":\"Bukti tiga prinsip terlepas pandang. Dataran kembali sibuk tetapi tiada siapa yang mengingati maksudnya.\",\"turns\":[{\"after\":4,\"options\":[{\"text\":\"Saling memahami dan bekerjasama.\",\"isCorrect\":true,\"reaction\":\"Tepat, Tunku! Kami bergotong-royong dan dataran ini menjadi lebih ceria!\"},{\"text\":\"Bersaing menunjukkan siapa yang lebih berkuasa.\",\"isCorrect\":false,\"reaction\":\"Tunku, bersaing begitu menjadikan jiran bermasam muka. Dataran itu sunyi dan orang pulang.\"},{\"text\":\"Mengelak bertegur sapa dengan jiran berlainan kaum.\",\"isCorrect\":false,\"reaction\":\"Tunku, kalau mengelak, tiada kerjasama. Prinsip kelima menuntut saling memahami, bukan menjauhkan diri.\"}],\"clue\":\"Prinsip kelima menyebut masyarakat saling memahami dan bekerjasama.\"}]}'),
(318, 'e3_n3_s6', 'Padanan Enam Peranan dan Contoh', 'Padankan setiap peranan Rukun Negara dengan contoh yang betul dalam kehidupan.', '4', 'Mengenal pasti enam peranan Rukun Negara.', '{\"pairs\": [{\"text\": \"Meraikan kepelbagaian agama\", \"pair\": 1}, {\"text\": \"Rumah ibadat pelbagai agama dihormati bersama\", \"pair\": 1}, {\"text\": \"Membentuk masyarakat patriotik\", \"pair\": 2}, {\"text\": \"Rakyat mengibarkan bendera dengan bangga\", \"pair\": 2}, {\"text\": \"Memupuk hormat undang-undang\", \"pair\": 3}, {\"text\": \"Orang ramai mematuhi peraturan jalan raya\", \"pair\": 3}, {\"text\": \"Mengukuhkan perpaduan\", \"pair\": 4}, {\"text\": \"Jiran pelbagai kaum bergotong-royong\", \"pair\": 4}, {\"text\": \"Menerapkan nilai murni\", \"pair\": 5}, {\"text\": \"Anak muda membantu warga emas\", \"pair\": 5}, {\"text\": \"Membentuk jati diri\", \"pair\": 6}, {\"text\": \"Rakyat bangga dengan identiti bersama sebagai orang Malaysia\", \"pair\": 6}], \"aftermath\": \"Contoh dipadankan dengan salah. Murid-murid menyalin padanan yang tersasar dan guru terpaksa membetulkannya.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Mengukuhkan perpaduan masyarakat.\", \"isCorrect\": true, \"reaction\": \"Tepat, Tunku! Kami bergotong-royong dan taman jadi cantik. Bintang emas saya selamat!\"}, {\"text\": \"Memupuk sikap menghormati undang-undang.\", \"isCorrect\": false, \"reaction\": \"Tunku, itu tentang peraturan. Bergotong-royong bukan soal undang-undang, tapi soal bersatu.\"}, {\"text\": \"Membentuk jati diri masyarakat Malaysia.\", \"isCorrect\": false, \"reaction\": \"Tunku, itu tentang identiti. Contoh ini lebih jelas tentang perpaduan yang diperkukuh bersama.\"}], \"clue\": \"Bergotong-royong bersama jiran pelbagai kaum menunjukkan perpaduan yang diperkukuh.\"}]}'),
(401, 'e4_n1_s1', 'Bantu Pemuzik Menjawab Soalan Kaum', 'Bantu pemuzik menjawab soalan anak muda tentang kaum lain di Sabah dan Sarawak.', '3', 'Mengenal pasti kepelbagaian kaum di Malaysia.', '{\"prompt\": \"Linda bertanya kepada kau: yang manakah senarai kaum lain di Sabah dan kaum lain di Sarawak?\", \"options\": [{\"text\": \"Sabah: Murut, Rungus, Iranun dan Bajau. Sarawak: Melayu, Kenyah, Melanau dan Bidayuh.\", \"isCorrect\": true}, {\"text\": \"Sabah: Melayu, Kenyah, Melanau dan Bidayuh. Sarawak: Murut, Rungus, Iranun dan Bajau.\", \"isCorrect\": false, \"consequence\": \"Linda menulis senarai yang tertukar. Anak-anak muda menyalin dan mula percaya kaum Sabah dan Sarawak sama sahaja.\"}, {\"text\": \"Sabah: Iban, Sikh, Serani dan Chetti. Sarawak: Siam, Orang Asli, Baba dan Nyonya.\", \"isCorrect\": false, \"consequence\": \"Senarai itu bercampur aduk. Murid-murid keliru dan tidak lagi tahu kaum mana tinggal di mana.\"}], \"aftermath\": \"Senarai kaum tertukar. Anak-anak muda pulang dengan nama kaum yang tersalah tempat.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Murut, Rungus, Iranun dan Bajau.\", \"isCorrect\": true, \"reaction\": \"Tepat, pak cik! Linda bersorak dan Pak Bajau melambai dari belakang. Papan skor bersinar!\"}, {\"text\": \"Melayu, Kenyah, Melanau dan Bidayuh.\", \"isCorrect\": false, \"reaction\": \"Itu kaum lain di Sarawak, pak cik! Jenny ketawa dan Linda menggeleng. Sabah kena tunggu giliran.\"}, {\"text\": \"Iban, Sikh, Serani dan Chetti.\", \"isCorrect\": false, \"reaction\": \"Pak cik, mereka bukan kumpulan kaum lain di Sabah. Papan skor jadi kelam-kabut!\"}], \"clue\": \"Linda menyebut kaum lain di Sabah selepas Kadazandusun. Dengar semula empat nama yang dia sebut.\"}]}'),
(402, 'e4_n1_s2', 'Padanan Kaum dan Kegiatan Dahulu', 'Padankan setiap kaum dengan petempatan dan kegiatan ekonominya dahulu.', '4', 'Mengenal pasti petempatan dan kegiatan ekonomi kaum di Semenanjung dahulu.', '{\"pairs\": [{\"text\": \"Melayu\", \"pair\": 1}, {\"text\": \"Kampung, pesisir pantai dan sungai; petani, nelayan, peniaga kecil\", \"pair\": 1}, {\"text\": \"Cina\", \"pair\": 2}, {\"text\": \"Pekan dan bandar; pelombong dan peniaga\", \"pair\": 2}, {\"text\": \"India\", \"pair\": 3}, {\"text\": \"Ladang dan pinggir bandar; pekerja ladang dan pelabuhan\", \"pair\": 3}, {\"text\": \"Orang Asli\", \"pair\": 4}, {\"text\": \"Pedalaman; kraf tangan, berburu dan memungut hasil hutan\", \"pair\": 4}], \"aftermath\": \"Kegiatan kaum tertukar tempat. Rentak lagu kampung pun berantakan dan penonton bingung.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Orang Cina, sebagai pelombong dan peniaga.\", \"isCorrect\": true, \"reaction\": \"Tepat, pak cik! Ah Meng membunyikan loceng kedai. KLING-KLING!\"}, {\"text\": \"Orang Melayu, sebagai petani dan nelayan.\", \"isCorrect\": false, \"reaction\": \"Itu kerja orang Melayu di kampung dan pesisir, pak cik. Ah Meng mengaru kepala dan loceng kedai terdiam.\"}, {\"text\": \"Orang India, sebagai pekerja ladang.\", \"isCorrect\": false, \"reaction\": \"Itu tentang ladang dan pinggir bandar, pak cik. Bukan pekan, jadi jawapan itu tersasar.\"}], \"clue\": \"Pelombong dan peniaga banyak berada di pekan dan bandar.\"}]}'),
(403, 'e4_n1_s3', 'Nyahkod Nota Lama Sarawak', 'Baca nota lama dan tentukan kegiatan ekonomi kaum Melayu, Melanau dan Kedayan di pekan dan bandar Sarawak.', '5', 'Mengenal pasti petempatan dan ekonomi kaum di Sarawak dahulu serta kehidupan bersama kini.', '{\"clueText\": \"Nota lama menulis: Bidayuh, Kenyah dan Kelabit tinggal di pedalaman. Iban dan Bisaya tinggal di lembah sungai sebagai petani. Melayu, Melanau dan Kedayan tinggal di pekan dan bandar. Ekonomi mereka sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Pedagang, pembuat perahu dan pengusaha sagu.\", \"isCorrect\": true}, {\"text\": \"Menanam padi sawah dan padi bukit di pedalaman.\", \"isCorrect\": false, \"consequence\": \"Nota itu ditulis semula dengan maksud yang salah. Pembaca menyangka orang pekan dan bandar bertani padi bukit.\"}, {\"text\": \"Menoreh getah dan bekerja di pelabuhan di ladang.\", \"isCorrect\": false, \"consequence\": \"Catatan itu bercampur dengan kegiatan di Semenanjung. Pembaca keliru dengan sejarah ekonomi Sarawak.\"}], \"aftermath\": \"Nota lama disalah baca. Kegiatan kaum Sarawak dicatat dengan tersasar.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Pedagang, pembuat perahu dan pengusaha sagu.\", \"isCorrect\": true, \"reaction\": \"Tepat, pak cik! Perahu kita meluncur laju dan kami bersorak!\"}, {\"text\": \"Menanam padi sawah dan padi bukit.\", \"isCorrect\": false, \"reaction\": \"Itu kerja kaum di pedalaman, pak cik. Perahu kita tersangkut di pasir kerana jawapan itu.\"}, {\"text\": \"Pekerja ladang getah dan pekerja pelabuhan.\", \"isCorrect\": false, \"reaction\": \"Itu kerja di Semenanjung, pak cik. Apai ketawa dan Jenny menggeleng.\"}], \"clue\": \"Nota lama menyebut kaum Melayu, Melanau dan Kedayan berada di pekan dan bandar.\"}]}'),
(404, 'e4_n1_s4', 'Cari Bukti Pentas Lima Kaum', 'Cari alat muzik dan tarian bagi lima kaum pada gambar padang perayaan.', '2', 'Mengenal pasti alat muzik dan tarian tradisional kaum Melayu, Cina, India, Sarawak dan Sabah.', '{\"hotspots\":[{\"name\":\"Pentas Melayu: gambus dan angklung; tarian makyung dan zapin\",\"top\":\"25%\",\"left\":\"32%\"},{\"name\":\"Tarian singa: gendang dan bo; masyarakat Cina\",\"top\":\"22.6%\",\"left\":\"52.7%\"},{\"name\":\"Pentas India: veenai dan talam; tarian bharatanatyam\",\"top\":\"64.4%\",\"left\":\"32.8%\"},{\"name\":\"Tarian ngajat: sape dan engkerurai; masyarakat Sarawak\",\"top\":\"61%\",\"left\":\"62%\"},{\"name\":\"Tarian sumazau: kulintangan dan sompotan; masyarakat Sabah\",\"top\":\"51.6%\",\"left\":\"71.7%\"}],\"bgImage\":\"../assets/gameAsset/background/alat_muzik_dan_tarian_tradisional.png\",\"aftermath\":\"Alat muzik dan tarian bercampur antara pentas. Persembahan terhenti dan penonton pulang dengan salah faham.\",\"turns\":[{\"after\":4,\"options\":[{\"text\":\"Pentas kaum Sabah.\",\"isCorrect\":true,\"reaction\":\"Tepat, pak cik! Gong Sabah berbunyi dan penonton bertepuk tangan!\"},{\"text\":\"Pentas kaum Sarawak.\",\"isCorrect\":false,\"reaction\":\"Itu tarian ngajat, pak cik! Sumazau dari Sabah. Penari ngajat pun tercengang.\"},{\"text\":\"Pentas kaum Cina.\",\"isCorrect\":false,\"reaction\":\"Pak cik, tarian singa dari pentas Cina, bukan sumazau. Singa itu menggeleng-geleng kepala!\"}],\"clue\":\"Sumazau ialah tarian dari Sabah, bukan dari Sarawak.\"}]}'),
(405, 'e4_n1_s5', 'Padanan Tempat Permainan Tradisional', 'Padankan permainan tradisional dengan tempat ia dimainkan.', '4', 'Mengenal pasti permainan anjung, laman dan kawasan lapang.', '{\"pairs\": [{\"text\": \"Permainan anjung\", \"pair\": 1}, {\"text\": \"Congkak, batu seremban, go, yoyo cina, chaturangam, paramapadham\", \"pair\": 1}, {\"text\": \"Permainan laman\", \"pair\": 2}, {\"text\": \"Sepak raga, chap teh dan kabaddi\", \"pair\": 2}, {\"text\": \"Permainan kawasan lapang\", \"pair\": 3}, {\"text\": \"Wau, tibau, sepak manggis dan gasing\", \"pair\": 3}], \"aftermath\": \"Permainan dipadankan dengan tempat yang salah. Kanak-kanak bermain di tempat yang tidak sesuai dan pertandingan berhenti.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Kawasan lapang.\", \"isCorrect\": true, \"reaction\": \"Tepat, pak cik! Wau saya terbang tinggi dan kawan-kawan bersorak!\"}, {\"text\": \"Anjung rumah.\", \"isCorrect\": false, \"reaction\": \"Anjung untuk permainan papan dan batu, pak cik. Wau saya tersangkut di tiang rumah!\"}, {\"text\": \"Laman rumah sahaja.\", \"isCorrect\": false, \"reaction\": \"Laman untuk sepak raga dan chap teh, pak cik. Wau perlu ruang lebih luas.\"}], \"clue\": \"Wau perlu ruang luas dan angin kencang, bukan di anjung atau laman.\"}]}'),
(406, 'e4_n1_s6', 'Susun Tipu Helah Si Luncai', 'Susun peristiwa dalam cerita Si Luncai mengikut urutan yang betul.', '1', 'Memahami cerita rakyat Si Luncai, Legenda Santubong dan Legenda Nunuk Ragang.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"Dihukum raja\", \"text\": \"Si Luncai dijatuhi hukuman raja kerana mempermain-mainkan raja dan pembesar\", \"why\": \"Hukuman itu mencetuskan seluruh cerita.\"}, {\"id\": 2, \"year\": \"Dalam perahu\", \"text\": \"Si Luncai dimasukkan ke dalam guni dan perahu menuju ke tengah laut\", \"why\": \"Dalam guni, dia melihat labu air di dalam perahu.\"}, {\"id\": 3, \"year\": \"Menyanyi\", \"text\": \"Si Luncai menyanyi dan pesuruh raja ikut menyanyi sehingga leka\", \"why\": \"Kelekaan memberi peluang kepada Si Luncai.\"}, {\"id\": 4, \"year\": \"Tipu helah\", \"text\": \"Si Luncai mengisi labu ke dalam guni dan terjun berenang dengan labu air\", \"why\": \"Pesuruh raja kemudian mencampak guni itu tanpa menyedari dia selamat.\"}], \"aftermath\": \"Urutan cerita tertukar. Anak-anak mendengar cerita yang kelam-kabut dan kehilangan pengajaran akal yang bijak.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Keluar dari guni, isi labu dalam guni, lalu terjun berenang dengan labu air.\", \"isCorrect\": true, \"reaction\": \"Tepat! Aku menjadi pelari laut yang terbaik! Pesuruh raja pun campak guni berisi labu itu!\"}, {\"text\": \"Terus menanti pesuruh raja membuka guni dan melepaskan aku di tengah laut itu.\", \"isCorrect\": false, \"reaction\": \"Aduh, Luncai tak sabar menunggu! Pesuruh raja tak akan buka guni, mereka hanya mahu campakkan ke laut.\"}, {\"text\": \"Terjun ke laut dengan guni di belakang tanpa membawa sebarang labu air.\", \"isCorrect\": false, \"reaction\": \"Tanpa labu, Luncai tenggelam, pemuzik! Labu air itulah yang menyelamatkan aku.\"}], \"clue\": \"Luncai menipu pesuruh raja dengan mengisi labu ke dalam guni, kemudian terjun dengan labu air.\"}]}'),
(407, 'e4_n2_s1', 'Padanan Kad Kaum Nenek', 'Padankan setiap kumpulan kaum dengan senarai namanya.', '4', 'Mengenal pasti kepelbagaian kaum di Semenanjung, Sabah dan Sarawak.', '{\"pairs\": [{\"text\": \"Kaum utama Semenanjung\", \"pair\": 1}, {\"text\": \"Melayu, Cina, India, Siam dan Orang Asli\", \"pair\": 1}, {\"text\": \"Peranakan dan lain-lain\", \"pair\": 2}, {\"text\": \"Chetti, Baba dan Nyonya, Sikh dan Serani\", \"pair\": 2}, {\"text\": \"Kaum utama Sabah dan Sarawak\", \"pair\": 3}, {\"text\": \"Kadazandusun (Sabah) dan Iban (Sarawak)\", \"pair\": 3}, {\"text\": \"Kaum lain di Sabah\", \"pair\": 4}, {\"text\": \"Murut, Rungus, Iranun dan Bajau\", \"pair\": 4}, {\"text\": \"Kaum lain di Sarawak\", \"pair\": 5}, {\"text\": \"Melayu, Kenyah, Melanau dan Bidayuh\", \"pair\": 5}], \"aftermath\": \"Kad kaum tersalah laci. Cucu-cucu pulang dengan senarai yang bercampur dan jiran pun dikenali dengan nama salah.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Murut, Rungus, Iranun dan Bajau.\", \"isCorrect\": true, \"reaction\": \"Betul, nenek! Pak Bajau melambai dan cucu-cucu bersorak. Kad bertukar emas!\"}, {\"text\": \"Melayu, Kenyah, Melanau dan Bidayuh.\", \"isCorrect\": false, \"reaction\": \"Itu kaum lain di Sarawak, nenek! Kad itu berpatah balik ke laci Sarawak.\"}, {\"text\": \"Chetti, Baba dan Nyonya, Sikh dan Serani.\", \"isCorrect\": false, \"reaction\": \"Kaum itu di Semenanjung, nenek! Murid-murid tergelak sebab kad tersesat laci.\"}], \"clue\": \"Kaum lain di Sabah disebut Linda bersama Pak Bajau, selepas Kadazandusun.\"}]}'),
(408, 'e4_n2_s2', 'Nyahkod Nota Lama Semenanjung', 'Baca nota lama dan tentukan kegiatan ekonomi masyarakat India dahulu.', '5', 'Mengenal pasti petempatan dan kegiatan ekonomi Melayu, Cina, India dan Orang Asli dahulu.', '{\"clueText\": \"Nota lama menulis: Melayu di kampung dan pesisir (petani, nelayan). Cina di pekan dan bandar (pelombong, peniaga). Orang Asli di pedalaman. India di ladang dan pinggir bandar, tetapi kegiatan ekonominya sudah luntur dan hilang.\", \"options\": [{\"text\": \"Pekerja ladang, peniaga kecil-kecilan dan pekerja pelabuhan.\", \"isCorrect\": true}, {\"text\": \"Pelombong bijih timah dan peniaga di pekan dan bandar.\", \"isCorrect\": false, \"consequence\": \"Nota ditulis semula dengan kegiatan kaum Cina. Cucu-cucu menyangka orang India dahulu melombong di pekan.\"}, {\"text\": \"Berburu dan memungut hasil hutan di pedalaman jauh.\", \"isCorrect\": false, \"consequence\": \"Catatan itu bercampur dengan kegiatan Orang Asli. Cucu-cucu tidak lagi tahu apa kerja orang India di ladang.\"}], \"aftermath\": \"Nota lama disalah baca. Kegiatan ekonomi kaum ditulis pada tempat yang salah.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Pekerja ladang, peniaga kecil-kecilan dan pekerja pelabuhan.\", \"isCorrect\": true, \"reaction\": \"Tepat, nenek! Kavitha mengangguk. Nota lama bercahaya semula!\"}, {\"text\": \"Pelombong bijih dan peniaga di pekan dan bandar besar.\", \"isCorrect\": false, \"reaction\": \"Itu kerja orang Cina di bandar, nenek. Kavitha menggaru kepala dan nota lama terdiam.\"}, {\"text\": \"Kraf tangan, berburu dan memungut hasil di dalam hutan.\", \"isCorrect\": false, \"reaction\": \"Itu Orang Asli di pedalaman, nenek. Tok Batin ketawa dan Kavitha memuncung.\"}], \"clue\": \"Nota lama menyebut India berada di ladang dan pinggir bandar, jauh dari hutan dan pekan.\"}]}');
INSERT INTO `Quest` (`questID`, `sceneID`, `questName`, `instruction`, `questType`, `description`, `questContent`) VALUES
(409, 'e4_n2_s3', 'Bantu Nenek Menjawab Apai', 'Bantu nenek menjawab soalan Apai tentang kaum dan kerja di lembah sungai Sarawak.', '3', 'Mengenal pasti petempatan dan ekonomi kaum Sarawak dahulu serta kehidupan bersama kini.', '{\"prompt\": \"Apai bertanya kepada kau: kaum manakah tinggal di lembah sungai Sarawak, apa kerjanya, dan bagaimana keadaan rakyat kini?\", \"options\": [{\"text\": \"Iban dan Bisaya bertani; kini semua kaum bekerja bersama dan tinggal dalam satu kawasan perumahan.\", \"isCorrect\": true}, {\"text\": \"Bidayuh, Kenyah dan Kelabit bertani padi bukit; kini setiap kaum tinggal berasingan di pedalaman.\", \"isCorrect\": false, \"consequence\": \"Cucu-cucu menyangka kaum lembah sungai ialah kaum pedalaman. Mereka juga percaya kini semua masih berpisah.\"}, {\"text\": \"Melayu, Melanau dan Kedayan berdagang; kini setiap kaum tinggal di tempat berasingan.\", \"isCorrect\": false, \"consequence\": \"Cucu-cucu mencatat pekan dan bandar sebagai lembah sungai. Mereka kehilangan pelajaran tentang hidup bersama.\"}], \"aftermath\": \"Petempatan Sarawak tercatat salah. Cucu-cucu menyangka rakyat kini masih tinggal berasingan.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Iban dan Bisaya, sebagai petani.\", \"isCorrect\": true, \"reaction\": \"Tepat, nenek! Apai mengayuh dayung dan Jenny bertepuk tangan!\"}, {\"text\": \"Bidayuh, Kenyah dan Kelabit, sebagai pengutip hasil hutan.\", \"isCorrect\": false, \"reaction\": \"Itu di pedalaman, nenek. Apai ketawa dan dayungnya tersangkut di akar.\"}, {\"text\": \"Melayu, Melanau dan Kedayan, sebagai pembuat perahu.\", \"isCorrect\": false, \"reaction\": \"Itu di pekan dan bandar, nenek. Perahu Apai pun hampir berpusing!\"}], \"clue\": \"Lembah sungai ialah tempat Iban dan Bisaya, kerjanya bertani.\"}]}'),
(410, 'e4_n2_s4', 'Padanan Alat Muzik dan Tarian', 'Padankan setiap kaum dengan alat muzik dan tarian tradisionalnya.', '4', 'Mengenal pasti alat muzik dan tarian tradisional pelbagai kaum.', '{\"pairs\": [{\"text\": \"Melayu\", \"pair\": 1}, {\"text\": \"Angklung, gambus, nafiri, geduk; makyung dan zapin\", \"pair\": 1}, {\"text\": \"Cina\", \"pair\": 2}, {\"text\": \"Gendang, bo, liu qin, seruling; tarian singa\", \"pair\": 2}, {\"text\": \"India\", \"pair\": 3}, {\"text\": \"Pullangkulal, talam, mattalam, veenai; bharatanatyam\", \"pair\": 3}, {\"text\": \"Sarawak\", \"pair\": 4}, {\"text\": \"Sape, engkerurai, engkerumong; ngajat\", \"pair\": 4}, {\"text\": \"Sabah\", \"pair\": 5}, {\"text\": \"Kulintangan, sompotan, tongkungan, tontog; sumazau\", \"pair\": 5}], \"aftermath\": \"Alat muzik tertukar antara kaum. Pentas berbunyi sumbang dan penonton pulang dengan kenangan yang salah.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Tarian ngajat ialah tarian Sarawak, sumazau tarian Sabah.\", \"isCorrect\": true, \"reaction\": \"Tepat, nenek! Linda dan Jenny bertukar senyum, dua tarian di pentas masing-masing.\"}, {\"text\": \"Tarian sumazau ialah tarian Sarawak, ngajat tarian Sabah.\", \"isCorrect\": false, \"reaction\": \"Tertukar, nenek! Kedua-dua penari berhenti dan mengerut dahi.\"}, {\"text\": \"Tarian ngajat dan sumazau kedua-duanya tarian Cina.\", \"isCorrect\": false, \"reaction\": \"Itu tarian singa, nenek. Singa terkejut kerana dua penari datang ke pentas Cina!\"}], \"clue\": \"Ngajat bersama sape, sumazau bersama kulintangan. Satu Sarawak, satu Sabah.\"}]}'),
(411, 'e4_n2_s5', 'Cari Bukti Permainan Tiga Tempat', 'Cari permainan tradisional di anjung, laman dan kawasan lapang pada gambar.', '2', 'Mengenal pasti permainan tradisional anjung, laman dan kawasan lapang.', '{\"hotspots\":[{\"name\":\"Permainan anjung: congkak, batu seremban, go dan chaturangam\",\"top\":\"28%\",\"left\":\"15%\"},{\"name\":\"Permainan laman: sepak raga\",\"top\":\"47.8%\",\"left\":\"45.7%\"},{\"name\":\"Permainan lapang: wau di langit\",\"top\":\"7.2%\",\"left\":\"63.2%\"},{\"name\":\"Permainan lapang: gasing dan tibau\",\"top\":\"46.3%\",\"left\":\"62.7%\"},{\"name\":\"Permainan laman: chap teh dan kabaddi\",\"top\":\"61.4%\",\"left\":\"59.8%\"}],\"bgImage\":\"../assets/gameAsset/background/permainan_tradisional.png\",\"aftermath\":\"Permainan terletak di tempat salah. Kanak-kanak bermain tanpa ruang dan pertandingan terhenti.\",\"turns\":[{\"after\":4,\"options\":[{\"text\":\"Wau dan gasing, di kawasan lapang.\",\"isCorrect\":true,\"reaction\":\"Tepat, nenek! Wau naik tinggi dan gasing berpusing laju. Hebat!\"},{\"text\":\"Congkak dan batu seremban, di kawasan lapang.\",\"isCorrect\":false,\"reaction\":\"Itu permainan anjung, nenek! Congkak jatuh bergolek dari padang, haha!\"},{\"text\":\"Chap teh dan kabaddi, di anjung rumah.\",\"isCorrect\":false,\"reaction\":\"Itu permainan laman, nenek! Ah Meng menggeleng sebab kabaddi tak muat di anjung.\"}],\"clue\":\"Wau dan gasing perlukan ruang luas, jadi ia di kawasan lapang.\"}]}'),
(412, 'e4_n2_s6', 'Nyahkod Gulung Santubong', 'Baca gulung lama dan tentukan apa yang menyebabkan Gunung Santubong sumbing.', '5', 'Memahami cerita rakyat Si Luncai, Legenda Santubong dan Legenda Nunuk Ragang.', '{\"clueText\": \"Gulung lama menulis: Puteri Santubong menenun, Puteri Sejinjang menumbuk padi. Mereka bertelingkah kerana Putera Serapi. Satu daripada senjata mereka mengenai pipi Santubong dan gunung itu sumbing, tetapi namanya sudah luntur.\", \"options\": [{\"text\": \"Antan terkena pipi Santubong, lalu Gunung Santubong sumbing.\", \"isCorrect\": true}, {\"text\": \"Batang belidah terkena pipi Santubong, lalu Gunung Santubong sumbing.\", \"isCorrect\": false, \"consequence\": \"Gulung itu ditulis semula dengan senjata yang salah. Cucu-cucu menyangka batang belidah membuat gunung sumbing.\"}, {\"text\": \"Ayam gergasi merah mengibar sayap dan gunung itu sumbing.\", \"isCorrect\": false, \"consequence\": \"Cerita Nunuk Ragang bercampur dengan Santubong. Cucu-cucu keliru dengan asal usul gunung itu.\"}], \"aftermath\": \"Gulung cerita disalah baca. Asal usul gunung dan pulau bercampur dengan cerita lain.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Antan terkena pipi Santubong, lalu Gunung Santubong sumbing.\", \"isCorrect\": true, \"reaction\": \"Betul, nenek! Santubong tersenyum sumbing dan cucu-cucu bertepuk tangan.\"}, {\"text\": \"Batang belidah terkena pipi Santubong, lalu gunung itu sumbing.\", \"isCorrect\": false, \"reaction\": \"Batang belidah terkena kepala Sejinjang, nenek! Santubong menggeleng dan gulung pun bergoyang.\"}, {\"text\": \"Si Luncai terjun dari Gunung Santubong dengan labu-labunya.\", \"isCorrect\": false, \"reaction\": \"Itu bukan cerita Santubong, nenek! Si Luncai ketawa dari gulung sebelah.\"}], \"clue\": \"Antan dan batang belidah mengenai dua orang berbeza. Gunung sumbing berpunca daripada pipi Santubong.\"}]}'),
(413, 'e4_n3_s1', 'Nyahkod Surat Pendaftaran Gelanggang', 'Baca surat lama dan tentukan kaum utama Sabah dan Sarawak yang dinyatakan.', '5', 'Mengenal pasti kepelbagaian kaum di Malaysia.', '{\"clueText\": \"Surat lama menulis: Semenanjung ada Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh dan Serani. Kaum utama Sabah dan Sarawak sudah luntur dan tidak kelihatan, tetapi kaum lain di Sabah dan Sarawak masih tertulis.\", \"options\": [{\"text\": \"Kadazandusun di Sabah dan Iban di Sarawak.\", \"isCorrect\": true}, {\"text\": \"Murut dan Rungus di Sarawak, Kenyah dan Melanau di Sabah.\", \"isCorrect\": false, \"consequence\": \"Surat itu ditulis semula dengan kaum bertukar negeri. Pemain pulang dengan peta kaum yang tersalah.\"}, {\"text\": \"Chetti dan Serani di Sabah, Sikh dan Siam di Sarawak.\", \"isCorrect\": false, \"consequence\": \"Kaum Semenanjung tersalah letak ke Sabah dan Sarawak. Pendaftaran menjadi kelam-kabut.\"}], \"aftermath\": \"Surat pendaftaran disalah baca. Pemain tersalah menyebut kaum Sabah dan Sarawak.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Kadazandusun di Sabah dan Iban di Sarawak.\", \"isCorrect\": true, \"reaction\": \"Tepat, tok! Pak Bajau dan Apai bertepuk tangan serentak. Pasukan didaftar!\"}, {\"text\": \"Siam dan Sikh di Sabah dan Sarawak.\", \"isCorrect\": false, \"reaction\": \"Mereka di Semenanjung, tok! Borang pun dikoyak kerana tersalah daftar.\"}, {\"text\": \"Chetti dan Serani di Sabah dan Sarawak.\", \"isCorrect\": false, \"reaction\": \"Mereka di Semenanjung juga, tok! Pasukan diminta mendaftar semula.\"}], \"clue\": \"Surat lama menyebut Kadazandusun di Sabah dan Iban di Sarawak sebagai kaum utama.\"}]}'),
(414, 'e4_n3_s2', 'Kuiz Gelanggang Petempatan Dahulu', 'Bantu tok menjawab kuiz tentang petempatan dan kerja kaum di Semenanjung dahulu.', '3', 'Mengenal pasti petempatan dan ekonomi kaum di Semenanjung dahulu.', '{\"prompt\": \"Kuiz gelanggang bertanya kepada kau: padankan kaum dengan petempatan dan kerjanya dahulu. Yang manakah paling betul?\", \"options\": [{\"text\": \"Cina di pekan dan bandar sebagai pelombong dan peniaga; India di ladang dan pinggir bandar.\", \"isCorrect\": true}, {\"text\": \"Cina di kampung sebagai nelayan dan petani; India di pedalaman sebagai pemburu hutan.\", \"isCorrect\": false, \"consequence\": \"Pasukan menjawab dengan tempat dan kerja tertukar. Penonton keliru dan skor pasukan jatuh.\"}, {\"text\": \"Orang Asli di pekan sebagai peniaga kecil; Melayu di ladang sebagai pekerja pelabuhan dan kedai.\", \"isCorrect\": false, \"consequence\": \"Jawapan bercampur aduk antara kaum. Pemain pulang dengan sejarah yang salah.\"}], \"aftermath\": \"Kuiz dijawab salah. Pemain keliru tentang petempatan dan kerja setiap kaum.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Orang Asli, dengan kraf tangan, berburu dan hasil hutan.\", \"isCorrect\": true, \"reaction\": \"Tepat, tok! Tok Batin mengangkat tangan dan gelanggang bergema dengan sorakan!\"}, {\"text\": \"Orang Cina, sebagai pelombong dan peniaga di bandar.\", \"isCorrect\": false, \"reaction\": \"Itu di pekan dan bandar, tok! Ah Meng ketawa sambil menggeleng.\"}, {\"text\": \"Orang Melayu, sebagai petani dan nelayan di pantai.\", \"isCorrect\": false, \"reaction\": \"Itu di kampung dan pesisir, tok! Aishah menggaru kepala sambil tersenyum.\"}], \"clue\": \"Pedalaman ialah rumah Orang Asli, dengan hutan sebagai sumber hidup.\"}]}'),
(415, 'e4_n3_s3', 'Susun Garis Masa Kaum Sarawak', 'Susun kad garis masa kaum Sarawak daripada zaman dahulu hingga kini.', '1', 'Mengenal pasti petempatan dan ekonomi kaum Sarawak dahulu serta kehidupan bersama kini.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"Zaman dahulu\", \"text\": \"Bidayuh, Kenyah, Kelabit di pedalaman; Iban dan Bisaya di lembah sungai; Melayu, Melanau, Kedayan di pekan dan bandar\", \"why\": \"Setiap kaum menetap di tempat dan kerja sendiri.\"}, {\"id\": 2, \"year\": \"Merdeka dan Malaysia\", \"text\": \"Selepas merdeka dan pembentukan Malaysia, pemimpin bekerja keras dan rakyat bertoleransi\", \"why\": \"Kerja keras pemimpin dan toleransi menyatukan rakyat.\"}, {\"id\": 3, \"year\": \"Kini\", \"text\": \"Rakyat bekerja bersama dan tinggal dalam satu kawasan perumahan\", \"why\": \"Hasilnya, pelbagai kaum hidup sebagai jiran.\"}], \"aftermath\": \"Garis masa kaum Sarawak tertukar. Pemain menyangka kaum hidup bersama sebelum merdeka.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Dahulu mengikut petempatan, kemudian merdeka dan Malaysia, akhirnya hidup bersama.\", \"isCorrect\": true, \"reaction\": \"Tepat, tok! Jenny menyusun kad satu persatu dan Apai bertepuk tangan!\"}, {\"text\": \"Hidup bersama dahulu, baru kemudian kembali kepada petempatan berasingan semula.\", \"isCorrect\": false, \"reaction\": \"Terbalik, tok! Kad garis masa pun berselerak ditiup angin sungai.\"}, {\"text\": \"Merdeka dan Malaysia dahulu, kemudian kembali kepada petempatan lama semula.\", \"isCorrect\": false, \"reaction\": \"Petempatan lama datang dahulu, tok! Jenny menggeleng dan Apai ketawa.\"}], \"clue\": \"Garis masa bermula dengan petempatan lama, kemudian merdeka dan Malaysia, kemudian hidup bersama kini.\"}]}'),
(416, 'e4_n3_s4', 'Pengadil Pentas Lima Kaum', 'Pilih padanan alat muzik dan tarian yang betul bagi setiap pasukan.', '3', 'Mengenal pasti alat muzik dan tarian tradisional pelbagai kaum.', '{\"prompt\": \"Pengadil pentas bertanya kepada kau: padanan manakah yang betul antara kaum, alat muzik dan tariannya?\", \"options\": [{\"text\": \"Sarawak: sape dan ngajat; Sabah: kulintangan dan sumazau; India: veenai dan bharatanatyam.\", \"isCorrect\": true}, {\"text\": \"Sarawak: kulintangan dan sumazau; Sabah: sape dan ngajat; India: gambus dan zapin.\", \"isCorrect\": false, \"consequence\": \"Pentas tertukar. Penari sumazau berdiri di pentas ngajat dan penonton keliru dengan bunyi alat.\"}, {\"text\": \"Cina: gambus dan zapin; Melayu: gendang dan tarian singa; India: sape dan ngajat.\", \"isCorrect\": false, \"consequence\": \"Alat muzik bertukar antara kaum. Muzik jadi sumbang dan pasukan hilang mata.\"}], \"aftermath\": \"Padanan alat muzik dan tarian tertukar. Pentas berbunyi sumbang dan penonton keliru.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Sabah.\", \"isCorrect\": true, \"reaction\": \"Tepat, tok! Linda melompat gembira dan gong Sabah berdentum!\"}, {\"text\": \"Sarawak.\", \"isCorrect\": false, \"reaction\": \"Sumazau bukan Sarawak, tok! Penari ngajat pun menoleh hairan.\"}, {\"text\": \"Cina.\", \"isCorrect\": false, \"reaction\": \"Tarian Cina ialah tarian singa, tok! Singa itu menggeleng kepala, hehe.\"}], \"clue\": \"Sumazau dimainkan dengan kulintangan dan sompotan di Sabah.\"}]}'),
(417, 'e4_n3_s5', 'Nyahkod Papan Skor Permainan', 'Baca papan skor lama dan tentukan permainan di kawasan lapang.', '5', 'Mengenal pasti permainan tradisional anjung, laman dan kawasan lapang.', '{\"clueText\": \"Papan skor lama menulis: anjung dan laman ada senarai sendiri. Permainan di kawasan lapang sudah luntur, tetapi ia melibatkan angin, tali dan putaran di tanah luas.\", \"options\": [{\"text\": \"Wau, tibau, sepak manggis dan gasing.\", \"isCorrect\": true}, {\"text\": \"Congkak, batu seremban, go dan yoyo cina.\", \"isCorrect\": false, \"consequence\": \"Papan skor menyalin senarai anjung. Kanak-kanak bermain congkak di tengah padang yang luas.\"}, {\"text\": \"Sepak raga, chap teh dan kabaddi.\", \"isCorrect\": false, \"consequence\": \"Papan skor menyalin senarai laman. Kanak-kanak berkumpul di laman sempit dan padang terbiar.\"}], \"aftermath\": \"Papan skor disalah baca. Kanak-kanak bermain di tempat yang tidak sesuai.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Wau, tibau, sepak manggis dan gasing.\", \"isCorrect\": true, \"reaction\": \"Tepat, tok! Wau naik ke langit dan gasing menari di tanah!\"}, {\"text\": \"Congkak, batu seremban, go dan yoyo cina.\", \"isCorrect\": false, \"reaction\": \"Itu permainan anjung, tok! Congkak pun malu kerana disuruh ke padang.\"}, {\"text\": \"Sepak raga, chap teh dan kabaddi.\", \"isCorrect\": false, \"reaction\": \"Itu permainan laman, tok! Ah Meng ketawa sambil menyepak raga ke langit.\"}], \"clue\": \"Papan skor menyebut wau dan gasing ialah permainan yang memerlukan padang luas.\"}]}'),
(418, 'e4_n3_s6', 'Cari Bukti Legenda Nunuk Ragang', 'Cari bukti legenda Nunuk Ragang pada gambar gelanggang cerita.', '2', 'Memahami cerita rakyat Si Luncai, Legenda Santubong dan Legenda Nunuk Ragang.', '{\"hotspots\":[{\"name\":\"Pohon nunuk besar tempat penduduk Sungai Liwagu berehat\",\"top\":\"52.5%\",\"left\":\"40.1%\"},{\"name\":\"Rakit di sungai: petempatan awal penduduk di Tambunan dan Ranau\",\"top\":\"80.4%\",\"left\":\"86.7%\"},{\"name\":\"Ayam gergasi merah bertaji emas yang mengibar sayap\",\"top\":\"35.5%\",\"left\":\"46.6%\"}],\"bgImage\":\"../assets/gameAsset/background/nunuk_ragang.png\",\"aftermath\":\"Bukti legenda tersalah cari. Pemain mencampurkan Nunuk Ragang dengan cerita Si Luncai dan Santubong.\",\"turns\":[{\"after\":6,\"options\":[{\"text\":\"Ayam gergasi merah bertaji emas membawa penduduk terbang.\",\"isCorrect\":true,\"reaction\":\"Tepat, tok! Linda menunjuk ke langit dan sayap ayam gergasi berkilau.\"},{\"text\":\"Puteri Santubong menenun di atas Gunung Santubong.\",\"isCorrect\":false,\"reaction\":\"Itu cerita Santubong, tok! Puteri itu melambai dari gambar sebelah.\"},{\"text\":\"Si Luncai terjun ke sungai Liwagu dengan labu air.\",\"isCorrect\":false,\"reaction\":\"Itu bukan Nunuk Ragang, tok! Si Luncai ketawa terbahak-bahak.\"}],\"clue\":\"Nunuk Ragang ialah legenda ayam gergasi merah yang membawa penduduk Sungai Liwagu terbang.\"}]}'),
(501, 'e5_n1_s1', 'Misi Kenal Tujuh Wakil', 'Bantu murid menyenaraikan semua agama dan ajaran yang diwakili di Taman Tujuh Pintu.', '3', 'Mengenal pasti agama dan kepercayaan utama di Malaysia.', '{\"prompt\": \"Seorang murid menahan kau dan bertanya: yang manakah senarai lengkap agama dan ajaran di Taman Tujuh Pintu?\", \"options\": [{\"text\": \"Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Tao dan Ajaran Konfusius.\", \"isCorrect\": true}, {\"text\": \"Islam, Kristian, Buddha, Hindu dan Sikh sahaja, tanpa Ajaran Tao dan Ajaran Konfusius.\", \"isCorrect\": false, \"consequence\": \"Murid itu mencatat lima sahaja. Kenny terkilan kerana dua ajarannya tidak disebut dan dilupakan.\"}, {\"text\": \"Islam, Kristian, Buddha, Hindu, Ajaran Tao dan Ajaran Konfusius, tanpa Sikh.\", \"isCorrect\": false, \"consequence\": \"Murid itu mencatat enam sahaja. Harjit terdiam kerana agamanya tertinggal daripada senarai.\"}], \"aftermath\": \"Senarai agama tidak lengkap. Murid-murid pulang dengan nota yang meninggalkan beberapa agama.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Ajaran Tao dan Ajaran Konfusius.\", \"isCorrect\": true, \"reaction\": \"Tepat, pengkaji! Kenny menepuk dada dan semua wakil bertepuk tangan. Satu mata untuk kau!\"}, {\"text\": \"Agama Buddha dan agama Hindu.\", \"isCorrect\": false, \"reaction\": \"Itu wakil Mei Ling dan Kavitha, pengkaji! Kenny ketawa dan menunjuk ke pintunya sendiri.\"}, {\"text\": \"Agama Islam dan agama Kristian.\", \"isCorrect\": false, \"reaction\": \"Itu wakil Aishah dan Daniel! Kenny menggeleng-geleng sambil tersenyum.\"}], \"clue\": \"Kenny menyebut dua ajaran itu pada akhir senarai, selepas Sikh.\"}]}'),
(502, 'e5_n1_s2', 'Misi Kamera: Rumah Ibadat', 'Cari rumah ibadat bagi lima kumpulan agama pada gambar dan kenal pasti namanya.', '2', 'Mengenal pasti rumah ibadat pelbagai agama di Malaysia.', '{\"hotspots\":[{\"name\":\"Masjid: rumah ibadat bagi penganut Islam\",\"top\":\"66.3%\",\"left\":\"17.2%\"},{\"name\":\"Gereja: rumah ibadat bagi penganut Kristian\",\"top\":\"62.4%\",\"left\":\"33%\"},{\"name\":\"Tokong: rumah ibadat Konfusius dan Tao, juga Buddha\",\"top\":\"60.4%\",\"left\":\"50.8%\"},{\"name\":\"Wat atau tokong: rumah ibadat bagi penganut Buddha\",\"top\":\"61.6%\",\"left\":\"61.7%\"},{\"name\":\"Kuil: rumah ibadat bagi penganut Hindu\",\"top\":\"62%\",\"left\":\"71.5%\"},{\"name\":\"Gurdwara: rumah ibadat bagi penganut Sikh\",\"top\":\"66.3%\",\"left\":\"88%\"}],\"bgImage\":\"../assets/gameAsset/background/tempat_beribadat_berdekat.png\",\"aftermath\":\"Rumah ibadat tersalah catat. Murid-murid pulang dengan gambar yang berlabel salah.\",\"turns\":[{\"after\":6,\"options\":[{\"text\":\"Gurdwara Sikh.\",\"isCorrect\":true,\"reaction\":\"Tepat, pengkaji! Murid itu menjerit gembira dan mengambil gambar gurdwara itu.\"},{\"text\":\"Gereja Kristian.\",\"isCorrect\":false,\"reaction\":\"Gereja itu milik Kristian, pengkaji! Daniel melambai dari menaranya dan ketawa.\"},{\"text\":\"Kuil Hindu.\",\"isCorrect\":false,\"reaction\":\"Kuil itu untuk Hindu, pengkaji! Kavitha menggeleng sambil tersenyum.\"}],\"clue\":\"Sikh mempunyai rumah ibadat bernama gurdwara, dengan kubah emas dan bangunan putih.\"}]}'),
(503, 'e5_n1_s3', 'Nyahkod Lampiran Perkara 3', 'Baca lampiran Perlembagaan yang luntur dan tentukan siapa Ketua Agama Islam di negeri tanpa Raja.', '5', 'Memahami kedudukan agama Islam dalam Perlembagaan Perkara 3.', '{\"clueText\": \"Lampiran lama menulis: Perkara 3(1): Islam agama Persekutuan, agama lain aman dan damai. Perkara 3(2): Raja ialah Ketua Agama Islam di negeri beraja. Perkara 3(3): bagi Melaka, Pulau Pinang, Sabah dan Sarawak, pemegang kedudukan itu sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Yang di-Pertuan Agong, bagi Melaka, Pulau Pinang, Sabah dan Sarawak.\", \"isCorrect\": true}, {\"text\": \"Raja setiap negeri itu, bagi Melaka, Pulau Pinang, Sabah dan Sarawak.\", \"isCorrect\": false, \"consequence\": \"Lampiran itu dibaca salah. Murid menyangka negeri tanpa Raja pun mempunyai Raja sebagai Ketua Agama Islam.\"}, {\"text\": \"Yang di-Pertua Negeri sebagai Ketua Agama Islam, bagi empat negeri itu.\", \"isCorrect\": false, \"consequence\": \"Lampiran itu disalah faham. Murid menyangka ketua negeri dilantik ialah Ketua Agama Islam di situ.\"}], \"aftermath\": \"Lampiran Perlembagaan disalah baca. Murid pulang dengan fahaman salah tentang Ketua Agama Islam.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Yang di-Pertuan Agong.\", \"isCorrect\": true, \"reaction\": \"Tepat, pengkaji! Perkara 3(3) menyatakannya. Murid itu menulis laju-laju dalam buku.\"}, {\"text\": \"Raja negeri itu.\", \"isCorrect\": false, \"reaction\": \"Sabah tiada Raja, pengkaji! Murid itu mengerut dahi dan mencoret jawapannya.\"}, {\"text\": \"Yang di-Pertua Negeri.\", \"isCorrect\": false, \"reaction\": \"Yang di-Pertua Negeri ialah ketua negeri, bukan Ketua Agama Islam di Sabah, pengkaji. Cuba lagi!\"}], \"clue\": \"Perkara 3(3) menyebut Melaka, Pulau Pinang, Sabah dan Sarawak, negeri tanpa Raja.\"}]}'),
(504, 'e5_n1_s4', 'Padanan Kepercayaan Orang Asli', 'Padankan setiap suku Orang Asli dengan kepercayaan atau upacaranya.', '4', 'Mengenal pasti kepercayaan masyarakat Orang Asli di Semenanjung.', '{\"pairs\": [{\"text\": \"Suku Mah Meri\", \"pair\": 1}, {\"text\": \"Upacara Puja Pantai untuk perlindungan daripada semangat laut\", \"pair\": 1}, {\"text\": \"Kepercayaan tentang penyakit\", \"pair\": 2}, {\"text\": \"Disebabkan kuasa jahat\", \"pair\": 2}, {\"text\": \"Suku Temiar dan Semai\", \"pair\": 3}, {\"text\": \"Upacara ritual untuk menghalau kuasa jahat\", \"pair\": 3}], \"aftermath\": \"Kepercayaan Orang Asli tersalah padan. Pak Mah Meri dan Tok Batin terkilan melihat catatan itu.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Memohon perlindungan dan pengampunan daripada semangat laut.\", \"isCorrect\": true, \"reaction\": \"Betul, pengkaji! Ombak pun macam bertepuk tangan. Pak Mah Meri tersenyum lebar.\"}, {\"text\": \"Menghalau kuasa jahat daripada badan orang yang sedang sakit.\", \"isCorrect\": false, \"reaction\": \"Itu tujuan upacara ritual Temiar dan Semai, pengkaji. Puja Pantai lain tujuannya!\"}, {\"text\": \"Meraikan musim padi di bukit bersama keluarga seluruh kampung.\", \"isCorrect\": false, \"reaction\": \"Padi bukit bukan tentang Puja Pantai, pengkaji. Pak Mah Meri ketawa.\"}], \"clue\": \"Puja Pantai diadakan di tepi laut, untuk semangat laut.\"}]}'),
(505, 'e5_n1_s5', 'Padanan Iban dan Kadazandusun', 'Padankan setiap kepercayaan atau upacara dengan masyarakat dan tokoh yang betul.', '4', 'Mengenal pasti kepercayaan masyarakat Iban dan Kadazandusun.', '{\"pairs\": [{\"text\": \"Iban: Petara\", \"pair\": 1}, {\"text\": \"Dewa yang menyampaikan petanda melalui mimpi dan bayangan\", \"pair\": 1}, {\"text\": \"Iban: Miring\", \"pair\": 2}, {\"text\": \"Upacara dimulai dengan jampi mentera oleh Lemambang\", \"pair\": 2}, {\"text\": \"Kadazandusun: Kinorohingan\", \"pair\": 3}, {\"text\": \"Tuhan untuk meminta sesuatu\", \"pair\": 3}, {\"text\": \"Kadazandusun: Magavau\", \"pair\": 4}, {\"text\": \"Upacara semangat padi yang diketuai Bobohizan\", \"pair\": 4}], \"aftermath\": \"Kepercayaan Iban dan Kadazandusun bertukar tempat. Apai dan Linda terpinga-pinga melihat nota kau.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Lemambang.\", \"isCorrect\": true, \"reaction\": \"Tepat, pengkaji! Apai Jelani menepuk lutut dan Linda mengangkat ibu jari.\"}, {\"text\": \"Bobohizan.\", \"isCorrect\": false, \"reaction\": \"Bobohizan ialah ketua bomoh Magavau Kadazandusun, pengkaji! Apai ketawa sambil menggeleng.\"}, {\"text\": \"Petara sendiri.\", \"isCorrect\": false, \"reaction\": \"Petara ialah dewa yang dipuja, pengkaji, bukan yang melakukan upacara. Cuba lagi!\"}], \"clue\": \"Penyair yang melakukan upacara Miring dikenali dengan satu gelaran khas.\"}]}'),
(506, 'e5_n1_s6', 'Nyahkod Nota Bisaya dan Bajau', 'Baca nota lama yang luntur dan tentukan upacara Bajau di Semporna.', '5', 'Mengenal pasti kepercayaan masyarakat Bisaya dan Bajau.', '{\"clueText\": \"Nota lama menulis: Bisaya membaca jampi mentera sebelum membuka kawasan pertanian baharu dan mengadakan Tamarok untuk pesakit. Bajau di Kota Belud mengadakan Ngeduang. Nama upacara Bajau di Semporna sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Mag\'ombo, menghargai warisan turun-temurun agar dirahmati.\", \"isCorrect\": true}, {\"text\": \"Ngeduang, menjamu tetamu sebagai sedekah selepas kematian.\", \"isCorrect\": false, \"consequence\": \"Nota itu disalin dengan nama upacara yang salah. Pembaca menyangka Ngeduang diamalkan di pantai timur.\"}, {\"text\": \"Tamarok, menghalau kuasa ghaib daripada badan pesakit.\", \"isCorrect\": false, \"consequence\": \"Nota itu bercampur dengan upacara Bisaya. Pembaca menyangka Bajau Semporna mengamalkan Tamarok.\"}], \"aftermath\": \"Nota tersalah baca. Upacara Bajau dan Bisaya bercampur dalam catatan kau.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Pantai barat Sabah, Kota Belud.\", \"isCorrect\": true, \"reaction\": \"Tepat, pengkaji! Pak Bajau mengangkat ibu jari dan petani Bisaya tersenyum.\"}, {\"text\": \"Pantai timur Sabah, Semporna.\", \"isCorrect\": false, \"reaction\": \"Itu tempat Mag\'ombo, pengkaji! Pak Bajau ketawa dan menunjuk ke arah timur.\"}, {\"text\": \"Kawasan pertanian Bisaya di Sarawak.\", \"isCorrect\": false, \"reaction\": \"Itu kawasan Tamarok, pengkaji! Pak Bajau menggeleng sambil tersenyum.\"}], \"clue\": \"Ngeduang diamalkan di pantai barat, manakala Mag\'ombo di pantai timur.\"}]}'),
(507, 'e5_n2_s1', 'Padanan Wakil dan Agama', 'Padankan setiap wakil dengan agama atau ajaran yang diwakilinya.', '4', 'Mengenal pasti tujuh agama dan ajaran di Malaysia.', '{\"pairs\": [{\"text\": \"Aishah\", \"pair\": 1}, {\"text\": \"Islam\", \"pair\": 1}, {\"text\": \"Daniel\", \"pair\": 2}, {\"text\": \"Kristian\", \"pair\": 2}, {\"text\": \"Mei Ling\", \"pair\": 3}, {\"text\": \"Buddha\", \"pair\": 3}, {\"text\": \"Kavitha\", \"pair\": 4}, {\"text\": \"Hindu\", \"pair\": 4}, {\"text\": \"Harjit\", \"pair\": 5}, {\"text\": \"Sikh\", \"pair\": 5}, {\"text\": \"Kenny\", \"pair\": 6}, {\"text\": \"Ajaran Tao dan Ajaran Konfusius\", \"pair\": 6}], \"aftermath\": \"Wakil tersalah padan. Persidangan terhenti sementara dan murid-murid keliru tentang agama setiap wakil.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Aishah wakil Islam dan Harjit wakil Sikh.\", \"isCorrect\": true, \"reaction\": \"Tepat, Bobohizan! Aishah dan Harjit mengangguk, dan loceng kecil berdenting riang.\"}, {\"text\": \"Daniel wakil Hindu dan Kavitha wakil Kristian.\", \"isCorrect\": false, \"reaction\": \"Tertukar, Bobohizan! Daniel dan Kavitha berpandangan lalu ketawa.\"}, {\"text\": \"Mei Ling wakil Sikh dan Harjit wakil Buddha.\", \"isCorrect\": false, \"reaction\": \"Silap, Bobohizan! Mei Ling dan Harjit saling menggeleng sambil tersenyum.\"}], \"clue\": \"Aishah memperkenalkan dirinya sebagai wakil Islam, Harjit sebagai wakil Sikh.\"}]}'),
(508, 'e5_n2_s2', 'Misi Bukit: Cari Rumah Ibadat', 'Cari rumah ibadat bagi enam kumpulan agama pada gambar.', '2', 'Mengenal pasti rumah ibadat pelbagai agama di Malaysia.', '{\"hotspots\":[{\"name\":\"Masjid: rumah ibadat bagi penganut Islam\",\"top\":\"21.9%\",\"left\":\"14.7%\"},{\"name\":\"Gereja: rumah ibadat bagi penganut Kristian\",\"top\":\"20.6%\",\"left\":\"40.1%\"},{\"name\":\"Kuil: rumah ibadat bagi penganut Hindu\",\"top\":\"28.2%\",\"left\":\"53.2%\"},{\"name\":\"Gurdwara: rumah ibadat bagi penganut Sikh\",\"top\":\"47%\",\"left\":\"12.9%\"},{\"name\":\"Wat atau tokong: rumah ibadat bagi penganut Buddha\",\"top\":\"52.9%\",\"left\":\"51.2%\"},{\"name\":\"Tokong: rumah ibadat bagi Ajaran Konfusius dan Ajaran Tao\",\"top\":\"65%\",\"left\":\"31%\"}],\"bgImage\":\"../assets/gameAsset/background/tempat_beribadat_semua.png\",\"aftermath\":\"Rumah ibadat tersalah tunjuk. Murid-murid turun bukit dengan nama bangunan yang bercampur.\",\"turns\":[{\"after\":6,\"options\":[{\"text\":\"Tokong, untuk Buddha, Ajaran Konfusius dan Ajaran Tao.\",\"isCorrect\":true,\"reaction\":\"Tepat, Bobohizan! Mei Ling bertepuk tangan dan lampu tokong pun menyala.\"},{\"text\":\"Gereja, untuk Buddha, Ajaran Konfusius dan Ajaran Tao.\",\"isCorrect\":false,\"reaction\":\"Gereja itu milik Kristian, Bobohizan! Daniel melambai sambil ketawa.\"},{\"text\":\"Kuil, untuk Buddha, Ajaran Konfusius dan Ajaran Tao.\",\"isCorrect\":false,\"reaction\":\"Kuil itu untuk Hindu, Bobohizan! Kavitha menggeleng sambil tersenyum.\"}],\"clue\":\"Mei Ling berkata tokong digunakan oleh tiga kumpulan: Buddha, Konfusius dan Tao.\"}]}'),
(509, 'e5_n2_s3', 'Soalan Mata Penentu Perlembagaan', 'Bantu murid memahami Perkara 3 dengan menjawab soalan tentang Ketua Agama Islam.', '3', 'Memahami kedudukan agama Islam dalam Perlembagaan Perkara 3.', '{\"prompt\": \"Seorang murid menahan kau dan bertanya: yang manakah pernyataan Perkara 3 yang betul?\", \"options\": [{\"text\": \"Islam agama Persekutuan; agama lain aman. Raja ketua agama di negeri beraja; Yang di-Pertuan Agong di negeri tanpa Raja dan Wilayah Persekutuan.\", \"isCorrect\": true}, {\"text\": \"Islam agama Persekutuan; agama lain dilarang. Raja ketua agama di semua negeri; Yang di-Pertuan Agong tiada peranan di mana-mana negeri.\", \"isCorrect\": false, \"consequence\": \"Murid menyangka agama lain dilarang dan Raja ketua di semua negeri. Cikgu terpaksa membetulkan dengan panjang lebar.\"}, {\"text\": \"Islam agama Persekutuan; agama lain aman. Yang di-Pertua Negeri ketua agama di Melaka, Pulau Pinang, Sabah dan Sarawak, dan Raja di Wilayah Persekutuan.\", \"isCorrect\": false, \"consequence\": \"Murid menyangka ketua negeri ialah Ketua Agama Islam. Jawapan itu tersebar dan menjadi kekeliruan.\"}], \"aftermath\": \"Perkara 3 disalah faham. Murid pulang dengan nota Perlembagaan yang tersasar.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Yang di-Pertuan Agong.\", \"isCorrect\": true, \"reaction\": \"Tepat, Bobohizan! Perkara 3(5) menyatakannya. Sultan mengangguk dengan senyuman.\"}, {\"text\": \"Sultan Selangor.\", \"isCorrect\": false, \"reaction\": \"Bukan, Bobohizan! Kuala Lumpur, Labuan dan Putrajaya di bawah Yang di-Pertuan Agong. Dewan pun berbisik.\"}, {\"text\": \"Yang di-Pertua Negeri.\", \"isCorrect\": false, \"reaction\": \"Bukan, Bobohizan. Yang di-Pertua Negeri ialah ketua negeri tanpa Raja, bukan Ketua Agama Islam Wilayah Persekutuan.\"}], \"clue\": \"Perkara 3(5) menyebut Kuala Lumpur, Labuan dan Putrajaya, dan ketuanya orang yang sama dengan Perkara 3(3).\"}]}'),
(510, 'e5_n2_s4', 'Nyahkod Catatan Orang Asli', 'Baca catatan lama dan tentukan upacara suku Temiar dan Semai.', '5', 'Mengenal pasti kepercayaan masyarakat Orang Asli di Semenanjung.', '{\"clueText\": \"Catatan lama menulis: suku Mah Meri mengadakan Puja Pantai untuk perlindungan dan pengampunan daripada semangat laut. Orang Asli percaya penyakit disebabkan kuasa jahat. Upacara suku Temiar dan Semai sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Upacara ritual untuk menghalau kuasa jahat.\", \"isCorrect\": true}, {\"text\": \"Upacara Puja Pantai untuk meminta perlindungan daripada semangat laut.\", \"isCorrect\": false, \"consequence\": \"Catatan itu bercampur dengan upacara Mah Meri. Pembaca menyangka Temiar dan Semai mengadakan Puja Pantai.\"}, {\"text\": \"Upacara Miring yang dimulakan dengan jampi mentera oleh Lemambang.\", \"isCorrect\": false, \"consequence\": \"Catatan itu bercampur dengan upacara Iban. Pembaca menyangka Temiar dan Semai mengadakan Miring.\"}], \"aftermath\": \"Catatan Orang Asli disalah baca. Upacara suku-suku itu bercampur dalam ingatan kau.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Disebabkan kuasa jahat.\", \"isCorrect\": true, \"reaction\": \"Tepat, Bobohizan! Tok Batin mengangguk dan murid itu mencatat dengan laju.\"}, {\"text\": \"Disebabkan semangat padi yang marah.\", \"isCorrect\": false, \"reaction\": \"Semangat padi itu kepercayaan Kadazandusun, Bobohizan! Tok Batin tersenyum dan menggeleng.\"}, {\"text\": \"Disebabkan Petara yang tidak berpuas hati.\", \"isCorrect\": false, \"reaction\": \"Petara itu dewa orang Iban, Bobohizan! Tok Batin menunjuk ke arah lain.\"}], \"clue\": \"Tok Batin Temiar menyebut punca penyakit sebelum bercakap tentang ritual.\"}]}'),
(511, 'e5_n2_s5', 'Soalan Sergahan di Sawah', 'Bantu Linda dan Apai Jelani menjawab soalan tentang kepercayaan Kadazandusun dan Iban.', '3', 'Mengenal pasti kepercayaan masyarakat Iban dan Kadazandusun.', '{\"prompt\": \"Seorang kanak-kanak menahan kau di batas sawah dan bertanya: yang manakah padanan kepercayaan yang betul?\", \"options\": [{\"text\": \"Kadazandusun: Kinorohingan dan Magavau bersama Bobohizan. Iban: Petara dan Miring bersama Lemambang.\", \"isCorrect\": true}, {\"text\": \"Kadazandusun: Petara dan Miring bersama Lemambang. Iban: Kinorohingan dan Magavau bersama Bobohizan.\", \"isCorrect\": false, \"consequence\": \"Kanak-kanak itu mencatat kepercayaan yang tertukar. Linda dan Apai tergelak melihat nota yang silap.\"}, {\"text\": \"Kadazandusun: Petara dan Magavau bersama Lemambang. Iban: Kinorohingan dan Miring bersama Bobohizan.\", \"isCorrect\": false, \"consequence\": \"Kanak-kanak itu mencatat kepercayaan yang bercampur-campur. Nota itu tidak lagi boleh dipercayai.\"}], \"aftermath\": \"Kepercayaan Iban dan Kadazandusun bercampur. Kanak-kanak pulang dengan nota yang tersilap.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Bobohizan, ketua bomoh.\", \"isCorrect\": true, \"reaction\": \"Tepat, Bobohizan! Linda bertepuk tangan dan sawah seakan beralun gembira.\"}, {\"text\": \"Lemambang, penyair Iban.\", \"isCorrect\": false, \"reaction\": \"Lemambang ialah penyair upacara Miring Iban, Bobohizan! Apai Jelani ketawa sambil mengangkat tangan.\"}, {\"text\": \"Petara, dewa yang dipuja.\", \"isCorrect\": false, \"reaction\": \"Petara ialah dewa Iban, Bobohizan, bukan yang memimpin upacara. Cuba lagi!\"}], \"clue\": \"Magavau diketuai oleh ketua bomoh yang dikenali dengan satu gelaran khas, gelaran kau sendiri.\"}]}'),
(512, 'e5_n2_s6', 'Padanan Upacara Bisaya dan Bajau', 'Padankan setiap upacara dengan masyarakat dan maksud atau tempatnya.', '4', 'Mengenal pasti kepercayaan masyarakat Bisaya dan Bajau.', '{\"pairs\": [{\"text\": \"Bisaya: jampi mentera\", \"pair\": 1}, {\"text\": \"Dibaca sebelum membuka kawasan pertanian baharu\", \"pair\": 1}, {\"text\": \"Bisaya: Tamarok\", \"pair\": 2}, {\"text\": \"Menghalau kuasa ghaib daripada badan pesakit\", \"pair\": 2}, {\"text\": \"Bajau: Ngeduang\", \"pair\": 3}, {\"text\": \"Menjamu tetamu sebagai sedekah di Kota Belud\", \"pair\": 3}, {\"text\": \"Bajau: Mag\'ombo\", \"pair\": 4}, {\"text\": \"Menghargai warisan turun-temurun di Semporna\", \"pair\": 4}], \"aftermath\": \"Upacara Bisaya dan Bajau tersalah padan. Jamuan terhenti dan tetamu saling berpandangan.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Ngeduang di Kota Belud, Mag\'ombo di Semporna.\", \"isCorrect\": true, \"reaction\": \"Tepat, Bobohizan! Pak Bajau mengangkat dulang tanda gembira dan jamuan pun bersambung.\"}, {\"text\": \"Ngeduang di Semporna, Mag\'ombo di Kota Belud.\", \"isCorrect\": false, \"reaction\": \"Tertukar, Bobohizan! Pak Bajau ketawa dan membetulkan dulang di tangannya.\"}, {\"text\": \"Tamarok di Kota Belud, Ngeduang di Semporna.\", \"isCorrect\": false, \"reaction\": \"Tamarok itu upacara Bisaya di Sarawak, Bobohizan! Petani Bisaya mengangkat tangan sambil ketawa.\"}], \"clue\": \"Pantai barat bersama Kota Belud dan pantai timur bersama Semporna.\"}]}'),
(513, 'e5_n3_s1', 'Nyahkod Papan Tanda Pesta', 'Baca papan tanda yang luntur dan lengkapkan senarai tiga nama terakhir agama dan ajaran.', '5', 'Mengenal pasti agama dan kepercayaan utama di Malaysia.', '{\"clueText\": \"Papan tanda pesta menulis: Islam, Kristian, Buddha dan Hindu dengan jelas. Tiga nama terakhir sudah luntur dan tidak kelihatan, sedangkan semuanya ada tujuh.\", \"options\": [{\"text\": \"Sikh, Ajaran Tao dan Ajaran Konfusius.\", \"isCorrect\": true}, {\"text\": \"Sikh dan Ajaran Tao sahaja, tanpa Ajaran Konfusius.\", \"isCorrect\": false, \"consequence\": \"Papan tanda ditulis semula dengan hanya enam nama. Penganut Ajaran Konfusius terkilan kerana tidak disebut.\"}, {\"text\": \"Ajaran Tao dan Ajaran Konfusius sahaja, tanpa Sikh.\", \"isCorrect\": false, \"consequence\": \"Papan tanda ditulis semula tanpa Sikh. Harjit terdiam kerana agamanya tidak tercatat.\"}], \"aftermath\": \"Papan tanda tidak lengkap. Pesta bermula dengan senarai yang meninggalkan sebahagian agama.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Sikh, Ajaran Tao dan Ajaran Konfusius.\", \"isCorrect\": true, \"reaction\": \"Tepat, Lemambang! Kenny bersorak dan papan tanda pun bercahaya semula!\"}, {\"text\": \"Sikh dan Ajaran Tao, tanpa Ajaran Konfusius.\", \"isCorrect\": false, \"reaction\": \"Ajaran Konfusius tertinggal, Lemambang! Kenny menggaru kepala dan ketawa.\"}, {\"text\": \"Ajaran Tao dan Ajaran Konfusius, tanpa Sikh.\", \"isCorrect\": false, \"reaction\": \"Sikh tertinggal, Lemambang! Harjit melambai dari hujung barisan.\"}], \"clue\": \"Selepas Hindu, ada Sikh, kemudian dua ajaran: Tao dan Konfusius.\"}]}'),
(514, 'e5_n3_s2', 'Padanan Pantas: Rumah Ibadat', 'Padankan setiap agama atau ajaran dengan nama rumah ibadatnya.', '4', 'Mengenal pasti rumah ibadat pelbagai agama di Malaysia.', '{\"pairs\": [{\"text\": \"Islam\", \"pair\": 1}, {\"text\": \"Masjid\", \"pair\": 1}, {\"text\": \"Kristian\", \"pair\": 2}, {\"text\": \"Gereja\", \"pair\": 2}, {\"text\": \"Hindu\", \"pair\": 3}, {\"text\": \"Kuil\", \"pair\": 3}, {\"text\": \"Sikh\", \"pair\": 4}, {\"text\": \"Gurdwara\", \"pair\": 4}, {\"text\": \"Buddha\", \"pair\": 5}, {\"text\": \"Tokong atau wat\", \"pair\": 5}, {\"text\": \"Konfusius dan Tao\", \"pair\": 6}, {\"text\": \"Tokong\", \"pair\": 6}], \"aftermath\": \"Kad rumah ibadat tersalah padan. Murid-murid berjalan ke bangunan yang salah dengan kad yang tersilap.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Konfusius dan Tao dengan tokong.\", \"isCorrect\": true, \"reaction\": \"Tepat, Lemambang! Kad itu melekat di papan dan Mei Ling bersorak!\"}, {\"text\": \"Konfusius dan Tao dengan kuil.\", \"isCorrect\": false, \"reaction\": \"Kuil itu rumah ibadat Hindu, Lemambang! Kavitha ketawa sambil menggeleng.\"}, {\"text\": \"Konfusius dan Tao dengan gurdwara.\", \"isCorrect\": false, \"reaction\": \"Gurdwara rumah ibadat Sikh, Lemambang! Harjit tersenyum dan menggeleng perlahan.\"}], \"clue\": \"Mei Ling menyebut tokong untuk Buddha, dan juga untuk dua ajaran lain.\"}]}'),
(515, 'e5_n3_s3', 'Susun Kad Perkara 3', 'Susun Perkara 3 Perlembagaan mengikut nombor dan isinya.', '1', 'Memahami kedudukan agama Islam dalam Perlembagaan Perkara 3.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"Perkara 3(1)\", \"text\": \"Islam agama bagi Persekutuan; agama lain boleh diamalkan dengan aman dan damai di mana-mana bahagian Persekutuan\", \"why\": \"Asas kepada seluruh Perkara 3.\"}, {\"id\": 2, \"year\": \"Perkara 3(2)\", \"text\": \"Di negeri yang mempunyai Raja, kedudukan Raja ialah Ketua Agama Islam di negeri itu\", \"why\": \"Raja memegang kedudukan di negeri masing-masing.\"}, {\"id\": 3, \"year\": \"Perkara 3(3)\", \"text\": \"Yang di-Pertuan Agong ialah Ketua Agama Islam di Melaka, Pulau Pinang, Sabah dan Sarawak\", \"why\": \"Negeri-negeri ini tidak mempunyai Raja.\"}, {\"id\": 4, \"year\": \"Perkara 3(5)\", \"text\": \"Yang di-Pertuan Agong ialah Ketua Agama Islam Wilayah Persekutuan Kuala Lumpur, Labuan dan Putrajaya\", \"why\": \"Wilayah Persekutuan tiada Raja sendiri.\"}], \"aftermath\": \"Perkara 3 tersusun salah. Murid menyalin urutan yang kelam-kabut ke dalam buku.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"3(1), 3(2), 3(3), kemudian 3(5).\", \"isCorrect\": true, \"reaction\": \"Tepat, Lemambang! Murid itu menyusun kad dan dewan bertepuk tangan.\"}, {\"text\": \"3(5), 3(3), 3(2), kemudian 3(1).\", \"isCorrect\": false, \"reaction\": \"Terbalik, Lemambang! Kad-kad itu bertaburan dan murid mengutipnya sambil ketawa.\"}, {\"text\": \"3(2), 3(1), 3(5), kemudian 3(3).\", \"isCorrect\": false, \"reaction\": \"Bercampur, Lemambang! Sultan mengerut dahi sambil tersenyum.\"}], \"clue\": \"Nombor perkara bermula dari kecil ke besar: 3(1), kemudian 3(2) dan seterusnya.\"}]}'),
(516, 'e5_n3_s4', 'Soalan Sergahan di Pantai', 'Bantu murid memilih padanan kepercayaan Orang Asli yang betul.', '3', 'Mengenal pasti kepercayaan masyarakat Orang Asli di Semenanjung.', '{\"prompt\": \"Seorang murid menahan kau di tepi pantai dan bertanya: yang manakah pernyataan kepercayaan Orang Asli di Semenanjung yang betul?\", \"options\": [{\"text\": \"Mah Meri mengadakan Puja Pantai kepada semangat laut; Temiar dan Semai mengadakan ritual untuk menghalau kuasa jahat.\", \"isCorrect\": true}, {\"text\": \"Mah Meri mengadakan ritual untuk menghalau kuasa jahat; Temiar dan Semai mengadakan Puja Pantai kepada semangat laut.\", \"isCorrect\": false, \"consequence\": \"Murid itu menukar upacara antara suku. Pak Mah Meri dan Tok Batin menggeleng kerana nama suku dan upacara bertukar.\"}, {\"text\": \"Mah Meri mengadakan Tamarok kepada semangat padi; Temiar dan Semai mengadakan Ngeduang untuk menjamu tetamu.\", \"isCorrect\": false, \"consequence\": \"Murid itu mencampur upacara kaum lain dengan Orang Asli. Catatan itu salah dari awal hingga akhir.\"}], \"aftermath\": \"Kepercayaan Orang Asli tertukar. Murid pulang dengan padanan suku dan upacara yang salah.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Mah Meri: Puja Pantai. Temiar dan Semai: ritual menghalau kuasa jahat.\", \"isCorrect\": true, \"reaction\": \"Tepat, Lemambang! Ombak bergulung gembira dan Tok Batin mengangguk.\"}, {\"text\": \"Mah Meri: ritual menghalau kuasa jahat. Temiar dan Semai: Puja Pantai.\", \"isCorrect\": false, \"reaction\": \"Tertukar, Lemambang! Pak Mah Meri dan Tok Batin ketawa melihat jawapan itu.\"}, {\"text\": \"Mah Meri: Miring. Temiar dan Semai: Magavau.\", \"isCorrect\": false, \"reaction\": \"Miring dan Magavau bukan upacara Orang Asli, Lemambang! Murid itu menggaru kepala.\"}], \"clue\": \"Puja Pantai berkait dengan laut dan Mah Meri; ritual menghalau kuasa jahat berkait dengan Temiar dan Semai.\"}]}'),
(517, 'e5_n3_s5', 'Nyahkod Catatan Iban dan Kadazandusun', 'Baca catatan lama dan tentukan gelaran ketua bomoh upacara Magavau.', '5', 'Mengenal pasti kepercayaan masyarakat Iban dan Kadazandusun.', '{\"clueText\": \"Catatan lama menulis: Iban percaya Petara menyampaikan petanda melalui mimpi dan bayangan, dipuja melalui upacara Miring yang dimulai jampi mentera oleh Lemambang. Kadazandusun percaya Kinorohingan dan semangat padi, dengan upacara Magavau diketuai oleh ketua bomoh yang namanya sudah luntur.\", \"options\": [{\"text\": \"Bobohizan, ketua bomoh upacara Magavau.\", \"isCorrect\": true}, {\"text\": \"Lemambang, penyair upacara Miring.\", \"isCorrect\": false, \"consequence\": \"Catatan itu dibaca dengan gelaran Iban. Pembaca menyangka ketua Magavau ialah penyair Miring.\"}, {\"text\": \"Petara, dewa yang dipuja dalam Miring.\", \"isCorrect\": false, \"consequence\": \"Catatan itu dibaca dengan nama dewa Iban. Pembaca menyangka dewa itu memimpin upacara Kadazandusun.\"}], \"aftermath\": \"Catatan Iban dan Kadazandusun disalah baca. Gelaran ketua upacara bercampur dalam ingatan.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Bobohizan.\", \"isCorrect\": true, \"reaction\": \"Tepat, Lemambang! Linda menepuk dahi dan bersorak, sambil awan syair beralun di langit.\"}, {\"text\": \"Lemambang.\", \"isCorrect\": false, \"reaction\": \"Lemambang ialah gelaran penyair Miring Iban, bukan ketua Magavau! Linda ketawa dan Apai tersenyum.\"}, {\"text\": \"Petara.\", \"isCorrect\": false, \"reaction\": \"Petara ialah dewa yang dipuja dalam Miring. Bukan ketua bomoh Magavau! Linda menggeleng.\"}], \"clue\": \"Ketua bomoh Magavau Kadazandusun mempunyai gelaran yang berbeza daripada gelaran penyair Miring.\"}]}'),
(518, 'e5_n3_s6', 'Misi Pantai: Bukti Upacara', 'Cari bukti upacara Bajau pada gambar pantai Semporna dan ingat upacara Bisaya yang diceritakan.', '2', 'Mengenal pasti kepercayaan masyarakat Bisaya dan Bajau.', '{\"hotspots\":[{\"name\":\"Perahu berhias: Mag\'ombo, upacara Bajau di Semporna\",\"top\":\"40.9%\",\"left\":\"77.6%\"},{\"name\":\"Gerbang upacara: Mag\'ombo menghargai warisan turun-temurun\",\"top\":\"46.1%\",\"left\":\"51.1%\"},{\"name\":\"Tikar jamuan: Ngeduang menjamu tetamu sebagai sedekah, Kota Belud\",\"top\":\"78.5%\",\"left\":\"17.5%\"},{\"name\":\"Rumah di atas air: perkampungan Bajau di pantai timur\",\"top\":\"25.4%\",\"left\":\"14.2%\"}],\"bgImage\":\"../assets/gameAsset/background/upacara_pantai.png\",\"aftermath\":\"Bukti upacara tersalah cari. Upacara Bajau dan Bisaya bercampur dalam ingatan.\",\"turns\":[{\"after\":4,\"options\":[{\"text\":\"Mag\'ombo, menghargai warisan turun-temurun agar dirahmati.\",\"isCorrect\":true,\"reaction\":\"Tepat, Lemambang! Perahu berhias bergoyang dan Pak Bajau bertepuk tangan.\"},{\"text\":\"Ngeduang, menjamu tetamu sebagai sedekah selepas kematian.\",\"isCorrect\":false,\"reaction\":\"Itu Ngeduang di Kota Belud, Lemambang! Pak Bajau ketawa dan menunjuk ke arah barat.\"},{\"text\":\"Tamarok, menghalau kuasa ghaib daripada badan pesakit.\",\"isCorrect\":false,\"reaction\":\"Tamarok upacara Bisaya di Sarawak, Lemambang! Petani Bisaya mengangkat tangan sambil ketawa.\"}],\"clue\":\"Mag\'ombo diadakan di Semporna, pantai timur Sabah.\"}]}'),
(601, 'e6_n1_s1', 'Misi Tempahan Semua Perayaan', 'Bantu murid memilih pernyataan yang betul tentang perayaan utama masyarakat di Malaysia.', '3', 'Mengenal pasti perayaan utama masyarakat di Malaysia.', '{\"prompt\": \"Seorang murid menahan kau dan bertanya: yang manakah pernyataan yang betul tentang perayaan utama masyarakat di Malaysia?\", \"options\": [{\"text\": \"Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro juga termasuk perayaan utama masyarakat di Malaysia.\", \"isCorrect\": true}, {\"text\": \"Hanya Hari Raya, Tahun Baharu Cina dan Deepavali sahaja dikira perayaan utama masyarakat di Malaysia kini.\", \"isCorrect\": false, \"consequence\": \"Murid itu mencatat tiga perayaan sahaja. Linda, Harjit dan Pak Nelayan terkilan kerana perayaan mereka tidak disebut.\"}, {\"text\": \"Krismas dan Thaipusam bukan perayaan utama; hanya Wesak dan Gawai yang termasuk dalam senarai itu.\", \"isCorrect\": false, \"consequence\": \"Murid itu menyingkirkan Krismas dan Thaipusam. Daniel dan Kavitha menggeleng kerana perayaan mereka disalah faham.\"}], \"aftermath\": \"Senarai perayaan tidak lengkap. Murid-murid pulang dengan nota yang meninggalkan beberapa perayaan.\", \"turns\": [{\"after\": 8, \"options\": [{\"text\": \"Vaisakhi.\", \"isCorrect\": true, \"reaction\": \"Tepat, penggiat! Harjit mengangguk dan kain berwarna dilambai riang. Satu mata untuk kau!\"}, {\"text\": \"Hari Wesak.\", \"isCorrect\": false, \"reaction\": \"Itu perayaan Mei Ling, penggiat! Harjit tersenyum dan menunjuk ke arah Mei Ling.\"}, {\"text\": \"Pesta Kaamatan.\", \"isCorrect\": false, \"reaction\": \"Itu perayaan Linda, penggiat! Harjit menggeleng sambil ketawa.\"}], \"clue\": \"Harjit menyebut perayaannya sebaik sahaja menyebut kain berwarna.\"}]}'),
(602, 'e6_n1_s2', 'Padanan Pantas: Tujuan Perayaan', 'Padankan setiap tujuan dengan perayaan yang diraikan untuk tujuan itu.', '4', 'Mengenal pasti tujuan perayaan masyarakat di Malaysia.', '{\"pairs\": [{\"text\": \"Keagamaan\", \"pair\": 1}, {\"text\": \"Aidilfitri, Aidiladha, Krismas dan Thaipusam\", \"pair\": 1}, {\"text\": \"Meraikan tahun baharu\", \"pair\": 2}, {\"text\": \"Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk, Tawun Empai\", \"pair\": 2}, {\"text\": \"Mensyukuri hasil tanaman atau laut\", \"pair\": 3}, {\"text\": \"Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro\", \"pair\": 3}, {\"text\": \"Kebaikan mengatasi kejahatan\", \"pair\": 4}, {\"text\": \"Deepavali\", \"pair\": 4}, {\"text\": \"Mengingati tokoh agama\", \"pair\": 5}, {\"text\": \"Hari Wesak\", \"pair\": 5}], \"aftermath\": \"Tujuan perayaan tersalah padan. Pelanggan membawa pulang hiasan untuk perayaan yang salah.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Mensyukuri hasil tanaman atau hasil laut.\", \"isCorrect\": true, \"reaction\": \"Tepat, penggiat! Murid itu menulis laju-laju dan Linda bertepuk tangan.\"}, {\"text\": \"Meraikan tahun baharu secara bersama.\", \"isCorrect\": false, \"reaction\": \"Itu tujuan Tahun Baharu Cina dan seumpamanya, penggiat! Ah Meng menggeleng sambil ketawa.\"}, {\"text\": \"Mengingati tokoh agama yang dihormati.\", \"isCorrect\": false, \"reaction\": \"Itu tujuan Hari Wesak, penggiat! Mei Ling tersenyum sambil menggeleng.\"}], \"clue\": \"Gawai, Kaamatan, Vaisakhi dan San Pedro disambut kerana tanaman atau laut.\"}]}');
INSERT INTO `Quest` (`questID`, `sceneID`, `questName`, `instruction`, `questType`, `description`, `questContent`) VALUES
(603, 'e6_n1_s3', 'Misi Kamera: Cara Dahulu', 'Cari bukti cara sambutan dahulu pada gambar studio kedai gambar.', '2', 'Mengenal pasti perbezaan kad ucapan dan foto keluarga dahulu dan kini.', '{\"hotspots\":[{\"name\":\"Kamera lama: foto keluarga diambil di kedai gambar\",\"top\":\"49.5%\",\"left\":\"14.9%\"},{\"name\":\"Latar lukisan studio kedai gambar untuk foto keluarga dahulu\",\"top\":\"40%\",\"left\":\"55%\"},{\"name\":\"Kerusi untuk bergambar bersama keluarga di kedai gambar\",\"top\":\"70%\",\"left\":\"52%\"},{\"name\":\"Lampu studio kedai gambar pada zaman dahulu\",\"top\":\"20.7%\",\"left\":\"97.7%\"}],\"bgImage\":\"../assets/gameAsset/background/mengambil_foto_dahulu.png\",\"aftermath\":\"Bukti cara dahulu tersalah cari. Murid menyangka cara dahulu dan kini sama sahaja.\",\"turns\":[{\"after\":4,\"options\":[{\"text\":\"Mengambil foto keluarga di kedai gambar.\",\"isCorrect\":true,\"reaction\":\"Tepat, penggiat! Nenek Dahulu menepuk tangan dan kamera lama pun berbunyi klik!\"},{\"text\":\"Swafoto dan memuat naiknya di media sosial.\",\"isCorrect\":false,\"reaction\":\"Itu cara kini, penggiat! Murid itu ketawa kerana jawapan itu tersasar zaman.\"},{\"text\":\"Menghantar ucapan menggunakan media sosial.\",\"isCorrect\":false,\"reaction\":\"Itu juga cara kini, penggiat! Nenek Dahulu menggeleng sambil tersenyum.\"}],\"clue\":\"Studio dengan kamera tripod menunjukkan cara foto keluarga dahulu.\"}]}'),
(604, 'e6_n1_s4', 'Nyahkod Catatan Kolam Lama', 'Baca catatan lama dan tentukan bahan membuat kolam pada zaman dahulu.', '5', 'Mengenal pasti perbezaan kolam Deepavali dan makan besar Tahun Baharu Cina dahulu dan kini.', '{\"clueText\": \"Catatan lama menulis: Pada Deepavali, orang membuat kolam di hadapan rumah. Bahan membuat kolam dahulu sudah luntur dan tidak kelihatan. Kini kolam dibuat daripada beras atau hampas kelapa berwarna-warni.\", \"options\": [{\"text\": \"Tepung.\", \"isCorrect\": true}, {\"text\": \"Beras berwarna-warni.\", \"isCorrect\": false, \"consequence\": \"Catatan itu dibaca dengan bahan kini. Pembaca menyangka kolam dahulu sama seperti kolam kini.\"}, {\"text\": \"Hampas kelapa berwarna-warni.\", \"isCorrect\": false, \"consequence\": \"Catatan itu dibaca dengan bahan kini. Pembaca tidak lagi tahu bahawa kolam dahulu daripada tepung.\"}], \"aftermath\": \"Catatan kolam disalah baca. Cara dahulu dan kini bercampur dalam ingatan kau.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Tepung.\", \"isCorrect\": true, \"reaction\": \"Tepat, penggiat! Kavitha bersorak dan corak putih pun nampak bercahaya.\"}, {\"text\": \"Beras berwarna-warni.\", \"isCorrect\": false, \"reaction\": \"Itu bahan kolam kini, penggiat! Kavitha tersenyum dan menggeleng.\"}, {\"text\": \"Hampas kelapa berwarna-warni.\", \"isCorrect\": false, \"reaction\": \"Itu juga bahan kolam kini, penggiat! Kavitha ketawa kecil.\"}], \"clue\": \"Catatan lama menyebut kolam dibuat daripada bahan putih, sebelum beras berwarna wujud.\"}]}'),
(605, 'e6_n1_s5', 'Soalan Sergahan di Dapur', 'Bantu murid memilih amalan perayaan yang masih kekal sehingga kini.', '3', 'Mengenal pasti perbezaan penyediaan kuih-muih dahulu dan kini serta amalan yang kekal.', '{\"prompt\": \"Seorang murid menahan kau di dapur dan bertanya: yang manakah amalan perayaan yang kekal dahulu dan kini?\", \"options\": [{\"text\": \"Tradisi balik ke kampung, pemberian duit raya dan amalan kunjung-mengunjung.\", \"isCorrect\": true}, {\"text\": \"Menghantar kad ucapan melalui pos dan mengambil foto keluarga di kedai gambar.\", \"isCorrect\": false, \"consequence\": \"Murid itu menyangka cara dahulu masih kekal. Nenek Dahulu menggeleng kerana kini ramai menghantar ucapan secara elektronik.\"}, {\"text\": \"Menyediakan kuih-muih secara gotong-royong menggunakan bahan dan kaedah tradisional sahaja.\", \"isCorrect\": false, \"consequence\": \"Murid itu menyangka cara kuih dahulu tidak berubah. Aishah menunjuk peralatan moden dan kuih raya yang mudah dibeli.\"}], \"aftermath\": \"Amalan yang kekal disalah faham. Murid menyangka semua cara beraya tidak pernah berubah.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Balik ke kampung, duit raya dan kunjung-mengunjung.\", \"isCorrect\": true, \"reaction\": \"Tepat, penggiat! Nenek Dahulu tersenyum bangga dan Aishah bertepuk tangan.\"}, {\"text\": \"Menghantar kad ucapan melalui pos dan bergambar di kedai gambar.\", \"isCorrect\": false, \"reaction\": \"Itu cara dahulu yang sudah berubah, penggiat! Nenek Dahulu menggeleng sambil ketawa.\"}, {\"text\": \"Menyediakan kuih secara gotong-royong dengan kaedah tradisional sahaja.\", \"isCorrect\": false, \"reaction\": \"Cara itu sudah banyak berubah, penggiat! Aishah menunjuk ke arah peralatan moden.\"}], \"clue\": \"Tiga amalan yang tidak berubah: balik kampung, duit raya dan kunjung-mengunjung.\"}]}'),
(606, 'e6_n1_s6', 'Misi Pentas: Unduk Ngadau Dahulu', 'Cari bukti Unduk Ngadau dahulu dan hasil tanaman yang disyukuri pada gambar.', '2', 'Mengenal pasti perbezaan Hari Gawai dan Pesta Kaamatan (Unduk Ngadau) dahulu dan kini.', '{\"hotspots\":[{\"name\":\"Pemenang Unduk Ngadau dahulu: dipilih berdasarkan semangat Huminodun\",\"top\":\"32.1%\",\"left\":\"69.2%\"},{\"name\":\"Tiga peserta Unduk Ngadau menunggu keputusan di tepi pentas\",\"top\":\"51.2%\",\"left\":\"40.3%\"},{\"name\":\"Pentas pondok Pesta Kaamatan di tepi sawah\",\"top\":\"57.6%\",\"left\":\"63.2%\"},{\"name\":\"Sawah padi: hasil tanaman yang disyukuri semasa Kaamatan dan Gawai\",\"top\":\"59.5%\",\"left\":\"8.1%\"}],\"bgImage\":\"../assets/gameAsset/background/unduk_ngadau_dahulu.png\",\"aftermath\":\"Bukti Unduk Ngadau tersalah cari. Cara memilih pemenang dahulu dan kini bercampur.\",\"turns\":[{\"after\":5,\"options\":[{\"text\":\"Pemenang dipilih berdasarkan semangat Huminodun.\",\"isCorrect\":true,\"reaction\":\"Tepat, penggiat! Linda bertepuk tangan dan padi pun beralun gembira.\"},{\"text\":\"Pemenang dipilih melalui sesi soal jawab sejarah sahaja.\",\"isCorrect\":false,\"reaction\":\"Itu cara kini, penggiat! Linda menggeleng sambil tersenyum.\"},{\"text\":\"Pemenang dipilih daripada golongan petani sahaja.\",\"isCorrect\":false,\"reaction\":\"Itu bukan cara memilih pemenang Unduk Ngadau, penggiat! Apai Jelani ketawa.\"}],\"clue\":\"Dahulu pemenang dipilih kerana semangat Huminodun, bukan kerana soal jawab.\"}]}'),
(607, 'e6_n2_s1', 'Padanan Kumpulan Perayaan', 'Padankan setiap kumpulan dengan perayaan yang tergolong di dalamnya.', '4', 'Mengenal pasti perayaan utama masyarakat di Malaysia.', '{\"pairs\": [{\"text\": \"Dua Hari Raya\", \"pair\": 1}, {\"text\": \"Hari Raya Aidilfitri dan Hari Raya Aidiladha\", \"pair\": 1}, {\"text\": \"Perayaan Hindu dan Sikh\", \"pair\": 2}, {\"text\": \"Deepavali, Thaipusam dan Vaisakhi\", \"pair\": 2}, {\"text\": \"Perayaan Kristian dan Buddha\", \"pair\": 3}, {\"text\": \"Krismas dan Hari Wesak\", \"pair\": 3}, {\"text\": \"Perayaan Sabah dan Sarawak\", \"pair\": 4}, {\"text\": \"Pesta Kaamatan dan Hari Gawai\", \"pair\": 4}, {\"text\": \"Perayaan lain dalam senarai\", \"pair\": 5}, {\"text\": \"Tahun Baharu Cina, Genggulang, Hari Moyang dan San Pedro\", \"pair\": 5}], \"aftermath\": \"Perayaan tersalah kumpulan. Kerja rumah murid dipenuhi dengan pengkelasan yang silap.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Sabah.\", \"isCorrect\": true, \"reaction\": \"Tepat, Ibu! Linda bersorak dan menunjukkan hiasan padi miliknya.\"}, {\"text\": \"Sarawak.\", \"isCorrect\": false, \"reaction\": \"Hari Gawai di Sarawak, Ibu! Pesta Kaamatan di Sabah. Daniel menyampuk sambil ketawa.\"}, {\"text\": \"Melaka.\", \"isCorrect\": false, \"reaction\": \"Bukan Melaka, Ibu! Linda menggeleng-geleng sambil tersenyum lebar.\"}], \"clue\": \"Linda ialah Kadazandusun dari negeri Borneo yang bukan Sarawak.\"}]}'),
(608, 'e6_n2_s2', 'Nyahkod Surat Lama Nenek', 'Baca surat lama yang luntur dan tentukan tujuan perayaan Deepavali.', '5', 'Mengenal pasti tujuan perayaan masyarakat di Malaysia.', '{\"clueText\": \"Surat lama menulis: Keagamaan untuk Aidilfitri, Aidiladha, Krismas dan Thaipusam. Hari Wesak untuk mengingati tokoh agama. Tujuan Deepavali sudah luntur dan tidak kelihatan, tetapi ia berkait dengan cahaya mengatasi kegelapan.\", \"options\": [{\"text\": \"Unsur baik mengatasi kejahatan.\", \"isCorrect\": true}, {\"text\": \"Mensyukuri hasil tanaman atau hasil laut.\", \"isCorrect\": false, \"consequence\": \"Surat itu disalah baca. Anak-anak menyangka Deepavali ialah perayaan hasil tuaian, bukan kebaikan mengatasi kejahatan.\"}, {\"text\": \"Meraikan tahun baharu.\", \"isCorrect\": false, \"consequence\": \"Surat itu disalah baca. Anak-anak menyangka Deepavali ialah tahun baharu, lalu catatan mereka tersasar.\"}], \"aftermath\": \"Tujuan perayaan disalah faham. Anak-anak pulang dengan catatan yang tersasar daripada tujuan sebenar.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Unsur baik mengatasi kejahatan.\", \"isCorrect\": true, \"reaction\": \"Tepat, Ibu! Nenek menepuk lutut dan surat lama bercahaya semula.\"}, {\"text\": \"Mensyukuri hasil tanaman atau hasil laut.\", \"isCorrect\": false, \"reaction\": \"Itu tujuan Gawai, Kaamatan, Vaisakhi dan San Pedro, Ibu! Nenek menggeleng sambil tersenyum.\"}, {\"text\": \"Mengingati tokoh agama.\", \"isCorrect\": false, \"reaction\": \"Itu tujuan Hari Wesak, Ibu! Murid itu ketawa.\"}], \"clue\": \"Surat lama menyebut cahaya dan kegelapan, kebaikan dan kejahatan.\"}]}'),
(609, 'e6_n2_s3', 'Soalan Sergahan di Ruang Tamu', 'Bantu murid memilih pernyataan yang betul tentang kad ucapan dan foto keluarga dahulu dan kini.', '3', 'Mengenal pasti perbezaan kad ucapan dan foto keluarga dahulu dan kini.', '{\"prompt\": \"Murid itu menunjuk skrin dan bertanya: yang manakah perbezaan kad ucapan dan foto keluarga dahulu dan kini?\", \"options\": [{\"text\": \"Dahulu kad dihantar melalui pos dan foto di kedai gambar; kini ucapan melalui media sosial dan swafoto.\", \"isCorrect\": true}, {\"text\": \"Dahulu ucapan melalui media sosial dan swafoto; kini kad melalui pos dan foto di kedai gambar.\", \"isCorrect\": false, \"consequence\": \"Murid itu menukar zaman. Nenek tergelak kerana pos tidak wujud pada zaman media sosial.\"}, {\"text\": \"Dahulu dan kini sama sahaja tanpa perubahan; kad dihantar melalui pos dan foto di kedai gambar sahaja.\", \"isCorrect\": false, \"consequence\": \"Murid itu menyangka tiada perubahan. Nenek menunjuk telefon yang berbunyi PING sebagai bukti perubahan.\"}], \"aftermath\": \"Cara ucapan dan foto dahulu dan kini tertukar. Murid menulis perbezaan yang silap dalam buku.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Menggunakan media elektronik dan media sosial.\", \"isCorrect\": true, \"reaction\": \"Tepat, Ibu! Murid itu bersorak dan telefon berbunyi PING seolah-olah bersetuju.\"}, {\"text\": \"Melalui pos atau serahan tangan di kampung.\", \"isCorrect\": false, \"reaction\": \"Itu cara dahulu, Ibu! Nenek mengangkat kad lama sambil ketawa.\"}, {\"text\": \"Mengambil foto di kedai gambar yang lama itu.\", \"isCorrect\": false, \"reaction\": \"Itu cara dahulu untuk foto, Ibu, bukan untuk ucapan! Nenek tersenyum.\"}], \"clue\": \"Ucapan kini dihantar dengan peranti yang dipegang murid itu.\"}]}'),
(610, 'e6_n2_s4', 'Misi Halaman: Kolam Kini', 'Cari bukti kolam kini dan meja makan besar pada gambar halaman.', '2', 'Mengenal pasti perbezaan kolam Deepavali dan makan besar Tahun Baharu Cina dahulu dan kini.', '{\"hotspots\":[{\"name\":\"Kolam kini daripada beras atau hampas kelapa berwarna-warni\",\"top\":\"48.2%\",\"left\":\"34.8%\"},{\"name\":\"Kanak-kanak melukis kolam beramai-ramai\",\"top\":\"60.6%\",\"left\":\"81.9%\"},{\"name\":\"Keluarga duduk bersama membuat kolam pada Deepavali\",\"top\":\"42.2%\",\"left\":\"10.7%\"},{\"name\":\"Pelita di tengah kolam semasa Deepavali\",\"top\":\"65.3%\",\"left\":\"36.8%\"}],\"bgImage\":\"../assets/gameAsset/background/kolam_deepavali_sekarang.png\",\"aftermath\":\"Bukti kolam kini tersalah cari. Cara dahulu dan kini bercampur dalam ingatan.\",\"turns\":[{\"after\":4,\"options\":[{\"text\":\"Kolam daripada beras atau hampas kelapa berwarna-warni.\",\"isCorrect\":true,\"reaction\":\"Tepat, Puan! Kavitha menepuk tangan dan manik-manik pelangi bergemerlapan.\"},{\"text\":\"Kolam daripada tepung putih sahaja tanpa warna lain.\",\"isCorrect\":false,\"reaction\":\"Itu bahan kolam dahulu, Puan! Kavitha ketawa kecil.\"},{\"text\":\"Kolam dibuat di kedai gambar lama itu bersama kamera.\",\"isCorrect\":false,\"reaction\":\"Itu bukan tempat membuat kolam, Puan! Ah Meng ketawa terbahak-bahak.\"}],\"clue\":\"Kolam kini berwarna-warni kerana bahan baharu, bukan tepung putih.\"}]}'),
(611, 'e6_n2_s5', 'Susun Urutan Kuih dan Amalan', 'Susun cara menyediakan kuih dahulu, kini dan amalan yang kekal mengikut urutan.', '1', 'Mengenal pasti perbezaan penyediaan kuih-muih dahulu dan kini serta amalan yang kekal.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"Dahulu\", \"text\": \"Kuih-muih disediakan menggunakan bahan dan kaedah tradisional secara gotong-royong\", \"why\": \"Jiran dan keluarga berkumpul membantu.\"}, {\"id\": 2, \"year\": \"Kini\", \"text\": \"Peralatan moden memudahkan penyediaan dan kuih raya juga mudah dibeli\", \"why\": \"Kemudahan menjimatkan masa.\"}, {\"id\": 3, \"year\": \"Sentiasa kekal\", \"text\": \"Tradisi balik ke kampung, pemberian duit raya dan kunjung-mengunjung\", \"why\": \"Amalan ini tidak berubah walaupun zaman berubah.\"}], \"aftermath\": \"Urutan cara dahulu dan kini tersusun salah. Anak-anak menyangka zaman berubah tanpa amalan yang kekal.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Dahulu, kini, kemudian yang kekal.\", \"isCorrect\": true, \"reaction\": \"Tepat, Ibu! Nenek mengangguk dan troli pun seolah-olah bergerak laju.\"}, {\"text\": \"Kini, dahulu, kemudian yang kekal.\", \"isCorrect\": false, \"reaction\": \"Tertukar, Ibu! Nenek ketawa kerana dahulu datang sebelum kini.\"}, {\"text\": \"Yang kekal dahulu, kemudian kini, dahulu.\", \"isCorrect\": false, \"reaction\": \"Bercampur-campur, Ibu! Murid itu menggaru kepala.\"}], \"clue\": \"Dahulu bermula dengan tradisi, kini dengan kemudahan, dan yang kekal tidak berubah sepanjang masa.\"}]}'),
(612, 'e6_n2_s6', 'Nyahkod Pengumuman Unduk Ngadau', 'Baca pengumuman yang luntur dan tentukan satu lagi asas pemilihan pemenang Unduk Ngadau kini.', '5', 'Mengenal pasti perbezaan Hari Gawai dan Pesta Kaamatan (Unduk Ngadau) dahulu dan kini.', '{\"clueText\": \"Pengumuman menulis: Pemenang Unduk Ngadau dipilih berdasarkan semangat Huminodun, iaitu kesanggupan berkorban demi menyelamatkan generasi. Satu lagi asas pemilihan kini sudah luntur dan tidak kelihatan, tetapi berkait dengan sesi soal jawab.\", \"options\": [{\"text\": \"Sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau.\", \"isCorrect\": true}, {\"text\": \"Upacara ritual oleh golongan petani daripada kaum Dayak.\", \"isCorrect\": false, \"consequence\": \"Pengumuman itu dibaca dengan Hari Gawai dahulu. Penonton menyangka Unduk Ngadau kini sama seperti upacara Gawai dahulu.\"}, {\"text\": \"Pertandingan menanam padi paling cepat di sawah.\", \"isCorrect\": false, \"consequence\": \"Pengumuman itu ditambah dengan cabaran yang tiada. Penonton keliru tentang cara memilih pemenang sebenar.\"}], \"aftermath\": \"Pengumuman Unduk Ngadau disalah baca. Cara memilih pemenang dahulu dan kini bercampur.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Sesi soal jawab sejarah dan kehidupan lampau.\", \"isCorrect\": true, \"reaction\": \"Tepat, Puan! Linda bersorak dan semua penonton bertepuk tangan.\"}, {\"text\": \"Pertandingan menanam padi paling cepat.\", \"isCorrect\": false, \"reaction\": \"Bukan, Puan! Linda ketawa kerana tiada pertandingan itu dalam Unduk Ngadau kini.\"}, {\"text\": \"Upacara ritual oleh petani kaum Dayak sahaja.\", \"isCorrect\": false, \"reaction\": \"Itu Hari Gawai dahulu, Puan! Apai Jelani menggeleng sambil tersenyum.\"}], \"clue\": \"Pengumuman menyebut semangat Huminodun dan satu lagi sesi yang berkait dengan sejarah.\"}]}'),
(613, 'e6_n3_s1', 'Nyahkod Senarai Jualan Kedai', 'Baca senarai jualan yang luntur dan lengkapkan nama perayaan yang tidak kelihatan.', '5', 'Mengenal pasti perayaan utama masyarakat di Malaysia.', '{\"clueText\": \"Senarai jualan kedai menulis: Hari Raya Aidilfitri, Hari Raya Aidiladha, Tahun Baharu Cina, Deepavali, Krismas dan Hari Wesak dengan jelas. Baki perayaan sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Thaipusam, Gawai, Kaamatan, Vaisakhi, Tahun Baharu, Genggulang, Hari Moyang dan San Pedro.\", \"isCorrect\": true}, {\"text\": \"Thaipusam, Hari Gawai, Pesta Kaamatan dan Vaisakhi sahaja, tanpa tahun baharu dan San Pedro.\", \"isCorrect\": false, \"consequence\": \"Senarai ditulis semula dengan separuh perayaan sahaja. Pelanggan yang menyambut San Pedro dan Hari Moyang pulang hampa.\"}, {\"text\": \"Hanya Hari Gawai dan Pesta Kaamatan sahaja, tanpa Thaipusam, Vaisakhi dan San Pedro.\", \"isCorrect\": false, \"consequence\": \"Senarai ditulis semula dengan dua perayaan sahaja. Kavitha dan Harjit pulang tanpa hiasan perayaan mereka.\"}], \"aftermath\": \"Senarai perayaan di kedai tidak lengkap. Pelanggan pulang tanpa barang perayaan mereka.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Thaipusam, Gawai, Kaamatan, Vaisakhi, Tahun Baharu, Genggulang, Hari Moyang dan San Pedro.\", \"isCorrect\": true, \"reaction\": \"Tepat, tauke! Murid itu bersorak dan senarai jualan pun terang semula!\"}, {\"text\": \"Thaipusam, Hari Gawai, Pesta Kaamatan dan Vaisakhi sahaja, tanpa tahun baharu dan San Pedro.\", \"isCorrect\": false, \"reaction\": \"Ada yang tertinggal, tauke! Pak Nelayan melambai-lambai kerana San Pedro tidak disebut.\"}, {\"text\": \"Hanya Hari Gawai dan Pesta Kaamatan, tanpa Thaipusam, Vaisakhi dan San Pedro.\", \"isCorrect\": false, \"reaction\": \"Banyak tertinggal, tauke! Kavitha dan Harjit saling berpandangan kerana perayaan mereka tidak disebut.\"}], \"clue\": \"Senarai itu menyebut enam perayaan yang jelas. Baki perayaan ialah Thaipusam hingga San Pedro.\"}]}'),
(614, 'e6_n3_s2', 'Soalan Sergahan di Kaunter', 'Bantu murid memilih tujuan perayaan yang betul.', '3', 'Mengenal pasti tujuan perayaan masyarakat di Malaysia.', '{\"prompt\": \"Murid itu bertanya di kaunter: yang manakah padanan tujuan dan perayaan yang betul?\", \"options\": [{\"text\": \"Mensyukuri hasil: Gawai, Kaamatan, Vaisakhi, San Pedro. Kebaikan mengatasi kejahatan: Deepavali.\", \"isCorrect\": true}, {\"text\": \"Mensyukuri hasil: Deepavali dan Krismas. Kebaikan mengatasi kejahatan: Gawai, Kaamatan, Vaisakhi dan San Pedro.\", \"isCorrect\": false, \"consequence\": \"Murid itu menukar tujuan perayaan. Pelanggan Deepavali menggeleng kerana tujuan perayaan mereka tersalah.\"}, {\"text\": \"Mengingati tokoh agama: Aidilfitri dan Aidiladha. Meraikan tahun baharu: Hari Wesak dan Thaipusam.\", \"isCorrect\": false, \"consequence\": \"Murid itu mencampur tujuan dan perayaan. Mei Ling menggeleng kerana Wesak sepatutnya untuk mengingati tokoh agama.\"}], \"aftermath\": \"Tujuan perayaan tersalah padan. Pelanggan membeli kad yang tidak sesuai dengan perayaan mereka.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Mensyukuri hasil tanaman atau hasil laut.\", \"isCorrect\": true, \"reaction\": \"Tepat, tauke! Murid itu menekan loceng kaunter dengan gembira.\"}, {\"text\": \"Meraikan tahun baharu secara bersama.\", \"isCorrect\": false, \"reaction\": \"Itu tujuan Tahun Baharu Cina dan seumpamanya, tauke! Ah Meng ketawa dari belakang.\"}, {\"text\": \"Mengingati tokoh agama yang dihormati.\", \"isCorrect\": false, \"reaction\": \"Itu tujuan Hari Wesak, tauke! Mei Ling tersenyum sambil menggeleng.\"}], \"clue\": \"Gawai dan Kaamatan menyambut padi, San Pedro menyambut hasil laut, jadi tujuannya sama.\"}]}'),
(615, 'e6_n3_s3', 'Susun Garis Masa Ucapan dan Foto', 'Susun cara kad ucapan dan foto keluarga dari zaman dahulu hingga kini.', '1', 'Mengenal pasti perbezaan kad ucapan dan foto keluarga dahulu dan kini.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"Dahulu\", \"text\": \"Kad ucapan dihantar melalui pos atau serahan tangan dan foto keluarga diambil di kedai gambar\", \"why\": \"Cara ini bergantung pada kad dan kedai gambar.\"}, {\"id\": 2, \"year\": \"Kini\", \"text\": \"Ucapan dihantar menggunakan media elektronik dan media sosial, dan swafoto bersama keluarga dimuat naik di media sosial\", \"why\": \"Peranti dan media sosial menggantikan kad pos dan kedai gambar.\"}], \"aftermath\": \"Cara dahulu dan kini tersusun terbalik. Murid menyangka media sosial wujud sebelum kad pos.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Kad pos dahulu, media sosial kemudian.\", \"isCorrect\": true, \"reaction\": \"Tepat, tauke! Nenek tersenyum dan murid itu menunjukkan telefonnya dengan bangga.\"}, {\"text\": \"Media sosial dahulu, kad pos kemudian.\", \"isCorrect\": false, \"reaction\": \"Terbalik, tauke! Nenek ketawa dan menunjuk kad lama di rak.\"}, {\"text\": \"Kad pos dan media sosial serentak.\", \"isCorrect\": false, \"reaction\": \"Tidak serentak, tauke! Nenek menggeleng sambil mengira dengan jari.\"}], \"clue\": \"Dahulu datang sebelum kini, dan kad pos wujud sebelum media sosial.\"}]}'),
(616, 'e6_n3_s4', 'Padanan Pantas: Kolam dan Makan Besar', 'Padankan kolam dan makan besar dahulu dan kini dengan bahan atau tempatnya.', '4', 'Mengenal pasti perbezaan kolam Deepavali dan makan besar Tahun Baharu Cina dahulu dan kini.', '{\"pairs\": [{\"text\": \"Kolam Deepavali dahulu\", \"pair\": 1}, {\"text\": \"Tepung\", \"pair\": 1}, {\"text\": \"Kolam Deepavali kini\", \"pair\": 2}, {\"text\": \"Beras atau hampas kelapa berwarna-warni\", \"pair\": 2}, {\"text\": \"Makan besar Tahun Baharu Cina dahulu\", \"pair\": 3}, {\"text\": \"Di rumah bersama keluarga\", \"pair\": 3}, {\"text\": \"Makan besar Tahun Baharu Cina kini\", \"pair\": 4}, {\"text\": \"Di rumah, ada yang di restoran atau hotel\", \"pair\": 4}], \"aftermath\": \"Kolam dan makan besar tersalah padan. Pelanggan pulang dengan bahan dan tempat yang tidak sesuai.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Kolam dahulu: tepung. Makan besar dahulu: di rumah.\", \"isCorrect\": true, \"reaction\": \"Tepat, tauke! Ah Meng dan Kavitha bertepuk tangan serentak.\"}, {\"text\": \"Kolam dahulu: hampas kelapa. Makan besar dahulu: di hotel.\", \"isCorrect\": false, \"reaction\": \"Itu cara kini, tauke! Ah Meng menggeleng sambil ketawa.\"}, {\"text\": \"Kolam dahulu: beras. Makan besar dahulu: di restoran.\", \"isCorrect\": false, \"reaction\": \"Itu juga cara kini, tauke! Kavitha tersenyum dan menggeleng.\"}], \"clue\": \"Dahulu kolam daripada tepung dan makan besar di rumah. Kini bahan dan tempat lebih pelbagai.\"}]}'),
(617, 'e6_n3_s5', 'Misi Kedai: Bukti Kuih Kini', 'Cari bukti kuih raya kini yang mudah dibeli pada gambar pojok kuih.', '2', 'Mengenal pasti perbezaan penyediaan kuih-muih dahulu dan kini serta amalan yang kekal.', '{\"hotspots\":[{\"name\":\"Rak balang kuih raya: kuih raya mudah dibeli di kedai\",\"top\":\"44%\",\"left\":\"43.4%\"},{\"name\":\"Juruwang kedai: kuih kini dibeli dengan mudah\",\"top\":\"52.7%\",\"left\":\"65.9%\"},{\"name\":\"Beg hadiah dan hamper kuih raya yang siap dibungkus\",\"top\":\"83%\",\"left\":\"8.4%\"},{\"name\":\"Papan Selamat Hari Raya\",\"top\":\"33.4%\",\"left\":\"71.9%\"}],\"bgImage\":\"../assets/gameAsset/background/pembelian_kuih_muih_kini.png\",\"aftermath\":\"Bukti kuih kini tersalah cari. Cara menyediakan kuih dahulu dan kini bercampur.\",\"turns\":[{\"after\":4,\"options\":[{\"text\":\"Balang kuih raya yang siap dibeli di kedai.\",\"isCorrect\":true,\"reaction\":\"Tepat, tauke! Nenek Dahulu tersenyum dan murid itu terus ke kaunter.\"},{\"text\":\"Dapur kayu api untuk menggoreng kuih bersama jiran.\",\"isCorrect\":false,\"reaction\":\"Itu cara dahulu, tauke! Nenek Dahulu ketawa sambil mengimbau kenangan.\"},{\"text\":\"Kad ucapan yang dihantar melalui pos.\",\"isCorrect\":false,\"reaction\":\"Itu bukan tentang kuih, tauke! Aishah menunjuk ke arah balang kuih.\"}],\"clue\":\"Kuih kini boleh dibeli terus di kedai dan tidak perlu disediakan sendiri.\"}]}'),
(618, 'e6_n3_s6', 'Padanan Pantas: Gawai dan Unduk Ngadau', 'Padankan Hari Gawai dan Unduk Ngadau dahulu dan kini dengan cara sambutan atau pemilihan pemenangnya.', '4', 'Mengenal pasti perbezaan Hari Gawai dan Pesta Kaamatan (Unduk Ngadau) dahulu dan kini.', '{\"pairs\": [{\"text\": \"Hari Gawai dahulu\", \"pair\": 1}, {\"text\": \"Petani kaum Dayak dengan upacara ritual\", \"pair\": 1}, {\"text\": \"Hari Gawai kini\", \"pair\": 2}, {\"text\": \"Pelbagai kaum tanpa mengira bidang pekerjaan\", \"pair\": 2}, {\"text\": \"Unduk Ngadau dahulu\", \"pair\": 3}, {\"text\": \"Semangat Huminodun, berkorban demi menyelamatkan generasi\", \"pair\": 3}, {\"text\": \"Unduk Ngadau kini\", \"pair\": 4}, {\"text\": \"Juga sesi soal jawab sejarah dan kehidupan lampau\", \"pair\": 4}], \"aftermath\": \"Cara sambutan dan pemilihan pemenang tersalah padan. Perarakan terhenti dan penonton kebingungan.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Gawai kini: pelbagai kaum tanpa mengira pekerjaan.\", \"isCorrect\": true, \"reaction\": \"Tepat, tauke! Apai Jelani bersorak dan penari berarak lebih laju.\"}, {\"text\": \"Gawai kini: petani kaum Dayak sahaja.\", \"isCorrect\": false, \"reaction\": \"Itu cara dahulu, tauke! Daniel menggeleng sambil tersenyum.\"}, {\"text\": \"Gawai kini: sesi soal jawab sejarah sahaja.\", \"isCorrect\": false, \"reaction\": \"Itu bukan tentang Gawai, tauke! Linda ketawa sambil menggeleng.\"}], \"clue\": \"Kini Gawai disambut oleh ramai kaum, bukan hanya oleh petani Dayak.\"}]}'),
(701, 'e7_n1_s1', 'Siaran Langsung: Siapa Perdana Menteri?', 'Pilih pernyataan yang betul tentang peranan jawatan Perdana Menteri untuk siaran akhbar.', '3', 'Mengenal pasti peranan jawatan Perdana Menteri.', '{\"prompt\": \"Seorang pembaca akhbar bertanya kepadamu: yang manakah pernyataan yang betul tentang jawatan Perdana Menteri?\", \"options\": [{\"text\": \"Ketua Kerajaan yang mengetuai pentadbiran negara dan dilantik secara rasmi oleh Yang di-Pertuan Agong.\", \"isCorrect\": true}, {\"text\": \"Ketua Utama Negara yang mengetuai pentadbiran negara dan dilantik secara rasmi oleh Dewan Rakyat.\", \"isCorrect\": false, \"consequence\": \"Berita itu tersiar dengan jawatan yang tersalah. Pembaca menyangka Perdana Menteri ialah Ketua Utama Negara.\"}, {\"text\": \"Ketua Kerajaan yang diwujudkan sebelum kemerdekaan dan dimansuhkan selepas itu oleh Parlimen.\", \"isCorrect\": false, \"consequence\": \"Berita itu tersiar dengan sejarah yang tersalah. Pembaca menyangka jawatan itu sudah tiada.\"}], \"aftermath\": \"Berita tentang jawatan Perdana Menteri tersiar tidak tepat. Pembaca akhbar keliru tentang peranan dan sejarahnya.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Yang di-Pertuan Agong.\", \"isCorrect\": true, \"reaction\": \"Tepat, wartawan! Tunku bertepuk tangan dan Tuanku tersenyum ke arah kamera.\"}, {\"text\": \"Ketua Hakim Negara.\", \"isCorrect\": false, \"reaction\": \"Bukan, wartawan! Tuanku mengangkat kening dan Tunku ketawa sambil menggeleng.\"}, {\"text\": \"Speaker Dewan Rakyat.\", \"isCorrect\": false, \"reaction\": \"Bukan begitu, wartawan! Tunku menunjuk ke arah Tuanku sambil tersenyum lebar.\"}], \"clue\": \"Yang melantik juga digelar Ketua Utama Negara, bukan Ketua Kerajaan.\"}]}'),
(702, 'e7_n1_s2', 'Susun Kad Temu Bual Mengikut Giliran', 'Susun enam Perdana Menteri yang pertama mengikut giliran memegang jawatan.', '1', 'Mengenal pasti senarai Perdana Menteri Malaysia mengikut giliran.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"Perdana Menteri pertama\", \"text\": \"Tunku Abdul Rahman Putra Al-Haj\", \"why\": \"Beliau memegang jawatan pada giliran pertama.\"}, {\"id\": 2, \"year\": \"Perdana Menteri kedua\", \"text\": \"Tun Abdul Razak bin Hussein\", \"why\": \"Beliau memegang jawatan pada giliran kedua.\"}, {\"id\": 3, \"year\": \"Perdana Menteri ketiga\", \"text\": \"Tun Hussein bin Onn\", \"why\": \"Beliau memegang jawatan pada giliran ketiga.\"}, {\"id\": 4, \"year\": \"Perdana Menteri keempat\", \"text\": \"Tun Dr. Mahathir bin Mohamad\", \"why\": \"Beliau kembali pada giliran ketujuh.\"}, {\"id\": 5, \"year\": \"Perdana Menteri kelima\", \"text\": \"Tun Abdullah bin Ahmad Badawi\", \"why\": \"Beliau datang selepas giliran keempat.\"}, {\"id\": 6, \"year\": \"Perdana Menteri keenam\", \"text\": \"Dato\' Sri Mohd Najib bin Tun Abdul Razak\", \"why\": \"Beliau memegang jawatan pada giliran keenam.\"}], \"aftermath\": \"Kad temu bual tersusun salah. Siaran menyebut nama Perdana Menteri tidak mengikut giliran.\", \"turns\": [{\"after\": 10, \"options\": [{\"text\": \"Tun Dr. Mahathir bin Mohamad.\", \"isCorrect\": true, \"reaction\": \"Tepat, wartawan! Tun Dr. Mahathir mengangkat dua jari kerana beliau dua kali memegang jawatan.\"}, {\"text\": \"Tun Hussein bin Onn.\", \"isCorrect\": false, \"reaction\": \"Itu Perdana Menteri ketiga, wartawan! Tun Hussein ketawa kecil dan mengangkat tiga jari.\"}, {\"text\": \"Tun Abdullah bin Ahmad Badawi.\", \"isCorrect\": false, \"reaction\": \"Itu Perdana Menteri kelima, wartawan! Tun Abdullah tersenyum dan mengangkat lima jari.\"}], \"clue\": \"Tokoh ini muncul dua kali dalam senarai, pada giliran keempat dan ketujuh.\"}]}'),
(703, 'e7_n1_s3', 'Padanan Tajuk Berita: Tugas Perdana Menteri', 'Padankan setiap tugas Perdana Menteri dengan penerangannya.', '4', 'Mengenal pasti tugas-tugas Perdana Menteri.', '{\"pairs\": [{\"text\": \"Penasihat kepada Yang di-Pertuan Agong\", \"pair\": 1}, {\"text\": \"Mengiringi baginda ke Mesyuarat Majlis Raja-Raja\", \"pair\": 1}, {\"text\": \"Mencadangkan senarai Jemaah Menteri\", \"pair\": 2}, {\"text\": \"Mempengerusikan Mesyuarat Jemaah Menteri\", \"pair\": 2}, {\"text\": \"Ketua Pentadbir Utama\", \"pair\": 3}, {\"text\": \"Merancang dan menyelaraskan semua dasar negara\", \"pair\": 3}, {\"text\": \"Menjalin hubungan diplomatik\", \"pair\": 4}, {\"text\": \"Mencadangkan pelantikan duta, diplomat dan konsulat\", \"pair\": 4}], \"aftermath\": \"Tugas Perdana Menteri tersalah padan. Tajuk berita membawa maklumat yang tidak tepat.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Menjalin hubungan diplomatik.\", \"isCorrect\": true, \"reaction\": \"Tepat, wartawan! Tun Abdul Razak mengangguk dan Tuanku tersenyum.\"}, {\"text\": \"Mempengerusikan Mesyuarat Jemaah Menteri.\", \"isCorrect\": false, \"reaction\": \"Itu tugas lain, wartawan! Tun Hussein melambai sambil tersenyum.\"}, {\"text\": \"Merancang dan menyelaraskan semua dasar negara.\", \"isCorrect\": false, \"reaction\": \"Itu tugas Ketua Pentadbir Utama, wartawan! Tun Abdullah menggeleng sambil ketawa.\"}], \"clue\": \"Duta, diplomat dan konsulat bekerja dengan negara luar.\"}]}'),
(704, 'e7_n1_s4', 'Misi Stadium: Bukti Perjuangan Kemerdekaan', 'Cari bukti perjuangan kemerdekaan pada gambar Stadium Merdeka.', '2', 'Mengenal pasti pencapaian Tunku Abdul Rahman, Tun Abdul Razak dan Tun Hussein Onn.', '{\"hotspots\":[{\"name\":\"Tunku di podium: memperjuangkan kemerdekaan secara rundingan\",\"top\":\"35%\",\"left\":\"52%\"},{\"name\":\"Papan Perisytiharan Kemerdekaan Malaya di podium\",\"top\":\"69.4%\",\"left\":\"50.4%\"},{\"name\":\"Poster Merdeka! Malaya! yang dipegang rakyat\",\"top\":\"46.5%\",\"left\":\"8.7%\"},{\"name\":\"Rakyat bersorak dan mengangkat tangan menyambut kemerdekaan\",\"top\":\"59.4%\",\"left\":\"73.3%\"}],\"bgImage\":\"../assets/gameAsset/background/laungan_di_stadium_merdeka.png\",\"aftermath\":\"Bukti perjuangan kemerdekaan tersalah cari. Siaran menyiarkan rakaman yang tidak berkaitan.\",\"turns\":[{\"after\":8,\"options\":[{\"text\":\"Pada 16 September 1963.\",\"isCorrect\":true,\"reaction\":\"Tepat, wartawan! Tunku mengangkat tangan dan penonton bersorak.\"},{\"text\":\"Pada 13 Mei 1969 itu.\",\"isCorrect\":false,\"reaction\":\"Itu tarikh peristiwa lain, wartawan! Tun Abdul Razak menggeleng perlahan.\"},{\"text\":\"Pada 31 Ogos 1957 dahulu.\",\"isCorrect\":false,\"reaction\":\"Itu tarikh lain, wartawan! Tunku tersenyum sambil menggeleng-geleng.\"}],\"clue\":\"Tarikh itu berlaku pada tahun 1963, bulan September.\"}]}'),
(705, 'e7_n1_s5', 'Nyahkod Nota Luntur: Koridor dan PIN', 'Baca nota yang luntur dan tentukan pelan yang diperkenalkan bersama Koridor Wilayah Ekonomi.', '5', 'Mengenal pasti pencapaian Tun Dr. Mahathir dan Tun Abdullah.', '{\"clueText\": \"Nota menulis: Tun Abdullah Ahmad Badawi memperkenalkan Koridor Wilayah Ekonomi dan satu pelan lagi. Nama pelan itu sudah luntur dan tidak kelihatan, tetapi ia berkait dengan integriti.\", \"options\": [{\"text\": \"Pelan Integriti Nasional (PIN).\", \"isCorrect\": true}, {\"text\": \"Pelan Industri Nasional (PIN).\", \"isCorrect\": false, \"consequence\": \"Nota itu dibaca dengan pelan yang tidak wujud. Siaran menyebut nama pelan yang tersalah.\"}, {\"text\": \"Program Transformasi Kerajaan (GTP).\", \"isCorrect\": false, \"consequence\": \"Nota itu dibaca dengan pencapaian Perdana Menteri lain. Siaran bercampur dengan pelan Najib.\"}], \"aftermath\": \"Nota tentang pencapaian Tun Abdullah disalah baca. Siaran menyebut pelan yang tidak tepat.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Tun Dr. Mahathir Mohamad.\", \"isCorrect\": true, \"reaction\": \"Tepat, wartawan! Tun Dr. Mahathir tersenyum bangga di hadapan menara kembar.\"}, {\"text\": \"Tun Abdullah Ahmad Badawi.\", \"isCorrect\": false, \"reaction\": \"Bukan, wartawan! Tun Abdullah tersenyum dan menunjuk ke arah Tun Dr. Mahathir.\"}, {\"text\": \"Dato\' Sri Mohd Najib Tun Abdul Razak.\", \"isCorrect\": false, \"reaction\": \"Bukan, wartawan! Tun Dr. Mahathir menggeleng sambil ketawa kecil.\"}], \"clue\": \"Beliau Perdana Menteri keempat dan ketujuh, dan beliau jugalah penubuh HICOM.\"}]}'),
(706, 'e7_n1_s6', 'Penutup Siaran: Tiga Pencapaian Terakhir', 'Pilih pernyataan yang betul tentang pencapaian Perdana Menteri keenam, kelapan dan kesembilan.', '3', 'Mengenal pasti pencapaian Najib, Muhyiddin dan Ismail Sabri.', '{\"prompt\": \"Seorang penonton siaran bertanya: yang manakah pernyataan yang betul tentang pencapaian Perdana Menteri keenam, kelapan dan kesembilan?\", \"options\": [{\"text\": \"Najib: 1Malaysia dan GTP; Muhyiddin: MTE dan bantuan semasa PKP; Ismail Sabri: Keluarga Malaysia.\", \"isCorrect\": true}, {\"text\": \"Najib: Keluarga Malaysia; Muhyiddin: 1Malaysia dan GTP; Ismail Sabri: MTE dan bantuan semasa PKP.\", \"isCorrect\": false, \"consequence\": \"Siaran menyebut pencapaian dengan tokoh yang tersalah. Penonton bercampur-aduk tentang siapa membuat apa.\"}, {\"text\": \"Najib: MTE dan bantuan semasa PKP; Muhyiddin: Keluarga Malaysia; Ismail Sabri: 1Malaysia dan GTP.\", \"isCorrect\": false, \"consequence\": \"Siaran menyebut pencapaian dengan tokoh yang tersalah. Penonton menyangka tiga pencapaian itu bertukar tempat.\"}], \"aftermath\": \"Pencapaian tiga Perdana Menteri terakhir tersalah padan. Penonton pulang dengan maklumat yang bercampur.\", \"turns\": [{\"after\": 8, \"options\": [{\"text\": \"Pelbagai agama, bangsa, kaum dan usia.\", \"isCorrect\": true, \"reaction\": \"Tepat, wartawan! Dato\' Seri Ismail Sabri tersenyum dan semua bertepuk tangan.\"}, {\"text\": \"Pelbagai bangsa dan kaum, tanpa agama dan usia.\", \"isCorrect\": false, \"reaction\": \"Ada yang tertinggal, wartawan! Dato\' Seri Ismail Sabri menggeleng sambil menunjuk ke senarai penuh.\"}, {\"text\": \"Satu kaum dan satu agama sahaja dalam negara.\", \"isCorrect\": false, \"reaction\": \"Bukan, wartawan! Dato\' Seri Ismail Sabri ketawa kerana jawapan itu bertentangan dengan konsepnya.\"}], \"clue\": \"Konsep itu meraikan keterangkuman, jadi senarainya panjang dan merangkumi usia juga.\"}]}'),
(707, 'e7_n2_s1', 'Nyahkod Nota Papan Putih', 'Baca nota papan putih yang luntur dan tentukan siapa yang melantik Perdana Menteri secara rasmi.', '5', 'Mengenal pasti peranan jawatan Perdana Menteri.', '{\"clueText\": \"Nota menulis: Perdana Menteri ialah Ketua Kerajaan yang mengetuai pentadbiran negara. Perdana Menteri dilantik secara rasmi oleh satu pihak. Nama pihak itu sudah luntur dan tidak kelihatan, tetapi beliau ialah Ketua Utama Negara.\", \"options\": [{\"text\": \"Yang di-Pertuan Agong.\", \"isCorrect\": true}, {\"text\": \"Speaker Dewan Rakyat.\", \"isCorrect\": false, \"consequence\": \"Nota itu dibaca dengan pihak yang tersalah. Murid-murid mencatat bahawa Speaker melantik Perdana Menteri.\"}, {\"text\": \"Ketua Hakim Negara.\", \"isCorrect\": false, \"consequence\": \"Nota itu dibaca dengan pihak yang tersalah. Murid-murid keliru tentang siapa Ketua Utama Negara.\"}], \"aftermath\": \"Nota tentang pelantikan Perdana Menteri disalah baca. Murid-murid mencatat pihak yang tidak tepat.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Ketua Kerajaan.\", \"isCorrect\": true, \"reaction\": \"Tepat, cikgu! Tunku bertepuk tangan dan murid-murid bersorak.\"}, {\"text\": \"Ketua Utama Negara.\", \"isCorrect\": false, \"reaction\": \"Itu gelaran Yang di-Pertuan Agong, cikgu! Tuanku tersenyum sambil mengangkat tangan.\"}, {\"text\": \"Ketua Hakim Negara.\", \"isCorrect\": false, \"reaction\": \"Bukan, cikgu! Tunku menggeleng sambil ketawa kecil.\"}], \"clue\": \"Ketua yang mengetuai pentadbiran negara, bukan Ketua Utama Negara.\"}]}'),
(708, 'e7_n2_s2', 'Padanan Kad Kehadiran', 'Padankan giliran Perdana Menteri dengan nama tokoh yang memegang jawatan itu.', '4', 'Mengenal pasti senarai Perdana Menteri Malaysia mengikut giliran.', '{\"pairs\": [{\"text\": \"Perdana Menteri pertama\", \"pair\": 1}, {\"text\": \"Tunku Abdul Rahman Putra Al-Haj\", \"pair\": 1}, {\"text\": \"Perdana Menteri kedua\", \"pair\": 2}, {\"text\": \"Tun Abdul Razak bin Hussein\", \"pair\": 2}, {\"text\": \"Perdana Menteri keempat dan ketujuh\", \"pair\": 3}, {\"text\": \"Tun Dr. Mahathir bin Mohamad\", \"pair\": 3}, {\"text\": \"Perdana Menteri keenam\", \"pair\": 4}, {\"text\": \"Dato\' Sri Mohd Najib bin Tun Abdul Razak\", \"pair\": 4}, {\"text\": \"Perdana Menteri kelapan\", \"pair\": 5}, {\"text\": \"Tan Sri Muhyiddin bin Md Yassin\", \"pair\": 5}, {\"text\": \"Perdana Menteri kesembilan\", \"pair\": 6}, {\"text\": \"Dato\' Seri Ismail Sabri bin Yaakob\", \"pair\": 6}], \"aftermath\": \"Kad kehadiran tersalah padan. Murid-murid mencatat nama Perdana Menteri pada giliran yang salah.\", \"turns\": [{\"after\": 10, \"options\": [{\"text\": \"Keempat dan ketujuh.\", \"isCorrect\": true, \"reaction\": \"Tepat, cikgu! Tun Dr. Mahathir mengangkat dua kad kehadiran dengan bangga.\"}, {\"text\": \"Keempat sahaja.\", \"isCorrect\": false, \"reaction\": \"Aku muncul sekali lagi, cikgu! Tun Dr. Mahathir menunjuk kad kehadiran keduanya.\"}, {\"text\": \"Ketujuh dan kelapan.\", \"isCorrect\": false, \"reaction\": \"Kelapan itu Tan Sri Muhyiddin, cikgu! Tun Dr. Mahathir ketawa sambil menggeleng.\"}], \"clue\": \"Beliau dikira dua kali dalam senarai sembilan giliran.\"}]}'),
(709, 'e7_n2_s3', 'Soalan Murid: Tugas Perdana Menteri', 'Pilih pernyataan yang betul tentang tugas Perdana Menteri untuk murid yang bertanya.', '3', 'Mengenal pasti tugas-tugas Perdana Menteri.', '{\"prompt\": \"Seorang murid mengangkat tangan dan bertanya: yang manakah pernyataan yang betul tentang tugas Perdana Menteri?\", \"options\": [{\"text\": \"Mengiringi Yang di-Pertuan Agong ke Mesyuarat Majlis Raja-Raja dan mempengerusikan Mesyuarat Jemaah Menteri.\", \"isCorrect\": true}, {\"text\": \"Melantik sendiri menteri dan mempengerusikan Mesyuarat Majlis Raja-Raja bersama Yang di-Pertuan Agong.\", \"isCorrect\": false, \"consequence\": \"Murid itu mencatat tugas yang tersalah. Mesyuarat dan pelantikan tertukar tempat dalam bukunya.\"}, {\"text\": \"Mencadangkan pelantikan Raja-Raja negeri dan merancang dasar untuk satu negeri sahaja.\", \"isCorrect\": false, \"consequence\": \"Murid itu mencatat tugas yang tersalah. Tugas diplomatik dan dasar negara tidak lagi kelihatan dalam catatannya.\"}], \"aftermath\": \"Tugas Perdana Menteri dicatat tidak tepat. Murid-murid pulang dengan maklumat yang tersalah.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Perdana Menteri.\", \"isCorrect\": true, \"reaction\": \"Tepat, cikgu! Tun Hussein mengangguk dan murid-murid bertepuk tangan.\"}, {\"text\": \"Yang di-Pertuan Agong.\", \"isCorrect\": false, \"reaction\": \"Tuanku hanya melantik menteri, cikgu! Tun Hussein menggeleng sambil tersenyum.\"}, {\"text\": \"Ketua Setiausaha Negara.\", \"isCorrect\": false, \"reaction\": \"Bukan, cikgu! Tun Hussein ketawa kerana jawatan itu bukan pengerusinya.\"}], \"clue\": \"Beliau juga mencadangkan senarai Jemaah Menteri itu.\"}]}'),
(710, 'e7_n2_s4', 'Susun Urutan Pencapaian Tiga Perdana Menteri', 'Susun peristiwa dan pencapaian mengikut urutan Perdana Menteri yang pertama hingga ketiga.', '1', 'Mengenal pasti pencapaian Tunku Abdul Rahman, Tun Abdul Razak dan Tun Hussein Onn.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"Perdana Menteri pertama\", \"text\": \"Tunku memperjuangkan kemerdekaan secara rundingan\", \"why\": \"Perjuangan ini dilakukan oleh Perdana Menteri pertama.\"}, {\"id\": 2, \"year\": \"16 September 1963\", \"text\": \"Tunku merealisasikan Pembentukan Malaysia\", \"why\": \"Tarikh ini ditandakan dalam sejarah Tunku.\"}, {\"id\": 3, \"year\": \"Selepas 13 Mei 1969\", \"text\": \"Tun Abdul Razak mengembalikan keamanan melalui MAGERAN dan memperkenalkan DEB\", \"why\": \"Peristiwa itu mendahului MAGERAN.\"}, {\"id\": 4, \"year\": \"Perdana Menteri ketiga\", \"text\": \"Tun Hussein Onn memperkenalkan ASNB dan Program Rukun Tetangga\", \"why\": \"Beliau datang selepas Tun Abdul Razak.\"}], \"aftermath\": \"Urutan pencapaian tersalah susun. Murid-murid menyangka MAGERAN berlaku sebelum kemerdekaan.\", \"turns\": [{\"after\": 8, \"options\": [{\"text\": \"Majlis Gerakan Negara.\", \"isCorrect\": true, \"reaction\": \"Tepat, cikgu! Tun Abdul Razak mengangguk dan jalan lengang itu mula bercahaya.\"}, {\"text\": \"Majlis Gabungan Negara.\", \"isCorrect\": false, \"reaction\": \"Hampir, cikgu! Tun Abdul Razak tersenyum dan menggeleng perlahan.\"}, {\"text\": \"Majlis Gerakan Nasional.\", \"isCorrect\": false, \"reaction\": \"Hampir, cikgu! Tun Abdul Razak ketawa kecil dan membetulkan sebutan.\"}], \"clue\": \"Singkatan itu bermula dengan majlis yang menggerakkan negara.\"}]}'),
(711, 'e7_n2_s5', 'Misi Bandar: Bukti Zaman Wawasan 2020', 'Cari bukti pencapaian Tun Dr. Mahathir pada gambar bandar ini.', '2', 'Mengenal pasti pencapaian Tun Dr. Mahathir dan Tun Abdullah.', '{\"hotspots\":[{\"name\":\"Menara Berkembar Petronas (KLCC): dibina pada zaman Tun Dr. Mahathir\",\"top\":\"26.5%\",\"left\":\"22%\"},{\"name\":\"Kilang moden: HICOM untuk industri berteknologi tinggi\",\"top\":\"45%\",\"left\":\"78%\"},{\"name\":\"Papan carta menaik: Wawasan 2020 menuju kemajuan\",\"top\":\"22%\",\"left\":\"90%\"},{\"name\":\"Jambatan layang dan jalan raya: pembangunan seperti KLIA dan Putrajaya\",\"top\":\"62%\",\"left\":\"38%\"}],\"bgImage\":\"../assets/gameAsset/background/pencapaian_ekonomi_perhubungan_dan_perdagangan.png\",\"aftermath\":\"Bukti pencapaian Tun Dr. Mahathir tersalah cari. Murid-murid keliru tentang apa yang dibina pada zamannya.\",\"turns\":[{\"after\":7,\"options\":[{\"text\":\"Industri berteknologi tinggi.\",\"isCorrect\":true,\"reaction\":\"Tepat, cikgu! Tun Dr. Mahathir tersenyum dan lampu kilang berkelip.\"},{\"text\":\"Industri pertanian tradisional sahaja.\",\"isCorrect\":false,\"reaction\":\"Bukan, cikgu! Tun Dr. Mahathir menggeleng sambil menunjuk ke kilang moden.\"},{\"text\":\"Industri kraf tangan di kampung.\",\"isCorrect\":false,\"reaction\":\"Bukan, cikgu! Tun Dr. Mahathir ketawa kerana HICOM bukan untuk kraf kampung.\"}],\"clue\":\"Kilang dan mesin moden, bukan kerja tangan atau pertanian tradisional.\"}]}'),
(712, 'e7_n2_s6', 'Nyahkod Kertas Tugasan', 'Baca kertas tugasan yang luntur dan tentukan satu lagi unsur keterangkuman dalam Keluarga Malaysia.', '5', 'Mengenal pasti pencapaian Najib, Muhyiddin dan Ismail Sabri.', '{\"clueText\": \"Kertas tugasan menulis: Dato\' Seri Ismail Sabri memperkenalkan konsep Keluarga Malaysia. Konsep itu meraikan keterangkuman pelbagai agama, bangsa dan kaum. Satu lagi unsur sudah luntur dan tidak kelihatan, tetapi ia berkait dengan umur.\", \"options\": [{\"text\": \"Pelbagai peringkat usia.\", \"isCorrect\": true}, {\"text\": \"Pelbagai jenis pekerjaan.\", \"isCorrect\": false, \"consequence\": \"Kertas itu dibaca dengan unsur yang tiada. Murid-murid menyangka konsep itu berkait dengan pekerjaan.\"}, {\"text\": \"Pelbagai bahasa negeri.\", \"isCorrect\": false, \"consequence\": \"Kertas itu dibaca dengan unsur yang tiada. Murid-murid menyangka konsep itu berkait dengan bahasa.\"}], \"aftermath\": \"Kertas tugasan tentang Keluarga Malaysia disalah baca. Murid-murid mencatat unsur yang tidak tepat.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Program Transformasi Kerajaan.\", \"isCorrect\": true, \"reaction\": \"Tepat, cikgu! Dato\' Sri Najib tersenyum dan murid-murid menulis laju.\"}, {\"text\": \"Pelan Integriti Nasional untuk rakyat.\", \"isCorrect\": false, \"reaction\": \"Itu PIN, cikgu! Dato\' Sri Najib menggeleng sambil tersenyum.\"}, {\"text\": \"Majlis Tindakan Ekonomi negara.\", \"isCorrect\": false, \"reaction\": \"Itu MTE, cikgu! Dato\' Sri Najib ketawa kecil.\"}], \"clue\": \"GTP diperkenalkan bersama Gagasan 1Malaysia.\"}]}'),
(713, 'e7_n3_s1', 'Padanan Kad Pertama: Jawatan Perdana Menteri', 'Padankan setiap kad dengan maklumat tentang jawatan Perdana Menteri.', '4', 'Mengenal pasti peranan jawatan Perdana Menteri.', '{\"pairs\": [{\"text\": \"Ketua Kerajaan\", \"pair\": 1}, {\"text\": \"Perdana Menteri\", \"pair\": 1}, {\"text\": \"Ketua Utama Negara\", \"pair\": 2}, {\"text\": \"Yang di-Pertuan Agong\", \"pair\": 2}, {\"text\": \"Jawatan Perdana Menteri diwujudkan\", \"pair\": 3}, {\"text\": \"Selepas kemerdekaan\", \"pair\": 3}, {\"text\": \"Jawatan Perdana Menteri kini\", \"pair\": 4}, {\"text\": \"Kekal hingga kini\", \"pair\": 4}], \"aftermath\": \"Kad pertama tersalah padan. Album membawa maklumat yang tidak tepat tentang jawatan Perdana Menteri.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Selepas kemerdekaan negara.\", \"isCorrect\": true, \"reaction\": \"Tepat, murid! Tunku mengangkat ibu jari dan kad pertama bersinar.\"}, {\"text\": \"Sebelum kemerdekaan negara.\", \"isCorrect\": false, \"reaction\": \"Bukan, murid! Tunku menggeleng sambil ketawa kerana kemerdekaan datang dahulu.\"}, {\"text\": \"Selepas peristiwa 13 Mei 1969.\", \"isCorrect\": false, \"reaction\": \"Bukan, murid! Tunku menggeleng kerana jawatan itu sudah lama ada sebelumnya.\"}], \"clue\": \"Tunku ialah Perdana Menteri pertama, dan jawatan itu diwujudkan sebaik sahaja negara merdeka.\"}]}'),
(714, 'e7_n3_s2', 'Susun Sembilan Kad Perdana Menteri', 'Pilih susunan sembilan giliran Perdana Menteri yang betul untuk album.', '3', 'Mengenal pasti senarai Perdana Menteri Malaysia mengikut giliran.', '{\"prompt\": \"Cikgu projek bertanya: yang manakah susunan sembilan giliran Perdana Menteri yang betul?\", \"options\": [{\"text\": \"Tunku, Razak, Hussein Onn, Mahathir, Abdullah, Najib, Mahathir, Muhyiddin, Ismail Sabri.\", \"isCorrect\": true}, {\"text\": \"Tunku, Razak, Hussein Onn, Mahathir, Najib, Abdullah, Mahathir, Muhyiddin, Ismail Sabri.\", \"isCorrect\": false, \"consequence\": \"Album itu disusun dengan giliran yang tersalah. Najib dan Abdullah bertukar tempat dalam sejarahmu.\"}, {\"text\": \"Tunku, Razak, Hussein Onn, Mahathir, Abdullah, Najib, Muhyiddin, Mahathir, Ismail Sabri.\", \"isCorrect\": false, \"consequence\": \"Album itu disusun dengan giliran yang tersalah. Muhyiddin dan Mahathir bertukar tempat dalam sejarahmu.\"}], \"aftermath\": \"Album tersusun dengan giliran yang tidak tepat. Kawan-kawan membaca urutan Perdana Menteri yang tersalah.\", \"turns\": [{\"after\": 10, \"options\": [{\"text\": \"Keempat dan ketujuh.\", \"isCorrect\": true, \"reaction\": \"Tepat, murid! Tun Dr. Mahathir menampal dua kad dengan bangga.\"}, {\"text\": \"Keempat dan kelapan.\", \"isCorrect\": false, \"reaction\": \"Kelapan itu Tan Sri Muhyiddin, murid! Tun Dr. Mahathir menggeleng sambil tersenyum.\"}, {\"text\": \"Ketujuh sahaja dalam album.\", \"isCorrect\": false, \"reaction\": \"Aku muncul pada giliran keempat juga, murid! Tun Dr. Mahathir mengangkat dua jari.\"}], \"clue\": \"Beliau dikira dua kali dalam senarai sembilan giliran.\"}]}');
INSERT INTO `Quest` (`questID`, `sceneID`, `questName`, `instruction`, `questType`, `description`, `questContent`) VALUES
(715, 'e7_n3_s3', 'Nyahkod Kad Tugas Keempat', 'Baca kad keempat yang luntur dan tentukan jawatan yang turut dicadangkan oleh Perdana Menteri.', '5', 'Mengenal pasti tugas-tugas Perdana Menteri.', '{\"clueText\": \"Kad keempat menulis: Perdana Menteri menjalin hubungan diplomatik. Beliau mencadangkan pelantikan duta, diplomat dan satu jawatan lagi. Nama jawatan itu sudah luntur dan tidak kelihatan, tetapi ia berkait dengan perwakilan di negara luar.\", \"options\": [{\"text\": \"Konsulat di negara luar.\", \"isCorrect\": true}, {\"text\": \"Setiausaha di pejabat dalam negeri.\", \"isCorrect\": false, \"consequence\": \"Kad itu dibaca dengan jawatan yang tidak wujud. Album mencatat tugas diplomatik yang tersalah.\"}, {\"text\": \"Jurucakap di Dewan Rakyat.\", \"isCorrect\": false, \"consequence\": \"Kad itu dibaca dengan jawatan yang tidak berkaitan. Album mencatat tugas yang tidak tepat.\"}], \"aftermath\": \"Kad tugas keempat disalah baca. Album mencatat jawatan diplomatik yang tidak tepat.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Dengan negara luar.\", \"isCorrect\": true, \"reaction\": \"Tepat, murid! Dato\' Seri Ismail Sabri mengangguk dan kad itu bersinar.\"}, {\"text\": \"Hanya dengan negeri dalam Malaysia.\", \"isCorrect\": false, \"reaction\": \"Bukan, murid! Dato\' Seri Ismail Sabri menggeleng sambil tersenyum.\"}, {\"text\": \"Hanya dengan Majlis Raja-Raja sahaja.\", \"isCorrect\": false, \"reaction\": \"Bukan, murid! Dato\' Seri Ismail Sabri ketawa kerana itu tugas yang lain.\"}], \"clue\": \"Duta bertugas di luar negara dan bukan di dalam negeri.\"}]}'),
(716, 'e7_n3_s4', 'Padanan Kad: Pencapaian Tiga Perdana Menteri', 'Padankan setiap kad dengan pencapaian yang betul.', '4', 'Mengenal pasti pencapaian Tunku Abdul Rahman, Tun Abdul Razak dan Tun Hussein Onn.', '{\"pairs\": [{\"text\": \"Tunku Abdul Rahman\", \"pair\": 1}, {\"text\": \"Kemerdekaan secara rundingan dan Pembentukan Malaysia\", \"pair\": 1}, {\"text\": \"Tun Abdul Razak\", \"pair\": 2}, {\"text\": \"MAGERAN dan Dasar Ekonomi Baru\", \"pair\": 2}, {\"text\": \"Tun Hussein Onn\", \"pair\": 3}, {\"text\": \"ASNB dan Program Rukun Tetangga\", \"pair\": 3}, {\"text\": \"Dasar Ekonomi Baru\", \"pair\": 4}, {\"text\": \"Membasmi kemiskinan dan menyusun semula masyarakat\", \"pair\": 4}, {\"text\": \"ASNB\", \"pair\": 5}, {\"text\": \"Pemilikan saham bumiputera\", \"pair\": 5}], \"aftermath\": \"Kad pencapaian tersalah padan. Album membawa maklumat yang tidak tepat tentang tiga Perdana Menteri.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Secara rundingan.\", \"isCorrect\": true, \"reaction\": \"Tepat, murid! Tunku mengangguk dan peta di meja seolah-olah bercahaya.\"}, {\"text\": \"Secara peperangan.\", \"isCorrect\": false, \"reaction\": \"Bukan, murid! Tunku menggeleng kerana beliau memilih berunding.\"}, {\"text\": \"Secara pemberontakan.\", \"isCorrect\": false, \"reaction\": \"Bukan, murid! Tunku ketawa kecil dan membetulkan jawapanmu.\"}], \"clue\": \"Tunku memilih cara aman, bukan perang atau pemberontakan.\"}]}'),
(717, 'e7_n3_s5', 'Soalan Kad: Mahathir dan Abdullah', 'Pilih padanan pencapaian yang betul untuk Tun Dr. Mahathir dan Tun Abdullah.', '3', 'Mengenal pasti pencapaian Tun Dr. Mahathir dan Tun Abdullah.', '{\"prompt\": \"Cikgu projek bertanya: yang manakah padanan pencapaian yang betul untuk Tun Dr. Mahathir dan Tun Abdullah?\", \"options\": [{\"text\": \"Tun Dr. Mahathir: Wawasan 2020, Putrajaya, KLIA, KLCC dan HICOM; Tun Abdullah: Koridor Wilayah Ekonomi dan PIN.\", \"isCorrect\": true}, {\"text\": \"Tun Abdullah: Wawasan 2020, Putrajaya, KLIA, KLCC dan HICOM; Tun Dr. Mahathir: Koridor Wilayah Ekonomi dan PIN.\", \"isCorrect\": false, \"consequence\": \"Kad itu disusun dengan tokoh yang tersalah. Album menyatakan Tun Abdullah membina Putrajaya dan KLIA.\"}, {\"text\": \"Tun Dr. Mahathir: Wawasan 2020 dan PIN; Tun Abdullah: Putrajaya, KLIA, KLCC, HICOM dan Koridor Wilayah Ekonomi.\", \"isCorrect\": false, \"consequence\": \"Kad itu bercampur-baur pada dua tokoh. Album menyatakan pencapaian yang tidak tepat.\"}], \"aftermath\": \"Pencapaian dua Perdana Menteri tersalah padan. Album menyatakan tokoh yang tidak tepat.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Pelan Integriti Nasional.\", \"isCorrect\": true, \"reaction\": \"Tepat, murid! Tun Abdullah tersenyum dan kad itu berkilat.\"}, {\"text\": \"Pelan Industri Nasional.\", \"isCorrect\": false, \"reaction\": \"Hampir, murid! Tun Abdullah ketawa kecil dan membetulkan sebutan.\"}, {\"text\": \"Program Integriti Negara.\", \"isCorrect\": false, \"reaction\": \"Hampir, murid! Tun Abdullah menggeleng sambil tersenyum.\"}], \"clue\": \"Singkatan itu menyebut pelan, integriti dan nasional.\"}]}'),
(718, 'e7_n3_s6', 'Susun Tiga Kad Terakhir Album', 'Susun tiga Perdana Menteri yang terakhir beserta pencapaian mereka mengikut giliran.', '1', 'Mengenal pasti pencapaian Najib, Muhyiddin dan Ismail Sabri.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"Perdana Menteri keenam\", \"text\": \"Najib memperkenalkan Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP)\", \"why\": \"Beliau memegang jawatan pada giliran keenam.\"}, {\"id\": 2, \"year\": \"Perdana Menteri kelapan\", \"text\": \"Muhyiddin menubuhkan MTE dan mengumumkan bantuan semasa PKP pandemik COVID-19\", \"why\": \"Beliau memegang jawatan pada giliran kelapan.\"}, {\"id\": 3, \"year\": \"Perdana Menteri kesembilan\", \"text\": \"Ismail Sabri memperkenalkan konsep Keluarga Malaysia\", \"why\": \"Beliau penutup dalam senarai sembilan giliran.\"}], \"aftermath\": \"Tiga kad terakhir tersusun salah. Album menyatakan giliran dan pencapaian yang tidak tepat.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Dato\' Seri Ismail Sabri.\", \"isCorrect\": true, \"reaction\": \"Tepat, murid! Dato\' Seri Ismail Sabri tersenyum dan album pun ditutup dengan tepukan.\"}, {\"text\": \"Tan Sri Muhyiddin Md Yassin.\", \"isCorrect\": false, \"reaction\": \"Bukan, murid! Tan Sri Muhyiddin tersenyum dan menunjuk ke arah Dato\' Seri Ismail Sabri.\"}, {\"text\": \"Dato\' Sri Mohd Najib.\", \"isCorrect\": false, \"reaction\": \"Bukan, murid! Dato\' Seri Ismail Sabri ketawa kerana konsep itu miliknya.\"}], \"clue\": \"Beliau Perdana Menteri kesembilan, penutup dalam senarai.\"}]}'),
(801, 'e8_n1_s1', 'Misi Sawah: Bukti Ekonomi Tradisional', 'Cari bukti ekonomi tradisional pada gambar sawah ini.', '2', 'Membezakan ekonomi tradisional dan ekonomi komersial.', '{\"hotspots\":[{\"name\":\"Cangkul di tepi petak: peralatan mudah ekonomi tradisional\",\"top\":\"78%\",\"left\":\"13.7%\"},{\"name\":\"Cangkul kedua di tepi pagar: modal kecil dan alat sederhana\",\"top\":\"75%\",\"left\":\"86%\"},{\"name\":\"Rumah kayu petani: hasil untuk keperluan sendiri dan keluarga\",\"top\":\"20.8%\",\"left\":\"22.4%\"},{\"name\":\"Petak sawah kecil: dijalankan secara kecil-kecilan\",\"top\":\"39.3%\",\"left\":\"59.9%\"}],\"bgImage\":\"../assets/gameAsset/background/ekonomi_tradisional.png\",\"aftermath\":\"Bukti ekonomi tradisional tersalah cari. Juruteknik menyangka sawah kecil itu ladang komersial.\",\"turns\":[{\"after\":7,\"options\":[{\"text\":\"Keperluan sendiri dan keluarga.\",\"isCorrect\":true,\"reaction\":\"Tepat, juruteknik! Pak Tani tersenyum dan mengetuk cangkulnya dua kali.\"},{\"text\":\"Kegunaan tempatan dan eksport.\",\"isCorrect\":false,\"reaction\":\"Itu hasil ekonomi komersial, juruteknik! Pak Tani ketawa sambil menggeleng.\"},{\"text\":\"Pasaran antarabangsa sahaja.\",\"isCorrect\":false,\"reaction\":\"Bukan, juruteknik! Pak Tani menunjuk ke arah petak kecilnya sambil tersenyum.\"}],\"clue\":\"Hasilnya untuk dapur sendiri, bukan untuk dijual jauh.\"}]}'),
(802, 'e8_n1_s2', 'Soalan Pekebun: Kesan Getah dan Sawit', 'Pilih pernyataan yang betul tentang kesan industri getah dan kelapa sawit.', '3', 'Mengenal pasti kesan industri getah dan kelapa sawit.', '{\"prompt\": \"Seorang pekebun bertanya kepadamu: yang manakah pernyataan yang betul tentang kesan industri getah dan kelapa sawit?\", \"options\": [{\"text\": \"Meningkatkan pendapatan negara, menyediakan peluang pekerjaan dan mewujudkan industri hiliran serta biodiesel.\", \"isCorrect\": true}, {\"text\": \"Hanya menyediakan peluang pekerjaan tanpa menambah pendapatan negara atau mewujudkan industri hiliran.\", \"isCorrect\": false, \"consequence\": \"Pekebun itu pulang dengan maklumat yang tidak lengkap. Dia menyangka industri ini tidak menambah pendapatan negara.\"}, {\"text\": \"Menyebabkan semua ladang ditutup dan menghentikan industri biodiesel serta industri asas tani.\", \"isCorrect\": false, \"consequence\": \"Pekebun itu pulang dengan maklumat yang tersalah. Dia menyangka industri ini menghentikan industri lain.\"}], \"aftermath\": \"Kesan industri getah dan kelapa sawit dijawab tidak tepat. Pekebun pulang dengan maklumat yang tersalah.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Industri getah dan kelapa sawit.\", \"isCorrect\": true, \"reaction\": \"Tepat, juruteknik! Penoreh Getah mengangkat mangkuk susu getahnya seperti menyambut kemenangan.\"}, {\"text\": \"Industri petroleum dan gas.\", \"isCorrect\": false, \"reaction\": \"Bukan, juruteknik! Penoreh Getah ketawa kerana minyak itu datang dari pelantar.\"}, {\"text\": \"Industri pelancongan.\", \"isCorrect\": false, \"reaction\": \"Bukan, juruteknik! Penoreh Getah menggeleng sambil tersenyum.\"}], \"clue\": \"Biodiesel dibangunkan hasil tanaman yang tumbuh di ladang.\"}]}'),
(803, 'e8_n1_s3', 'Padanan Pelantar: Kesan Petroleum dan Gas', 'Padankan setiap kumpulan dengan kesan industri petroleum dan gas.', '4', 'Mengenal pasti kesan industri petroleum dan gas.', '{\"pairs\": [{\"text\": \"Usahawan\", \"pair\": 1}, {\"text\": \"Stesen minyak\", \"pair\": 1}, {\"text\": \"Meningkatkan pendapatan\", \"pair\": 2}, {\"text\": \"Penajaan sukan permotoran\", \"pair\": 2}, {\"text\": \"Pelajar\", \"pair\": 3}, {\"text\": \"Biasiswa\", \"pair\": 3}, {\"text\": \"Pekerja\", \"pair\": 4}, {\"text\": \"Peluang pekerjaan\", \"pair\": 4}], \"aftermath\": \"Kesan industri petroleum dan gas tersalah padan. Pelantar menghantar maklumat yang tidak tepat.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Usahawan stesen minyak.\", \"isCorrect\": true, \"reaction\": \"Tepat, juruteknik! Jurutera mengangkat helmetnya sebagai tanda tabik.\"}, {\"text\": \"Usahawan kedai bunga.\", \"isCorrect\": false, \"reaction\": \"Bukan, juruteknik! Jurutera ketawa kerana pelantar tiada bunga.\"}, {\"text\": \"Usahawan kilang kasut.\", \"isCorrect\": false, \"reaction\": \"Bukan, juruteknik! Jurutera menggeleng sambil menunjuk ke arah stesen minyak.\"}], \"clue\": \"Mereka menjual petrol yang diisi ke dalam kenderaan.\"}]}'),
(804, 'e8_n1_s4', 'Susun Garis Masa Kilang Kereta', 'Susun peristiwa industri automotif mengikut tahun.', '1', 'Mengenal pasti perkembangan industri automotif dan kegiatan pelancongan.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"1983\", \"text\": \"PROTON ditubuhkan\", \"why\": \"Tahun penubuhan PROTON ialah 1983.\"}, {\"id\": 2, \"year\": \"1993\", \"text\": \"PERODUA ditubuhkan\", \"why\": \"Tahun penubuhan PERODUA ialah 1993.\"}, {\"id\": 3, \"year\": \"2018\", \"text\": \"PROTON mengadakan usaha sama dengan Geely Holding Group\", \"why\": \"Usaha sama ini dibuat pada tahun 2018.\"}], \"aftermath\": \"Garis masa kilang kereta tersalah susun. Tahun penubuhan PROTON dan PERODUA bertukar tempat.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Pada tahun 1993.\", \"isCorrect\": true, \"reaction\": \"Tepat, juruteknik! Inspektor mengangguk dan sebuah kereta kecil berbunyi hon.\"}, {\"text\": \"Pada tahun 1983.\", \"isCorrect\": false, \"reaction\": \"Itu tahun PROTON, juruteknik! Inspektor tersenyum sambil menggeleng.\"}, {\"text\": \"Pada tahun 2018.\", \"isCorrect\": false, \"reaction\": \"Itu tahun usaha sama dengan Geely, juruteknik! Inspektor ketawa kecil.\"}], \"clue\": \"Ia ditubuhkan sepuluh tahun selepas PROTON.\"}]}'),
(805, 'e8_n1_s5', 'Nyahkod Catatan Produk Petroleum', 'Baca catatan yang luntur dan tentukan satu lagi produk petroleum jenama Malaysia.', '5', 'Mengenal pasti keluaran barangan jenama Malaysia.', '{\"clueText\": \"Catatan menulis: Produk petroleum jenama Malaysia ialah minyak petrol dan gas untuk memasak. Satu lagi produk sudah luntur dan tidak kelihatan, tetapi ia melincirkan enjin kenderaan.\", \"options\": [{\"text\": \"Minyak pelincir kenderaan.\", \"isCorrect\": true}, {\"text\": \"Minyak masak untuk dapur.\", \"isCorrect\": false, \"consequence\": \"Catatan itu dibaca dengan produk pertanian. Pelanggan menyangka minyak masak ialah produk petroleum.\"}, {\"text\": \"Motosikal untuk perjalanan.\", \"isCorrect\": false, \"consequence\": \"Catatan itu dibaca dengan produk automotif. Pelanggan menyangka motosikal ialah produk petroleum.\"}], \"aftermath\": \"Catatan produk petroleum disalah baca. Pelanggan keliru tentang kumpulan produk.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Produk pertanian.\", \"isCorrect\": true, \"reaction\": \"Tepat, juruteknik! Pemilik kedai menepuk tangan dan rak itu berkilat.\"}, {\"text\": \"Produk petroleum.\", \"isCorrect\": false, \"reaction\": \"Bukan, juruteknik! Pemilik kedai menggeleng kerana sabun satu kumpulan dengan minyak masak.\"}, {\"text\": \"Produk automotif.\", \"isCorrect\": false, \"reaction\": \"Bukan, juruteknik! Pemilik kedai ketawa sambil menunjuk ke arah kereta mainan.\"}], \"clue\": \"Sabun disenaraikan bersama minyak masak dan buah-buahan.\"}]}'),
(806, 'e8_n1_s6', 'Padanan Bandar: Tiga Pencapaian', 'Padankan setiap pencapaian dengan cirinya.', '4', 'Mengenal pasti pencapaian pembangunan, perhubungan dan perdagangan.', '{\"pairs\": [{\"text\": \"Pembangunan\", \"pair\": 1}, {\"text\": \"Bangunan pencakar langit\", \"pair\": 1}, {\"text\": \"Perhubungan\", \"pair\": 2}, {\"text\": \"Jaringan perhubungan moden yang terancang\", \"pair\": 2}, {\"text\": \"Perdagangan\", \"pair\": 3}, {\"text\": \"Kegiatan e-dagang yang semakin berkembang\", \"pair\": 3}], \"aftermath\": \"Pencapaian ekonomi tersalah padan. Peta kemajuan bandar membawa maklumat yang tidak tepat.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Kegiatan e-dagang.\", \"isCorrect\": true, \"reaction\": \"Tepat, juruteknik! Peniaga E-Dagang menekan butang hantar sambil ketawa.\"}, {\"text\": \"Kegiatan jual beli secara tukar barang.\", \"isCorrect\": false, \"reaction\": \"Itu cara lama, juruteknik! Peniaga E-Dagang menggeleng sambil tersenyum.\"}, {\"text\": \"Kegiatan jual beli di pasar kampung sahaja.\", \"isCorrect\": false, \"reaction\": \"Bukan, juruteknik! Peniaga E-Dagang menunjuk ke arah gudang e-dagang.\"}], \"clue\": \"Jual beli dilakukan melalui telefon dan laman web.\"}]}'),
(807, 'e8_n2_s1', 'Padanan Borang Ciri Ekonomi', 'Padankan setiap ciri dengan jenis ekonomi yang betul.', '4', 'Membezakan ekonomi tradisional dan ekonomi komersial.', '{\"pairs\": [{\"text\": \"Tradisional: peralatan\", \"pair\": 1}, {\"text\": \"Cangkul dan sabit\", \"pair\": 1}, {\"text\": \"Komersial: peralatan\", \"pair\": 2}, {\"text\": \"Mesin dan jentera penuai\", \"pair\": 2}, {\"text\": \"Tradisional: modal dan tenaga kerja\", \"pair\": 3}, {\"text\": \"Modal kecil, tenaga kerja sedikit\", \"pair\": 3}, {\"text\": \"Komersial: modal dan tenaga kerja\", \"pair\": 4}, {\"text\": \"Modal besar, tenaga kerja banyak\", \"pair\": 4}, {\"text\": \"Tradisional: hasil\", \"pair\": 5}, {\"text\": \"Keperluan sendiri dan keluarga\", \"pair\": 5}, {\"text\": \"Komersial: hasil\", \"pair\": 6}, {\"text\": \"Kegunaan tempatan dan eksport\", \"pair\": 6}], \"aftermath\": \"Borang ciri ekonomi tersalah padan. Inspektor mencop LULUS pada ciri yang tidak tepat.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Ekonomi komersial.\", \"isCorrect\": true, \"reaction\": \"Tepat, inspektor! Petani Moden menekan cop LULUS di udara sambil ketawa.\"}, {\"text\": \"Ekonomi tradisional.\", \"isCorrect\": false, \"reaction\": \"Itu pakai cangkul dan sabit, inspektor! Pak Tani menggeleng sambil tersenyum.\"}, {\"text\": \"Ekonomi cangkul dan sabit.\", \"isCorrect\": false, \"reaction\": \"Itu ekonomi tradisional, inspektor! Petani Moden menunjuk ke arah jentera penuainya.\"}], \"clue\": \"Mesin dan jentera penuai hadir bersama modal besar dan perladangan.\"}]}'),
(808, 'e8_n2_s2', 'Soalan Murid: Kesan Getah dan Sawit', 'Pilih pernyataan yang betul tentang kesan industri getah dan kelapa sawit.', '3', 'Mengenal pasti kesan industri getah dan kelapa sawit.', '{\"prompt\": \"Seorang pekebun bertanya kepadamu: yang manakah pernyataan yang betul tentang kesan industri getah dan kelapa sawit?\", \"options\": [{\"text\": \"Memajukan industri asas tani dan membangunkan industri biodiesel selain meningkatkan pendapatan negara.\", \"isCorrect\": true}, {\"text\": \"Hanya mewujudkan industri hiliran tanpa menyediakan peluang pekerjaan kepada sesiapa pun di ladang.\", \"isCorrect\": false, \"consequence\": \"Pekebun itu pulang dengan maklumat yang tersalah. Dia menyangka industri ini tidak membuka pekerjaan.\"}, {\"text\": \"Menurunkan pendapatan negara kerana semua hasil getah dan sawit tidak dieksport ke mana-mana.\", \"isCorrect\": false, \"consequence\": \"Pekebun itu pulang dengan maklumat yang tersalah. Dia menyangka industri ini merugikan negara.\"}], \"aftermath\": \"Kesan industri getah dan kelapa sawit dijawab tidak tepat. Pekebun pulang dengan maklumat yang tersalah.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Menyediakan peluang pekerjaan.\", \"isCorrect\": true, \"reaction\": \"Tepat, inspektor! Penoreh Getah tersenyum lebar dan mencop LULUS di borang.\"}, {\"text\": \"Mewujudkan industri biodiesel.\", \"isCorrect\": false, \"reaction\": \"Itu kesan lain, inspektor! Penoreh Getah ketawa sambil menggeleng.\"}, {\"text\": \"Meningkatkan pendapatan negara.\", \"isCorrect\": false, \"reaction\": \"Itu juga kesan lain, inspektor! Penoreh Getah tersenyum dan membetulkan jawapanmu.\"}], \"clue\": \"Penoreh dan pekerja ladang mendapat kerja daripada industri ini.\"}]}'),
(809, 'e8_n2_s3', 'Nyahkod Papan Iklan Litar', 'Baca papan iklan yang luntur dan tentukan sukan yang dinaja oleh industri petroleum dan gas.', '5', 'Mengenal pasti kesan industri petroleum dan gas.', '{\"clueText\": \"Papan iklan menulis: Industri petroleum dan gas meningkatkan pendapatan menerusi penajaan satu jenis sukan. Nama sukan itu sudah luntur dan tidak kelihatan, tetapi ia melibatkan motosikal dan kereta di litar.\", \"options\": [{\"text\": \"Sukan permotoran.\", \"isCorrect\": true}, {\"text\": \"Sukan renang kebangsaan.\", \"isCorrect\": false, \"consequence\": \"Papan iklan itu dibaca dengan sukan yang tidak berkaitan. Penonton menyangka syarikat petroleum menaja renang.\"}, {\"text\": \"Sukan memanah tradisional.\", \"isCorrect\": false, \"consequence\": \"Papan iklan itu dibaca dengan sukan yang tidak berkaitan. Penonton menyangka syarikat petroleum menaja memanah.\"}], \"aftermath\": \"Papan iklan litar disalah baca. Penonton keliru tentang sukan yang dinaja oleh syarikat petroleum.\", \"turns\": [{\"after\": 4, \"options\": [{\"text\": \"Biasiswa untuk pelajar.\", \"isCorrect\": true, \"reaction\": \"Tepat, inspektor! Jurutera mengangkat ibu jari dan sorakan litar bergema.\"}, {\"text\": \"Pinjaman kereta untuk pelajar.\", \"isCorrect\": false, \"reaction\": \"Bukan, inspektor! Jurutera menggeleng sambil ketawa.\"}, {\"text\": \"Tiket perlumbaan percuma sahaja.\", \"isCorrect\": false, \"reaction\": \"Bukan, inspektor! Jurutera tersenyum dan menunjuk ke arah pelajar yang belajar.\"}], \"clue\": \"Bantuan itu untuk pelajar yang belajar di universiti.\"}]}'),
(810, 'e8_n2_s4', 'Misi Hutan: Bukti Tarikan Pelancong', 'Cari bukti tarikan pelancong pada gambar pantai dan hutan ini.', '2', 'Mengenal pasti perkembangan industri automotif dan kegiatan pelancongan.', '{\"hotspots\":[{\"name\":\"Air terjun hutan: alam semula jadi memacu Tahun Melawat Malaysia\",\"top\":\"28.3%\",\"left\":\"27.7%\"},{\"name\":\"Pelancong di jambatan gantung: tarikan alam semula jadi\",\"top\":\"24%\",\"left\":\"5%\"},{\"name\":\"Gua batu kapur: tapak semula jadi yang menarik pelancong\",\"top\":\"64.6%\",\"left\":\"30.1%\"},{\"name\":\"Pelancong bergambar di pantai: Tahun Melawat Malaysia\",\"top\":\"67.8%\",\"left\":\"72.8%\"}],\"bgImage\":\"../assets/gameAsset/background/industri_pelancongan.png\",\"aftermath\":\"Bukti tarikan pelancong tersalah cari. Inspektor menyangka tarikan pelancong hanyalah kilang kereta.\",\"turns\":[{\"after\":5,\"options\":[{\"text\":\"Pada tahun 1983.\",\"isCorrect\":true,\"reaction\":\"Tepat, inspektor! Pemandu Pelancong menepuk tangan dan monyet belanda pun menoleh.\"},{\"text\":\"Pada tahun 1993.\",\"isCorrect\":false,\"reaction\":\"Itu tahun PERODUA, inspektor! Pemandu Pelancong menggeleng sambil tersenyum.\"},{\"text\":\"Pada tahun 2018.\",\"isCorrect\":false,\"reaction\":\"Itu tahun usaha sama dengan Geely, inspektor! Pemandu Pelancong ketawa kecil.\"}],\"clue\":\"PROTON ditubuhkan lebih awal daripada PERODUA.\"}]}'),
(811, 'e8_n2_s5', 'Padanan Barisan Pemeriksaan Produk', 'Padankan setiap kumpulan produk dengan senarai produknya.', '4', 'Mengenal pasti keluaran barangan jenama Malaysia.', '{\"pairs\": [{\"text\": \"Produk pertanian\", \"pair\": 1}, {\"text\": \"Minyak masak, durian, nanas dan sabun\", \"pair\": 1}, {\"text\": \"Produk petroleum\", \"pair\": 2}, {\"text\": \"Petrol, gas memasak dan minyak pelincir\", \"pair\": 2}, {\"text\": \"Produk automotif\", \"pair\": 3}, {\"text\": \"Motosikal dan kereta\", \"pair\": 3}], \"aftermath\": \"Produk jenama Malaysia tersalah padan. Cop LULUS dijatuhkan pada kumpulan yang tidak tepat.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Produk petroleum.\", \"isCorrect\": true, \"reaction\": \"Tepat, inspektor! Pemilik Kedai mencop LULUS pada tong gas.\"}, {\"text\": \"Produk pertanian.\", \"isCorrect\": false, \"reaction\": \"Bukan, inspektor! Pemilik Kedai menggeleng kerana gas bukan hasil tanaman.\"}, {\"text\": \"Produk automotif.\", \"isCorrect\": false, \"reaction\": \"Bukan, inspektor! Pemilik Kedai ketawa sambil menunjuk ke arah kereta.\"}], \"clue\": \"Gas itu datang daripada industri minyak dan gas.\"}]}'),
(812, 'e8_n2_s6', 'Misi Bandar: Bukti Tiga Pencapaian', 'Cari bukti pembangunan, perhubungan dan perdagangan pada gambar bandar ini.', '2', 'Mengenal pasti pencapaian pembangunan, perhubungan dan perdagangan.', '{\"hotspots\":[{\"name\":\"Menara pencakar langit: pembangunan negara\",\"top\":\"25.4%\",\"left\":\"22.1%\"},{\"name\":\"Jambatan, kereta api dan jalan raya: perhubungan moden yang terancang\",\"top\":\"62%\",\"left\":\"38%\"},{\"name\":\"Gudang E-Dagang: perdagangan yang semakin berkembang\",\"top\":\"45%\",\"left\":\"78%\"},{\"name\":\"Papan iklan carta menaik: e-dagang semakin berkembang\",\"top\":\"22%\",\"left\":\"90%\"}],\"bgImage\":\"../assets/gameAsset/background/pencapaian_ekonomi_perhubungan_dan_perdagangan.png\",\"aftermath\":\"Bukti pencapaian bandar tersalah cari. Inspektor mencop LULUS pada bukti yang tidak berkaitan.\",\"turns\":[{\"after\":5,\"options\":[{\"text\":\"Kegiatan e-dagang.\",\"isCorrect\":true,\"reaction\":\"Tepat, inspektor! Peniaga E-Dagang mencop LULUS di skrin telefon.\"},{\"text\":\"Kegiatan tukar barang di pasar.\",\"isCorrect\":false,\"reaction\":\"Itu cara lama, inspektor! Peniaga E-Dagang menggeleng sambil tersenyum.\"},{\"text\":\"Kegiatan jual beli di pasar malam sahaja.\",\"isCorrect\":false,\"reaction\":\"Bukan, inspektor! Peniaga E-Dagang menunjuk ke arah gudang e-dagang.\"}],\"clue\":\"Jual beli melalui telefon dan laman web yang semakin berkembang.\"}]}'),
(813, 'e8_n3_s1', 'Nyahkod Lembaran Nota Kampung', 'Baca lembaran nota yang luntur dan tentukan pasaran yang dituju oleh ekonomi komersial.', '5', 'Membezakan ekonomi tradisional dan ekonomi komersial.', '{\"clueText\": \"Lembaran nota menulis: Ekonomi komersial dijalankan secara perladangan dengan peralatan moden. Hasilnya untuk kegunaan tempatan dan satu lagi pasaran. Pasaran itu sudah luntur dan tidak kelihatan, tetapi ia di luar negara.\", \"options\": [{\"text\": \"Eksport ke luar negara.\", \"isCorrect\": true}, {\"text\": \"Keperluan sendiri dan keluarga.\", \"isCorrect\": false, \"consequence\": \"Nota itu dibaca dengan ciri ekonomi tradisional. Pelanggan menyangka ladang komersial hanya untuk keluarga.\"}, {\"text\": \"Pasar tani di hujung kampung.\", \"isCorrect\": false, \"consequence\": \"Nota itu dibaca dengan pasaran yang terlalu kecil. Pelanggan menyangka ladang komersial hanya berniaga di kampung.\"}], \"aftermath\": \"Nota tentang ekonomi komersial disalah baca. Pelanggan menyangka ladang komersial hanya untuk keluarga.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Cangkul dan sabit.\", \"isCorrect\": true, \"reaction\": \"Tepat, tauke! Pak Tani mengangkat cangkulnya seperti sebuah piala.\"}, {\"text\": \"Mesin dan jentera penuai.\", \"isCorrect\": false, \"reaction\": \"Itu peralatan ekonomi komersial, tauke! Petani Moden menyampuk sambil ketawa.\"}, {\"text\": \"Jentera pembajak berkuasa besar.\", \"isCorrect\": false, \"reaction\": \"Bukan, tauke! Pak Tani menggeleng kerana dia hanya ada alat mudah.\"}], \"clue\": \"Peralatan mudah yang boleh dipegang dengan tangan sahaja.\"}]}'),
(814, 'e8_n3_s2', 'Padanan Rak: Kesan Getah dan Sawit', 'Padankan setiap kesan industri getah dan kelapa sawit dengan kata kerjanya.', '4', 'Mengenal pasti kesan industri getah dan kelapa sawit.', '{\"pairs\": [{\"text\": \"Pendapatan negara\", \"pair\": 1}, {\"text\": \"Ditingkatkan\", \"pair\": 1}, {\"text\": \"Peluang pekerjaan\", \"pair\": 2}, {\"text\": \"Disediakan\", \"pair\": 2}, {\"text\": \"Industri hiliran\", \"pair\": 3}, {\"text\": \"Diwujudkan\", \"pair\": 3}, {\"text\": \"Industri asas tani\", \"pair\": 4}, {\"text\": \"Dimajukan\", \"pair\": 4}, {\"text\": \"Industri biodiesel\", \"pair\": 5}, {\"text\": \"Dibangunkan\", \"pair\": 5}], \"aftermath\": \"Kesan industri getah dan kelapa sawit tersalah padan. Rak di kedai membawa maklumat yang tidak tepat.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Industri getah dan kelapa sawit.\", \"isCorrect\": true, \"reaction\": \"Tepat, tauke! Petani Moden mengangkat buah sawit sebagai tanda kemenangan.\"}, {\"text\": \"Industri petroleum dan gas.\", \"isCorrect\": false, \"reaction\": \"Bukan, tauke! Penoreh Getah ketawa kerana itu industri di pelantar.\"}, {\"text\": \"Industri automotif dan pelancongan.\", \"isCorrect\": false, \"reaction\": \"Bukan, tauke! Petani Moden menggeleng sambil menunjuk ke arah ladang.\"}], \"clue\": \"Industri ini tumbuh di ladang, daripada pokok getah dan kelapa sawit.\"}]}'),
(815, 'e8_n3_s3', 'Soalan Pelanggan: Kesan Petroleum dan Gas', 'Pilih pernyataan yang betul tentang kesan industri petroleum dan gas.', '3', 'Mengenal pasti kesan industri petroleum dan gas.', '{\"prompt\": \"Seorang pelanggan bertanya kepadamu: yang manakah pernyataan yang betul tentang kesan industri petroleum dan gas?\", \"options\": [{\"text\": \"Mewujudkan peluang pekerjaan, melahirkan usahawan stesen minyak dan menyediakan biasiswa.\", \"isCorrect\": true}, {\"text\": \"Hanya melahirkan usahawan stesen minyak dan tidak menyediakan sebarang biasiswa kepada pelajar.\", \"isCorrect\": false, \"consequence\": \"Pelanggan itu pulang dengan maklumat yang tidak lengkap. Dia menyangka biasiswa tidak pernah disediakan.\"}, {\"text\": \"Meningkatkan pendapatan menerusi penajaan tetapi tidak mewujudkan sebarang peluang pekerjaan.\", \"isCorrect\": false, \"consequence\": \"Pelanggan itu pulang dengan maklumat yang tersalah. Dia menyangka industri ini tidak membuka pekerjaan.\"}], \"aftermath\": \"Kesan industri petroleum dan gas dijawab tidak tepat. Pelanggan pulang dengan maklumat yang tersalah.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Melalui penajaan sukan permotoran.\", \"isCorrect\": true, \"reaction\": \"Tepat, tauke! Jurutera tersenyum dan ombak pun menyambut jawapanmu.\"}, {\"text\": \"Melalui penjualan tiket kapal terbang.\", \"isCorrect\": false, \"reaction\": \"Bukan, tauke! Jurutera menggeleng sambil ketawa.\"}, {\"text\": \"Melalui penanaman padi di pelantar.\", \"isCorrect\": false, \"reaction\": \"Bukan, tauke! Jurutera ketawa kerana tiada sawah di tengah laut.\"}], \"clue\": \"Syarikat petroleum menaja perlumbaan motosikal dan kereta.\"}]}'),
(816, 'e8_n3_s4', 'Susun Kad Automotif di Kaunter', 'Susun peristiwa industri automotif mengikut tahun.', '1', 'Mengenal pasti perkembangan industri automotif dan kegiatan pelancongan.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"1983\", \"text\": \"PROTON ditubuhkan\", \"why\": \"PROTON ditubuhkan lebih awal daripada PERODUA.\"}, {\"id\": 2, \"year\": \"1993\", \"text\": \"PERODUA ditubuhkan\", \"why\": \"PERODUA ditubuhkan selepas PROTON.\"}, {\"id\": 3, \"year\": \"2018\", \"text\": \"PROTON mengadakan usaha sama dengan Geely Holding Group\", \"why\": \"Usaha sama ini ialah peristiwa terkini dalam senarai.\"}], \"aftermath\": \"Kad automotif tersalah susun. Pelanggan membaca tahun penubuhan yang tidak tepat.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Geely Holding Group.\", \"isCorrect\": true, \"reaction\": \"Tepat, tauke! Inspektor menepuk bumbung kereta sambil tersenyum.\"}, {\"text\": \"Syarikat PERODUA.\", \"isCorrect\": false, \"reaction\": \"Bukan, tauke! PERODUA ialah syarikat lain yang ditubuhkan pada 1993.\"}, {\"text\": \"Syarikat PETRONAS.\", \"isCorrect\": false, \"reaction\": \"Bukan, tauke! Inspektor ketawa dan menggeleng-geleng.\"}], \"clue\": \"Syarikat luar negara yang namanya mengandungi perkataan Group.\"}]}'),
(817, 'e8_n3_s5', 'Soalan Pelanggan: Produk Jenama Malaysia', 'Pilih pernyataan yang betul tentang kumpulan produk jenama Malaysia.', '3', 'Mengenal pasti keluaran barangan jenama Malaysia.', '{\"prompt\": \"Seorang pelanggan bertanya kepadamu: yang manakah pernyataan yang betul tentang kumpulan produk jenama Malaysia?\", \"options\": [{\"text\": \"Pertanian: minyak masak dan sabun; petroleum: petrol dan gas memasak; automotif: motosikal dan kereta.\", \"isCorrect\": true}, {\"text\": \"Pertanian: motosikal dan sabun; petroleum: petrol dan gas memasak; automotif: minyak masak dan kereta.\", \"isCorrect\": false, \"consequence\": \"Pelanggan itu pulang dengan senarai yang tersalah. Dia menyangka motosikal ialah produk pertanian.\"}, {\"text\": \"Pertanian: minyak masak dan sabun; petroleum: motosikal dan petrol; automotif: gas memasak dan kereta.\", \"isCorrect\": false, \"consequence\": \"Pelanggan itu pulang dengan senarai yang tersalah. Dia menyangka gas memasak ialah produk automotif.\"}], \"aftermath\": \"Produk jenama Malaysia dijawab tidak tepat. Pelanggan pulang dengan senarai yang tersalah.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Buah durian dan buah nanas.\", \"isCorrect\": true, \"reaction\": \"Tepat, tauke! Petani Moden menghulur sebiji durian sebagai hadiah.\"}, {\"text\": \"Minyak petrol dan gas memasak.\", \"isCorrect\": false, \"reaction\": \"Itu produk petroleum, tauke! Petani Moden menggeleng sambil tersenyum.\"}, {\"text\": \"Motosikal dan kereta.\", \"isCorrect\": false, \"reaction\": \"Itu produk automotif, tauke! Petani Moden ketawa kecil.\"}], \"clue\": \"Hasil tanaman dari ladang dan kebun.\"}]}'),
(818, 'e8_n3_s6', 'Nyahkod Nota Perdagangan', 'Baca nota yang luntur dan tentukan kegiatan perdagangan yang semakin berkembang.', '5', 'Mengenal pasti pencapaian pembangunan, perhubungan dan perdagangan.', '{\"clueText\": \"Nota menulis: Perdagangan negara kini ditandai oleh satu kegiatan yang semakin berkembang. Nama kegiatan itu sudah luntur dan tidak kelihatan, tetapi ia dilakukan melalui telefon dan laman web.\", \"options\": [{\"text\": \"Kegiatan e-dagang.\", \"isCorrect\": true}, {\"text\": \"Kegiatan tukar barang di pasar.\", \"isCorrect\": false, \"consequence\": \"Nota itu dibaca dengan cara perdagangan lama. Pelanggan menyangka perdagangan masih tukar barang.\"}, {\"text\": \"Kegiatan menoreh getah di kebun.\", \"isCorrect\": false, \"consequence\": \"Nota itu dibaca dengan kegiatan yang tidak berkaitan. Pelanggan menyangka perdagangan ialah menoreh getah.\"}], \"aftermath\": \"Nota tentang perdagangan disalah baca. Pelanggan menyangka perdagangan masih secara tukar barang.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Jaringan perhubungan moden yang terancang.\", \"isCorrect\": true, \"reaction\": \"Tepat, tauke! Peniaga E-Dagang menekan butang hantar sambil ketawa.\"}, {\"text\": \"Bangunan pencakar langit yang tinggi.\", \"isCorrect\": false, \"reaction\": \"Itu pembangunan, tauke! Peniaga E-Dagang menggeleng sambil tersenyum.\"}, {\"text\": \"Kegiatan e-dagang yang berkembang.\", \"isCorrect\": false, \"reaction\": \"Itu perdagangan, tauke! Peniaga E-Dagang ketawa kecil.\"}], \"clue\": \"Kereta api, jambatan layang dan lebuh raya yang bersambung.\"}]}'),
(901, 'e9_n1_s1', 'Siaran Langsung: Badminton dan Bola Sepak', 'Pilih pernyataan yang betul tentang badminton dan bola sepak Malaysia untuk siaran langsung.', '3', 'Mengenal pasti pencapaian sukan badminton dan bola sepak.', '{\"prompt\": \"Seorang pendengar siaran bertanya: yang manakah pernyataan yang betul tentang badminton dan bola sepak Malaysia?\", \"options\": [{\"text\": \"BAM menguruskan badminton yang juara Piala Thomas lima kali; FAM menguruskan bola sepak yang juara Piala Suzuki AFF 2010.\", \"isCorrect\": true}, {\"text\": \"FAM menguruskan badminton yang juara Piala Thomas lima kali; BAM menguruskan bola sepak yang juara Piala Suzuki AFF 2010.\", \"isCorrect\": false, \"consequence\": \"Siaran menyebut badan pengurusan yang tersalah. Pendengar menyangka FAM menguruskan badminton.\"}, {\"text\": \"BAM menguruskan badminton yang juara Piala Suzuki AFF 2010; FAM menguruskan bola sepak yang juara Piala Thomas lima kali.\", \"isCorrect\": false, \"consequence\": \"Siaran menyebut pencapaian yang tersalah. Pendengar menyangka Piala Thomas dimenangi dalam bola sepak.\"}], \"aftermath\": \"Pencapaian badminton dan bola sepak disiarkan dengan tidak tepat. Pendengar keliru tentang badan pengurusan dan kejohanan.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Lima kali.\", \"isCorrect\": true, \"reaction\": \"Tepat, pengulas! Lee Chong Wei mengangkat raket dan penonton bersorak.\"}, {\"text\": \"Tiga kali sahaja.\", \"isCorrect\": false, \"reaction\": \"Lebih daripada itu, pengulas! Lee Chong Wei mengangkat lima jari sambil tersenyum.\"}, {\"text\": \"Lapan kali.\", \"isCorrect\": false, \"reaction\": \"Terlalu banyak, pengulas! Lee Chong Wei ketawa sambil menggeleng.\"}], \"clue\": \"Bilangannya kurang daripada enam dan lebih daripada tiga.\"}]}'),
(902, 'e9_n1_s2', 'Misi Trek: Bukti Olahraga Malaysia', 'Cari bukti pencapaian olahraga Malaysia pada gambar trek ini.', '2', 'Mengenal pasti pencapaian sukan olahraga dan hoki.', '{\"hotspots\":[{\"name\":\"Pelari pecut: pingat emas 100m Sukan Asia pada 1966 dan 1982\",\"top\":\"45.7%\",\"left\":\"47.5%\"},{\"name\":\"Blok permulaan: acara 100m Sukan Asia\",\"top\":\"77.2%\",\"left\":\"54.5%\"},{\"name\":\"Pegawai berjam randik: pengurusan olahraga oleh KOM\",\"top\":\"60%\",\"left\":\"14.5%\"},{\"name\":\"Pelari kedua: atlet olahraga Malaysia dalam Kejohanan Sukan SEA\",\"top\":\"50.5%\",\"left\":\"70.8%\"}],\"bgImage\":\"../assets/gameAsset/background/olahraga.png\",\"aftermath\":\"Bukti pencapaian olahraga tersalah cari. Pengulas menyiarkan rakaman yang tidak berkaitan.\",\"turns\":[{\"after\":6,\"options\":[{\"text\":\"Pada 1966 dan 1982.\",\"isCorrect\":true,\"reaction\":\"Tepat, pengulas! Dr. Jegathesan menepuk bahu dan pelari berlari lebih laju.\"},{\"text\":\"Pada 1972 dan 1980.\",\"isCorrect\":false,\"reaction\":\"Itu tahun Olimpik bola sepak, pengulas! Dr. Jegathesan menggeleng sambil tersenyum.\"},{\"text\":\"Pada 2010 dan 2017.\",\"isCorrect\":false,\"reaction\":\"Itu tahun lain, pengulas! Dr. Jegathesan ketawa kecil dan menunjuk ke arah papan skor.\"}],\"clue\":\"Dua tahun itu jauh lebih awal daripada tahun 2000.\"}]}'),
(903, 'e9_n1_s3', 'Nyahkod Papan Kemenangan', 'Baca papan kemenangan yang luntur dan tentukan nama atlet kebanggaan yang tidak kelihatan.', '5', 'Mengenal pasti atlet kebanggaan negara.', '{\"clueText\": \"Papan menulis: Lee Chong Wei, Nicol Ann David, S. Kuhan, Pandelela Rinong anak Pamg, Mohd Azizulhasni Awang, Team Secret MY, Nurul Huda Abdullah, Abdul Malek Mohamed Noor, Bonnie Bunyau Gustin, Muhammad Ziyad bin Zolkefli dan Mohamad Ridzuan bin Mohamad Puzi. Satu nama sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Abdul Latif bin Romly.\", \"isCorrect\": true}, {\"text\": \"Dato\' Peter Velappan.\", \"isCorrect\": false, \"consequence\": \"Papan itu dibaca dengan nama tokoh inspirasi. Pendengar menyangka tokoh itu atlet kebanggaan.\"}, {\"text\": \"Mokhtar Dahari.\", \"isCorrect\": false, \"consequence\": \"Papan itu dibaca dengan nama tokoh inspirasi. Pendengar menyangka tokoh itu atlet kebanggaan.\"}], \"aftermath\": \"Nama atlet kebanggaan disalah baca. Senarai yang disiarkan mengandungi nama tokoh inspirasi.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Dua belas orang.\", \"isCorrect\": true, \"reaction\": \"Tepat, pengulas! Lee Chong Wei mengangkat dua belas jari dan seluruh pentas bersorak.\"}, {\"text\": \"Lapan orang.\", \"isCorrect\": false, \"reaction\": \"Lebih ramai daripada itu, pengulas! Lee Chong Wei ketawa sambil mengira lagi.\"}, {\"text\": \"Lima belas orang.\", \"isCorrect\": false, \"reaction\": \"Terlalu banyak, pengulas! Lee Chong Wei menggeleng sambil tersenyum.\"}], \"clue\": \"Hitung semua nama yang naik ke atas pentas tadi.\"}]}'),
(904, 'e9_n1_s4', 'Padanan Papan Nama Program Perpaduan', 'Padankan setiap singkatan dengan nama penuh program sukan perpaduan.', '4', 'Mengenal pasti sukan sebagai alat perpaduan dan keharmonian kaum.', '{\"pairs\": [{\"text\": \"RIMUP\", \"pair\": 1}, {\"text\": \"Rancangan Integrasi Murid untuk Perpaduan\", \"pair\": 1}, {\"text\": \"1M1S\", \"pair\": 2}, {\"text\": \"1Murid 1Sukan\", \"pair\": 2}, {\"text\": \"MSSM\", \"pair\": 3}, {\"text\": \"Kejohanan Majlis Sukan Sekolah Malaysia\", \"pair\": 3}, {\"text\": \"SUKMA\", \"pair\": 4}, {\"text\": \"Temasya Sukan Malaysia\", \"pair\": 4}, {\"text\": \"SUKIPT\", \"pair\": 5}, {\"text\": \"Sukan Institusi Pendidikan Tinggi\", \"pair\": 5}], \"aftermath\": \"Singkatan program sukan tersalah padan. Papan nama stadium membawa maklumat yang tidak tepat.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"1Murid 1Sukan.\", \"isCorrect\": true, \"reaction\": \"Tepat, pengulas! Jurulatih meniup wisel dua kali sebagai tanda lulus.\"}, {\"text\": \"1Malaysia 1Sukan.\", \"isCorrect\": false, \"reaction\": \"Hampir, pengulas! Jurulatih ketawa dan membetulkan kata pertama.\"}, {\"text\": \"1Murid 1Sekolah.\", \"isCorrect\": false, \"reaction\": \"Bukan, pengulas! Jurulatih menggeleng sambil menunjuk ke arah murid yang berlari.\"}], \"clue\": \"Setiap murid menyertai satu sukan.\"}]}'),
(905, 'e9_n1_s5', 'Susun Garis Masa Tuan Rumah Sukan SEA', 'Susun tahun Malaysia menjadi tuan rumah Sukan SEA mengikut urutan.', '1', 'Mengenal pasti penganjuran sukan antarabangsa di Malaysia.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"1965\", \"text\": \"Malaysia menjadi tuan rumah Sukan SEA buat kali pertama dalam senarai\", \"why\": \"Tahun paling awal dalam senarai tuan rumah.\"}, {\"id\": 2, \"year\": \"1971\", \"text\": \"Malaysia menjadi tuan rumah Sukan SEA sekali lagi\", \"why\": \"Datang selepas 1965.\"}, {\"id\": 3, \"year\": \"1977\", \"text\": \"Malaysia menjadi tuan rumah Sukan SEA buat kali ketiga\", \"why\": \"Datang selepas 1971.\"}, {\"id\": 4, \"year\": \"2001\", \"text\": \"Malaysia menjadi tuan rumah Sukan SEA pada abad ke-21\", \"why\": \"Datang selepas jurang yang panjang.\"}, {\"id\": 5, \"year\": \"2017\", \"text\": \"Malaysia menjadi tuan rumah Sukan SEA yang terkini dalam senarai\", \"why\": \"Tahun terkini dalam senarai.\"}], \"aftermath\": \"Garis masa Sukan SEA tersalah susun. Pendengar menyangka tuan rumah tahun terkini berlaku lebih awal.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Enam kali.\", \"isCorrect\": true, \"reaction\": \"Tepat, pengulas! Jurulatih mengangkat enam jari dan stadium bergema.\"}, {\"text\": \"Dua kali sahaja.\", \"isCorrect\": false, \"reaction\": \"Itu bilangan Hoki Piala Dunia, pengulas! Jurulatih menggeleng sambil tersenyum.\"}, {\"text\": \"Sepuluh kali.\", \"isCorrect\": false, \"reaction\": \"Terlalu banyak, pengulas! Jurulatih ketawa kecil.\"}], \"clue\": \"Bilangannya lebih daripada lima dan kurang daripada tujuh.\"}]}'),
(906, 'e9_n1_s6', 'Penutup Siaran: Tokoh Inspirasi Sukan', 'Pilih senarai tokoh inspirasi sukan negara yang betul untuk penutup siaran.', '3', 'Mengenal pasti tokoh inspirasi sukan negara.', '{\"prompt\": \"Seorang peminat bertanya kepadamu: yang manakah senarai tokoh inspirasi sukan negara yang betul?\", \"options\": [{\"text\": \"Sultan Azlan Muhibbuddin Shah, Dato\' Peter Velappan, Dato\' Sieh Kok Chi, Dr. M. Jegathesan, M. Rajamani, Tan Aik Huang dan Mokhtar Dahari.\", \"isCorrect\": true}, {\"text\": \"Sultan Azlan Muhibbuddin Shah, Dato\' Peter Velappan, Dato\' Sieh Kok Chi, Lee Chong Wei, M. Rajamani, Tan Aik Huang dan Mokhtar Dahari.\", \"isCorrect\": false, \"consequence\": \"Peminat itu mencatat senarai yang tersalah. Dia menyangka Lee Chong Wei ialah tokoh inspirasi dalam senarai itu.\"}, {\"text\": \"Sultan Azlan Muhibbuddin Shah, Dato\' Peter Velappan, Nicol Ann David, Dr. M. Jegathesan, M. Rajamani, Tan Aik Huang dan Mokhtar Dahari.\", \"isCorrect\": false, \"consequence\": \"Peminat itu mencatat senarai yang tersalah. Dia menyangka Nicol Ann David ialah tokoh inspirasi dalam senarai itu.\"}], \"aftermath\": \"Senarai tokoh inspirasi dicatat tidak tepat. Peminat pulang dengan nama atlet kebanggaan dalam senarai tokoh.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Mokhtar Dahari.\", \"isCorrect\": true, \"reaction\": \"Tepat, pengulas! Dato\' Peter Velappan mengangguk dan tokoh-tokoh bertepuk tangan.\"}, {\"text\": \"Lee Chong Wei.\", \"isCorrect\": false, \"reaction\": \"Dia atlet kebanggaan, pengulas! Dato\' Peter Velappan tersenyum sambil menggeleng.\"}, {\"text\": \"Nicol Ann David.\", \"isCorrect\": false, \"reaction\": \"Dia juga atlet kebanggaan, pengulas! Dato\' Peter Velappan ketawa kecil.\"}], \"clue\": \"Tokoh inspirasi tidak sama dengan senarai atlet kebanggaan.\"}]}'),
(907, 'e9_n2_s1', 'Nyahkod Papan Skor Olimpik', 'Baca papan skor yang luntur dan tentukan bandar Olimpik tahun 1980 yang tidak kelihatan.', '5', 'Mengenal pasti pencapaian sukan bola sepak.', '{\"clueText\": \"Papan skor menulis: Bola sepak Malaysia layak ke Sukan Olimpik Munich 1972 dan Sukan Olimpik 1980. Nama bandar tuan rumah 1980 sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Moscow.\", \"isCorrect\": true}, {\"text\": \"Montreal.\", \"isCorrect\": false, \"consequence\": \"Papan skor ditulis semula dengan nama bandar yang tersalah. Murid menyangka Olimpik 1980 berlangsung di Montreal.\"}, {\"text\": \"Seoul.\", \"isCorrect\": false, \"consequence\": \"Papan skor ditulis semula dengan nama bandar yang tersalah. Murid menyangka Olimpik 1980 berlangsung di Seoul.\"}], \"aftermath\": \"Papan skor ditulis dengan bandar yang tersalah. Murid menghafal maklumat yang salah.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Persatuan Badminton Malaysia (BAM).\", \"isCorrect\": true, \"reaction\": \"Tepat, cikgu! Lee Chong Wei mengangkat raket sambil tersenyum lebar.\"}, {\"text\": \"Persatuan Bola Sepak Malaysia (FAM).\", \"isCorrect\": false, \"reaction\": \"Itu bola sepak, cikgu! Lee Chong Wei ketawa sambil menunjuk raketnya.\"}, {\"text\": \"Kesatuan Olahraga Malaysia (KOM).\", \"isCorrect\": false, \"reaction\": \"Itu olahraga, cikgu! Lee Chong Wei menggeleng sambil mengangkat kening.\"}], \"clue\": \"BAM ialah singkatan bagi nama badminton.\"}]}'),
(908, 'e9_n2_s2', 'Padanan Badan Sukan Negara', 'Padankan setiap badan sukan negara dengan sukan yang diuruskannya.', '4', 'Mengenal pasti badan pengurusan sukan negara.', '{\"pairs\": [{\"text\": \"Persatuan Badminton Malaysia\", \"pair\": 1}, {\"text\": \"Badminton\", \"pair\": 1}, {\"text\": \"Persatuan Bola Sepak Malaysia\", \"pair\": 2}, {\"text\": \"Bola sepak\", \"pair\": 2}, {\"text\": \"Kesatuan Olahraga Malaysia\", \"pair\": 3}, {\"text\": \"Olahraga\", \"pair\": 3}, {\"text\": \"Konfederasi Hoki Malaysia\", \"pair\": 4}, {\"text\": \"Hoki\", \"pair\": 4}], \"aftermath\": \"Badan sukan tersalah padan dengan sukan. Murid keliru siapa menguruskan apa.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Pada tahun 1975.\", \"isCorrect\": true, \"reaction\": \"Tepat, cikgu! Dr. Jegathesan menepuk bahu sambil ketawa.\"}, {\"text\": \"Pada tahun 1998.\", \"isCorrect\": false, \"reaction\": \"Itu tahun Komanwel, cikgu! Dr. Jegathesan menggeleng sambil tersenyum.\"}, {\"text\": \"Pada tahun 2017.\", \"isCorrect\": false, \"reaction\": \"Itu tahun Sukan SEA, cikgu! Dr. Jegathesan ketawa kecil.\"}], \"clue\": \"Tahun itu pada pertengahan 1970-an.\"}]}'),
(909, 'e9_n2_s3', 'Tepuk Tangan Atlet Kebanggaan', 'Pilih kumpulan yang semuanya atlet kebanggaan negara.', '3', 'Mengenal pasti atlet kebanggaan negara.', '{\"prompt\": \"Seorang murid bertanya kepadamu: yang manakah kumpulan yang semuanya atlet kebanggaan negara?\", \"options\": [{\"text\": \"Nicol Ann David, S. Kuhan, Pandelela Rinong anak Pamg dan Bonnie Bunyau Gustin.\", \"isCorrect\": true}, {\"text\": \"Nicol Ann David, S. Kuhan, Dato\' Sieh Kok Chi dan Bonnie Bunyau Gustin.\", \"isCorrect\": false, \"consequence\": \"Murid itu menulis nama tokoh inspirasi dalam senarai atlet. Dia menyangka Dato\' Sieh Kok Chi atlet kebanggaan.\"}, {\"text\": \"Nicol Ann David, S. Kuhan, Tan Aik Huang dan Bonnie Bunyau Gustin.\", \"isCorrect\": false, \"consequence\": \"Murid itu menulis nama tokoh inspirasi dalam senarai atlet. Dia menyangka Tan Aik Huang atlet kebanggaan.\"}], \"aftermath\": \"Senarai atlet kebanggaan dicatat dengan nama tokoh inspirasi. Murid menghafal senarai yang salah.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Piala Thomas.\", \"isCorrect\": true, \"reaction\": \"Tepat, cikgu! Lee Chong Wei menghadiahkan ibu jari kepada murid.\"}, {\"text\": \"Piala Suzuki AFF.\", \"isCorrect\": false, \"reaction\": \"Itu kejohanan bola sepak, cikgu! Lee Chong Wei ketawa sambil menggeleng.\"}, {\"text\": \"Sukan Komanwel.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, cikgu! Lee Chong Wei tersenyum sambil menunjuk ke arah trofi Piala Thomas.\"}], \"clue\": \"Kejohanan itu bernama sempena nama seorang tokoh badminton.\"}]}'),
(910, 'e9_n2_s4', 'Penjelasan Program Perpaduan', 'Pilih kepanjangan yang betul bagi RIMUP dan 1M1S untuk ibu bapa.', '3', 'Mengenal pasti sukan sebagai alat perpaduan dan keharmonian kaum.', '{\"prompt\": \"Seorang ibu bapa bertanya kepadamu: apakah kepanjangan RIMUP dan 1M1S?\", \"options\": [{\"text\": \"RIMUP ialah Rancangan Integrasi Murid untuk Perpaduan; 1M1S ialah 1Murid 1Sukan.\", \"isCorrect\": true}, {\"text\": \"RIMUP ialah 1Murid 1Sukan; 1M1S ialah Rancangan Integrasi Murid untuk Perpaduan.\", \"isCorrect\": false, \"consequence\": \"Ibu bapa itu menerima maklumat yang bertukar tempat. Dia menyangka RIMUP bermaksud satu murid satu sukan.\"}, {\"text\": \"RIMUP ialah Temasya Sukan Malaysia; 1M1S ialah Sukan Institusi Pendidikan Tinggi.\", \"isCorrect\": false, \"consequence\": \"Ibu bapa itu menerima maklumat program lain. Dia menyangka RIMUP ialah temasya sukan peringkat negara.\"}], \"aftermath\": \"Kepanjangan program dijelaskan dengan tidak tepat. Ibu bapa pulang dengan maklumat yang salah.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"1Murid 1Sukan.\", \"isCorrect\": true, \"reaction\": \"Tepat, cikgu! Pengulas mengangkat mikrofon tanda setuju.\"}, {\"text\": \"1Malaysia 1Sekolah.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, cikgu! Pengulas ketawa sambil menggeleng.\"}, {\"text\": \"1Murid 1Kelas.\", \"isCorrect\": false, \"reaction\": \"Hampir, cikgu! Pengulas mengusik sambil membetulkan perkataan terakhir.\"}], \"clue\": \"Setiap murid menyertai satu sukan.\"}]}'),
(911, 'e9_n2_s5', 'Padanan Acara Sukan Antarabangsa', 'Padankan setiap acara sukan antarabangsa dengan butiran penganjurannya di Malaysia.', '4', 'Mengenal pasti penganjuran sukan antarabangsa di Malaysia.', '{\"pairs\": [{\"text\": \"Piala Thomas\", \"pair\": 1}, {\"text\": \"Berlangsung enam kali di Malaysia\", \"pair\": 1}, {\"text\": \"Hoki Piala Dunia\", \"pair\": 2}, {\"text\": \"Malaysia tuan rumah dua edisi\", \"pair\": 2}, {\"text\": \"Le Tour de Langkawi\", \"pair\": 3}, {\"text\": \"Acara tahunan sejak 1996\", \"pair\": 3}, {\"text\": \"Piala Monsun\", \"pair\": 4}, {\"text\": \"Perahu layar sejak 2005\", \"pair\": 4}, {\"text\": \"Sukan Komanwel\", \"pair\": 5}, {\"text\": \"Tahun 1998, negara Asia pertama\", \"pair\": 5}], \"aftermath\": \"Acara sukan tersalah padan dengan butirannya. Murid mencatat tarikh dan bilangan yang salah.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Sejak tahun 1996.\", \"isCorrect\": true, \"reaction\": \"Tepat, cikgu! Pengulas membunyikan hon basikal.\"}, {\"text\": \"Sejak tahun 2005.\", \"isCorrect\": false, \"reaction\": \"Itu Piala Monsun, cikgu! Pengulas ketawa sambil menunjuk ke arah layar.\"}, {\"text\": \"Sejak tahun 1998.\", \"isCorrect\": false, \"reaction\": \"Itu tahun Komanwel, cikgu! Pengulas menggeleng sambil tersenyum.\"}], \"clue\": \"Ia bermula sebelum tahun 1998.\"}]}');
INSERT INTO `Quest` (`questID`, `sceneID`, `questName`, `instruction`, `questType`, `description`, `questContent`) VALUES
(912, 'e9_n2_s6', 'Nyahkod Dinding Tokoh Inspirasi', 'Baca dinding tokoh yang luntur dan tentukan nama tokoh inspirasi yang tidak kelihatan.', '5', 'Mengenal pasti tokoh inspirasi sukan negara.', '{\"clueText\": \"Dinding menulis: Sultan Azlan Muhibbuddin Shah, Dato\' Peter Velappan, Dato\' Sieh Kok Chi, Dr. M. Jegathesan, M. Rajamani dan Tan Aik Huang. Satu nama lagi sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Mokhtar Dahari.\", \"isCorrect\": true}, {\"text\": \"Nicol Ann David.\", \"isCorrect\": false, \"consequence\": \"Dinding itu ditulis semula dengan nama atlet kebanggaan. Murid menyangka Nicol Ann David tokoh inspirasi.\"}, {\"text\": \"S. Kuhan.\", \"isCorrect\": false, \"consequence\": \"Dinding itu ditulis semula dengan nama atlet kebanggaan. Murid menyangka S. Kuhan tokoh inspirasi.\"}], \"aftermath\": \"Dinding tokoh ditulis dengan nama yang salah. Murid pulang menghafal senarai yang tidak tepat.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Tujuh orang.\", \"isCorrect\": true, \"reaction\": \"Tepat, jurulatih! Dato\' Peter Velappan mengangkat tujuh jari.\"}, {\"text\": \"Lima orang.\", \"isCorrect\": false, \"reaction\": \"Lebih ramai, jurulatih! Dato\' Peter Velappan ketawa sambil mengira semula.\"}, {\"text\": \"Sepuluh orang.\", \"isCorrect\": false, \"reaction\": \"Terlalu banyak, jurulatih! Dato\' Peter Velappan menggeleng sambil tersenyum.\"}], \"clue\": \"Kira semua tokoh yang menyapa tadi.\"}]}'),
(913, 'e9_n3_s1', 'Padanan Kad Pencapaian Badminton dan Bola Sepak', 'Padankan kejohanan dengan pencapaian pada kad dalam buku skrap.', '4', 'Mengenal pasti pencapaian sukan badminton dan bola sepak.', '{\"pairs\": [{\"text\": \"Piala Thomas\", \"pair\": 1}, {\"text\": \"Juara lima kali\", \"pair\": 1}, {\"text\": \"Piala Suzuki AFF\", \"pair\": 2}, {\"text\": \"Juara pada tahun 2010\", \"pair\": 2}, {\"text\": \"Olimpik 1972 dan 1980\", \"pair\": 3}, {\"text\": \"Bola sepak layak\", \"pair\": 3}, {\"text\": \"Perak dan gangsa Olimpik\", \"pair\": 4}, {\"text\": \"Pingat badminton\", \"pair\": 4}], \"aftermath\": \"Kad pencapaian tersalah padan dalam buku skrap. Rakan menyalin maklumat yang salah.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Lima kali.\", \"isCorrect\": true, \"reaction\": \"Tepat, adik! Pengulas mengangkat lima jari dan kamera berkelip.\"}, {\"text\": \"Satu kali.\", \"isCorrect\": false, \"reaction\": \"Lebih daripada itu, adik! Pengulas ketawa sambil mengira semula.\"}, {\"text\": \"Sepuluh kali.\", \"isCorrect\": false, \"reaction\": \"Terlalu banyak, adik! Pengulas menggeleng sambil tersenyum.\"}], \"clue\": \"Bilangannya kurang daripada enam dan lebih daripada empat.\"}]}'),
(914, 'e9_n3_s2', 'Catatan Buku Skrap: Hoki dan Olahraga', 'Pilih catatan buku skrap yang betul tentang hoki dan olahraga.', '3', 'Mengenal pasti pencapaian sukan hoki dan olahraga.', '{\"prompt\": \"Rakanmu hendak menyalin catatan daripada buku skrapmu: yang manakah catatan yang betul tentang hoki dan olahraga?\", \"options\": [{\"text\": \"Hoki layak lapan kali ke Piala Dunia, ke-4 pada 1975; olahraga emas 100m Sukan Asia 1966 dan 1982.\", \"isCorrect\": true}, {\"text\": \"Hoki layak dua kali ke Piala Dunia, ke-4 pada 1975; olahraga emas 100m Sukan Asia 1966 dan 1982.\", \"isCorrect\": false, \"consequence\": \"Rakan menyalin bilangan penyertaan Piala Dunia yang salah. Dia menyangka hoki hanya layak dua kali.\"}, {\"text\": \"Hoki layak lapan kali ke Piala Dunia, ke-4 pada 1975; olahraga emas 100m Sukan Asia 1972 dan 1980.\", \"isCorrect\": false, \"consequence\": \"Rakan menyalin tahun emas Sukan Asia yang salah. Dia menyangka emas olahraga diraih pada 1972 dan 1980.\"}], \"aftermath\": \"Catatan hoki dan olahraga disalin tidak tepat. Rakan membawa pulang tahun dan bilangan yang salah.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Lapan kali.\", \"isCorrect\": true, \"reaction\": \"Tepat, adik! Dr. Jegathesan menepuk bahumu dengan bangga.\"}, {\"text\": \"Dua kali.\", \"isCorrect\": false, \"reaction\": \"Lebih daripada itu, adik! Dr. Jegathesan ketawa sambil membuka lapan jari.\"}, {\"text\": \"Satu kali sahaja.\", \"isCorrect\": false, \"reaction\": \"Lebih banyak, adik! Dr. Jegathesan menggeleng sambil tersenyum.\"}], \"clue\": \"Bilangannya lebih daripada enam.\"}]}'),
(915, 'e9_n3_s3', 'Cari Bukti Kebanggaan di Podium', 'Cari bukti kebanggaan atlet negara pada gambar podium ini.', '2', 'Mengenal pasti atlet kebanggaan negara.', '{\"hotspots\":[{\"name\":\"Pingat emas: lambang kebanggaan atlet negara\",\"top\":\"25.9%\",\"left\":\"27.9%\"},{\"name\":\"Bendera Malaysia: kebanggaan negara\",\"top\":\"23%\",\"left\":\"50.8%\"},{\"name\":\"Trofi diangkat: kejayaan atlet kebanggaan negara\",\"top\":\"37.6%\",\"left\":\"48.1%\"},{\"name\":\"Penonton bersorak: rakyat bangga dengan atlet negara\",\"top\":\"88%\",\"left\":\"15%\"}],\"bgImage\":\"../assets/gameAsset/background/semua_podium_sukan.png\",\"aftermath\":\"Bukti kebanggaan tersalah cari. Buku skrap diisi gambar yang tidak berkaitan.\",\"turns\":[{\"after\":7,\"options\":[{\"text\":\"Berapa jumlah atlet kebanggaan: dua belas orang.\",\"isCorrect\":true,\"reaction\":\"Tepat, adik! Lee Chong Wei mengangkat dua belas jari.\"},{\"text\":\"Berapa jumlah atlet kebanggaan: lima orang.\",\"isCorrect\":false,\"reaction\":\"Lebih ramai, adik! Lee Chong Wei ketawa sambil menunjuk barisan atlet.\"},{\"text\":\"Berapa jumlah atlet kebanggaan: dua puluh orang.\",\"isCorrect\":false,\"reaction\":\"Terlalu banyak, adik! Lee Chong Wei menggeleng sambil tersenyum.\"}],\"clue\":\"Hitung semua atlet yang berbaris tadi.\"}]}'),
(916, 'e9_n3_s4', 'Nyahkod Poster Program Perpaduan', 'Baca poster yang luntur dan tentukan program sukan perpaduan yang tidak kelihatan.', '5', 'Mengenal pasti sukan sebagai alat perpaduan dan keharmonian kaum.', '{\"clueText\": \"Poster menulis: RIMUP, 1M1S, MSSM, SUKMA dan SUKIPT. Satu program lagi sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Sukan Paralimpik.\", \"isCorrect\": true}, {\"text\": \"Piala Thomas.\", \"isCorrect\": false, \"consequence\": \"Poster ditulis semula dengan kejohanan yang tersalah. Murid menyangka Piala Thomas program perpaduan sekolah.\"}, {\"text\": \"Le Tour de Langkawi.\", \"isCorrect\": false, \"consequence\": \"Poster ditulis semula dengan acara yang tersalah. Murid menyangka Le Tour de Langkawi program perpaduan sekolah.\"}], \"aftermath\": \"Poster program ditulis dengan nama yang salah. Murid menyalin senarai program yang tidak tepat.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Temasya Sukan Malaysia.\", \"isCorrect\": true, \"reaction\": \"Tepat, adik! Cikgu mengangguk puas.\"}, {\"text\": \"Sukan Murid Malaysia.\", \"isCorrect\": false, \"reaction\": \"Hampir, adik! Cikgu ketawa dan membetulkan kata terakhir.\"}, {\"text\": \"Sukan Institusi Pendidikan Tinggi.\", \"isCorrect\": false, \"reaction\": \"Itu SUKIPT, adik! Cikgu tersenyum sambil menggeleng.\"}], \"clue\": \"SUKMA ialah temasya peringkat negara.\"}]}'),
(917, 'e9_n3_s5', 'Esei Buku Skrap: Sukan Antarabangsa', 'Pilih pernyataan yang betul tentang penganjuran sukan antarabangsa di Malaysia.', '3', 'Mengenal pasti penganjuran sukan antarabangsa di Malaysia.', '{\"prompt\": \"Cikgu meminta eseimu: yang manakah pernyataan yang betul tentang penganjuran sukan antarabangsa di Malaysia?\", \"options\": [{\"text\": \"Sukan Komanwel 1998 dianjurkan sebagai negara Asia pertama; Le Tour de Langkawi acara tahunan sejak 1996.\", \"isCorrect\": true}, {\"text\": \"Sukan Komanwel 1998 dianjurkan sebagai negara Asia pertama; Le Tour de Langkawi acara tahunan sejak 2005.\", \"isCorrect\": false, \"consequence\": \"Esei itu menulis tahun Le Tour de Langkawi yang salah. Cikgu menandakan tarikh Piala Monsun dicampur dengan Le Tour.\"}, {\"text\": \"Sukan Komanwel 2001 dianjurkan sebagai negara Asia pertama; Le Tour de Langkawi acara tahunan sejak 1996.\", \"isCorrect\": false, \"consequence\": \"Esei itu menulis tahun Komanwel yang salah. Cikgu menandakan tahun itu ialah tahun Sukan SEA.\"}], \"aftermath\": \"Esei menulis maklumat penganjuran yang salah. Cikgu memulangkan esei untuk dibetulkan.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Kejohanan perahu layar.\", \"isCorrect\": true, \"reaction\": \"Tepat, adik! Cikgu mengangkat ibu jari.\"}, {\"text\": \"Kejohanan berbasikal.\", \"isCorrect\": false, \"reaction\": \"Itu Le Tour de Langkawi, adik! Cikgu ketawa sambil menggeleng.\"}, {\"text\": \"Kejohanan hoki.\", \"isCorrect\": false, \"reaction\": \"Bukan, adik! Cikgu menunjuk ke arah layar yang berkibar.\"}], \"clue\": \"Kejohanan itu menggunakan layar dan angin.\"}]}'),
(918, 'e9_n3_s6', 'Nyahkod Dinding Tokoh Sukan SEA', 'Baca dinding yang pudar dan tentukan nama tokoh inspirasi yang tidak kelihatan.', '5', 'Mengenal pasti tokoh inspirasi sukan negara.', '{\"clueText\": \"Dinding menulis: Sultan Azlan Muhibbuddin Shah, Dato\' Peter Velappan, Dato\' Sieh Kok Chi, Dr. M. Jegathesan, M. Rajamani dan Mokhtar Dahari. Satu nama lagi sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Tan Aik Huang.\", \"isCorrect\": true}, {\"text\": \"Soh Chin Ann.\", \"isCorrect\": false, \"consequence\": \"Dinding ditulis semula dengan nama atlet bola sepak. Murid menyangka Soh Chin Ann tokoh inspirasi dalam senarai itu.\"}, {\"text\": \"Lee Chong Wei.\", \"isCorrect\": false, \"consequence\": \"Dinding ditulis semula dengan nama atlet kebanggaan. Murid menyangka Lee Chong Wei tokoh inspirasi dalam senarai itu.\"}], \"aftermath\": \"Dinding tokoh ditulis dengan nama yang salah. Murid menampal senarai tokoh yang tidak tepat.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Tujuh orang.\", \"isCorrect\": true, \"reaction\": \"Tepat, adik! Tan Aik Huang mengangkat tujuh jari.\"}, {\"text\": \"Empat orang.\", \"isCorrect\": false, \"reaction\": \"Lebih ramai, adik! Tan Aik Huang ketawa sambil mengira semula.\"}, {\"text\": \"Dua belas orang.\", \"isCorrect\": false, \"reaction\": \"Itu bilangan atlet kebanggaan, adik! Tan Aik Huang tersenyum sambil menggeleng.\"}], \"clue\": \"Kira semua tokoh yang menyapa tadi.\"}]}'),
(1001, 'e10_n1_s1', 'Padanan Nama Pertubuhan Serantau', 'Padankan nama penuh pertubuhan serantau dengan singkatannya.', '4', 'Mengenal pasti pertubuhan serantau SEAFET, ASA dan ASEAN.', '{\"pairs\": [{\"text\": \"Southeast Asia Friendship and Economic Treaty\", \"pair\": 1}, {\"text\": \"SEAFET\", \"pair\": 1}, {\"text\": \"Association of Southeast Asia\", \"pair\": 2}, {\"text\": \"ASA\", \"pair\": 2}, {\"text\": \"Association of Southeast Asian Nations\", \"pair\": 3}, {\"text\": \"ASEAN\", \"pair\": 3}], \"aftermath\": \"Nama pertubuhan serantau tersalah padan. Dokumen sidang dicetak dengan singkatan yang tidak tepat.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"ASEAN.\", \"isCorrect\": true, \"reaction\": \"Tepat, wakil muda! Wakil Indonesia mengangguk dan bendera di belakangnya berkibar.\"}, {\"text\": \"SEAFET.\", \"isCorrect\": false, \"reaction\": \"SEAFET hanya tiga negara, wakil muda! Wakil Indonesia ketawa sambil menggeleng.\"}, {\"text\": \"ASA.\", \"isCorrect\": false, \"reaction\": \"ASA juga tiga negara sahaja, wakil muda! Wakil Indonesia tersenyum sambil membetulkan.\"}], \"clue\": \"Pertubuhan itu melibatkan lima negara.\"}]}'),
(1002, 'e10_n1_s2', 'Susun Garis Masa Penubuhan Pertubuhan', 'Susun penubuhan pertubuhan mengikut urutan tahun.', '1', 'Mengenal pasti pertubuhan serantau dan antarabangsa.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"1931\", \"text\": \"Komanwel dibentuk pada 11 Disember\", \"why\": \"Tahun paling awal dalam senarai.\"}, {\"id\": 2, \"year\": \"1945\", \"text\": \"PBB ditubuhkan pada 24 Oktober\", \"why\": \"Datang selepas Komanwel.\"}, {\"id\": 3, \"year\": \"1967\", \"text\": \"ASEAN ditubuhkan pada 8 Ogos\", \"why\": \"Datang selepas PBB.\"}, {\"id\": 4, \"year\": \"1969\", \"text\": \"OIC ditubuhkan pada 25 September\", \"why\": \"Tahun paling akhir dalam senarai.\"}], \"aftermath\": \"Garis masa pertubuhan tersalah susun. Delegasi menyangka OIC lebih tua daripada Komanwel.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"57 buah negara.\", \"isCorrect\": true, \"reaction\": \"Tepat, wakil muda! Wakil OIC mengangkat kedua-dua tangan tanda bangga.\"}, {\"text\": \"120 buah negara.\", \"isCorrect\": false, \"reaction\": \"Itu bilangan NAM, wakil muda! Wakil OIC tersenyum sambil menunjuk ke arah duta NAM.\"}, {\"text\": \"54 buah negara.\", \"isCorrect\": false, \"reaction\": \"Itu bilangan Komanwel, wakil muda! Wakil OIC ketawa kecil.\"}], \"clue\": \"Bilangannya lebih daripada lima puluh.\"}]}'),
(1003, 'e10_n1_s3', 'Nyahkod Dokumen Penubuhan ASEAN', 'Baca dokumen ASEAN yang luntur dan tentukan bandar ibu pejabat yang tidak kelihatan.', '5', 'Mengenal pasti latar belakang, matlamat dan sumbangan Malaysia dalam ASEAN.', '{\"clueText\": \"Dokumen menulis: ASEAN ditubuhkan pada 8 Ogos 1967 dan dianggotai 10 negara Asia Tenggara. Nama bandar ibu pejabatnya sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Jakarta, Indonesia.\", \"isCorrect\": true}, {\"text\": \"Bangkok, Thailand.\", \"isCorrect\": false, \"consequence\": \"Dokumen ditulis semula dengan ibu pejabat yang tersalah. Delegasi menyangka ibu pejabat ASEAN di Bangkok.\"}, {\"text\": \"Manila, Filipina.\", \"isCorrect\": false, \"consequence\": \"Dokumen ditulis semula dengan ibu pejabat yang tersalah. Delegasi menyangka ibu pejabat ASEAN di Manila.\"}], \"aftermath\": \"Ibu pejabat ASEAN ditulis tidak tepat. Delegasi tersalah arah ke bandar lain.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Zon Aman, Bebas dan Berkecuali.\", \"isCorrect\": true, \"reaction\": \"Tepat, wakil muda! Pakar ekonomi menepuk meja tanda setuju.\"}, {\"text\": \"Zon Aman, Bebas dan Bersenjata.\", \"isCorrect\": false, \"reaction\": \"Terbalik maksudnya, wakil muda! Pakar ekonomi menggeleng sambil ketawa.\"}, {\"text\": \"Zon Aman, Bersatu dan Berkuasa.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, wakil muda! Pakar ekonomi mengangkat kening.\"}], \"clue\": \"Ia bermaksud aman, bebas dan tidak memihak.\"}]}'),
(1004, 'e10_n1_s4', 'Penjelasan Komanwel dan OIC', 'Pilih pernyataan yang betul tentang Komanwel dan OIC untuk delegasi.', '3', 'Mengenal pasti latar belakang dan sumbangan Malaysia dalam Komanwel dan OIC.', '{\"prompt\": \"Seorang delegasi bertanya kepadamu: yang manakah pernyataan yang betul tentang Komanwel dan OIC?\", \"options\": [{\"text\": \"Komanwel berpusat di London dan Malaysia menjadi tuan rumah CHOGM 1989; OIC berpusat di Jeddah dan Tunku Setiausaha Agung pertamanya.\", \"isCorrect\": true}, {\"text\": \"Komanwel berpusat di Jeddah dan Malaysia menjadi tuan rumah CHOGM 1989; OIC berpusat di London dan Tunku Setiausaha Agung pertamanya.\", \"isCorrect\": false, \"consequence\": \"Delegasi mencatat ibu pejabat yang bertukar tempat. Dia menyangka Komanwel berpusat di Jeddah.\"}, {\"text\": \"Komanwel berpusat di London dan Malaysia menjadi tuan rumah CHOGM 1974; OIC berpusat di Jeddah dan Tunku Setiausaha Agung pertamanya.\", \"isCorrect\": false, \"consequence\": \"Delegasi mencatat tahun CHOGM yang salah. Dia menyangka CHOGM dianjurkan pada tahun persidangan OIC 1974.\"}], \"aftermath\": \"Maklumat Komanwel dan OIC dicatat dengan tidak tepat. Delegasi pulang membawa ibu pejabat dan tahun yang salah.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Universiti Islam Antarabangsa Malaysia (UIAM).\", \"isCorrect\": true, \"reaction\": \"Tepat, wakil muda! Wakil OIC mengangguk puas.\"}, {\"text\": \"Universiti Kebangsaan Malaysia (UKM) di Bangi.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, wakil muda! Wakil OIC tersenyum sambil menggeleng.\"}, {\"text\": \"Universiti Putra Malaysia (UPM) di Serdang.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, wakil muda! Wakil OIC mengangkat kening.\"}], \"clue\": \"Namanya mengandungi perkataan Islam dan antarabangsa.\"}]}'),
(1005, 'e10_n1_s5', 'Cari Bukti Sumbangan Malaysia di PBB', 'Cari bukti sumbangan dan pengiktirafan Malaysia di dewan sidang PBB.', '2', 'Mengenal pasti sumbangan Malaysia kepada PBB dan pengiktirafan PBB kepada Malaysia.', '{\"hotspots\":[{\"name\":\"Dewan sidang: keahlian PBB terbuka kepada semua negara\",\"top\":\"42.2%\",\"left\":\"26.9%\"},{\"name\":\"Bendera Malaysia: negara anggota PBB yang aktif menyumbang\",\"top\":\"25.6%\",\"left\":\"26.5%\"},{\"name\":\"Peta dunia di skrin: pasukan pengaman PBB termasuk Malaysia\",\"top\":\"22.3%\",\"left\":\"92.5%\"},{\"name\":\"Peta di skrin utama: kawasan tugas pasukan pengaman PBB\",\"top\":\"73.6%\",\"left\":\"49.5%\"}],\"bgImage\":\"../assets/gameAsset/background/malaysia_di_pentas_dunia.png\",\"aftermath\":\"Bukti sumbangan Malaysia tersalah cari. Wakil PBB menolak laporan yang tidak lengkap.\",\"turns\":[{\"after\":6,\"options\":[{\"text\":\"Sijil dan pingat perkhidmatan PBB.\",\"isCorrect\":true,\"reaction\":\"Tepat, wakil muda! Penjaga keamanan memberi tabik hormat.\"},{\"text\":\"Wang tunai untuk setiap anggota.\",\"isCorrect\":false,\"reaction\":\"Bukan itu, wakil muda! Penjaga keamanan ketawa sambil menggeleng.\"},{\"text\":\"Kerusi tetap di dewan sidang.\",\"isCorrect\":false,\"reaction\":\"Bukan itu, wakil muda! Penjaga keamanan tersenyum sambil menunjuk ke arah pingat di dadanya.\"}],\"clue\":\"Pengiktirafan itu boleh dipakai di dada.\"}]}'),
(1006, 'e10_n1_s6', 'Penerangan Warisan Dunia UNESCO', 'Pilih pernyataan yang betul tentang Tapak Warisan Dunia UNESCO di Malaysia.', '3', 'Mengenal pasti pengiktirafan UNESCO kepada Malaysia.', '{\"prompt\": \"Seorang pelawat bertanya kepadamu: yang manakah pernyataan yang betul tentang Tapak Warisan Dunia UNESCO di Malaysia?\", \"options\": [{\"text\": \"Mulu dan Kinabalu diiktiraf pada 2000, Melaka dan George Town pada 2008, dan Lembah Lenggong pada 2012.\", \"isCorrect\": true}, {\"text\": \"Mulu dan Kinabalu diiktiraf pada 2008, Melaka dan George Town pada 2000, dan Lembah Lenggong pada 2012.\", \"isCorrect\": false, \"consequence\": \"Pelawat menulis tahun yang bertukar tempat. Dia menyangka Melaka diiktiraf lebih awal daripada Mulu.\"}, {\"text\": \"Mulu dan Kinabalu diiktiraf pada 2000, Melaka dan George Town pada 2012, dan Lembah Lenggong pada 2008.\", \"isCorrect\": false, \"consequence\": \"Pelawat menulis tahun yang bertukar tempat. Dia menyangka Lenggong diiktiraf lebih awal daripada Melaka.\"}], \"aftermath\": \"Tahun pengiktirafan UNESCO dicatat tidak tepat. Pelawat membawa pulang urutan yang salah.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Silat diiktiraf pada tahun 2019.\", \"isCorrect\": true, \"reaction\": \"Tepat, wakil muda! Pemandu pameran mengangguk bangga.\"}, {\"text\": \"Silat diiktiraf pada tahun 2005.\", \"isCorrect\": false, \"reaction\": \"Itu tahun Makyung, wakil muda! Pemandu pameran tersenyum sambil membetulkan.\"}, {\"text\": \"Silat diiktiraf pada tahun 2020.\", \"isCorrect\": false, \"reaction\": \"Itu tahun Wangkang, wakil muda! Pemandu pameran ketawa kecil.\"}], \"clue\": \"Tahun itu sebelum tahun 2020.\"}]}'),
(1007, 'e10_n2_s1', 'Kuiz Sidang Serantau', 'Pilih pernyataan yang betul tentang SEAFET, ASA dan ASEAN untuk wakil sidang.', '3', 'Mengenal pasti pertubuhan serantau SEAFET, ASA dan ASEAN.', '{\"prompt\": \"Seorang wakil bertanya kepadamu: yang manakah pernyataan yang betul tentang SEAFET, ASA dan ASEAN?\", \"options\": [{\"text\": \"SEAFET dan ASA dianggotai Tanah Melayu, Thailand dan Filipina; ASEAN dianggotai lima negara termasuk Indonesia dan Singapura.\", \"isCorrect\": true}, {\"text\": \"SEAFET dan ASA dianggotai Tanah Melayu, Indonesia dan Singapura; ASEAN dianggotai tiga negara termasuk Thailand dan Filipina.\", \"isCorrect\": false, \"consequence\": \"Wakil itu mencatat anggota yang bertukar tempat. Dia menyangka Indonesia dan Singapura anggota SEAFET.\"}, {\"text\": \"SEAFET dan ASA dianggotai Tanah Melayu, Thailand dan Filipina; ASEAN dianggotai tiga negara termasuk Indonesia dan Singapura.\", \"isCorrect\": false, \"consequence\": \"Wakil itu mencatat bilangan anggota ASEAN yang salah. Dia menyangka ASEAN hanya tiga negara.\"}], \"aftermath\": \"Anggota pertubuhan serantau dicatat tidak tepat. Wakil membawa nota yang salah ke sidang.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Association of Southeast Asia.\", \"isCorrect\": true, \"reaction\": \"Tepat, penjaga! Pakar ekonomi mengangkat ibu jari.\"}, {\"text\": \"Alliance of Southeast Asian States.\", \"isCorrect\": false, \"reaction\": \"Hampir, penjaga! Pakar ekonomi ketawa sambil membetulkan perkataan pertama.\"}, {\"text\": \"Association of South Asian Allies.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, penjaga! Pakar ekonomi menggeleng sambil tersenyum.\"}], \"clue\": \"Huruf pertama ASA ialah Association.\"}]}'),
(1008, 'e10_n2_s2', 'Padanan Pertubuhan Antarabangsa', 'Padankan setiap pertubuhan antarabangsa dengan keahliannya.', '4', 'Mengenal pasti pertubuhan antarabangsa Komanwel, PBB, OIC dan NAM.', '{\"pairs\": [{\"text\": \"Komanwel\", \"pair\": 1}, {\"text\": \"Bekas tanah jajahan British\", \"pair\": 1}, {\"text\": \"PBB\", \"pair\": 2}, {\"text\": \"Terbuka kepada semua negara\", \"pair\": 2}, {\"text\": \"OIC\", \"pair\": 3}, {\"text\": \"57 buah negara Islam\", \"pair\": 3}, {\"text\": \"NAM\", \"pair\": 4}, {\"text\": \"120 buah negara membangun\", \"pair\": 4}], \"aftermath\": \"Keahlian pertubuhan antarabangsa tersalah padan. Pintu bilik mesyuarat tertukar tempat.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"PBB.\", \"isCorrect\": true, \"reaction\": \"Tepat, penjaga! Wakil PBB menghadiahkan tabik hormat.\"}, {\"text\": \"Komanwel.\", \"isCorrect\": false, \"reaction\": \"Komanwel dibentuk pada tahun 1931, penjaga! Wakil PBB tersenyum sambil membetulkan.\"}, {\"text\": \"OIC.\", \"isCorrect\": false, \"reaction\": \"OIC ditubuhkan pada tahun 1969, penjaga! Wakil PBB ketawa kecil.\"}], \"clue\": \"Ia ditubuhkan selepas tahun 1931 dan sebelum tahun 1967.\"}]}'),
(1009, 'e10_n2_s3', 'Cari Bukti di Bilik ASEAN', 'Cari bukti maklumat ASEAN dan sumbangan Malaysia di bilik mesyuarat ini.', '2', 'Mengenal pasti latar belakang, matlamat dan sumbangan Malaysia dalam ASEAN.', '{\"hotspots\":[{\"name\":\"Bendera Malaysia: tuan rumah Mesyuarat Menteri Luar ASEAN\",\"top\":\"44.2%\",\"left\":\"27.2%\"},{\"name\":\"Peta Asia Tenggara: ASEAN dianggotai 10 negara Asia Tenggara\",\"top\":\"21.3%\",\"left\":\"25.5%\"},{\"name\":\"Bendera Singapura: salah satu negara awal ASEAN\",\"top\":\"46.6%\",\"left\":\"72.2%\"},{\"name\":\"Dokumen perjanjian: matlamat keamanan dan kestabilan politik\",\"top\":\"81.3%\",\"left\":\"24.4%\"}],\"bgImage\":\"../assets/gameAsset/background/bilik_mesyuarat.png\",\"aftermath\":\"Bukti ASEAN tersalah cari. Penjaga melaporkan bilik yang tidak lengkap.\",\"turns\":[{\"after\":5,\"options\":[{\"text\":\"10 negara.\",\"isCorrect\":true,\"reaction\":\"Tepat, penjaga! Pakar ekonomi mengira sepuluh bendera di meja.\"},{\"text\":\"5 negara.\",\"isCorrect\":false,\"reaction\":\"Itu bilangan pengasas awal, penjaga! Pakar ekonomi tersenyum sambil menunjuk bendera lain.\"},{\"text\":\"57 negara.\",\"isCorrect\":false,\"reaction\":\"Itu bilangan OIC, penjaga! Pakar ekonomi ketawa kecil.\"}],\"clue\":\"Bilangannya tepat sepuluh.\"}]}'),
(1010, 'e10_n2_s4', 'Nyahkod Catatan OIC', 'Baca catatan OIC yang luntur dan tentukan bandar ibu pejabat yang tidak kelihatan.', '5', 'Mengenal pasti latar belakang dan sumbangan Malaysia dalam Komanwel dan OIC.', '{\"clueText\": \"Catatan menulis: OIC ditubuhkan pada 25 September 1969 dan dianggotai 57 negara Islam. Nama bandar ibu pejabatnya sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Jeddah, Arab Saudi.\", \"isCorrect\": true}, {\"text\": \"London, England.\", \"isCorrect\": false, \"consequence\": \"Catatan ditulis semula dengan ibu pejabat yang tersalah. Penjaga menyangka ibu pejabat OIC di London.\"}, {\"text\": \"New York, Amerika Syarikat.\", \"isCorrect\": false, \"consequence\": \"Catatan ditulis semula dengan ibu pejabat yang tersalah. Penjaga menyangka ibu pejabat OIC di New York.\"}], \"aftermath\": \"Ibu pejabat OIC ditulis tidak tepat. Penjaga menghantar utusan ke bandar yang salah.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Tunku Abdul Rahman.\", \"isCorrect\": true, \"reaction\": \"Tepat, penjaga! Sukarelawan itu memberi tabik hormat kepada Tunku.\"}, {\"text\": \"Tun Abdul Razak.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, penjaga! Sukarelawan itu tersenyum sambil menunjuk ke arah Tunku.\"}, {\"text\": \"Tun Hussein Onn.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, penjaga! Sukarelawan itu ketawa kecil.\"}], \"clue\": \"Beliau juga Perdana Menteri pertama Malaysia.\"}]}'),
(1011, 'e10_n2_s5', 'Kuiz Pusat Operasi PBB', 'Pilih pernyataan yang betul tentang PBB dan sumbangan Malaysia.', '3', 'Mengenal pasti sumbangan Malaysia kepada PBB dan pengiktirafan PBB kepada Malaysia.', '{\"prompt\": \"Seorang rekrut bertanya kepadamu: yang manakah pernyataan yang betul tentang PBB dan sumbangan Malaysia?\", \"options\": [{\"text\": \"PBB berpusat di New York; pasukan pengaman Malaysia diiktiraf melalui sijil dan pingat perkhidmatan PBB.\", \"isCorrect\": true}, {\"text\": \"PBB berpusat di London; pasukan pengaman Malaysia diiktiraf melalui sijil dan pingat perkhidmatan PBB.\", \"isCorrect\": false, \"consequence\": \"Rekrut itu menulis ibu pejabat PBB yang salah. Dia menyangka PBB berpusat di London.\"}, {\"text\": \"PBB berpusat di New York; pasukan pengaman Malaysia diiktiraf melalui wang tunai dan kerusi tetap PBB.\", \"isCorrect\": false, \"consequence\": \"Rekrut itu menulis pengiktirafan yang salah. Dia menyangka pasukan pengaman menerima wang tunai.\"}], \"aftermath\": \"Maklumat PBB dan pengiktirafan dicatat tidak tepat. Rekrut membawa pulang nota yang salah.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Datuk Dr. Mazlan Othman.\", \"isCorrect\": true, \"reaction\": \"Tepat, penjaga! Wakil PBB mendongak ke langit sambil tersenyum.\"}, {\"text\": \"Tan Sri Razali Ismail.\", \"isCorrect\": false, \"reaction\": \"Beliau Pengerusi Majlis Keselamatan, penjaga! Wakil PBB menggeleng sambil tersenyum.\"}, {\"text\": \"Tunku Abdul Rahman.\", \"isCorrect\": false, \"reaction\": \"Beliau Setiausaha Agung OIC, penjaga! Wakil PBB ketawa kecil.\"}], \"clue\": \"Beliau seorang wanita yang berkhidmat dalam bidang angkasa lepas.\"}]}'),
(1012, 'e10_n2_s6', 'Susun Garis Masa Pengiktirafan UNESCO', 'Susun pengiktirafan UNESCO kepada Malaysia mengikut urutan tahun.', '1', 'Mengenal pasti pengiktirafan UNESCO kepada Malaysia.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"2000\", \"text\": \"Taman Negara Gunung Mulu dan Taman Kinabalu menjadi Tapak Warisan Dunia\", \"why\": \"Tahun paling awal dalam senarai.\"}, {\"id\": 2, \"year\": \"2005\", \"text\": \"Makyung diiktiraf sebagai Warisan Budaya Tidak Ketara\", \"why\": \"Datang selepas tapak alam semula jadi.\"}, {\"id\": 3, \"year\": \"2008\", \"text\": \"Melaka dan George Town menjadi Tapak Warisan Dunia\", \"why\": \"Datang selepas Makyung.\"}, {\"id\": 4, \"year\": \"2012\", \"text\": \"Warisan Arkeologi Lembah Lenggong menjadi Tapak Warisan Dunia\", \"why\": \"Datang selepas Melaka dan George Town.\"}, {\"id\": 5, \"year\": \"2019\", \"text\": \"Silat diiktiraf sebagai Warisan Budaya Tidak Ketara\", \"why\": \"Tahun paling akhir dalam senarai.\"}], \"aftermath\": \"Garis masa pengiktirafan UNESCO tersalah susun. Pemandu pameran menunda lampu kotak kaca.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Tahun 2009.\", \"isCorrect\": true, \"reaction\": \"Tepat, penjaga! Pemandu pameran menyalakan lampu kotak kaca.\"}, {\"text\": \"Tahun 2001.\", \"isCorrect\": false, \"reaction\": \"Itu tahun Hikayat Hang Tuah, penjaga! Pemandu pameran tersenyum sambil membetulkan.\"}, {\"text\": \"Tahun 2018.\", \"isCorrect\": false, \"reaction\": \"Itu tahun Dondang Sayang, penjaga! Pemandu pameran ketawa kecil.\"}], \"clue\": \"Tahun itu sebelum tahun 2010.\"}]}'),
(1013, 'e10_n3_s1', 'Nyahkod Papan Nama Anggota SEAFET', 'Baca papan nama yang luntur dan tentukan negara anggota SEAFET yang tidak kelihatan.', '5', 'Mengenal pasti pertubuhan serantau SEAFET, ASA dan ASEAN.', '{\"clueText\": \"Papan menulis: SEAFET dan ASA dianggotai Tanah Melayu, Thailand dan satu negara lagi. Nama negara itu sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Filipina.\", \"isCorrect\": true}, {\"text\": \"Indonesia.\", \"isCorrect\": false, \"consequence\": \"Papan ditulis semula dengan negara yang tersalah. Pelawat menyangka Indonesia anggota SEAFET.\"}, {\"text\": \"Singapura.\", \"isCorrect\": false, \"consequence\": \"Papan ditulis semula dengan negara yang tersalah. Pelawat menyangka Singapura anggota SEAFET.\"}], \"aftermath\": \"Anggota SEAFET ditulis tidak tepat. Pelawat membawa pulang catatan yang salah.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Association of Southeast Asian Nations.\", \"isCorrect\": true, \"reaction\": \"Tepat, pemandu! Wakil Indonesia menepuk tangan.\"}, {\"text\": \"Alliance of Southeast Asian National States.\", \"isCorrect\": false, \"reaction\": \"Hampir, pemandu! Wakil Indonesia ketawa sambil membetulkan.\"}, {\"text\": \"Association of Southeast Asia Navies.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, pemandu! Wakil Indonesia menggeleng sambil tersenyum.\"}], \"clue\": \"Perkataan terakhirnya ialah Nations.\"}]}'),
(1014, 'e10_n3_s2', 'Penerangan Pertubuhan Antarabangsa', 'Pilih pernyataan yang betul tentang Komanwel, PBB, OIC dan NAM untuk pelawat.', '3', 'Mengenal pasti pertubuhan antarabangsa Komanwel, PBB, OIC dan NAM.', '{\"prompt\": \"Seorang pelawat bertanya kepadamu: yang manakah pernyataan yang betul tentang Komanwel, PBB, OIC dan NAM?\", \"options\": [{\"text\": \"Komanwel: bekas jajahan British; PBB: semua negara; OIC: 57 negara Islam; NAM: 120 negara membangun.\", \"isCorrect\": true}, {\"text\": \"Komanwel: bekas jajahan British; PBB: semua negara; OIC: 120 negara Islam; NAM: 57 negara membangun.\", \"isCorrect\": false, \"consequence\": \"Pelawat menulis bilangan OIC dan NAM yang bertukar tempat. Dia menyangka OIC 120 negara.\"}, {\"text\": \"Komanwel: semua negara; PBB: bekas jajahan British; OIC: 57 negara Islam; NAM: 120 negara membangun.\", \"isCorrect\": false, \"consequence\": \"Pelawat menulis keahlian Komanwel dan PBB yang bertukar tempat. Dia menyangka PBB hanya untuk bekas jajahan British.\"}], \"aftermath\": \"Keahlian pertubuhan antarabangsa dicatat tidak tepat. Pelawat membawa pulang nota yang salah.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"120 buah negara.\", \"isCorrect\": true, \"reaction\": \"Tepat, pemandu! Duta NAM mengangkat ibu jari.\"}, {\"text\": \"57 buah negara.\", \"isCorrect\": false, \"reaction\": \"Itu bilangan OIC, pemandu! Duta NAM tersenyum sambil menunjuk ke arah wakil OIC.\"}, {\"text\": \"54 buah negara.\", \"isCorrect\": false, \"reaction\": \"Itu bilangan Komanwel, pemandu! Duta NAM ketawa kecil.\"}], \"clue\": \"Bilangannya lebih daripada seratus.\"}]}'),
(1015, 'e10_n3_s3', 'Padanan Kad Pameran ASEAN', 'Padankan setiap butiran ASEAN dengan jawapannya.', '4', 'Mengenal pasti latar belakang, matlamat dan sumbangan Malaysia dalam ASEAN.', '{\"pairs\": [{\"text\": \"Tarikh penubuhan ASEAN\", \"pair\": 1}, {\"text\": \"8 Ogos 1967\", \"pair\": 1}, {\"text\": \"Ibu pejabat ASEAN\", \"pair\": 2}, {\"text\": \"Jakarta, Indonesia\", \"pair\": 2}, {\"text\": \"Bilangan anggota ASEAN\", \"pair\": 3}, {\"text\": \"10 negara Asia Tenggara\", \"pair\": 3}, {\"text\": \"Dikemukakan oleh Malaysia\", \"pair\": 4}, {\"text\": \"ZOPFAN\", \"pair\": 4}, {\"text\": \"Disertai oleh Malaysia\", \"pair\": 5}, {\"text\": \"SEAMEO\", \"pair\": 5}], \"aftermath\": \"Kad pameran ASEAN tersalah padan. Pelawat menyalin butiran yang salah.\", \"turns\": [{\"after\": 5, \"options\": [{\"text\": \"Zon Aman, Bebas dan Berkecuali.\", \"isCorrect\": true, \"reaction\": \"Tepat, pemandu! Pakar ekonomi menepuk tangan.\"}, {\"text\": \"Zon Aman, Bebas dan Bersenjata.\", \"isCorrect\": false, \"reaction\": \"Terbalik maksudnya, pemandu! Pakar ekonomi menggeleng sambil ketawa.\"}, {\"text\": \"Zon Aman, Bersatu dan Berkuasa.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, pemandu! Pakar ekonomi mengangkat kening.\"}], \"clue\": \"Ia bermaksud aman, bebas dan tidak memihak.\"}]}'),
(1016, 'e10_n3_s4', 'Susun Garis Masa Sumbangan Malaysia dalam OIC dan Komanwel', 'Susun peristiwa OIC dan Komanwel yang melibatkan Malaysia mengikut urutan tahun.', '1', 'Mengenal pasti latar belakang dan sumbangan Malaysia dalam Komanwel dan OIC.', '{\"timelineItems\": [{\"id\": 1, \"year\": \"1969\", \"text\": \"OIC ditubuhkan dan Tunku Abdul Rahman menjadi Setiausaha Agung pertama\", \"why\": \"Tahun paling awal dalam senarai.\"}, {\"id\": 2, \"year\": \"1974\", \"text\": \"Malaysia menjadi tuan rumah Persidangan OIC buat kali pertama\", \"why\": \"Datang selepas penubuhan OIC.\"}, {\"id\": 3, \"year\": \"1983\", \"text\": \"UIAM ditubuhkan\", \"why\": \"Datang selepas persidangan pertama.\"}, {\"id\": 4, \"year\": \"1989\", \"text\": \"Malaysia menjadi tuan rumah CHOGM dan mengisytiharkan Deklarasi Langkawi\", \"why\": \"Datang selepas penubuhan UIAM.\"}, {\"id\": 5, \"year\": \"1991\", \"text\": \"Malaysia menangani isu Bosnia dan Herzegovina dalam OIC\", \"why\": \"Datang selepas CHOGM.\"}, {\"id\": 6, \"year\": \"2003\", \"text\": \"Malaysia menjadi tuan rumah Persidangan OIC buat kali kedua\", \"why\": \"Tahun paling akhir dalam senarai.\"}], \"aftermath\": \"Garis masa sumbangan Malaysia tersalah susun. Pelawat menyangka UIAM lebih awal daripada persidangan OIC.\", \"turns\": [{\"after\": 6, \"options\": [{\"text\": \"Tunku Abdul Rahman.\", \"isCorrect\": true, \"reaction\": \"Tepat, pemandu! Wakil OIC memberi tabik hormat kepada Tunku.\"}, {\"text\": \"Tun Abdul Razak.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, pemandu! Wakil OIC tersenyum sambil menunjuk ke arah Tunku.\"}, {\"text\": \"Tun Dr. Mahathir.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, pemandu! Wakil OIC menggeleng sambil ketawa.\"}], \"clue\": \"Beliau juga Perdana Menteri pertama Malaysia.\"}]}'),
(1017, 'e10_n3_s5', 'Nyahkod Sijil Pengerusi Majlis Keselamatan', 'Baca sijil yang luntur dan tentukan nama tokoh Malaysia yang tidak kelihatan.', '5', 'Mengenal pasti sumbangan Malaysia kepada PBB dan pengiktirafan PBB kepada Malaysia.', '{\"clueText\": \"Sijil menulis: Pengerusi Majlis Keselamatan PBB (1989-1990) ialah tokoh Malaysia. Nama tokoh itu sudah luntur dan tidak kelihatan.\", \"options\": [{\"text\": \"Tan Sri Razali Ismail.\", \"isCorrect\": true}, {\"text\": \"Datuk Dr. Mazlan Othman.\", \"isCorrect\": false, \"consequence\": \"Sijil ditulis semula dengan nama yang tersalah. Pelawat menyangka Mazlan Othman Pengerusi Majlis Keselamatan.\"}, {\"text\": \"Tunku Abdul Rahman.\", \"isCorrect\": false, \"consequence\": \"Sijil ditulis semula dengan nama yang tersalah. Pelawat menyangka Tunku Pengerusi Majlis Keselamatan PBB.\"}], \"aftermath\": \"Nama tokoh pada sijil ditulis tidak tepat. Pelawat menyalin nama yang salah.\", \"turns\": [{\"after\": 7, \"options\": [{\"text\": \"Menyertai pasukan pengaman.\", \"isCorrect\": true, \"reaction\": \"Tepat, pemandu! Penjaga keamanan memberi tabik hormat.\"}, {\"text\": \"Menghantar angkasawan ke angkasa.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, pemandu! Penjaga keamanan ketawa sambil menunjuk ke arah topi birunya.\"}, {\"text\": \"Menubuhkan sebuah bank dunia.\", \"isCorrect\": false, \"reaction\": \"Bukan itu, pemandu! Penjaga keamanan menggeleng sambil tersenyum.\"}], \"clue\": \"Anggotanya memakai topi biru.\"}]}'),
(1018, 'e10_n3_s6', 'Cari Bukti Warisan Dunia', 'Cari bukti Tapak Warisan Dunia UNESCO di Malaysia pada kotak kaca pameran ini.', '2', 'Mengenal pasti pengiktirafan UNESCO kepada Malaysia.', '{\"hotspots\":[{\"name\":\"Gunung dalam kaca: Taman Kinabalu di Sabah, warisan alam 2000\",\"top\":\"50%\",\"left\":\"8%\"},{\"name\":\"Gua batu kapur: Taman Negara Gunung Mulu di Sarawak, warisan 2000\",\"top\":\"52%\",\"left\":\"88%\"},{\"name\":\"Peta bandar dalam kaca: Melaka dan George Town, warisan 2008\",\"top\":\"56%\",\"left\":\"72%\"},{\"name\":\"Hologram tengah: Warisan Arkeologi Lembah Lenggong, 2012\",\"top\":\"42%\",\"left\":\"50%\"}],\"bgImage\":\"../assets/gameAsset/background/ruang_unesco.png\",\"aftermath\":\"Bukti warisan dunia tersalah cari. Pelawat keluar dari pameran dengan maklumat yang salah.\",\"turns\":[{\"after\":7,\"options\":[{\"text\":\"Sabah.\",\"isCorrect\":true,\"reaction\":\"Tepat, pemandu! Ahli antropologi menepuk bahumu.\"},{\"text\":\"Sarawak.\",\"isCorrect\":false,\"reaction\":\"Itu negeri Gunung Mulu, pemandu! Ahli antropologi tersenyum sambil membetulkan.\"},{\"text\":\"Pahang.\",\"isCorrect\":false,\"reaction\":\"Bukan itu, pemandu! Ahli antropologi ketawa kecil.\"}],\"clue\":\"Gunung tertinggi Malaysia terletak di negeri itu.\"}]}');
INSERT INTO `Question` (`questionID`, `bankID`, `questionText`, `option_a`, `option_b`, `option_c`, `option_d`, `correctAnswer`, `hint`, `explanation`) VALUES
(101, 1, 'Siapakah tokoh British yang mula-mula mencadangkan penggabungan wilayah Borneo dan Negeri-Negeri Selat pada tahun 1887?', 'Sir Frank Swettenham', 'Sir Hugh Low', 'Lord Brassey', 'Sir Hugh Clifford', 'C', 'Idea ini timbul hampir 75 tahun sebelum Tunku membuat pengumuman rasmi.', 'Lord Brassey mencadangkan penggabungan wilayah Borneo dan Negeri-Negeri Selat pada 1887. Ini antara idea terawal ke arah gabungan wilayah.'),
(102, 1, 'Apakah konsep penggabungan wilayah yang dicadangkan oleh Ibrahim Haji Yaakob dan Harun Aminurrashid pada tahun 1938?', 'Melayu Raya, gabungan Tanah Melayu dan Kepulauan Indonesia', 'Nusantara Raya, gabungan Indonesia dan Borneo Utara sahaja', 'Malaya Raya, gabungan Tanah Melayu dan Singapura sahaja', 'Asia Raya, gabungan Tanah Melayu dan Kepulauan Filipina', 'A', 'Konsep ini merangkumi Tanah Melayu dan Kepulauan Indonesia.', 'Konsep Melayu Raya menggabungkan Tanah Melayu bersama Kepulauan Indonesia. Ia dikemukakan pada 1938 oleh Ibrahim Haji Yaakob dan Harun Aminurrashid.'),
(103, 1, 'Siapakah Gabenor Jeneral British yang menganjurkan perbincangan awal mengenai penggabungan wilayah pada tahun 1951?', 'Sir Gerald Templer', 'Malcolm MacDonald', 'Sir Henry Gurney', 'Lord Mountbatten', 'B', 'Beliau mewakili British di Asia Tenggara dan menganjurkan perbincangan pada 1951.', 'Malcolm MacDonald menganjurkan perbincangan awal tentang penggabungan wilayah pada tahun 1951.'),
(104, 1, 'Bilakah dan di manakah Tunku Abdul Rahman Putra Al-Haj pertama kali menyatakan gagasan penggabungan Tanah Melayu, Singapura, Sarawak, Sabah dan Brunei?', 'Pada tahun 1953 semasa persidangan wartawan asing di Singapura', 'Pada tahun 1951 semasa lawatan Malcolm MacDonald di Kuching', 'Pada tahun 1957 semasa upacara Kemerdekaan di Stadium Merdeka', 'Pada tahun 1955 semasa Dewan Perhimpunan di Kuala Lumpur', 'D', 'Gagasan ini dinyatakan sebelum Tanah Melayu merdeka.', 'Tunku mula menyatakan gagasan penggabungan lima wilayah itu pada tahun 1955 semasa Dewan Perhimpunan di Kuala Lumpur.'),
(105, 1, 'Di manakah dan bilakah Tunku Abdul Rahman mengumumkan cadangan Pembentukan Malaysia kepada media antarabangsa?', 'Hotel Adelphi, Singapura pada 27 Mei 1963', 'Hotel Raffles, Singapura pada 27 Mei 1961', 'Hotel Adelphi, Singapura pada 27 Mei 1961', 'Stadium Merdeka, Kuala Lumpur pada 27 Mei 1961', 'C', 'Pengumuman dibuat semasa majlis makan tengah hari Persatuan Wartawan Luar Negeri Asia Tenggara.', 'Pada 27 Mei 1961, Tunku mengumumkan cadangan Pembentukan Malaysia di Hotel Adelphi, Singapura, semasa majlis makan tengah hari Persatuan Wartawan Luar Negeri Asia Tenggara.'),
(106, 1, 'Apakah faktor keselamatan utama yang mendorong cadangan Pembentukan Malaysia pada tahun 1961?', 'Menghalang pengaruh ekonomi asing di Singapura dan Sarawak', 'Menamatkan pertikaian sempadan di Sabah dan Sarawak', 'Membendung penyebaran fahaman komunis di Thailand dan Kemboja', 'Membendung penyebaran fahaman komunis di Singapura dan Sarawak', 'D', 'Ancaman ini berkait dengan satu fahaman politik yang berkembang di Singapura dan Sarawak.', 'Penggabungan dilihat dapat membendung ancaman fahaman komunis di Singapura dan Sarawak.'),
(107, 1, 'Mengapakah penggabungan Singapura dan wilayah Borneo penting dari segi keseimbangan kaum?', 'Mengimbangi nisbah penduduk Bumiputera dan bukan Bumiputera', 'Mengimbangi nisbah penduduk bandar dan luar bandar sahaja', 'Menjadikan penduduk Bumiputera majoriti dua pertiga di Singapura', 'Menyamakan jumlah penduduk Singapura dengan Tanah Melayu', 'A', 'Fikirkan komposisi penduduk selepas Singapura yang ramai penduduk bukan Bumiputera bergabung.', 'Penyertaan wilayah Borneo yang ramai penduduk Bumiputera mengimbangi komposisi kaum apabila Singapura bergabung.'),
(108, 1, 'Bagaimanakah Pembentukan Malaysia memberi faedah politik kepada Sarawak, Sabah dan Singapura?', 'Menyerahkan hal ehwal luar kepada Pertubuhan PBB', 'Mengekalkan perlindungan British sehingga tahun 1970', 'Mempercepatkan kemerdekaan daripada pentadbiran British', 'Memindahkan pentadbiran wilayah itu kepada Brunei', 'C', 'Ketiga-tiga wilayah masih berada di bawah penjajah ketika itu.', 'Melalui Pembentukan Malaysia, Sarawak, Sabah dan Singapura memperoleh kemerdekaan daripada pentadbiran British dengan lebih cepat.'),
(109, 1, 'Apakah faedah sosioekonomi yang diperoleh melalui penggabungan negeri-negeri dalam Malaysia?', 'Taraf hidup meningkat dan pasaran ekonomi bersama dimajukan', 'Taraf hidup meningkat kerana semua cukai dihapuskan', 'Pelaburan asing meningkat kerana pasaran dibahagi mengikut negeri', 'Pasaran ekonomi dimajukan kerana perdagangan antara negeri dihentikan', 'A', 'Faedahnya berkaitan kehidupan rakyat dan ekonomi bersama.', 'Penggabungan membolehkan pasaran bersama dan penyatuan sumber kekayaan, lalu meningkatkan taraf hidup rakyat.'),
(110, 1, 'Siapakah Perdana Menteri Persekutuan Tanah Melayu yang digelar Arsitek Utama Pembentukan Malaysia?', 'Tun Dr. Ismail', 'Tun Tan Cheng Lock', 'Tun Abdul Razak bin Hussein', 'Tunku Abdul Rahman Putra Al-Haj', 'D', 'Beliau ialah Perdana Menteri pertama dan Bapa Kemerdekaan.', 'Tunku Abdul Rahman mencetuskan dan menggerakkan gagasan Pembentukan Malaysia, maka beliau digelar Arsitek Utamanya.'),
(111, 1, 'Bilakah Jawatankuasa Setia Kawan Malaysia (JSKM) ditubuhkan selepas pengumuman di Singapura?', '17 Januari 1962', '27 Mei 1961', '23 Julai 1961', '9 Julai 1963', 'C', 'Ia ditubuhkan kira-kira dua bulan selepas pengumuman Tunku.', 'JSKM ditubuhkan pada 23 Julai 1961, selepas pengumuman Tunku pada 27 Mei 1961.'),
(112, 1, 'Siapakah tokoh dari Sabah yang dilantik sebagai pengerusi Jawatankuasa Setia Kawan Malaysia (JSKM)?', 'Tun Temenggung Jugah anak Barieng', 'Donald Stephens (Tun Fuad Stephens)', 'Lee Kuan Yew', 'Tun Datu Mustapha bin Datu Harun', 'B', 'Beliau kemudian menjadi Ketua Menteri Sabah yang pertama.', 'Donald Stephens, yang kemudian dikenali sebagai Tun Fuad Stephens, mengetuai JSKM.'),
(113, 1, 'Apakah peranan utama Jawatankuasa Setia Kawan Malaysia (JSKM)?', 'Menyediakan saluran perbincangan dan mengumpul pandangan pemimpin Borneo', 'Menyediakan draf Perlembagaan untuk dibentangkan di London', 'Menjalankan pungutan suara rasmi di seluruh Sabah dan Sarawak', 'Menyediakan pasukan tentera bagi mempertahankan sempadan Borneo', 'A', 'Nama jawatankuasa ini membawa maksud kesetiakawanan dan perundingan.', 'JSKM menjadi saluran perbincangan untuk menerangkan gagasan Malaysia dan mengumpul pandangan pemimpin serta rakyat Borneo.'),
(114, 1, 'Berapa kali mesyuarat perundingan JSKM diadakan sebelum mengesyorkan penubuhan suruhanjaya peninjau, dan di mana?', 'Empat kali: Jesselton, Kuching, Brunei dan London', 'Empat kali: Jesselton, Kuching, Kuala Lumpur dan Singapura', 'Lima kali: Jesselton, Kuching, Singapura, London dan Brunei', 'Tiga kali: Jesselton, Kuching dan Kuala Lumpur', 'B', 'Mesyuarat diadakan di empat bandar utama.', 'JSKM bermesyuarat empat kali di Jesselton, Kuching, Kuala Lumpur dan Singapura sebelum mengesyorkan suruhanjaya peninjau.'),
(115, 1, 'Bilakah Suruhanjaya Cobbold ditubuhkan secara rasmi?', '17 Januari 1962', '14 September 1963', '21 Jun 1962', '30 Ogos 1962', 'A', 'Ia ditubuhkan pada awal tahun 1962.', 'Suruhanjaya Cobbold ditubuhkan oleh Kerajaan British dan Persekutuan Tanah Melayu pada 17 Januari 1962.'),
(116, 1, 'Apakah tugas utama Suruhanjaya Cobbold semasa melawat Sabah dan Sarawak antara Februari hingga April 1962?', 'Menyelesaikan tuntutan Filipina ke atas Sabah dan Sarawak', 'Menyediakan draf Perlembagaan untuk Sabah dan Sarawak', 'Meninjau pandangan rakyat Sabah dan Sarawak tentang Malaysia', 'Mengesahkan keputusan Perjanjian Malaysia di Borneo', 'C', 'Suruhanjaya ini menjelajah Borneo untuk mendengar suara rakyat.', 'Suruhanjaya Cobbold meninjau pandangan dan reaksi rakyat Sabah serta Sarawak terhadap cadangan Pembentukan Malaysia.'),
(117, 1, 'Siapakah dua tokoh tempatan dari Persekutuan Tanah Melayu yang menjadi anggota Suruhanjaya Cobbold?', 'Tun Abdul Razak dan Tun Dr. Ismail', 'Tun Tan Siew Sin dan Tun V.T. Sambanthan', 'Tun Muhammad Ghazali Shafie dan Tun Dr. Ismail', 'Tun Muhammad Ghazali Shafie dan Tan Sri Wong Pow Nee', 'D', 'Salah seorang daripadanya ialah Ketua Menteri Pulau Pinang.', 'Suruhanjaya Cobbold dianggotai Tun Muhammad Ghazali Shafie dan Tan Sri Wong Pow Nee bersama wakil British.'),
(118, 1, 'Berapakah nisbah penduduk Sabah dan Sarawak yang menyokong Pembentukan Malaysia menurut Suruhanjaya Cobbold?', 'Tiga perempat (3/4)', 'Dua pertiga (2/3)', 'Satu perempat (1/4)', 'Separuh (1/2)', 'B', 'Nisbah ini lebih daripada separuh tetapi kurang daripada tiga perempat.', 'Laporan Cobbold mendapati kira-kira dua pertiga penduduk Sabah dan Sarawak menyokong pembentukan Malaysia.'),
(119, 1, 'Bagaimanakah pandangan rakyat Sabah dan Sarawak dibahagikan dalam Laporan Suruhanjaya Cobbold?', 'Satu pertiga menyokong penuh, satu pertiga menentang, satu pertiga berkecuali', 'Dua pertiga menyokong penuh dan satu pertiga mahu merdeka dahulu', 'Separuh menyokong penuh, satu perempat bersyarat, satu perempat menentang', 'Satu pertiga menyokong penuh, satu pertiga bersyarat, satu pertiga mahu merdeka dahulu', 'D', 'Pandangan terbahagi kepada tiga kumpulan yang hampir sama besar.', 'Satu pertiga menyokong penuh, satu pertiga menyokong dengan syarat hak dipelihara dan satu pertiga mahukan kemerdekaan berasingan dahulu.'),
(120, 1, 'Bilakah Laporan Suruhanjaya Cobbold diserahkan kepada Kerajaan British dan Persekutuan Tanah Melayu?', '27 Mei 1961', '21 Jun 1962', '30 Ogos 1962', '17 Januari 1962', 'B', 'Laporan siap kira-kira lima bulan selepas suruhanjaya ditubuhkan.', 'Laporan Suruhanjaya Cobbold diserahkan secara rasmi pada 21 Jun 1962.'),
(121, 1, 'Bilakah Jawatankuasa Antara Kerajaan (JAK) ditubuhkan?', '12 Ogos 1963', '9 Julai 1963', '30 Ogos 1962', '21 Jun 1962', 'C', 'Ia ditubuhkan selepas Laporan Cobbold diserahkan.', 'JAK ditubuhkan pada 30 Ogos 1962 untuk menyusun butiran pembentukan Malaysia.'),
(122, 1, 'Siapakah dua tokoh yang memimpin dan mempengerusikan mesyuarat Jawatankuasa Antara Kerajaan (JAK)?', 'Lord Lansdowne dan Tun Abdul Razak bin Hussein', 'Lord Lansdowne dan Tunku Abdul Rahman Putra', 'Malcolm MacDonald dan Tun Abdul Razak bin Hussein', 'Lord Cobbold dan Tun Abdul Razak bin Hussein', 'A', 'Seorang mewakili British, seorang lagi ialah Timbalan Perdana Menteri Persekutuan Tanah Melayu.', 'Lord Lansdowne mewakili British dan Tun Abdul Razak mewakili Persekutuan Tanah Melayu dalam memimpin JAK.'),
(123, 1, 'Apakah tanggungjawab utama Jawatankuasa Antara Kerajaan (JAK)?', 'Merangka Perlembagaan dan melindungi hak Sabah dan Sarawak', 'Mengesahkan persetujuan rakyat di bawah pengawasan PBB', 'Merunding penyelesaian tuntutan Filipina ke atas Sabah', 'Meninjau pandangan rakyat dan melaporkannya kepada British', 'A', 'Jawatankuasa ini bekerja pada peringkat kerajaan, bukan meninjau rakyat.', 'JAK bertanggungjawab merangka Perlembagaan Malaysia dan peruntukan perlindungan hak istimewa Sabah serta Sarawak.'),
(124, 1, 'Apakah nama dokumen peruntukan khas yang dikemukakan pemimpin Sabah untuk dimasukkan ke dalam perlembagaan?', 'Tuntutan Hak 18 Perkara Sabah', 'Tuntutan Hak 14 Perkara Borneo', 'Tuntutan Hak 20 Perkara Sabah', 'Tuntutan Hak 20 Perkara Sarawak', 'C', 'Dokumen ini dikemukakan bagi melindungi hak istimewa Sabah.', 'Pemimpin Sabah mengemukakan Tuntutan Hak 20 Perkara Sabah supaya hak negeri itu terpelihara dalam perlembagaan.'),
(125, 1, 'Nyatakan dua perkara penting yang dilindungi dalam hak istimewa Sabah dan Sarawak melalui perlembagaan.', 'Kuasa kewangan dan agama', 'Kuasa imigresen dan agama', 'Kuasa luar negeri dan pendidikan', 'Kuasa pertahanan dan imigresen', 'B', 'Bidang ini kekal di bawah kawalan negeri, bukan Persekutuan.', 'Hak istimewa yang dilindungi merangkumi kuasa imigresen, agama, bahasa dan pentadbiran perkhidmatan awam tempatan.'),
(126, 1, 'Bilakah Perjanjian Malaysia ditandatangani secara rasmi di London?', '9 Julai 1963', '16 September 1963', '31 Ogos 1963', '14 September 1963', 'A', 'Ia berlaku beberapa bulan sebelum Pemasyhuran Malaysia.', 'Perjanjian Malaysia ditandatangani di London pada 9 Julai 1963.'),
(127, 1, 'Di manakah Perjanjian Malaysia 1963 ditandatangani?', 'Stadium Merdeka, Kuala Lumpur', 'Hotel Adelphi, Singapura', 'Marlborough House, London', 'Istana Buckingham, London', 'C', 'Tempat ini ialah sebuah rumah bersejarah di London.', 'Perjanjian Malaysia ditandatangani di Marlborough House, London.'),
(128, 1, 'Siapakah pihak yang menandatangani Perjanjian Malaysia pada 9 Julai 1963?', 'Wakil British, Tanah Melayu, Sabah, Sarawak dan Brunei', 'Wakil Tanah Melayu, Sabah, Sarawak, Singapura dan PBB', 'Wakil British, Tanah Melayu, Singapura dan Indonesia', 'Wakil British, Tanah Melayu, Sabah, Sarawak dan Singapura', 'D', 'Semua pihak yang akan membentuk Malaysia hadir bersama British.', 'Perjanjian itu ditandatangani oleh wakil British, Persekutuan Tanah Melayu, Sabah, Sarawak dan Singapura.'),
(129, 1, 'Apakah ikrar utama dalam Perjanjian Malaysia 1963?', 'Persetujuan perundangan bagi menubuhkan persekutuan Malaysia', 'Persetujuan perundangan bagi meneruskan pentadbiran British', 'Persetujuan perundangan bagi menggabungkan Singapura dengan Indonesia', 'Persetujuan perundangan bagi menubuhkan Persekutuan Borneo', 'A', 'Perjanjian ini menetapkan syarat penubuhan sebuah negara baharu.', 'Perjanjian Malaysia menetapkan persetujuan dan syarat perundangan bagi penubuhan persekutuan Malaysia yang berdaulat.'),
(130, 1, 'Siapakah Timbalan Perdana Menteri yang memimpin delegasi dalam JAK dan perundingan di London?', 'Tun Tan Siew Sin', 'Tunku Abdul Rahman Putra Al-Haj', 'Tun Abdul Razak bin Hussein', 'Tun Dr. Ismail', 'C', 'Beliau juga digelar Bapa Pembangunan.', 'Tun Abdul Razak, Timbalan Perdana Menteri, memimpin delegasi Persekutuan Tanah Melayu dalam JAK dan di London.'),
(131, 1, 'Apakah parti politik utama di Sarawak yang menentang Pembentukan Malaysia pada peringkat awal?', 'Parti Negara Sarawak (PANAS)', 'Sarawak United Peoples Party (SUPP)', 'Parti Pesaka Anak Sarawak (PESAKA)', 'Sarawak National Party (SNAP)', 'B', 'Parti ini ditubuhkan pada tahun 1959.', 'SUPP menentang cadangan Pembentukan Malaysia pada peringkat awal.'),
(132, 1, 'Mengapakah SUPP menolak cadangan Pembentukan Malaysia?', 'Mahu Sarawak merdeka serta-merta tanpa sebarang persekutuan', 'Mahu persekutuan Borneo sendiri atau merdeka berasingan dahulu', 'Mahu Sarawak bergabung dengan Brunei dan Singapura sahaja', 'Mahu Sarawak dikekalkan di bawah pentadbiran British', 'B', 'SUPP mahukan jalan yang berbeza untuk Sarawak.', 'SUPP mahu membentuk persekutuan sendiri bersama Brunei dan Borneo Utara, atau mencapai kemerdekaan berasingan terlebih dahulu.'),
(133, 1, 'Bagaimanakah Indonesia menentang penubuhan Malaysia secara luaran?', 'Menuntut Sarawak sebagai wilayah Indonesia di PBB pada 20 Januari 1963', 'Menyekat perdagangan dengan Malaysia pada 20 Januari 1962', 'Mengisytiharkan Konfrontasi dengan slogan Ganyang Malaysia pada 20 Januari 1963', 'Mengisytiharkan Konfrontasi dengan slogan Ganyang Malaysia pada 16 September 1963', 'C', 'Doktrin ini berbunyi seperti seruan untuk menghancurkan Malaysia.', 'Indonesia mengisytiharkan Konfrontasi dengan doktrin Ganyang Malaysia pada 20 Januari 1963.'),
(134, 1, 'Apakah bantahan luaran yang dikemukakan oleh Filipina terhadap Pembentukan Malaysia?', 'Mengisytiharkan Konfrontasi terhadap Malaysia', 'Menuntut Sabah sebagai sebahagian daripada wilayahnya', 'Menuntut Brunei dan Sabah sebagai wilayah bersama', 'Menuntut Sarawak sebagai sebahagian daripada wilayahnya', 'B', 'Tuntutan ini berkaitan sebuah wilayah di utara Borneo.', 'Filipina mendakwa Sabah sebahagian daripada hak wilayahnya.'),
(135, 1, 'Mengapakah Malaysia memilih pendekatan diplomasi melalui Pertubuhan Bangsa-Bangsa Bersatu (PBB) pada Ogos 1963?', 'Mengelakkan tandatangan Perjanjian Malaysia di London', 'Meredakan tentangan Indonesia dan Filipina melalui PBB', 'Meredakan tentangan SUPP melalui pengesahan Parlimen', 'Mendapatkan bantuan tentera PBB untuk menghadapi Indonesia', 'B', 'Pendekatan ini bertujuan membuktikan ketelusan kepada dunia.', 'Malaysia memilih diplomasi melalui PBB untuk meredakan tentangan Indonesia dan Filipina serta membuktikan hasrat sebenar rakyat Borneo.'),
(136, 1, 'Apakah nama misi khas PBB yang ditubuhkan pada 12 Ogos 1963 untuk meninjau semula pandangan di Sabah dan Sarawak?', 'Jawatankuasa Antara Kerajaan (JAK)', 'Jawatankuasa Setia Kawan Malaysia (JSKM)', 'Suruhanjaya Cobbold', 'United Nations Malaysia Mission (UNMM)', 'D', 'Namanya mengandungi singkatan PBB dalam bahasa Inggeris.', 'UNMM ditubuhkan pada 12 Ogos 1963 untuk meninjau semula pandangan rakyat Sabah dan Sarawak.'),
(137, 1, 'Siapakah tokoh PBB yang dilantik mengetuai misi UNMM semasa tinjauan di Borneo?', 'Sir Anthony Abell', 'Lord Lansdowne', 'U Thant', 'Laurence Michelmore', 'D', 'Beliau ialah pegawai kanan PBB, bukan wakil British.', 'Laurence Michelmore mengetuai misi UNMM di Sabah dan Sarawak.'),
(138, 1, 'Bilakah Laporan Rasmi United Nations Malaysia Mission (UNMM) dikeluarkan?', '16 September 1963', '12 Ogos 1963', '14 September 1963', '9 Julai 1963', 'C', 'Laporan dikeluarkan dua hari sebelum Pemasyhuran Malaysia.', 'Laporan UNMM dikeluarkan pada 14 September 1963, dua hari sebelum Pemasyhuran Malaysia.'),
(139, 1, 'Apakah penemuan muktamad Laporan UNMM mengenai pendirian rakyat Sabah dan Sarawak?', 'Majoriti rakyat Sabah menyokong tetapi Sarawak menolak', 'Majoriti rakyat menyokong tetapi tanpa pungutan suara bebas', 'Majoriti rakyat menolak dan mahu pungutan suara baharu', 'Majoriti rakyat menyokong Malaysia secara bebas dan demokratik', 'D', 'Laporan ini mengesahkan keputusan rakyat, bukan menolaknya.', 'UNMM mengesahkan bahawa majoriti rakyat Sabah dan Sarawak menyokong pembentukan Malaysia secara bebas dan demokratik.'),
(140, 1, 'Siapakah tokoh perunding diplomatik Malaysia yang aktif mengendalikan operasi penerangan dan keselamatan bagi menangkis cabaran Konfrontasi?', 'Tun Dr. Ismail Abdul Rahman', 'Tun Tan Siew Sin (MCA)', 'Tun V.T. Sambanthan (MIC)', 'Tun Muhammad Ghazali Shafie', 'D', 'Beliau juga pernah menjadi anggota Suruhanjaya Cobbold.', 'Tun Muhammad Ghazali Shafie giat dalam diplomasi, penerangan dan keselamatan menangkis cabaran Konfrontasi.'),
(141, 1, 'Siapakah tokoh pejuang Sabah yang memimpin pembacaan Pemasyhuran Malaysia di Kota Kinabalu pada 16 September 1963?', 'Donald Stephens (Tun Fuad Stephens)', 'Tun Temenggung Jugah anak Barieng', 'Stephen Kalong Ningkan', 'Tun Datu Mustapha bin Datu Harun', 'A', 'Beliau berasal dari Sabah dan pernah mengerusikan JSKM.', 'Donald Stephens memimpin pembacaan Pemasyhuran Malaysia di Kota Kinabalu.'),
(142, 1, 'Siapakah Pemimpin Utama Sarawak yang membacakan Teks Pemasyhuran Malaysia di Kuching pada 16 September 1963?', 'Datu Bandar Abang Haji Mustapha', 'Tun Datu Mustapha Datu Harun', 'Stephen Kalong Ningkan', 'Tun Temenggung Jugah anak Barieng', 'C', 'Beliau ialah Ketua Menteri Sarawak yang pertama.', 'Stephen Kalong Ningkan membacakan Teks Pemasyhuran Malaysia di Kuching.'),
(143, 1, 'Siapakah pemuka masyarakat Iban di Sarawak yang konsisten menyokong pembentukan Malaysia demi keselamatan wilayah?', 'Donald Stephens', 'Tun Datu Mustapha bin Datu Harun', 'Tun Temenggung Jugah anak Barieng', 'Lee Kuan Yew', 'C', 'Gelaran Temenggung diberikan kepada pemimpin adat.', 'Tun Temenggung Jugah ialah pemuka Iban yang konsisten menyokong pembentukan Malaysia.'),
(144, 1, 'Siapakah Yang di-Pertua Negeri Sabah yang pertama dilantik semasa pembentukan Malaysia pada tahun 1963?', 'Tun Temenggung Jugah anak Barieng', 'Tun Abang Haji Openg', 'Donald Stephens', 'Tun Datu Mustapha bin Datu Harun', 'D', 'Beliau juga pemimpin yang menubuhkan USNO.', 'Tun Datu Mustapha bin Datu Harun dilantik sebagai Yang di-Pertua Negeri Sabah yang pertama.'),
(145, 1, 'Bilakah tarikh rasmi Hari Pemasyhuran Malaysia yang diisytiharkan serentak?', '16 September 1963', '31 Ogos 1957', '27 Mei 1961', '31 Ogos 1963', 'A', 'Tarikh ini kini disambut sebagai Hari Malaysia.', 'Malaysia diisytiharkan serentak pada 16 September 1963.'),
(146, 1, 'Nyatakan empat lokasi utama majlis Pemasyhuran Malaysia yang diisytiharkan serentak pada 16 September 1963.', 'London, Kuala Lumpur, Kuching dan City Hall Singapura', 'Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall Singapura', 'Kuala Lumpur, Kuching, Pulau Pinang dan City Hall Singapura', 'Kuala Lumpur, Kuching, Kota Kinabalu dan Bandar Seri Begawan', 'B', 'Empat lokasi ini mewakili Tanah Melayu, Sarawak, Sabah dan Singapura.', 'Pemasyhuran dibuat serentak di Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall, Singapura.'),
(147, 1, 'Di manakah Tunku Abdul Rahman membaca Teks Pemasyhuran Malaysia di ibu negara?', 'Stadium Merdeka, Kuala Lumpur', 'Hotel Adelphi, Singapura', 'Istana Negara', 'Padang Kota Lama, Pulau Pinang', 'A', 'Stadium ini juga tempat Kemerdekaan Tanah Melayu dilaungkan pada 1957.', 'Tunku membaca Teks Pemasyhuran Malaysia di Stadium Merdeka, Kuala Lumpur.'),
(148, 1, 'Apakah lambang kedaulatan utama yang dikibarkan semasa perayaan Hari Pemasyhuran Malaysia pada 16 September 1963?', 'Bendera Pertubuhan Bangsa-Bangsa Bersatu', 'Bendera Persekutuan Tanah Melayu (11 jalur)', 'Bendera Union Jack British', 'Bendera Malaysia (Jalur Gemilang)', 'D', 'Bendera ini dikibarkan sebagai lambang negara baharu.', 'Bendera Malaysia (Jalur Gemilang) dikibarkan sebagai lambang kedaulatan negara baharu.'),
(149, 1, 'Susun peristiwa berikut mengikut kronologi yang betul: A. Laporan Suruhanjaya Cobbold; B. Cadangan Tunku di Singapura; C. Perjanjian Malaysia di London; D. Pemasyhuran Malaysia; E. Penubuhan JSKM.', 'E → B → A → C → D', 'B → E → A → C → D', 'B → A → E → C → D', 'B → E → C → A → D', 'B', 'Mulakan dengan pengumuman di Hotel Adelphi dan akhiri dengan Pemasyhuran.', 'B (27 Mei 1961), E (23 Julai 1961), A (21 Jun 1962), C (9 Julai 1963), D (16 September 1963).'),
(150, 1, 'Apakah iktibar dan ikatan utama yang dicapai oleh rakyat pelbagai kaum dan wilayah melalui pembentukan Malaysia?', 'Pergantungan sepenuhnya kepada kuasa asing', 'Toleransi, kerjasama diplomasi dan perpaduan berbilang kaum', 'Persaingan antara wilayah untuk menguasai pentadbiran', 'Pengasingan kaum demi mengekalkan kestabilan', 'B', 'Fikirkan nilai yang menyatukan rakyat berbilang kaum.', 'Pembentukan Malaysia berjaya melalui toleransi, kerjasama diplomasi, perpaduan berbilang kaum dan muafakat kepimpinan.'),
(201, 2, 'Nama Pulau Pinang diambil sempena apa?', 'Pokok mahang yang banyak tumbuh di pulau itu', 'Sungai Pinang yang mengalir di tengah pulau itu', 'Buah pinang yang dijual pedagang Siam di pulau itu', 'Pokok pinang yang banyak tumbuh di pulau itu', 'D', 'Pulau itu dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga.', 'Pulau Pinang diambil sempena pokok pinang yang banyak tumbuh di pulau itu. Dahulu ia dikenali sebagai Pulo Ka Satu atau Tanjong Penaga.'),
(202, 2, 'Nama Pahang diambil daripada nama pokok apa?', 'Pokok mahang', 'Pokok pinang', 'Pokok mentagau', 'Pokok gelam hutan', 'A', 'Catatan lama juga menyebut Pahang sebagai Inderapura.', 'Nama Pahang diambil daripada pokok mahang. Pahang juga dikenali sebagai Inderapura dalam catatan lama.'),
(203, 2, 'Nama Johor berasal daripada perkataan Arab \'Jauhar\'. Apakah maksudnya?', 'Perangkap untuk menangkap gajah', 'Tempat persinggahan kapal dagang', 'Kilatan cahaya yang terang', 'Batu permata yang bernilai', 'D', 'Dalam Sulalatus Salatin, Johor dikenali sebagai Ujung Tanah.', 'Johor berasal daripada perkataan Arab \'Jauhar\', iaitu batu permata bernilai. Dalam Sulalatus Salatin, Johor dikenali sebagai Ujung Tanah.'),
(204, 2, 'Menurut satu pendapat, nama Kedah berasal daripada perkataan \'Kheddah\'. Apakah maksudnya?', 'Perangkap gajah', 'Kelapa hanyut', 'Batu permata bernilai', 'Taring harimau liar', 'A', 'Perkataan itu berkait dengan binatang besar yang ditangkap.', 'Menurut satu pendapat, Kedah berasal daripada \'Kheddah\', iaitu perangkap gajah. Pendapat lain menyebut perkataan Arab \'Qadah\' atau \'Kadaram\' dalam rujukan India.'),
(205, 2, 'Menurut satu pendapat, nama Perlis berasal daripada perkataan Siam \'phrau loi\'. Apakah maksudnya?', 'Perangkap gajah', 'Kelapa hanyut', 'Pisang jaba', 'Taring harimau', 'B', 'Perlis juga dikaitkan dengan perkataan tempatan \'peroleh\'.', 'Perlis dikatakan daripada perkataan Siam \'phrau loi\' (kelapa hanyut) atau perkataan tempatan \'peroleh\'. Ia juga dikaitkan dengan tokoh tempatan Tok Perlis.'),
(206, 2, 'Salah satu pendapat mengaitkan nama Perak dengan apa?', 'Warna bijih timah putih yang berkilat seperti perak', 'Warna bijih timah hitam yang berkilat seperti arang', 'Warna pasir sungai yang berkilat seperti emas', 'Warna daun pokok yang berkilat seperti zamrud', 'A', 'Pendapat lain mengaitkannya dengan kilatan ikan di dalam air.', 'Nama Perak dikaitkan dengan kilatan ikan di dalam air atau warna bijih timah putih yang berkilat seperti perak.'),
(207, 2, 'Menurut satu pendapat, nama Selangor diambil sempena apa?', 'Sungai Klang', 'Sungai Selangor', 'Sungai Bernam', 'Sungai Langat', 'B', 'Pendapat lain menyebut pokok mentagau di kuala sungai.', 'Selangor dikaitkan dengan Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga bernama selangur.'),
(208, 2, 'Negeri Sembilan terbentuk daripada penyatuan berapa luak asal?', 'Tujuh luak', 'Lima luak', 'Dua belas luak', 'Sembilan luak', 'D', 'Antaranya Sungai Ujong, Jelebu, Rembau dan Johol.', 'Negeri Sembilan terbentuk daripada penyatuan sembilan luak asal, antaranya Sungai Ujong, Jelebu, Rembau dan Johol.'),
(209, 2, 'Perkataan \'negeri\' dalam Negeri Sembilan berasal daripada \'nagari\'. Apakah maksudnya?', 'Wilayah', 'Istana', 'Kampung kecil', 'Sungai besar', 'A', 'Sembilan luak asal itu bersatu menjadi satu wilayah.', 'Perkataan negeri berasal daripada \'nagari\', iaitu wilayah.'),
(210, 2, 'Nama Melaka dikatakan sempena pokok Melaka tempat siapa berehat?', 'Hang Tuah', 'Tun Perak', 'Parameswara', 'Sultan Mahmud Shah', 'C', 'Beliau datang mencari tempat untuk membuka petempatan baharu.', 'Nama Melaka dikaitkan dengan pokok Melaka tempat Parameswara berehat. Rujukan Arab pula mengaitkannya dengan \'Malakat\'.'),
(211, 2, 'Rujukan Arab mengaitkan nama Melaka dengan \'Malakat\'. Apakah maksudnya?', 'Tempat berlabuh kapal perang', 'Pusat perhimpunan pedagang', 'Kota yang dikelilingi parit', 'Pelabuhan yang berlumpur', 'B', 'Melaka terkenal sebagai tempat pedagang berkumpul.', 'Rujukan Arab mengaitkan Melaka dengan \'Malakat\', iaitu pusat perhimpunan pedagang.'),
(212, 2, 'Dalam Sulalatus Salatin, negeri manakah dikenali sebagai Ujung Tanah?', 'Johor', 'Pahang', 'Kelantan', 'Terengganu', 'A', 'Namanya berasal daripada perkataan Arab yang bermaksud permata.', 'Dalam Sulalatus Salatin, Johor dikenali sebagai Ujung Tanah.'),
(213, 2, 'Dalam rujukan China, negeri manakah disebut Ho-lan-tan?', 'Pahang', 'Terengganu', 'Kedah', 'Kelantan', 'D', 'Namanya dikaitkan dengan kilatan atau pokok gelam hutan.', 'Rujukan China menyebut Kelantan sebagai Ho-lan-tan.'),
(214, 2, '\'Terang ganu\' dalam satu pendapat asal usul nama Terengganu bermaksud apa?', 'Bulan penuh', 'Bintang timur', 'Pelangi', 'Cahaya fajar', 'C', 'Pendapat lain menyebut taring anu, iaitu taring binatang liar.', 'Terengganu dikaitkan dengan \'taring anu\' (taring harimau atau binatang liar) atau \'terang ganu\' (pelangi).'),
(215, 2, 'Antara asal usul nama Sarawak ialah logam antimoni. Apakah nama logam itu dalam cerita tempatan?', 'Cerava', 'Gelam', 'Saba', 'Mentagau', 'A', 'Sarawak juga dikaitkan dengan Sungai Sarawak.', 'Nama Sarawak dikaitkan dengan Sungai Sarawak, logam antimoni (cerava) atau dialog \'serah kepada awak\'.'),
(216, 2, 'Nama Sabah diambil daripada sejenis apa?', 'Padi, iaitu padi saba', 'Pisang, iaitu pisang saba', 'Ubi, iaitu ubi jaba', 'Kelapa, iaitu kelapa saba', 'B', 'Pisang itu juga disebut pisang jaba.', 'Nama Sabah diambil daripada sejenis pisang iaitu pisang saba (pisang jaba).'),
(217, 2, 'Nama Kuala Lumpur berasal daripada kawasan apa?', 'Muara sungai yang berpasir akibat penerokaan hutan paya', 'Muara sungai yang berlumpur akibat perlombongan bijih timah', 'Muara sungai yang berbatu akibat pembinaan jambatan lama', 'Muara sungai yang berkarang akibat pembukaan pelabuhan', 'B', 'Lumpur itu datang daripada kegiatan melombong.', 'Kuala Lumpur berasal daripada kawasan muara sungai yang berlumpur akibat perlombongan bijih timah.'),
(218, 2, 'Nama Labuan berasal daripada perkataan \'labuhan\'. Apakah maksudnya?', 'Tempat pelabuhan dan persinggahan kapal', 'Tempat penempatan dan perlindungan nelayan', 'Tempat perhimpunan dan perniagaan pedagang', 'Tempat penanaman dan pengeringan kelapa', 'A', 'Kapal-kapal singgah di sana.', 'Labuan berasal daripada \'labuhan\', iaitu tempat pelabuhan atau persinggahan kapal.'),
(219, 2, 'Nama Putrajaya diambil sempena nama siapa?', 'Tun Abdul Razak Hussein', 'Tun Hussein Onn', 'Tunku Abdul Rahman Putra Al-Haj', 'Tun Dr. Mahathir Mohamad', 'C', 'Beliau ialah Perdana Menteri Pertama.', 'Putrajaya diambil sempena nama Perdana Menteri Pertama, Tunku Abdul Rahman Putra Al-Haj, manakala jaya bermaksud kejayaan.'),
(220, 2, 'Apakah gelaran ketua negeri bagi Perlis?', 'Sultan', 'Yang di-Pertuan Besar', 'Raja', 'Yang di-Pertua Negeri', 'C', 'Hanya satu negeri menggunakan gelaran ini.', 'Ketua negeri Perlis bergelar Raja.'),
(221, 2, 'Siapakah yang memilih Yang di-Pertuan Besar Negeri Sembilan?', 'Dewan Negeri Sembilan', 'Undang Yang Empat', 'Majlis Raja-Raja', 'Yang di-Pertuan Agong', 'B', 'Pemilih itu ialah pembesar adat negeri ini.', 'Yang di-Pertuan Besar Negeri Sembilan dipilih oleh Undang Yang Empat.'),
(222, 2, 'Negeri manakah menggunakan sistem penggiliran takhta yang unik?', 'Perak', 'Kedah', 'Johor', 'Pahang', 'A', 'Bandar dirajanya Kuala Kangsar.', 'Perak menggunakan sistem penggiliran takhta yang unik.'),
(223, 2, 'Berapa tahun satu penggal jawatan Yang di-Pertua Negeri?', 'Empat tahun', 'Dua tahun', 'Tiga tahun', 'Lima tahun', 'A', 'Jawatan ini dilantik oleh Yang di-Pertuan Agong.', 'Yang di-Pertua Negeri dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.'),
(224, 2, 'Siapakah yang melantik Yang di-Pertua Negeri?', 'Majlis Raja-Raja', 'Yang di-Pertuan Agong', 'Perdana Menteri', 'Ketua Menteri', 'B', 'Pelantik itu ialah ketua utama negara.', 'Yang di-Pertua Negeri dilantik oleh Yang di-Pertuan Agong.'),
(225, 2, 'Negeri manakah diketuai oleh Yang di-Pertua Negeri?', 'Kedah', 'Perlis', 'Pulau Pinang', 'Negeri Sembilan', 'C', 'Ada empat negeri semuanya, dua di Semenanjung dan dua di Borneo.', 'Yang di-Pertua Negeri mengetuai Melaka, Pulau Pinang, Sabah dan Sarawak.'),
(226, 2, 'Berapa buah negeri yang diketuai oleh Sultan?', 'Lima buah', 'Enam buah', 'Lapan buah', 'Tujuh buah', 'D', 'Perak, Kedah dan Selangor antaranya.', 'Tujuh negeri diketuai Sultan: Johor, Kedah, Kelantan, Pahang, Perak, Selangor dan Terengganu.'),
(227, 2, 'Siapakah ketua negeri bagi Kuala Lumpur, Labuan dan Putrajaya?', 'Yang di-Pertuan Agong', 'Perdana Menteri', 'Datuk Bandar', 'Yang di-Pertua Negeri', 'A', 'Beliau ialah Ketua Utama Negara.', 'Yang di-Pertuan Agong ialah Ketua Utama Negara dan ketua negeri bagi tiga Wilayah Persekutuan.'),
(228, 2, 'Pasangan negeri dan gelaran ketua negeri manakah yang betul?', 'Perlis dan Sultan', 'Sabah dan Raja', 'Melaka dan Yang di-Pertuan Besar', 'Negeri Sembilan dan Yang di-Pertuan Besar', 'D', 'Ketua negeri itu dipilih oleh Undang Yang Empat.', 'Negeri Sembilan diketuai Yang di-Pertuan Besar. Perlis diketuai Raja, Sabah dan Melaka diketuai Yang di-Pertua Negeri.'),
(229, 2, 'Negeri manakah diketuai oleh Sultan?', 'Melaka', 'Sabah', 'Selangor', 'Perlis', 'C', 'Bandar dirajanya ialah Klang.', 'Selangor diketuai Sultan. Melaka dan Sabah diketuai Yang di-Pertua Negeri, manakala Perlis diketuai Raja.'),
(230, 2, 'Apakah ibu negeri Perlis?', 'Arau', 'Kangar', 'Alor Setar', 'Kuala Kangsar', 'B', 'Bandar dirajanya ialah Arau.', 'Kangar ialah ibu negeri Perlis, manakala bandar dirajanya ialah Arau.'),
(231, 2, 'Apakah bandar diraja Perlis?', 'Kangar', 'Anak Bukit', 'Pekan', 'Arau', 'D', 'Ibu negerinya ialah Kangar.', 'Arau ialah bandar diraja Perlis.'),
(232, 2, 'Apakah bandar diraja Perak?', 'Ipoh', 'Kuala Kangsar', 'Klang', 'Seri Menanti', 'B', 'Ibu negerinya ialah Ipoh.', 'Kuala Kangsar ialah bandar diraja Perak, manakala ibu negerinya ialah Ipoh.'),
(233, 2, 'Apakah bandar diraja Kedah?', 'Alor Setar', 'Arau', 'Pekan', 'Anak Bukit', 'D', 'Ibu negerinya ialah Alor Setar.', 'Anak Bukit ialah bandar diraja Kedah, manakala ibu negerinya ialah Alor Setar.'),
(234, 2, 'Apakah bandar diraja Pahang?', 'Kuantan', 'Klang', 'Pekan', 'Arau', 'C', 'Ibu negerinya ialah Kuantan.', 'Pekan ialah bandar diraja Pahang, manakala ibu negerinya ialah Kuantan.'),
(235, 2, 'Apakah bandar diraja Negeri Sembilan?', 'Seremban', 'Seri Menanti', 'Pekan', 'Anak Bukit', 'B', 'Ibu negerinya ialah Seremban.', 'Seri Menanti ialah bandar diraja Negeri Sembilan, manakala ibu negerinya ialah Seremban.'),
(236, 2, 'Apakah bandar diraja Johor?', 'Johor Bahru', 'Klang', 'Bandar Maharani', 'Pekan', 'C', 'Ibu negerinya ialah Johor Bahru.', 'Bandar Maharani ialah bandar diraja Johor, manakala ibu negerinya ialah Johor Bahru.'),
(237, 2, 'Apakah bandar diraja Selangor?', 'Shah Alam', 'Seremban', 'Kuala Kangsar', 'Klang', 'D', 'Ibu negerinya ialah Shah Alam.', 'Klang ialah bandar diraja Selangor, manakala ibu negerinya ialah Shah Alam.'),
(238, 2, 'Apakah ibu negeri Selangor?', 'Shah Alam', 'Klang', 'Seremban', 'Kuala Kangsar', 'A', 'Bandar dirajanya ialah Klang.', 'Shah Alam ialah ibu negeri Selangor.'),
(239, 2, 'Apakah ibu negeri Pahang?', 'Pekan', 'Kota Bharu', 'Kuala Terengganu', 'Kuantan', 'D', 'Bandar dirajanya ialah Pekan.', 'Kuantan ialah ibu negeri Pahang.'),
(240, 2, 'Apakah ibu negeri Sabah?', 'Kuching', 'Kota Bharu', 'Kota Kinabalu', 'Kuala Terengganu', 'C', 'Ibu negeri itu terletak di Borneo.', 'Kota Kinabalu ialah ibu negeri Sabah.'),
(241, 2, 'Apakah ibu negeri Sarawak?', 'Kota Kinabalu', 'Kuching', 'Kota Bharu', 'Kuala Kangsar', 'B', 'Lagu negerinya ialah Ibu Pertiwiku.', 'Kuching ialah ibu negeri Sarawak.'),
(242, 2, 'Apakah ibu negeri Pulau Pinang?', 'Alor Setar', 'George Town', 'Ipoh', 'Bandar Melaka', 'B', 'Ibu negeri itu terletak di sebuah pulau.', 'George Town ialah ibu negeri Pulau Pinang.'),
(243, 2, 'Apakah lagu negeri Perak?', 'Allah Selamatkan Sultan Mahkota', 'Allah Selamatkan Sultan Kami', 'Berkatlah Yang di-Pertuan Besar', 'Allah Lanjutkan Usia Sultan', 'D', 'Tajuknya menyebut usia.', 'Lagu negeri Perak ialah Allah Lanjutkan Usia Sultan.'),
(244, 2, 'Apakah lagu negeri Kedah?', 'Allah Selamatkan Sultan Mahkota', 'Allah Lanjutkan Usia Sultan', 'Allah Selamatkan Sultan Kami', 'Duli Yang Maha Mulia', 'A', 'Tajuknya menyebut mahkota.', 'Lagu negeri Kedah ialah Allah Selamatkan Sultan Mahkota.'),
(245, 2, 'Apakah lagu negeri Negeri Sembilan?', 'Duli Yang Maha Mulia', 'Allah Lanjutkan Usia Sultan', 'Berkatlah Yang di-Pertuan Besar', 'Lagu Bangsa Johor', 'C', 'Tajuknya menyebut gelaran ketua negerinya.', 'Lagu negeri Negeri Sembilan ialah Berkatlah Yang di-Pertuan Besar.'),
(246, 2, 'Apakah lagu negeri Melaka?', 'Maju dan Sejahtera', 'Sabah Tanah Airku', 'Lagu Bangsa Johor', 'Melaka Maju Jaya', 'D', 'Tajuknya menyebut nama negeri itu sendiri.', 'Lagu negeri Melaka ialah Melaka Maju Jaya.'),
(247, 2, 'Apakah lagu negeri Sabah?', 'Sabah Tanah Airku', 'Ibu Pertiwiku', 'Melaka Maju Jaya', 'Maju dan Sejahtera', 'A', 'Tajuknya menyebut tanah air.', 'Lagu negeri Sabah ialah Sabah Tanah Airku.'),
(248, 2, 'Apakah lagu negeri Sarawak?', 'Sabah Tanah Airku', 'Selamat Sultan', 'Ibu Pertiwiku', 'Lagu Bangsa Johor', 'C', 'Tajuknya menyebut ibu pertiwi.', 'Lagu negeri Sarawak ialah Ibu Pertiwiku.'),
(249, 2, 'Apakah lagu negeri Johor?', 'Melaka Maju Jaya', 'Duli Yang Maha Mulia', 'Lagu Bangsa Johor', 'Selamat Sultan', 'C', 'Tajuknya menyebut bangsa Johor.', 'Lagu negeri Johor ialah Lagu Bangsa Johor.'),
(250, 2, 'Apakah lagu negeri Selangor?', 'Selamat Sultan', 'Duli Yang Maha Mulia', 'Allah Selamatkan Sultan Kami', 'Berkatlah Yang di-Pertuan Besar', 'B', 'Tajuknya ialah ungkapan hormat kepada raja.', 'Lagu negeri Selangor ialah Duli Yang Maha Mulia.'),
(301, 3, 'Rukun Negara dibentuk selepas negara ditadbir oleh badan apa?', 'Jawatankuasa Antara Kerajaan', 'Suruhanjaya Cobbold', 'Jawatankuasa Setia Kawan Malaysia', 'MAGERAN', 'D', 'Badan itu ditubuhkan selepas peristiwa 1969.', 'Rukun Negara dibentuk selepas pentadbiran negara dijalankan oleh MAGERAN selepas peristiwa 1969.'),
(302, 3, 'Apakah kepanjangan MAGERAN?', 'Majlis Gabungan Negara', 'Majlis Gerakan Negara', 'Majlis Gerakan Negeri', 'Majlis Gerak Gempur Negara', 'B', 'Perkataan tengahnya berkait dengan gerakan.', 'MAGERAN ialah Majlis Gerakan Negara, yang mentadbir negara selepas peristiwa 1969.'),
(303, 3, 'Peristiwa manakah yang menjadi latar belakang pentadbiran MAGERAN dan kelahiran Rukun Negara?', 'Rusuhan kaum 13 Mei 1969', 'Pengisytiharan Kemerdekaan 31 Ogos 1957', 'Pemasyhuran Malaysia 16 September 1963', 'Laporan Suruhanjaya Cobbold 21 Jun 1962', 'A', 'Peristiwa itu berlaku pada tahun 1969.', 'Rusuhan kaum 13 Mei 1969 menjadi latar belakang MAGERAN mentadbir negara dan Rukun Negara diperkenalkan.'),
(304, 3, 'Jawatankuasa Rukun Negara bekerja di bawah badan apa?', 'Majlis Perundingan Negara (MAPEN)', 'Majlis Gerakan Negara (MAGERAN)', 'Jawatankuasa Antara Kerajaan (JAK)', 'Majlis Raja-Raja', 'A', 'Badan itu ialah majlis perundingan.', 'Rukun Negara dirangka dan diperkenalkan oleh Jawatankuasa Rukun Negara di bawah Majlis Perundingan Negara (MAPEN).'),
(305, 3, 'Apakah kepanjangan MAPEN?', 'Majlis Penasihat Negara', 'Majlis Pentadbiran Negara', 'Majlis Perundingan Negara', 'Majlis Perpaduan Negara', 'C', 'Perkataan tengahnya berkait dengan perundingan.', 'MAPEN ialah Majlis Perundingan Negara, tempat Jawatankuasa Rukun Negara bekerja.'),
(306, 3, 'Bilakah Rukun Negara dirangka dan diperkenalkan oleh Jawatankuasa Rukun Negara?', '13 Mei 1969', '31 Ogos 1957', '4 Mac 1970', '16 September 1963', 'C', 'Tarikh itu jatuh pada awal tahun 1970.', 'Rukun Negara dirangka dan diperkenalkan oleh Jawatankuasa Rukun Negara di bawah MAPEN pada 4 Mac 1970.'),
(307, 3, 'Rukun Negara diisytiharkan pada Hari Kebangsaan tahun apa?', '1957', '1970', '1963', '1969', 'B', 'Hari Kebangsaan ialah 31 Ogos.', 'Rukun Negara diisytiharkan pada Hari Kebangsaan, 31 Ogos 1970, selepas dirangka pada 4 Mac 1970.'),
(308, 3, 'Susun peristiwa ini mengikut kronologi: A. Rusuhan 13 Mei 1969; B. MAGERAN mentadbir negara; C. Rukun Negara dirangka pada 4 Mac 1970; D. Rukun Negara diisytiharkan pada 31 Ogos 1970.', 'B, A, C, D', 'A, C, B, D', 'A, B, D, C', 'A, B, C, D', 'D', 'Rusuhan dahulu, pengisytiharan paling akhir.', 'Urutan yang betul: rusuhan 13 Mei 1969, MAGERAN mentadbir negara, Rukun Negara dirangka (4 Mac 1970), kemudian diisytiharkan (31 Ogos 1970).'),
(309, 3, 'Apakah tujuan utama Rukun Negara diperkenalkan?', 'Memisahkan setiap kaum mengikut kawasan tempat tinggal masing-masing', 'Mengukuhkan perpaduan dan semangat kekitaan masyarakat berbilang kaum', 'Menggantikan Perlembagaan Persekutuan sebagai undang-undang tertinggi', 'Menyeragamkan semua agama dan budaya masyarakat Malaysia', 'B', 'Tujuan itu berkait dengan kekitaan.', 'Rukun Negara diperkenalkan untuk mengukuhkan perpaduan dan semangat kekitaan dalam kalangan masyarakat berbilang kaum.'),
(310, 3, 'Apakah kegiatan ekonomi utama orang Melayu dahulu?', 'Perlombongan bijih timah', 'Pertanian sara diri', 'Perladangan getah', 'Perniagaan di bandar besar', 'B', 'Mereka menanam untuk keperluan sendiri.', 'Orang Melayu dahulu terlibat dalam pertanian sara diri.'),
(311, 3, 'Apakah kegiatan ekonomi utama orang Cina dahulu?', 'Pertanian sara diri', 'Perladangan', 'Menangkap ikan di laut dalam', 'Perlombongan dan perniagaan', 'D', 'Mereka banyak berada di lombong dan kedai.', 'Orang Cina dahulu terlibat dalam perlombongan dan perniagaan.'),
(312, 3, 'Apakah kegiatan ekonomi utama orang India dahulu?', 'Pertanian sara diri', 'Perlombongan', 'Perniagaan di pekan', 'Perladangan', 'D', 'Mereka bekerja di ladang getah dan sawit.', 'Orang India dahulu terlibat dalam perladangan.'),
(313, 3, 'Di manakah orang Melayu dahulu kebanyakannya tinggal?', 'Kampung dan kawasan pedalaman', 'Bandar dan kawasan lombong', 'Ladang dan kawasan perlombongan', 'Pekan dan kawasan pesisir pantai', 'A', 'Mereka dekat dengan sawah.', 'Orang Melayu dahulu tinggal di kampung dan kawasan pedalaman.'),
(314, 3, 'Di manakah orang Cina dahulu kebanyakannya tinggal?', 'Bandar', 'Kampung', 'Ladang', 'Pedalaman', 'A', 'Mereka dekat dengan kedai dan lombong.', 'Orang Cina dahulu kebanyakannya tinggal di bandar.'),
(315, 3, 'Di manakah orang India dahulu kebanyakannya tinggal?', 'Kampung', 'Bandar', 'Ladang', 'Pedalaman', 'C', 'Tempat tinggal mereka dekat dengan tempat kerja.', 'Orang India dahulu kebanyakannya tinggal di ladang.'),
(316, 3, 'Apakah kesan perbezaan fahaman politik antara kaum sebelum Rukun Negara?', 'Mengukuhkan kerjasama semua kaum sehingga rusuhan berakhir', 'Menyatukan semua parti politik dalam satu gabungan besar', 'Menegangkan hubungan kaum sehingga rusuhan 13 Mei 1969', 'Menghapuskan perbezaan ekonomi antara semua kaum', 'C', 'Ketegangan itu memuncak pada tahun 1969.', 'Perbezaan fahaman politik menegangkan hubungan kaum sehingga mencetuskan rusuhan kaum 13 Mei 1969.'),
(317, 3, 'Mengapakah perbezaan kegiatan ekonomi dan tempat tinggal menyukarkan perpaduan?', 'Semua kaum tinggal bercampur di satu kawasan sepanjang masa', 'Semua kaum melakukan kerja yang sama di tempat yang sama', 'Setiap kaum bergantung kepada satu pemimpin sahaja dalam semua urusan', 'Interaksi antara kaum terbatas dan mudah menimbulkan salah faham', 'D', 'Fikirkan kekerapan mereka bertemu.', 'Apabila kegiatan ekonomi dan tempat tinggal berasingan, interaksi antara kaum terbatas dan mudah menimbulkan salah faham.'),
(318, 3, 'Berapakah matlamat Rukun Negara?', 'Tiga', 'Empat', 'Lima', 'Enam', 'C', 'Bilangannya sama dengan bilangan prinsip.', 'Rukun Negara mempunyai lima matlamat dan lima prinsip.'),
(319, 3, 'Matlamat yang mana menyebut perpaduan yang lebih erat?', 'Mencapai perpaduan yang lebih erat dalam kalangan seluruh masyarakat', 'Memelihara satu cara hidup demokrasi dalam kalangan rakyat', 'Mencipta masyarakat yang adil dengan kemakmuran dikongsi', 'Membina masyarakat progresif yang menggunakan teknologi', 'A', 'Matlamat itu merangkumi seluruh masyarakat.', 'Matlamat pertama ialah mencapai perpaduan yang lebih erat dalam kalangan seluruh masyarakat.'),
(320, 3, 'Matlamat manakah yang berkait dengan cara hidup demokrasi?', 'Menjamin satu cara yang liberal terhadap tradisi kebudayaan', 'Membina satu masyarakat progresif', 'Mencapai perpaduan yang lebih erat', 'Memelihara satu cara hidup demokrasi', 'D', 'Perhatikan perkataan demokrasi.', 'Salah satu matlamat Rukun Negara ialah memelihara satu cara hidup demokrasi.'),
(321, 3, 'Matlamat manakah yang berkait dengan kemakmuran negara yang dinikmati bersama?', 'Memelihara satu cara hidup demokrasi dalam kalangan rakyat jelata', 'Mencipta masyarakat adil dengan kemakmuran dinikmati bersama secara saksama', 'Membina masyarakat progresif dengan sains dan teknologi moden yang terkini', 'Menjamin cara yang liberal terhadap tradisi kebudayaan yang pelbagai', 'B', 'Perkataan penting ialah adil dan saksama.', 'Matlamat Rukun Negara ialah mencipta masyarakat yang adil di mana kemakmuran negara dinikmati bersama secara adil dan saksama.'),
(322, 3, 'Matlamat manakah yang berkait dengan tradisi kebudayaan yang kaya dan pelbagai?', 'Mencapai perpaduan yang lebih erat dalam kalangan masyarakat', 'Memelihara cara hidup demokrasi dalam kalangan seluruh rakyat', 'Menjamin satu cara yang liberal terhadap tradisi kebudayaan', 'Mencipta masyarakat yang adil dan kemakmuran dikongsi bersama', 'C', 'Perkataan penting ialah liberal.', 'Salah satu matlamat ialah menjamin satu cara yang liberal terhadap tradisi kebudayaan yang kaya dan pelbagai corak.'),
(323, 3, 'Matlamat manakah yang menyebut sains dan teknologi moden?', 'Memelihara satu cara hidup demokrasi yang liberal dan terbuka', 'Mencapai perpaduan yang lebih erat dalam kalangan seluruh masyarakat', 'Mencipta masyarakat yang adil dengan kemakmuran dinikmati bersama', 'Membina satu masyarakat progresif yang menggunakan sains dan teknologi moden', 'D', 'Perkataan penting ialah progresif.', 'Salah satu matlamat ialah membina satu masyarakat progresif yang menggunakan sains dan teknologi moden.'),
(324, 3, 'Sekolah membenarkan murid memakai pakaian tradisional pelbagai kaum pada Hari Budaya. Matlamat manakah yang dihayati?', 'Membina masyarakat progresif dengan teknologi moden', 'Memelihara satu cara hidup demokrasi dalam kalangan rakyat', 'Mencapai kemakmuran negara yang adil dan saksama bersama', 'Menjamin cara yang liberal terhadap tradisi kebudayaan yang pelbagai', 'D', 'Fikirkan pakaian dan tradisi.', 'Menghargai pakaian tradisional pelbagai kaum menghayati matlamat menjamin cara yang liberal terhadap tradisi kebudayaan.'),
(325, 3, 'Kerajaan memastikan hasil pembangunan sampai ke kampung, ladang dan bandar. Matlamat manakah yang dihayati?', 'Masyarakat yang adil, kemakmuran dinikmati bersama secara adil dan saksama', 'Memelihara satu cara hidup demokrasi dalam kalangan rakyat jelata', 'Membina masyarakat progresif dengan sains dan teknologi moden', 'Menjamin cara yang liberal terhadap tradisi kebudayaan pelbagai', 'A', 'Fikirkan pembahagian yang saksama.', 'Memastikan pembangunan sampai kepada semua menghayati matlamat masyarakat yang adil dengan kemakmuran dinikmati bersama.'),
(326, 3, 'Rakyat memilih wakil mereka melalui pilihan raya yang bebas. Matlamat manakah yang dihayati?', 'Membina masyarakat progresif dengan teknologi moden', 'Memelihara satu cara hidup demokrasi', 'Mencapai perpaduan yang lebih erat', 'Mencipta masyarakat yang adil', 'B', 'Fikirkan cara rakyat memilih pemimpin.', 'Pilihan raya yang bebas menghayati matlamat memelihara satu cara hidup demokrasi.'),
(327, 3, 'Berapakah prinsip Rukun Negara?', 'Tiga', 'Empat', 'Lima', 'Enam', 'C', 'Bilangannya sama dengan bilangan matlamat.', 'Rukun Negara mempunyai lima prinsip.'),
(328, 3, 'Apakah prinsip pertama Rukun Negara?', 'Kepercayaan kepada Tuhan', 'Kesetiaan kepada Raja dan Negara', 'Keluhuran Perlembagaan', 'Kedaulatan Undang-undang', 'A', 'Prinsip itu berkait dengan agama.', 'Prinsip pertama Rukun Negara ialah Kepercayaan kepada Tuhan.'),
(329, 3, 'Apakah prinsip kedua Rukun Negara?', 'Kepercayaan kepada Tuhan', 'Keluhuran Perlembagaan', 'Kesetiaan kepada Raja dan Negara', 'Kesopanan dan Kesusilaan', 'C', 'Prinsip itu berkait dengan Ketua Utama Negara.', 'Prinsip kedua ialah Kesetiaan kepada Raja dan Negara.'),
(330, 3, 'Apakah prinsip ketiga Rukun Negara?', 'Keluhuran Perlembagaan', 'Kedaulatan Undang-undang', 'Kesetiaan kepada Raja dan Negara', 'Kepercayaan kepada Tuhan', 'A', 'Prinsip itu berkait dengan undang-undang tertinggi.', 'Prinsip ketiga ialah Keluhuran Perlembagaan.'),
(331, 3, 'Apakah prinsip keempat Rukun Negara?', 'Kedaulatan Undang-undang', 'Keluhuran Perlembagaan', 'Kesopanan dan Kesusilaan', 'Kepercayaan kepada Tuhan', 'A', 'Prinsip itu berkait dengan mematuhi undang-undang.', 'Prinsip keempat ialah Kedaulatan Undang-undang.'),
(332, 3, 'Apakah prinsip kelima Rukun Negara?', 'Kedaulatan Undang-undang', 'Keluhuran Perlembagaan', 'Kesopanan dan Kesusilaan', 'Kesetiaan kepada Raja dan Negara', 'C', 'Prinsip itu berkait dengan nilai murni.', 'Prinsip kelima ialah Kesopanan dan Kesusilaan.'),
(333, 3, 'Prinsip manakah yang menjadikan agama sebagai pegangan utama rakyat Malaysia?', 'Kesetiaan kepada Raja dan Negara', 'Kedaulatan Undang-undang', 'Kesopanan dan Kesusilaan', 'Kepercayaan kepada Tuhan', 'D', 'Prinsip pertama.', 'Kepercayaan kepada Tuhan bermaksud agama sebagai pegangan utama rakyat Malaysia.'),
(334, 3, 'Prinsip manakah yang melahirkan rakyat yang menghormati amalan beragama masyarakat lain?', 'Keluhuran Perlembagaan', 'Kepercayaan kepada Tuhan', 'Kedaulatan Undang-undang', 'Kesetiaan kepada Raja dan Negara', 'B', 'Ia juga menyatukan rakyat berbilang kaum.', 'Prinsip Kepercayaan kepada Tuhan melahirkan rakyat yang menghormati amalan beragama masyarakat lain.'),
(335, 3, 'Siapakah Ketua Utama Negara yang diberikan taat setia dalam prinsip kedua?', 'Yang di-Pertuan Agong', 'Perdana Menteri', 'Ketua Hakim Negara', 'Menteri Besar', 'A', 'Gelaran penuhnya ialah Duli Yang Maha Mulia Seri Paduka Baginda.', 'Prinsip kedua menyatakan taat setia kepada Yang di-Pertuan Agong sebagai Ketua Utama Negara.'),
(336, 3, 'Apakah kesan prinsip Kesetiaan kepada Raja dan Negara kepada masyarakat?', 'Setiap kaum berikrar kepada ketuanya sahaja dalam semua hal', 'Masyarakat bergantung sepenuhnya kepada satu parti politik', 'Masyarakat bersatu padu dan mempunyai semangat patriotik', 'Rakyat bebas daripada semua undang-undang yang ditetapkan', 'C', 'Fikirkan semangat cinta akan negara.', 'Prinsip ini menjadikan masyarakat bersatu padu dan mempunyai semangat patriotik.'),
(337, 3, 'Apakah maksud Keluhuran Perlembagaan?', 'Perlembagaan boleh diatasi oleh institusi tertentu', 'Perlembagaan Persekutuan ialah undang-undang tertinggi negara', 'Perlembagaan hanya untuk kaum tertentu di negara ini', 'Perlembagaan hanya dipatuhi oleh pegawai kerajaan sahaja', 'B', 'Perkataan penting ialah tertinggi.', 'Keluhuran Perlembagaan bermaksud Perlembagaan Persekutuan ialah undang-undang tertinggi negara dan tiada institusi dapat mengatasinya.'),
(338, 3, 'Rakyat menerima, mematuhi dan mempertahankan kemuliaan Perlembagaan. Prinsip manakah yang dihayati?', 'Kedaulatan Undang-undang', 'Kesopanan dan Kesusilaan', 'Kepercayaan kepada Tuhan', 'Keluhuran Perlembagaan', 'D', 'Prinsip ketiga.', 'Menerima, mematuhi dan mempertahankan kemuliaan Perlembagaan ialah penghayatan Keluhuran Perlembagaan.');
INSERT INTO `Question` (`questionID`, `bankID`, `questionText`, `option_a`, `option_b`, `option_c`, `option_d`, `correctAnswer`, `hint`, `explanation`) VALUES
(339, 3, 'Apakah yang dijamin oleh prinsip Kedaulatan Undang-undang?', 'Kebebasan melanggar peraturan apabila tiada pegawai', 'Kuasa mutlak untuk satu kaum sahaja di negara ini', 'Keharmonian masyarakat dan keselamatan negara', 'Pengasingan kawasan tempat tinggal bagi setiap kaum', 'C', 'Fikirkan hasil apabila semua mematuhi undang-undang.', 'Menghormati dan mematuhi undang-undang menjamin keharmonian masyarakat dan keselamatan negara.'),
(340, 3, 'Apakah ciri masyarakat yang dibentuk oleh prinsip Kesopanan dan Kesusilaan?', 'Bersaing untuk menunjukkan siapa yang lebih berkuasa', 'Berdisiplin, berakhlak mulia dan hidup harmoni', 'Menyendiri dan mengelak bertegur sapa dengan jiran', 'Mengabaikan nilai murni demi mengejar kejayaan sahaja', 'B', 'Prinsip kelima berkait dengan nilai murni.', 'Prinsip Kesopanan dan Kesusilaan membentuk masyarakat yang berdisiplin, berakhlak mulia dan hidup dalam suasana harmoni.'),
(341, 3, 'Seorang pemandu mematuhi peraturan lalu lintas walaupun tiada polis. Prinsip manakah yang dihayati?', 'Kesopanan dan Kesusilaan', 'Kepercayaan kepada Tuhan', 'Kesetiaan kepada Raja dan Negara', 'Kedaulatan Undang-undang', 'D', 'Fikirkan mematuhi peraturan yang ditetapkan.', 'Mematuhi peraturan lalu lintas menghayati prinsip Kedaulatan Undang-undang.'),
(342, 3, 'Seorang murid menghormati orang yang lebih tua dan bertutur dengan sopan. Prinsip manakah yang dihayati?', 'Keluhuran Perlembagaan', 'Kedaulatan Undang-undang', 'Kesetiaan kepada Raja dan Negara', 'Kesopanan dan Kesusilaan', 'D', 'Fikirkan nilai murni dan akhlak mulia.', 'Menghormati orang yang lebih tua dan bertutur dengan sopan menghayati prinsip Kesopanan dan Kesusilaan.'),
(343, 3, 'Berapakah peranan Rukun Negara yang disenaraikan?', 'Enam', 'Tiga', 'Empat', 'Lima', 'A', 'Bilangannya satu lebih banyak daripada bilangan prinsip.', 'Rukun Negara mempunyai enam peranan.'),
(344, 3, 'Peranan manakah yang meraikan kepelbagaian agama dan kepercayaan?', 'Memupuk sikap menghormati undang-undang', 'Meraikan kepelbagaian agama dan kepercayaan', 'Menerapkan nilai murni', 'Mengukuhkan perpaduan masyarakat', 'B', 'Ia salah satu peranan pertama.', 'Salah satu peranan Rukun Negara ialah meraikan kepelbagaian agama dan kepercayaan.'),
(345, 3, 'Peranan manakah yang berkait dengan cinta akan negara?', 'Membentuk masyarakat Malaysia yang patriotik', 'Memupuk sikap menghormati undang-undang', 'Menerapkan nilai murni', 'Membentuk jati diri masyarakat', 'A', 'Perkataan penting ialah patriotik.', 'Salah satu peranan Rukun Negara ialah membentuk masyarakat Malaysia yang patriotik.'),
(346, 3, 'Peranan manakah yang berkait dengan mematuhi peraturan negara?', 'Meraikan kepelbagaian agama', 'Memupuk sikap menghormati undang-undang', 'Membentuk jati diri masyarakat', 'Mengukuhkan perpaduan masyarakat', 'B', 'Perkataan penting ialah menghormati.', 'Salah satu peranan Rukun Negara ialah memupuk sikap menghormati undang-undang.'),
(347, 3, 'Peranan manakah yang berkait dengan jiran pelbagai kaum yang bergotong-royong?', 'Mengukuhkan perpaduan masyarakat', 'Memupuk sikap menghormati undang-undang', 'Menerapkan nilai murni', 'Membentuk jati diri masyarakat', 'A', 'Fikirkan bersatu padu.', 'Bergotong-royong antara jiran pelbagai kaum mengukuhkan perpaduan masyarakat, salah satu peranan Rukun Negara.'),
(348, 3, 'Peranan manakah yang berkait dengan membantu warga emas?', 'Memupuk sikap menghormati undang-undang', 'Menerapkan nilai murni', 'Membentuk masyarakat yang patriotik', 'Meraikan kepelbagaian agama', 'B', 'Fikirkan akhlak mulia.', 'Membantu warga emas ialah contoh peranan menerapkan nilai murni.'),
(349, 3, 'Peranan manakah yang berkait dengan identiti bersama sebagai rakyat Malaysia?', 'Menggantikan Perlembagaan Persekutuan', 'Membentuk jati diri masyarakat Malaysia', 'Menyeragamkan semua agama', 'Meraikan satu kaum sahaja', 'B', 'Perkataan penting ialah jati diri.', 'Salah satu peranan Rukun Negara ialah membentuk jati diri masyarakat Malaysia.'),
(350, 3, 'Murid mengucapkan selamat hari raya kepada kawan pelbagai kaum dan agama. Peranan manakah yang dihayati?', 'Memupuk sikap menghormati undang-undang', 'Menggantikan Perlembagaan', 'Meraikan kepelbagaian agama dan kepercayaan', 'Membentuk satu agama tunggal', 'C', 'Fikirkan perayaan pelbagai agama.', 'Meraikan perayaan kawan pelbagai kaum dan agama menghayati peranan meraikan kepelbagaian agama dan kepercayaan.'),
(401, 4, 'Antara berikut, yang manakah kaum di Semenanjung Malaysia?', 'Murut', 'Siam', 'Kenyah', 'Rungus', 'B', 'Pilih kaum yang tinggal di Semenanjung.', 'Siam ialah salah satu kaum di Semenanjung, bersama Melayu, Cina, India dan Orang Asli.'),
(402, 4, 'Kaum manakah termasuk dalam kaum peranakan atau kecil di Semenanjung?', 'Bidayuh dan Kenyah', 'Murut dan Rungus', 'Iban dan Melanau', 'Baba dan Nyonya', 'D', 'Kaum ini bercampur budaya Cina dan tempatan.', 'Baba dan Nyonya, bersama Chetti, Sikh dan Serani, ialah kaum di Semenanjung.'),
(403, 4, 'Kaum manakah termasuk kaum lain di Sabah?', 'Kenyah', 'Rungus', 'Melanau', 'Bidayuh', 'B', 'Ingat empat nama selepas Kadazandusun.', 'Kaum lain di Sabah ialah Murut, Rungus, Iranun dan Bajau.'),
(404, 4, 'Kaum manakah termasuk kaum lain di Sarawak?', 'Iranun', 'Bajau', 'Murut', 'Melanau', 'D', 'Ingat empat nama selain Iban.', 'Kaum lain di Sarawak ialah Melayu, Kenyah, Melanau dan Bidayuh.'),
(405, 4, 'Kadazandusun ialah kaum utama di negeri mana?', 'Sabah', 'Sarawak', 'Kelantan', 'Pahang', 'A', 'Negeri di Pulau Borneo, bukan Sarawak.', 'Kadazandusun ialah kaum yang terkenal di Sabah.'),
(406, 4, 'Iban ialah kaum utama di negeri mana?', 'Sabah', 'Pulau Pinang', 'Sarawak', 'Selangor', 'C', 'Negeri di Pulau Borneo, bukan Sabah.', 'Iban ialah kaum utama di Sarawak.'),
(407, 4, 'Apakah perbezaan kaum lain di Sabah dengan kaum lain di Sarawak?', 'Sabah ada Murut dan Bajau, Sarawak ada Kenyah dan Bidayuh', 'Sabah ada Kenyah dan Bidayuh, Sarawak ada Murut dan Bajau', 'Sabah ada Siam dan Sikh, Sarawak ada Chetti dan Serani', 'Sabah dan Sarawak ada kaum lain yang sama sahaja', 'A', 'Ingat dua kumpulan kaum lain yang berbeza.', 'Kaum lain di Sabah ialah Murut, Rungus, Iranun dan Bajau; di Sarawak ialah Melayu, Kenyah, Melanau dan Bidayuh.'),
(408, 4, 'Apakah ciri kepelbagaian kaum di Malaysia?', 'Hanya satu kaum di setiap negeri kita', 'Hanya kaum Melayu dan Cina di negara', 'Banyak kaum di Semenanjung, Sabah dan Sarawak', 'Kaum hanya wujud di Semenanjung sahaja', 'C', 'Fikirkan semua kawasan Malaysia.', 'Malaysia ada pelbagai kaum di Semenanjung, Sabah dan Sarawak.'),
(409, 4, 'Petempatan orang Melayu dahulu terletak di mana?', 'Kampung, pantai dan sungai', 'Pekan dan bandar yang sibuk', 'Ladang getah dan pinggir bandar', 'Pedalaman yang jauh dari pantai', 'A', 'Dekat air pantai dan sungai.', 'Orang Melayu dahulu menetap di kampung, persisiran pantai dan sungai.'),
(410, 4, 'Apakah kegiatan ekonomi orang Melayu dahulu?', 'Petani, nelayan dan peniaga kecil', 'Pelombong bijih dan peniaga besar', 'Pekerja ladang dan pelabuhan sahaja', 'Pemburu dan pemungut hasil hutan', 'A', 'Dekat laut dan sawah.', 'Orang Melayu dahulu menjadi petani, nelayan, peniaga kecil-kecilan dan bekerja dalam perkhidmatan awam.'),
(411, 4, 'Di mana orang Cina dahulu menetap?', 'Kampung dan persisiran pantai', 'Ladang dan pinggir bandar', 'Pedalaman hutan', 'Pekan dan bandar', 'D', 'Tempat yang berniaga dan melombong.', 'Orang Cina dahulu menetap di pekan dan bandar, kerja sebagai pelombong dan peniaga.'),
(412, 4, 'Apakah kerja orang Cina dahulu?', 'Petani dan nelayan', 'Pekerja ladang dan pelabuhan', 'Pelombong dan peniaga', 'Pemburu dan pengutip hasil hutan', 'C', 'Berkait dengan bijih dan kedai.', 'Orang Cina dahulu bekerja sebagai pelombong dan peniaga di pekan dan bandar.'),
(413, 4, 'Di mana orang India dahulu menetap?', 'Pekan dan bandar besar sahaja', 'Kampung dan pantai yang jauh', 'Ladang dan pinggir bandar', 'Pedalaman hutan Semenanjung kita', 'C', 'Dekat tempat kerja ladang.', 'Orang India dahulu menetap di ladang dan pinggir bandar.'),
(414, 4, 'Apakah kerja orang India dahulu selain bekerja di ladang?', 'Peniaga kecil dan pekerja pelabuhan', 'Pelombong bijih timah di lombong', 'Nelayan di persisiran pantai lama', 'Pemburu di dalam hutan pedalaman', 'A', 'Berkait dengan perniagaan kecil dan pelabuhan.', 'Orang India dahulu bekerja di ladang, berniaga kecil-kecilan dan bekerja di pelabuhan.'),
(415, 4, 'Apakah kegiatan Orang Asli di pedalaman dahulu?', 'Melombong bijih dan berniaga di bandar', 'Bekerja di ladang dan di pelabuhan', 'Menangkap ikan dan menanam padi sawah', 'Kraf tangan, berburu dan hasil hutan', 'D', 'Hutan menjadi sumber hidup.', 'Orang Asli di pedalaman membuat kraf tangan, berburu dan memungut hasil hutan.'),
(416, 4, 'Di mana Bidayuh, Kenyah dan Kelabit menetap?', 'Pedalaman', 'Lembah sungai', 'Pekan dan bandar', 'Pesisiran pantai', 'A', 'Jauh dari sungai besar dan bandar.', 'Bidayuh, Kenyah dan Kelabit menetap di pedalaman Sarawak.'),
(417, 4, 'Apakah ekonomi Bidayuh, Kenyah dan Kelabit dahulu?', 'Berdagang, membuat perahu dan mengusahakan sagu', 'Bertani di lembah sungai dan menangkap ikan', 'Padi sawah, padi bukit dan hasil hutan', 'Bekerja di ladang getah dan di pelabuhan', 'C', 'Tanaman padi dan hutan.', 'Mereka menanam padi sawah dan padi bukit serta mengutip hasil hutan.'),
(418, 4, 'Kaum manakah menetap di lembah sungai Sarawak?', 'Bidayuh dan Kenyah', 'Melayu dan Melanau', 'Kelabit dan Kedayan', 'Iban dan Bisaya', 'D', 'Tinggal di tepi sungai.', 'Iban dan Bisaya menetap di lembah sungai dan menjadi petani.'),
(419, 4, 'Kaum manakah menetap di pekan dan bandar Sarawak?', 'Iban, Bisaya dan Bidayuh', 'Melayu, Melanau dan Kedayan', 'Kenyah, Kelabit dan Iban', 'Bidayuh, Kelabit dan Bisaya', 'B', 'Tiga kaum yang berdagang.', 'Melayu, Melanau dan Kedayan menetap di pekan dan bandar Sarawak.'),
(420, 4, 'Apakah kegiatan ekonomi Melayu, Melanau dan Kedayan di Sarawak dahulu?', 'Berdagang, membuat perahu dan mengusahakan sagu', 'Menanam padi bukit di pedalaman hutan sahaja', 'Mengutip hasil hutan di pedalaman yang jauh', 'Melombong bijih dan berniaga di bandar besar', 'A', 'Berkait dengan dagang, perahu dan sagu.', 'Mereka menjadi pedagang, pembuat perahu dan pengusaha sagu.'),
(421, 4, 'Apakah yang membolehkan rakyat bekerja bersama dan tinggal dalam satu kawasan perumahan kini?', 'Pemisahan kaum mengikut tempat tinggal', 'Kerja keras pemimpin dan toleransi', 'Kegiatan ekonomi yang sama bagi semua', 'Perbezaan bahasa yang besar antara kaum', 'B', 'Hasil kerja pemimpin dan sikap rakyat.', 'Setelah merdeka dan Malaysia terbentuk, kerja keras pemimpin dan toleransi membolehkan rakyat bekerja bersama.'),
(422, 4, 'Apakah keadaan rakyat berbilang kaum kini?', 'Tinggal di tempat berasingan mengikut kaum', 'Bekerja bersama dan satu kawasan perumahan', 'Bekerja hanya dengan kaum sendiri sahaja', 'Menetap hanya di pedalaman hutan jauh', 'B', 'Ingat maksud perkataan kini.', 'Kini rakyat pelbagai kaum mampu bekerja bersama dan tinggal dalam satu kawasan perumahan.'),
(423, 4, 'Alat muzik manakah ialah alat muzik tradisional Melayu?', 'Gambus', 'Veenai', 'Sape', 'Kulintangan', 'A', 'Alat petik Melayu.', 'Alat muzik Melayu termasuk angklung, gambus, nafiri dan geduk.'),
(424, 4, 'Tarian manakah ialah tarian tradisional Melayu?', 'Zapin', 'Ngajat', 'Sumazau', 'Tarian singa', 'A', 'Tarian berpasangan Melayu.', 'Tarian Melayu termasuk makyung dan zapin.'),
(425, 4, 'Alat muzik manakah digunakan dalam muzik tradisional Cina?', 'Mattalam', 'Liu qin', 'Engkerurai', 'Sompotan', 'B', 'Alat tali Cina.', 'Alat muzik Cina termasuk gendang, bo, liu qin dan seruling.'),
(426, 4, 'Apakah tarian tradisional kaum Cina?', 'Bharatanatyam', 'Tarian singa', 'Makyung', 'Ngajat', 'B', 'Menggunakan kostum singa.', 'Tarian tradisional kaum Cina ialah tarian singa.'),
(427, 4, 'Alat muzik manakah digunakan dalam muzik tradisional India?', 'Geduk', 'Kulintangan', 'Bo', 'Veenai', 'D', 'Alat petik India.', 'Alat muzik India termasuk pullangkulal, talam, mattalam dan veenai.'),
(428, 4, 'Apakah tarian tradisional kaum India?', 'Bharatanatyam', 'Tarian Zapin', 'Tarian Sumazau', 'Tarian Ngajat', 'A', 'Tarian klasik India.', 'Tarian tradisional kaum India ialah bharatanatyam.'),
(429, 4, 'Alat muzik manakah ialah alat muzik tradisional Sarawak?', 'Veenai', 'Gendang cina', 'Tongkungan', 'Sape', 'D', 'Alat petik Sarawak.', 'Alat muzik Sarawak termasuk sape, engkerurai dan engkerumong.'),
(430, 4, 'Apakah tarian tradisional Sarawak?', 'Sumazau', 'Bharatanatyam', 'Ngajat', 'Zapin', 'C', 'Tarian perang kaum Sarawak.', 'Tarian tradisional Sarawak ialah ngajat.'),
(431, 4, 'Apakah tarian tradisional dan alat muzik Sabah?', 'Ngajat dengan sape dan engkerurai', 'Zapin dengan gambus dan geduk', 'Makyung dengan geduk dan nafiri', 'Sumazau dengan kulintangan', 'D', 'Pasangan alat dan tarian Sabah.', 'Tarian Sabah ialah sumazau, dengan alat muzik seperti kulintangan, sompotan, tongkungan dan tontog.'),
(432, 4, 'Permainan manakah dimainkan di anjung?', 'Sepak raga', 'Wau', 'Congkak', 'Kabaddi', 'C', 'Dimainkan di atas papan.', 'Permainan anjung termasuk congkak, batu seremban, go atau weiqi, yoyo cina, chaturangam dan paramapadham.'),
(433, 4, 'Permainan manakah ialah permainan anjung kaum Cina?', 'Kabaddi lama', 'Gasing besar', 'Go atau weiqi', 'Chap teh baru', 'C', 'Permainan papan strategi.', 'Go atau weiqi ialah permainan anjung kaum Cina.'),
(434, 4, 'Permainan manakah ialah permainan anjung kaum India?', 'Kabaddi dan sepak raga di laman', 'Chaturangam dan paramapadham', 'Wau dan tibau di kawasan lapang', 'Congkak dan gasing di dalam rumah', 'B', 'Dua permainan papan India.', 'Chaturangam dan paramapadham ialah permainan anjung.'),
(435, 4, 'Permainan manakah dimainkan di laman?', 'Congkak', 'Gasing', 'Paramapadham', 'Sepak raga', 'D', 'Dimainkan dengan bola rotan.', 'Permainan laman termasuk sepak raga, chap teh dan kabaddi.'),
(436, 4, 'Apakah permainan laman yang berasal dari India?', 'Wau', 'Kabaddi', 'Sepak manggis', 'Tibau', 'B', 'Permainan menangkap pasukan lawan.', 'Kabaddi ialah permainan laman yang dimainkan oleh kaum India.'),
(437, 4, 'Permainan manakah dimainkan di kawasan lapang?', 'Batu seremban', 'Congkak', 'Wau', 'Chap teh', 'C', 'Memerlukan angin kencang.', 'Permainan kawasan lapang termasuk wau, tibau, sepak manggis dan gasing.'),
(438, 4, 'Di manakah gasing biasanya dimainkan?', 'Anjung', 'Laman sempit', 'Kawasan lapang', 'Dalam rumah sahaja', 'C', 'Memerlukan tanah luas.', 'Gasing dimainkan di kawasan lapang.'),
(439, 4, 'Mengapakah permainan tradisional dimainkan oleh semua kaum bersama-sama?', 'Untuk memisahkan kaum yang berbeza', 'Untuk memupuk perpaduan dan warisan', 'Untuk menggantikan sekolah di kampung', 'Untuk mengelakkan jiran daripada bertemu', 'B', 'Fikirkan faedah kepada masyarakat.', 'Permainan tradisional dikongsi untuk memupuk perpaduan dan mengekalkan warisan.'),
(440, 4, 'Mengapakah Si Luncai dihukum oleh raja?', 'Kerana mencuri labu di dalam istana', 'Kerana mempermain-mainkan raja', 'Kerana memberontak bersama semua pembesar', 'Kerana melarikan diri dari dalam istana', 'B', 'Berkait dengan sikap Si Luncai kepada raja.', 'Si Luncai dihukum kerana mempermain-mainkan raja dan pembesar.'),
(441, 4, 'Apakah yang dilakukan oleh pesuruh raja kepada Si Luncai?', 'Memenjarakannya di menara paling tinggi', 'Menghalaunya jauh ke dalam hutan belantara', 'Membawanya semula ke istana raja sahaja', 'Memasukkannya ke dalam guni di perahu', 'D', 'Hukuman melibatkan perahu.', 'Si Luncai dimasukkan ke dalam guni di atas perahu.'),
(442, 4, 'Bagaimanakah Si Luncai menipu pesuruh raja?', 'Menyanyi lagu supaya mereka leka', 'Berpura-pura sakit', 'Menyorok di bawah perahu', 'Meminta tolong daripada nelayan', 'A', 'Pesuruh raja berasa terhibur.', 'Si Luncai menyanyi lagu \'Si Luncai terjun dengan labu-labunya, biarkan! biarkan!\' sehingga pesuruh raja leka.'),
(443, 4, 'Apakah yang dimasukkan oleh Si Luncai ke dalam guni sebelum terjun?', 'Batu', 'Sagu', 'Kayu', 'Labu', 'D', 'Sebutan dalam namanya sendiri.', 'Si Luncai mengisi labu ke dalam guni lalu terjun dan berenang dengan labu air.'),
(444, 4, 'Siapakah dua puteri dalam Legenda Santubong?', 'Puteri Gunung Ledang dan Puteri Santubong', 'Puteri Santubong dan Puteri Sejinjang', 'Puteri Sejinjang dan Puteri Serapi', 'Puteri Serapi dan Puteri Talang', 'B', 'Satu menenun, satu menumbuk padi.', 'Puteri Santubong menenun, Puteri Sejinjang menumbuk padi.'),
(445, 4, 'Mengapakah dua puteri diturunkan dari kayangan dalam Legenda Santubong?', 'Untuk mencari Putera Serapi dari Matang', 'Untuk mendamaikan Pasir Kuning dan Pasir Putih', 'Untuk menenun pakaian bagi raja kayangan', 'Untuk membina Gunung Santubong yang tinggi', 'B', 'Dua kampung berselisih.', 'Mereka diturunkan dari kayangan untuk mendamaikan kampung Pasir Kuning dan Pasir Putih.'),
(446, 4, 'Mengapakah Puteri Santubong dan Puteri Sejinjang bertelingkah?', 'Kerana berebut hasil padi di kampung', 'Kerana berebut kain tenunan di kayangan', 'Kerana sama-sama menyukai Putera Serapi', 'Kerana tersilap membina rumah di gunung', 'C', 'Putera dari Matang.', 'Mereka menyukai Putera Serapi dari Matang lalu bertelingkah.'),
(447, 4, 'Apakah akibat antan terkena pipi Puteri Santubong?', 'Pulau Kera terbentuk', 'Sungai Liwagu terbentuk', 'Gunung Santubong sumbing', 'Kampung Pasir Putih hilang', 'C', 'Gunung berkait dengan namanya.', 'Antan terkena pipi Santubong lalu Gunung Santubong sumbing.'),
(448, 4, 'Apakah terjadi apabila batang belidah terkena kepala Puteri Sejinjang?', 'Gunung Santubong menjadi sumbing di tengah', 'Dua kampung berbaik semula selepas itu', 'Putera Serapi terjun ke laut kerana malu', 'Menjadi Pulau Kera, Satang dan Talang-talang', 'D', 'Hasilnya ialah pulau.', 'Batang belidah terkena kepala Sejinjang lalu menjadi Pulau Kera, Pulau Satang dan Pulau Talang-talang.'),
(449, 4, 'Legenda Nunuk Ragang menceritakan tentang kemunculan kaum di mana?', 'Tambunan dan Ranau, Sabah', 'Kuching dan Sibu, Sarawak', 'Melaka dan Kuantan', 'Kuala Terengganu dan Kota Bharu', 'A', 'Berkait dengan Sungai Liwagu.', 'Legenda Nunuk Ragang menceritakan kemunculan pelbagai kaum di Tambunan dan Ranau, Sabah.'),
(450, 4, 'Apakah yang membawa penduduk Sungai Liwagu terbang dalam Legenda Nunuk Ragang?', 'Ayam gergasi merah bertaji emas', 'Burung helang bersayap perak', 'Rama-rama gergasi', 'Naga bersisik biru', 'A', 'Seekor burung yang besar.', 'Ayam gergasi merah bertaji emas membawa penduduk terbang; di mana sayapnya dikibar, di situ mereka membina petempatan dan dialek sendiri.'),
(501, 5, 'Antara berikut, yang manakah agama atau ajaran di Malaysia?', 'Ajaran Konfusius', 'Ajaran Magavau', 'Ajaran Miring', 'Ajaran Tamarok', 'A', 'Ingat tujuh agama dan ajaran dalam senarai.', 'Agama dan ajaran di Malaysia ialah Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Tao dan Ajaran Konfusius.'),
(502, 5, 'Berapakah bilangan agama dan ajaran yang disenaraikan di Malaysia?', 'Lima', 'Enam', 'Sembilan', 'Tujuh', 'D', 'Kira Islam hingga Ajaran Konfusius.', 'Tujuh: Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Tao dan Ajaran Konfusius.'),
(503, 5, 'Antara berikut, yang manakah ialah satu daripada agama di Malaysia?', 'Sikh', 'Kinorohingan', 'Petara', 'Bobohizan', 'A', 'Pilih nama agama, bukan nama dewa atau tokoh.', 'Sikh ialah salah satu agama di Malaysia, manakala Kinorohingan dan Petara ialah kepercayaan kaum dan Bobohizan ialah gelaran ketua bomoh.'),
(504, 5, 'Ajaran manakah dipasangkan dengan Ajaran Konfusius dalam senarai agama Malaysia?', 'Ajaran Sikh', 'Ajaran Tao', 'Ajaran Hindu', 'Ajaran Kristian', 'B', 'Dua ajaran yang berkongsi tokong.', 'Ajaran Tao dan Ajaran Konfusius ialah dua ajaran dalam senarai tujuh agama dan ajaran.'),
(505, 5, 'Mengapakah penting kita mengenali agama dan kepercayaan lain?', 'Supaya semua orang menganut satu agama sahaja', 'Supaya perbezaan agama dapat dihapuskan kelak', 'Supaya agama lain tidak lagi diamalkan orang', 'Supaya dapat hidup bersama dengan aman dan hormat', 'D', 'Fikirkan kehidupan bersama dalam masyarakat.', 'Mengenali agama dan kepercayaan lain membantu rakyat hidup bersama dengan aman dan hormat.'),
(506, 5, 'Antara berikut, yang manakah BUKAN agama dalam senarai tujuh agama dan ajaran?', 'Hindu', 'Buddha', 'Magavau', 'Kristian', 'C', 'Satu nama ialah upacara kaum.', 'Magavau ialah upacara Kadazandusun, bukan agama dalam senarai tujuh agama dan ajaran.'),
(507, 5, 'Kenny dalam cerita mewakili ajaran apakah?', 'Ajaran Hindu dan Ajaran Sikh', 'Ajaran Buddha dan Kristian', 'Ajaran Islam dan Ajaran Sikh', 'Ajaran Tao dan Ajaran Konfusius', 'D', 'Dua ajaran, satu wakil.', 'Kenny mewakili Ajaran Tao dan Ajaran Konfusius.'),
(508, 5, 'Apakah rumah ibadat bagi penganut Islam?', 'Gereja', 'Masjid', 'Kuil', 'Gurdwara', 'B', 'Rumah ibadat dengan kubah dan menara.', 'Rumah ibadat penganut Islam ialah masjid.'),
(509, 5, 'Apakah rumah ibadat bagi penganut Kristian?', 'Gereja', 'Masjid', 'Gurdwara', 'Wat', 'A', 'Bangunan dengan menara dan salib.', 'Rumah ibadat penganut Kristian ialah gereja.'),
(510, 5, 'Apakah rumah ibadat bagi penganut Hindu?', 'Tokong', 'Gereja', 'Kuil', 'Masjid', 'C', 'Menara berwarna-warni.', 'Rumah ibadat penganut Hindu ialah kuil.'),
(511, 5, 'Apakah rumah ibadat bagi penganut Sikh?', 'Kuil lama', 'Tokong lama', 'Wat lama', 'Gurdwara', 'D', 'Bangunan putih dengan kubah emas.', 'Rumah ibadat penganut Sikh ialah gurdwara.'),
(512, 5, 'Apakah rumah ibadat bagi penganut Buddha?', 'Masjid atau kuil', 'Gereja atau gurdwara', 'Tokong atau wat', 'Kuil atau gereja', 'C', 'Ada dua nama yang digunakan.', 'Rumah ibadat penganut Buddha ialah tokong atau wat.'),
(513, 5, 'Apakah rumah ibadat bagi penganut Ajaran Konfusius dan Ajaran Tao?', 'Kuil', 'Gurdwara', 'Gereja', 'Tokong', 'D', 'Nama yang sama dengan salah satu rumah ibadat Buddha.', 'Rumah ibadat penganut Ajaran Konfusius dan Ajaran Tao ialah tokong.'),
(514, 5, 'Penganut manakah menggunakan gurdwara sebagai rumah ibadat?', 'Hindu', 'Kristian', 'Sikh', 'Buddha', 'C', 'Rumah ibadat dengan kubah emas.', 'Gurdwara ialah rumah ibadat penganut Sikh.'),
(515, 5, 'Rumah ibadat manakah dikongsi namanya oleh Buddha, Konfusius dan Tao?', 'Tokong', 'Gurdwara', 'Gereja', 'Masjid', 'A', 'Satu nama untuk tiga kumpulan.', 'Tokong digunakan oleh penganut Buddha, Ajaran Konfusius dan Ajaran Tao.'),
(516, 5, 'Apakah agama bagi Persekutuan menurut Perkara 3(1) Perlembagaan?', 'Kristian', 'Buddha', 'Islam', 'Hindu', 'C', 'Perkara 3(1) membuka bahagian ini.', 'Perkara 3(1) menyatakan Islam adalah agama bagi Persekutuan.'),
(517, 5, 'Apakah yang dinyatakan tentang agama lain dalam Perkara 3(1)?', 'Boleh diamalkan dengan aman dan damai', 'Dilarang diamalkan di Persekutuan', 'Hanya boleh diamalkan di rumah sendiri', 'Hanya boleh diamalkan di kawasan pedalaman', 'A', 'Perkara 3(1) memberi jaminan kepada agama lain.', 'Perkara 3(1) menyatakan agama lain boleh diamalkan dengan aman dan damai di mana-mana bahagian Persekutuan.'),
(518, 5, 'Siapakah Ketua Agama Islam di negeri yang mempunyai Raja, menurut Perkara 3(2)?', 'Raja negeri itu', 'Yang di-Pertua Negeri', 'Perdana Menteri', 'Menteri Besar', 'A', 'Gelaran bergantung kepada jenis negeri.', 'Perkara 3(2) menyatakan Raja ialah Ketua Agama Islam di negeri beraja.'),
(519, 5, 'Di manakah Yang di-Pertuan Agong menjadi Ketua Agama Islam menurut Perkara 3(3)?', 'Selangor, Perak, Kedah dan Johor', 'Melaka, Pulau Pinang, Sabah dan Sarawak', 'Perlis, Kelantan, Pahang dan Terengganu', 'Kuala Lumpur, Labuan dan Putrajaya sahaja', 'B', 'Empat negeri tanpa Raja.', 'Perkara 3(3) menyatakan Yang di-Pertuan Agong ialah Ketua Agama Islam di Melaka, Pulau Pinang, Sabah dan Sarawak.'),
(520, 5, 'Siapakah Ketua Agama Islam Wilayah Persekutuan menurut Perkara 3(5)?', 'Sultan Selangor', 'Yang di-Pertuan Agong', 'Yang di-Pertua Negeri', 'Menteri Besar', 'B', 'Perkara 3(5) menyebut tiga wilayah.', 'Perkara 3(5) menyatakan Yang di-Pertuan Agong ialah Ketua Agama Islam Wilayah Persekutuan.'),
(521, 5, 'Manakah tiga Wilayah Persekutuan yang disebut dalam Perkara 3(5)?', 'Kuala Lumpur, Melaka dan Putrajaya', 'Labuan, Kuching dan Putrajaya', 'Kuala Lumpur, Labuan dan Putrajaya', 'Kuala Lumpur, Johor Bahru dan Labuan', 'C', 'Ingat ibu kota, pulau dan pusat pentadbiran.', 'Perkara 3(5) menyebut Wilayah Persekutuan Kuala Lumpur, Labuan dan Putrajaya.'),
(522, 5, 'Perkara manakah menyatakan kedudukan Raja sebagai Ketua Agama Islam di negeri beraja?', 'Perkara 3(1)', 'Perkara 3(3)', 'Perkara 3(5)', 'Perkara 3(2)', 'D', 'Perkara kedua dalam bahagian ini.', 'Perkara 3(2) menyatakan kedudukan Raja sebagai Ketua Agama Islam di negeri beraja.'),
(523, 5, 'Mengapakah Yang di-Pertuan Agong menjadi Ketua Agama Islam di Sabah?', 'Sabah mempunyai banyak Raja', 'Sabah tidak mempunyai agama', 'Sabah baru menyertai Persekutuan', 'Sabah tidak mempunyai Raja', 'D', 'Perkara 3(3) berkait dengan negeri tanpa Raja.', 'Perkara 3(3) meletakkan Yang di-Pertuan Agong sebagai Ketua Agama Islam di negeri tanpa Raja seperti Sabah.'),
(524, 5, 'Mengapakah Perkara 3(1) penting kepada rakyat berbilang agama?', 'Melarang semua agama lain di Persekutuan ini', 'Menjamin agama lain diamalkan dengan aman dan damai', 'Hanya menyebut agama Islam tanpa jaminan lain', 'Memisahkan rakyat mengikut agama dan kaum mereka', 'B', 'Fikirkan kebebasan beragama.', 'Perkara 3(1) menjadikan Islam agama Persekutuan sambil menjamin agama lain diamalkan dengan aman dan damai.'),
(525, 5, 'Suku manakah mengadakan upacara Puja Pantai?', 'Suku Mah Meri', 'Suku Temiar', 'Suku Semai', 'Suku Bajau', 'A', 'Upacara itu di tepi laut.', 'Suku Mah Meri mengadakan upacara Puja Pantai.'),
(526, 5, 'Apakah tujuan upacara Puja Pantai suku Mah Meri?', 'Menghalau kuasa jahat daripada badan orang yang sakit', 'Meraikan tuaian padi di sawah yang luas', 'Memohon perlindungan dan pengampunan daripada semangat laut', 'Menjamu tetamu selepas kematian sebagai sedekah', 'C', 'Berkait dengan laut.', 'Puja Pantai diadakan untuk perlindungan dan pengampunan daripada semangat laut.'),
(527, 5, 'Apakah yang dipercayai oleh Orang Asli sebagai punca penyakit?', 'Kuasa jahat', 'Semangat padi', 'Petara', 'Kinorohingan', 'A', 'Berkait dengan upacara menghalau.', 'Orang Asli percaya penyakit disebabkan kuasa jahat.'),
(528, 5, 'Suku manakah mengadakan upacara ritual untuk menghalau kuasa jahat?', 'Temiar dan Semai', 'Mah Meri dan Iban', 'Bajau dan Bisaya', 'Kadazandusun dan Iban', 'A', 'Dua suku di Semenanjung.', 'Suku Temiar dan Semai mengadakan upacara ritual untuk menghalau kuasa jahat.'),
(529, 5, 'Antara berikut, yang manakah upacara suku Mah Meri?', 'Upacara Miring', 'Upacara Magavau', 'Upacara Tamarok', 'Puja Pantai', 'D', 'Pilih upacara Orang Asli.', 'Puja Pantai ialah upacara suku Mah Meri.'),
(530, 5, 'Suku Orang Asli manakah yang percaya semangat laut?', 'Iban', 'Mah Meri', 'Bajau', 'Kadazandusun', 'B', 'Orang Asli Semenanjung di tepi laut.', 'Suku Mah Meri mengadakan Puja Pantai untuk semangat laut.'),
(531, 5, 'Mengapakah Orang Asli mengadakan upacara ritual apabila ada yang sakit?', 'Untuk memuja semangat padi di sawah yang luas lagi subur', 'Untuk menjamu tetamu sebagai sedekah selepas kematian di kampung', 'Untuk membuka kawasan pertanian baharu di tepi hutan belantara', 'Untuk menghalau kuasa jahat yang dipercayai menyebabkan penyakit', 'D', 'Hubungan antara penyakit dan kepercayaan.', 'Orang Asli percaya penyakit disebabkan kuasa jahat, lalu mengadakan ritual untuk menghalaunya.'),
(532, 5, 'Siapakah Petara dalam kepercayaan Iban?', 'Penyair', 'Ketua bomoh', 'Penjaga padi', 'Dewa', 'D', 'Dewa yang dipuja.', 'Petara ialah dewa dalam kepercayaan masyarakat Iban.'),
(533, 5, 'Bagaimanakah Petara menyampaikan petanda dan alamat kepada masyarakat Iban?', 'Melalui mimpi dan bayangan', 'Melalui bunyi ombak di laut', 'Melalui asap kemenyan tebal', 'Melalui pokok besar di tebing', 'A', 'Dua cara yang berlaku semasa tidur dan siang.', 'Petara menyampaikan petanda dan alamat melalui mimpi dan bayangan.'),
(534, 5, 'Apakah upacara untuk memuja Petara?', 'Miring', 'Magavau', 'Puja Pantai', 'Tamarok', 'A', 'Upacara Iban.', 'Petara dipuja melalui beberapa upacara seperti upacara Miring.'),
(535, 5, 'Dengan apakah upacara Miring dimulakan?', 'Tarian ngajat', 'Jampi mentera', 'Jamuan sedekah', 'Tiupan sape', 'B', 'Bacaan khas.', 'Upacara Miring dimulai dengan jampi mentera.'),
(536, 5, 'Siapakah yang melakukan upacara Miring?', 'Bobohizan', 'Tok Batin', 'Imam', 'Lemambang', 'D', 'Seorang penyair.', 'Upacara Miring dilakukan oleh seorang penyair dikenali sebagai Lemambang.'),
(537, 5, 'Siapakah Kinorohingan dalam kepercayaan Kadazandusun?', 'Dewa penyampai petanda dan alamat', 'Semangat laut yang dipercayai', 'Tuhan untuk meminta sesuatu', 'Penyair yang memimpin upacara', 'C', 'Dimohon apabila ada hajat.', 'Kinorohingan ialah Tuhan untuk meminta sesuatu bagi masyarakat Kadazandusun.'),
(538, 5, 'Apakah semangat yang dipercayai oleh masyarakat Kadazandusun?', 'Semangat laut', 'Semangat hutan Temiar', 'Semangat padi', 'Semangat Petara', 'C', 'Berkait dengan tanaman.', 'Masyarakat Kadazandusun percaya semangat padi dan menjalankan upacara Magavau.'),
(539, 5, 'Apakah upacara Kadazandusun untuk semangat padi?', 'Miring', 'Magavau', 'Tamarok', 'Ngeduang', 'B', 'Upacara Kadazandusun.', 'Upacara Magavau dijalankan untuk semangat padi.'),
(540, 5, 'Siapakah yang mengetuai upacara Magavau?', 'Lemambang', 'Bobohizan', 'Petara', 'Tok Batin', 'B', 'Ketua bomoh.', 'Upacara Magavau diketuai oleh ketua bomoh dikenali sebagai Bobohizan.'),
(541, 5, 'Apakah perbezaan Lemambang Iban dengan Bobohizan Kadazandusun?', 'Lemambang melakukan Miring, Bobohizan mengetuai Magavau', 'Lemambang mengetuai Magavau, Bobohizan melakukan Miring', 'Kedua-duanya menjalankan upacara Tamarok', 'Kedua-duanya memimpin upacara Puja Pantai', 'A', 'Setiap tokoh milik kaum dan upacara sendiri.', 'Lemambang melakukan upacara Miring (Iban), manakala Bobohizan mengetuai Magavau (Kadazandusun).'),
(542, 5, 'Apakah pekerjaan masyarakat Bisaya di Sarawak yang disebut dalam kepercayaan mereka?', 'Nelayan', 'Pelombong', 'Petani', 'Pedagang', 'C', 'Berkait dengan kawasan pertanian.', 'Masyarakat Bisaya di Sarawak bekerja sebagai petani dan mempercayai kuasa ghaib.'),
(543, 5, 'Mengapakah masyarakat Bisaya membaca jampi mentera sebelum membuka kawasan pertanian baharu?', 'Untuk meraikan tuaian', 'Untuk menjamu tetamu', 'Untuk menghormati warisan', 'Untuk mengelakkan gangguan', 'D', 'Jampi dibaca demi keselamatan.', 'Jampi mentera dibaca untuk mengelakkan gangguan semasa membuka kawasan pertanian baharu.'),
(544, 5, 'Apakah upacara Bisaya untuk menghalau kuasa ghaib daripada badan pesakit?', 'Miring', 'Tamarok', 'Ngeduang', 'Magavau', 'B', 'Upacara untuk pesakit.', 'Upacara Tamarok dilaksanakan bagi menghalau kuasa ghaib daripada badan pesakit.'),
(545, 5, 'Apakah upacara Bajau yang diamalkan di Kota Belud?', 'Mag\'ombo', 'Tamarok', 'Ngeduang', 'Miring', 'C', 'Pantai barat Sabah.', 'Upacara Ngeduang diamalkan di pantai barat Sabah, Kota Belud.'),
(546, 5, 'Apakah yang dilakukan oleh keluarga si mati dalam upacara Ngeduang?', 'Menghalau kuasa ghaib daripada badan pesakit', 'Menjamu makanan kepada tetamu sebagai sedekah', 'Menghargai warisan di tepi pantai timur', 'Membacakan jampi mentera di tengah ladang', 'B', 'Berkait dengan makanan dan tetamu.', 'Dalam Ngeduang, keluarga si mati menjamu makanan kepada tetamu sebagai sedekah.'),
(547, 5, 'Di manakah upacara Mag\'ombo diadakan?', 'Kota Belud, pantai barat Sabah', 'Semporna, pantai timur Sabah', 'Tambunan, pedalaman Sabah', 'Kuching, bandar Sarawak', 'B', 'Pantai timur Sabah.', 'Etnik Bajau di pantai timur, Semporna, mengadakan upacara Mag\'ombo.'),
(548, 5, 'Apakah maksud Mag\'ombo?', 'Menjamu tetamu sebagai sedekah selepas kematian di Kota Belud', 'Menghalau kuasa ghaib daripada badan pesakit di ladang baharu', 'Menghargai dan menghormati warisan agar kehidupan dirahmati', 'Membaca jampi mentera sebelum membuka kawasan pertanian baharu', 'C', 'Berkait dengan warisan.', 'Mag\'ombo bermaksud menghargai dan menghormati warisan turun-temurun agar kehidupan dirahmati.'),
(549, 5, 'Apakah perbezaan Ngeduang dengan Mag\'ombo?', 'Ngeduang di Kota Belud, Mag\'ombo di Semporna', 'Ngeduang di Semporna, Mag\'ombo di Kota Belud', 'Kedua-duanya di Kota Belud sahaja', 'Kedua-duanya di Semporna sahaja', 'A', 'Pantai barat dan pantai timur.', 'Ngeduang diamalkan di pantai barat (Kota Belud), manakala Mag\'ombo di pantai timur (Semporna).'),
(550, 5, 'Antara berikut, yang manakah dikaitkan dengan masyarakat Bisaya di Sarawak?', 'Ngeduang', 'Tamarok', 'Mag\'ombo', 'Magavau', 'B', 'Upacara untuk pesakit.', 'Tamarok ialah upacara masyarakat Bisaya bagi menghalau kuasa ghaib daripada badan pesakit.'),
(601, 6, 'Antara berikut, yang manakah perayaan utama masyarakat di Malaysia?', 'Hari Kantin', 'Hari Wesak', 'Hari Pahlawan', 'Hari Sukan', 'B', 'Pilih perayaan dalam senarai.', 'Hari Wesak ialah salah satu perayaan utama masyarakat di Malaysia.'),
(602, 6, 'Antara berikut, yang manakah acara dalam Pesta Kaamatan?', 'Hari Gawai Dayak', 'Thaipusam Hindu', 'Unduk Ngadau', 'Vaisakhi Sikh', 'C', 'Acara memilih seorang pemenang.', 'Unduk Ngadau ialah acara pemilihan pemenang dalam Pesta Kaamatan.'),
(603, 6, 'Antara berikut, yang manakah termasuk perayaan utama selain Hari Raya Aidilfitri?', 'Hari Raya Cina Baharu', 'Hari Raya Siam Lama', 'Hari Raya Sabah Besar', 'Hari Raya Aidiladha', 'D', 'Dua Hari Raya dalam senarai.', 'Hari Raya Aidilfitri dan Hari Raya Aidiladha ialah dua perayaan utama masyarakat di Malaysia.'),
(604, 6, 'Krismas diraikan oleh penganut agama manakah?', 'Penganut Hindu', 'Penganut Kristian', 'Penganut Buddha', 'Penganut Sikh', 'B', 'Perayaan ini jatuh pada hujung tahun.', 'Krismas ialah salah satu perayaan utama masyarakat di Malaysia, diraikan oleh penganut Kristian.'),
(605, 6, 'Antara berikut, yang manakah perayaan utama bagi masyarakat Sarawak dan Sabah?', 'Hari Wesak dan Hari Thaipusam', 'Deepavali dan Vaisakhi Baharu', 'Krismas dan San Pedro lama', 'Hari Gawai dan Pesta Kaamatan', 'D', 'Satu untuk Sarawak, satu untuk Sabah.', 'Hari Gawai dan Pesta Kaamatan ialah perayaan utama masyarakat di Sarawak dan Sabah.'),
(606, 6, 'Antara berikut, yang manakah perayaan utama yang disambut selepas menuai padi dan hasil laut?', 'San Pedro', 'Thaipusam', 'Hari Wesak', 'Krismas', 'A', 'Berkait dengan hasil laut.', 'San Pedro ialah perayaan yang mensyukuri hasil laut.'),
(607, 6, 'Antara berikut, yang manakah termasuk dalam senarai perayaan utama?', 'Hari Pekerja', 'Hari Belia', 'Hari Guru', 'Thaipusam', 'D', 'Perayaan berkait dengan agama.', 'Thaipusam ialah salah satu perayaan utama masyarakat di Malaysia.'),
(608, 6, 'Mengapakah masyarakat Malaysia meraikan banyak perayaan?', 'Kerana hanya satu kaum mendiami negara ini', 'Kerana semua perayaan dilarang oleh kerajaan', 'Kerana terdiri daripada pelbagai kaum dan agama', 'Kerana tiada perayaan lama dirayakan lagi', 'C', 'Fikirkan kepelbagaian rakyat.', 'Masyarakat Malaysia meraikan banyak perayaan kerana terdiri daripada pelbagai kaum dan agama.'),
(609, 6, 'Apakah tujuan Hari Raya Aidilfitri, Hari Raya Aidiladha, Krismas dan Thaipusam?', 'Keagamaan', 'Meraikan tahun baharu', 'Mensyukuri hasil laut', 'Mengingati tokoh agama', 'A', 'Perayaan berkait dengan agama.', 'Hari Raya Aidilfitri, Aidiladha, Krismas dan Thaipusam diraikan atas tujuan keagamaan.'),
(610, 6, 'Perayaan manakah bertujuan meraikan tahun baharu?', 'Deepavali dan lampu', 'Tahun Baharu Cina', 'Hari Wesak Buddha', 'Hari Gawai Dayak', 'B', 'Namanya sendiri menyebut tahun baharu.', 'Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk dan Tawun Empai diraikan untuk meraikan tahun baharu.'),
(611, 6, 'Perayaan manakah ialah nama lain bagi sambutan tahun baharu?', 'Pesta Kaamatan', 'Tahon Baro', 'Hari Wesak', 'Thaipusam', 'B', 'Salah satu daripada senarai tahun baharu.', 'Tahon Baro ialah salah satu perayaan tahun baharu, bersama Jis Pai, Tahun Bahauk dan Tawun Empai.'),
(612, 6, 'Apakah tujuan Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro?', 'Meraikan tahun baharu secara rasmi', 'Mengingati tokoh agama', 'Mensyukuri hasil tanaman atau hasil laut', 'Menyambut kemerdekaan negara', 'C', 'Berkait dengan hasil bumi dan laut.', 'Perayaan ini diraikan untuk mensyukuri hasil tanaman atau hasil laut.'),
(613, 6, 'Apakah tujuan Deepavali diraikan?', 'Mensyukuri hasil tanaman dan hasil laut', 'Mengharapkan unsur baik mengatasi kejahatan', 'Meraikan tahun baharu secara bersama', 'Mengingati tokoh agama yang dihormati', 'B', 'Berkait dengan cahaya dan kegelapan.', 'Deepavali diraikan dengan harapan unsur baik mengatasi kejahatan.'),
(614, 6, 'Apakah tujuan Hari Wesak diraikan?', 'Mengingati tokoh agama', 'Meraikan tahun baharu', 'Mengharapkan kebaikan mengatasi kejahatan', 'Mensyukuri hasil laut', 'A', 'Berkait dengan seorang tokoh.', 'Hari Wesak diraikan untuk mengingati tokoh agama.'),
(615, 6, 'Perayaan manakah termasuk perayaan keagamaan?', 'Pesta Kaamatan', 'Thaipusam', 'San Pedro', 'Jis Pai', 'B', 'Pilih perayaan agama.', 'Thaipusam ialah perayaan keagamaan, bersama Aidilfitri, Aidiladha dan Krismas.'),
(616, 6, 'Perayaan manakah mensyukuri hasil tanaman atau hasil laut?', 'Krismas', 'Hari Wesak', 'Tahun Baharu Cina', 'Pesta Kaamatan', 'D', 'Pilih perayaan hasil bumi.', 'Pesta Kaamatan ialah perayaan mensyukuri hasil tanaman.'),
(617, 6, 'Antara berikut, yang manakah BUKAN tujuan perayaan di Malaysia?', 'Keagamaan', 'Meraikan tahun baharu', 'Memisahkan kaum dan agama', 'Mensyukuri hasil tanaman', 'C', 'Tujuan perayaan ialah menyatukan.', 'Perayaan di Malaysia dirayakan untuk tujuan keagamaan, tahun baharu, syukur hasil, kebaikan atasi kejahatan dan mengingati tokoh.'),
(618, 6, 'Bagaimanakah kad ucapan perayaan dihantar pada zaman dahulu?', 'Melalui media sosial sahaja', 'Melalui telefon pintar sahaja', 'Melalui e-mel dan telefon', 'Melalui pos atau serahan tangan', 'D', 'Tiada peranti digital pada zaman itu.', 'Dahulu kad ucapan dihantar melalui pos atau serahan tangan.'),
(619, 6, 'Bagaimanakah ucapan perayaan dihantar pada zaman kini?', 'Melalui pos dan serahan tangan di kampung', 'Melalui burung merpati dan perahu', 'Menggunakan media elektronik dan media sosial', 'Melalui surat yang ditulis tangan', 'C', 'Gunakan peranti yang ada kini.', 'Kini ucapan dihantar menggunakan media elektronik dan media sosial.'),
(620, 6, 'Di manakah foto keluarga diambil pada zaman dahulu?', 'Di kedai gambar', 'Di media sosial', 'Di telefon pintar', 'Di atas awan', 'A', 'Perlukan kamera lama dan studio.', 'Dahulu foto keluarga diambil di kedai gambar.'),
(621, 6, 'Bagaimanakah foto keluarga diambil pada zaman kini?', 'Swafoto bersama keluarga dan dimuat naik di media sosial', 'Di kedai gambar dengan kamera tripod lama dan lampu', 'Dilukis oleh pelukis jalanan di tepi jalan', 'Tiada foto diambil lagi oleh sesiapa pun', 'A', 'Guna telefon dan kongsi dalam talian.', 'Kini keluarga bergambar swafoto dan memuat naiknya di media sosial.'),
(622, 6, 'Apakah perbezaan ucapan perayaan dahulu dan kini?', 'Dahulu melalui media sosial; kini melalui pos sahaja', 'Dahulu dan kini sama sahaja tanpa sebarang perubahan', 'Dahulu melalui pos; kini media elektronik dan sosial', 'Dahulu telefon pintar; kini surat sahaja', 'C', 'Fikirkan perubahan teknologi.', 'Dahulu ucapan melalui pos atau serahan tangan; kini melalui media elektronik dan media sosial.'),
(623, 6, 'Apakah perbezaan foto keluarga dahulu dan kini?', 'Dahulu swafoto; kini di kedai gambar', 'Dahulu di kedai gambar; kini swafoto', 'Dahulu dan kini sama sahaja', 'Dahulu di sekolah; kini di bank', 'B', 'Fikirkan alat yang digunakan.', 'Dahulu foto keluarga di kedai gambar; kini swafoto dan dimuat naik di media sosial.'),
(624, 6, 'Apakah yang menjadikan ucapan kini lebih cepat sampai?', 'Penggunaan media elektronik dan media sosial', 'Penggunaan pos lama yang perlahan sampai', 'Penghantaran dengan tangan ke setiap rumah', 'Penggunaan kad bertulis tangan sahaja', 'A', 'Teknologi menjimatkan masa.', 'Media elektronik dan media sosial membolehkan ucapan sampai dengan pantas.'),
(625, 6, 'Perayaan manakah mempunyai tradisi membuat kolam?', 'Hari Wesak', 'Tahun Baharu Cina', 'Krismas', 'Deepavali', 'D', 'Dibuat di hadapan rumah.', 'Tradisi membuat kolam dilakukan ketika Deepavali.'),
(626, 6, 'Daripada apakah kolam dibuat pada zaman dahulu?', 'Beras berwarna', 'Hampas kelapa berwarna', 'Kertas berwarna', 'Tepung', 'D', 'Bahan putih biasa.', 'Dahulu kolam dibuat daripada tepung ketika Deepavali.'),
(627, 6, 'Daripada apakah kolam dibuat pada zaman kini?', 'Tepung putih sahaja tanpa warna lain', 'Batu hitam sahaja tanpa warna lain', 'Beras atau hampas kelapa berwarna-warni', 'Kertas lipat sahaja tanpa warna lain', 'C', 'Lebih berwarna-warni.', 'Kini kolam dihasilkan daripada beras atau hampas kelapa yang berwarna-warni.'),
(628, 6, 'Perayaan manakah mempunyai tradisi makan besar bersama keluarga?', 'Hari Gawai Dayak', 'Tahun Baharu Cina', 'Thaipusam Hindu', 'Hari Wesak Buddha', 'B', 'Berkumpul di meja bulat.', 'Tradisi makan besar diamalkan ketika Tahun Baharu Cina.'),
(629, 6, 'Di manakah makan besar Tahun Baharu Cina diraikan pada zaman dahulu?', 'Di rumah bersama keluarga', 'Di hotel mewah yang besar', 'Di restoran besar di bandar', 'Di padang awam kampung', 'A', 'Tempat keluarga berkumpul.', 'Dahulu makan besar diraikan di rumah dengan berkumpul bersama keluarga.'),
(630, 6, 'Di manakah sebahagian keluarga menikmati makan besar pada zaman kini?', 'Di rumah, restoran atau hotel', 'Hanya di sekolah kampung', 'Hanya di padang kampung', 'Hanya di pejabat pos lama', 'A', 'Ada pilihan lebih banyak kini.', 'Kini makan besar masih diraikan di rumah, tetapi ada keluarga yang memilih restoran atau hotel.'),
(631, 6, 'Apakah perbezaan kolam dahulu dan kini?', 'Dahulu beras berwarna; kini tepung putih sahaja', 'Dahulu dan kini sama sahaja tanpa perubahan', 'Dahulu kertas lipat; kini plastik berwarna', 'Dahulu tepung; kini beras atau hampas kelapa berwarna', 'D', 'Bahan makin berwarna-warni.', 'Dahulu kolam daripada tepung; kini daripada beras atau hampas kelapa berwarna-warni.'),
(632, 6, 'Bagaimanakah kuih-muih disediakan pada zaman dahulu?', 'Dengan mesin sepenuhnya di kilang tanpa gotong-royong', 'Dengan bahan dan kaedah tradisional secara gotong-royong', 'Dengan membeli di kedai sahaja tanpa membuat', 'Dengan menghantar kepada pengilang di bandar', 'B', 'Bergotong-royong dengan jiran.', 'Dahulu kuih-muih disediakan dengan bahan atau kaedah tradisional secara gotong-royong.'),
(633, 6, 'Bagaimanakah kuih-muih disediakan atau diperoleh pada zaman kini?', 'Hanya dengan kayu api dan tungku tanah liat lama', 'Menggunakan peralatan moden atau dibeli dengan mudah', 'Hanya melalui gotong-royong tanpa peralatan', 'Tiada kuih dibuat atau dijual lagi di rumah', 'B', 'Kemudahan teknologi.', 'Kini peralatan moden memudahkan penyediaan dan kuih raya juga mudah dibeli.'),
(634, 6, 'Antara berikut, yang manakah amalan yang kekal ketika perayaan?', 'Menghantar kad melalui pos', 'Membuat kolam daripada tepung', 'Mengambil foto di kedai gambar', 'Balik ke kampung', 'D', 'Amalan yang tidak berubah.', 'Tradisi balik ke kampung ialah amalan yang kekal.'),
(635, 6, 'Pemberian apakah merupakan amalan yang kekal ketika perayaan?', 'Duit raya', 'Kad pos', 'Foto kedai gambar', 'Tepung kolam', 'A', 'Diberi kepada kanak-kanak.', 'Pemberian duit raya ialah amalan yang kekal.'),
(636, 6, 'Amalan manakah dikekalkan walaupun zaman berubah?', 'Menghantar kad pos', 'Gotong-royong memasak kuih sahaja', 'Makan besar di rumah sahaja', 'Kunjung-mengunjung', 'D', 'Berkunjung ke rumah jiran dan saudara.', 'Amalan kunjung-mengunjung ialah amalan yang kekal.'),
(637, 6, 'Mengapakah amalan balik ke kampung kekal sehingga kini?', 'Kerana kampung sudah dilupakan', 'Kerana eratkan hubungan keluarga', 'Kerana sekolah ditutup', 'Kerana kuih sukar dibuat', 'B', 'Fikirkan kasih sayang dalam keluarga.', 'Balik ke kampung kekal kerana mengeratkan hubungan keluarga.'),
(638, 6, 'Antara berikut, yang manakah BUKAN amalan yang kekal?', 'Membuat kolam daripada tepung', 'Menghantar kad ucapan melalui pos', 'Mengambil foto di kedai gambar', 'Gotong-royong memasak kuih sahaja', 'B', 'Satu amalan sudah berubah.', 'Menghantar kad melalui pos sudah berubah, manakala tiga amalan lain kekal.'),
(639, 6, 'Apakah kelebihan kuih raya yang mudah dibeli kini?', 'Menjimatkan masa penyediaan', 'Menghapuskan semua perayaan', 'Menggantikan kunjung-mengunjung', 'Menghentikan balik kampung', 'A', 'Fikirkan kemudahan.', 'Kuih raya yang mudah dibeli menjimatkan masa penyediaan, tetapi amalan lain tetap kekal.'),
(640, 6, 'Siapakah yang meraikan Hari Gawai pada zaman dahulu?', 'Semua kaum tanpa mengira pekerjaan', 'Pelayar dari Eropah', 'Golongan petani daripada kaum Dayak', 'Pemain muzik istana', 'C', 'Berkait dengan tanaman.', 'Dahulu Hari Gawai diraikan oleh golongan petani daripada kaum Dayak.'),
(641, 6, 'Bagaimanakah Hari Gawai dahulu diraikan?', 'Dengan pelbagai upacara ritual', 'Dengan perarakan kereta sahaja', 'Dengan media sosial sahaja', 'Dengan persembahan wayang', 'A', 'Berkait dengan upacara.', 'Dahulu Hari Gawai diraikan dengan pelbagai upacara ritual.'),
(642, 6, 'Siapakah yang meraikan Hari Gawai pada zaman kini?', 'Petani kaum Dayak sahaja tanpa pekerja lain', 'Nelayan dari pantai timur sahaja tanpa lain', 'Pelbagai kaum tanpa mengira bidang pekerjaan', 'Pelombong sahaja tanpa kaum lain di kampung', 'C', 'Lebih terbuka kini.', 'Kini Hari Gawai diraikan oleh pelbagai kaum tanpa mengira bidang pekerjaan.'),
(643, 6, 'Apakah Unduk Ngadau?', 'Acara menanam padi paling cepat di sawah', 'Acara membuat kolam di hadapan rumah', 'Acara memilih pemenang dalam Pesta Kaamatan', 'Acara berarak di jalan raya bandar', 'C', 'Dikaitkan dengan Pesta Kaamatan.', 'Unduk Ngadau ialah acara pemilihan pemenang dalam Pesta Kaamatan.'),
(644, 6, 'Apakah semangat yang menjadi asas pemilihan pemenang Unduk Ngadau dahulu?', 'Semangat padi bukit sahaja', 'Semangat laut Mah Meri', 'Semangat Gawai Dayak', 'Semangat Huminodun', 'D', 'Nama itu ialah nama tokoh.', 'Dahulu pemenang dipilih berdasarkan semangat Huminodun.'),
(645, 6, 'Apakah maksud semangat Huminodun?', 'Kesanggupan menanam padi paling banyak di sawah', 'Kesanggupan menari paling lama di pentas', 'Kesanggupan berkorban demi menyelamatkan generasi', 'Kesanggupan menyanyi paling lantang di dewan', 'C', 'Berkait dengan pengorbanan.', 'Semangat Huminodun ialah kesanggupan berkorban demi menyelamatkan generasi.'),
(646, 6, 'Selain semangat Huminodun, bagaimanakah pemenang Unduk Ngadau kini dipilih?', 'Melalui sesi soal jawab sejarah dan kehidupan masyarakat lampau', 'Melalui pertandingan memasak kuih raya terbanyak di dapur kampung', 'Melalui perlumbaan perahu di sungai besar yang panjang itu', 'Melalui undian ramai di media sosial setiap malam', 'A', 'Menguji pengetahuan peserta.', 'Kini pemenang juga dipilih berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau.'),
(647, 6, 'Apakah perbezaan Unduk Ngadau dahulu dan kini?', 'Kini tiada pemenang dipilih langsung dalam acara', 'Dahulu ada sesi soal jawab sahaja tanpa Huminodun', 'Kini ada sesi soal jawab selain semangat Huminodun', 'Dahulu dan kini sama sahaja tanpa sebarang tambahan', 'C', 'Kini ada tambahan.', 'Dahulu pemenang dipilih berdasarkan semangat Huminodun; kini juga melalui sesi soal jawab.'),
(648, 6, 'Apakah persamaan Hari Gawai dan Pesta Kaamatan?', 'Kedua-duanya meraikan tahun baharu', 'Kedua-duanya mensyukuri hasil tanaman', 'Kedua-duanya mengingati tokoh agama', 'Kedua-duanya diraikan di Semenanjung sahaja', 'B', 'Fikirkan tujuan kedua-duanya.', 'Hari Gawai dan Pesta Kaamatan sama-sama diraikan untuk mensyukuri hasil tanaman.'),
(649, 6, 'Pesta Kaamatan disambut di negeri manakah?', 'Sarawak', 'Pahang', 'Kedah', 'Sabah', 'D', 'Kadazandusun.', 'Pesta Kaamatan ialah perayaan masyarakat di Sabah.'),
(650, 6, 'Mengapakah Hari Gawai dan Pesta Kaamatan penting kepada rakyat berbilang kaum?', 'Kerana perayaan boleh dikongsi dan diraikan bersama', 'Kerana hanya satu kaum sahaja boleh menyertainya', 'Kerana ia tidak pernah berubah sejak dahulu', 'Kerana ia menggantikan semua perayaan lain', 'A', 'Fikirkan perpaduan.', 'Kini Hari Gawai diraikan oleh pelbagai kaum, mencerminkan perayaan yang dikongsi bersama.'),
(701, 7, 'Siapakah Ketua Kerajaan yang mengetuai pentadbiran negara Malaysia?', 'Yang di-Pertuan Agong', 'Perdana Menteri', 'Ketua Hakim Negara', 'Speaker Dewan Rakyat', 'B', 'Ketua Kerajaan berbeza daripada Ketua Utama Negara.', 'Perdana Menteri ialah Ketua Kerajaan yang mengetuai pentadbiran negara.'),
(702, 7, 'Siapakah yang melantik Perdana Menteri secara rasmi?', 'Ketua Hakim Negara', 'Speaker Dewan Rakyat', 'Yang di-Pertuan Agong', 'Setiausaha Kerajaan Negeri', 'C', 'Beliau juga ialah Ketua Utama Negara.', 'Perdana Menteri dilantik secara rasmi oleh Yang di-Pertuan Agong, Ketua Utama Negara.'),
(703, 7, 'Yang di-Pertuan Agong dikenali sebagai apa dalam negara?', 'Ketua Kerajaan negara', 'Ketua Pentadbir Utama', 'Ketua Pembangkang rasmi', 'Ketua Utama Negara', 'D', 'Perdana Menteri pula ialah Ketua Kerajaan.', 'Yang di-Pertuan Agong ialah Ketua Utama Negara, manakala Perdana Menteri ialah Ketua Kerajaan.'),
(704, 7, 'Bilakah jawatan Perdana Menteri diwujudkan?', 'Selepas kemerdekaan', 'Sebelum kemerdekaan dicapai', 'Selepas peristiwa 13 Mei 1969', 'Selepas Wawasan 2020 dilancarkan', 'A', 'Tunku Abdul Rahman ialah Perdana Menteri pertama.', 'Jawatan Perdana Menteri diwujudkan selepas kemerdekaan.'),
(705, 7, 'Sehingga bilakah jawatan Perdana Menteri kekal dalam negara kita?', 'Dimansuhkan selepas Pembentukan Malaysia', 'Sehingga hari ini', 'Dimansuhkan selepas peristiwa 13 Mei 1969', 'Hanya sehingga Perdana Menteri keempat', 'B', 'Senarai Perdana Menteri sudah mencecah sembilan giliran.', 'Jawatan ini diwujudkan selepas kemerdekaan dan kekal hingga kini.');
INSERT INTO `Question` (`questionID`, `bankID`, `questionText`, `option_a`, `option_b`, `option_c`, `option_d`, `correctAnswer`, `hint`, `explanation`) VALUES
(706, 7, 'Yang manakah pernyataan yang betul tentang jawatan Perdana Menteri?', 'Ketua Kerajaan yang mengetuai pentadbiran negara dan dilantik secara rasmi oleh Yang di-Pertuan Agong', 'Ketua Utama Negara yang mengetuai pentadbiran negara dan dilantik secara rasmi oleh Dewan Rakyat', 'Ketua Kerajaan yang diwujudkan sebelum kemerdekaan dan dimansuhkan selepas itu oleh Parlimen', 'Ketua Utama Negara yang dilantik secara rasmi oleh Perdana Menteri yang terdahulu', 'A', 'Ingat dua ketua dan dua tugas yang berbeza.', 'Perdana Menteri ialah Ketua Kerajaan dan dilantik secara rasmi oleh Yang di-Pertuan Agong.'),
(707, 7, 'Siapakah Perdana Menteri pertama Malaysia?', 'Tun Abdul Razak bin Hussein', 'Tun Hussein bin Onn', 'Tun Dr. Mahathir bin Mohamad', 'Tunku Abdul Rahman Putra Al-Haj', 'D', 'Beliau memperjuangkan kemerdekaan secara rundingan.', 'Tunku Abdul Rahman Putra Al-Haj ialah Perdana Menteri pertama.'),
(708, 7, 'Siapakah Perdana Menteri kedua Malaysia?', 'Tun Abdul Razak bin Hussein', 'Tunku Abdul Rahman Putra Al-Haj', 'Tun Hussein bin Onn', 'Tun Abdullah bin Ahmad Badawi', 'A', 'Beliau memperkenalkan Dasar Ekonomi Baru.', 'Tun Abdul Razak bin Hussein ialah Perdana Menteri kedua.'),
(709, 7, 'Siapakah Perdana Menteri ketiga Malaysia?', 'Tun Abdul Razak bin Hussein', 'Tun Hussein bin Onn', 'Tun Dr. Mahathir bin Mohamad', 'Tun Abdullah bin Ahmad Badawi', 'B', 'Beliau memperkenalkan ASNB dan Rukun Tetangga.', 'Tun Hussein bin Onn ialah Perdana Menteri ketiga.'),
(710, 7, 'Siapakah Perdana Menteri keempat Malaysia?', 'Tun Hussein bin Onn', 'Tun Dr. Mahathir bin Mohamad', 'Tun Abdullah bin Ahmad Badawi', 'Dato\' Sri Mohd Najib bin Tun Abdul Razak', 'B', 'Beliau menjadi Perdana Menteri sekali lagi pada giliran ketujuh.', 'Tun Dr. Mahathir bin Mohamad ialah Perdana Menteri keempat dan juga ketujuh.'),
(711, 7, 'Siapakah Perdana Menteri kelima Malaysia?', 'Dato\' Sri Mohd Najib bin Tun Abdul Razak', 'Tan Sri Muhyiddin bin Md Yassin', 'Dato\' Seri Ismail Sabri bin Yaakob', 'Tun Abdullah bin Ahmad Badawi', 'D', 'Beliau datang selepas Perdana Menteri keempat.', 'Tun Abdullah bin Ahmad Badawi ialah Perdana Menteri kelima.'),
(712, 7, 'Siapakah Perdana Menteri keenam Malaysia?', 'Tun Abdullah bin Ahmad Badawi', 'Dato\' Sri Mohd Najib bin Tun Abdul Razak', 'Dato\' Seri Ismail Sabri bin Yaakob', 'Tan Sri Muhyiddin bin Md Yassin', 'B', 'Beliau memperkenalkan Gagasan 1Malaysia.', 'Dato\' Sri Mohd Najib bin Tun Abdul Razak ialah Perdana Menteri keenam.'),
(713, 7, 'Siapakah yang menjadi Perdana Menteri pada giliran keempat dan juga ketujuh?', 'Tun Abdullah bin Ahmad Badawi', 'Tun Dr. Mahathir bin Mohamad', 'Dato\' Sri Mohd Najib bin Tun Abdul Razak', 'Tan Sri Muhyiddin bin Md Yassin', 'B', 'Seorang tokoh muncul dua kali dalam senarai.', 'Tun Dr. Mahathir bin Mohamad ialah Perdana Menteri keempat dan ketujuh.'),
(714, 7, 'Siapakah Perdana Menteri kelapan dan kesembilan, mengikut giliran?', 'Tan Sri Muhyiddin bin Md Yassin, kemudian Dato\' Seri Ismail Sabri bin Yaakob', 'Dato\' Seri Ismail Sabri bin Yaakob, kemudian Tan Sri Muhyiddin bin Md Yassin', 'Dato\' Sri Mohd Najib bin Tun Abdul Razak, kemudian Tan Sri Muhyiddin bin Md Yassin', 'Tun Dr. Mahathir bin Mohamad, kemudian Dato\' Seri Ismail Sabri bin Yaakob', 'A', 'Kelapan dahulu, baru kesembilan.', 'Perdana Menteri kelapan ialah Tan Sri Muhyiddin bin Md Yassin dan kesembilan ialah Dato\' Seri Ismail Sabri bin Yaakob.'),
(715, 7, 'Sebagai penasihat kepada Yang di-Pertuan Agong, apakah yang dilakukan oleh Perdana Menteri?', 'Mempengerusikan Mesyuarat Majlis Raja-Raja menggantikan baginda sendiri', 'Mengiringi Yang di-Pertuan Agong ke Mesyuarat Majlis Raja-Raja', 'Memilih Raja-Raja yang akan hadir ke Mesyuarat Majlis Raja-Raja itu', 'Menyampaikan titah Yang di-Pertuan Agong tanpa mengiringi baginda ke mesyuarat', 'B', 'Perdana Menteri mengiringi, bukan mempengerusikan.', 'Perdana Menteri menjadi penasihat dan mengiringi Yang di-Pertuan Agong ke Mesyuarat Majlis Raja-Raja.'),
(716, 7, 'Mesyuarat manakah yang diiringi oleh Perdana Menteri bersama Yang di-Pertuan Agong?', 'Mesyuarat Majlis Raja-Raja', 'Mesyuarat Majlis Tindakan Ekonomi', 'Mesyuarat Dewan Undangan Negeri', 'Mesyuarat Agung Pertubuhan Pelajar', 'A', 'Majlis ini dihadiri oleh Raja-Raja.', 'Perdana Menteri mengiringi Yang di-Pertuan Agong ke Mesyuarat Majlis Raja-Raja.'),
(717, 7, 'Siapakah yang mempengerusikan Mesyuarat Jemaah Menteri?', 'Perdana Menteri', 'Yang di-Pertuan Agong', 'Ketua Setiausaha Negara', 'Speaker Dewan Rakyat', 'A', 'Beliau juga mencadangkan senarai Jemaah Menteri.', 'Perdana Menteri mempengerusikan Mesyuarat Jemaah Menteri.'),
(718, 7, 'Siapakah yang mencadangkan senarai Jemaah Menteri?', 'Majlis Raja-Raja negeri', 'Ketua Setiausaha Negara', 'Perdana Menteri', 'Speaker Dewan Rakyat', 'C', 'Menteri itu kemudian dilantik oleh Yang di-Pertuan Agong.', 'Perdana Menteri mencadangkan senarai Jemaah Menteri bagi menteri yang dilantik oleh Yang di-Pertuan Agong.'),
(719, 7, 'Apakah yang dilakukan oleh Perdana Menteri sebagai Ketua Pentadbir Utama?', 'Mengubah semua undang-undang negeri tanpa persetujuan sesiapa pun', 'Menyelaraskan dasar bagi satu negeri tertentu sahaja setiap tahun', 'Menjaga istana dan mengurus majlis rasmi kerajaan negeri sahaja', 'Merancang dan menyelaraskan semua dasar negara demi kesejahteraan rakyat', 'D', 'Dasar negara itu untuk semua rakyat.', 'Perdana Menteri merancang dan menyelaraskan semua dasar negara serta memastikan pembangunan ditingkatkan demi kesejahteraan rakyat.'),
(720, 7, 'Apakah tujuan Perdana Menteri memastikan pembangunan ditingkatkan?', 'Demi kepentingan negara jiran semata-mata', 'Demi kemasyhuran Perdana Menteri sendiri', 'Demi mengurangkan bilangan menteri', 'Demi kesejahteraan rakyat', 'D', 'Ia berkait dengan kehidupan rakyat.', 'Pembangunan ditingkatkan demi kesejahteraan rakyat.'),
(721, 7, 'Apakah tugas Perdana Menteri dalam menjalin hubungan diplomatik?', 'Mencadangkan pelantikan duta, diplomat dan konsulat', 'Melantik sendiri duta tanpa sebarang cadangan kerajaan', 'Menjadi duta kepada semua negara serentak', 'Menghantar surat kepada Majlis Raja-Raja sahaja', 'A', 'Tiga jawatan yang dicadangkan untuk negara luar.', 'Perdana Menteri mencadangkan pelantikan duta, diplomat dan konsulat untuk menjalin kerjasama dengan negara luar.'),
(722, 7, 'Antara yang berikut, yang manakah BUKAN tugas Perdana Menteri?', 'Mempengerusikan Mesyuarat Jemaah Menteri', 'Mencadangkan pelantikan duta, diplomat dan konsulat', 'Mengiringi Yang di-Pertuan Agong ke Mesyuarat Majlis Raja-Raja', 'Melantik sendiri Yang di-Pertuan Agong', 'D', 'Ingat siapa yang melantik Perdana Menteri.', 'Perdana Menteri dilantik oleh Yang di-Pertuan Agong, bukan sebaliknya.'),
(723, 7, 'Bagaimanakah Tunku Abdul Rahman memperjuangkan kemerdekaan?', 'Secara peperangan terbuka', 'Secara rundingan', 'Secara pemberontakan bersenjata', 'Secara pengusiran serta-merta', 'B', 'Beliau memilih berunding, bukan berperang.', 'Tunku memperjuangkan kemerdekaan secara rundingan.'),
(724, 7, 'Pada tarikh manakah Pembentukan Malaysia direalisasikan?', 'Pada 13 Mei 1969 itu juga', 'Pada 16 September 1963', 'Pada 31 Ogos 1957 dahulu', 'Pada 31 Disember 1999 itu', 'B', 'Ia berlaku pada zaman Perdana Menteri pertama.', 'Tunku merealisasikan Pembentukan Malaysia pada 16 September 1963.'),
(725, 7, 'Apakah pencapaian utama Tunku Abdul Rahman Putra Al-Haj?', 'Dasar Ekonomi Baru dan Majlis Gerakan Negara', 'Pembinaan Putrajaya dan Menara Berkembar Petronas', 'Kemerdekaan secara rundingan dan Pembentukan Malaysia', 'Amanah Saham Nasional Berhad dan Rukun Tetangga', 'C', 'Satu pencapaian ialah pada 16 September 1963.', 'Tunku memperjuangkan kemerdekaan secara rundingan dan merealisasikan Pembentukan Malaysia.'),
(726, 7, 'Peristiwa manakah yang mendahului penubuhan MAGERAN?', 'Pembentukan Malaysia 1963', 'Perintah Kawalan Pergerakan', 'Peristiwa 13 Mei 1969', 'Pengisytiharan Wawasan 2020', 'C', 'Tun Abdul Razak mengembalikan keamanan selepas peristiwa itu.', 'Tun Abdul Razak mengembalikan keamanan selepas peristiwa 13 Mei 1969 menerusi MAGERAN.'),
(727, 7, 'MAGERAN ialah singkatan bagi apakah?', 'Majlis Gabungan Negara', 'Majlis Gerakan Nasional', 'Majlis Gotong-royong Negeri', 'Majlis Gerakan Negara', 'D', 'Majlis ini mengembalikan keamanan.', 'MAGERAN bermaksud Majlis Gerakan Negara.'),
(728, 7, 'Apakah tujuan Dasar Ekonomi Baru (DEB)?', 'Membina kota pentadbiran baharu di Putrajaya', 'Menggalakkan industri berteknologi tinggi sahaja', 'Membasmi kemiskinan dan menyusun semula masyarakat', 'Memberi bantuan kewangan semasa pandemik', 'C', 'Dua tujuan: kemiskinan dan masyarakat.', 'DEB diperkenalkan untuk membasmi kemiskinan dan menyusun semula masyarakat.'),
(729, 7, 'Apakah pencapaian Tun Abdul Razak Hussein?', 'Memperkenalkan Wawasan 2020 dan membina Putrajaya serta KLIA', 'Memperkenalkan ASNB dan Program Rukun Tetangga untuk perpaduan', 'Memperkenalkan Gagasan 1Malaysia dan Program Transformasi Kerajaan', 'Mengembalikan keamanan melalui MAGERAN dan memperkenalkan DEB', 'D', 'Selepas 13 Mei 1969.', 'Tun Abdul Razak mengembalikan keamanan melalui MAGERAN dan memperkenalkan Dasar Ekonomi Baru.'),
(730, 7, 'Apakah tujuan Amanah Saham Nasional Berhad (ASNB)?', 'Pembinaan lebuh raya baharu', 'Pemilikan saham bumiputera', 'Bantuan kewangan semasa PKP', 'Pelan integriti penjawat awam', 'B', 'Ia berkait dengan saham.', 'ASNB diperkenalkan oleh Tun Hussein Onn untuk pemilikan saham bumiputera.'),
(731, 7, 'Apakah tujuan Program Rukun Tetangga?', 'Pemilikan saham bumiputera', 'Pembinaan koridor ekonomi', 'Bantuan kewangan semasa pandemik', 'Perpaduan', 'D', 'Jiran saling bertegur sapa.', 'Program Rukun Tetangga diperkenalkan oleh Tun Hussein Onn untuk perpaduan.'),
(732, 7, 'Siapakah yang memperkenalkan ASNB dan Program Rukun Tetangga?', 'Tun Abdul Razak Hussein', 'Tun Dr. Mahathir Mohamad', 'Tun Hussein Onn', 'Tun Abdullah Ahmad Badawi', 'C', 'Perdana Menteri ketiga.', 'Tun Hussein Onn memperkenalkan ASNB dan Program Rukun Tetangga.'),
(733, 7, 'Siapakah yang memperkenalkan Wawasan 2020?', 'Tun Abdul Razak Hussein', 'Tun Abdullah Ahmad Badawi', 'Tun Dr. Mahathir Mohamad', 'Dato\' Sri Mohd Najib Tun Abdul Razak', 'C', 'Perdana Menteri keempat dan ketujuh.', 'Wawasan 2020 diperkenalkan oleh Tun Dr. Mahathir Mohamad.'),
(734, 7, 'Apakah tujuan penubuhan HICOM?', 'Untuk bantuan kewangan semasa PKP', 'Untuk pemilikan saham bumiputera sahaja', 'Untuk menyusun semula masyarakat', 'Untuk industri berteknologi tinggi', 'D', 'Kilang dan mesin moden.', 'HICOM ditubuhkan oleh Tun Dr. Mahathir untuk industri berteknologi tinggi.'),
(735, 7, 'Apakah nama lain bagi Menara Berkembar Petronas?', 'KLIA', 'HICOM', 'PIN', 'KLCC', 'D', 'Singkatan nama pusat bandar tersebut.', 'Menara Berkembar Petronas turut dikenali sebagai KLCC.'),
(736, 7, 'Binaan manakah yang dikaitkan dengan kepimpinan Tun Dr. Mahathir?', 'Putrajaya, KLIA dan Menara Berkembar Petronas (KLCC)', 'Putrajaya, ASNB dan Menara Berkembar Petronas (KLCC)', 'KLIA, MAGERAN dan Menara Berkembar Petronas (KLCC)', 'Putrajaya, KLIA dan Koridor Wilayah Ekonomi (KLCC)', 'A', 'Tiga binaan besar pada zaman Perdana Menteri keempat.', 'Pembinaan Putrajaya, KLIA dan Menara Berkembar Petronas (KLCC) dikaitkan dengan Tun Dr. Mahathir.'),
(737, 7, 'Yang manakah pencapaian Tun Dr. Mahathir Mohamad?', 'Wawasan 2020, Koridor Wilayah Ekonomi dan PIN', 'Gagasan 1Malaysia, GTP, KLIA dan HICOM', 'Wawasan 2020, Putrajaya, KLIA, KLCC dan HICOM', 'Wawasan 2020, MTE, KLCC dan Keluarga Malaysia', 'C', 'Banyak pembinaan besar dan satu wawasan.', 'Pencapaian Tun Dr. Mahathir ialah Wawasan 2020, Putrajaya, KLIA, KLCC dan HICOM.'),
(738, 7, 'Apakah pencapaian Tun Abdullah Ahmad Badawi?', 'Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP)', 'Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN)', 'Majlis Tindakan Ekonomi (MTE) dan bantuan semasa PKP', 'Wawasan 2020 dan pembinaan Putrajaya dan KLIA', 'B', 'Perdana Menteri kelima.', 'Tun Abdullah Ahmad Badawi memperkenalkan Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).'),
(739, 7, 'PIN ialah singkatan bagi apakah?', 'Pelan Integriti Nasional', 'Pelan Industri Nasional', 'Program Integriti Negara', 'Pelan Insentif Negeri', 'A', 'Ia berkait dengan integriti.', 'PIN bermaksud Pelan Integriti Nasional.'),
(740, 7, 'Siapakah yang memperkenalkan Gagasan 1Malaysia?', 'Tun Abdullah Ahmad Badawi', 'Tan Sri Muhyiddin Md Yassin', 'Dato\' Sri Mohd Najib Tun Abdul Razak', 'Dato\' Seri Ismail Sabri Yaakob', 'C', 'Perdana Menteri keenam.', 'Gagasan 1Malaysia dan GTP diperkenalkan oleh Dato\' Sri Mohd Najib Tun Abdul Razak.'),
(741, 7, 'GTP ialah singkatan bagi apakah?', 'Program Transformasi Kerajaan', 'Program Tindakan Ekonomi Rakyat', 'Pelan Transformasi Industri Negeri', 'Gagasan Tindakan Perpaduan Rakyat', 'A', 'Program ini diperkenalkan bersama Gagasan 1Malaysia.', 'GTP bermaksud Program Transformasi Kerajaan (Government Transformation Programme).'),
(742, 7, 'Majlis manakah yang ditubuhkan oleh Tan Sri Muhyiddin Md Yassin?', 'Majlis Gerakan Negara (MAGERAN)', 'Majlis Tindakan Ekonomi (MTE)', 'Majlis Raja-Raja', 'Majlis Integriti Nasional', 'B', 'Majlis ini berkait dengan ekonomi.', 'Tan Sri Muhyiddin Md Yassin menubuhkan Majlis Tindakan Ekonomi (MTE).'),
(743, 7, 'Semasa apakah bantuan kewangan dan peruntukan besar diumumkan oleh Tan Sri Muhyiddin?', 'Semasa PKP pandemik COVID-19', 'Semasa peristiwa 13 Mei 1969', 'Semasa Pembentukan Malaysia', 'Semasa pelancaran Wawasan 2020', 'A', 'PKP bermaksud Perintah Kawalan Pergerakan.', 'Bantuan kewangan dan peruntukan besar diumumkan semasa Perintah Kawalan Pergerakan (PKP) pandemik COVID-19.'),
(744, 7, 'Apakah pencapaian Tan Sri Muhyiddin Md Yassin?', 'Menubuhkan MTE dan mengumumkan bantuan semasa PKP', 'Memperkenalkan Keluarga Malaysia dan Wawasan 2020', 'Memperkenalkan Gagasan 1Malaysia dan GTP', 'Memperkenalkan PIN dan Koridor Wilayah Ekonomi', 'A', 'Perdana Menteri kelapan.', 'Tan Sri Muhyiddin menubuhkan MTE dan mengumumkan bantuan kewangan serta peruntukan besar semasa PKP.'),
(745, 7, 'Apakah konsep yang diperkenalkan oleh Dato\' Seri Ismail Sabri Yaakob?', 'Gagasan 1Malaysia', 'Wawasan 2020', 'Keluarga Malaysia', 'Rukun Tetangga', 'C', 'Perdana Menteri kesembilan.', 'Dato\' Seri Ismail Sabri Yaakob memperkenalkan konsep Keluarga Malaysia.'),
(746, 7, 'Apakah yang diraikan oleh konsep Keluarga Malaysia?', 'Keterangkuman satu bangsa dan satu agama sahaja', 'Keterangkuman pelbagai negara jiran', 'Keterangkuman pelbagai agama, bangsa, kaum dan usia', 'Keterangkuman kumpulan peniaga dan pelabur', 'C', 'Semua orang ada tempat dalam keluarga.', 'Keluarga Malaysia meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.'),
(747, 7, 'Berapakah giliran Perdana Menteri dalam senarai, dan mengapa jumlah orangnya lebih sedikit?', 'Sembilan giliran, kerana Tun Dr. Mahathir menjadi Perdana Menteri dua kali', 'Sembilan giliran, kerana Tunku Abdul Rahman memegang jawatan dua kali', 'Lapan giliran, kerana Tun Dr. Mahathir memegang jawatan sekali', 'Sepuluh giliran, kerana ada dua orang memegang jawatan dua kali', 'A', 'Satu tokoh disebut pada giliran keempat dan ketujuh.', 'Senarai mempunyai sembilan giliran, tetapi Tun Dr. Mahathir ialah Perdana Menteri keempat dan ketujuh.'),
(748, 7, 'Yang manakah susunan pencapaian yang betul mengikut urutan Perdana Menteri?', 'MAGERAN dan DEB, kemudian ASNB dan Rukun Tetangga, kemudian kemerdekaan', 'ASNB dan Rukun Tetangga, kemudian kemerdekaan, kemudian MAGERAN dan DEB', 'Kemerdekaan secara rundingan, MAGERAN dan DEB, kemudian ASNB dan Rukun Tetangga', 'Kemerdekaan secara rundingan, ASNB dan Rukun Tetangga, kemudian MAGERAN dan DEB', 'C', 'Mulakan dengan Perdana Menteri pertama.', 'Tunku (kemerdekaan secara rundingan), Tun Abdul Razak (MAGERAN dan DEB) dan Tun Hussein Onn (ASNB dan Rukun Tetangga).'),
(749, 7, 'Yang manakah padanan Perdana Menteri dan pencapaiannya yang betul?', 'Tunku Abdul Rahman dan Amanah Saham Nasional', 'Tun Abdullah Badawi dan Wawasan 2020', 'Tun Abdul Razak dan Koridor Wilayah Ekonomi', 'Tun Hussein Onn dan Program Rukun Tetangga', 'D', 'Rukun Tetangga membawa perpaduan.', 'Program Rukun Tetangga diperkenalkan oleh Tun Hussein Onn.'),
(750, 7, 'Yang manakah padanan Perdana Menteri dan pencapaiannya yang betul?', 'Dato\' Sri Najib dan Majlis Tindakan Ekonomi', 'Dato\' Seri Ismail Sabri dan Keluarga Malaysia', 'Tan Sri Muhyiddin dan Gagasan 1Malaysia', 'Tun Dr. Mahathir dan Pelan Integriti Nasional', 'B', 'Konsep ini meraikan pelbagai agama, bangsa, kaum dan usia.', 'Dato\' Seri Ismail Sabri memperkenalkan konsep Keluarga Malaysia.'),
(801, 8, 'Ekonomi yang dijalankan secara kecil-kecilan dengan peralatan mudah dikenali sebagai apa?', 'Ekonomi komersial secara perladangan', 'Ekonomi tradisional', 'Ekonomi moden berasaskan mesin', 'Ekonomi eksport berskala besar', 'B', 'Fikirkan cangkul dan sabit.', 'Ekonomi tradisional dijalankan secara kecil-kecilan, menggunakan peralatan mudah, modal kecil dan tenaga kerja yang sedikit.'),
(802, 8, 'Antara yang berikut, yang manakah peralatan ekonomi tradisional?', 'Cangkul dan sabit', 'Mesin dan jentera penuai', 'Jentera pembajak moden', 'Mesin penuai kelapa sawit', 'A', 'Peralatan mudah, tiada mesin.', 'Peralatan ekonomi tradisional ialah peralatan mudah seperti cangkul dan sabit.'),
(803, 8, 'Untuk siapakah hasil ekonomi tradisional digunakan?', 'Kegunaan tempatan dan eksport ke luar negara', 'Pasaran antarabangsa dan syarikat besar', 'Syarikat perladangan yang menggunakan jentera', 'Keperluan sendiri dan keluarga', 'D', 'Dijalankan secara kecil-kecilan.', 'Hasil ekonomi tradisional digunakan untuk keperluan sendiri atau keluarga.'),
(804, 8, 'Bagaimanakah modal dan tenaga kerja dalam ekonomi tradisional?', 'Modal kecil dan tenaga kerja sedikit', 'Modal besar dan tenaga kerja banyak', 'Modal besar dan tenaga kerja sedikit', 'Modal kecil dan tenaga kerja banyak', 'A', 'Kedua-duanya kecil atau sedikit.', 'Ekonomi tradisional menggunakan modal kecil dan tenaga kerja yang sedikit.'),
(805, 8, 'Ekonomi komersial dijalankan secara apa?', 'Secara kecil-kecilan di halaman rumah', 'Secara perladangan', 'Secara tukar barang dengan jiran', 'Secara sara diri untuk keluarga', 'B', 'Kawasan yang luas dan teratur.', 'Ekonomi komersial dijalankan secara perladangan.'),
(806, 8, 'Antara yang berikut, yang manakah peralatan ekonomi komersial?', 'Cangkul dan sabit kecil', 'Cangkul dan parang tangan', 'Mesin dan jentera penuai', 'Sabit dan bakul rotan', 'C', 'Peralatan moden berskala besar.', 'Ekonomi komersial menggunakan peralatan moden seperti mesin dan jentera penuai.'),
(807, 8, 'Bagaimanakah modal dan tenaga kerja dalam ekonomi komersial?', 'Modal besar dan tenaga kerja banyak', 'Modal kecil dan tenaga kerja sedikit', 'Modal kecil dan tenaga kerja banyak', 'Modal besar dan tenaga kerja sedikit', 'A', 'Perladangan memerlukan banyak sumber.', 'Ekonomi komersial menggunakan modal besar dan tenaga kerja yang banyak.'),
(808, 8, 'Untuk kegunaan apakah hasil ekonomi komersial?', 'Keperluan sendiri dan keluarga sahaja', 'Keperluan jiran dekat dan saudara mara', 'Kegunaan tempatan dan eksport', 'Keperluan dapur sendiri pada hujung minggu', 'C', 'Dijual jauh sehingga ke luar negara.', 'Hasil ekonomi komersial digunakan untuk kegunaan tempatan dan eksport.'),
(809, 8, 'Apakah kesan industri getah dan kelapa sawit terhadap pendapatan negara?', 'Menurunkan pendapatan negara', 'Meningkatkan pendapatan negara', 'Tidak mengubah pendapatan negara', 'Menggantikan semua pendapatan lain', 'B', 'Pendapatan itu menjadi lebih banyak.', 'Industri getah dan kelapa sawit meningkatkan pendapatan negara.'),
(810, 8, 'Apakah yang disediakan oleh industri getah dan kelapa sawit kepada rakyat?', 'Biasiswa kepada semua pelajar', 'Penajaan sukan permotoran', 'Tiket kempen pelancongan', 'Peluang pekerjaan', 'D', 'Penoreh dan pekerja ladang mendapat kerja.', 'Industri getah dan kelapa sawit menyediakan peluang pekerjaan.'),
(811, 8, 'Industri manakah diwujudkan hasil perkembangan getah dan kelapa sawit untuk memproses hasilnya?', 'Industri stesen minyak', 'Industri hiliran', 'Industri penajaan sukan', 'Industri kereta nasional', 'B', 'Ia mengambil hasil dan menjadikannya produk lain.', 'Industri getah dan kelapa sawit mewujudkan industri hiliran.'),
(812, 8, 'Industri manakah dimajukan oleh perkembangan getah dan kelapa sawit?', 'Industri asas tani', 'Industri pelancongan antarabangsa', 'Industri automotif nasional', 'Industri petroleum dan gas', 'A', 'Industri ini berkait dengan pertanian.', 'Industri getah dan kelapa sawit memajukan industri asas tani.'),
(813, 8, 'Industri bahan api manakah dibangunkan oleh industri getah dan kelapa sawit?', 'Industri petrol dan gas memasak', 'Industri minyak pelincir kenderaan', 'Industri bateri kereta elektrik', 'Industri biodiesel', 'D', 'Bahan api daripada hasil kelapa sawit.', 'Industri getah dan kelapa sawit membangunkan industri biodiesel.'),
(814, 8, 'Yang manakah pernyataan yang betul tentang kesan industri getah dan kelapa sawit?', 'Meningkatkan pendapatan negara, melahirkan usahawan stesen minyak dan menyediakan biasiswa', 'Menyediakan biasiswa, menaja sukan permotoran dan melahirkan usahawan stesen minyak', 'Meningkatkan pendapatan negara, mewujudkan industri hiliran dan membangunkan industri biodiesel', 'Mewujudkan PROTON dan PERODUA serta membangunkan kempen Tahun Melawat Malaysia', 'C', 'Ingat lima kesan: pendapatan, pekerjaan, hiliran, asas tani dan biodiesel.', 'Lima kesan industri getah dan kelapa sawit ialah pendapatan negara, peluang pekerjaan, industri hiliran, industri asas tani dan industri biodiesel.'),
(815, 8, 'Siapakah yang dilahirkan oleh industri petroleum dan gas di sepanjang jalan raya?', 'Usahawan kedai bunga', 'Usahawan kilang kasut', 'Usahawan stesen minyak', 'Usahawan pasar tani', 'C', 'Mereka menjual petrol kepada pemandu.', 'Industri petroleum dan gas melahirkan usahawan stesen minyak.'),
(816, 8, 'Bagaimanakah industri petroleum dan gas meningkatkan pendapatan?', 'Menerusi penanaman padi di pelantar', 'Menerusi penjualan tiket kapal terbang', 'Menerusi penubuhan kebun getah', 'Menerusi penajaan sukan permotoran', 'D', 'Syarikat petroleum menaja perlumbaan.', 'Industri petroleum dan gas meningkatkan pendapatan menerusi penajaan sukan permotoran.'),
(817, 8, 'Apakah yang disediakan kepada pelajar oleh industri petroleum dan gas?', 'Pinjaman kereta', 'Tiket perlumbaan percuma', 'Tanah ladang kelapa sawit', 'Biasiswa', 'D', 'Pelajar belajar dengan bantuan kewangan.', 'Industri petroleum dan gas menyediakan biasiswa.'),
(818, 8, 'Apakah yang diwujudkan oleh industri petroleum dan gas bagi rakyat?', 'Hanya hutan simpan', 'Peluang pekerjaan', 'Hanya tapak bersejarah', 'Hanya ladang getah', 'B', 'Jurutera dan juruteknik bekerja di pelantar.', 'Industri petroleum dan gas mewujudkan peluang pekerjaan.'),
(819, 8, 'Yang manakah pernyataan yang betul tentang industri petroleum dan gas?', 'Melahirkan usahawan stesen minyak tetapi tidak menyediakan sebarang biasiswa kepada pelajar', 'Menyediakan biasiswa tetapi tidak mewujudkan sebarang peluang pekerjaan kepada rakyat', 'Mewujudkan peluang pekerjaan, melahirkan usahawan stesen minyak dan menyediakan biasiswa', 'Meningkatkan pendapatan menerusi penajaan tetapi tidak melahirkan sebarang usahawan', 'C', 'Ingat empat kesan: pekerjaan, usahawan, penajaan dan biasiswa.', 'Empat kesan industri petroleum dan gas ialah peluang pekerjaan, usahawan stesen minyak, pendapatan menerusi penajaan sukan permotoran dan biasiswa.'),
(820, 8, 'Antara yang berikut, yang manakah BUKAN kesan industri petroleum dan gas?', 'Membangunkan industri biodiesel', 'Melahirkan usahawan stesen minyak', 'Menyediakan biasiswa', 'Mewujudkan peluang pekerjaan', 'A', 'Industri biodiesel berkait dengan kelapa sawit.', 'Industri biodiesel dibangunkan oleh industri getah dan kelapa sawit, bukan oleh industri petroleum dan gas.'),
(821, 8, 'Pada tahun berapakah PROTON ditubuhkan?', '1983', '1993', '2018', '1973', 'A', 'Ia ditubuhkan lebih awal daripada PERODUA.', 'PROTON ditubuhkan pada tahun 1983.'),
(822, 8, 'Pada tahun berapakah PERODUA ditubuhkan?', '1983', '1993', '2018', '1963', 'B', 'Ia ditubuhkan sepuluh tahun selepas PROTON.', 'PERODUA ditubuhkan pada tahun 1993.'),
(823, 8, 'PROTON mengadakan usaha sama pada tahun 2018 dengan syarikat apa?', 'PERODUA Holding Group', 'Geely Holding Group', 'Petronas Holding Group', 'Proton Holding Group', 'B', 'Syarikat luar negara.', 'PROTON mengadakan usaha sama dengan Geely Holding Group pada tahun 2018.'),
(824, 8, 'Yang manakah susunan yang betul mengikut tahun dalam industri automotif?', 'PERODUA 1983, PROTON 1993, usaha sama PROTON dengan Geely 2018', 'PROTON 1983, usaha sama dengan Geely 1993, PERODUA 2018', 'Usaha sama dengan Geely 1983, PROTON 1993, PERODUA 2018', 'PROTON 1983, PERODUA 1993, usaha sama PROTON dengan Geely 2018', 'D', 'Mulakan dengan tahun yang paling awal.', 'PROTON (1983), PERODUA (1993), usaha sama PROTON dengan Geely Holding Group (2018).'),
(825, 8, 'Antara PROTON dan PERODUA, yang manakah ditubuhkan lebih awal?', 'PERODUA', 'Kedua-duanya pada tahun yang sama', 'Geely Holding Group', 'PROTON', 'D', 'Bandingkan 1983 dengan 1993.', 'PROTON ditubuhkan pada 1983, manakala PERODUA pada 1993.'),
(826, 8, 'Kempen apakah yang dipacu oleh keistimewaan tapak sejarah, alam semula jadi dan keharmonian budaya?', 'Tahun Wawasan Malaysia', 'Tahun Melawat Malaysia', 'Tahun Perpaduan Malaysia', 'Tahun Perladangan Malaysia', 'B', 'Kempen ini mengajak pelancong datang.', 'Kempen Tahun Melawat Malaysia dipacu oleh pelbagai keistimewaan negara.'),
(827, 8, 'Yang manakah pemacu kempen Tahun Melawat Malaysia?', 'Penutupan semua taman negara', 'Kenaikan harga makanan di hotel', 'Penghentian semua pameran antarabangsa', 'Tapak dan bangunan bersejarah', 'D', 'Pelancong gemar melawat tempat lama yang bernilai.', 'Tapak dan bangunan bersejarah ialah salah satu pemacu kempen Tahun Melawat Malaysia.'),
(828, 8, 'Yang manakah keistimewaan semula jadi yang memacu kempen Tahun Melawat Malaysia?', 'Gudang e-dagang', 'Kilang kereta nasional', 'Alam semula jadi', 'Pelantar minyak di laut', 'C', 'Hutan, air terjun dan pantai.', 'Alam semula jadi memacu kempen Tahun Melawat Malaysia.'),
(829, 8, 'Pelancongan yang berkait dengan ladang dan kebun dikenali sebagai apa?', 'Eko-industri', 'Pelancongan sukan', 'Agropelancongan', 'Pelancongan angkasa', 'C', 'Pelancong menikmati suasana pertanian.', 'Agropelancongan ialah salah satu pemacu kempen Tahun Melawat Malaysia.'),
(830, 8, 'Penganjuran apakah yang turut menarik pelancong ke Malaysia?', 'Sukan, muzik dan pameran antarabangsa', 'Pasar malam tempatan sahaja', 'Mesyuarat jemaah menteri sahaja', 'Pertandingan tanam padi sahaja', 'A', 'Acara besar yang disertai peserta luar negara.', 'Penganjuran sukan, muzik dan pameran antarabangsa turut menarik pelancong.'),
(831, 8, 'Antara yang berikut, yang manakah BUKAN pemacu kempen Tahun Melawat Malaysia?', 'Keharmonian budaya negara', 'Agropelancongan di ladang', 'Penutupan semua tapak bersejarah', 'Alam semula jadi yang indah', 'C', 'Pemacu menarik pelancong, bukan menjauhkan mereka.', 'Tapak bersejarah memacu kempen itu, jadi penutupannya bukan pemacu.'),
(832, 8, 'Yang manakah produk pertanian jenama Malaysia?', 'Minyak petrol, gas memasak dan minyak pelincir', 'Minyak masak, buah durian, buah nanas dan sabun', 'Motosikal, kereta dan minyak pelincir', 'Minyak petrol, buah durian dan motosikal', 'B', 'Hasil tanaman dan olahannya.', 'Produk pertanian ialah minyak masak, buah durian, buah nanas dan sabun.'),
(833, 8, 'Buah durian termasuk dalam kumpulan produk apa?', 'Produk pertanian', 'Produk petroleum', 'Produk automotif', 'Produk perhubungan', 'A', 'Hasil tanaman.', 'Buah durian ialah produk pertanian jenama Malaysia.'),
(834, 8, 'Yang manakah produk petroleum jenama Malaysia?', 'Minyak masak, buah durian, sabun dan gas untuk memasak', 'Minyak petrol, gas untuk memasak dan minyak pelincir kenderaan', 'Motosikal, kereta, minyak petrol dan gas untuk memasak', 'Buah nanas, minyak petrol, sabun dan kereta jenama nasional', 'B', 'Hasil minyak dan gas.', 'Produk petroleum ialah minyak petrol, gas untuk memasak dan minyak pelincir kenderaan.'),
(835, 8, 'Gas untuk memasak termasuk dalam kumpulan produk apa?', 'Produk pertanian', 'Produk automotif', 'Produk petroleum', 'Produk perladangan', 'C', 'Ia berasal daripada industri minyak dan gas.', 'Gas untuk memasak ialah produk petroleum.'),
(836, 8, 'Yang manakah produk automotif jenama Malaysia?', 'Minyak petrol dan kereta', 'Motosikal dan kereta', 'Sabun dan motosikal', 'Gas memasak dan kereta', 'B', 'Kenderaan berenjin.', 'Produk automotif ialah motosikal dan kereta.'),
(837, 8, 'Sabun termasuk dalam kumpulan produk apa?', 'Produk petroleum', 'Produk automotif', 'Produk pertanian', 'Produk pelancongan', 'C', 'Ia disenaraikan bersama minyak masak.', 'Sabun ialah produk pertanian jenama Malaysia.'),
(838, 8, 'Minyak pelincir kenderaan termasuk dalam kumpulan produk apa?', 'Produk pertanian', 'Produk automotif', 'Produk petroleum', 'Produk pelancongan', 'C', 'Ia dibuat daripada hasil minyak.', 'Minyak pelincir kenderaan ialah produk petroleum.'),
(839, 8, 'Yang manakah padanan produk dan kumpulannya yang betul?', 'Buah nanas dengan produk pertanian', 'Gas memasak dengan produk automotif', 'Motosikal dengan produk pertanian', 'Minyak petrol dengan produk pertanian', 'A', 'Fikirkan dari mana produk itu datang.', 'Buah nanas ialah produk pertanian jenama Malaysia.'),
(840, 8, 'Apakah tanda pembangunan dalam pencapaian ekonomi Malaysia?', 'Kewujudan kebun getah di kampung sahaja', 'Kewujudan sawah padi di kampung sahaja', 'Kewujudan pasar tani di kampung sahaja', 'Kewujudan bangunan pencakar langit', 'D', 'Bangunan yang menjulang tinggi di bandar.', 'Pembangunan ditandai oleh kewujudan bangunan pencakar langit.'),
(841, 8, 'Apakah yang dimaksudkan dengan perhubungan dalam pencapaian ekonomi Malaysia?', 'Jaringan perhubungan lama yang tidak teratur', 'Hanya jalan kampung sahaja', 'Hanya perhubungan melalui pos', 'Jaringan perhubungan moden yang terancang', 'D', 'Kereta api, jambatan layang dan lebuh raya.', 'Perhubungan ialah jaringan perhubungan moden yang terancang.'),
(842, 8, 'Apakah kegiatan perdagangan yang semakin berkembang di Malaysia?', 'Kegiatan e-dagang', 'Kegiatan tukar barang di pasar', 'Kegiatan menoreh getah di kebun', 'Kegiatan membajak sawah tradisional', 'A', 'Jual beli menggunakan telefon dan internet.', 'Perdagangan ditandai oleh kegiatan e-dagang yang semakin berkembang.'),
(843, 8, 'Yang manakah padanan yang betul bagi pencapaian ekonomi Malaysia?', 'Pembangunan dengan kegiatan e-dagang', 'Perhubungan dengan jaringan moden yang terancang', 'Perdagangan dengan bangunan pencakar langit', 'Perhubungan dengan jual beli secara tukar barang', 'B', 'Setiap tajuk ada ciri yang tersendiri.', 'Pembangunan: pencakar langit; perhubungan: jaringan moden terancang; perdagangan: e-dagang.'),
(844, 8, 'Yang manakah susunan pencapaian yang betul bagi pembangunan, perhubungan dan perdagangan?', 'E-dagang, pencakar langit, jaringan moden yang terancang', 'Jaringan moden yang terancang, e-dagang, pencakar langit', 'Pencakar langit, e-dagang, jaringan moden yang terancang', 'Pencakar langit, jaringan moden yang terancang, e-dagang', 'D', 'Ikut urutan tajuk: pembangunan, perhubungan dan perdagangan.', 'Pembangunan ialah pencakar langit, perhubungan ialah jaringan moden yang terancang dan perdagangan ialah e-dagang.'),
(845, 8, 'Yang manakah kegiatan ekonomi pemacu kemajuan negara?', 'Getah dan kelapa sawit, petroleum dan gas, automotif serta pelancongan', 'Getah dan kelapa sawit, sawah padi, nelayan serta perikanan laut', 'Petroleum dan gas, tenusu, perikanan serta kraf tangan kampung', 'Automotif, perikanan, tenusu serta kraf tangan kampung lama', 'A', 'Empat kegiatan utama.', 'Kegiatan ekonomi pemacu ialah industri getah dan kelapa sawit, petroleum dan gas, automotif serta pelancongan.'),
(846, 8, 'Ladang kelapa sawit yang menggunakan jentera penuai dan mengeksport hasil tergolong dalam ekonomi apa?', 'Ekonomi komersial', 'Ekonomi tradisional', 'Ekonomi untuk keluarga sahaja', 'Ekonomi kecil-kecilan', 'A', 'Perhatikan peralatan dan pasarannya.', 'Perladangan dengan peralatan moden dan hasil untuk eksport ialah ekonomi komersial.'),
(847, 8, 'Industri manakah mewujudkan industri hiliran dan industri biodiesel?', 'Industri petroleum dan gas', 'Industri automotif', 'Industri getah dan kelapa sawit', 'Industri pelancongan', 'C', 'Hasil tanaman diproses menjadi produk lain.', 'Industri hiliran dan biodiesel diwujudkan oleh industri getah dan kelapa sawit.'),
(848, 8, 'Industri manakah melahirkan usahawan stesen minyak?', 'Industri petroleum dan gas', 'Industri getah dan kelapa sawit', 'Industri automotif', 'Industri pelancongan', 'A', 'Stesen minyak menjual petrol.', 'Industri petroleum dan gas melahirkan usahawan stesen minyak.'),
(849, 8, 'Industri manakah ditandai oleh penubuhan PROTON dan PERODUA?', 'Industri pelancongan', 'Industri getah dan kelapa sawit', 'Industri petroleum dan gas', 'Industri automotif', 'D', 'Kereta nasional.', 'PROTON dan PERODUA ialah nama besar dalam industri automotif.'),
(850, 8, 'Yang manakah pernyataan yang betul tentang ekonomi tradisional dan ekonomi komersial?', 'Tradisional menggunakan modal besar dan jentera; komersial menggunakan modal kecil', 'Tradisional menggunakan cangkul dan sabit; komersial menggunakan mesin dan jentera penuai', 'Tradisional dijalankan secara perladangan; komersial dijalankan secara kecil-kecilan', 'Tradisional untuk eksport ke luar negara; komersial untuk keperluan keluarga sahaja', 'B', 'Bandingkan peralatan, modal dan hasil.', 'Ekonomi tradisional menggunakan peralatan mudah seperti cangkul dan sabit, manakala ekonomi komersial menggunakan peralatan moden seperti mesin dan jentera penuai.'),
(901, 9, 'Badan manakah yang menguruskan sukan badminton di Malaysia?', 'Persatuan Bola Sepak Malaysia (FAM)', 'Persatuan Badminton Malaysia (BAM)', 'Konfederasi Hoki Malaysia (MHC)', 'Kesatuan Olahraga Malaysia (KOM)', 'B', 'Singkatannya bermula dengan huruf B.', 'Persatuan Badminton Malaysia (BAM) menguruskan sukan badminton.'),
(902, 9, 'Siapakah antara atlet badminton contoh Malaysia?', 'Soh Chin Ann, James Wong dan Safawi Rasid', 'Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi', 'Punch Gunalan, Misbun Sidek dan Lee Chong Wei', 'Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek', 'C', 'Salah seorang beradik Sidek ada dalam senarai.', 'Atlet badminton contoh ialah Punch Gunalan, Misbun Sidek dan Lee Chong Wei.'),
(903, 9, 'Berapa kali Malaysia menjuarai Piala Thomas dalam badminton?', 'Lima kali', 'Tiga kali sahaja', 'Lapan kali', 'Sepuluh kali', 'A', 'Bilangannya kurang daripada enam.', 'Malaysia menjuarai Piala Thomas sebanyak lima kali.'),
(904, 9, 'Apakah pingat yang diraih badminton Malaysia di Sukan Olimpik?', 'Pingat emas sahaja', 'Pingat gangsa sahaja', 'Tiada sebarang pingat', 'Pingat perak dan gangsa', 'D', 'Tiada pingat emas dalam senarai.', 'Badminton Malaysia meraih pingat perak dan gangsa di Sukan Olimpik.'),
(905, 9, 'Kejohanan manakah yang dijuarai oleh atlet badminton Malaysia selain Piala Thomas?', 'Terbuka All England', 'Piala Suzuki AFF', 'Piala Monsun', 'Le Tour de Langkawi', 'A', 'Kejohanan terbuka yang tertua dalam badminton.', 'Atlet badminton Malaysia menjuarai Terbuka All England.'),
(906, 9, 'Yang manakah pernyataan yang betul tentang sukan badminton Malaysia?', 'FAM menguruskannya dan ia menjuarai Piala Thomas lima kali', 'BAM menguruskannya dan ia menjuarai Piala Thomas lima kali', 'BAM menguruskannya dan ia menjuarai Piala Suzuki AFF pada 2010', 'MHC menguruskannya dan ia layak ke Sukan Olimpik Munich 1972', 'B', 'Cari badan dan pencapaian yang sepadan.', 'Badminton diuruskan oleh BAM dan Malaysia menjuarai Piala Thomas lima kali.'),
(907, 9, 'Badan manakah yang menguruskan sukan bola sepak di Malaysia?', 'Persatuan Badminton Malaysia (BAM)', 'Konfederasi Hoki Malaysia (MHC)', 'Kesatuan Olahraga Malaysia (KOM)', 'Persatuan Bola Sepak Malaysia (FAM)', 'D', 'Singkatannya bermula dengan huruf F.', 'Persatuan Bola Sepak Malaysia (FAM) menguruskan bola sepak.'),
(908, 9, 'Siapakah antara atlet bola sepak contoh Malaysia?', 'Punch Gunalan, Misbun Sidek dan Lee Chong Wei', 'Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi', 'Soh Chin Ann, James Wong dan Safawi Rasid', 'Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek', 'C', 'Tiga nama pemain bola sepak.', 'Atlet bola sepak contoh ialah Soh Chin Ann, James Wong dan Safawi Rasid.'),
(909, 9, 'Bola sepak Malaysia layak ke Sukan Olimpik di bandar manakah pada tahun 1972?', 'Munich', 'Moscow', 'Tokyo', 'London', 'A', 'Bandar di negara Jerman.', 'Malaysia layak ke Sukan Olimpik Munich 1972.'),
(910, 9, 'Bola sepak Malaysia layak ke Sukan Olimpik di bandar manakah pada tahun 1980?', 'Munich', 'Tokyo', 'Moscow', 'Seoul', 'C', 'Bandar di negara Rusia.', 'Malaysia layak ke Sukan Olimpik Moscow 1980.'),
(911, 9, 'Pada tahun berapakah bola sepak Malaysia menjuarai Piala Suzuki AFF?', '2010', '1972', '1980', '2017', 'A', 'Tahun selepas tahun 2000.', 'Bola sepak Malaysia menjuarai Piala Suzuki AFF pada tahun 2010.'),
(912, 9, 'Yang manakah pencapaian utama bola sepak Malaysia?', 'Juara Piala Thomas lima kali dan juara Terbuka All England kemudian', 'Layak lapan kali ke Piala Dunia dan naib juara Sukan Komanwel pada 1998', 'Pingat emas 100m Sukan Asia pada 1966 dan 1982 serta juara Sukan SEA', 'Layak ke Olimpik Munich 1972 dan Moscow 1980, serta juara Piala Suzuki AFF 2010', 'D', 'Cari tiga pencapaian dalam bola sepak.', 'Bola sepak layak ke Olimpik Munich 1972 dan Moscow 1980 serta menjuarai Piala Suzuki AFF 2010.'),
(913, 9, 'Badan manakah yang menguruskan sukan olahraga di Malaysia?', 'Persatuan Badminton Malaysia (BAM)', 'Persatuan Bola Sepak Malaysia (FAM)', 'Kesatuan Olahraga Malaysia (KOM)', 'Konfederasi Hoki Malaysia (MHC)', 'C', 'Nama lamanya ialah KOAM.', 'Kesatuan Olahraga Malaysia (KOM), bekas KOAM, menguruskan olahraga.'),
(914, 9, 'Apakah nama lama bagi Kesatuan Olahraga Malaysia (KOM)?', 'KOAN', 'KOEM', 'KOMM', 'KOAM', 'D', 'Singkatan empat huruf.', 'Kesatuan Olahraga Malaysia (KOM) dahulunya dikenali sebagai KOAM.'),
(915, 9, 'Siapakah antara atlet olahraga contoh Malaysia?', 'Punch Gunalan, Misbun Sidek dan Lee Chong Wei', 'Soh Chin Ann, James Wong dan Safawi Rasid', 'Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi', 'Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek', 'D', 'Tiga nama pelari dan atlet trek.', 'Atlet olahraga contoh ialah Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek.'),
(916, 9, 'Pingat emas dalam acara 100m Sukan Asia diraih pada tahun berapa?', '1972 dan 1980', '1975 dan 1998', '1966 dan 1982', '2010 dan 2017', 'C', 'Dua tahun yang berbeza.', 'Olahraga Malaysia meraih pingat emas 100m Sukan Asia pada 1966 dan 1982.'),
(917, 9, 'Pada tahun berapakah olahraga Malaysia menjuarai Kejohanan Sukan SEA?', '1966', '1982', '2017', '2010', 'C', 'Tahun terkini dalam senarai pencapaian olahraga.', 'Olahraga Malaysia menjuarai Kejohanan Sukan SEA pada tahun 2017.'),
(918, 9, 'Yang manakah pencapaian utama olahraga Malaysia?', 'Pingat emas 100m Sukan Asia (1966 dan 1982) serta juara Sukan SEA 2017', 'Juara Piala Suzuki AFF pada 2010 dan layak ke Olimpik Munich 1972', 'Juara Piala Thomas lima kali dan juara Terbuka All England kemudian', 'Layak lapan kali ke Piala Dunia dan tempat ke-4 pada tahun 1975', 'A', 'Ingat acara 100m.', 'Olahraga meraih emas 100m Sukan Asia (1966 dan 1982) dan juara Kejohanan Sukan SEA 2017.'),
(919, 9, 'Badan manakah yang menguruskan sukan hoki di Malaysia?', 'Persatuan Badminton Malaysia (BAM)', 'Konfederasi Hoki Malaysia (MHC)', 'Persatuan Bola Sepak Malaysia (FAM)', 'Kesatuan Olahraga Malaysia (KOM)', 'B', 'Singkatannya bermula dengan huruf M.', 'Konfederasi Hoki Malaysia (MHC) menguruskan sukan hoki.'),
(920, 9, 'Siapakah antara atlet hoki contoh Malaysia?', 'Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi', 'Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek', 'Punch Gunalan, Misbun Sidek dan Lee Chong Wei', 'Soh Chin Ann, James Wong dan Safawi Rasid', 'A', 'Tiga nama pemain hoki.', 'Atlet hoki contoh ialah Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi.'),
(921, 9, 'Berapa kali hoki Malaysia layak ke Piala Dunia?', 'Dua kali', 'Lima kali', 'Lapan kali', 'Sepuluh kali', 'C', 'Bilangannya lebih daripada lima.', 'Hoki Malaysia layak ke Piala Dunia sebanyak lapan kali.'),
(922, 9, 'Hoki Malaysia mendapat tempat keberapa dalam Piala Dunia pada tahun 1975?', 'Tempat pertama', 'Tempat ke-8', 'Tempat ke-10', 'Tempat ke-4', 'D', 'Hampir ke pentas pingat.', 'Hoki Malaysia mendapat tempat ke-4 dalam Piala Dunia pada 1975.'),
(923, 9, 'Hoki Malaysia menjadi naib juara dalam sukan apa pada tahun 1998?', 'Sukan Asia', 'Sukan Komanwel', 'Sukan SEA', 'Sukan Olimpik', 'B', 'Sukan itu turut dianjurkan di Malaysia pada tahun yang sama.', 'Hoki Malaysia menjadi naib juara Sukan Komanwel 1998.'),
(924, 9, 'Yang manakah pencapaian utama hoki Malaysia?', 'Layak dua kali ke Piala Dunia dan juara Sukan Komanwel 1998', 'Juara Piala Thomas lima kali dan naib juara Komanwel 1998', 'Layak lapan kali ke Olimpik dan juara Piala Suzuki AFF 2010', 'Layak lapan kali ke Piala Dunia dan naib juara Sukan Komanwel 1998', 'D', 'Piala Dunia dan Sukan Komanwel.', 'Hoki layak lapan kali ke Piala Dunia (tempat ke-4 pada 1975) dan naib juara Sukan Komanwel 1998.'),
(925, 9, 'Berapakah bilangan nama dalam senarai atlet kebanggaan negara?', 'Sepuluh', 'Dua belas', 'Lapan', 'Lima belas', 'B', 'Lebih daripada sepuluh.', 'Terdapat dua belas nama dalam senarai atlet kebanggaan negara.'),
(926, 9, 'Yang manakah termasuk dalam senarai atlet kebanggaan negara?', 'Dato\' Peter Velappan', 'Mokhtar Dahari', 'Tan Aik Huang', 'Nurul Huda Abdullah', 'D', 'Cari nama atlet, bukan tokoh inspirasi.', 'Nurul Huda Abdullah ialah antara atlet kebanggaan negara.'),
(927, 9, 'Yang manakah BUKAN dalam senarai atlet kebanggaan negara?', 'Lee Chong Wei', 'Dato\' Sieh Kok Chi', 'Nicol Ann David', 'Mohd Azizulhasni Awang', 'B', 'Beliau tersenarai sebagai tokoh inspirasi.', 'Dato\' Sieh Kok Chi ialah tokoh inspirasi sukan negara, bukan dalam senarai atlet kebanggaan.'),
(928, 9, 'Yang manakah senarai atlet kebanggaan negara yang betul?', 'Lee Chong Wei, Nicol Ann David, S. Kuhan dan Pandelela Rinong anak Pamg', 'Lee Chong Wei, Nicol Ann David, S. Kuhan dan Dato\' Peter Velappan', 'Lee Chong Wei, Mokhtar Dahari, S. Kuhan dan Pandelela Rinong anak Pamg', 'Tan Aik Huang, Nicol Ann David, S. Kuhan dan Pandelela Rinong anak Pamg', 'A', 'Empat nama yang pertama dalam senarai.', 'Lee Chong Wei, Nicol Ann David, S. Kuhan dan Pandelela Rinong anak Pamg ialah empat nama pertama dalam senarai.'),
(929, 9, 'Apakah kepanjangan RIMUP?', 'Rancangan Integrasi Masyarakat untuk Perpaduan', 'Rancangan Integrasi Murid untuk Perpaduan', 'Rancangan Imbasan Murid untuk Pendidikan', 'Rancangan Integrasi Murid untuk Pertandingan', 'B', 'Ia merapatkan murid pelbagai kaum.', 'RIMUP bermaksud Rancangan Integrasi Murid untuk Perpaduan.'),
(930, 9, 'Apakah maksud 1M1S?', '1Malaysia 1Sukan', '1Murid 1Sukan', '1Murid 1Sekolah', '1Majlis 1Sukan', 'B', 'Setiap murid menyertai satu sukan.', '1M1S bermaksud 1Murid 1Sukan.'),
(931, 9, 'Apakah kepanjangan MSSM?', 'Majlis Sukan Sekolah Malaysia', 'Majlis Sukan Sekolah Melayu', 'Majlis Sukan Sosial Malaysia', 'Majlis Sukan Seluruh Malaysia', 'A', 'Ia berkait dengan sekolah.', 'Kejohanan MSSM ialah kejohanan Majlis Sukan Sekolah Malaysia.'),
(932, 9, 'Apakah kepanjangan SUKMA?', 'Sukan Mahasiswa', 'Sukan Malaysia', 'Sukan Sekolah Malaysia', 'Sukan Masyarakat', 'B', 'Temasya sukan peringkat negeri di Malaysia.', 'Temasya Sukan Malaysia (SUKMA) ialah program sukan perpaduan.'),
(933, 9, 'Apakah kepanjangan SUKIPT?', 'Sukan Institusi Pendidikan Tinggi', 'Sukan Institusi Pendidikan Tadika', 'Sukan Institusi Pelajar Tinggi', 'Sukan Institusi Pertahanan Tinggi', 'A', 'Ia melibatkan universiti dan kolej.', 'SUKIPT bermaksud Sukan Institusi Pendidikan Tinggi.'),
(934, 9, 'Sukan manakah yang turut menjadi program sukan perpaduan, selain SUKMA dan SUKIPT?', 'Sukan Paralimpik', 'Sukan Formula One', 'Piala Monsun', 'Le Tour de Langkawi', 'A', 'Ia memberi ruang kepada atlet berkeperluan khas.', 'Sukan Paralimpik ialah salah satu program sukan perpaduan.'),
(935, 9, 'Apakah peranan sukan dalam masyarakat Malaysia yang pelbagai kaum?', 'Alat pengasingan antara kaum', 'Alat untuk menaikkan harga barang', 'Alat perpaduan dan keharmonian kaum', 'Alat untuk mengurangkan pelancong', 'C', 'Semua kaum bermain bersama.', 'Sukan menjadi alat perpaduan dan keharmonian kaum.'),
(936, 9, 'Yang manakah senarai program sukan perpaduan yang betul?', 'RIMUP, 1M1S, MSSM, SUKMA, Piala Thomas dan Sukan Paralimpik', 'RIMUP, SUKMA, SUKIPT, Le Tour de Langkawi, MSSM dan 1M1S', '1M1S, MSSM, SUKMA, Piala Monsun, SUKIPT dan Sukan Paralimpik', 'RIMUP, 1M1S, MSSM, SUKMA, SUKIPT dan Sukan Paralimpik', 'D', 'Enam program sahaja.', 'Program sukan perpaduan ialah RIMUP, 1M1S, MSSM, SUKMA, SUKIPT dan Sukan Paralimpik.'),
(937, 9, 'Yang manakah tahun Malaysia menjadi tuan rumah Sukan SEA?', '1957, 1963, 1975, 1998 dan 2005', '1965, 1971, 1981, 1991 dan 2017', '1965, 1971, 1977, 2001 dan 2017', '1960, 1970, 1980, 1990 dan 2000', 'C', 'Lima tahun sahaja.', 'Malaysia menjadi tuan rumah Sukan SEA pada 1965, 1971, 1977, 2001 dan 2017.'),
(938, 9, 'Apakah faedah penganjuran Sukan SEA kepada rantau ini?', 'Memutuskan hubungan serantau', 'Menaikkan cukai pelancong', 'Menutup semua stadium', 'Merapatkan hubungan serantau', 'D', 'Negara-negara serantau bertemu.', 'Penganjuran Sukan SEA merapatkan hubungan serantau.'),
(939, 9, 'Berapa kali Piala Thomas berlangsung di Malaysia?', 'Dua kali', 'Lima kali', 'Enam kali', 'Sepuluh kali', 'C', 'Lebih banyak daripada kekerapan Piala Dunia hoki.', 'Piala Thomas berlangsung di Malaysia sebanyak enam kali.'),
(940, 9, 'Berapa edisi Hoki Piala Dunia yang Malaysia menjadi tuan rumah?', 'Satu edisi', 'Dua edisi', 'Enam edisi', 'Lapan edisi', 'B', 'Bilangannya paling sedikit selepas satu.', 'Malaysia menjadi tuan rumah Hoki Piala Dunia sebanyak dua edisi.'),
(941, 9, 'Sukan permotoran Formula One dan Formula E bermula di Malaysia pada tahun berapa?', '1965 dan 1971', '1996 dan 1998', '1991 dan 2000', '2005 dan 2017', 'C', 'Dua tahun yang berbeza.', 'Sukan permotoran (Formula One, Formula E) bermula di Malaysia pada 1991 dan 2000.'),
(942, 9, 'Sejak tahun berapakah Le Tour de Langkawi menjadi acara tahunan?', '1991', '2005', '2017', '1996', 'D', 'Acara berbasikal.', 'Le Tour de Langkawi ialah acara tahunan sejak 1996.'),
(943, 9, 'Sukan Komanwel 1998 di Malaysia mencipta sejarah sebagai apa?', 'Negara Asia pertama menjadi tuan rumah', 'Negara Afrika pertama menjadi tuan rumah', 'Penganjuran Sukan Komanwel yang terakhir', 'Penganjuran tanpa penonton asing', 'A', 'Ia berkait dengan benua Asia.', 'Malaysia ialah negara Asia pertama menjadi tuan rumah Sukan Komanwel (1998).'),
(944, 9, 'Piala Monsun ialah kejohanan sukan apa?', 'Berbasikal', 'Hoki', 'Badminton', 'Perahu layar', 'D', 'Sukan di atas air.', 'Piala Monsun ialah kejohanan perahu layar sejak 2005.'),
(945, 9, 'Sejak tahun berapakah Piala Monsun berlangsung?', '2005', '1991', '1996', '2017', 'A', 'Tahun selepas Sukan SEA 2001.', 'Piala Monsun berlangsung sejak 2005.'),
(946, 9, 'Yang manakah padanan sukan antarabangsa dan penganjuran di Malaysia yang betul?', 'Piala Monsun dengan acara tahunan sejak 1998', 'Le Tour de Langkawi dengan acara tahunan sejak 1996', 'Sukan Komanwel dengan tuan rumah pada 2005', 'Hoki Piala Dunia dengan tuan rumah enam edisi', 'B', 'Cari tahun dan acara yang sepadan.', 'Le Tour de Langkawi ialah acara tahunan sejak 1996.'),
(947, 9, 'Yang manakah tokoh inspirasi sukan negara?', 'Lee Chong Wei', 'Nicol Ann David', 'Dato\' Peter Velappan', 'Pandelela Rinong anak Pamg', 'C', 'Beliau tersenarai sebagai tokoh, bukan atlet kebanggaan.', 'Dato\' Peter Velappan ialah salah seorang tokoh inspirasi sukan negara.'),
(948, 9, 'Yang manakah senarai tokoh inspirasi sukan negara yang betul?', 'Dato\' Sieh Kok Chi, M. Rajamani, Tan Aik Huang dan Mokhtar Dahari', 'Dato\' Sieh Kok Chi, M. Rajamani, Tan Aik Huang dan Lee Chong Wei', 'Dato\' Sieh Kok Chi, S. Kuhan, Tan Aik Huang dan Mokhtar Dahari', 'Nicol Ann David, M. Rajamani, Tan Aik Huang dan Mokhtar Dahari', 'A', 'Tiga atlet kebanggaan tidak termasuk di sini.', 'Dato\' Sieh Kok Chi, M. Rajamani, Tan Aik Huang dan Mokhtar Dahari ialah tokoh inspirasi sukan negara.'),
(949, 9, 'Tokoh manakah ialah Sultan yang disenaraikan sebagai tokoh inspirasi sukan negara?', 'Sultan Mizan Zainal Abidin', 'Sultan Azlan Muhibbuddin Shah', 'Sultan Ibrahim Iskandar', 'Sultan Sallehuddin Badlishah', 'B', 'Nama baginda mengandungi perkataan Muhibbuddin.', 'Sultan Azlan Muhibbuddin Shah ialah salah seorang tokoh inspirasi sukan negara.'),
(950, 9, 'Tokoh manakah yang turut disenaraikan sebagai atlet olahraga contoh dan tokoh inspirasi?', 'Dato\' Sieh Kok Chi', 'Dr. M. Jegathesan', 'Mokhtar Dahari', 'Tan Aik Huang', 'B', 'Beliau juga meraih pingat emas 100m Sukan Asia.', 'Dr. M. Jegathesan disenaraikan sebagai atlet olahraga contoh dan tokoh inspirasi sukan negara.'),
(1001, 10, 'Apakah kepanjangan SEAFET?', 'Southeast Asia Federation and Economic Treaty', 'Southeast Asian Friendship and Education Treaty', 'Southeast Asia Friendship and Economic Treaty', 'South Eastern Alliance for Economic Trade', 'C', 'Nama itu mengandungi perkataan persahabatan dan ekonomi.', 'SEAFET ialah Southeast Asia Friendship and Economic Treaty, pertubuhan serantau yang disertai Tanah Melayu, Thailand dan Filipina.'),
(1002, 10, 'Negara manakah anggota SEAFET dan ASA?', 'Tanah Melayu, Indonesia dan Singapura', 'Thailand, Filipina dan Singapura', 'Indonesia, Thailand dan Singapura', 'Tanah Melayu, Thailand dan Filipina', 'D', 'Tiga negara itu sama bagi kedua-dua pertubuhan.', 'SEAFET dan ASA masing-masing dianggotai oleh Tanah Melayu, Thailand dan Filipina.');
INSERT INTO `Question` (`questionID`, `bankID`, `questionText`, `option_a`, `option_b`, `option_c`, `option_d`, `correctAnswer`, `hint`, `explanation`) VALUES
(1003, 10, 'Apakah kepanjangan ASA?', 'Alliance of Southeast Asian States', 'Association of South Asian Allies', 'Association of Southeast Asia', 'Assembly of Southeast Asian Authorities', 'C', 'Huruf pertamanya ialah Association.', 'ASA ialah Association of Southeast Asia, pertubuhan serantau yang disertai Tanah Melayu, Thailand dan Filipina.'),
(1004, 10, 'Negara manakah termasuk dalam keahlian ASEAN yang awal selain Malaysia?', 'Vietnam, Kemboja, Laos dan Myanmar', 'Jepun, China, Korea dan India', 'Indonesia, Thailand, Filipina dan Singapura', 'Indonesia, Australia, Jepun dan Singapura', 'C', 'Empat negara itu bersama Malaysia dalam senarai pertubuhan ini.', 'ASEAN dianggotai oleh Malaysia, Indonesia, Thailand, Filipina dan Singapura.'),
(1005, 10, 'Apakah kepanjangan ASEAN?', 'Alliance of Southeast Asian National States', 'Association of Southeast Asia Navies', 'Assembly of Southeast Asian Neighbours', 'Association of Southeast Asian Nations', 'D', 'Perkataan terakhirnya ialah Nations.', 'ASEAN ialah Association of Southeast Asian Nations.'),
(1006, 10, 'Antara berikut, yang manakah pertubuhan serantau?', 'PBB', 'Komanwel', 'NAM', 'ASEAN', 'D', 'Serantau bermaksud satu rantau, iaitu Asia Tenggara.', 'ASEAN ialah pertubuhan serantau, manakala PBB, Komanwel dan NAM ialah pertubuhan antarabangsa.'),
(1007, 10, 'Siapakah yang layak menjadi ahli Komanwel?', 'Negara bekas tanah jajahan British', 'Semua negara di Asia Tenggara', 'Hanya negara Islam', 'Hanya negara membangun di Afrika', 'A', 'Sejarah pentadbiran British menjadi asas keahlian.', 'Keahlian Komanwel terdiri daripada negara bekas tanah jajahan British.'),
(1008, 10, 'Apakah kepanjangan PBB?', 'Pertubuhan Bangsa-Bangsa Bersatu', 'Pergerakan Bangsa-Bangsa Berkecuali', 'Perhimpunan Bangsa-Bangsa Besar', 'Pertubuhan Belia Bersatu Bangsa', 'A', 'Ia ialah pertubuhan yang bersatu untuk semua bangsa.', 'PBB ialah Pertubuhan Bangsa-Bangsa Bersatu, yang keahliannya terbuka kepada semua negara.'),
(1009, 10, 'Berapakah bilangan negara Islam dalam OIC?', '120 buah negara', '57 buah negara', '54 buah negara', '10 buah negara', 'B', 'Bilangan itu lebih daripada lima puluh dan kurang daripada enam puluh.', 'OIC, iaitu Pertubuhan Kerjasama Islam, terdiri daripada 57 buah negara Islam.'),
(1010, 10, 'Apakah kepanjangan NAM?', 'Pertubuhan Negara-negara Asia Muda', 'Persatuan Negara-negara Antarabangsa Malaysia', 'Pergerakan Negara-negara Asia Merdeka', 'Pergerakan Negara-negara Berkecuali', 'D', 'Ia berkaitan dengan sikap tidak memihak kepada mana-mana blok.', 'NAM ialah Pergerakan Negara-negara Berkecuali.'),
(1011, 10, 'Berapakah bilangan negara membangun dalam NAM?', '57 buah negara', '120 buah negara', '54 buah negara', '10 buah negara', 'B', 'Negaranya terdiri daripada Asia, Afrika dan Amerika Selatan.', 'NAM dianggotai 120 buah negara membangun di Asia, Afrika dan Amerika Selatan.'),
(1012, 10, 'Pertubuhan manakah yang keahliannya terbuka kepada semua negara?', 'PBB', 'Komanwel', 'OIC', 'ASEAN', 'A', 'Pertubuhan ini bertapak di New York.', 'Keahlian PBB terbuka kepada semua negara.'),
(1013, 10, 'Bilakah ASEAN ditubuhkan?', '11 Disember 1931', '8 Ogos 1967', '25 September 1969', '24 Oktober 1945', 'B', 'Tarikh itu pada bulan Ogos.', 'ASEAN ditubuhkan pada 8 Ogos 1967.'),
(1014, 10, 'Berapakah bilangan negara anggota ASEAN kini?', '10 negara Asia Tenggara', '5 negara Asia Tenggara', '57 negara Islam', '54 negara bekas jajahan', 'A', 'Bilangannya tepat sepuluh.', 'ASEAN dianggotai 10 negara Asia Tenggara.'),
(1015, 10, 'Di manakah ibu pejabat ASEAN?', 'Kuala Lumpur, Malaysia', 'Jakarta, Indonesia', 'Bangkok, Thailand', 'New York, Amerika Syarikat', 'B', 'Ia terletak di sebuah negara Asia Tenggara yang besar.', 'Ibu pejabat ASEAN terletak di Jakarta, Indonesia.'),
(1016, 10, 'Antara berikut, yang manakah matlamat ASEAN?', 'Menjadikan semua anggota negara Islam', 'Menyatukan semua negara bekas jajahan', 'Memelihara keamanan dan kestabilan politik', 'Menamatkan dasar Aparteid sahaja', 'C', 'Matlamat itu berkaitan politik serantau.', 'Matlamat ASEAN termasuk keamanan dan kestabilan politik, pertumbuhan ekonomi, sosial dan budaya.'),
(1017, 10, 'Apakah satu matlamat ASEAN selain keamanan dan kestabilan politik?', 'Mengisytiharkan deklarasi alam sekitar', 'Meningkatkan taraf hidup rakyat', 'Menubuhkan sebuah bank Islam', 'Menghantar angkasawan ke angkasa', 'B', 'Ia berkaitan dengan kehidupan rakyat.', 'ASEAN juga bermatlamat meningkatkan taraf hidup rakyat serta menggalakkan latihan dan penyelidikan.'),
(1018, 10, 'Apakah sumbangan Malaysia kepada ASEAN berkaitan Vietnam?', 'Membantu Vietnam menjadi anggota Komanwel', 'Menubuhkan Bank Pembangunan Islam di Vietnam', 'Membantu isu pencerobohan Vietnam di Kemboja', 'Menghantar pasukan pengaman ke Vietnam', 'C', 'Isu itu berlaku di sebuah negara jiran Vietnam.', 'Malaysia membantu menangani isu pencerobohan Vietnam di Kemboja.'),
(1019, 10, 'Konflik manakah yang diredakan Malaysia dalam ASEAN?', 'Konflik di Utara Thailand', 'Konflik di Selatan Filipina', 'Konflik di Timur Indonesia', 'Konflik di Barat Singapura', 'B', 'Ia berlaku di sebuah negara yang bersempadan laut dengan Sabah.', 'Malaysia membantu meredakan konflik di Selatan Filipina.'),
(1020, 10, 'Apakah kepanjangan ZOPFAN yang diutarakan oleh Malaysia?', 'Zon Anggota Politik Federasi ASEAN', 'Zon Aman, Bebas dan Berkecuali', 'Zon Ahli Pertubuhan Antarabangsa', 'Zon Aman Perdagangan Bebas ASEAN', 'B', 'Namanya mengandungi tiga ciri: aman, bebas dan berkecuali.', 'Malaysia mengutarakan penubuhan ZOPFAN, iaitu Zon Aman, Bebas dan Berkecuali.'),
(1021, 10, 'Organisasi pendidikan manakah yang Malaysia sertai dalam ASEAN?', 'UNESCO', 'SEAFET', 'NAM', 'SEAMEO', 'D', 'Namanya berkaitan dengan menteri pendidikan Asia Tenggara.', 'Malaysia menyertai SEAMEO sebagai sumbangan di peringkat serantau.'),
(1022, 10, 'Apakah peranan Malaysia dalam Mesyuarat Menteri Luar ASEAN?', 'Menjadi pengerusi tetap', 'Menjadi pemerhati', 'Menjadi penaja kewangan tunggal', 'Menjadi tuan rumah', 'D', 'Mesyuarat itu diadakan di Malaysia.', 'Malaysia menjadi tuan rumah Mesyuarat Menteri Luar ASEAN.'),
(1023, 10, 'Bilakah Komanwel dibentuk?', '8 Ogos 1967', '25 September 1969', '11 Disember 1931', '24 Oktober 1945', 'C', 'Ia dibentuk pada tahun 1931.', 'Komanwel dibentuk pada 11 Disember 1931.'),
(1024, 10, 'Berapakah bilangan negara anggota Komanwel?', '57 negara', '54 negara', '120 negara', '10 negara', 'B', 'Bilangannya lebih daripada lima puluh dan kurang daripada lima puluh lima.', 'Komanwel dianggotai 54 negara bekas jajahan British.'),
(1025, 10, 'Di manakah ibu pejabat Komanwel?', 'London, England', 'New York, Amerika Syarikat', 'Jeddah, Arab Saudi', 'Jakarta, Indonesia', 'A', 'Ia terletak di bekas pusat pentadbiran penjajah.', 'Ibu pejabat Komanwel terletak di London, England.'),
(1026, 10, 'Apakah dasar yang dikecam Malaysia dalam Komanwel?', 'Dasar Pandang ke Timur', 'Dasar Ekonomi Baru', 'Dasar Aparteid', 'Dasar Pengimportan Bebas', 'C', 'Dasar itu berkaitan dengan diskriminasi kaum di Afrika Selatan.', 'Malaysia mengecam dan membantu menamatkan dasar Aparteid melalui Komanwel.'),
(1027, 10, 'Pada tahun berapakah Malaysia menjadi tuan rumah CHOGM?', '1931', '1974', '2003', '1989', 'D', 'Tahun itu juga tahun Deklarasi Langkawi.', 'Malaysia menjadi tuan rumah CHOGM pada tahun 1989.'),
(1028, 10, 'Apakah isu yang ditekankan dalam Deklarasi Langkawi 1989?', 'Pendidikan tinggi', 'Alam sekitar', 'Keamanan Palestin', 'Perdagangan bebas serantau', 'B', 'Isu itu berkaitan dengan hutan, laut dan udara.', 'Deklarasi Langkawi 1989 diisytiharkan Malaysia untuk alam sekitar.'),
(1029, 10, 'Bilakah OIC ditubuhkan?', '11 Disember 1931', '25 September 1969', '24 Oktober 1945', '8 Ogos 1967', 'B', 'Ia ditubuhkan pada bulan September.', 'OIC ditubuhkan pada 25 September 1969.'),
(1030, 10, 'Di manakah ibu pejabat OIC?', 'London, England', 'New York, Amerika Syarikat', 'Jakarta, Indonesia', 'Jeddah, Arab Saudi', 'D', 'Bandar itu terletak di Tanah Arab.', 'Ibu pejabat OIC terletak di Jeddah, Arab Saudi.'),
(1031, 10, 'Siapakah Setiausaha Agung OIC yang pertama?', 'Tunku Abdul Rahman', 'Tun Abdul Razak', 'Tun Dr. Mahathir', 'Tun Hussein Onn', 'A', 'Beliau juga Perdana Menteri pertama Malaysia.', 'Tunku Abdul Rahman dilantik sebagai Setiausaha Agung OIC pertama.'),
(1032, 10, 'Apakah institusi kewangan yang Malaysia bantu tubuhkan dalam OIC?', 'Bank Dunia', 'Tabung Kewangan Antarabangsa', 'Bank Pembangunan Asia', 'Bank Pembangunan Islam', 'D', 'Namanya mengandungi perkataan Islam.', 'Malaysia menyumbang kepada penubuhan Bank Pembangunan Islam.'),
(1033, 10, 'Isu manakah yang ditangani Malaysia dalam OIC pada tahun 1991?', 'Isu pencerobohan di Kemboja', 'Isu konflik Selatan Filipina', 'Isu dasar Aparteid Afrika', 'Isu Bosnia dan Herzegovina', 'D', 'Negara itu terletak di Eropah.', 'Malaysia menangani isu Bosnia dan Herzegovina pada tahun 1991.'),
(1034, 10, 'Apakah universiti yang ditubuhkan pada tahun 1983 sebagai sumbangan Malaysia dalam OIC?', 'UiTM', 'UPSI', 'UIAM', 'UTHM', 'C', 'Namanya mengandungi perkataan Islam dan antarabangsa.', 'Universiti Islam Antarabangsa Malaysia (UIAM) ditubuhkan pada tahun 1983.'),
(1035, 10, 'Pada tahun berapakah Malaysia menjadi tuan rumah Persidangan OIC?', '1974 dan 2003', '1931 dan 1945', '1967 dan 1989', '1983 dan 1991', 'A', 'Dua tahun itu mengikut tahun 1970-an dan 2000-an.', 'Malaysia menjadi tuan rumah Persidangan OIC pada tahun 1974 dan 2003.'),
(1036, 10, 'Bilakah PBB ditubuhkan?', '11 Disember 1931', '25 September 1969', '24 Oktober 1945', '8 Ogos 1967', 'C', 'Ia ditubuhkan pada bulan Oktober.', 'PBB ditubuhkan pada 24 Oktober 1945.'),
(1037, 10, 'Di manakah ibu pejabat PBB?', 'New York, Amerika Syarikat', 'London, England', 'Jeddah, Arab Saudi', 'Washington, Amerika Syarikat', 'A', 'Ia terletak di sebuah bandar di Amerika.', 'Ibu pejabat PBB terletak di New York, Amerika Syarikat.'),
(1038, 10, 'Isu rakyat manakah yang dibawa Malaysia ke PBB?', 'Isu rakyat Aparteid', 'Isu rakyat Kemboja', 'Isu rakyat Bosnia sahaja', 'Isu rakyat Palestin', 'D', 'Isu itu juga disokong dalam OIC.', 'Malaysia membawa isu rakyat Palestin ke PBB.'),
(1039, 10, 'Apakah usaha yang didesak Malaysia di PBB?', 'Menaikkan harga minyak', 'Memperluas penjajahan', 'Memerangi dadah', 'Mengehadkan kegiatan sukan', 'C', 'Ia berkaitan dengan masalah sosial yang memudaratkan.', 'Malaysia mendesak usaha memerangi dadah di PBB.'),
(1040, 10, 'Apakah sumbangan Malaysia kepada PBB dalam bidang keamanan?', 'Menyertai pasukan pengaman', 'Menghantar angkasawan', 'Menubuhkan bank dunia', 'Menjadi tuan rumah Olimpik', 'A', 'Anggota pasukan itu memakai topi biru.', 'Malaysia menyertai pasukan pengaman PBB.'),
(1041, 10, 'Bagaimana pasukan pengaman Malaysia diiktiraf oleh PBB?', 'Melalui pemberian sijil dan pingat perkhidmatan PBB', 'Melalui pemberian wang tunai kepada setiap anggota', 'Melalui pemberian tanah di bandar New York', 'Melalui pemberian kerusi tetap di Majlis Keselamatan', 'A', 'Pengiktirafan itu ialah bukti perkhidmatan.', 'Pasukan pengaman Malaysia diiktiraf melalui sijil dan pingat perkhidmatan PBB.'),
(1042, 10, 'Siapakah Pengerusi Majlis Keselamatan PBB pada 1989 hingga 1990?', 'Datuk Dr. Mazlan Othman', 'Tan Sri Razali Ismail', 'Tunku Abdul Rahman', 'Tun Abdul Razak', 'B', 'Beliau kemudian mengerusikan sesi ke-51 Perhimpunan Agung PBB.', 'Tan Sri Razali Ismail ialah Pengerusi Majlis Keselamatan PBB (1989-1990) dan Pengerusi Perhimpunan Agung PBB sesi ke-51 (1996-1997).'),
(1043, 10, 'Siapakah Pengarah Hal Ehwal Angkasa Lepas PBB?', 'Tan Sri Razali Ismail', 'Tunku Abdul Rahman', 'Datuk Dr. Mazlan Othman', 'Tun Dr. Mahathir', 'C', 'Beliau ialah seorang wanita Malaysia.', 'Datuk Dr. Mazlan Othman ialah Pengarah Hal Ehwal Angkasa Lepas PBB pada 1999-2002 dan 2007.'),
(1044, 10, 'Pada tahun berapakah Taman Negara Gunung Mulu dan Taman Kinabalu menjadi Tapak Warisan Dunia UNESCO?', '2000', '2008', '2012', '1989', 'A', 'Tahun itu ialah tahun alam semula jadi.', 'Taman Negara Gunung Mulu (Sarawak) dan Taman Kinabalu (Sabah) menjadi Tapak Warisan Dunia alam semula jadi pada 2000.'),
(1045, 10, 'Taman Kinabalu terletak di negeri mana?', 'Sarawak', 'Sabah', 'Pahang', 'Perak', 'B', 'Gunung tertinggi Malaysia terletak di negeri itu.', 'Taman Kinabalu terletak di Sabah.'),
(1046, 10, 'Apakah dua tapak warisan kebudayaan UNESCO pada tahun 2008?', 'Taman Negara dan Kinabalu', 'Lenggong dan Mulu', 'Kuching dan Kota Kinabalu', 'Melaka dan George Town', 'D', 'Kedua-duanya ialah bandar bersejarah Selat Melaka.', 'Melaka dan George Town menjadi Tapak Warisan Dunia kebudayaan pada 2008.'),
(1047, 10, 'Apakah tapak warisan UNESCO yang diiktiraf pada tahun 2012?', 'Warisan Arkeologi Lembah Lenggong', 'Taman Negara Gunung Mulu di Sarawak', 'Melaka dan George Town di Selat Melaka', 'Taman Kinabalu di negeri Sabah', 'A', 'Tapak itu berkaitan dengan penemuan arkeologi di Perak.', 'Warisan Arkeologi Lembah Lenggong diiktiraf pada 2012.'),
(1048, 10, 'Manakah antara berikut dalam Daftar Memori Dunia pada tahun 2001?', 'Sulalatus Salatin', 'Batu Bersurat Terengganu', 'Hikayat Hang Tuah', 'Warisan Lembah Lenggong', 'C', 'Ia ialah kisah laksamana Melayu.', 'Hikayat Hang Tuah (2001) dan Surat-menyurat Almarhum Sultan Kedah 1882-1943 (2001) dalam Daftar Memori Dunia.'),
(1049, 10, 'Pada tahun berapakah Batu Bersurat Terengganu masuk Daftar Memori Dunia?', '2009', '2001', '2002', '2018', 'A', 'Tahun itu sebelum tahun 2010.', 'Batu Bersurat Terengganu masuk Daftar Memori Dunia pada 2009.'),
(1050, 10, 'Manakah warisan budaya tidak ketara yang diiktiraf pada tahun 2019?', 'Makyung', 'Silat', 'Dondang Sayang', 'Wangkang', 'B', 'Ia ialah seni mempertahankan diri.', 'Silat diiktiraf pada 2019, Makyung pada 2005, Dondang Sayang pada 2018 dan Wangkang pada 2020.');
