INSERT INTO `Scene` (`sceneID`, `sceneStoryline`, `sceneOrder`, `narrativeID`, `asset`) VALUES
('e10_n1_s1', 'Bilik sidang serantau berkaca besar dengan bendera negara Asia Tenggara berbaris dan meja peta dunia bercahaya di tengah. Kau, wakil muda ASEAN, menyusun fail sementara pakar ekonomi dan wakil Indonesia menyambutmu.', 1, 1001, 'malaysia_dan_dunia_serantau.png'),
('e10_n1_s2', 'Bilik mesyuarat dunia dengan meja bulat besar dan peta dunia bercahaya di dinding. Kau, wakil muda ASEAN, duduk di meja sementara utusan Komanwel, wakil PBB, wakil OIC dan duta NAM masuk satu persatu.', 2, 1001, 'bilik_mesyuarat_dunia.png'),
('e10_n1_s3', 'Bilik mesyuarat panjang dengan bendera meja negara anggota ASEAN dan peta Asia Tenggara di dinding. Kau, wakil muda ASEAN, menyemak dokumen sementara pakar ekonomi menerangkan sumbangan Malaysia.', 3, 1001, 'bilik_mesyuarat.png'),
('e10_n1_s4', 'Bilik mesyuarat London yang megah dengan jambatan Thames di tingkap dan peta serantau di meja panjang. Kau, wakil muda ASEAN, duduk bersama utusan Komanwel, wakil OIC dan Tunku Abdul Rahman.', 4, 1001, 'bilik_mesyuarat_london.png'),
('e10_n1_s5', 'Dewan sidang besar PBB dengan bendera Malaysia di pentas dan skrin kawalan menunjukkan peta dunia. Kau, wakil muda ASEAN, berdiri di tengah bersama wakil PBB dan penjaga keamanan PBB.', 5, 1001, 'malaysia_di_pentas_dunia.png'),
('e10_n1_s6', 'Ruang pameran UNESCO dengan kotak kaca silinder memaparkan gunung, gua dan peta warisan. Kau, wakil muda ASEAN, melangkah masuk sementara pemandu pameran menyambutmu dengan lampu pameran yang bersinar.', 6, 1001, 'ruang_unesco.png'),
('e10_n2_s1', 'Bilik mesyuarat moden dengan peta Asia Tenggara di dinding dan meja berkilat. Kau, penjaga keamanan PBB, berdiri di muka pintu sementara pakar ekonomi dan wakil Indonesia bersiap untuk sidang serantau.', 1, 1002, 'bilik_mesyuarat_modern.png'),
('e10_n2_s2', 'Bilik mesyuarat dunia dengan meja bulat dan peta dunia bercahaya. Kau, penjaga keamanan PBB, meronda di sekeliling meja sementara utusan Komanwel, wakil PBB, wakil OIC dan duta NAM menunggu giliran.', 2, 1002, 'bilik_mesyuarat_dunia.png'),
('e10_n2_s3', 'Bilik mesyuarat panjang dengan bendera meja negara ASEAN dan peta Asia Tenggara di dinding. Kau, penjaga keamanan PBB, memeriksa bilik sementara pakar ekonomi menerangkan ASEAN.', 3, 1002, 'bilik_mesyuarat.png'),
('e10_n2_s4', 'Bilik mesyuarat formal berhias ukiran Islam dengan meja panjang dan dokumen bertulis tangan. Kau, penjaga keamanan PBB, mengiringi utusan Komanwel dan wakil OIC masuk ke bilik itu.', 4, 1002, 'bilik_mesyuarat_formal.png'),
('e10_n2_s5', 'Pusat operasi PBB yang sibuk dengan kotak bantuan bertanda PBB, mesin telex dan anggota topi biru. Kau, penjaga keamanan PBB, menyemak laporan sementara wakil PBB menerangkan sumbangan Malaysia.', 5, 1002, 'bilik_UNMM.png'),
('e10_n2_s6', 'Ruang pameran UNESCO dengan kotak kaca silinder memaparkan gunung, gua dan peta warisan. Kau, penjaga keamanan PBB, mengiringi pemandu pameran menyusuri kotak kaca itu pada akhir rondaan.', 6, 1002, 'ruang_unesco.png'),
('e10_n3_s1', 'Bilik pameran serantau dengan bendera negara Asia Tenggara dan meja peta dunia bercahaya di tengah. Kau, pemandu pameran, membuka lawatan bersama pakar ekonomi dan wakil Indonesia.', 1, 1003, 'malaysia_dan_dunia_serantau.png'),
('e10_n3_s2', 'Bilik mesyuarat dunia dengan meja bulat dan peta dunia bercahaya di dinding. Kau, pemandu pameran, membawa pelawat bertemu utusan Komanwel, wakil PBB, wakil OIC dan duta NAM.', 2, 1003, 'bilik_mesyuarat_dunia.png'),
('e10_n3_s3', 'Bilik mesyuarat moden dengan peta Asia Tenggara di dinding dan meja panjang berkilat. Kau, pemandu pameran, membawa pelawat mengenali ASEAN bersama pakar ekonomi.', 3, 1003, 'bilik_mesyuarat_modern.png'),
('e10_n3_s4', 'Bilik mesyuarat London yang megah dengan peta serantau di meja panjang. Kau, pemandu pameran, membawa pelawat bertemu utusan Komanwel, wakil OIC dan Tunku Abdul Rahman.', 4, 1003, 'bilik_mesyuarat_london.png'),
('e10_n3_s5', 'Dewan sidang besar PBB dengan bendera Malaysia di pentas dan skrin kawalan menunjukkan peta dunia. Kau, pemandu pameran, membawa pelawat berdiri di tengah bersama wakil PBB dan penjaga keamanan PBB.', 5, 1003, 'malaysia_di_pentas_dunia.png'),
('e10_n3_s6', 'Ruang pameran UNESCO dengan kotak kaca silinder memaparkan gunung, gua dan peta warisan. Kau, pemandu pameran, membawa pelawat ke bilik terakhir bersama ahli antropologi UNESCO.', 6, 1003, 'ruang_unesco.png'),
('e1_n1_s1', '27 Mei 1961, Hotel Adelphi, Singapura. Kau, Tunku Abdul Rahman, berdiri di hadapan wartawan tempatan dan asing dengan satu cadangan yang akan mengubah peta Asia Tenggara.', 1, 1, 'grand_hotel_ballroom.png'),
('e1_n1_s2', '1961–1962, Kuching dan Kota Kinabalu. Kau menghantar wakil untuk mendengar rakyat Borneo. Kau tidak mahu keputusan sebesar ini dibuat tanpa suara mereka.', 2, 1, 'lawatan_ke_sarawak.png'),
('e1_n1_s3', '30 Ogos 1962, Kuala Lumpur. Jawatankuasa Antara Kerajaan bersidang. Kau perlu memastikan hak Sabah dan Sarawak ditulis dalam Perlembagaan, bukan hanya dijanjikan dengan lisan.', 3, 1, 'bilik_mesyuarat_formal.png'),
('e1_n1_s4', '1962–1963, Kuala Lumpur. Tiga ancaman tiba serentak di mejamu: SUPP, Konfrontasi dan Filipina. Kau mesti menemui buktinya sebelum memutuskan langkah.', 4, 1, 'bilik_strategi_keselamatan.png'),
('e1_n1_s5', '9 Julai hingga 14 September 1963, London. Kau menandatangani Perjanjian Malaysia, tetapi Indonesia dan Filipina belum puas hati. PBB akan bertanya kepada rakyat Borneo sendiri.', 5, 1, 'bilik_mesyuarat_london.png'),
('e1_n1_s6', '16 September 1963, Stadium Merdeka, Kuala Lumpur. Kau berdiri untuk membaca Pemasyhuran Malaysia yang akan diisytiharkan serentak di empat bandar.', 6, 1, 'laungan_di_stadium_merdeka.png'),
('e1_n2_s1', '1961, Jesselton (Kota Kinabalu). Kau, Donald Stephens, berdiri di balai perhimpunan. Tunku sudah membuat pengumuman di Adelphi dan kini rakyat menunggu kau menjawab.', 1, 2, 'petempatan_pedalaman_sabah.png'),
('e1_n2_s2', '1961–1962, rumah panjang di Sarawak dan pejabat daerah di Sabah. Kau mengetuai JSKM supaya rakyat memahami Malaysia, dan Suruhanjaya Cobbold datang mendengar mereka.', 2, 2, 'bilik_jskm.png'),
('e1_n2_s3', '30 Ogos 1962, Kuching dan Kota Kinabalu. Kau dalam sesi perundingan JAK. Hak Sabah dan Sarawak mesti ditulis dalam Perlembagaan, bukan hanya diingat.', 3, 2, 'bangunan_perlembagaan.png'),
('e1_n2_s4', '1962–1963, sempadan Sabah dan Sarawak. Kau berdepan bantahan SUPP, tentera Konfrontasi dan tuntutan Filipina. Kau mesti menemui buktinya untuk menenangkan rakyat.', 4, 2, 'bilik_strategi_keselamatan.png'),
('e1_n2_s5', 'Julai hingga September 1963, Kuching dan Kota Kinabalu. Perjanjian Malaysia sudah ditandatangani, dan pegawai PBB datang bertanya kepada rakyat Borneo sendiri.', 5, 2, 'bilik_UNMM.png'),
('e1_n2_s6', '16 September 1963, Padang Merdeka, Kota Kinabalu dan Kuching. Kau membacakan Pemasyhuran Malaysia di hadapan rakyat Sabah. Pada hari yang sama pemimpin Sarawak melakukannya di Kuching.', 6, 2, 'laungan_di_stadium_merdeka.png'),
('e1_n3_s1', '27 Mei 1961, Kuala Lumpur. Kau, Tun Ghazali Shafie, membaca keadaan keselamatan Asia Tenggara selepas pengumuman Tunku. Komunis tidak menunggu sesiapa.', 1, 3, 'bilik_strategi_keselamatan.png'),
('e1_n3_s2', '1961–1962, Kuala Lumpur. Kau dan Wong Pow Nee dalam Suruhanjaya Cobbold turun mendengar rakyat Borneo. Keraguan mereka akan dibawa ke JAK.', 2, 3, 'bilik_suruhanjaya_cobbold.png'),
('e1_n3_s3', '30 Ogos 1962, Kuala Lumpur. Kau, Tun Ghazali Shafie, membantu Jawatankuasa Antara Kerajaan menulis jaminan hak Sabah dan Sarawak ke dalam Perlembagaan.', 3, 3, 'bangunan_perlembagaan.png'),
('e1_n3_s4', '1962–1963, Kuala Lumpur. SUPP, Konfrontasi dan Filipina menekan serentak. Kau perlu mengenal pasti bukti ancaman keselamatan sebelum menasihati Tunku.', 4, 3, 'perancangan_pembentukan_malaysia.png'),
('e1_n3_s5', '9 Julai hingga 14 September 1963, London dan Borneo. Perjanjian Malaysia sudah ditandatangani. Kau menasihati Tunku bagaimana melayan misi siasatan PBB.', 5, 3, 'bilik_UNMM.png'),
('e1_n3_s6', '16 September 1963, Kuala Lumpur. Kau memastikan Pemasyhuran Malaysia berjalan serentak di empat bandar, tanpa gangguan keselamatan.', 6, 3, 'laungan_di_stadium_merdeka.png'),
('e2_n1_s1', 'Pagi di tepi sawah. Angin sawah menghembus padi yang menguning. Kau, Tok Penglipur Lara, melangkah masuk ke Perlis sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 1, 201, 'negeri_perlis.png'),
('e2_n1_s10', 'Senja di tepi pantai. Ombak berbuih memukul pantai dan layang-layang camar berputar. Kau, Tok Penglipur Lara, melangkah masuk ke Terengganu sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 10, 201, 'negeri_terengganu.png'),
('e2_n1_s11', 'Petang di halaman rumah ukiran. Ukiran kayu berkilat di rumah tua yang harum dengan bunga. Kau, Tok Penglipur Lara, melangkah masuk ke Kelantan sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 11, 201, 'negeri_kelantan.png'),
('e2_n1_s12', 'Senja di tebing sungai. Air sungai berwarna teh mengalir lambat di bawah tebing. Kau, Tok Penglipur Lara, melangkah masuk ke Sarawak sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 12, 201, 'negeri_sarawak.png'),
('e2_n1_s13', 'Tengah hari di tepi teluk. Angin teluk berhembus sambil gong kecil berdenting jauh. Kau, Tok Penglipur Lara, melangkah masuk ke Sabah sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 13, 201, 'negeri_sabah.png'),
('e2_n1_s14', 'Malam di ibu kota. Lampu bandar menyala dan bunyi trafik bersahut-sahutan. Kau, Tok Penglipur Lara, melangkah masuk ke Wilayah Persekutuan sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 14, 201, 'wilayah_persekutuan.png'),
('e2_n1_s2', 'Senja di tengah sawah padi. Hamparan sawah padi berkilau di bawah langit senja. Kau, Tok Penglipur Lara, melangkah masuk ke Kedah sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 2, 201, 'negeri_kedah.png'),
('e2_n1_s3', 'Senja di jeti. Bau garam dan angin laut singgah di jeti yang sibuk. Kau, Tok Penglipur Lara, melangkah masuk ke Pulau Pinang sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 3, 201, 'negeri_pulau_pinang.png'),
('e2_n1_s4', 'Petang di halaman rumah beraja. Cahaya petang menyuluh halaman yang bersih disapu. Kau, Tok Penglipur Lara, melangkah masuk ke Perak sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 4, 201, 'negeri_perak.png'),
('e2_n1_s5', 'Pagi di tepi sungai. Air sungai mengalir tenang dan burung berkicau di tebing. Kau, Tok Penglipur Lara, melangkah masuk ke Selangor sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 5, 201, 'negeri_selangor.png'),
('e2_n1_s6', 'Petang di halaman rumah bergonjong. Bumbung bergonjong rumah adat tegak di hujung halaman. Kau, Tok Penglipur Lara, melangkah masuk ke Negeri Sembilan sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 6, 201, 'negeri_sembilan.png'),
('e2_n1_s7', 'Pagi di tepi sungai Melaka. Bunyi sungai dan bayangan kubu lama menyambut pagi. Kau, Tok Penglipur Lara, melangkah masuk ke Melaka sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 7, 201, 'negeri_melaka.png'),
('e2_n1_s8', 'Petang di tepi sungai. Angin petang menyapu permukaan sungai yang berkilat. Kau, Tok Penglipur Lara, melangkah masuk ke Johor sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 8, 201, 'negeri_johor.png'),
('e2_n1_s9', 'Pagi di tepi sungai. Kabus nipis naik dari sungai dan hutan di seberang. Kau, Tok Penglipur Lara, melangkah masuk ke Pahang sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 9, 201, 'negeri_pahang.png'),
('e2_n2_s1', 'Petang di tepi sungai. Angin petang menyapu permukaan sungai yang berkilat. Kau, seorang Sultan, bertamu ke Johor. Ketua negeri menyambut dengan hormat, tetapi di matanya ada teka-teki untuk kau.', 1, 202, 'negeri_johor.png'),
('e2_n2_s10', 'Pagi di tepi sungai Melaka. Bunyi sungai dan bayangan kubu lama menyambut pagi. Kau, seorang Sultan, bertamu ke Melaka. Ketua negeri menyambut dengan hormat, tetapi di matanya ada teka-teki untuk kau.', 10, 202, 'negeri_melaka.png'),
('e2_n2_s11', 'Senja di jeti. Bau garam dan angin laut singgah di jeti yang sibuk. Kau, seorang Sultan, bertamu ke Pulau Pinang. Ketua negeri menyambut dengan hormat, tetapi di matanya ada teka-teki untuk kau.', 11, 202, 'negeri_pulau_pinang.png'),
('e2_n2_s12', 'Tengah hari di tepi teluk. Angin teluk berhembus sambil gong kecil berdenting jauh. Kau, seorang Sultan, bertamu ke Sabah. Ketua negeri menyambut dengan hormat, tetapi di matanya ada teka-teki untuk kau.', 12, 202, 'negeri_sabah.png'),
