-- SejarahWira  |  sejarahwira_db_full.sql  (SET SEMULA PENUH)
-- Memadam dan mencipta semula SEMUA jadual, kemudian memasukkan data daripada dump anda.
-- Selamat dijalankan berulang kali. TETAPI kemajuan pelajar, akaun yang didaftar kemudian,
-- lencana/artifak pelajar dan log perubahan akan HILANG (kembali kepada keadaan dump).
-- Untuk mengemas kini kandungan sahaja, guna sejarahwira_db_content.sql.
-- ====================================================================
CREATE DATABASE IF NOT EXISTS `sejarahwira_db` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `sejarahwira_db`;
SET NAMES utf8mb4;
SET @OLD_FK = @@FOREIGN_KEY_CHECKS, @OLD_SQL_MODE = @@SQL_MODE;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = '+00:00';

