-- ---------- Artifact ----------
CREATE TABLE `Artifact` (
  `artifactID` bigint(20) NOT NULL,
  `artifactName` varchar(50) NOT NULL,
  `moralLesson` text NOT NULL,
  `asset` varchar(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
ALTER TABLE `Artifact`
  ADD PRIMARY KEY (`artifactID`);
ALTER TABLE `Artifact`
  MODIFY `artifactID` bigint(20) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=11;

-- ---------- Assessment ----------
CREATE TABLE `Assessment` (
  `assessmentID` bigint(20) NOT NULL,
  `eraID` bigint(20) NOT NULL,
  `assessmentType` enum('Formative','Summative') NOT NULL,
  `requiredScore` int(11) NOT NULL DEFAULT 80,
  `formativeConfig` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`formativeConfig`)),
  `summativeConfig` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`summativeConfig`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
ALTER TABLE `Assessment`
  ADD PRIMARY KEY (`assessmentID`),
  ADD KEY `eraID` (`eraID`);
ALTER TABLE `Assessment`
  MODIFY `assessmentID` bigint(20) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=21;

-- ---------- AssessmentAttempt ----------
CREATE TABLE `AssessmentAttempt` (
  `attemptID` bigint(20) NOT NULL,
